    public function profile(Request $request, $id='')
    {
        $patient = Patient::find($id);
        $org_id = auth()->user()->org_id;

        if($patient) {
            $doctors = HospitalDoctor::join('doctor_db','doctor_db.id','=','org_doc_index.doc_id')->select('doctor_db.*')->where('org_doc_index.org_id',$org_id)->where('org_doc_index.active',1)->where('org_doc_index.org_perm',1)->where('org_doc_index.doc_perm',1)->orderBy('name','ASC')->get();
            $vitals = Vitals::join('visitlog','visitlog.id','=','vitals.visit_id')->where('visitlog.patient_id',$id)->whereNotNull('vitals.bp')->orderBy('vitals.id','DESC')->select(['vitals.*'])->first();
            $payments['OPD'] = PatientBilling::join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                ->leftJoin(
                                    DB::raw('(SELECT bill_id, SUM(amount) AS total_payment FROM billing_payment_type WHERE transaction_type = 0 GROUP BY bill_id) as billing_totals'),
                                    'billing_totals.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->leftJoin(
                                    DB::raw('(SELECT bill_id, SUM(charges * qty - discount) AS subtotal FROM patient_gen_bill GROUP BY bill_id) as gen_totals'),
                                    'gen_totals.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->selectRaw('
                                    SUM(IFNULL(billing_totals.total_payment, 0)) as total_payment,
                                    SUM(IFNULL(gen_totals.subtotal, 0) - patient_billing.discount) as total
                                ')
                                ->where('visitlog.patient_id', $id)
                                ->whereIn('visitlog.visit_status', [0])
                                ->first()->toArray();
            $payments['IPD'] = PatientBilling::join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                ->leftJoin(
                                    DB::raw('(SELECT bill_id, SUM(amount) AS total_payment FROM billing_payment_type WHERE transaction_type = 0 GROUP BY bill_id) as billing_totals'),
                                    'billing_totals.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->leftJoin(
                                    DB::raw('(SELECT bill_id, SUM(charges * qty - discount) AS subtotal FROM patient_gen_bill GROUP BY bill_id) as gen_totals'),
                                    'gen_totals.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->selectRaw('
                                    SUM(IFNULL(billing_totals.total_payment, 0)) as total_payment,
                                    SUM(IFNULL(gen_totals.subtotal, 0) - patient_billing.discount) as total
                                ')
                                ->where('visitlog.patient_id', $id)
                                ->whereIn('visitlog.visit_status', [1,2])
                                ->first()->toArray();

                                // dd($payments);
            $visitingDoctors = Visitlog::join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                ->join('doctor_specialities', 'doctor_specialities.id', '=', 'doctor_db.key_spec')
                                ->where('visitlog.patient_id', $id)
                                ->groupBy('visitlog.doctor_id')
                                ->orderByRaw('MAX(visitlog.created_at) DESC')
                                ->select([
                                    'doctor_db.*',
                                    'doctor_specialities.name as specname',
                                    DB::raw('MAX(visitlog.created_at) as last_visit')
                                ])
                                ->get();

            $visits = Visitlog::leftjoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->leftJoin('pi', 'pi.id', '=', 'visitlog.patient_id')
                            ->leftJoin('patient_billing', function ($join) {
                                $join->on('patient_billing.visit_id', '=', 'visitlog.id');
                                $join->on('visitlog.patient_id', '=', 'pi.id');
                            })
                            ->leftJoin('vitals', 'vitals.visit_id', '=', 'visitlog.id')
                            ->select('visitlog.*',
                                'visitlog.created_at as created',
                                'visitlog.doctor_id as did',
                                'visitlog.id as vid',
                                'visitlog.patient_id as pid',
                                'doctor_db.name',
                                'pi.prefix',
                                'pi.id as uhid',
                                'pi.Fname',
                                'pi.Lname',
                                'pi.age',
                                'pi.sex',
                                'pi.dob',
                                'pi.mobile_no',
                                'pi.Address',
                                'pi.mnvs',
                                'patient_billing.id as bill_id',
                                'patient_billing.status as bill_status',
                                'vitals.temprature as t',
                                'vitals.weight as w',
                                'vitals.height as h',
                            )
                            // ->distinct() // Ensure no duplicate rows
                            ->where('visitlog.hospital_id', $org_id)
                            ->where('visit_status', 0)
                            ->where('visitlog.patient_id', $id)
                            ->when($from_date = $request->visit_filter_from_date, function ($query, $from_date) {
                                $query->whereDate('visitlog.created_at', '>=', $from_date);
                            })
                            ->when($to_date = $request->visit_filter_to_date, function ($query, $to_date) {
                                $query->whereDate('visitlog.created_at', '<=', $to_date);
                            })
                            ->when($doctor = $request->visit_filter_doctor, function ($query, $doctor) {
                                $query->where('visitlog.doctor_id', $doctor);
                            })
                            ->orderBy('visitlog.id', 'DESC')
                            ->groupBy('visitlog.id')
                            ->latest('created_at')->paginate(10)->withQueryString();

            $bills = PatientBilling::join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                            ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
                            ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->leftJoin('users', 'users.id', '=', 'patient_billing.created_by')
                            ->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover')
                            ->leftJoin(
                                DB::raw('(
                                    SELECT
                                        bill_id,
                                        SUM(
                                            CASE
                                                WHEN transaction_type = 0 THEN amount
                                                WHEN transaction_type = 1 THEN -amount
                                                ELSE 0
                                            END
                                        ) AS total_payment
                                    FROM billing_payment_type
                                    GROUP BY bill_id
                                ) as billing_totals'),
                                // DB::raw('(SELECT bill_id, SUM(amount) AS total_payment FROM billing_payment_type GROUP BY bill_id) as billing_totals'),
                                'billing_totals.bill_id',
                                '=',
                                'patient_billing.id'
                            )
                            // ->leftJoin(
                            //     DB::raw('(SELECT bill_id, SUM(charges*qty-discount) AS subtotal FROM patient_gen_bill WHERE GROUP BY bill_id) as gen_totals'),
                            //     'gen_totals.bill_id',
                            //     '=',
                            //     'patient_billing.id'
                            // )
                            ->leftJoin(
                                DB::raw('(
                                    SELECT
                                        bill_id,
                                        SUM(
                                            (charges * qty - discount)
                                            + IFNULL(JSON_UNQUOTE(JSON_EXTRACT(additional_info, "$.cgst")), 0)
                                            + IFNULL(JSON_UNQUOTE(JSON_EXTRACT(additional_info, "$.sgst")), 0)
                                        ) AS subtotal
                                    FROM patient_gen_bill
                                    WHERE is_deleted = 0
                                    AND (is_cancelled IS NULL OR is_cancelled = 0)
                                    GROUP BY bill_id
                                ) as gen_totals'),
                                'gen_totals.bill_id',
                                '=',
                                'patient_billing.id'
                            )
                            ->leftJoin(
                                DB::raw("(SELECT DISTINCT bill_id FROM refund_remarks WHERE status = 'issued') as refunded_bills"),
                                'refunded_bills.bill_id',
                                '=',
                                'patient_billing.id'
                            )
                            ->select(
                                'pi.Fname', 'pi.Lname', 'pi.prefix', 'pi.sex', 'pi.age', 'pi.dob', 'pi.id as uhid',
                                'doctor_db.name as doctor_name',
                                'health_insurance_agen.insurance_agen',
                                'patient_billing.id as bill_id',
                                'patient_billing.*',
                                'patient_billing.created_at',
                                DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
                                DB::raw('gen_totals.subtotal - patient_billing.discount as total'),
                                'billing_totals.total_payment as total_paid',
                                'gen_totals.subtotal as subtotal',
                                DB::raw('CASE WHEN refunded_bills.bill_id IS NOT NULL THEN 1 ELSE 0 END as is_refunded')
                            );

                        if ($request->bill_filter_from_date) {
                            $bills->whereDate('patient_billing.created_at','>=', $request->bill_filter_from_date);
                        }
                        if($request->bill_filter_to_date) {
                            $bills->whereDate('patient_billing.created_at','<=', $request->bill_filter_to_date);
                        }
                        // Type specific filters
                        if ($request->bill_filter_type === 'cancelled') {
                            $bills->where('patient_billing.is_cancelled', 1);
                        } elseif ($request->bill_filter_type === 'pending') {
                            $bills->whereRaw('(gen_totals.subtotal - patient_billing.discount) - IFNULL(billing_totals.total_payment, 0) > 0');
                        } elseif ($request->bill_filter_type === 'refund') {
                            $bills->whereNotNull('refunded_bills.bill_id');
                        }

                        // Final conditions
                        $bills->where('visitlog.hospital_id', auth()->user()->org_id);
                        $bills->where('visitlog.patient_id', $id);
                        $bills->orderBy('patient_billing.id', 'DESC');

            $bills = $bills->latest('created_at')->paginate(10)->withQueryString();

            $type = $request->attachment_filter_type;

            $scanned = ScannedDoc::select('id','patient_id','path','remarks' ,'tag','created_at',DB::raw("'offline' as scanned"))
                                        ->where('patient_id', $patient->id)
                                        ->when($type, fn($q) => $q->where('tag', $type));

            $online = OnlineDocuments::select('id','patient_id','path','remarks', 'tag','created_at',DB::raw("'online' as scanned"))
                                        ->where('patient_id', $patient->id)
                                        ->when($type, fn($q) => $q->where('tag', $type));

            $attachments = $scanned
                                    ->unionAll($online)
                                    ->orderBy('created_at', 'desc')
                                    ->paginate(12)
                                    ->withQueryString();

          //  return $attachments;

            $investigations = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                                ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                ->join('pi','pi.id','=','visitlog.patient_id')
                                ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                                ->select('patient_gen_bill.*',
                                    'hospital_services.service as service_name',
                                    'hospital_services.group_attributes as group_attributes',
                                    'doctor_db.name as doctor_name',
                                    'pi.id as uhid',
                                    'pi.dob',
                                    'patient_gen_bill.created_at as bill_date',
                                    'patient_gen_bill.id as pGen_bill_id',
                                    'pi.prefix as prefix',
                                    'pi.Fname as patient_first_name',
                                    'pi.Lname as patient_last_name',
                                    'pi.sex as sex',
                                    'pi.mobile_no as phone',
                                    'lab_investigations.id as lab_investigation_id',
                                    'lab_investigations.status as investigation_status',
                                    'lab_investigations.sample_collect_time as sample_collect_time',
                                    'lab_investigations.reporting_time as reporting_time',
                                    'lab_investigations.approval_time as approval_time',
                                    'lab_investigations.approved_by as approved_by',
                                    'lab_investigations.status as status',
                                    'patient_billing.id as pbill_id',
                                    // 'patient_billing.bill_tag as bill_tag',
                                    'patient_billing.status as pbill_status',
                                    )
                                ->when($from_date = $request->investigation_filter_from_date, function ($query, $from_date) {
                                    $query->whereDate('patient_gen_bill.created_at', '>=', $from_date);
                                })
                                ->when($to_date = $request->investigation_filter_to_date, function ($query, $to_date) {
                                    $query->whereDate('patient_gen_bill.created_at', '<=', $to_date);
                                })
                                ->where('visitlog.hospital_id',$org_id)
                                ->where('visitlog.patient_id',$id)
                                ->where('hospital_services.flag',"!=",'refund')
                                ->where('lab_investigations.status','=','approved')
                                ->orderBy('lab_investigations.id','DESC')
                                ->paginate(10)->withQueryString();


            $pharmacy_from_date = $request->pharmacy_from_date;
            $pharmacy_to_date = $request->pharmacy_to_date;
            $pharmacyBills = InventoryBilling::whereHas('createBy', function ($query) {
                                    $query->where('org_id', auth()->user()->org_id);
                                })
                                ->when($bill_id = $request->bill_id, function ($query, $bill_id) {
                                    $query->byFormattedBillNo($bill_id);
                                },
                                function ($query) use ($request,$pharmacy_from_date,$pharmacy_to_date) {
                                    $query->when($pharmacy_from_date, function ($query, $pharmacy_from_date) {
                                        $query->whereDate('created_at', '>=', $pharmacy_from_date);
                                    });
                                    $query->when($pharmacy_to_date, function ($query, $pharmacy_to_date) {
                                        $query->whereDate('created_at', '<=', $pharmacy_to_date);
                                    });
                                    $query->when($invoice_type = $request->invoice_type, function ($query, $invoice_type) {
                                        $query->where('invoice_type', $invoice_type);
                                    });
                                })
                                ->when($bill_type = $request->bill_type??false, function ($q, $bill_type) {
                                    if($bill_type == 'opd'){
                                        $q->whereNull('inventory_billing.ipd_no');
                                    }
                                    if($bill_type == 'ipd'){
                                        $q->whereNotNull('inventory_billing.ipd_no');
                                    }
                                })
                                ->where('patient_id',$id)
                                ->whereIn('bill_type',['sale','return'])
                                ->latest('created_at')
                                ->paginate(10)
                                ->withQueryString();


            if($request->ajax()) {

                if (!$request->has('tab') || $request->tab == 'overview_tab') {
                    // $grouping = $request->grouping?1:0;
                    // return view('admin.hospital.inventory.tables.stock_list_table', compact('inventory','grouping'))->render();
                }
                if($request->tab == 'visit_tab'){
                    return view('admin.patient.table.visit_list_table', compact('visits'))->render();
                }
                if($request->tab == 'bills_tab'){
                    return view('admin.patient.table.bill_list_table', compact('bills'))->render();
                }
                if($request->tab == 'attachments_tab'){
                    return view('admin.patient.table.attachment_list_table', compact('attachments'))->render();
                }
                if($request->tab == 'lab_investigation_tab'){
                    return view('admin.patient.table.investigation_list_table', compact('investigations'))->render();
                }
                if($request->tab == 'pharmacy_tab'){
                    return view('admin.patient.table.pharmacy_list_table', compact('pharmacyBills'))->render();
                }
                return;
            }
            return view('admin.patient.profile',compact('id','patient','visitingDoctors','payments','vitals','doctors','visits','bills','attachments','investigations','pharmacyBills'));
        }
        return view('admin.patient.profile',compact('id','patient'));
    }


    public function previous_visit_details(Request $request){
        $visit_id = $request->visit_id;
        $context = $request->context;

        $patient = visitlog::find($visit_id);
        if (!$patient) {
            return response()->json([
                'status' => false,
                'message' => 'Visit not found.'
            ]);
        }

        $prevVisits = VisitClinicalData::join('visitlog', 'visitlog.id', '=', 'visit_clinical_data.visit_id')
                                ->select('visitlog.id', 'visitlog.created_at')
                                ->where('visitlog.patient_id', $patient->patient_id)
                                ->where('visitlog.doctor_id', $patient->doctor_id)
                                ->where('visitlog.hospital_id', $patient->hospital_id)
                                ->where('visit_clinical_data.context', $context)
                                ->where('visitlog.id', '!=', $visit_id)
                                ->distinct()
                                ->orderBy('visitlog.created_at', 'desc')
                                ->take(100)
                                ->get();

        if ($prevVisits->isEmpty()) {
            return response()->json([
                'status' => false,
                'message' => 'No previous visits found.'
            ]);
        }

        $print = "patient.print_pres_urology";

        $html = view('components.visit_note', compact(
            'prevVisits',
            'context',
            'print'
        ))->render();

        return response()->json([
            'status' => true,
            'html' => $html,
            'count' => $prevVisits->count(),
        ]);
    }

    public function get_health_chart(Request $request)
    {
        $request->validate(['id'=>'required']);
        $patient = Patient::findOrFail($request->id);
        $vitals = Vitals::join('visitlog','visitlog.id','=','vitals.visit_id')->where('visitlog.patient_id',$patient->id)->whereNotNull('vitals.bp')->orderBy('vitals.id','DESC')->select(['vitals.*'])->first();


        return view('admin.patient.partials.health_chart',compact('patient','vitals'))->render();

    }
    public function list()
    {
        $user = Auth::user();
        $org_id = $user->org_id;
        $currentDate = Carbon::now()->toDateString();


        $patient = Patient::whereDate('pi.created_at',$currentDate)
                            ->where('pi.hospital_id',$org_id)
                            ->leftJoin('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                            ->select('pi.*','health_insurance_agen.insurance_agen as insurance')
                            ->orderBy('id','DESC')
                            ->get();

        $sms_status = (SmsSetting::where('status',1)->count())>0 ? 1:0;

        if($sms_status){
            $sms_status = Notifier::is_enabled('registration_otp');
        }



        $data=compact('patient','sms_status');
        return view('admin.patient.list')->with($data);
    }

    public function create_doctor_team(Request $request)
    {

        $team = DoctorTeam::get();
        return view('admin.create_doctors_team',compact('team'))->render();
    }

    public function save_doctor_team(Request $request)
    {

        $team = new DoctorTeam();
        $team->name = $request->name;
        $team->hospital_id = Auth::user()->org_id;
        $team->save();
        return redirect()->back()->with('success', 'Team Created Successfully');
    }


