    public function er_patient_view(Request $request)
    {
        $user = Auth::user();
        $org_id = $user->org_id;

        $visits = Visitlog::leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
            ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
            ->select([
                'visitlog.id as vid',
                'visitlog.patient_id as uhid_val',
                'visitlog.doctor_id as did',
                'visitlog.created_at as created',
                'visitlog.hospital_id',
                'visitlog.visit_status',
                'visitlog.date as admission_date',
                'visitlog.visit_time as admission_time',
                'pi.id as uhid',
                'pi.id as ageUhid',
                'pi.prefix',
                'pi.Fname',
                'pi.Lname',
                'pi.age',
                'pi.dob',
                'pi.sex',
                'doctor_db.name as doctor_name',
            ])
            ->where('visitlog.hospital_id', $org_id)
            ->where('visitlog.emergency', 1)
            ->where('visitlog.er_status', 0)
            ->where('visitlog.is_cancelled', 0)
            ->where('visitlog.visit_status', 0)
            ->orderBy('visitlog.id', 'DESC')
            ->get();

        $visits = $visits->map(function($v) {
            $vitalRecord = Vitals::where('visit_id', $v->vid)
                ->where('context', 'clinical.er_note')
                ->orderBy('created_at', 'desc')
                ->first();

            $vitals = [
                'sbp' => '--',
                'dbp' => '--',
                'pulse' => '--',
                'temp' => '--',
                'saturation' => '--',
                'gcs_total' => '--',
                'gcs_eye' => '--',
                'gcs_verbal' => '--',
                'gcs_motor' => '--',
                'pain_assessment' => '--'
            ];

            if ($vitalRecord) {
                $bpArr = json_decode($vitalRecord->bp, true) ?? [];
                $bp = is_array($bpArr) ? (end($bpArr) ?: []) : [];
                $vitals['sbp'] = !empty($bp['upper_bp']) ? $bp['upper_bp'] : '--';
                $vitals['dbp'] = !empty($bp['lower_bp']) ? $bp['lower_bp'] : '--';

                $pulseArr = json_decode($vitalRecord->pulse, true) ?? [];
                $pulse = is_array($pulseArr) ? (end($pulseArr) ?: []) : [];
                $vitals['pulse'] = !empty($pulse['pulseRate']) ? $pulse['pulseRate'] : '--';

                $vitals['temp'] = !empty($vitalRecord->temprature) ? $vitalRecord->temprature : '--';
                $vitals['saturation'] = !empty($vitalRecord->saturation) ? $vitalRecord->saturation : '--';
                $vitals['gcs_total'] = !empty($vitalRecord->gcs_total) ? $vitalRecord->gcs_total : '--';
                $vitals['gcs_eye'] = !empty($vitalRecord->gcs_eye) ? $vitalRecord->gcs_eye : '--';
                $vitals['gcs_verbal'] = !empty($vitalRecord->gcs_verbal) ? $vitalRecord->gcs_verbal : '--';
                $vitals['gcs_motor'] = !empty($vitalRecord->gcs_motor) ? $vitalRecord->gcs_motor : '--';
                $vitals['pain_assessment'] = !empty($vitalRecord->pain_assessment) ? $vitalRecord->pain_assessment : '--';
            }

            $v->latest_vitals = $vitals;
            $v->last_vital_update_time = ($vitalRecord && $vitalRecord->created_at) ? $vitalRecord->created_at->toDateTimeString() : '';

            $vcd = VisitClinicalData::where('visit_id', $v->vid)
                ->where('context', 'clinical.er_note')
                ->first();

            $triageLevel = '';
            $arrivalTime = '';
            if ($vcd && !empty($vcd->others)) {
                $others = json_decode($vcd->others, true);
                if (isset($others['triage_level']['value'])) {
                    $triageLevel = $others['triage_level']['value'];
                }
                if (isset($others['arrival_date_time']['value'])) {
                    $arrivalTime = $others['arrival_date_time']['value'];
                }
            }
            $v->triage_level = $triageLevel;
            $v->arrival_date_time = !empty($arrivalTime) ? $arrivalTime : $v->created;

            return $v;
        });

        $doctors = HospitalDoctor::join('doctor_db', 'doctor_db.id', '=', 'org_doc_index.doc_id')
            ->select('doctor_db.*')
            ->where('org_doc_index.org_id', $org_id)
            ->where('doctor_db.active', 1)
            ->where('org_doc_index.active', 1)
            ->orderBy('name', 'ASC')
            ->get();

        return view('admin.patient.er_view', compact('visits', 'doctors'));
    }

    public function er_patient_detail($vid)
    {
        $p = Visitlog::leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
            ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
            ->select([
                'visitlog.id as vid',
                'visitlog.patient_id as uhid_val',
                'visitlog.doctor_id as did',
                'visitlog.created_at as created',
                'visitlog.hospital_id',
                'pi.id as uhid',
                'pi.id as ageUhid',
                'pi.prefix',
                'pi.Fname',
                'pi.Lname',
                'pi.age',
                'pi.dob',
                'pi.sex',
                'doctor_db.name as doctor_name',
            ])
            ->where('visitlog.id', $vid)
            ->first();

        if (!$p) {
            return '<div class="alert alert-danger">ER Visit not found.</div>';
        }

        // Fetch latest vitals
        $vitalRecord = Vitals::where('visit_id', $p->vid)
            ->where('context', 'clinical.er_note')
            ->orderBy('created_at', 'desc')
            ->first();

        $vitals = [
            'sbp' => '--',
            'dbp' => '--',
            'pulse' => '--',
            'temp' => '--',
            'saturation' => '--',
            'gcs_total' => '--',
            'gcs_eye' => '--',
            'gcs_verbal' => '--',
            'gcs_motor' => '--',
            'pain_assessment' => '--'
        ];

        if ($vitalRecord) {
            $bpArr = json_decode($vitalRecord->bp, true) ?? [];
            $bp = is_array($bpArr) ? (end($bpArr) ?: []) : [];
            $vitals['sbp'] = !empty($bp['upper_bp']) ? $bp['upper_bp'] : '--';
            $vitals['dbp'] = !empty($bp['lower_bp']) ? $bp['lower_bp'] : '--';

            $pulseArr = json_decode($vitalRecord->pulse, true) ?? [];
            $pulse = is_array($pulseArr) ? (end($pulseArr) ?: []) : [];
            $vitals['pulse'] = !empty($pulse['pulseRate']) ? $pulse['pulseRate'] : '--';

            $vitals['temp'] = !empty($vitalRecord->temprature) ? $vitalRecord->temprature : '--';
            $vitals['saturation'] = !empty($vitalRecord->saturation) ? $vitalRecord->saturation : '--';
            $vitals['gcs_total'] = !empty($vitalRecord->gcs_total) ? $vitalRecord->gcs_total : '--';
            $vitals['gcs_eye'] = !empty($vitalRecord->gcs_eye) ? $vitalRecord->gcs_eye : '--';
            $vitals['gcs_verbal'] = !empty($vitalRecord->gcs_verbal) ? $vitalRecord->gcs_verbal : '--';
            $vitals['gcs_motor'] = !empty($vitalRecord->gcs_motor) ? $vitalRecord->gcs_motor : '--';
            $vitals['pain_assessment'] = !empty($vitalRecord->pain_assessment) ? $vitalRecord->pain_assessment : '--';
        }

        $p->latest_vitals = $vitals;
        $p->last_vital_update_time = ($vitalRecord && $vitalRecord->created_at) ? $vitalRecord->created_at->toDateTimeString() : '';

        // Fetch clinical data (triage, complaints, HOPI, course, etc.)
        $vcd = VisitClinicalData::where('visit_id', $p->vid)
            ->where('context', 'clinical.er_note')
            ->first();

        $clinicalData = [];
        $triageLevel = '';
        $arrivalTime = '';
        $diagnosis = [];
        if ($vcd) {
            $diagnosis = json_decode($vcd->diagnosis, true) ?? [];
            if (!empty($vcd->others)) {
                $clinicalData = json_decode($vcd->others, true) ?? [];
                if (isset($clinicalData['triage_level']['value'])) {
                    $triageLevel = $clinicalData['triage_level']['value'];
                }
                if (isset($clinicalData['arrival_date_time']['value'])) {
                    $arrivalTime = $clinicalData['arrival_date_time']['value'];
                }
            }
        }

        $p->triage_level = $triageLevel;
        $p->arrival_date_time = !empty($arrivalTime) ? $arrivalTime : $p->created;

        $vitalsList = Vitals::where('visit_id', $p->vid)
            ->where('context', 'clinical.er_note')
            ->orderBy('created_at', 'asc')
            ->get();

        $medicines = $this->get_medicine_list($p->vid) ?? collect();
        $pres_manual = PresManual::where('visit_table_id', $p->vid)->get() ?? collect();
        $pres_manual = $pres_manual->map(function ($item) {
            $item->name = $item->brand_id;
            return $item;
        });
        $mergedMedicines = $medicines->merge($pres_manual)->sortBy('d_order')->values();

        return view('admin.patient.er_detail_partial', compact('p', 'clinicalData', 'vitalsList', 'diagnosis', 'mergedMedicines'))->render();
    }

