    public function registration(Request $request)
    {
        $org_id = auth()->user()->org_id;

        $user = Auth::user();
        $org_id = $user->org_id;

        $insu = HospitalInsurance::join('health_insurance_agen','health_insurance_agen.id','=','hospital_insurance.insurance')->where('hospital_insurance.hospital_id',$org_id)->where('hospital_insurance.active',1)->select('health_insurance_agen.*')->orderBy('insurance_agen','ASC')->get();

        $specialization = DoctorSpec::where('active',1)->orderBy('name','ASC')->get();
        $doctor = HospitalDoctor::join('doctor_db','doctor_db.id','=','org_doc_index.doc_id')->select('doctor_db.*')->where('org_doc_index.org_id',$org_id)->where('org_doc_index.active',1)->where('org_doc_index.org_perm',1)->where('org_doc_index.doc_perm',1)->orderBy('name','ASC')->get();

        $charges = DocCharge::get();

        $ref_users = RefUsers::where('hospital_id', $org_id)->orderBy('name', 'ASC')->get();



        $visit = Visitlog::leftjoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->leftJoin('pi', 'pi.id', '=', 'visitlog.patient_id')
                            ->leftJoin('patient_billing', function ($join) {
                                $join->on('patient_billing.visit_id', '=', 'visitlog.id');
                                $join->on('visitlog.patient_id', '=', 'pi.id');
                            })
                            ->leftJoin('vitals', 'vitals.visit_id', '=', 'visitlog.id')
                            ->select('visitlog.*',
                                'visitlog.created_at as created',
                                'visitlog.doctor_id as did',
                                'visitlog.id as vid',
                                'visitlog.patient_id as pid',
                                'doctor_db.name',
                                'pi.prefix',
                                'pi.Fname',
                                'pi.Lname',
                                'pi.age',
                                'pi.sex',
                                'pi.dob',
                                'pi.mobile_no',
                                'pi.Address',
                                'pi.mnvs',
                                'patient_billing.id as bill_id',
                                'patient_billing.status as bill_status',
                                'vitals.temprature as t',
                                'vitals.weight as w',
                                'vitals.height as h',
                            )
                            // ->distinct() // Ensure no duplicate rows
                            ->where('visitlog.hospital_id', $org_id)
                            ->where('visit_status', 0)
                            ->whereDate('visitlog.date', date('Y-m-d'));
        $visit->orderBy('visitlog.id', 'DESC');
        $visit->groupBy('visitlog.id');
        $visits = $visit->get();

        $doctorVisitCounts = [];
        // Loop through visits and assign serial numbers
        foreach ($visits as $visi) {
            $doctorId = $visi->did;

            // Initialize the count if not already set
            if (!isset($doctorVisitCounts[$doctorId])) {
                $doctorVisitCounts[$doctorId] = 0;
            }

            // Increment the count
            $doctorVisitCounts[$doctorId]++;

            // Assign the serial number
            $visi->sr_no = $doctorVisitCounts[$doctorId];
        }

        $data = compact('insu','doctor','charges','specialization','ref_users','visits');

        return view('admin.patient.registration.registration_page')->with($data);
    }

    public function get_services_items(Request $request)
    {
        $org_id = auth()->user()->org_id;

        $search = $request->input('query');
        $page = $request->input('page', 1);

        // Fetch data based on the query
        $service = HospitalService::leftJoin('hospital_services','hospital_services.id','=','hospital_services_index.service')
                    ->leftJoin('hospital_service_charges','hospital_service_charges.service','=','hospital_services_index.service')
                    ->where('hospital_services_index.hospital_id',$org_id)
                    ->where('hospital_services_index.active',1)
                    ->where(DB::raw('CONCAT(hospital_services.short_code, " ", hospital_services.service)'), 'like', "%{$search}%")
                    // ->where('hospital_service_charges.insurance',$visit->i_cover)
                    ->where('hospital_service_charges.hospital_id',$org_id)
                    ->select(
                        DB::raw('CONCAT(hospital_services.service," (",hospital_services.short_code, ")") as name'),
                        'hospital_services.service as service',
                                'hospital_services.spec_id',
                                'hospital_services.id',
                                'hospital_services.short_code'
                                )
                    ->groupBy('hospital_service_charges.service')
                    ->paginate(10, ['*'], 'page', $page);

        return response()->json([
            'items' => $service->items(), // Paginated results
            'pagination' => [
                'has_more' => $service->hasMorePages(), // Boolean for more results
            ]
        ]);
    }

    public function checkmobile(Request $request)
    {
        $org_id = auth()->user()->org_id;

        $mobileNumber = $request->input('mobile_no');

        // Check if the mobile number exists in the database
        $exists = Patient::where('mobile_no', $mobileNumber)->where('hospital_id', $org_id)->exists();

        // Return a JSON response indicating whether the mobile number exists
        return response()->json(['exists' => $exists]);
    }

    public function getName(Request $request)
    {
    $mobileNumber = $request->input('mobile_no');



  $patients = Patient::join('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                    ->select('health_insurance_agen.insurance_agen','pi.*')
                    ->where('mobile_no', $mobileNumber)
                    ->where('hospital_id', auth()->user()->org_id)
                    ->get();

    if ($patients->isNotEmpty()) {
    // Convert collection of patients to array of arrays
    $patientDataArray = [];
    foreach ($patients as $patient) {
        $patientDataArray[] = [
            'uhid' =>$patient->id,
            'first_name' => $patient->Fname,
            'last_name' => $patient->Lname,
            'age' => $patient->age,
            'sex' => $patient->sex,
            'dob' => $patient->dob,
            'email' =>$patient->email_id,
            'mobile' => $patient->mobile_no,
            'i_cover' => $patient->insurance_agen,
            'Fathername' =>$patient->Fathername,
            'spousename' => $patient->spousename,
            'guardian_name' => $patient->guardian_name,
            'date' => $patient->date,
            'created_at' => date('d-m-Y', strtotime($patient->created_at)),
            'org_id' => $patient->hospital_id
        ];
    }
    // Return patient information as JSON response
    return response()->json($patientDataArray);
} else {
    // If patients with the given mobile number are not found, return an empty response
    return response()->json([]);
}
    }


    public function save(Request $req)
    {
        $validate = Validator::make($req->all(), [
            'prefix' => 'required',
            'Fname' => 'required',
            'email' => 'nullable|email',
            'i_cover' => 'required',
            'gender' => 'required',
            'age' => 'required',
            'mobile_no' => 'required|digits:10',
        ], [
            'Fname.required' => 'First name is required field',
            'i_cover.required' => 'Insurance is required field'
        ]);

        if ($validate->fails()) {
            return response()->json([
                'status' => 'error',
                'success' => false,
                'message' => $validate->errors()->first(),
                'errors' => $validate->errors()
            ], 422);
        }

        $currentDate = Carbon::now()->toDateString();
        $currentTime = Carbon::now()->toTimeString();

        $user = Auth::user();
        $org_id = $user->org_id;

        // Check if existing patient
        $patient = null;
        $isUpdate = false;
        if ($req->filled('patient_id')) {
            $patient = Patient::where('hospital_id', $org_id)->where('id', $req->patient_id)->first();
        } elseif ($req->filled('id')) {
            $patient = Patient::where('hospital_id', $org_id)->where('id', $req->id)->first();
        } elseif ($req->filled('uhid')) {
            $rawUhid = preg_replace('/[^0-9]/', '', (string) $req->uhid);
            if ($rawUhid) {
                $patient = Patient::where('hospital_id', $org_id)
                    ->where('id', $rawUhid)
                    ->first();
            }
        }

        if ($patient) {
            $isUpdate = true;
            if (!auth()->user()->can('module-permission', ['patient', 'can_update'])) {
                return response()->json([
                    'status' => 'error',
                    'success' => false,
                    'message' => 'You do not have permission to update patient details.'
                ], 403);
            }
        } else {
            if (!auth()->user()->can('module-permission', ['patient', 'can_create'])) {
                return response()->json([
                    'status' => 'error',
                    'success' => false,
                    'message' => 'You do not have permission to register a new patient.'
                ], 403);
            }
        }

        $fee = HospitalRegistrationFee::where('hospital_id', $org_id)->first();
        if (!$fee) {
            try {
                $fee = HospitalRegistrationFee::create([
                    'hospital_id' => $org_id,
                    'registration_fee' => 0,
                ]);
            } catch (\Throwable $ex) {
                $fee = HospitalRegistrationFee::where('hospital_id', $org_id)->first();
            }
        }

        $calculateAge = (int) $req->age;
        if (!empty($req->dob)) {
            $assumeDob = date("Y-m-d", strtotime($req->dob));
        } else {
            $assumeDob = Carbon::now()->subYears($calculateAge)->toDateString();
        }

        DB::beginTransaction();
        try {
            if (!$isUpdate) {
                // Lock hospital row to prevent concurrent UHID generation
                $hospital = Healtcare_org::where('id', $org_id)
                    ->lockForUpdate()
                    ->firstOrFail();

                // Hospital-wise UHID
                $lastUhid = Patient::where('hospital_id', $org_id)
                    ->max('uhid');

                $patient = new Patient;
                $patient->uhid = ($lastUhid ?? 0) + 1;
                $patient->uhid_prefix = Carbon::now()->year;
                $patient->hospital_id = $org_id;
                $patient->created_by = auth()->user()->id;
                $patient->date = $currentDate;
                $patient->time = $currentTime;
                $patient->first_reg_charge = $fee ? $fee->registration_fee : 0;
            }

            $patient->mr_no = $patient->mr_no ?? "";
            $iCover = $req->i_cover;
            if (!is_numeric($iCover) || (int)$iCover <= 0) {
                $cashId = \Illuminate\Support\Facades\DB::table('health_insurance_agen')
                    ->where('is_cash', 1)
                    ->value('id');
                $iCover = $cashId ?: 0;
            }
            $patient->i_cover = (int)$iCover;
            $patient->email_id = $req->email_id ?? $patient->email_id ?? "";
            $patient->prefix = $req->prefix;
            $patient->Fname = $req->Fname;
            $patient->Lname = $req->Lname ?? '';
           
            $patient->age = $req->age;
            $patient->sex = $req->gender;
            $patient->vpo = $patient->vpo ?? "";
            $patient->houseno = $patient->houseno ?? 0;
            $patient->street = $patient->street ?? "";
            $patient->city = $req->city ?? $patient->city ?? "";
            $patient->state = $req->state ?? $patient->state ?? "";
            $patient->login_id = $patient->login_id ?? "";
            $patient->mobile_no = $req->mobile_no;
            $patient->district = $req->district ?? $patient->district ?? "";
            $patient->Fathername = $req->Fathername ?? $patient->Fathername ?? "";
            $patient->spousename = $req->spousename ?? $patient->spousename ?? "";
            $patient->guardian_name = $req->guardian_name ?? $patient->guardian_name ?? "";
            $refDocName = $req->referring_doctor;
            if (empty($refDocName) && $req->filled('ref_by')) {
                $refDocName = RefUsers::where('id', $req->ref_by)->value('name');
            }
            $patient->referring_doctor = $refDocName ?? $patient->referring_doctor ?? "";
            $patient->pin = !empty($req->pin) ? (int)$req->pin : ($patient->pin ?? 0);
            $patient->p_lang = $req->p_lang ?? $patient->p_lang ?? 0;
            $patient->email_id1 = $patient->email_id1 ?? "";
            $patient->email_id2 = $patient->email_id2 ?? "";
            $patient->Mothername = $patient->Mothername ?? "";
            $patient->dump = $patient->dump ?? 0;
            $patient->passcode = $patient->passcode ?? "";
            $patient->user_p_level = $patient->user_p_level ?? 0;
            $patient->doctor_id = $patient->doctor_id ?? 0;
            $patient->org_name = $patient->org_name ?? "";
            $patient->opr_name = $patient->opr_name ?? "";
            $patient->opr_id = $patient->opr_id ?? 0;
            $patient->mars_passcode = $patient->mars_passcode ?? "";
            $patient->ipd_no = $patient->ipd_no ?? 0;
            $patient->admission_status = $patient->admission_status ?? 0;
            $patient->m_count = $patient->m_count ?? 0;

            if ($req->dob) {
                $patient->dob = date("Y-m-d", strtotime($req->dob));
                $patient->is_dob_calc = 0;
            } else {
                $patient->dob = $assumeDob;
                $patient->is_dob_calc = 1;
            }

            $patient->Address = $req->Address ?? $patient->Address ?? "";
            $patient->lead_gen = $req->lead_gen ?? $patient->lead_gen ?? "";

            if ($req->boolean('whatsapp_checkbox', false)) {
                $patient->whats_app_no = $req->mobile_no;
            } elseif ($req->filled('whats_app_no')) {
                $patient->whats_app_no = $req->whats_app_no;
            } else {
                $patient->whats_app_no = $patient->whats_app_no ?? $req->mobile_no;
            }

            $patient->global_euid = $patient->global_euid ?? 0;
            $patient->abha_mobile = $req->abha_mobile ?? $patient->abha_mobile ?? "";
            $patient->abha_number = $req->abha_number ?? $patient->abha_number ?? "";

            $inputAbhaAddress = $req->filled('abha_address') ? trim($req->abha_address) : ($req->filled('abha_add') ? trim($req->abha_add) : null);
            if (!empty($inputAbhaAddress)) {
                $normalizedAbha = ABDMCloudRelay::normalizeAbhaAddress($inputAbhaAddress);
                $patient->abha_address = $normalizedAbha;
                $patient->abha_add     = $normalizedAbha;
            } else {
                $patient->abha_add     = $patient->abha_add ?? "";
            }

            if ($req->filled('abha_number')) {
                $patient->abha_number = trim($req->abha_number);
            }

            // V2 Registration Fields (columns in pi table)
            $patient->policy_no = $req->policy_no ?? $patient->policy_no ?? "";
            $patient->emergency_contact_name = $req->emergency_contact_name ?? $patient->emergency_contact_name ?? "";
            $patient->emergency_contact_relation = $req->emergency_contact_relation ?? $patient->emergency_contact_relation ?? "";
            $patient->emergency_contact_phone = $req->emergency_contact_phone ?? $patient->emergency_contact_phone ?? "";
            $patient->blood_group = $req->blood_group ?? $patient->blood_group ?? "";
            $patient->payer_name = $req->payer_name ?? $patient->payer_name ?? "";
            $patient->marital_status = $req->marital_status ?? $patient->marital_status ?? "";
            $patient->occupation = $req->occupation ?? $patient->occupation ?? "";
            $patient->id_type = $req->id_type ?? $patient->id_type ?? "";
            $patient->id_no = $req->id_no ?? $patient->id_no ?? "";

            $isVerified = $req->boolean('mobile_verified', false)
                || \Illuminate\Support\Facades\Cache::get('patient_reg_otp_verified_' . $patient->mobile_no)
                || session('patient_reg_otp_verified_' . $patient->mobile_no);

            if ($isVerified) {
                $patient->mnvs = 1;
                $patient->mnvs_otp = 0;
                $patient->mnvs_otp_expiry = null;
            } elseif (!$isUpdate) {
                $otp = random_int(1000, 9999);
                $patient->mnvs_otp = $otp;
                $patient->mnvs_otp_expiry = Carbon::now()->addMinutes(10);
            }

            $isWaSame = $req->boolean('whatsapp_checkbox', false) || $req->boolean('waSame', false);
            $waNum = $patient->whats_app_no;
            $isWaVerified = $req->boolean('whatsapp_verify', false)
                || $req->boolean('whatsapp_verified', false)
                || ($waNum && \Illuminate\Support\Facades\Cache::get('patient_reg_otp_verified_' . $waNum))
                || ($waNum && session('patient_reg_otp_verified_' . $waNum))
                || ($isWaSame && (int)$patient->mnvs === 1);

            $patient->whatsapp_verify = $isWaVerified ? 1 : 0;

            $patient->save();

            if (empty($patient->uhid) || $patient->uhid != $patient->id) {
                $patient->uhid = $patient->id;
                $patient->save();
            }

            if (!empty($inputAbhaAddress)) {
                ABDMCloudRelay::recordPatientAbhaAddress($patient, $inputAbhaAddress, true, 'patient_profile');
            }

            $uhidNumber = (int) $patient->id;

            DB::commit();
        } catch (\Throwable $e) {
            DB::rollBack();
            throw $e;
        }

        if (!empty($patient->abha_address) || !empty($patient->abha_number) || !empty($patient->abha_add)) {
            \App\Jobs\ABDM\GenerateAbdmLinkTokenJob::dispatch((int)$patient->id, (int)($org_id ?? 1))
                ->onQueue('abdm-notifications')
                ->delay(now()->addSecond());
        }

        $otpSend = null;
        if (!$isUpdate) {
            $hospital = Healtcare_org::find($org_id);

            if (!$isVerified && !empty($otp)) {
                $otpSend = Notifier::registration_otp([
                    'patient_id' => $patient->id,
                    'phone_number' => $patient->mobile_no,
                    'params' => [
                        'otp' => $otp,
                        'patient_name' => $patient->prefix . ' ' . $patient->Fname . ' ' . $patient->Lname
                    ]
                ]);

                if (env('SELF_SMS_SERVICE', false)) {
                    $this->send_otp_through_self_sms($patient->id);
                }
            }

            $hospitalContact = '';
            if (\App\Helpers\HospitalHelper::isSettingEnabled(auth()->user()->org_id, 'clinic_number_to_whatsapp')) {
                $hospitalContact = $hospital->contact_no ?? '';
            }

            Notifier::registration_complete([
                'patient_id' => $patient->id,
                'phone_number' => $patient->mobile_no,
                'params' => [
                    'patient_uhid' => $patient->id,
                    'patient_name' => $patient->prefix . ' ' . $patient->Fname . ' ' . $patient->Lname,
                    'hospital_name' => ($hospital->name ?? '') . ($hospitalContact ? ' - Contact : ' . $hospitalContact : ''),
                    'hospital_contact' => $hospital->contact_no ?? '',
                    'link' => $hospital->external_app_link ?: url('book-appointment/select-doctor/' . encryptID($hospital->id)),
                ]
            ]);
        }

        $sms_status = (SmsSetting::where('status', 1)->count()) > 0 ? 1 : 0;
        if ($sms_status) {
            $sms_status = Notifier::is_enabled('registration_otp');
        }

        $data = [
            'success' => 'ok',
            'status' => 1,
            'sms_status' => $sms_status,
            'otp_sent' => $otpSend,
            'message' => $isUpdate ? 'Patient details updated successfully' : 'Registration completed successfully',
            'data' => $patient,
            'patient_id' => $patient->id,
            'patient' => $patient,
            'uhid' => $uhidNumber,
            'visit' => null,
        ];
        return response()->json($data);
    }


    public function send_otp_through_self_sms($pid)
    {
        $fields = array('id'=>$pid);
        $curl = curl_init();
        curl_setopt_array($curl, array
            (
                CURLOPT_URL => url(env('SELF_SMS_SERVICE_LINK',''))."/add_otp_sms.php",
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_ENCODING => "",
                CURLOPT_MAXREDIRS => 10,
                CURLOPT_TIMEOUT => 10,
                CURLOPT_SSL_VERIFYHOST => 0,
                CURLOPT_SSL_VERIFYPEER => 0,
                CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
                CURLOPT_CUSTOMREQUEST => "POST",
                CURLOPT_POSTFIELDS => ($fields),
            )
        );

        $response = curl_exec($curl);
        // dd($response);
        curl_close($curl);
    }

