    public function visit_form($id){

        $user = Auth::user();
        $org_id = $user->org_id;

        $patient = Patient::find($id);

        if(!$patient){
            return response()->json(['status'=>'error','message'=>'No Record Found']);
        }


        $specialization = DoctorSpec::where('active',1)->orderBy('name','ASC')->get();
        $doctor = HospitalDoctor::join('doctor_db','doctor_db.id','=','org_doc_index.doc_id')
                                    ->select('doctor_db.*')
                                    ->where('org_doc_index.org_id',$org_id)
                                    ->where('org_doc_index.active',1)
                                    ->orderBy('name','ASC')
                                    ->get();

        $charges = DocCharge::get();

       $visitlog = Visitlog::where('visitlog.patient_id',$id)
                                ->where('visitlog.hospital_id',$org_id)
                                ->join('doctor_db','doctor_db.id','=','visitlog.doctor_id')
