    public function verify_otp(Request $request){
        $request->validate([
            'otp' => 'required',
        ]);

        $org_id = Auth::user()->org_id;
        $patientId = $request->input('patient_id');
        $mobile = $request->input('mobile_no') ?: ($request->input('mobile') ?: $request->input('phone'));
        $otp = trim($request->input('otp'));

        $patient = null;
        if (!empty($patientId)) {
            $patient = Patient::find($patientId);
        }
        if (!$patient && !empty($mobile)) {
            $patient = Patient::where('hospital_id', $org_id)->where('mobile_no', $mobile)->latest('id')->first();
        }

        if ($patient) {
            $expiry = $patient->mnvs_otp_expiry;

            if (!empty($patient->mnvs_otp) && (string)$patient->mnvs_otp === (string)$otp) {
                if ($patient->mnvs_otp_expiry && $patient->mnvs_otp_expiry < Carbon::now()) {
                    return response()->json(['success' => false, 'message' => 'OTP expired']);
                }

                $patient->mnvs_otp = 0;
                $patient->mnvs_otp_expiry = null;
                if (!empty($patient->whats_app_no) && (string)$patient->whats_app_no === (string)$mobile) {
                    $patient->whatsapp_verify = 1;
                }
                if ((string)$patient->mobile_no === (string)$mobile) {
                    $patient->mnvs = 1;
                }
                $patient->save();

                \Illuminate\Support\Facades\Cache::put('patient_reg_otp_verified_' . $mobile, true, 3600);
                session(['patient_reg_otp_verified_' . $mobile => true]);

                return response()->json(['success' => true, 'message' => 'Mobile Number verified successfully']);
            } else {
                return response()->json(['success' => false, 'message' => 'Invalid OTP']);
            }
        } elseif (!empty($mobile)) {
            $cachedOtp = \Illuminate\Support\Facades\Cache::get('patient_reg_otp_' . $mobile) ?? session('patient_reg_otp_' . $mobile);
            $cachedExpiry = \Illuminate\Support\Facades\Cache::get('patient_reg_otp_expiry_' . $mobile);

            if ($cachedExpiry && Carbon::parse($cachedExpiry) < Carbon::now()) {
                return response()->json(['success' => false, 'message' => 'OTP expired']);
            }

            if (!empty($cachedOtp) && (string)$cachedOtp === (string)$otp) {
                \Illuminate\Support\Facades\Cache::forget('patient_reg_otp_' . $mobile);
                \Illuminate\Support\Facades\Cache::forget('patient_reg_otp_expiry_' . $mobile);
                \Illuminate\Support\Facades\Cache::put('patient_reg_otp_verified_' . $mobile, true, 3600);
                session(['patient_reg_otp_verified_' . $mobile => true]);
                return response()->json(['success' => true, 'message' => 'Mobile Number verified successfully']);
            } else {
                return response()->json(['success' => false, 'message' => 'Invalid OTP']);
            }
        }

        return response()->json(['success' => false, 'message' => 'Patient or mobile number not found']);
    }

    public function resend_otp(Request $request){
        $org_id = Auth::user()->org_id;
        $patientId = $request->input('patient_id');
        $mobile = $request->input('mobile_no') ?: ($request->input('mobile') ?: $request->input('phone'));
        $isForceResend = $request->boolean('resend') || $request->input('is_resend');

        if (empty($patientId) && empty($mobile)) {
            return response()->json(['success' => false, 'message' => 'Patient ID or mobile number is required.'], 422);
        }

        $patient = null;
        if (!empty($patientId)) {
            $patient = Patient::find($patientId);
        }
        if (!$patient && !empty($mobile)) {
            $patient = Patient::where('hospital_id', $org_id)->where('mobile_no', $mobile)->latest('id')->first();
        }

        if ($patient) {
            if (!$isForceResend && !empty($patient->mnvs_otp) && $patient->mnvs_otp_expiry && $patient->mnvs_otp_expiry > Carbon::now()) {
                return response()->json(['success' => true, 'tag' => "verify", 'expiry' => $patient->mnvs_otp_expiry, 'message' => 'Enter OTP to verify phone number']);
            }

            $otp = random_int(1000, 9999);
            $patient->mnvs_otp = $otp;
            $patient->mnvs_otp_expiry = Carbon::now()->addMinutes(10);
            if (env('SELF_SMS_SERVICE', false)) {
                $other = json_decode($patient->others, true);
                $other['is_transfered_to_sms_server'] = 0;
                $patient->others = json_encode($other);
            }
            $patient->save();
            if (env('SELF_SMS_SERVICE', false)) {
                $this->send_otp_through_self_sms($patient->id);
            }
            Notifier::registration_otp([
                'patient_id' => $patient->id,
                'phone_number' => $patient->mobile_no,
                'params' => [
                    'otp' => $otp,
                    'patient_name' => $patient->prefix . ' ' . $patient->Fname . ' ' . $patient->Lname
                ]
            ]);
            return response()->json(['success' => true, 'tag' => "new_otp", 'expiry' => $patient->mnvs_otp_expiry, 'message' => 'OTP sent successfully']);
        } else {
            $cachedExpiry = \Illuminate\Support\Facades\Cache::get('patient_reg_otp_expiry_' . $mobile);
            $cachedOtp = \Illuminate\Support\Facades\Cache::get('patient_reg_otp_' . $mobile);
            if (!$isForceResend && !empty($cachedOtp) && $cachedExpiry && Carbon::parse($cachedExpiry) > Carbon::now()) {
                return response()->json(['success' => true, 'tag' => "verify", 'expiry' => $cachedExpiry, 'message' => 'Enter OTP to verify phone number']);
            }

            $otp = random_int(1000, 9999);
            $expiry = Carbon::now()->addMinutes(10);
            \Illuminate\Support\Facades\Cache::put('patient_reg_otp_' . $mobile, $otp, 600);
            \Illuminate\Support\Facades\Cache::put('patient_reg_otp_expiry_' . $mobile, $expiry->toDateTimeString(), 600);
            session(['patient_reg_otp_' . $mobile => $otp]);

            try {
                Notifier::registration_otp([
                    'patient_id' => 0,
                    'phone_number' => $mobile,
                    'params' => [
                        'otp' => $otp,
                        'patient_name' => 'Patient'
                    ]
                ]);
            } catch (\Exception $e) {
                \Illuminate\Support\Facades\Log::error('OTP send error: ' . $e->getMessage());
            }

            return response()->json(['success' => true, 'tag' => "new_otp", 'expiry' => $expiry->toDateTimeString(), 'message' => 'OTP sent successfully to +91 ' . $mobile]);
        }
    }

