    public function print_opd_slip(Request $req){

        $req->validate([
            'visit_id' => 'required',
            'token_no' => 'required'
        ]);

        $user = Auth::user();
        $org_id = $user->org_id;






        $slipV = HospitalSetting::where('hospital_id',auth()->user()->org_id)
                            ->where('identifier','visit_label')
                            ->first()->current_setting??'v1';

        $id = $req->visit_id;
        $sr_no = $req->token_no;

        $visit =Visitlog::join('users','users.id','=','visitlog.created_by')
                        ->select('visitlog.*','users.first_name','users.last_name')
                        ->where('visitlog.id',$id)->first();

        $patient = Patient::find($visit->patient_id);
        $doctor = Doctor_db::leftJoin('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                                ->leftJoin('org_doc_index','org_doc_index.doc_id','=','doctor_db.id')
                                ->select('doctor_db.*','doctor_specialities.name as department','org_doc_index.opd_validity','doctor_db.qualification')
                                ->where('doctor_db.id',$visit->doctor_id)
                                ->where('org_doc_index.org_id',$org_id)
                                ->first();

        $service_id = HospitalSer::where('flag','consultation_charge')->first()->id;

        $lastPaidVisit = null;

        $hospital_version = HospitalSetting::where('hospital_id',auth()->user()->org_id)
                                    ->where('identifier','hospital_version')
                                    ->first()->current_setting??'v1';

        if($hospital_version == 'v3') {   // v2 for derabassi

            $pgb = PatientBilling::join('patient_gen_bill','patient_gen_bill.bill_id','=','patient_billing.id')
                            ->select('patient_gen_bill.charges','patient_gen_bill.qty','patient_gen_bill.discount')
                            ->where('patient_gen_bill.service_id',$service_id)
                            ->where('patient_billing.visit_id',$id)
                            ->first();
            $charges = $pgb->charges * $pgb->qty - $pgb->discount;

         }else
         if($hospital_version == 'v1') {   // v1 for EROS

            $pgb = PatientBilling::join('patient_gen_bill','patient_gen_bill.bill_id','=','patient_billing.id')
                                    ->select('patient_gen_bill.charges','patient_gen_bill.qty','patient_gen_bill.discount')
                                    ->where('patient_gen_bill.service_id',$service_id)
                                    ->where('patient_billing.visit_id',$id)
                                    ->first();
            $charges = ($pgb) ? $pgb->charges * $pgb->qty - $pgb->discount : 0;

            $charges = (float) $charges;

            if($charges <= 0){

                $lastPaidVisit = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                                        ->join('patient_gen_bill','patient_gen_bill.bill_id','=','patient_billing.id')
                                        ->join('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                        ->select(
                                            'visitlog.id',
                                            'visitlog.created_at',
                                            'patient_gen_bill.charges',
                                            'patient_gen_bill.qty',
                                            'patient_gen_bill.discount'
                                        )
                                        ->where([
                                            ['visitlog.patient_id', $patient->id],
                                            ['visitlog.hospital_id', $org_id],
                                            ['visitlog.doctor_id', $doctor->id],
                                        ])
                                        ->where('visitlog.id', '!=', $id)
                                        ->where('hospital_services.flag', 'consultation_charge')
                                        // ->where('patient_gen_bill.charges', '>', 0) // Γ£à only paid visits
                                        ->orderBy('visitlog.created_at', 'desc')
                                        ->first();


                if($lastPaidVisit){
                    $last_paid_visit_date = $lastPaidVisit->created_at;
                    $last_visit_gap_from_today = Carbon::now()->diffInDays($lastPaidVisit->created_at);
                    // dd($last_visit_gap_from_today);
                }
            }


         }
         else{

             $pgb = PatientBilling::join('patient_gen_bill', 'patient_gen_bill.bill_id', '=', 'patient_billing.id')
                                ->leftJoin('billing_payment_type', 'billing_payment_type.bill_id', '=', 'patient_billing.id')
                                ->select([
                                    'patient_gen_bill.charges',
                                    'patient_gen_bill.qty',
                                    'patient_gen_bill.discount',
                                    DB::raw('IFNULL(SUM(billing_payment_type.amount), 0) as paid_amount'),
                                ])
                                ->where('patient_gen_bill.service_id', $service_id)
                                ->where('patient_billing.visit_id', $id)
                                ->groupBy('patient_billing.id', 'patient_gen_bill.charges', 'patient_gen_bill.qty', 'patient_gen_bill.discount')
                                ->first();

             $created_opd_charges = (float)($visit->ch ?? 0);
             if ($created_opd_charges <= 0 && $pgb) {
                 $created_opd_charges = (float)(($pgb->charges * $pgb->qty) - $pgb->discount);
             }

             if ($created_opd_charges > 0) {
                 $charges = $created_opd_charges;
             } else {
                 $charges = (float)($pgb->paid_amount ?? 0);
             }
        }


        $res = HospitalSetting::select('status')->where('identifier','consultant_charges')->where('hospital_id',$org_id)->first();
        // 0 for automatic && 1 for manual
        $type = ($res->status??true) ? 'manual' :  'automatic';

        $baseCharge = 0;
        if($type == 'automatic'){

            $org_doc = HospitalDoctor::where('org_id', $org_id)->where('doc_id', $visit->doctor_id)->first();
            $opdCharges = $org_doc->opd_charges;
            $auto_charges = json_decode($opdCharges);

            if($auto_charges == null){
                return response()->json(['status'=>'error','message'=>'Charges not found']);
            }

            $baseCharge = (float)$auto_charges->baseCharge;

        }

        $latestVisit = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                                ->join('patient_gen_bill','patient_gen_bill.bill_id','=','patient_billing.id')
                                ->join('billing_payment_type','billing_payment_type.bill_id','patient_billing.id')
                                ->join('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                ->select('visitlog.id',
                                         'visitlog.created_at',
                                         'patient_gen_bill.charges',
                                         'patient_gen_bill.qty',
                                         'patient_gen_bill.discount',
                                          DB::raw('(patient_gen_bill.charges * patient_gen_bill.qty) - IFNULL(patient_gen_bill.discount, 0) as total_charges'),
                                         'patient_billing.id as bill_id'
                                        )
                                ->where([
                                            ['visitlog.patient_id', $patient->id],
                                            ['visitlog.hospital_id', $org_id],
                                            ['visitlog.doctor_id', $doctor->id],
                                        ])
                                ->where('visitlog.id', '!=', $id)
                                ->where('hospital_services.flag', 'consultation_charge')
                                ->orderBy('created_at', 'desc')
                                ->first();






        if($latestVisit){
            $last_visit_date = $latestVisit->created_at;
            $lastVisit = Carbon::now()->diffInDays($latestVisit->created_at);
            $last_visit_charges = $latestVisit->charges * $latestVisit->qty - $latestVisit->discount;
        }


        $vital = Vitals::where('visit_id', $visit->id)->first();

        $data["mr"] = $patient->id;
        $data["prefix"] = $patient->prefix;
        $data["uhid"] = $patient->uhid;
        $data["dob"] = $patient->dob;
        $data["fname"] = $patient->Fname;
        $data["lname"] = $patient->Lname;
        // $data["age"] = $patient->age;
        // $data["dob"] = $patient->dob;

        if (!empty($patient->dob)) {
            $isValid = false;

            try {
                $dob = Carbon::parse($patient->dob);
                // Check logical validity ΓÇö not a future date or ancient nonsense
                if (!$dob->isFuture() && $dob->year >= 1900) {
                    $isValid = true;
                }
            } catch (\Exception $e) {
                $isValid = false;
            }

            if ($isValid) {
                $now = Carbon::now();
                $diff = $dob->diff($now);

                if ($diff->y < 1) {
                    // Less than 1 year ΓåÆ show months and days
                    $ageText = '';
                    if ($diff->m > 0) {
                        $ageText .= $diff->m . ' M';
                    }
                    if ($diff->d > 0) {
                        $ageText .= ($ageText ? ' ' : '') . $diff->d . ' D';
                    }
                    $data['age'] = $ageText ?: '0 D';
                } else {
                    // 1 year or more ΓåÆ show just years (e.g. 25 Y)
                    $data['age'] = $diff->y . ' Y';
                }
            } else {
                // Invalid date ΓåÆ fallback to stored age
                $data['age'] = !empty($patient->age) ? $patient->age . ' Y' : null;
            }

        } else {
            // DOB not available ΓåÆ fallback
            $data['age'] = !empty($patient->age) ? $patient->age . ' Y' : null;
        }

        $data['dob'] = $patient->dob;


        $data["sex"] = $patient->sex;
        $data["doctor"] = $doctor->name;
        $data['department'] = $doctor->department;
        $data["mobile"] = $patient->mobile_no;
        $data["amt"] = $charges??0;
        $data["address"] = $patient->Address;
        $data["sr_no"] = $sr_no;
        $data['user'] = $user->Fname.' '.$user->Lname;
        $data['insurance'] = HealthInsurance::find($patient->i_cover)->insurance_agen??'';
        $data['category'] = ((float)($charges ?? 0) > 0) ? 'Cash' : 'Free';
        $data['staff_name'] = $visit->first_name.' '.$visit->last_name;
        $data['temp'] = $vital->temprature??'';
        $data['weight'] = $vital->weight??'';
        $data['height'] = $vital->height??'';
        $data['date'] = date('d-m-Y',strtotime($visit->created_at));
        $data['time'] = date('h:i A',strtotime($visit->created_at));
        $data['doc_qualification'] = $doctor->qualification;
        $data['medical_reg_no'] = $doctor->medical_reg_no;
        $data['qualification'] = $doctor->qualification;
        $data['visit_id'] = $visit->visit_id;
        // last paid visit
        $data['last_paid_visit_date'] = $lastPaidVisit ? $lastPaidVisit->created_at : '';
        $data['gap_from_last_paid_visit'] = isset($last_visit_gap_from_today) ? $last_visit_gap_from_today : '';

        $data['base_charges'] = $baseCharge;
        $data['type'] = $type;

        // dd($data['last_paid_visit_date'], $data['gap_from_last_paid_visit']);
        $data['pgb'] = $pgb??'';
        $data['valid_upto'] = $doctor->opd_validity;

        if(intval($charges) > 0){
            $data['visit_type'] = 'normal';
        }else{
             //check if patient already visited during validity days
             if($latestVisit && $lastVisit <= $doctor->opd_validity && intVal($last_visit_charges)>0){
                // followup
                $data['visit_type'] = 'followup';
            }else{
                $data['visit_type'] = 'normal';
            }
        }

        $currentDate =  $visit->created_at ; // Carbon::now(); // Current date
        $data['exp_date'] = $currentDate->addDays($doctor->opd_validity); // Add opd validity days

        $dob = $patient->dob;

        if($dob && ($dob != '0000-00-00')){
            $ageComponents = $this->calculateAge($dob);
            $data['ageComponents']  = $ageComponents;
        }

        if(env('COMMON_PRINTER_PATH',false))
        {

            $jsonFile = url(env('COMMON_PRINTER_PATH').'/printers_config.json');
            $printers = json_decode(file_get_contents($jsonFile), true);
            $printer = $printers['printers']['label_priner'];

            $width_mm = $printer['page_width_mm'] ?? 90;
            $height_mm = $printer['page_height_mm'] ?? 30;

