    public function calculateAge($dobString) {
        $dob = Carbon::parse($dobString);
        $today = Carbon::parse('today');
        $diff = $today->diff($dob);

         // Check if the age is less than 1 month
        if ($diff->y == 0 && $diff->m == 0) {
            return "{$diff->d} days";
        }

        // Check if the age is less than 1 year
        if ($diff->y == 0) {
            return "{$diff->m} months {$diff->d} days";
        }

        // For age 1 year or more
        return "{$diff->y} Y {$diff->m} M {$diff->d} D";
    }

