    public function patient_filter(Request $req)
    {
        $user = Auth::user();
        $org_id = $user->org_id;
        $startDate = $req->start_date;
        $endDate = $req->end_date;
        $search = trim($req->search ?? $req->keyword ?? '');
        $uhid = trim($req->uhid ?? '');
        $name = trim($req->name ?? '');
        $mobile = trim($req->mobile ?? '');

        $this->dateRangeLimit->validate(
            $startDate,
            $endDate,
            auth()->user()->org_id
        );

        $query = Patient::where('pi.hospital_id', $org_id)
            ->leftJoin('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover');

        // If specific UHID provided
        if (!empty($uhid)) {
            $query->where('pi.id', $uhid);
        }

        // If specific Mobile provided
        if (!empty($mobile)) {
            $cleanMob = preg_replace('/\D/', '', $mobile);
            $query->where(function($q) use ($mobile, $cleanMob) {
                $q->where('pi.mobile_no', 'LIKE', "%{$mobile}%")
                  ->orWhere('pi.whats_app_no', 'LIKE', "%{$mobile}%");
                if (!empty($cleanMob)) {
                    $q->orWhere('pi.mobile_no', 'LIKE', "%{$cleanMob}%");
                }
            });
        }

        // If specific Name provided
        if (!empty($name)) {
            $query->where(function($q) use ($name) {
                $q->where('pi.Fname', 'LIKE', "%{$name}%")
                  ->orWhere('pi.Lname', 'LIKE', "%{$name}%")
                  ->orWhereRaw("CONCAT(COALESCE(pi.Fname, ''), ' ', COALESCE(pi.Lname, '')) LIKE ?", ["%{$name}%"]);
            });
        }

        // If general Search term provided
        if (!empty($search)) {
            $cleanSearch = preg_replace('/\D/', '', $search);
            $query->where(function($q) use ($search, $cleanSearch) {
                $q->where('pi.id', $search)
                  ->orWhere('pi.Fname', 'LIKE', "%{$search}%")
                  ->orWhere('pi.Lname', 'LIKE', "%{$search}%")
                  ->orWhereRaw("CONCAT(COALESCE(pi.Fname, ''), ' ', COALESCE(pi.Lname, '')) LIKE ?", ["%{$search}%"])
                  ->orWhere('pi.mobile_no', 'LIKE', "%{$search}%")
                  ->orWhere('pi.abha_number', 'LIKE', "%{$search}%")
                  ->orWhere('pi.abha_address', 'LIKE', "%{$search}%");
                if (!empty($cleanSearch) && strlen($cleanSearch) >= 10) {
                    $q->orWhere('pi.mobile_no', 'LIKE', "%{$cleanSearch}%")
                      ->orWhere('pi.abha_number', 'LIKE', "%{$cleanSearch}%");
                }
            });
        }

        // Date range filtering (applied if dates provided or if no specific search query)
        if (!empty($startDate) && !empty($endDate)) {
            $query->where(function($q) use ($startDate, $endDate) {
                $q->where(function($sub) use ($startDate, $endDate) {
                    $sub->whereNotNull('pi.date')
                        ->whereDate('pi.date', '>=', $startDate)
                        ->whereDate('pi.date', '<=', $endDate);
                })->orWhere(function($sub) use ($startDate, $endDate) {
                    $sub->whereNull('pi.date')
                        ->whereDate('pi.created_at', '>=', $startDate)
                        ->whereDate('pi.created_at', '<=', $endDate);
                });
            });
        } elseif (!empty($startDate)) {
            $query->where(function($q) use ($startDate) {
                $q->whereDate('pi.date', '>=', $startDate)
                  ->orWhereDate('pi.created_at', '>=', $startDate);
            });
        } elseif (!empty($endDate)) {
            $query->where(function($q) use ($endDate) {
                $q->whereDate('pi.date', '<=', $endDate)
                  ->orWhereDate('pi.created_at', '<=', $endDate);
            });
        }

        $data = $query->orderBy('pi.id', 'DESC')
            ->select('pi.*', 'health_insurance_agen.insurance_agen as insurance')
            ->limit(300)
            ->get();

        return response()->json($data);
    }

    public function visit_filter(Request $req)
    {
        $user = Auth::user();
        $org_id = $user->org_id;

        $startDate = $req->start_date;
        $endDate = $req->end_date;
        $doctor = $req->doctor;

        $data = Visitlog::leftjoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
                            ->whereDate('visitlog.date', '>=', $startDate)
                            ->whereDate('visitlog.date', '<=', $endDate)
                            ->where('visitlog.hospital_id', $org_id)
                            ->select('visitlog.*','visitlog.id as visitid','visitlog.doctor_id as did',
                                    'visitlog.patient_id as pid', 'visitlog.created_at as visitdate',
                                    'pi.*','pi.id as pid','pi.age as patient_age','doctor_db.*')
                            ->orderBy('visitlog.date', 'ASC')
                            ->orderBy('visitlog.id', 'ASC');
    if($doctor)
    {
        $data->where('visitlog.doctor_id', $doctor);
    }
    $data = $data->get();

    // Initialize array to store visit counts for each doctor and date
    $doctorDateVisitCounts = [];

    // Loop through visits and assign serial numbers
    foreach ($data as $visi) {
        $doctorId = $visi->did;
        $visitDate = \Carbon\Carbon::parse($visi->visitdate)->toDateString();

        // Key for grouping by date and doctor
        $dateDoctorKey = $visitDate . '_' . $doctorId;

        // Initialize the count if not already set
        if (!isset($doctorDateVisitCounts[$dateDoctorKey])) {
            $doctorDateVisitCounts[$dateDoctorKey] = 0;
        }

        // Increment the count
        $doctorDateVisitCounts[$dateDoctorKey]++;

        // Assign the serial number
        $visi->sr_no = $doctorDateVisitCounts[$dateDoctorKey];
    }

    // Reverse the collection order for display
    $data = $data->sortByDesc('visitid')->values();

        return response()->json($data);
    }



