    public function pat_save(Request $req){
        $user = Auth::user();
        $org_id = $user->org_id;



            $validate =  Validator::make($req->all(),[
                'prefix'=> 'required',
                'Fname' => 'required',
                'email' => 'email',
                'i_cover' =>'required',
                'gender' => 'required',
                'age' => 'required',
                'mobile_no' => 'required|digits:10',
            ]);

            if($validate->fails()){
                    return response()->json([
                        'status' => 'error',
                        'errors' => $validate->errors()
                    ]);
            }

        if(auth()->user()->can('module-permission',['patient','can_update']))
          {
            $patient = Patient::findOrFail($req->uhid);

            $addMsg = '';

            if($patient->mobile_no != $req->mobile_no){
                $patient->mnvs = 0;
                $patient->mnvs_otp = 0;
                $patient->mnvs_otp_expiry = null;
                $patient->save();

                $addMsg = 'Mobile Number Updated.';
            }


            $patient->prefix = $req->prefix;
            $patient->Fname = $req->Fname;
            $patient->Lname = $req->Lname;
            $patient->age = $req->age;
            // $patient->dob = $req->dob?date('Y-m-d',strtotime($req->dob)):null;
            if($req->dob){
                $patient->dob = date("Y-m-d", strtotime($req->dob));
            }else{
                $age = $req->age;
                $patient->dob = date('Y-m-d', strtotime('-'.$age.' years'));
                $patient->is_dob_calc = 1;
            }
            $patient->sex = $req->gender;
            $patient->i_cover = $req->i_cover;
            $patient->Fathername = $req->Fathername;
            $patient->spousename = $req->spousename;
            $patient->guardian_name = $req->guardian_name;
            $patient->referring_doctor = $req->ref_doctor;
            $patient->mobile_no = $req->mobile_no;
            $patient->whats_app_no = $req->whats_app_no;
            $patient->lead_gen = $req->lead_gen;
            $patient->Address = $req->Address;
            $patient->email_id = $req->email_id;
            if ($req->has('abdm_enabled')) {
                $patient->abdm_enabled = $req->input('abdm_enabled') ? 1 : 0;
            } elseif ($patient->abdm_enabled === null) {
                $patient->abdm_enabled = 1;
            }
            $patient->save();

            if (!empty($patient->abha_address) || !empty($patient->abha_number) || !empty($patient->abha_add)) {
                \App\Jobs\ABDM\GenerateAbdmLinkTokenJob::dispatch((int)$patient->id, (int)($patient->hospital_id ?? 1))
                    ->onQueue('abdm-notifications')
                    ->delay(now()->addSecond());
            }
        }else{
            return response()->json(['status'=> 'error', 'msg'=>'You do not have permission to update patient details.']);
        }

            $insurance = HealthInsurance::find($req->i_cover);

            $data = [
                'data' => $req->input(),
                'insurance' => $insurance
            ];

            if($patient){
                return response()->json(['status'=> 'success', 'msg'=>'Record updated successfully.'. $addMsg, 'data' => $data ]);
            }


    }



