    public function update(Request $req, $id)
    {
        $user = Auth::user();
        $org_id = $user->org_id;

         if(auth()->user()->can('module-permission',['patient','can_update']))
          {

                $req->validate([
                    'prefix'    => 'required',
                    'Fname'     => 'required',
                    'email'     => 'nullable|email',
                    'i_cover'   => 'required',
                    'gender'    => 'required',
                    'age'       => 'required',
                    'mobile_no' => 'required|digits:10',
                    'image'     => 'nullable|file|mimes:jpeg,jpg,png,gif,bmp,webp|max:5120',
                ], [
                    'image.file'  => 'The uploaded profile photo must be a valid file.',
                    'image.mimes' => 'The profile image must be a file of type: JPG, JPEG, PNG, GIF, BMP, or WebP.',
                    'image.max'   => 'The profile image must not exceed 5MB.',
                ]);

                $patient = Patient::findOrFail($id);

                if ($req->hasFile('image')) {
                    $file = $req->file('image');
                    if ($file && $file->isValid()) {
                        // Secure validation checking true MIME bytes and blocking executable extensions
                        \App\Services\SecureFileService::validate($file, ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp'], 5120, 'image');

                        $photo_filenm = 'patient_' . time() . '_' . \Illuminate\Support\Str::random(10) . '.jpg';
                        $save_dir = public_path('assets/images/patients');
                        if (!file_exists($save_dir)) {
                            mkdir($save_dir, 0755, true);
                        }

                        $target_path = $save_dir . DIRECTORY_SEPARATOR . $photo_filenm;

                        try {
                            Image::load($file->getRealPath() ?: $file->getPathname())
                                ->quality(75)
                                ->format('jpg')
                                ->save($target_path);

                            // Safely remove previous image if it exists and is not a default avatar
                            if (!empty($patient->image) && file_exists(public_path($patient->image)) && !str_contains($patient->image, 'avatar.png')) {
                                @unlink(public_path($patient->image));
                            }

                            $patient->image = 'assets/images/patients/' . $photo_filenm;
                        } catch (\Throwable $e) {
                            \Log::error('Patient image processing failed: ' . $e->getMessage(), [
                                'patient_id' => $id,
                                'file'       => $file->getClientOriginalName(),
                            ]);
                            throw \Illuminate\Validation\ValidationException::withMessages([
                                'image' => ['Unsupported image type. GD driver is only able to decode JPG, PNG, GIF, BMP or WebP files.']
                            ]);
                        }
                    }
                }

                $patient->prefix = $req->prefix;
                $patient->Fname = $req->Fname;
                $patient->Lname = $req->Lname;
                $patient->age = $req->age;
                $patient->dob = $req->filled('dob') ? date('Y-m-d', strtotime($req->dob)) : null;
                $patient->sex = $req->gender;
                $patient->i_cover = $req->i_cover;
                $patient->Fathername= $req->Fathername;
                $patient->spousename= $req->spousename;
                $patient->guardian_name= $req->guardian_name;
                $patient->referring_doctor = $req->ref_doctor;
                $patient->whats_app_no = $req->whats_app_no;
                $patient->mobile_no = $req->mobile_no;
                $patient->lead_gen= $req->lead_gen;
                $patient->Address = $req->Address;
                if ($req->filled('abha_number')) {
                    $patient->abha_number = trim($req->abha_number);
                }
                if ($req->filled('abha_address')) {
                    ABDMCloudRelay::recordPatientAbhaAddress($patient, $req->abha_address, true, 'patient_edit');
                } elseif ($req->filled('abha_add')) {
                    ABDMCloudRelay::recordPatientAbhaAddress($patient, $req->abha_add, true, 'patient_edit');
                }
                if ($req->has('abdm_enabled')) {
                    $patient->abdm_enabled = $req->input('abdm_enabled') ? 1 : 0;
                } elseif ($patient->abdm_enabled === null) {
                    $patient->abdm_enabled = 1;
                }
                $patient->save();

                if (!empty($patient->abha_address) || !empty($patient->abha_number) || !empty($patient->abha_add)) {
                    \App\Jobs\ABDM\GenerateAbdmLinkTokenJob::dispatch((int)$patient->id, (int)($patient->hospital_id ?? 1))
                        ->onQueue('abdm-notifications')
                        ->delay(now()->addSecond());
                }

                return redirect()->back()->with('success', 'Record updated successfully.');

          }else{

           return response()->json([
                    'success' => false,
                    'status'  => 'error',
                    'message' => 'You do not have permission to update patient',
                ], 403);
          }
    }

    public function update_visit_abdm_status(Request $request)
    {
        try {
            $request->validate([
                'visit_id' => 'required|exists:visitlog,id',
                'abdm_enabled' => 'required|in:0,1',
            ]);

            $visit = Visitlog::find($request->visit_id);
            if (!$visit) {
                return response()->json([
                    'status' => false,
                    'message' => 'Visit record not found.'
                ], 404);
            }

            $visit->abdm_enabled = (int) $request->abdm_enabled;
            $visit->save();

            $statusText = $visit->abdm_enabled ? 'enabled' : 'disabled';

            return response()->json([
                'status' => true,
                'message' => 'ABDM status ' . $statusText . ' for Visit #' . $visit->id,
                'abdm_enabled' => $visit->abdm_enabled
            ]);
        } catch (\Exception $e) {
            return response()->json([
                'status' => false,
                'message' => 'Failed to update ABDM status: ' . $e->getMessage()
            ], 500);
        }
    }


