    public function cancel_visit(Request $request){
        $user = Auth::user();

        if($user->can('module-permission', ['opd_visit_cancel', 'can_update'])){
            $visitlog = Visitlog::find($request->visit_id);
            $visitlog->is_cancelled = 1;
            $visitlog->save();
            return response()->json(['status' => 'success', 'message' => 'Visit cancelled successfully']);
        }else{
            return response()->json(['status' => 'error', 'message' => 'You are not authorized to perform this action']);
        }
    }


