    public function admit_patient(Request $request){
        $user = Auth::user();
        $org_id = $user->org_id;

        DB::beginTransaction();

        $v = Visitlog::join('pi','pi.id','=','visitlog.patient_id')
                            ->where('visitlog.id',$request->vid)
                            ->where('visitlog.hospital_id',$org_id)
                            ->select('visitlog.*','pi.i_cover')
                            ->first();
        if(!$v){
            return response()->json(['status' => 'error', 'message' => 'Visit not found']);
        }

        $pat = Visitlog::where('patient_id',$v->patient_id)
                        ->where('hospital_id',$org_id)
                        ->where('visit_status',1)
                        ->first();

        if($pat){
            return response()->json(['status' => 'error', 'message' => 'Patient already admitted']);
        }


           $visit = new Visitlog;
           $visit->patient_id = $v->patient_id;
           $visit->hospital_id = $org_id;
           $visit->doctor_id = $v->doctor_id;
           $visit->ch = '';
           $visit->visit_status = 1;

           $currentDate =  $v->ad2; // Carbon::today()->toDateString();
           $date = $currentDate." 00:00:00";
           $visit->date = $date;
           $visit->admission_date = $date;
           $visit->ad2 = $date;
           $visit->at1 = $v->at1;
           // $visit->dd2 = $date;

           $currentTime =  Carbon::now();
           $visit->visit_time = $currentTime->format('H:i:s');

           $visit->last_update= time();

           // visit id is visit no. for selected doctor in this hospital

           $lastVisitNo = Visitlog::where([
                                           ['patient_id',$v->patient_id],
                                           ['hospital_id',$org_id],
                                           ['doctor_id',$v->doctor_id]]
                                       )
                                       ->latest('created_at')
                                       ->value('visit_id');

           // Increment the `visit_id` if it exists; otherwise, start with 1
           $visit->visit_id = $lastVisitNo ? $lastVisitNo + 1 : 1;


           $visit->save();

           // insert id to gen_pres_log_1 table
           $new_visit_id = $visit->id;

           // // insert id to gen_pres_log_1 table
           $gen_pres_log = new Gen_pres_log_1();
           $gen_pres_log->visit_table_id = $new_visit_id;
           $gen_pres_log->save();

           // fetch second last record
           $second_last_visit_data = Visitlog::where([['doctor_id',$v->doctor_id],['patient_id',$v->patient_id],['hospital_id',$org_id]])->whereNull('visit_type')->orderBy('id','desc')->skip(1)->take(1)->first();

           if($second_last_visit_data){
               $this->copy_old_visit_data_to_new($new_visit_id, $second_last_visit_data->id);
           }




           $hosp = new Ipd_details;
           $hosp->visit_table_id =  $new_visit_id;
           $hosp->i_cover = $v->i_cover;

           $hosp->save();


           DB::commit();


        return response()->json(['status' => 'success', 'message' => 'Patient admitted successfully']);
    }


