    public function export_visit_list(Request $request){
        $fromDate = $request->query('from_date');
        $toDate = $request->query('to_date');
        $uhid = $request->query('uhid');
        $doctor = $request->query('doctor');

        // If dates are not provided, set default values
        if (!$fromDate || !$toDate) {
            return redirect()->back()->with('error', 'Please select a date range.');
        }

        // Fetch users based on date range
        $users = Visitlog::leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->leftJoin('pi', 'pi.id', '=', 'visitlog.patient_id')
                            ->leftJoin('vitals','vitals.visit_id','=','visitlog.id')
                            ->select('visitlog.created_at',
                                    'pi.prefix',
                                    'pi.id',
                                    'pi.Fname',
                                    'pi.Lname',
                                    'pi.dob',
                                    'pi.mobile_no',
                                    'doctor_db.name as doctor_name',
                                    'pi.Address',
                                    'pi.id as uhid',
                                    'pi.age',
                                    'pi.sex as gender',
                                    'vitals.temprature',
                                    'vitals.weight',
                                    'vitals.height',
                            )
                            ->whereBetween('visitlog.created_at', [
                                Carbon::parse($fromDate)->startOfDay(),
                                Carbon::parse($toDate)->endOfDay()
                            ])
                            ->where('visitlog.hospital_id', auth()->user()->org_id)
                            ->where('visitlog.visit_status', 0);
        if($doctor){
            $users->where('visitlog.doctor_id', $doctor);
        }
        if($uhid){
            $users->where('pi.id', $uhid);
        }
        $users = $users->groupBy('visitlog.id')->get();
        if ($users->isEmpty()) {
            return redirect()->back()->with('error', 'No data found for the selected date range.');
        }

        $fileName = "users_data_" . date('Ymd_His') . ".xls";
        $headers = [
            "Content-Type" => "application/vnd.ms-excel",
            "Content-Disposition" => "attachment; filename=\"$fileName\""
        ];

        // Generate Excel content
        $excelContent = "Date\t Patient Name\t Contact \t UHID\t Age\tGender \tAddress \t Doctor\t Height(cm)\t Weight(Kg)\t BMI \t Category\n"; // Column headings
        foreach ($users as $user) {
            $height = $user->height;
            $weight = $user->weight;
            if ($height > 0 && $weight > 0) {
                $heightInMeters = $height / 100; // Convert cm to meters
                $bmi = $weight / ($heightInMeters * $heightInMeters);
                $bmi = round($bmi, 2); // Round to 2 decimal places

                if ($bmi < 18.5) {
                    $category = "Underweight";
                } elseif ($bmi >= 18.5 && $bmi <= 24.9) {
                    $category = "Normal weight";
                } elseif ($bmi >= 25 && $bmi <= 29.9) {
                    $category = "Overweight";
                } else {
                    $category = "Obese";
                }

            }else{
                $bmi = '';
                $category = '';
            }

            $date = date('d-m-Y h:i A', strtotime($user->created_at));
            $geAge = get_age_number($user->dob);

            $excelContent .= "{$date}\t{$user->prefix} {$user->Fname} {$user->Lname}\t{$user->mobile_no}\t{$user->uhid}\t{$geAge}\t{$user->gender}\t{$user->Address}\t{$user->doctor_name}\t{$user->height}\t{$user->weight}\t $bmi \t $category \n";
        }

        return response()->make($excelContent, 200, $headers);

    }





    public function send_follow_up_message(Request $request)
    {
        $request->validate([
            'id' => 'required',
        ]);
        try{
            DB::beginTransaction();

            $orgID = auth()->user()->org_id;

            // dd($orgID);

            $visit = Visitlog::findOrFail($request->id);
            $patient = Patient::findOrFail($visit->patient_id);
            $doctor = Doctor_db::findOrFail($visit->doctor_id);
            $hospital = Healtcare_org::findOrFail($orgID);

            if($visit->app_sms_count >= 2)
            {
                return response()->json(['success' => false,'message'=>'Notify limit for the patient is exceeded.']);
            }
            $visit->app_sms_count = $visit->app_sms_count+1;
            $visit->save();

          $res =  \App\Helpers\Notifier::followup_visit_reminder([
                'patient_id' => $patient->id,
                'phone_number' => $patient->mobile_no,
                'params' => [
                    'patient_name'=> $patient->prefix.' '.$patient->Fname.' '.($patient->Lname??""),
                    'follow_up_date'=> date('D, d M Y', strtotime($visit->fud)),
                    'dr_name'=> $doctor->name??"",
                    'hospital_name'=>$hospital->name??'',
                    'hospital_contact'=>$hospital->contact_no??'',
                    'link' => $hospital->external_app_link?:url('book-appointment/select-doctor/'.encryptID($orgID)),
                    ]
            ]);

            // dd($res);

            DB::commit();
        }catch(\Exception $e){
            DB::rollBack();
            return response()->json(['success' => false,'message'=>$e->getMessage()]);
        }

        return response()->json(['success' => true,'message'=>'Message sent successfully']);
    }
