    public function fetch_today_patient_visit_charges_v5()
    {
        $org_id = auth()->user()->org_id;
        $currentDate = Carbon::today()->toDateString();
        $visitsIds = Visitlog::where('hospital_id', $org_id)
            ->whereDate('date', $currentDate)
            ->where('is_cancelled', 0)
            ->where('visit_status', 0)
            ->pluck('id');
        if ($visitsIds->isEmpty()) {
            return response()->json([
                'success' => true,
                'charges' => []
            ]);
        }

        $rows = PatientGenBill::join('patient_billing', 'patient_gen_bill.bill_id', '=', 'patient_billing.id')
            ->join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
            ->join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
            ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
            ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
            ->select([
                'patient_billing.visit_id',
                'doctor_db.id as doctor_id',
                'doctor_db.name as doctor_name',
                'patient_gen_bill.bill_id',
                'patient_gen_bill.created_at',
                'patient_gen_bill.service_id',
                'hospital_services.service',
                'patient_gen_bill.charges',
                'patient_gen_bill.discount',
                DB::raw('(patient_gen_bill.charges - patient_gen_bill.discount) as net_charge'),
                'patient_gen_bill.service_status',
                'pi.Fname',
                'pi.Lname'
            ])
            ->whereIn('patient_billing.visit_id', $visitsIds)
            ->whereIn('hospital_services.flag', [
                'consultation_charge',
                'procedure'
            ])
            ->get();

        $charges = $rows->groupBy('visit_id')->map(function ($items) {
            $first = $items->first();
            $data = $items->map(function ($row) {
                return [
                    'bill_id'        => $row->bill_id,
                    'created_at'     => $row->created_at ? (string)$row->created_at : null,
                    'service_id'     => $row->service_id,
                    'service'        => $row->service,
                    'charges'        => $row->charges,
                    'discount'       => $row->discount,
                    'net_charge'     => $row->net_charge,
                    'service_status' => $row->service_status,
                    'Fname'          => $row->Fname,
                    'Lname'          => $row->Lname,
                ];
            })->values();

            return [
                'visit_id'    => $first->visit_id,
                'doctor_id'   => $first->doctor_id,
                'doctor_name' => $first->doctor_name,
                'data'        => json_encode($data),
            ];
        })->values();

        return response()->json([
            'success' => true,
            'charges' => $charges
        ]);
    }

