    public function getCities(Request $request)
    {
        $search = $request->q;

        $cities = CityDb::query()
                            ->when($search, function($query, $search) {
                                $query->where('name', 'like', "%{$search}%")
                                    ->orWhere('state_name', 'like', "%{$search}%");
                            })
                            ->where('status','approved')
                            ->limit(20)
                            ->get();

        return response()->json($cities);
    }

