     public function approve_ref_doctor(Request $request){
       $id = $request->id;
       $status = $request->status;

       if($request->status == 'delete'){
            $doctor = RefDoctor::find($id);
            $doctor->delete();
       }else {
            $city = RefDoctor::find($id);
            $city->status = $request->status;
            $city->approved_by = Auth()->User()->id;
            $city->save();
       }


       $msg = 'Referring Doctor '.$status.' successfully';
       return response()->json(['status'=>'success','message'=>$msg]);
    }


    public function visit_patientList()
    {
        $user = Auth::user();
        $org_id = $user->org_id;
        $currentDate = Carbon::today()->toDateString();
        $visit = Visitlog::leftjoin('doctor_db','doctor_db.id','=','visitlog.doctor_id')
                ->leftjoin('pi','pi.id','=','visitlog.patient_id')
                ->whereDate('visitlog.date',$currentDate)
                ->select('visitlog.*','visitlog.date as created','visitlog.doctor_id as did','visitlog.id as vid','visitlog.patient_id as pid','doctor_db.name','pi.*')
                ->where('visitlog.hospital_id',$org_id)
                ->orderBy('visitlog.id','DESC')
                ->get();

       // Initialize an array to store the visit count for each doctor
        $doctorVisitCounts = [];

        // Loop through visits and assign serial numbers
        foreach ($visit as $visi) {
            $doctorId = $visi->did;

            // Initialize the count if not already set
            if (!isset($doctorVisitCounts[$doctorId])) {
                $doctorVisitCounts[$doctorId] = 0;
            }

            // Increment the count
            $doctorVisitCounts[$doctorId]++;

            // Assign the serial number
            $visi->sr_no = $doctorVisitCounts[$doctorId];
        }
       // Reverse the collection order for display
        // $visit = $visit->sortByDesc('id')->values();

        $data=compact('visit');
        return response()->json($data);
    }

    public function fetch_by_abha(Request $request)
    {
        $user = Auth::user();
        $org_id = $user->org_id;

        $abhaNumber = trim($request->input('abha_number', ''));
        $abhaAddress = trim($request->input('abha_address', ''));

        if (empty($abhaNumber) && empty($abhaAddress)) {
            return response()->json([
                'success' => false,
                'message' => 'Please enter an ABHA Number or ABHA Address to search.'
            ]);
        }

        $cleanAbhaDigits = preg_replace('/\D/', '', $abhaNumber);
        $hyphenAbhaNumber = (strlen($cleanAbhaDigits) === 14)
            ? substr($cleanAbhaDigits, 0, 2) . '-' . substr($cleanAbhaDigits, 2, 4) . '-' . substr($cleanAbhaDigits, 6, 4) . '-' . substr($cleanAbhaDigits, 10, 4)
            : $abhaNumber;

        $query = Patient::where('hospital_id', $org_id);

        $addrVariants = [];
        if (!empty($abhaAddress)) {
            $addrPrefix = explode('@', $abhaAddress)[0];
            $addrVariants = array_values(array_unique(array_filter([
                $abhaAddress,
                $addrPrefix,
                $addrPrefix . '@sbx',
                $addrPrefix . '@abdm',
            ])));
        }

        $query->where(function ($q) use ($abhaNumber, $addrVariants, $cleanAbhaDigits, $hyphenAbhaNumber) {
            if (!empty($abhaNumber)) {
                $q->where('abha_number', $abhaNumber)
                  ->orWhere('abha_number', $hyphenAbhaNumber)
                  ->orWhere('abha_number', $cleanAbhaDigits);
            }
            if (!empty($addrVariants)) {
                $q->orWhereIn('abha_address', $addrVariants)
                  ->orWhereIn('abha_add', $addrVariants);
            }
        });

        $patient = $query->first();

        if ($patient) {
            return $this->getpatient_details($patient->id);
        }

        return response()->json([
            'success' => false,
            'message' => 'No patient record found matching the provided ABHA details.'
        ]);
    }

