public function getDoctorsBySpecialization($spec_id=null)
{
    $user = Auth::user();
    $org_id = $user->org_id;
    $specIdArray = ($spec_id??false)?explode(',', $spec_id):[];
    $doctors = HospitalDoctor::join('doctor_db','doctor_db.id','=','org_doc_index.doc_id')
                ->select('doctor_db.*','org_doc_index.org_id')
                ->when($specIdArray, function ($q) use ($specIdArray) {
                    $q->whereIn('key_spec', $specIdArray);
                })
                ->where('org_doc_index.org_id',$org_id)
                ->orderBy('name','ASC')
                ->get();
    return response()->json($doctors);
}

