public function get_consultcharges($doc, $uhid = 0)
{
    $user = Auth::user();
    $org_id = $user->org_id;

    $res = HospitalSetting::select('status')->where('identifier','consultant_charges')->where('hospital_id',$org_id)->first();
    // 0 for automatic && 1 for manual
    $type = ($res->status ?? true) ? 'manual' : 'automatic';

    $patient = null;
    if (!empty($uhid) && $uhid !== '0') {
        $patient = is_numeric($uhid) ? Patient::find($uhid) : null;
    }

    $reg_charge = 0;
    if (!$patient || $patient->is_registered == 0) {
        $regch = HospitalRegistrationFee::where('hospital_id', $org_id)->first();
        $reg_charge = $regch ? (float)$regch->registration_fee : 0;
    }

    if ($type == 'manual') {
        $org_doc = HospitalDoctor::where('org_id', $org_id)->where('doc_id', $doc)->first();

        $query = DocCharge::where(function($q) use ($org_doc, $doc) {
            if ($org_doc) {
                $q->where('entry_id', $org_doc->id);
            } else {
                $q->where('entry_id', $doc);
            }
        })
        ->where('status', 1)
        ->where('opd', 1)
        ->whereNotIn('comment', ['C2', 'C3']);

        $charges = $query->orderBy('id', 'ASC')->get();

        // If empty (e.g. entry_id stored under doc instead of org_doc->id), try with doc
        if ($charges->isEmpty() && $org_doc && $org_doc->id != $doc) {
            $charges = DocCharge::where('entry_id', $doc)
                ->where('status', 1)
                ->where('opd', 1)
                ->whereNotIn('comment', ['C2', 'C3'])
                ->orderBy('id', 'ASC')
                ->get();
        }

        $total_visit = 0;
        if ($patient) {
            $visitlog = Visitlog::select('visit_id', 'patient_id')
                ->where('patient_id', $patient->id)
                ->where('doctor_id', $doc)
                ->where('hospital_id', $org_id)
                ->where('visit_status', 0)
                ->whereNull('visit_type')
                ->orderBy('id', 'DESC')
                ->first();
            if ($visitlog) {
                $total_visit = (int)$visitlog->visit_id;
            }
        }

        $data = [
            'status' => 'success',
            'charges' => $charges,
            'total_visit' => $total_visit,
            'patient_id' => $patient ? $patient->id : 0,
            'type' => $type,
            'is_registered' => $patient ? $patient->is_registered : 0,
            'reg_charge' => $reg_charge
        ];

        return response()->json($data);

    }else
    if($type == 'automatic'){

        $org_doc = HospitalDoctor::where('org_id', $org_id)->where('doc_id', $doc)->first();
        $opdCharges = $org_doc->opd_charges;
        $charges = json_decode($opdCharges);
        $opd_validity = $org_doc->opd_validity ?? 0;



        if($charges == null){
            return response()->json(['status'=>'error','message'=>'Charges not found']);
        }

        $baseCharge = (float)$charges->baseCharge;
        $emergencyCharge = (float)$charges->emergencyCharge;
        $vaccinationCharge = (float)$charges->vaccinationCharge;
        $discountArr = $charges->discount;

        // Get LAST visit where full consultation/base charge was paid
        // $lastVisit = Visitlog::join('patient_billing', 'patient_billing.visit_id', '=', 'visitlog.id')
        //                         ->join('patient_gen_bill', 'patient_gen_bill.bill_id', '=', 'patient_billing.id')
        //                         ->join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')

        //                         ->select(
        //                             'visitlog.visit_id',
        //                             'visitlog.created_at',
        //                             'visitlog.id as visitlog_id',
        //                             DB::raw('
        //                                 SUM(
        //                                     (patient_gen_bill.charges * patient_gen_bill.qty)
        //                                     - IFNULL(patient_gen_bill.discount, 0)
        //                                 ) as total_charges
        //                             ')
        //                         )
        //                         ->whereNull('visitlog.visit_type')
        //                         ->where([
        //                             ['visitlog.patient_id', $uhid],
        //                             ['visitlog.doctor_id', $doc],
        //                             ['visitlog.hospital_id', $org_id]
        //                         ])
        //                         ->where('hospital_services.flag', 'consultation_charge')
        //                         ->where(function ($query) {
        //                                     $query->where('patient_gen_bill.is_deleted', 0)
        //                                         ->orWhereNull('patient_gen_bill.is_deleted');
        //                                 })
        //                         ->groupBy(
        //                             'visitlog.id',
        //                             'visitlog.visit_id',
        //                             'visitlog.created_at'
        //                         )
        //                         ->havingRaw('total_charges >= ?', [$baseCharge])
        //                         ->orderByDesc('visitlog.id')
        //                         ->first();



   $lastVisit = Visitlog::whereNull('visitlog.visit_type')
                        ->select(
                            'visitlog.visit_id',
                            'visitlog.created_at',
                            'visitlog.id as visitlog_id',
