        // dd($lastVisit);

        $data = [];
        $netCharge = $baseCharge;
        $daysAgo = null;
        $discountApplied = false;

        if($lastVisit){
            $daysAgo = Carbon::now()->diffInDays($lastVisit->created_at);
            // $lastVisitCharges = (float)$lastVisit->total_charges;

            if($daysAgo >= 0){
                // Within 0-9 days window
                  $netCharge = $this->getDoctorCharge($discountArr, $daysAgo, $baseCharge);

            } else {
                // 10+ days since last visit ΓåÆ NEW CYCLE STARTS
                // Apply BASE CHARGE
