        private function getDoctorCharge($discountArr, $daysAgo, $baseCharge)
        {
            $netCharge = $baseCharge;

            foreach ($discountArr as $item) {
                $start = (int)$item->start;
                $end = (int)$item->end;
                $discount = (float)$item->discount;

                if ($daysAgo >= $start && $daysAgo <= $end) {
                    $netCharge = $baseCharge - (($baseCharge * $discount) / 100);
                    break;
                }
            }

            return round($netCharge, 2);
        }


