        public function get_reg_opd_services($patient_id){
            $user = Auth::user();
            $org_id = $user->org_id;

             $patient = Patient::where('id', $patient_id)->first();

             if($patient && $patient->is_registered == 0){
                $records = HospitalSer::select('id','service','flag')
                                        ->where('flag', 'registration_charge')
                                        ->orWhere('flag', 'consultation_charge')
                                        ->orderBy('id','desc')
                                        ->get();

                $regch = HospitalRegistrationFee::where('hospital_id', $org_id)->first();
                $reg_charge = $regch->registration_fee ?? 0;


                $records = $records->map(function ($record) use ($reg_charge) {
                                            if ($record->flag === 'registration_charge') {
                                                $record->charges = $reg_charge;
                                            }
                                            return $record;
                                        });

             }else{
                $records = HospitalSer::select('id','service','flag')
                                        ->where('flag', 'consultation_charge')
                                        ->get();
             }


            return response()->json($records);
        }


    public function getPatientDetails(Request $request)
    {
        // Retrieve the UHID from the request
        $uhid = $request->input('uhid');

        // Retrieve patient details based on the UHID (ensure exact match)
        $patient = Patient::where('id', $uhid)->first();



        if ($patient) {
