   public function check_doc_base_charges($doctor_id, $charge)
    {
        $org_id = Auth::user()->org_id;

        $org_doc = HospitalDoctor::where('org_id', $org_id)
                    ->where('doc_id', $doctor_id)
                    ->first();

        if (!$org_doc || empty($org_doc->opd_charges)) {
            return false;
        }

        $auto_charges = json_decode($org_doc->opd_charges);

        $baseCharge = (float) ($auto_charges->baseCharge ?? 0);
        $emergencyCharge = (float) ($auto_charges->emergencyCharge ?? 0);

        $charge = (float) $charge;

        return ($charge == $baseCharge || $charge == $emergencyCharge);
    }


     public function visit_save(Request $req)
    {
        $module = $req->input('module');

        $validate =  Validator::make($req->all(),[
