            'doctor_id' => 'required',
            'doc_charges' => 'required',
            'registration_fee' => 'required',
            // 'team' => [
            //     Rule::requiredIf($module == 'emergency')
            // ],
        ]);

        if($validate->fails()){
            return response()->json([ 'status' => 'error', 'errors'=> $validate->errors()]);
        }

        $user = Auth::user();
        $org_id = $user->org_id;

        //    $pi = Patient::where('id', $request->patient_id)->where('hospital_id', $org_id)->first();
        //    if(!$pi){
        //         return response()->json(['status'=>'error','message'=>'Patient not found in this hospital. Please register patient first.']);
        //    }


        // $v = Visitlog::where('hospital_id',$org_id)->where('patient_id',$req->patient_id)->where('visit_status',1)->first();
        // if($v){
        //     return response()->json(['status'=>'error','errors'=>['Patient aleady admitted.']]);
        // }

        try{
            DB::beginTransaction();

            $res = HospitalSetting::select('status')->where('identifier','consultant_charges')->where('hospital_id',$org_id)->first();
            // 0 for automatic && 1 for manual
            $type = ($res->status??true) ? 'manual' :  'automatic';

            $is_base_charges = false;
            if($type == 'automatic'){
                 $is_base_charges =  $this->check_doc_base_charges($req->doctor_id, $req->doc_charges);
            }else{
                if($req->doc_charges > 0){
                    $is_base_charges = true;
                }
            }

            $visit = new Visitlog;
            $visit->patient_id = $req->patient_id;
            $visit->hospital_id = $org_id;
            $visit->doctor_id = $req->doctor_id;
            $visit->ch = $req->doc_charges;
            $visit->ref_by = $req->ref_by ?? null;
