            $visit->date = $date;

            $currentTime = Carbon::now();
            $visit->visit_time = $currentTime->format('H:i:s');

            $visit->last_update= time();

            // visit id is visit no. for selected doctor in this hospital
            // fetch last visit no.
            $lastVisitNo = Visitlog::where([
                                            ['patient_id',$req->patient_id],
                                            ['hospital_id',$org_id],
                                            ['doctor_id',$req->doctor_id]]
                                        )
                                        ->latest('created_at')
                                        ->value('visit_id');

            // Increment the `visit_id` if it exists; otherwise, start with 1
            $visit->visit_id = $lastVisitNo ? $lastVisitNo + 1 : 1;

            // Generating new Payment receipt no.
            //Check Upload Setting is Enbaled or Not
            $isVisitUpload = HospitalHelper::isSettingEnabled($org_id,'upload_visit_data');
            $isVisitClinicalUpload = HospitalHelper::isSettingEnabled($org_id,'upload_visit_clinical_data');

            // is_visited is for billing status
            $visit->is_visited =0;
            $visit->visit_status = 0;
            $visit->emergency = ($module == 'emergency') ? 1 : 0;
            $visit->team_id = $req->team ?? null;
            $visit->created_by = auth()->user()->id;

            $visit->visit_upload_data = json_encode([
                'upload_visit' => $isVisitUpload,
                'upload_visit_clinical' => $isVisitClinicalUpload,
                'is_uploaded' => 0,
                'last_call_time' => '',
                'last_call_respose' => '',
                'last_update' => strtotime(date('Y-m-d H:i:s')),
            ]);
            $visit->save();

            $new_visit_id = $visit->id;


        // insert id to gen_pres_log_1 table
            $gen_pres_log = new Gen_pres_log_1();
            $gen_pres_log->visit_table_id = $new_visit_id;
            $gen_pres_log->save();


            $hv = HospitalSetting::where('hospital_id', auth()->user()->org_id)
                        ->where('identifier', 'ipd_clinical_notes_context')
                        ->first()->current_setting ?? '';

            $hv2 = HospitalSetting::where('hospital_id', auth()->user()->org_id)
                        ->where('identifier', 'opd_clinical_notes_context')
                        ->first()->current_setting ?? '';

            if(($hv != '') && ($hv2 != '')){
                // fetch second last record
                $second_last_visit_data = Visitlog::where([['doctor_id',$req->doctor_id],['patient_id',$req->patient_id],['hospital_id',$org_id]])->whereNull('visit_type')->orderBy('id','desc')->skip(1)->take(1)->first();
                if($second_last_visit_data){
                    $this->copy_old_visit_data_to_new($new_visit_id, $second_last_visit_data->id);
                }

            }else{
                 // fetch second last record
                $second_last_visit_data = Visitlog::where([['doctor_id',$req->doctor_id],['patient_id',$req->patient_id],['hospital_id',$org_id],['visit_status',0]])->whereNull('visit_type')->orderBy('id','desc')->skip(1)->take(1)->first();
                if($second_last_visit_data){
                    $this->copy_old_visit_data_to_new($new_visit_id, $second_last_visit_data->id);
                }
            }



            $regService = \App\Models\admin\HospitalSer::where('flag','registration_charge')->first();
            $consultService = \App\Models\admin\HospitalSer::where('flag','consultation_charge')->first();
            $docConsultService = \App\Models\admin\HospitalSer::where('flag','doctor_consultation')->first();

           // dd($consultService, $docConsultService);

            $patient = Patient::find($req->patient_id);

            $lastBill = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                                ->select('visitlog.visit_status','patient_billing.*')
                                ->where('visitlog.visit_status',0)
                                ->orderBy('patient_billing.id','DESC')
                                ->first();
            $receipt_no = ($lastBill && $lastBill->receipt_no) ? $lastBill->receipt_no + 1 : 1;

            $registration_fee = floatval($req->registration_fee ?? 0);
            $doc_charges      = floatval($req->doc_charges ?? 0);

            $total_charges = $registration_fee + $doc_charges;



            $bill = new PatientBilling;
            $bill->visit_id = $new_visit_id;
            $bill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($bill->visit_id);
            $bill->i_cover = $patient->i_cover;
            $bill->status = 1;
            $bill->receipt_no = $receipt_no;
            if ($req->discount_type === 'cash') {
                $bill->discount = $req->bill_discount ?? 0;
            } elseif ($req->discount_type === 'percentage') {
                $percent = $req->discountPer ?? 0;
                $total   = $total_charges ?? 0;
                $bill->discount = ($total * $percent) / 100;
            } else {
                $bill->discount = 0;
            }
            if($req->bill_discount || $req->discountPer || $req->r_discount || $req->o_discount || $req->discount_auth_person2){
                $bill->discount_auth_by = $req->discount_auth_person2;
            }

            if($req->discountPer){
                $discount_name = BillDiscount::where('discount', $req->discountPer)->first();
                if($discount_name){
                    $bill->discount_name = $discount_name->name;
                }
            }

            $bill->discount_type = $req->discount_type;
            $bill->remarks = $req->visit_pay_remark ?? null;
            $bill->created_by = auth()->user()->id;
            $bill->save();

            $discount_in = HospitalSetting::where('hospital_id',auth()->user()->org_id)
                            ->where('identifier','discount_in_cash_or_percentage')
                            ->first()->current_setting??'cash';

            if($patient->is_registered != 1)
            {
                // insert registration fee
                $genBillReg = new PatientGenBill;
                $genBillReg->bill_id = $bill->id;
                $genBillReg->service_id = $regService->id;
                $genBillReg->charges =  $req->registration_fee??0;
                $genBillReg->qty = 1;

                if($discount_in == 'cash'){
                    $genBillReg->discount = $req->r_discount ?? 0;
                }else{
                    $genBillReg->discount_per = $req->r_discount ?? 0;

                    $c_discount = $req->registration_fee * $req->r_discount / 100;

                    $genBillReg->discount_per = $c_discount ?? 0;
                }
                $genBillReg->doctor_id = $req->doctor_id;
                $genBillReg->i_cover = $patient->i_cover;
                $genBillReg->created_by = auth()->user()->id;
                $genBillReg->save();

                $patient->is_registered = 1;
                $patient->save();
            }

            $ddata = [
                        'doctor_id' =>  (int)$req->doctor_id,
                        'cgst' => 0,
                        'sgst' => 0,
                    ];


            // insert consultation fee
            $genBillConsult = new PatientGenBill;
            $genBillConsult->bill_id = $bill->id;
            $genBillConsult->service_id = ($module == 'emergency') ? $docConsultService->id : $consultService->id;
            $genBillConsult->charges =  $req->doc_charges??0;
            $genBillConsult->qty = 1;
            // $genBillConsult->discount = $req->o_discount ?? 0;

            if($discount_in == 'cash'){
                $genBillConsult->discount = $req->o_discount ?? 0;
            }else{
                $genBillConsult->discount_per = $req->o_discount ?? 0;

                $c_discount = $req->doc_charges * $req->o_discount / 100;

                $genBillConsult->discount = $c_discount ?? 0;
            }

            $genBillConsult->additional_info = json_encode([
                                                                'doctor_id' => (int)$req->doctor_id,
                                                                'cgst'      => 0,
                                                                'sgst'      => 0,
                                                            ]);
            $genBillConsult->doctor_id = $req->doctor_id;
            $genBillConsult->i_cover = $patient->i_cover;
            $genBillConsult->service_delivered_at = now();
            $genBillConsult->is_er = ($module == 'emergency') ? 1 : 0;
            $genBillConsult->created_by = auth()->user()->id;
            $genBillConsult->save();

            // Insert Payment Details
            if ($req->visit_pay_mode && is_array($req->visit_pay_mode)) {
                foreach ($req->visit_pay_mode as $index => $mode) {
                    $paytype = new BillingPaymentType;
                    $paytype->bill_id = $bill->id;
                    $paytype->payment_mode = $mode;
                    $paytype->amount = $req->payment_amount[$index] ?? 0;
                    $paytype->transaction_id = $req->transaction_id[$index] ?? null;
                    $paytype->remarks = $req->visit_pay_remark ?? null; // Common remark for all entries
                    $paytype->created_by = auth()->user()->id;
                    $paytype->save();
                }
            }

            $hDoc = HospitalDoctor::where('org_id',$org_id)->where('doc_id',$req->doctor_id)->first();


            \App\Helpers\Notifier::opd_visit_complete([
                'patient_id' => $patient->id,
                'phone_number' => $patient->mobile_no,
                'params' => [
                    'patient_name'=> $patient->prefix.' '.$patient->Fname.' '.$patient->Lname,
                    'dr_name'=> $hDoc->doctor->name??"",
                    'link' => $hDoc->hospital->external_app_link?:url('book-appointment/select-doctor/'.encryptID($org_id)),
                    'hospital_name'=>$hDoc->hospital->name??'',
                    'hospital_contact'=>$hDoc->hospital->contact_no??'',
                    ]
            ]);

            \App\Helpers\Notifier::doctor_visit_created([
                'patient_id' => $patient->id,
                'phone_number' => $hDoc->doctor->contact_no??"",
                'params' => [
                    'dr_name'=> $hDoc->doctor->name??"",
                    'patient_name'=> $patient->prefix.' '.$patient->Fname.' '.$patient->Lname??"",
                    'link' => $hDoc->hospital->external_app_link?:url('book-appointment/select-doctor/'.encryptID($org_id)),
                    'visit_date' => date('d-m-Y'),
                    'visit_time' => date('h:i A'),
                    'hospital_name'=>$hDoc->hospital->name??'',
                    'hospital_contact'=>$hDoc->hospital->contact_no??'',
                ]
            ]);

            DB::commit();
        }catch(\Exception $e){
            DB::rollBack();
            return response()->json(['status' => 'error','message' => $e->getMessage()]);
        }



            return response()->json([
                'status' => 'success',
                'message' => 'Visit created successfully',
                'bill_id' => $bill->id,
            ]);
    }

    public function add_ref_list(Request $req){

        $org = auth()->user()->org_id;
        $name = trim($req->name ?? '');
        $contact = trim($req->contact ?? '');

        if (empty($name)) {
            return response()->json(['status' => 'error', 'message' => 'Doctor / Referrer name is required']);
        }

        if (empty($contact)) {
            return response()->json(['status' => 'error', 'message' => 'Contact number is required']);
        }

        // Validate 10-digit mobile number
        if (!preg_match('/^\d{10}$/', $contact)) {
            return response()->json(['status' => 'error', 'message' => 'Please enter a valid 10-digit contact number']);
        }

        // check for uniqueness
        $ref = RefUsers::where('hospital_id', $org)->where('mobile_no', $contact)->first();
        if ($ref) {
            return response()->json(['status' => 'error', 'message' => 'A referring doctor with this contact number already exists']);
        }

        $ref= new RefUsers;
        $ref->hospital_id = $org;
        $ref->name = $name;
        $ref->mobile_no = $contact;
        $ref->save();

        return response()->json([
            'status' => 'success',
            'id' => $ref->id,
            'name' => $ref->name,
            'message' => 'Reference added successfully'
        ]);
    }

