    public function copy_old_visit_data_to_new(
        $new_visit_table_id,
        $old_visit_table_id,
        $context = null
    ){
        // 1. Investigation orders (source = 2)
        patient_investigation_orders::where('visit_table_id', $new_visit_table_id)->delete();

        $a = patient_investigation_orders::select('*')
                ->where([
                    ['visit_table_id', $old_visit_table_id],
                    ['source', 2]
                ])
                ->get()
                ->toArray();

        foreach($a as $code){
            unset($code["id"]);
            unset($code['report_date']);
            unset($code['order_date']);
            $code["visit_table_id"] = $new_visit_table_id;
            $code['created_at'] = now();
            $code['updated_at'] = now();
            $code['created_by'] = auth()->user()->id ?? null;
            patient_investigation_orders::create($code);
        }

        // 2. Patient ICD diagnosis data
        Patient_icd_data::where('visit_table_id', $new_visit_table_id)->delete();

        $a = Patient_icd_data::select('*')
                                ->where('visit_table_id', $old_visit_table_id)
                                ->get()
                                ->toArray();

        foreach($a as $code){
            unset($code["id"]);
            $code["visit_table_id"] = $new_visit_table_id;
            Patient_icd_data::insert($code);
        }

        // 3. Pres_final (Medications)
        Pres_final::where('visit_table_id', $new_visit_table_id)->delete();

        $a = Pres_final::select('*')
                ->where('visit_table_id', $old_visit_table_id)
                ->get()
                ->toArray();

        foreach($a as $code){
            unset($code['id']);
            $code['visit_table_id'] = $new_visit_table_id;
            Pres_final::insert($code);
        }

        // 4. PresManual (Manual Medications)
        PresManual::where('visit_table_id', $new_visit_table_id)->delete();

        $b = PresManual::select('*')
                ->where('visit_table_id', $old_visit_table_id)
                ->get()
                ->toArray();

        foreach($b as $code){
            unset($code['id']);
            $code['visit_table_id'] = $new_visit_table_id;
            $code['created_at'] = now();
            $code['updated_at'] = now();
            PresManual::insert($code);
        }

        // 5. VisitClinicalData (Clinical Notes / Document Data)
        VisitClinicalData::where('visit_id', $new_visit_table_id)
            ->when($context, function ($q) use ($context) {
                $q->where('context', $context);
            })
            ->delete();

        $old_visit = Visitlog::find($old_visit_table_id);

        if ($old_visit && $old_visit->visit_status == 0) {
            // OPD Visit: Copy clinical documents
            $records = VisitClinicalData::where('visit_id', $old_visit_table_id)
                        ->when($context, function ($q) use ($context) {
                            $q->where('context', $context);
                        })
                        ->get();

            foreach ($records as $r) {
                $code = $r->toArray();

                unset($code['id']);
                unset($code['created_at']);
                unset($code['updated_at']);
                unset($code['closed_at']);
                unset($code['approved_by']);
                unset($code['investigation_request']);
                unset($code['add_info']);
                unset($code['is_approved']);
                unset($code['is_abdm_approved']);

                if (!empty($code['others'])) {
                    $othersArr = is_string($code['others']) ? json_decode($code['others'], true) : $code['others'];
                    if (is_array($othersArr)) {
                        unset($othersArr['investigations']);
                        unset($othersArr['investigation_free_box_cb']);
                        unset($othersArr['tooth_plan']);
                        $code['others'] = json_encode($othersArr);
                    }
                }

                $code['created_at']       = now();
                $code['updated_at']       = now();
                $code['is_approved']      = 0;
                $code['is_abdm_approved'] = 0;
                $code['approved_by']      = null;
                $code['closed_at']        = null;
                $code['visit_id']         = $new_visit_table_id;
                $code['created_by']       = auth()->user()->id ?? null;

                VisitClinicalData::insert($code);
            }

        } else {
            // IPD or other context transition
            $hv = HospitalSetting::where('hospital_id', auth()->user()->org_id)
                        ->where('identifier', 'ipd_clinical_notes_context')
                        ->first()->current_setting ?? '';

            $hv2 = HospitalSetting::where('hospital_id', auth()->user()->org_id)
                        ->where('identifier', 'opd_clinical_notes_context')
                        ->first()->current_setting ?? '';

            if (($hv != '') && ($hv2 != '')) {

                $records = VisitClinicalData::where('visit_id', $old_visit_table_id)
                            ->when($context, function ($q) use ($context, $hv) {
                                $q->where('context', $context);
                            }, function ($q) use ($hv) {
                                $q->where('context', $hv);
                            })
                            ->get();

                $insertRows = [];

                VisitClinicalData::where('visit_id', $new_visit_table_id)
                        ->when($hv2, function ($q) use ($hv2) {
                            $q->where('context', $hv2);
                        })
                        ->delete();

                foreach ($records as $r) {

                    $data = $r->toArray();
                    unset($data['id']);
                    unset($data['created_at']);
                    unset($data['updated_at']);
                    unset($data['closed_at']);
                    unset($data['approved_by']);
                    unset($data['investigation_request']);
                    unset($data['add_info']);
                    unset($data['is_approved']);
                    unset($data['is_abdm_approved']);

                    if (!empty($data['others'])) {
                        $othersArr = is_string($data['others']) ? json_decode($data['others'], true) : $data['others'];
                        if (is_array($othersArr)) {
                            unset($othersArr['investigations']);
                            unset($othersArr['investigation_free_box_cb']);
                            unset($othersArr['tooth_plan']);
                            $data['others'] = json_encode($othersArr);
                        }
                    }

                    $data['visit_id']         = $new_visit_table_id;
                    $data['context']          = $hv2 ?? $context;
                    $data['is_approved']      = 0;
                    $data['is_abdm_approved'] = 0;
                    $data['approved_by']      = null;
                    $data['closed_at']        = null;
                    $data['created_at']       = now();
                    $data['updated_at']       = now();
                    $data['created_by']       = auth()->user()->id ?? null;

                    $insertRows[] = $data;
                }

                if (count($insertRows) > 0) {
                    VisitClinicalData::insert($insertRows);
                }
            } else {
                $records = VisitClinicalData::where('visit_id', $old_visit_table_id)
                            ->when($context, function ($q) use ($context) {
                                $q->where('context', $context);
                            })
                            ->get();

                $insertRows = [];
                foreach ($records as $r) {
                    $data = $r->toArray();
                    unset($data['id']);
                    unset($data['created_at']);
                    unset($data['updated_at']);
                    unset($data['closed_at']);
                    unset($data['approved_by']);
                    unset($data['investigation_request']);
                    unset($data['add_info']);
                    unset($data['is_approved']);
                    unset($data['is_abdm_approved']);

                    if (!empty($data['others'])) {
                        $othersArr = is_string($data['others']) ? json_decode($data['others'], true) : $data['others'];
                        if (is_array($othersArr)) {
                            unset($othersArr['investigations']);
                            unset($othersArr['investigation_free_box_cb']);
                            unset($othersArr['tooth_plan']);
                            $data['others'] = json_encode($othersArr);
                        }
                    }

                    $data['visit_id']         = $new_visit_table_id;
                    $data['context']          = $data['context'] ?? $context;
                    $data['is_approved']      = 0;
                    $data['is_abdm_approved'] = 0;
                    $data['approved_by']      = null;
                    $data['closed_at']        = null;
                    $data['created_at']       = now();
                    $data['updated_at']       = now();
                    $data['created_by']       = auth()->user()->id ?? null;

                    $insertRows[] = $data;
                }

                if (count($insertRows) > 0) {
                    VisitClinicalData::insert($insertRows);
                }
            }
        }

        // 6. Vitals
        Vitals::where('visit_id', $new_visit_table_id)->delete();

        $a = Vitals::select('*')
                ->where('visit_id', $old_visit_table_id)
                ->get()
                ->toArray();

        foreach($a as $code){
            unset($code['id']);
            $code['visit_id'] = $new_visit_table_id;
            $code['created_at'] = now();
            $code['updated_at'] = now();
            $userId = auth()->user()->id ?? ($code['created_by'] ?? 1);
            $code['created_by'] = $userId;
            $code['updated_by'] = $userId;

            if (!empty($code['bp'])) {
                $bpArr = is_string($code['bp']) ? json_decode($code['bp'], true) : $code['bp'];
                if (is_array($bpArr)) {
                    foreach ($bpArr as &$item) {
                        if (is_array($item)) {
                            $item['created_at'] = now()->toISOString();
                            $item['created_by'] = auth()->user()->id ?? ($item['created_by'] ?? null);
                        }
                    }
                    $code['bp'] = json_encode($bpArr);
                }
            }

            if (!empty($code['pulse'])) {
                $pulseArr = is_string($code['pulse']) ? json_decode($code['pulse'], true) : $code['pulse'];
                if (is_array($pulseArr)) {
                    foreach ($pulseArr as &$item) {
                        if (is_array($item)) {
                            $item['created_at'] = now()->toISOString();
                            $item['created_by'] = auth()->user()->id ?? ($item['created_by'] ?? null);
                        }
                    }
                    $code['pulse'] = json_encode($pulseArr);
                }
            }

            Vitals::insert($code);
        }

        // 7. Other Diagnosis (Visit_other_diagnosis_v2)
        Visit_other_diagnosis_v2::where('visit_table_id', $new_visit_table_id)->delete();

        $a = Visit_other_diagnosis_v2::select('*')
                ->where('visit_table_id', $old_visit_table_id)
                ->get()
                ->toArray();

        foreach($a as $code){
            unset($code['id']);
            $code['visit_table_id'] = $new_visit_table_id;
            Visit_other_diagnosis_v2::insert($code);
        }

        // 8. Clinical History Comment Data
        Clinical_history_comment_data::where('visit_table_id', $new_visit_table_id)->delete();

        $ocd = Clinical_history_comment_data::select('*')
                ->where('visit_table_id', $old_visit_table_id)
                ->get()
                ->toArray();

        foreach($ocd as $oc){
            $b_id = $oc["cb_id"];
            $comment = $oc["comment"];

            $chcd = new Clinical_history_comment_data;
            $chcd->cb_id = $b_id;
            $chcd->final_box = $b_id;
            $chcd->comment = $comment;
            $chcd->type = 'comment_box';
            $chcd->visit_table_id = $new_visit_table_id;
            $chcd->visit_id = $oc['visit_id'] + 1;
            $chcd->hospital_id = $oc['hospital_id'];
            $chcd->patient_id = $oc['patient_id'];
            $chcd->doctor_id = $oc['doctor_id'];
            $chcd->final_box = $oc['final_box'];
            $chcd->save();
        }
    }


    private function create_opd_bill($visit_id,$reg_charge,$reg_discount,$reg_pay_type,$reg_pay_trans_id, $doctor_charge,$doc_discount,$doc_pay_type,$doc_pay_trans_id,$discount_auth_by){

            $user = Auth::user();
            $org_id = $user->org_id;

            $visit = Visitlog::join('pi','pi.id','=','visitlog.patient_id')
                        ->select('visitlog.patient_id', 'visitlog.doctor_id','visitlog.hospital_id','pi.i_cover','pi.is_registered')
                        ->where('visitlog.id',$visit_id)
                        ->first();


            if(($reg_charge != null) && ( $visit->is_registered != 1)){

                $payment_type = $reg_pay_type;
                $tr_id = $reg_pay_trans_id;
                $total_charges = $reg_charge - $reg_discount;

                $bill = new PatientBilling;
                $bill->doctor_id = $visit->doctor_id;
                $bill->patient_id = $visit->patient_id;
                $bill->hospital_id = $org_id;
                $bill->visit_id = $visit_id;
                $bill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($bill->visit_id);
                $bill->i_cover = $visit->i_cover;
                $bill->reg_charges = $reg_charge;
                $bill->discount = $reg_discount;
                $bill->subtotal = $reg_charge;
                $bill->total = $total_charges;
                $bill->bill_tag = "reg_fee";
                $bill->status = 1;
                $bill->created_by = auth()->user()->id;
                $bill->save();

                $paytype = new BillingPaymentType;
                $paytype->bill_id = $bill->id;
                $paytype->cash = ($payment_type == 'cash') ? $total_charges : 0;
                $paytype->upi =  ($payment_type == 'upi') ? $total_charges : 0;
                $paytype->debit_card =  ($payment_type == 'card') ? $total_charges : 0;
                $paytype->cash_transId =  ($payment_type == 'cash') ? $tr_id : '';
                $paytype->upi_transId = ($payment_type == 'upi') ? $tr_id : '';
                $paytype->debit_transId = ($payment_type == 'card') ? $tr_id : '';
                $paytype->credit_transId = '';
                $paytype->flag = "opd";
                $paytype->created_by = auth()->user()->id;
                $paytype->save();
            }


            $total_charges = $doctor_charge - $doc_discount;
            $payment_type = $doc_pay_type;
            $tr_id = $doc_pay_trans_id;

            $bill = new PatientBilling;
            $bill->doctor_id = $visit->doctor_id;
            $bill->patient_id = $visit->patient_id;
            $bill->hospital_id = $org_id;
            $bill->visit_id = $visit_id;
            $bill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($bill->visit_id);
            $bill->i_cover = $visit->i_cover;
            $bill->doc_charges = $doctor_charge;
            $bill->discount = $doc_discount;
            if($doc_discount)
                $bill->discount_auth_by = $discount_auth_by;

            $bill->subtotal = $doctor_charge;
            $bill->total =$total_charges;
            $bill->status = 1;
            $bill->bill_tag = "visit_fee";

            $bill->created_by = auth()->user()->id;
            $bill->save();

            $paytype = new BillingPaymentType;
            $paytype->bill_id = $bill->id;
            $paytype->cash = ($payment_type == 'cash') ? $total_charges : 0;
            $paytype->upi =  ($payment_type == 'upi') ? $total_charges : 0;
            $paytype->debit_card =  ($payment_type == 'card') ? $total_charges : 0;
            $paytype->cash_transId =  ($payment_type == 'cash') ? $tr_id : '';
            $paytype->upi_transId = ($payment_type == 'upi') ? $tr_id : '';
            $paytype->debit_transId = ($payment_type == 'card') ? $tr_id : '';
            $paytype->credit_transId = '';
            $paytype->flag = "opd";
            $paytype->created_by = auth()->user()->id;
            $paytype->save();

            Patient::where('id',$visit->patient_id)->update(['is_registered'=>1]);
    }


