    public function all_receipt_list(Request $request)
    {
        $activeTab = $request->input('tab', 'receipts_tab');
        $activeTab = $request->input('tab', 'receipts_tab');


        // Collections query
        $collectionsQuery = BillingPaymentType::leftJoin('patient_billing', 'patient_billing.id', '=', 'billing_payment_type.bill_id')
            ->leftJoin('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
            ->leftJoin('pi', 'visitlog.patient_id', '=', 'pi.id')
            ->leftJoin('doctor_db', 'visitlog.doctor_id', '=', 'doctor_db.id')
            ->leftJoin('users', 'users.id', '=', 'billing_payment_type.created_by')
            ->whereIn('visitlog.visit_status', [0, 1, 2])
            ->where('patient_billing.status', 1)
            ->where('billing_payment_type.transaction_type', 0);

        // Refunds query
        $refundsQuery = BillingPaymentType::leftJoin('patient_billing', 'patient_billing.id', '=', 'billing_payment_type.bill_id')
            ->leftJoin('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
            ->leftJoin('pi', 'visitlog.patient_id', '=', 'pi.id')
            ->leftJoin('doctor_db', 'visitlog.doctor_id', '=', 'doctor_db.id')
            ->leftJoin('users', 'users.id', '=', 'billing_payment_type.created_by')
            ->whereIn('visitlog.visit_status', [0, 1, 2])
            ->where('patient_billing.status', 1)
            ->where('billing_payment_type.transaction_type', 1);

        // Apply filters to Collections
        if ($activeTab === 'receipts_tab') {
            if ($request->filled('receipt_no')) {
                $collectionsQuery->where('billing_payment_type.id', $request->input('receipt_no'));
            } else {
                $startDate = $request->input('start_date');
                $endDate = $request->input('end_date');

                if (!$startDate && !$endDate && !$request->filled('patient_name') && !$request->filled('patient_id')) {
                    $startDate = date('Y-m-d');
                    $endDate = date('Y-m-d');
                }

                if ($startDate) {
                    $collectionsQuery->whereDate('billing_payment_type.created_at', '>=', $startDate);
                }
                if ($endDate) {
                    $collectionsQuery->whereDate('billing_payment_type.created_at', '<=', $endDate);
                }
            }

            if ($request->filled('patient_name')) {
                $collectionsQuery->whereRaw("CONCAT(pi.Fname, ' ', pi.Lname) LIKE ?", ['%' . $request->input('patient_name') . '%']);
            }

            if ($request->filled('patient_id')) {
                $collectionsQuery->where('pi.id', $request->input('patient_id'));
            }
        } else {
            // Default Collections to today if not the active tab
            $collectionsQuery->whereDate('billing_payment_type.created_at', '>=', date('Y-m-d'))
                             ->whereDate('billing_payment_type.created_at', '<=', date('Y-m-d'));
        }

        // Apply filters to Refunds
        if ($activeTab === 'refunds_tab') {
            if ($request->filled('receipt_no')) {
                $refundsQuery->where('billing_payment_type.id', $request->input('receipt_no'));
            } else {
                $startDate = $request->input('start_date');
                $endDate = $request->input('end_date');

                if (!$startDate && !$endDate && !$request->filled('patient_name') && !$request->filled('patient_id')) {
                    $startDate = date('Y-m-d');
                    $endDate = date('Y-m-d');
                }

                if ($startDate) {
                    $refundsQuery->whereDate('billing_payment_type.created_at', '>=', $startDate);
                }
                if ($endDate) {
                    $refundsQuery->whereDate('billing_payment_type.created_at', '<=', $endDate);
                }
            }

            if ($request->filled('patient_name')) {
                $refundsQuery->whereRaw("CONCAT(pi.Fname, ' ', pi.Lname) LIKE ?", ['%' . $request->input('patient_name') . '%']);
            }

            if ($request->filled('patient_id')) {
                $refundsQuery->where('pi.id', $request->input('patient_id'));
            }
        } else {
            // Default Refunds to today if not the active tab
            $refundsQuery->whereDate('billing_payment_type.created_at', '>=', date('Y-m-d'))
                         ->whereDate('billing_payment_type.created_at', '<=', date('Y-m-d'));
        }

        $collections = $collectionsQuery->select(
            'billing_payment_type.*',
            'billing_payment_type.bill_id as bill_id',
            'patient_billing.receipt_no',
            'patient_billing.is_locked as bill_is_locked',
            'patient_billing.is_settled as bill_is_settled',
            'pi.id as patient_id',
            'pi.hospital_id',
            'pi.Fname',
            'pi.age',
            'pi.sex',
            'pi.address',
            'pi.Lname',
            'pi.mobile_no',
            'doctor_db.name as doc_name',
            'visitlog.visit_status as visit_status',
            DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
        )->get();

        $refunds = $refundsQuery->select(
            'billing_payment_type.*',
            'billing_payment_type.bill_id as bill_id',
            'patient_billing.receipt_no',
            'patient_billing.is_locked as bill_is_locked',
            'patient_billing.is_settled as bill_is_settled',
            'pi.id as patient_id',
            'pi.hospital_id',
            'pi.Fname',
            'pi.age',
            'pi.sex',
            'pi.address',
            'pi.Lname',
            'pi.mobile_no',
            'doctor_db.name as doc_name',
            'visitlog.visit_status as visit_status',
            DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
        )->get();

        return view('admin.patient.billing.receipts_list', compact('collections', 'refunds'));
    }

    public function update_payment_receipt(Request $request)
    {
        $user = Auth::user();
        if (!$user->can('module-permission', ['opd_billing', 'can_update'])) {
            return response()->json([
                'status' => 'error',
                'message' => 'You do not have permission to edit receipts. Billing update permission is required.'
            ], 403);
        }

        $request->validate([
            'payment_id' => 'required|exists:billing_payment_type,id',
            'amount' => 'required|numeric|min:0',
            'payment_mode' => 'required|string',
        ]);

        try {
            \DB::beginTransaction();

            $payment = BillingPaymentType::findOrFail($request->payment_id);

            // Check if associated bill is locked, settled, or cancelled
            $bill = PatientBilling::find($payment->bill_id);
            if ($bill) {
                if ($bill->is_cancelled == 1) {
                    return response()->json([
                        'status' => 'error',
                        'message' => 'Receipts for cancelled bills cannot be modified.'
                    ], 422);
                }
                // Run autoLockIfExpired to ensure hour threshold-based locks are updated in DB
                $bill->autoLockIfExpired();
                if ($bill->is_locked == 1 || $bill->is_settled == 1) {
                    return response()->json([
                        'status' => 'error',
                        'message' => 'This bill is locked or settled and cannot be modified.'
                    ], 400);
                }
            }

            $payment->amount = $request->amount;
            $payment->payment_mode = $request->payment_mode;
            $payment->save();

            \DB::commit();

            return response()->json([
                'status' => 'success',
                'message' => 'Payment updated successfully'
            ]);
        } catch (\Exception $e) {
            \DB::rollBack();
            return response()->json([
                'status' => 'error',
                'message' => 'Failed to update payment: ' . $e->getMessage()
            ], 500);
        }
    }

