    public function all_bill_list_v1(Request $request)
    {
        $user = Auth::user();
        $others = json_decode($user->others??'{}',true);
        $restric_bills_list = $others['restric_bills_list']??false;

        $authUser = Auth::user();
        $isDoctor = $authUser && $authUser->is_doctor;
        $showAllBills = 0;
        $loginDoc = false;
        if ($isDoctor) {
            $doctorDoc = \App\Models\admin\HospitalDoctor::find($authUser->doctor_index_id);
            $docOthers = $doctorDoc ? json_decode($doctorDoc->others ?? '{}', true) : [];
            $showAllBills = $docOthers['show_all_bills'] ?? 0;
            $loginDoc = $doctorDoc->doc_id ?? false;
        }

        $bills = PatientBilling::join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                                ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
                                ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                ->leftJoin('users', 'users.id', '=', 'patient_billing.created_by')
                                ->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover')
                                ->leftJoin(
                                    DB::raw('(
                                        SELECT
                                            bill_id,
                                            SUM(amount) AS total_payment,
                                            GROUP_CONCAT(DISTINCT payment_mode ORDER BY payment_mode SEPARATOR ", ")
                                                AS payment_mode
                                        FROM billing_payment_type
                                        WHERE (is_deleted = 0 OR is_deleted IS NULL)
                                        GROUP BY bill_id
                                    ) as billing_totals'),
                                    'billing_totals.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->leftJoin(
                                        DB::raw('(
                                            SELECT bill_id, SUM(charges * qty - discount) AS subtotal,
                                            SUM(
                                                    (
                                                        (charges * qty - discount)
                                                        * (
                                                            IFNULL(cgst, 0)
                                                            + IFNULL(sgst, 0)
                                                            + IFNULL(igst, 0)
                                                        ) / 100
                                                    )
                                                ) AS total_tax
                                            FROM patient_gen_bill
                                            WHERE (is_cancelled != 1 OR is_cancelled IS NULL)
                                            AND (is_deleted != 1 OR is_deleted IS NULL)
                                            GROUP BY bill_id
                                        ) as gen_totals'),
                                        'gen_totals.bill_id',
                                        '=',
                                        'patient_billing.id'
                                    )
                                ->leftJoin(
                                    DB::raw("(
                                        SELECT bill_id,
                                            MAX(CASE WHEN is_cancelled = 1 THEN 1 ELSE 0 END) as has_cancelled
                                        FROM patient_gen_bill
                                        GROUP BY bill_id
                                    ) as cancelled_services"),
                                    'cancelled_services.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )

                                // ->leftJoin(
                                //     DB::raw("(SELECT DISTINCT bill_id FROM refund_remarks WHERE status = 'issued') as refunded_bills"),
                                //     'refunded_bills.bill_id',
                                //     '=',
                                //     'patient_billing.id'
                                // )

                                ->leftJoin(
                                        DB::raw("(SELECT id, bill_id, JSON_UNQUOTE(JSON_EXTRACT(bill_ref_id, '$[0]')) as ref_bill_id
                                                FROM refund_remarks
                                                WHERE status = 'issued') as refunded_bills"),
                                        'refunded_bills.bill_id',
                                        '=',
                                        'patient_billing.id'
                                    )
                                ->select(
                                    'pi.Fname', 'pi.Lname', 'pi.prefix', 'pi.sex', 'pi.age', 'pi.id as uhid',
                                    'doctor_db.name as doctor_name',
                                    'health_insurance_agen.insurance_agen',
                                    'patient_billing.id as bill_id',
                                    'patient_billing.*',
                                    'patient_billing.updated_at',
                                    'patient_billing.updated_by',
                                    'patient_billing.created_at',
                                    'visitlog.is_visited',
                                    'visitlog.emergency',
                                    'patient_billing.remarks',
                                    'billing_totals.payment_mode',
                                    DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
                                    DB::raw('gen_totals.subtotal - patient_billing.discount as total'),
                                    'billing_totals.total_payment as total_paid',
                                    'gen_totals.subtotal as subtotal',
                                    DB::raw('CASE WHEN refunded_bills.bill_id IS NOT NULL THEN 1 ELSE 0 END as is_refunded'),
                                    'refunded_bills.ref_bill_id' ,
                                    DB::raw('CASE
                                            WHEN cancelled_services.has_cancelled = 1
                                                AND (gen_totals.subtotal - patient_billing.discount) > 0
                                            THEN "Service Reversed"
                                            WHEN cancelled_services.has_cancelled = 1
                                                AND (gen_totals.subtotal - patient_billing.discount) = 0
                                            THEN "Fully Cancelled"
                                            ELSE ""
                                        END as cancel_status'),

                                    DB::raw('gen_totals.total_tax as total_tax'),

                                );

                            if ($isDoctor && !$showAllBills && $loginDoc) {
                                $bills->where('visitlog.doctor_id', $loginDoc);
                            }

                            // Filter logic
                            if ($request->bill_id) {
                                $bills->where('patient_billing.id', $request->bill_id);
                            } elseif ($request->start_date && $request->end_date) {
                                $bills->whereBetween(DB::raw('DATE(patient_billing.created_at)'), [$request->start_date, $request->end_date]);
                            } elseif ($request->status) {
                                $bills->where('patient_billing.status', $request->status);
                            } else {
                                $bills->whereBetween(DB::raw('DATE(patient_billing.created_at)'), [date('Y-m-d'), date('Y-m-d')]);
                            }

                            if ($request->patient_name) {
                                $bills->whereRaw("CONCAT(pi.Fname, ' ', pi.Lname) LIKE ?", ['%' . $request->patient_name . '%']);
                            }

                            if ($request->patient_id){
                                $bills->where('pi.id', $request->patient_id);
                            }

                            if ($restric_bills_list){
                                $bills->where('patient_billing.created_by', $user->id);
                            }

                            // Type specific filters
                            if ($request->type === 'cancelled') {
                                $bills->where('patient_billing.is_cancelled', 1);
                            } elseif ($request->type === 'pending') {
                                $bills->whereRaw('(gen_totals.subtotal - patient_billing.discount) - IFNULL(billing_totals.total_payment, 0) > 0');
                            } elseif ($request->type === 'refund') {
                                $bills->whereNotNull('refunded_bills.bill_id');
                            }

                            // Final conditions
                            $bills->where('visitlog.hospital_id', auth()->user()->org_id);

                            $bills->where('visitlog.visit_status',0);
                            $bills->orderBy('patient_billing.id', 'DESC');

                            $bills = $bills->get();


                    // Visit Breif

            // "All" = no condition
            $payTotals = BillingPaymentType::leftJoin('patient_billing','patient_billing.id','=','billing_payment_type.bill_id')
                ->select(
                'patient_billing.visit_id',
                DB::raw("SUM(CASE
                            WHEN billing_payment_type.transaction_type = 0 THEN billing_payment_type.amount
                            WHEN billing_payment_type.transaction_type = 1 THEN -billing_payment_type.amount
                            ELSE 0
                        END) AS payment_received")
                )
                // ->where('patient_billing.is_cancelled',0)->orWhereNull('patient_billing.is_cancelled')
                ->groupBy('patient_billing.visit_id');
                        $billWiseTotals = PatientGenBill::select(
                    'patient_billing.visit_id',
                    'patient_gen_bill.bill_id',
                    DB::raw("SUM(patient_gen_bill.charges * patient_gen_bill.qty) AS bill_subtotal"),
                    DB::raw("SUM(IFNULL(patient_gen_bill.discount, 0)) AS bill_row_discount"),
                    DB::raw("(
                        (SUM(patient_gen_bill.charges * patient_gen_bill.qty) - SUM(IFNULL(patient_gen_bill.discount, 0)))
                        * (patient_billing.discount / NULLIF(SUM(patient_gen_bill.charges * patient_gen_bill.qty - IFNULL(patient_gen_bill.discount, 0) ), 0))
                    ) AS bill_level_discount"),

                )
                ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                ->where(function ($q) {
                    $q->where('patient_gen_bill.is_cancelled', 0)
                    ->orWhereNull('patient_gen_bill.is_cancelled');
                })
                ->where(function ($q) {
                    $q->where('patient_gen_bill.is_deleted', 0)
                    ->orWhereNull('patient_gen_bill.is_deleted');
                })
                ->where(function ($q) {
                    $q->where('patient_billing.is_cancelled', 0)
                    ->orWhereNull('patient_billing.is_cancelled');
                })
                ->groupBy('patient_billing.visit_id','patient_gen_bill.bill_id');

                    $subTotals = DB::table(DB::raw("({$billWiseTotals->toSql()}) as bill_totals"))
                    ->mergeBindings($billWiseTotals->getQuery()) // keep bindings
                    ->select(
                        'bill_totals.visit_id',
                        DB::raw("SUM(bill_totals.bill_subtotal) AS subtotal"),
                        DB::raw("SUM(bill_totals.bill_row_discount) AS total_row_discount"),
                        DB::raw("SUM(bill_totals.bill_level_discount) AS total_bill_discount"),
                        DB::raw("(SUM(bill_totals.bill_subtotal) - SUM(bill_totals.bill_row_discount) - SUM(bill_totals.bill_level_discount)) AS net_amount")
                    )
                    ->groupBy('bill_totals.visit_id');
        $investigationQuery = PatientGenBill::leftJoin('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
            ->leftJoin('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
            ->leftJoin('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
            ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
            ->leftJoin('pi','visitlog.patient_id', '=', 'pi.id')
            ->leftJoin('users as u','u.id','=','patient_gen_bill.created_by')
            ->leftJoin('users as discount_by','discount_by.id','=','patient_billing.discount_auth_by')
            ->leftJoin('doctor_db', 'visitlog.doctor_id', '=', 'doctor_db.id')
            ->leftJoinSub($subTotals, 'subtotals', function($join){
                $join->on('subtotals.visit_id','=','visitlog.id');
            })
            ->leftJoinSub($payTotals, 'paytotals', function($join){
                $join->on('paytotals.visit_id','=','visitlog.id');
            });

        if ($isDoctor && !$showAllBills && $loginDoc) {
            $investigationQuery->where('visitlog.doctor_id', $loginDoc);
        }

        $investigationQuery->whereIn('patient_billing.status',[1]);
        $investigationQuery->where(function ($query) {
            $query->where('patient_gen_bill.is_cancelled',0)->orWhereNull('patient_gen_bill.is_cancelled');
        });
        $investigationQuery->where(function ($query) {
            $query->where('patient_gen_bill.is_deleted',0)->orWhereNull('patient_gen_bill.is_deleted');
        });
        $investigationQuery->where(function ($query) {
            $query->where('patient_billing.is_cancelled',0)->orWhereNull('patient_gen_bill.is_cancelled');
        });
        // Grouping and pivoted select
        $investigationQuery->groupBy('visitlog.id')
            ->select(
                'visitlog.id as visit_id',
                'pi.id as patient_id',
                'pi.hospital_id',
                'pi.Fname',
                'pi.Lname',
                'pi.mobile_no',
                'doctor_db.name as doc_name',
                DB::raw('SUM(patient_gen_bill.charges * patient_gen_bill.qty - patient_gen_bill.discount) as gross_amount'),

                // amounts
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'registration_charge' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as registration_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'consultation_charge' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as consultation_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'test' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as test_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'radiology' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as radiology_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'procedure' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as procedure_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'admission_charge' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as admission_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'doctor_consultation' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as visit_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'room' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as room_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'package' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as package_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'nursing_charges' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as nursing_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'miscellaneous' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as other_amt"),


                // totals
                DB::raw("(subtotals.subtotal) as subtotal"),
                DB::raw("(subtotals.total_bill_discount) as total_discount"),
                DB::raw("(subtotals.net_amount) as net_amount"),
                DB::raw("(paytotals.payment_received) as total_paid"),

                DB::raw("SUM(((patient_gen_bill.charges * patient_gen_bill.qty) - IFNULL(patient_gen_bill.discount, 0)) - (((patient_gen_bill.charges * patient_gen_bill.qty) - IFNULL(patient_gen_bill.discount, 0)) * (patient_billing.discount / NULLIF(subtotals.subtotal, 0)))) as total_collection")
            );
            // Patient Name
            if ($request->patient_name) {
                $investigationQuery->whereRaw(
                    "CONCAT(pi.Fname, ' ', pi.Lname) LIKE ?",
                    ['%' . $request->patient_name . '%']
                );
            }

            // UHID
            if ($request->patient_id) {
                $investigationQuery->where('pi.id', $request->patient_id);
            }

            // Type Filter
            if ($request->type === 'pending') {
                $investigationQuery->havingRaw('(paytotals.payment_received - subtotals.net_amount) < 0');

            } elseif ($request->type === 'excess') {
                $investigationQuery->havingRaw('(paytotals.payment_received - subtotals.net_amount) > 0');
            }

            // DATE FILTER (FIXED)
            if (!$request->start_date && !$request->end_date) {
                $investigationQuery->whereDate('patient_gen_bill.created_at', now());
            } else {
                $investigationQuery->whereBetween(
                    DB::raw('DATE(patient_gen_bill.created_at)'),
                    [$request->start_date, $request->end_date]
                );
            }

            // FINAL EXECUTION (IMPORTANT)
            $records = $investigationQuery
                        ->orderBy('visitlog.id','DESC')
                        ->get();
            $type = $request->type ?? 'all';

                    // End Vist Breif
                    $activeTab = $request->tab ?? 'bill_list';


                    // return $bills;

        return view('admin.patient.billing.bills_list_v1' , compact('bills', 'records', 'activeTab'));
    }



    public function all_bill_list_v2(Request $request){
        $user = Auth::user();
        $others = json_decode($user->others??'{}',true);
        $restric_bills_list = $others['restric_bills_list']??false;

        $authUser = Auth::user();
        $isDoctor = $authUser && $authUser->is_doctor;
        $showAllBills = 0;
        $loginDoc = false;
        if ($isDoctor) {
            $doctorDoc = \App\Models\admin\HospitalDoctor::find($authUser->doctor_index_id);
            $docOthers = $doctorDoc ? json_decode($doctorDoc->others ?? '{}', true) : [];
            $showAllBills = $docOthers['show_all_bills'] ?? 0;
            $loginDoc = $doctorDoc->doc_id ?? false;
        }




        $activeTab = $request->tab ?? 'bill_list';




        if ($request->filled('start_date') && $request->filled('end_date')) {

            $dateError = $this->dateRangeLimit->getError(
                $request->start_date,
                $request->end_date,
                $user->org_id
            );



            if ($dateError) {
                return view(
                    'admin.patient.billing.bills_list_v2', compact('activeTab')
                )->with('dateRangeError', $dateError);
            }
        }





        $bills = PatientBilling::query()
                    ->join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                    ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
                    ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                    ->leftJoin('users', 'users.id', '=', 'patient_billing.created_by')
                    ->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover')
                    ->leftJoin('patient_care_contexts as pcc', function ($join) {
                        $join->on('pcc.bill_id', '=', 'patient_billing.id')
                             ->where('pcc.is_active', 1);
                    })

                    /*
                    |--------------------------------------------------------------------------
                    | PAYMENT TOTALS
                    |--------------------------------------------------------------------------
                    */
                    ->leftJoin(
                        DB::raw('(
                            SELECT
                                bill_id,
                                SUM(amount) AS total_payment,
                                GROUP_CONCAT(DISTINCT payment_mode ORDER BY payment_mode SEPARATOR ", ") AS payment_mode
                            FROM billing_payment_type
                            WHERE (is_deleted = 0 OR is_deleted IS NULL)
                            GROUP BY bill_id
                        ) as billing_totals'),
                        'billing_totals.bill_id',
                        '=',
                        'patient_billing.id'
                    )

                    /*
                    |--------------------------------------------------------------------------
                    | BILL SUBTOTAL
                    |--------------------------------------------------------------------------
                    */
                    ->leftJoin(
                        DB::raw('(
                            SELECT
                                bill_id,
                                SUM((charges * qty) - discount) AS subtotal
                            FROM patient_gen_bill
                            WHERE (is_cancelled != 1 OR is_cancelled IS NULL)
                            AND (is_deleted != 1 OR is_deleted IS NULL)
                            GROUP BY bill_id
                        ) as gen_totals'),
                        'gen_totals.bill_id',
                        '=',
                        'patient_billing.id'
                    )

                    /*
                    |--------------------------------------------------------------------------
                    | CANCELLED SERVICES
                    |--------------------------------------------------------------------------
                    */
                    ->leftJoin(
                        DB::raw('(
                            SELECT
                                bill_id,
                                MAX(CASE WHEN is_cancelled = 1 THEN 1 ELSE 0 END) as has_cancelled
                            FROM patient_gen_bill
                            GROUP BY bill_id
                        ) as cancelled_services'),
                        'cancelled_services.bill_id',
                        '=',
                        'patient_billing.id'
                    )

                    /*
                    |--------------------------------------------------------------------------
                    | SETTLEMENT TOTALS
                    |--------------------------------------------------------------------------
                    */
                    ->leftJoin(
                        DB::raw('(
                            SELECT
                                br.bill_id,
                                SUM(IFNULL(bpt.amount,0)) as settlement_amount
                            FROM bill_reference br
                            JOIN billing_payment_type bpt
                                ON bpt.bill_id = br.ref_bill
                            WHERE (bpt.is_deleted = 0 OR bpt.is_deleted IS NULL)
                            GROUP BY br.bill_id
                        ) as settlement_totals'),
                        'settlement_totals.bill_id',
                        '=',
                        'patient_billing.id'
                    )

                    /*
                    |--------------------------------------------------------------------------
                    | REFUND TOTALS
                    |--------------------------------------------------------------------------
                    */
                    ->leftJoin(
                        DB::raw("(
                            SELECT
                                JSON_UNQUOTE(JSON_EXTRACT(rr.bill_ref_id, '$[0]')) as original_bill_id,
                                SUM(IFNULL(bpt.amount,0)) as refund_amount
                            FROM refund_remarks rr

                            JOIN billing_payment_type bpt
                                ON bpt.bill_id = rr.bill_id

                            WHERE rr.status = 'issued'
                            AND (bpt.is_deleted = 0 OR bpt.is_deleted IS NULL)

                            GROUP BY original_bill_id
                        ) as refund_totals"),
                        'refund_totals.original_bill_id',
                        '=',
                        'patient_billing.id'
                    )

                    /*
                    |--------------------------------------------------------------------------
                    | REFUND STATUS
                    |--------------------------------------------------------------------------
                    */
                    ->leftJoin(
                        DB::raw("(SELECT
                                    id,
                                    bill_id,
                                    JSON_UNQUOTE(JSON_EXTRACT(bill_ref_id, '$[0]')) as ref_bill_id
                                FROM refund_remarks
                                WHERE status = 'issued'
                            ) as refunded_bills"),
                        'refunded_bills.bill_id',
                        '=',
                        'patient_billing.id'
                    )
                    /*
                    |--------------------------------------------------------------------------
                    | BILL EVENTS JSON
                    |--------------------------------------------------------------------------
                    */
                    ->leftJoin(
                        DB::raw("
                        (
                            SELECT
                                events.bill_id,

                                JSON_ARRAYAGG(
                                    JSON_OBJECT(
                                        'event_type', events.event_type,
                                        'transaction_type', events.transaction_type,
                                        'payment_id', events.payment_id,
                                        'payment_mode', events.payment_mode,
                                        'amount', events.amount,
                                        'timestamp', events.created_at
                                    )
                                ) as bill_events

                            FROM
                            (

                                /*
                                |--------------------------------------------------------------------------
                                | DIRECT COLLECTION EVENTS
                                |--------------------------------------------------------------------------
                                */
                                SELECT

                                    bpt.bill_id,

                                    'PAYMENT' as event_type,

                                    bpt.transaction_type,

                                    bpt.id as payment_id,

                                    bpt.payment_mode,

                                    bpt.amount,

                                    bpt.created_at

                                FROM billing_payment_type bpt

                                WHERE (bpt.is_deleted = 0 OR bpt.is_deleted IS NULL)
                                AND IFNULL(bpt.amount,0) > 0

                                AND NOT EXISTS (
                                    SELECT 1
                                    FROM bill_reference br
                                    WHERE br.ref_bill = bpt.bill_id
                                )

                                AND NOT EXISTS (
                                    SELECT 1
                                    FROM refund_remarks rr
                                    WHERE rr.bill_id = bpt.bill_id
                                    AND rr.status = 'issued'
                                )



                                UNION ALL



                                /*
                                |--------------------------------------------------------------------------
                                | SETTLEMENT EVENTS
                                |--------------------------------------------------------------------------
                                */
                                SELECT

                                    br.bill_id,

                                    'SETTLEMENT' as event_type,

                                    bpt.transaction_type,

                                    bpt.id as payment_id,

                                    bpt.payment_mode,

                                    bpt.amount,

                                    bpt.created_at

                                FROM bill_reference br

                                JOIN billing_payment_type bpt
                                    ON bpt.bill_id = br.ref_bill

                                WHERE (bpt.is_deleted = 0 OR bpt.is_deleted IS NULL)
                                AND IFNULL(bpt.amount,0) > 0



                                UNION ALL



                                /*
                                |--------------------------------------------------------------------------
                                | REFUND EVENTS
                                |--------------------------------------------------------------------------
                                */
                                SELECT

                                    JSON_UNQUOTE(JSON_EXTRACT(rr.bill_ref_id, '$[0]')) as bill_id,

                                    'REFUND' as event_type,

                                    bpt.transaction_type,

                                    bpt.id as payment_id,

                                    bpt.payment_mode,

                                    bpt.amount,

                                    bpt.created_at

                                FROM refund_remarks rr

                                JOIN billing_payment_type bpt
                                    ON bpt.bill_id = rr.bill_id

                                WHERE rr.status = 'issued'
                                AND (bpt.is_deleted = 0 OR bpt.is_deleted IS NULL)
                                AND IFNULL(bpt.amount,0) > 0

                            ) events

                            GROUP BY events.bill_id

                        ) as bill_events_json
                        "),
                        'bill_events_json.bill_id',
                        '=',
                        'patient_billing.id'
                    )

                    /*
                    |--------------------------------------------------------------------------
                    | SELECTS
                    |--------------------------------------------------------------------------
                    */
                    ->select(
                        'pi.Fname',
                        'pi.Lname',
                        'pi.prefix',
                        'pi.sex',
                        'pi.age',
                        'pi.id as uhid',

                        'doctor_db.name as doctor_name',
                        'health_insurance_agen.insurance_agen',

                        'visitlog.visit_status',
                        'visitlog.id as visit_id',
                        'pi.mobile_no',
                        'pi.abha_address',
                        'pi.abha_add',

                        'patient_billing.id as bill_id',
                        'patient_billing.*',
                        'patient_billing.is_abdm_approved',
                        'pcc.linking_status as abdm_linking_status',
                        'pcc.care_context_reference as abdm_care_context_ref',

                        'patient_billing.updated_at',
                        'patient_billing.updated_by',
                        'patient_billing.created_at',

                        'visitlog.is_visited',

                        'patient_billing.remarks',

                        'billing_totals.payment_mode',

                        DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),

                        DB::raw('
                            (
                                IFNULL(gen_totals.subtotal,0)
                                - IFNULL(patient_billing.discount,0)
                            ) as total
                        '),

                        DB::raw('
                            (
                                IFNULL(billing_totals.total_payment,0)
                                + IFNULL(settlement_totals.settlement_amount,0)
                                - IFNULL(refund_totals.refund_amount,0)
                            ) as total_paid
                        '),

                        'gen_totals.subtotal as subtotal',

                        DB::raw('
                            CASE
                                WHEN refunded_bills.bill_id IS NOT NULL
                                THEN 1
                                ELSE 0
                            END as is_refunded
                        '),

                        'refunded_bills.ref_bill_id',

                        DB::raw('
                            CASE
                                WHEN cancelled_services.has_cancelled = 1
                                    AND (gen_totals.subtotal - patient_billing.discount) > 0
                                THEN "Service Reversed"

                                WHEN cancelled_services.has_cancelled = 1
                                    AND (gen_totals.subtotal - patient_billing.discount) = 0
                                THEN "Fully Cancelled"

                                ELSE ""
                            END as cancel_status
                        '),
                        'bill_events_json.bill_events',
                    )

                    /*
                    |--------------------------------------------------------------------------
                    | REMOVE SETTLEMENT CHILD BILLS
                    |--------------------------------------------------------------------------
                    */
                    ->whereNotIn('patient_billing.id', function ($q) {
                        $q->select('ref_bill')
                            ->from('bill_reference');
                    })

                    /*
                    |--------------------------------------------------------------------------
                    | REMOVE REFUND CHILD BILLS
                    |--------------------------------------------------------------------------
                    */
                    ->whereNotIn('patient_billing.id', function ($q) {
                        $q->select('bill_id')
                            ->from('refund_remarks')
                            ->where('status', 'issued');
                    })

                    /*
                    |--------------------------------------------------------------------------
                    | FILTERS
                    |--------------------------------------------------------------------------
                    */
                    ->where('visitlog.hospital_id', auth()->user()->org_id)
                    ->where('visitlog.visit_status', 0);

        if ($isDoctor && !$showAllBills && $loginDoc) {
            $bills->where('visitlog.doctor_id', $loginDoc);
        }




                /*
                |--------------------------------------------------------------------------
                | FILTER LOGIC
                |--------------------------------------------------------------------------
                */

                if ($request->bill_id) {

                    $bills->where('patient_billing.id', $request->bill_id);

                } elseif ($request->start_date && $request->end_date) {

                    $bills->whereBetween(
                        DB::raw('DATE(patient_billing.created_at)'),
                        [$request->start_date, $request->end_date]
                    );

                } elseif ($request->status) {

                    $bills->where('patient_billing.status', $request->status);

                } else {

                    $bills->whereBetween(
                        DB::raw('DATE(patient_billing.created_at)'),
                        [date('Y-m-d'), date('Y-m-d')]
                    );
                }


                if ($request->patient_name) {

                    $bills->whereRaw(
                        "CONCAT(pi.Fname, ' ', pi.Lname) LIKE ?",
                        ['%' . $request->patient_name . '%']
                    );
                }


                if ($request->patient_id) {

                    $bills->where('pi.id', $request->patient_id);
                }


                if ($restric_bills_list) {

                    $bills->where('patient_billing.created_by', $user->id);
                }


                /*
                |--------------------------------------------------------------------------
                | TYPE FILTERS
                |--------------------------------------------------------------------------
                */

                if ($request->type === 'cancelled') {

                    $bills->where('patient_billing.is_cancelled', 1);

                } elseif ($request->type === 'pending') {

                    $bills->whereRaw('
                        (
                            (
                                IFNULL(gen_totals.subtotal,0)
                                - IFNULL(patient_billing.discount,0)
                            )
                            -
                            (
                                IFNULL(billing_totals.total_payment,0)
                                + IFNULL(settlement_totals.settlement_amount,0)
                                - IFNULL(refund_totals.refund_amount,0)
                            )
                        ) > 0
                    ');

                } elseif ($request->type === 'refund') {

                    $bills->whereNotNull('refunded_bills.bill_id');
                }


                /*
                |--------------------------------------------------------------------------
                | ORDER + PAGINATION
                |--------------------------------------------------------------------------
                */

                $bills = $bills
                    ->orderByDesc('patient_billing.id')
                    ->paginate(20)->withQueryString();



                // Visit Breif

                  // "All" = no condition
                    $payTotals = BillingPaymentType::leftJoin('patient_billing','patient_billing.id','=','billing_payment_type.bill_id')
                        ->select(
                            'patient_billing.visit_id',
                            DB::raw("SUM(CASE
                                        WHEN billing_payment_type.transaction_type = 0 THEN billing_payment_type.amount
                                        WHEN billing_payment_type.transaction_type = 1 THEN -billing_payment_type.amount
                                        ELSE 0
                                    END) AS payment_received")
                        )
                        // ->where('patient_billing.is_cancelled',0)->orWhereNull('patient_billing.is_cancelled')
                        ->groupBy('patient_billing.visit_id');
                                $billWiseTotals = PatientGenBill::select(
                            'patient_billing.visit_id',
                            'patient_gen_bill.bill_id',
                            DB::raw("SUM(patient_gen_bill.charges * patient_gen_bill.qty) AS bill_subtotal"),
                            DB::raw("SUM(IFNULL(patient_gen_bill.discount, 0)) AS bill_row_discount"),
                            DB::raw("(
                                (SUM(patient_gen_bill.charges * patient_gen_bill.qty) - SUM(IFNULL(patient_gen_bill.discount, 0)))
                                * (patient_billing.discount / NULLIF(SUM(patient_gen_bill.charges * patient_gen_bill.qty - IFNULL(patient_gen_bill.discount, 0) ), 0))
                            ) AS bill_level_discount")
                        )
                        ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                        ->where(function ($q) {
                            $q->where('patient_gen_bill.is_cancelled', 0)
                            ->orWhereNull('patient_gen_bill.is_cancelled');
                        })
                        ->where(function ($q) {
                            $q->where('patient_gen_bill.is_deleted', 0)
                            ->orWhereNull('patient_gen_bill.is_deleted');
                        })
                        ->where(function ($q) {
                            $q->where('patient_billing.is_cancelled', 0)
                            ->orWhereNull('patient_billing.is_cancelled');
                        })
                        ->groupBy('patient_billing.visit_id','patient_gen_bill.bill_id');

            $subTotals = DB::table(DB::raw("({$billWiseTotals->toSql()}) as bill_totals"))
                    ->mergeBindings($billWiseTotals->getQuery()) // keep bindings
                    ->select(
                        'bill_totals.visit_id',
                        DB::raw("SUM(bill_totals.bill_subtotal) AS subtotal"),
                        DB::raw("SUM(bill_totals.bill_row_discount) AS total_row_discount"),
                        DB::raw("SUM(bill_totals.bill_level_discount) AS total_bill_discount"),
                        DB::raw("(SUM(bill_totals.bill_subtotal) - SUM(bill_totals.bill_row_discount) - SUM(bill_totals.bill_level_discount)) AS net_amount")
                    )
                    ->groupBy('bill_totals.visit_id');


        $investigationQuery = PatientGenBill::leftJoin('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
            ->leftJoin('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
            ->leftJoin('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
            ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
            ->leftJoin('pi','visitlog.patient_id', '=', 'pi.id')
            ->leftJoin('users as u','u.id','=','patient_gen_bill.created_by')
            ->leftJoin('users as discount_by','discount_by.id','=','patient_billing.discount_auth_by')
            ->leftJoin('doctor_db', 'visitlog.doctor_id', '=', 'doctor_db.id')
            ->leftJoinSub($subTotals, 'subtotals', function($join){
                $join->on('subtotals.visit_id','=','visitlog.id');
            })
            ->leftJoinSub($payTotals, 'paytotals', function($join){
                $join->on('paytotals.visit_id','=','visitlog.id');
            });

        if ($isDoctor && !$showAllBills && $loginDoc) {
            $investigationQuery->where('visitlog.doctor_id', $loginDoc);
        }

        $investigationQuery->whereIn('patient_billing.status',[1]);
        $investigationQuery->where(function ($query) {
            $query->where('patient_gen_bill.is_cancelled',0)->orWhereNull('patient_gen_bill.is_cancelled');
        });
        $investigationQuery->where(function ($query) {
            $query->where('patient_gen_bill.is_deleted',0)->orWhereNull('patient_gen_bill.is_deleted');
        });
        $investigationQuery->where(function ($query) {
            $query->where('patient_billing.is_cancelled',0)->orWhereNull('patient_gen_bill.is_cancelled');
        });
        // Grouping and pivoted select
        $investigationQuery->groupBy('visitlog.id')
            ->select(
                'visitlog.id as visit_id',
                'pi.id as patient_id',
                'pi.hospital_id',
                'pi.Fname',
                'pi.Lname',
                'pi.mobile_no',
                'doctor_db.name as doc_name',
                DB::raw('SUM(patient_gen_bill.charges * patient_gen_bill.qty - patient_gen_bill.discount) as gross_amount'),

                // amounts
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'registration_charge' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as registration_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'consultation_charge' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as consultation_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'test' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as test_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'radiology' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as radiology_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'procedure' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as procedure_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'admission_charge' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as admission_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'doctor_consultation' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as visit_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'room' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as room_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'package' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as package_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'nursing_charges' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as nursing_amt"),
                DB::raw("SUM(CASE WHEN hospital_services.flag = 'miscellaneous' THEN ((patient_gen_bill.charges * patient_gen_bill.qty)) ELSE 0 END) as other_amt"),


                // totals
                DB::raw("(subtotals.subtotal) as subtotal"),
                DB::raw("(subtotals.total_bill_discount) as total_discount"),
                DB::raw("(subtotals.net_amount) as net_amount"),
                DB::raw("(paytotals.payment_received) as total_paid"),

                DB::raw("SUM(((patient_gen_bill.charges * patient_gen_bill.qty) - IFNULL(patient_gen_bill.discount, 0)) - (((patient_gen_bill.charges * patient_gen_bill.qty) - IFNULL(patient_gen_bill.discount, 0)) * (patient_billing.discount / NULLIF(subtotals.subtotal, 0)))) as total_collection")
            );
        // Patient Name
        if ($request->patient_name) {
            $investigationQuery->whereRaw(
                "CONCAT(pi.Fname, ' ', pi.Lname) LIKE ?",
                ['%' . $request->patient_name . '%']
            );
        }

        // UHID
        if ($request->patient_id) {
            $investigationQuery->where('pi.id', $request->patient_id);
        }

        // Type Filter
        if ($request->type === 'pending') {
            $investigationQuery->havingRaw('(paytotals.payment_received - subtotals.net_amount) < 0');

        } elseif ($request->type === 'excess') {
            $investigationQuery->havingRaw('(paytotals.payment_received - subtotals.net_amount) > 0');
        }

        // DATE FILTER (FIXED)
        if (!$request->start_date && !$request->end_date) {
            $investigationQuery->whereDate('patient_gen_bill.created_at', now());
        } else {
            $investigationQuery->whereBetween(
                DB::raw('DATE(patient_gen_bill.created_at)'),
                [$request->start_date, $request->end_date]
            );
        }

        // FINAL EXECUTION (IMPORTANT)
        $records = $investigationQuery
                    ->orderBy('visitlog.id','DESC')
                    ->get();
        $type = $request->type ?? 'all';

        // End Vist Breif


        // Collections query
        $collectionsQuery = BillingPaymentType::leftJoin('patient_billing', 'patient_billing.id', '=', 'billing_payment_type.bill_id')
            ->leftJoin('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
            ->leftJoin('pi', 'visitlog.patient_id', '=', 'pi.id')
            ->leftJoin('doctor_db', 'visitlog.doctor_id', '=', 'doctor_db.id')
            ->leftJoin('users', 'users.id', '=', 'billing_payment_type.created_by')
            ->whereIn('visitlog.visit_status', [0])
            ->where('patient_billing.status', 1)
            ->where('billing_payment_type.transaction_type', 0);

        // Refunds query
        $refundsQuery = BillingPaymentType::leftJoin('patient_billing', 'patient_billing.id', '=', 'billing_payment_type.bill_id')
            ->leftJoin('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
            ->leftJoin('pi', 'visitlog.patient_id', '=', 'pi.id')
            ->leftJoin('doctor_db', 'visitlog.doctor_id', '=', 'doctor_db.id')
            ->leftJoin('users', 'users.id', '=', 'billing_payment_type.created_by')
            ->whereIn('visitlog.visit_status', [0])
            ->where('patient_billing.status', 1)
            ->where('billing_payment_type.transaction_type', 1);

        // Apply filters to Collections
        if ($activeTab === 'receipts_tab') {
            if ($request->filled('receipt_no')) {
                $collectionsQuery->where('billing_payment_type.id', $request->input('receipt_no'));
            } else {
                $startDate = $request->input('start_date');
                $endDate = $request->input('end_date');

                if (!$startDate && !$endDate && !$request->filled('patient_name') && !$request->filled('patient_id')) {
                    $startDate = date('Y-m-d');
                    $endDate = date('Y-m-d');
                }

                if ($startDate) {
                    $collectionsQuery->whereDate('billing_payment_type.created_at', '>=', $startDate);
                }
                if ($endDate) {
                    $collectionsQuery->whereDate('billing_payment_type.created_at', '<=', $endDate);
                }
            }

            if ($request->filled('patient_name')) {
                $collectionsQuery->whereRaw("CONCAT(pi.Fname, ' ', pi.Lname) LIKE ?", ['%' . $request->input('patient_name') . '%']);
            }

            if ($request->filled('patient_id')) {
                $collectionsQuery->where('pi.id', $request->input('patient_id'));
            }
        } else {
            // Default Collections to today if not the active tab
            $collectionsQuery->whereDate('billing_payment_type.created_at', '>=', date('Y-m-d'))
                             ->whereDate('billing_payment_type.created_at', '<=', date('Y-m-d'));
        }

        // Apply filters to Refunds
        if ($activeTab === 'refunds_tab') {
            if ($request->filled('receipt_no')) {
                $refundsQuery->where('billing_payment_type.id', $request->input('receipt_no'));
            } else {
                $startDate = $request->input('start_date');
                $endDate = $request->input('end_date');

                if (!$startDate && !$endDate && !$request->filled('patient_name') && !$request->filled('patient_id')) {
                    $startDate = date('Y-m-d');
                    $endDate = date('Y-m-d');
                }

                if ($startDate) {
                    $refundsQuery->whereDate('billing_payment_type.created_at', '>=', $startDate);
                }
                if ($endDate) {
                    $refundsQuery->whereDate('billing_payment_type.created_at', '<=', $endDate);
                }
            }

            if ($request->filled('patient_name')) {
                $refundsQuery->whereRaw("CONCAT(pi.Fname, ' ', pi.Lname) LIKE ?", ['%' . $request->input('patient_name') . '%']);
            }

            if ($request->filled('patient_id')) {
                $refundsQuery->where('pi.id', $request->input('patient_id'));
            }
        } else {
            // Default Refunds to today if not the active tab
            $refundsQuery->whereDate('billing_payment_type.created_at', '>=', date('Y-m-d'))
                         ->whereDate('billing_payment_type.created_at', '<=', date('Y-m-d'));
        }

        $collections = $collectionsQuery->select(
            'billing_payment_type.*',
            'billing_payment_type.bill_id as bill_id',
            'patient_billing.receipt_no',
            'patient_billing.is_locked as bill_is_locked',
            'patient_billing.is_settled as bill_is_settled',
            'pi.id as patient_id',
            'pi.hospital_id',
            'pi.Fname',
            'pi.age',
            'pi.sex',
            'pi.address',
            'pi.Lname',
            'pi.mobile_no',
            'doctor_db.name as doc_name',
            'visitlog.visit_status as visit_status',
            DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
        )->get();

        $refunds = $refundsQuery->select(
            'billing_payment_type.*',
            'billing_payment_type.bill_id as bill_id',
            'patient_billing.receipt_no',
            'patient_billing.is_locked as bill_is_locked',
            'patient_billing.is_settled as bill_is_settled',
            'pi.id as patient_id',
            'pi.hospital_id',
            'pi.Fname',
            'pi.age',
            'pi.sex',
            'pi.address',
            'pi.Lname',
            'pi.mobile_no',
            'doctor_db.name as doc_name',
            'visitlog.visit_status as visit_status',
            DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
        )->get();



        return view('admin.patient.billing.bills_list_v2' , compact('bills', 'records', 'activeTab','collections','refunds'));
    }


    public function mark_bills_cancel(Request $request){
        $billIds = array_values($request->order_id);

        // Or if you want to be extra safe:
        $billIds = array_map('intval', $billIds);

        DB::table('patient_billing')
            ->whereIn('id', $billIds)
            ->update([
                'is_cancelled' => '1',
                'updated_by' => Auth()->user()->id,
            ]);

         DB::table('patient_gen_bill')
            ->whereIn('bill_id', $billIds)
            ->update([
                'is_cancelled' => '1',
                'cancelled_at' => now(),
                'cancelled_by' =>  Auth()->user()->id,
                'updated_by' => Auth()->user()->id,
            ]);


          return redirect()->back()->with('success','Cancelled Successfully.');


    }

