    public function update_fud(Request $request, $visit_id){
        $user = Auth::user();
        $org_id = $user->org_id;


        $fud = $request->next_visit_date;
        $advice = $request->follow_up_type;
        $remarks = $request->remarks ?? '';


        $visit = Visitlog::where('id', $visit_id)->first();
        if($visit){

            if($advice =='next_visit'){
                $visit->fud = $fud;
                $visit->advice = $advice;
            }else{
                $visit->advice = $advice;
                $visit->remarks = $remarks;
            }


            $visit->save();
            return response()->json(['status'=>'success','message'=>'Follow up Date updated successfully']);
        }else{
            return response()->json(['status'=>'error','message'=>'Visit not found']);
        }
    }

     public function update_fud_v2(Request $request, $visit_id){
        $user = Auth::user();
        $org_id = $user->org_id;


        $fud = $request->next_visit_date;
        // $advice = $request->follow_up_type;
        // $remarks = $request->remarks ?? '';


        $visit = Visitlog::where('id', $visit_id)->first();
        if($visit){
            $visit->fud = $fud;
            $visit->save();

            $patient = Patient::findOrFail($visit->patient_id);
            $doctor = Doctor_db::findOrFail($visit->doctor_id);
            $hospital = Healtcare_org::findOrFail($org_id);

            $trigger_at = date('Y-m-d', strtotime('-1 day', strtotime($fud)));
            $dueDate = Carbon::parse($fud);

            $oneDayBeforeEvening = $dueDate->copy()->subDay()->setTime(19, 0)->format('Y-m-d H:i:s');
            $sameDayMorning = $dueDate->copy()->setTime(7, 0)->format('Y-m-d H:i:s');

            // today evening (6:00 PM)
           // $todayEvening = date('Y-m-d 19:00:00');

            // next day morning (9:00 AM)
           // $tomorrowMorning = date('Y-m-d 07:00:00', strtotime('+1 day'));

            // final JSON structure  for patient
            $data = [
                "followup_date" => $fud,
                "schedule" => [
                    [
                        "label" => "Evening Reminder",
                        "type"  => "evening",
                        "datetime" => $oneDayBeforeEvening
                    ],
                    [
                        "label" => "Morning Reminder",
                        "type"  => "morning",
                        "datetime" => $sameDayMorning
                    ]
                ]
            ];

            $additional = json_encode($data, JSON_PRETTY_PRINT);



            $res =  \App\Helpers\Notifier::followup_next_visit_reminder([
                'patient_id' => $patient->id,
                'phone_number' => $patient->mobile_no,
                'params' => [
                    'patient_name'=> $patient->prefix.' '.$patient->Fname.' '.($patient->Lname??""),
                    'follow_up_date'=> date('D, d M Y', strtotime($visit->fud)),
                    'dr_name'=> $doctor->name??"",
                    'hospital_name'=>$hospital->name??'',
                    'hospital_contact'=>$hospital->contact_no??'',
                    'link' => $hospital->external_app_link?:url('book-appointment/select-doctor/'.encryptID($org_id)),
                    ],
                'trigger_at' => $trigger_at,
                'additional' =>   $additional
            ]);


            $res =  \App\Helpers\Notifier::followup_visit_reminder_doctor([
                'doctor_id' => $doctor->id,
                'phone_number' => $doctor->contact_no,
                'params' => [
                    'dr_name'=> $doctor->name??"",
                    'patient_name'=> $patient->prefix.' '.$patient->Fname.' '.($patient->Lname??""),
                    'follow_up_date'=> date('D, d M Y', strtotime($visit->fud)),
                    'hospital_name'=>$hospital->name??'',
                    ],
                'trigger_at' => $trigger_at,
                'additional' =>   $additional
            ]);


            return response()->json(['status'=>'success','message'=>'Follow up Date updated successfully']);



        }else{
            return response()->json(['status'=>'error','message'=>'Visit not found']);
        }
    }


    public function loadSettleBills(Request $request)
    {

        $bills = PatientBilling::join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                                ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
                                ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                ->leftJoin('users', 'users.id', '=', 'patient_billing.created_by')
                                ->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover')
                                ->leftJoin(
                                    DB::raw('(SELECT bill_id, SUM(amount) AS total_payment FROM billing_payment_type GROUP BY bill_id) as billing_totals'),
                                    'billing_totals.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->leftJoin(
                                    DB::raw('(SELECT bill_id, SUM(charges*qty-discount) AS subtotal FROM patient_gen_bill where is_cancelled IS NULL GROUP BY bill_id) as gen_totals'),
                                    'gen_totals.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->leftJoin(
                                    DB::raw("(SELECT DISTINCT bill_id FROM refund_remarks WHERE status = 'issued') as refunded_bills"),
                                    'refunded_bills.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->select(
                                    'pi.Fname', 'pi.Lname', 'pi.prefix', 'pi.sex', 'pi.age', 'pi.id as uhid',
                                    'doctor_db.name as doctor_name',
                                    'health_insurance_agen.insurance_agen',
                                    'patient_billing.id as bill_id',
                                    'patient_billing.*',
                                    'patient_billing.created_at',
                                    DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
                                    DB::raw('gen_totals.subtotal - patient_billing.discount as total'),
                                    'billing_totals.total_payment as total_paid',
                                    'gen_totals.subtotal as subtotal',
                                    DB::raw('CASE WHEN refunded_bills.bill_id IS NOT NULL THEN 1 ELSE 0 END as is_refunded')
                                )
                                ->where('visitlog.hospital_id', auth()->user()->org_id)
                                ->where('visitlog.visit_status', 0)
                               ->where(function ($query) {
                                        $query->where('patient_billing.is_cancelled', '!=', 1)
                                            ->orWhereNull('patient_billing.is_cancelled');
                                    })
                                // Amount fully paid
                                ->whereRaw('IFNULL(billing_totals.total_payment, 0) = IFNULL(gen_totals.subtotal, 0) - IFNULL(patient_billing.discount, 0)')
                                // Now apply conditional logic for full settlement
                                ->where(function ($query) {
                                    $query->where('patient_billing.is_settled', 1) // Option 1
                                        ->orWhere(function ($q) {
                                            $q->whereNotExists(function ($subQuery) {
                                                $subQuery->select(DB::raw(1))
                                                    ->from('patient_gen_bill')
                                                    ->whereRaw('patient_gen_bill.bill_id = patient_billing.id')
                                                    ->where(function ($sq) {
                                                        $sq->whereNull('patient_gen_bill.is_settled')
                                                            ->orWhere('patient_gen_bill.is_settled', '!=', 1);
                                                    });
                                            });
                                        });
                                });


                            // Filter logic
                            if ($request->bill_id) {
                                $bills->where('patient_billing.id', $request->bill_id);
                            } elseif ($request->start_date && $request->end_date) {
                                $bills->whereBetween(DB::raw('DATE(patient_billing.created_at)'), [$request->start_date, $request->end_date]);
                            } elseif ($request->status) {
                                $bills->where('patient_billing.status', $request->status);
                            } else {
                                $bills->whereBetween(DB::raw('DATE(patient_billing.created_at)'), [date('Y-m-d'), date('Y-m-d')]);
                            }

                            // Final conditions
                            $bills->where('visitlog.hospital_id', auth()->user()->org_id);
                            // $bills->where('visitlog.visit_status',0);
                            $bills->orderBy('patient_billing.id', 'DESC');

                            $bills = $bills->get();


        return view('admin.patient.billing.settle_bills' , compact('bills'));
    }


    public function settle_bill_view(Request $request){


        $this->dateRangeLimit->validate(
            $request->from_date,
            $request->end_date,
            Auth()->user()->org_id
        );




          $bills = PatientBilling::join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                                    ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
                                    ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                    ->leftJoin('users', 'users.id', '=', 'patient_billing.created_by')
                                    ->leftJoin('ipd_details','ipd_details.visit_table_id','=','visitlog.id')
                                    ->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover')
                                    // ->leftJoin(
                                    //     DB::raw('(SELECT bill_id, SUM(amount) AS total_payment FROM billing_payment_type GROUP BY bill_id) as billing_totals'),
                                    //     'billing_totals.bill_id',
                                    //     '=',
                                    //     'patient_billing.id'
                                    // )

                                    ->leftJoin(
                                        DB::raw('
                                            (
                                                SELECT
                                                    bill_id,

                                                    -- Net Paid (without TDS)
                                                    SUM(
                                                        CASE
                                                            WHEN transaction_type = 0
                                                                THEN amount
                                                            WHEN transaction_type = 1
                                                                THEN - amount
                                                            ELSE 0
                                                        END
                                                    ) AS total_payment,

                                                    -- Net TDS (separate column)
                                                    SUM(
                                                        CASE
                                                            WHEN transaction_type = 0
                                                                THEN COALESCE(tds, 0)
                                                            WHEN transaction_type = 1
                                                                THEN - COALESCE(tds, 0)
                                                            ELSE 0
                                                        END
                                                    ) AS total_tds

                                                FROM billing_payment_type
                                                WHERE (is_deleted != 1 OR is_deleted IS NULL)
                                                GROUP BY bill_id
                                            ) as billing_totals
                                        '),
                                        'billing_totals.bill_id',
                                        '=',
                                        'patient_billing.id'
                                    )


                                ->leftJoin(
                                        DB::raw('(
                                            SELECT
                                                bill_id,
                                                SUM(charges * qty - discount) AS subtotal,
                                                SUM(JSON_UNQUOTE(JSON_EXTRACT(additional_info, "$.cgst"))) AS cgst_total,
                                                SUM(JSON_UNQUOTE(JSON_EXTRACT(additional_info, "$.sgst"))) AS sgst_total,
                                                SUM((charges * qty - discount) +
                                                    IFNULL(JSON_UNQUOTE(JSON_EXTRACT(additional_info, "$.cgst")), 0) +
                                                    IFNULL(JSON_UNQUOTE(JSON_EXTRACT(additional_info, "$.sgst")), 0)
                                                ) AS grand_total
                                            FROM patient_gen_bill
                                            WHERE (is_cancelled != 1 OR is_cancelled IS NULL)
                                            AND (is_deleted != 1 OR is_deleted IS NULL)
                                            GROUP BY bill_id
                                        ) as gen_totals'),
                                        'gen_totals.bill_id',
                                        '=',
                                        'patient_billing.id'
                                    )

                                    ->select(
                                        'pi.Fname', 'pi.Lname', 'pi.prefix', 'pi.sex', 'pi.age','pi.dob', 'pi.id as uhid',
                                        'doctor_db.name as doctor_name',
                                        'health_insurance_agen.insurance_agen',
                                        'patient_billing.id as bill_id',
                                        'patient_billing.visit_id',
                                        'patient_billing.discount',
                                        'patient_billing.*',
                                        'patient_billing.created_at',
                                        'ipd_details.id as ipd_no',
                                         // Original subtotal minus discount
                                        DB::raw('gen_totals.subtotal - patient_billing.discount as total'),

                                        // Including CGST and SGST in grand total
                                        'gen_totals.subtotal as subtotal',
                                        'gen_totals.cgst_total as cgst',
                                        'gen_totals.sgst_total as sgst',
                                        'gen_totals.grand_total as total_with_tax',

                                        DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
                                        DB::raw('(gen_totals.subtotal + IFNULL(gen_totals.cgst_total, 0) + IFNULL(gen_totals.sgst_total, 0) - patient_billing.discount) as total'),
                                        'billing_totals.total_payment as total_paid',
                                        'billing_totals.total_tds as total_tds',
                                        'gen_totals.subtotal as subtotal',

                                    );

                        if($request->type !== 'unsettled_partial_settled'){
                                 //   dd($request->all());
                                if ($request->from_date && $request->end_date) {
                                    $bills->whereBetween(DB::raw('DATE(visitlog.created_at)'), [$request->from_date, $request->end_date]);
                                }else{
                                    $bills->whereBetween(DB::raw('DATE(visitlog.created_at)'), [date('Y-m-d'), date('Y-m-d')]);
                                }

                                if($request->uhid){
                                    $bills->where('pi.id', $request->uhid);
                                }

                                if($request->bill_id){
                                    $bills->where('patient_billing.id', $request->bill_id);
                                }

                                if($request->mobile){
                                    $bills->where('pi.mobile_no', $request->mobile);
                                }


                                if ($request->name) {
                                        $bills->whereRaw("CONCAT(pi.prefix, ' ', pi.Fname, ' ', pi.Lname) LIKE ?", ['%' . $request->name . '%']);
                                }


                               if ($request->status) {
                                    $statusMap = [
                                        'all'               => [0, 1, 2],
                                        'unsettled'         => [0],
                                        'settled'           => [1],
                                        'partial_unsettled' => [0, 2],
                                        'partial_settled'   => [2],
                                    ];

                                    if (isset($statusMap[$request->status])) {
                                        $bills->whereIn('patient_billing.is_settled', $statusMap[$request->status]);
                                    }
                                }

                                if($request->visit_status){
                                    if($request->visit_status == 'opd'){
                                        $bills->where('visitlog.visit_status', 0);
                                    }else
                                    if($request->visit_status == 'ipd'){
                                        $bills->where('visitlog.visit_status', 2);
                                    }else{
                                        $bills->whereIn('visitlog.visit_status', [0,2]);
                                    }

                                }

                        }   else {

                            $bills->whereIn('patient_billing.is_settled', [0,2]);
                             $bills->whereIn('visitlog.visit_status', [0,2]);
                        }

                                // Final conditions
                               $bills->where('visitlog.hospital_id', auth()->user()->org_id);

                                // $bills->whereIN('visitlog.visit_status',[1,2]);
                                $bills->orderBy('patient_billing.id', 'DESC');

                                // $bills = $bills->get();

                                   $bills = $bills->with(['bill_items' => function ($q) {
                                            $q->where(function ($subQuery) {
                                                $subQuery->where('is_deleted', '!=', 1)
                                                ->orWhereNull('is_deleted');
                                            })->where(function ($subQuery) {
                                            $subQuery->where('is_cancelled', '!=', 1)
                                                ->orWhereNull('is_cancelled');
                                            });
                                        }, 'bill_items.service'])->get();

                                        // return $bills;

        if ($request->ajax()) {
           return view('admin.patient.settlement.bill-list',compact('bills'))->render();
        }



        return view('admin.patient.settlement.settle-bill', compact('bills'));
    }


