                                ->leftJoin(
                                    DB::raw('(SELECT bill_id, SUM(amount) AS total_payment FROM billing_payment_type GROUP BY bill_id) as billing_totals'),
                                    'billing_totals.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->leftJoin(
                                    DB::raw('(SELECT bill_id, SUM(charges*qty-discount) AS subtotal FROM patient_gen_bill where is_cancelled IS NULL GROUP BY bill_id) as gen_totals'),
                                    'gen_totals.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->select(
                                    'pi.Fname', 'pi.Lname', 'pi.prefix', 'pi.sex', 'pi.age', 'pi.id as uhid',
