                                    })
                                    ->where(function ($q) {
                                        $q->where('patient_gen_bill.is_cancelled', '!=', 1)
                                        ->orWhereNull('patient_gen_bill.is_cancelled');
                                    })
                                    ->where(function ($q) {
                                        $q->where('patient_gen_bill.is_deleted', '!=', 1)
                                        ->orWhereNull('patient_gen_bill.is_deleted');
                                    });
                            });


