                                                $subQuery->where('is_deleted', '!=', 1)
                                                ->orWhereNull('is_deleted');
                                            })->where(function ($subQuery) {
                                            $subQuery->where('is_cancelled', '!=', 1)
                                                ->orWhereNull('is_cancelled');
