    public function mark_bills_as_settled(Request $request)
    {

        $fullyPaidBills = DB::table('patient_billing as pb')
                                ->join('visitlog', 'visitlog.id', '=', 'pb.visit_id')
                               ->leftJoin(DB::raw('(
                                        SELECT bill_id, SUM(charges * qty - IFNULL(discount, 0)) as service_total
                                        FROM patient_gen_bill
                                        GROUP BY bill_id
                                    ) as pgb'), 'pgb.bill_id', '=', 'pb.id')

                                    ->leftJoin(DB::raw('(
                                        SELECT bill_id,
                                        SUM(CASE WHEN transaction_type = 0 THEN IFNULL(amount, 0) ELSE 0 END) as payment_total
                                        FROM billing_payment_type
                                        GROUP BY bill_id
                                        ) as bpt'), 'bpt.bill_id', '=', 'pb.id')

                                    ->select('pb.id')
                                    ->selectRaw('
                                        (IFNULL(pgb.service_total, 0) - IFNULL(pb.discount, 0)) as total_bill_amount,
                                        IFNULL(bpt.payment_total, 0) as total_paid
                                    ')
                                    ->havingRaw('total_paid >= total_bill_amount')
                                    ->where('visitlog.hospital_id', auth()->user()->org_id)
                                    ->where(function ($query) {
                                            $query->where('pb.is_cancelled', '!=', 1)
                                            ->orWhereNull('pb.is_cancelled');
                                    })
                                    ->where('pb.status', '=', 1)
                                    ->get();


       $billIds = $fullyPaidBills->pluck('id')->toArray();
    //    return $billIds;

       $res =  DB::table('patient_billing')->whereIn('id', $billIds)->update(['is_settled' => 1]);

    //    $res = DB::table('patient_gen_bill')->whereIn('bill_id', $billIds)->update(['is_settled' => 1]);

       if($res) {
         return response()->json(['status' => 'success', 'message'=>'Bills Settled Successfully']);
       }

       return response()->json(['status' => 'error', 'message'=>'Something went wrong']);

    }


    public function opd_bill_list(Request $request)
    {

        $bills = PatientBilling::join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                                ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
                                ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                ->leftJoin('users', 'users.id', '=', 'patient_billing.created_by')
                                ->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover')
                                ->leftJoin(
                                    DB::raw('(SELECT bill_id, SUM(amount) AS total_payment FROM billing_payment_type GROUP BY bill_id) as billing_totals'),
                                    'billing_totals.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->leftJoin(
                                    DB::raw('(SELECT bill_id, SUM(charges*qty-discount) AS subtotal FROM patient_gen_bill GROUP BY bill_id) as gen_totals'),
                                    'gen_totals.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->leftJoin(
                                    DB::raw("(SELECT DISTINCT bill_id FROM refund_remarks WHERE status = 'issued') as refunded_bills"),
                                    'refunded_bills.bill_id',
                                    '=',
                                    'patient_billing.id'
                                )
                                ->select(
                                    'pi.Fname', 'pi.Lname', 'pi.prefix', 'pi.sex', 'pi.age', 'pi.id as uhid',
                                    'doctor_db.name as doctor_name',
                                    'health_insurance_agen.insurance_agen',
                                    'patient_billing.id as bill_id',
                                    'patient_billing.*',
                                    'patient_billing.created_at',
                                    DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
                                    DB::raw('gen_totals.subtotal - patient_billing.discount as total'),
                                    'billing_totals.total_payment as total_paid',
                                    'gen_totals.subtotal as subtotal',
                                    DB::raw('CASE WHEN refunded_bills.bill_id IS NOT NULL THEN 1 ELSE 0 END as is_refunded')
                                );

                            // Filter logic
                            if ($request->bill_id) {
                                $bills->where('patient_billing.id', $request->bill_id);
                            } elseif ($request->start_date && $request->end_date) {
                                $bills->whereBetween(DB::raw('DATE(patient_billing.created_at)'), [$request->start_date, $request->end_date]);
                            } elseif ($request->status) {
                                $bills->where('patient_billing.status', $request->status);
                            } else {
                                $bills->whereBetween(DB::raw('DATE(patient_billing.created_at)'), [date('Y-m-d'), date('Y-m-d')]);
                            }

                            // Type specific filters
                            if ($request->type === 'cancelled') {
                                $bills->where('patient_billing.is_cancelled', 1);
                            } elseif ($request->type === 'pending') {
                                $bills->whereRaw('(gen_totals.subtotal - patient_billing.discount) - IFNULL(billing_totals.total_payment, 0) > 0');
                            } elseif ($request->type === 'refund') {
                                $bills->whereNotNull('refunded_bills.bill_id');
                            }

                            // Final conditions
                            $bills->where('visitlog.visit_status',0);
                            $bills->where('visitlog.hospital_id', auth()->user()->org_id);
                            $bills->orderBy('patient_billing.id', 'DESC');

                            $bills = $bills->get();

                    //    return $bills;

        return view('admin.patient.billing.opd_bill_list' , compact('bills'));
    }



