    public function edit_bill_item(Request $request) {

        // return $id;
        $org_id = Auth::user()->org_id;

        $id = $request->bill_id;

        $bill = PatientBilling::join('visitlog','visitlog.id','=' ,'patient_billing.visit_id')
                                ->join('pi','pi.id','=','visitlog.patient_id')
                                ->select('pi.id as pid','visitlog.id as visit_id','visitlog.doctor_id','patient_billing.created_at','patient_billing.*','patient_billing.is_settled')
                                ->where('patient_billing.id',$id)
                                ->where('visitlog.hospital_id',$org_id)
                                ->where('patient_billing.is_settled',0)
                                ->where('visitlog.visit_status',0)
                                ->where(function($q) {
                                        $q->whereNull('patient_billing.is_cancelled')
                                        ->orWhere('patient_billing.is_cancelled', 0);
                                    })
                                ->first();

        if(!$bill) {
            return response()->json(['status' => 'error', 'message'=>'Bill not found']);
        }

        if($bill->is_settled == 1) {
            return response()->json(['status' => 'error', 'message'=>'Bill already settled']);
        }

        $hasRefunds = DB::table('refund_remarks')
            ->where(function($q) use ($id) {
                $q->whereRaw('JSON_CONTAINS(bill_ref_id, ?)', [json_encode((string)$id)])
                  ->orWhereRaw('JSON_CONTAINS(bill_ref_id, ?)', [json_encode((int)$id)])
                  ->orWhere('bill_id', $id);
            })
            ->where('status', 'issued')
            ->exists();

        if ($hasRefunds) {
            return response()->json(['status' => 'error', 'message' => 'This bill has refunds issued against it and cannot be edited.']);
        }

        $pid = $bill->pid;
        $vid = $bill->visit_id;

        $patient = Patient::join('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                                ->select('pi.id','pi.i_cover as i_cover','pi.*','health_insurance_agen.insurance_agen as insurance')
                                ->where('pi.hospital_id',$org_id)
                                ->where('pi.id',$pid)
                                ->first();


        $doctors = HospitalDoctor::join('doctor_db','doctor_db.id','=','org_doc_index.doc_id')
                                    ->select('doctor_db.*')
                                    ->where('org_doc_index.org_id',$org_id)
                                    ->where('org_doc_index.active',1)
                                    ->orderBy('name','ASC')
                                    ->get();

       $service=HospitalService::leftJoin('hospital_services','hospital_services.id','=','hospital_services_index.service')
                                ->leftJoin('hospital_service_charges','hospital_service_charges.service','=','hospital_services_index.service')
                                ->where('hospital_services_index.hospital_id',$org_id)
                                ->where('hospital_services_index.active',1)
                                ->where('hospital_service_charges.insurance',$patient->i_cover)
                                ->where('hospital_service_charges.hospital_id',$org_id)
                                ->select('hospital_services.service',
                                            'hospital_services.spec_id',
                                            'hospital_services.id',
                                            'hospital_services.short_code'
                                            )
                                ->groupBy('hospital_service_charges.service')
                                ->get();

       $discAuthUsers = User::where('active',1)->get()->toArray();

       // check if there is any existing bill
        $discount = BillDiscount::where('active',1)->get();

                        // $patient_payment= BillingPaymentType::where('bill_id',$billId)->get();
            $patient_services = PatientGenBill::leftJoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                                ->select('patient_gen_bill.*', 'hospital_services.service as service_name')
                                                ->where('hospital_services.flag', '!=', 'refund')
                                                ->where('hospital_services.flag', '!=', 'balance')
                                                ->where('patient_gen_bill.bill_id', $id)
                                                ->where('patient_gen_bill.is_deleted', 0)
                                                ->where(function($q) {
                                                    $q->whereNull('patient_gen_bill.is_cancelled')
                                                    ->orWhere('patient_gen_bill.is_cancelled', 0);
                                                })
                                                ->get();


                        $payment = BillingPaymentType::where('bill_id', $id)
                                                        ->select(
                                                            'payment_mode',
                                                            DB::raw('SUM(amount) as amount')
                                                        )
                                                        ->groupBy('payment_mode')
                                                        ->get()
                                                        ->pluck('amount', 'payment_mode')
                                                        ->toArray();

                            // Dynamically get all payment modes from the database (if needed)
                            // This ensures you always have the latest payment modes
                            $paymentModes = BillingPaymentType::distinct('payment_mode')->pluck('payment_mode')->toArray();

                            // Initialize payment modes with 0 if they don't exist
                            foreach ($paymentModes as $mode) {
                                if (!isset($payment[$mode])) {
                                    $payment[$mode] = 0;
                                }
                            }

                        // Calculate the total collection dynamically
                        $total_collection = array_sum($payment);

                        // return $total_collection;

                        $trx = BillingPaymentType::where('bill_id',$id)
                                                    ->select('payment_mode','transaction_id')
                                                    ->groupBy('payment_mode')
                                                    ->get()
                                                    ->pluck('transaction_id','payment_mode')
                                                    ->toArray();
                            if(count($trx) == 0){
                                $trx['cash'] = '';
                                $trx['upi'] = '';
                                $trx['card'] = '';
                            }

                                return response()->json([
                                    'status' => 0,
                                    'billid' =>$id,
                                    'visit_id' => $vid,
                                    'patient'=> $patient,
                                    'service' => $service,
                                    'patient_billing' => $bill,
                                    'patient_services' => $patient_services,
                                    'patient_payment' => $payment,
                                    'trx' => $trx,
                                    'disc' => $discount,
                                    'i_cover' => $patient->i_cover,
                                    'disc_auth_users' =>$discAuthUsers,
                                    'doctors'=>$doctors,
                                    'doctor_id' => $bill->doctor_id,
                                    'display_date' => $bill->created_at,
                                    'type'=>2,
                                    'total_collection' => $total_collection
                                ]);

    }


    public function save_edited_bill(Request $request, $status) {

        $org_id = Auth::user()->org_id;

        $bill_id = $request->bill_no;

        $bill =PatientBilling::find($bill_id);
        $visit_id =$request->visit_id??$bill->visit_id;
        $bill->visit_id = $visit_id;
        $display_date = $request->display_date;

        if ($request->has('ref_by') && $visit_id) {
            $refVal = (!empty($request->ref_by) && $request->ref_by !== '__new__') ? $request->ref_by : null;
            Visitlog::where('id', $visit_id)->update(['ref_by' => $refVal]);
        }

        $user = auth()->user();

        // --- Backend Lock & Status Verification ---
        if ($bill->is_cancelled == 1) {
            return response()->json(['status' => 'error', 'message' => "This bill is cancelled and cannot be edited."], 422);
        }

        $hasRefunds = DB::table('refund_remarks')
            ->where(function($q) use ($bill) {
                $q->whereRaw('JSON_CONTAINS(bill_ref_id, ?)', [json_encode((string)$bill->id)])
                  ->orWhereRaw('JSON_CONTAINS(bill_ref_id, ?)', [json_encode((int)$bill->id)])
                  ->orWhere('bill_id', $bill->id);
            })
            ->where('status', 'issued')
            ->exists();

        if ($hasRefunds) {
            return response()->json(['status' => 'error', 'message' => "This bill has refunds issued against it and cannot be edited."], 422);
        }

        if ($bill->is_settled == 1) {
             return response()->json(['message' =>"This bill is already settled and cannot be edited."], 200);
        }

        if ($bill->is_locked == 1) {
            // return back()->with('error', '');
            return response()->json(['message' =>"This bill is locked and cannot be edited. Please contact Administrator."], 200);
        }

        $response = $bill->autoLockIfExpired(true);
        if ($response) return $response;


        $pi = null;
        if (!empty($visit_id) && is_numeric($visit_id)) {
            $pi = Visitlog::join('pi', 'pi.id', '=', 'visitlog.patient_id')
                            ->select('i_cover', 'visitlog.doctor_id')
                            ->where('visitlog.id', '=', $visit_id)
                            ->first();
        }
        $i_cover = $pi ? $pi->i_cover : ($bill->i_cover ?? 0);
        $doctor_id = $pi ? $pi->doctor_id : ($request->doctor_id ?? 0);

            $discount_in = HospitalSetting::where('hospital_id',auth()->user()->org_id)
                            ->where('identifier','discount_in_cash_or_percentage')
                            ->first()->current_setting??'cash';

            // dd($discount_in);

            // $bill->discount = $request->input('discount');

            if($discount_in == 'cash'){
                $bill->discount = $request->input('discount');
            }else{
                $bill->discount = $request->input('discount');
                $bill->discount_per = $request->input('discount_per');
            }

            $bill->status = $status;
           // $bill->discount = $request->discount??0;
            $bill->discount_type = $request->discount_type;
            if($request->discount != null){
                $bill->discount_auth_by = $request->discount_auth_by;
            }
            $bill->updated_by = auth()->user()->id;
            $bill->claim_id = $request->input('claim_id');

            if(isset($display_date) && !empty($display_date) && $display_date != 'undefined') {
                 $bill->created_at = $display_date;
            }
            $bill->remarks = $request->remarks ?? '';

             if ($request->hasFile('discount_attachment')) {
                    $file = $request->file('discount_attachment');
                    \App\Services\SecureFileService::validate($file, ['pdf', 'jpg', 'jpeg', 'png', 'webp', 'doc', 'docx'], 5120);

                    $cleanOriginalName = preg_replace('/[^a-zA-Z0-9_\.-]/', '_', $file->getClientOriginalName());
                    $filename = time() . '_' . $cleanOriginalName;

                    $destination = public_path('assets/files/attachments');
                    if (!file_exists($destination)) {
                        @mkdir($destination, 0755, true);
                    }
                    $file->move($destination, $filename);

                    $bill->attachment = $filename;
                    $bill->save();
                }

            $bill->save();

            $b_id = $bill->id;



        if (auth()->user()->can('module-permission', ['bill_payment_edit', 'can_update'])) {
            $updatedModes = [];

            foreach ($request->payment as $key => $amount) {
                if ($amount > 0) {
                    BillingPaymentType::updateOrCreate(
                        [
                            'bill_id'      => $b_id,
                            'payment_mode' => $key,
                        ],
                        [
                            'amount'        => $amount,
                            'transaction_id'=> $request->trx[$key] ?? null,
                            'created_by'    => $bill->created_by,
                            'updated_by'    => auth()->user()->id,
                            'created_at'    => $bill->created_at,
                        ]
                    );

                    $updatedModes[] = $key; // keep track of modes we updated
                }
            }

            // update other records not present in the request

           BillingPaymentType::where('bill_id', $b_id)
                ->whereNotIn('payment_mode', $updatedModes)
                ->update(['amount' => 0, 'updated_by' => auth()->user()->id]);

        } else {
            $updatedModes = [];

            foreach ($request->payment as $key => $amount) {
                if ($key === 'cash' && $amount > 0) {
                    BillingPaymentType::updateOrCreate(
                        [
                            'bill_id'      => $b_id,
                            'payment_mode' => 'cash',
                        ],
                        [
                            'amount'        => $amount,
                            'transaction_id'=> $request->trx[$key] ?? null,
                            'created_by'    => $bill->created_by,
                            'updated_by'    => auth()->user()->id,
                            'created_at'    => $bill->created_at,
                        ]
                    );

                    $updatedModes[] = 'cash';
                }
            }

            // delete other modes (non-cash) if they exist
             BillingPaymentType::where('bill_id', $b_id)
                                    ->whereNotIn('payment_mode', $updatedModes)
                                    ->update(['amount' => 0, 'updated_by' => auth()->user()->id]);
        }



            $kept_ids = [];

            foreach ($request->service_id ?? [] as $i => $ser_id) {
                $primaryId = $request->primary_id[$i] ?? null;

                if ($service = HospitalSer::find($ser_id)) {
                    if ($service->flag == "lab_package") {

                        // $packageService = $service->service;
                        $packageServiceCharge = HospitalServiceCharges::where('hospital_id',$org_id)
                                                                        ->where('insurance',$i_cover)
                                                                        ->where('service',$service->id)
                                                                        ->first()->charges??0;

                        $testIncludes = InvestigationGroupTest::where('group_id', $ser_id)->orderBy('sequence_no', 'asc')->get();
                        $subTotal = 0;
                        foreach($testIncludes as $test)
                        {
                            $sCharge = HospitalServiceCharges::where('hospital_id',$org_id)->where('insurance',$i_cover)->where('service',$test->test_id)->first();
                            $subTotal += $sCharge->charges??0;

                            $gen= PatientGenBill::firstOrNew([ 'bill_id' => $b_id, 'service_id' => $test->test_id ]);
                            $gen->bill_id = $b_id;
                            $gen->service_id = $test->test_id;
                            $gen->charges = $sCharge->charges??0;
                            $gen->qty = 1;
                            $gen->doctor_id = $doctor_id;
                            $gen->i_cover = $i_cover;
                            $gen->service_delivered_at = now();
                            $gen->doctor_id = $doctor_id;
                            $gen->i_cover = $i_cover;
                            $gen->created_at = $bill->created_at;
                            $gen->created_by = $bill->created_by;
                            $gen->updated_by = auth()->user()->id;
                            $gen->save();
                        }

                        $bill = PatientBilling::find($b_id);
                        // $bill->bill_tag = 'package';
                        // $bill->tag_ref_id = $ser_id;
                        $bill->discount = $bill->discount + ($subTotal - $packageServiceCharge);
                        $bill->save();


                    } else {
                        if ($primaryId) {
                            // Update existing record
                            $gen = PatientGenBill::find($primaryId);
                            if (!$gen) {
                                $gen = new PatientGenBill();
                            }
                        } else {
                            // Defensive fallback: match existing record if not yet kept
                            $gen = PatientGenBill::where('bill_id', $b_id)
                                ->where('service_id', $ser_id)
                                ->where('is_deleted', 0)
                                ->whereNotIn('id', $kept_ids)
                                ->first();

                            if (!$gen) {
                                // Create new record
                                $gen = new PatientGenBill();
                                $gen->created_at = $bill->created_at;
                                $gen->service_delivered_at = now();
                            }
                        }

                        if($discount_in == 'cash'){
                            $dis_value = $request->discountArr[$i] ?? 0;
                        }else{
                            $dis_value = ($request->charges[$i]??0)  * ($request->qty[$i]??1) * ($request->discountArr[$i]??0) / 100;
                        }


                        $gen->bill_id   = $b_id;
                        $gen->service_id = $ser_id;
                        $gen->charges   = $request->charges[$i] ?? 0;
                        $gen->qty       = $request->qty[$i] ?? 1;
                        $gen->cgst       = $request->cgst[$i] ?? 0;
                        $gen->sgst       = $request->sgst[$i] ?? 0;
                        $gen->igst       = $request->igst[$i] ?? 0;

                        if($discount_in == 'cash'){
                            $gen->discount  = $dis_value;
                        }else{
                             $gen->discount  = $dis_value;
                             $gen->discount_per  = $request->discountArr[$i]?? null;
                        }

                        $gen->doctor_id = $doctor_id;
                        $gen->i_cover = $i_cover;
                        $gen->created_by = $bill->created_by;
                        $gen->updated_by = auth()->user()->id;
                        $gen->save();
                    }
                }

            $kept_ids[] = $gen->id;
        }

       // ---------------------
        // 2. Remove rows not in kept_ids
        // ---------------------
        $old_records = PatientGenBill::where('bill_id', $bill_id)
            ->where('is_deleted', 0)
            ->where(function ($q) {
                $q->whereNull('is_cancelled')
                ->orWhere('is_cancelled', 0);
            })
            ->pluck('id')
            ->toArray();

        // Anything in DB but not in kept_ids is to be soft-deleted
        $removed_records = array_diff($old_records, $kept_ids);

        if (!empty($removed_records)) {
            PatientGenBill::where('bill_id', $bill_id)
                ->whereIn('id', $removed_records)
                ->update([
                    'is_deleted'   => 1,
                    'is_cancelled' => 1,
                    'cancelled_by'   => auth()->user()->id,
                    'cancelled_at'   => now(),
                    'updated_at'   => now(),
                ]);
        }



            $data = PatientBilling::join('visitlog','visitlog.id','patient_billing.visit_id')
                                        ->join('pi','pi.id','visitlog.patient_id')
                                        ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                        ->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover')
                                        ->join('users','users.id','=','patient_billing.created_by')
                                        ->select(
                                            'pi.id as patient_id',
                                            'pi.prefix as prefix',
                                            'pi.Fname as Fname',
                                            'pi.Lname as Lname',
                                            'pi.sex as gender',
                                            'pi.age as age',
                                            'pi.mobile_no as mobile_no',
                                            'doctor_db.name as doctor_name',
                                            'pi.i_cover as i_cover',
                                            'health_insurance_agen.insurance_agen as insurance',
                                            'patient_billing.created_at as created_at',
                                            'patient_billing.status as status',
                                            'patient_billing.id as bill_no',
                                            'patient_billing.discount as discount',
                                            'users.first_name',
                                            'users.last_name'
                                        )
                                        ->where('patient_billing.id',$b_id)
                                        ->first();

            $services = PatientGenBill::where('bill_id',$b_id)
                                          ->where('is_deleted', 0)
                                            ->where(function ($q) {
                                                $q->whereNull('is_cancelled')
                                                ->orWhere('is_cancelled', 0);
                                            })
                                        ->get();

            $payment = BillingPaymentType::where('bill_id',$b_id)
                ->select(
                    'payment_mode',
                    DB::raw('SUM(amount) as amount'),
                )
                ->groupBy('payment_mode')
                ->get()
                ->pluck('amount','payment_mode')->toArray();



            $pdf = PDF::loadView('admin.pdf.patient_bill',['data' => $data,'serviceData'=>$services, 'payments'=>$payment]);


        // download PDF file with download method
        // return $pdf->stream('pdf_file.pdf');
            if (!file_exists('assets/billing')) {
                mkdir('assets/billing', 0777, true);
            }

            //$pdf = PDF::loadView('admin.pdf.bill');
            $pdfFilename = 'pdf_file_' . $b_id . '.pdf';
            $pdfPath = 'assets/billing/'.$pdfFilename;
            $pdf->save($pdfPath);

        return response()->json(['message' =>"Service Charges Saved Successfully",  'pdf_url' => url($pdfPath)], 200);

    }




    public function cancel_bill_item(Request $request,$id, $req_id=null){

        $bill = PatientBilling::join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                ->join('pi','pi.id','=','visitlog.patient_id')
                                ->join('doctor_db','doctor_db.id','=','visitlog.doctor_id')
                                ->leftJoin('users','users.id','=','patient_billing.created_by')
                                ->join('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                                ->select('pi.Fname','pi.Lname','pi.prefix','pi.sex','pi.age','pi.dob','pi.id as uhid',
                                        'doctor_db.name as doctor_name',
                                        'health_insurance_agen.insurance_agen',
                                        // 'patient_billing.doc_charges as docch',
                                        // 'patient_billing.reg_charges as regch',
                                        'patient_billing.id as bill_id',
                                        // 'patient_billing.subtotal as subtotal',
                                        'patient_billing.discount as discount',
                                        // 'patient_billing.total as total',
                                        'patient_billing.created_at',
                                        DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
                                        // DB::raw('IFNULL(billing_payment_type.cash,0) +IFNULL(billing_payment_type.upi,0) +IFNULL(billing_payment_type.debit_card,0) as total_paid'),
                                    )->where('patient_billing.id', $id)->first();

        $services = PatientGenBill::where('bill_id',$id)
                                    ->leftJoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                    ->select('patient_gen_bill.*',
                                                // 'patient_gen_bill.amount',
                                                'hospital_services.service')
                                    ->get();
        $payments = BillingPaymentType::where('bill_id',$id)->get();


        if($req_id){
            $cancel_req = BillCancelRequest::where('id', $req_id)->first();
        }else{
            $cancel_req = null;
        }


        return view('admin.patient.billing.cancel_bill_items' , compact('bill','services','payments','cancel_req'))->render();
    }


    public function send_cancel_request(Request $request){
        $request->validate([
                'bill_id' => 'required',
                'remark' => 'required',
                'cancel_item' => 'required|array|min:1',
            ],[
                'cancel_item.required' => 'Please Select at least one item to cancel.',
            ]
        );

        $bill = new BillCancelRequest;
        $bill->bill_id = $request->bill_id;
        $bill->remarks = $request->remark;
        $bill->services = json_encode($request->cancel_item);
        $bill->created_by = Auth::user()->id;
        $bill->save();

        return response()->json(['status'=>'success', 'message'=>'Request Sent Successfully']);


    }



    public function save_cancel_bill_item(Request $request)
    {
        $user = Auth::user();
        if (!$user->can('module-permission', ['bill_cancel', 'can_update'])) {
            if ($request->ajax() || $request->wantsJson()) {
                return response()->json(['status' => 'error', 'message' => 'You do not have permission to cancel bills or items.'], 403);
            }
            return redirect()->back()->with('error', 'You do not have permission to cancel bills or items.');
        }

        if ($request->type === 'refund_and_cancel' && !$user->can('module-permission', ['refund', 'can_update'])) {
            if ($request->ajax() || $request->wantsJson()) {
                return response()->json(['status' => 'error', 'message' => 'You do not have permission to initiate refunds.'], 403);
            }
            return redirect()->back()->with('error', 'You do not have permission to initiate refunds.');
        }

        $request->validate([
                'bill_id' => 'required',
                'remark' => 'required',
                'cancel_item' => 'required|array|min:1',
                'type' => 'required',
            ],[
                'cancel_item.required' => 'Please Select at least one item to cancel.',
            ]
        );

        if($request->cancel_services_request_id){
            BillCancelRequest::where('id',$request->cancel_services_request_id)
                                ->update(['status'=>'approved']);
        }


        $billIds = DB::table('refund_remarks')
                        ->whereRaw('JSON_CONTAINS(bill_ref_id, ?)', [json_encode((string)$request->bill_id)])
                        ->pluck('bill_id')
                        ->toArray();

        // If no refund records found, set total_refund_amount to 0
        if (empty($billIds)) {
            $total_refund_amount = 0;
        } else {
            $total_refund_amount = DB::table('billing_payment_type')
                ->whereIn('bill_id', $billIds)
                ->selectRaw("SUM(CASE WHEN transaction_type = 0 THEN amount ELSE -amount END) as net_total")
                ->value('net_total') ?? 0; // also handles null result
        }

         $total_refund_amount = abs((float) $total_refund_amount); // Make sure it's positive
         $total_paid_amount = DB::table('billing_payment_type')
                                    ->where('bill_id', $request->bill_id)
                                    ->selectRaw("SUM(CASE WHEN transaction_type = 0 THEN amount ELSE -amount END) as net_total")
                                    ->value('net_total') ?? 0;

        DB::beginTransaction();

        $bill = PatientBilling::find($request->bill_id);

        $totalPaid = BillingPaymentType::where('bill_id', $request->bill_id)->sum('amount');

        if (count($request->cancel_item) > 0 && $request->type == 'cancel_bill_only') {
          if (bccomp($total_refund_amount, $total_paid_amount, 2) !== 0) {
                return response()->json([
                    'status' => 'error',
                    'message' => 'This bill has already been paid and cannot be cancelled. To make changes, please issue a refund or edit the bill.'
                ], 200);
            }
        } else if (count($request->cancel_item) > 0 && $request->type == 'refund_and_cancel') {

            $billItems = PatientGenBill::whereIn('id', $request->cancel_item)->get();

            $billItems2 = PatientGenBill::where('bill_id', $request->bill_id)
                                            ->where(function($query) {
                                                    $query->whereNull('is_deleted')
                                                        ->orWhere('is_deleted', 0);
                                                })
                                            ->get();
            // Step 1: Calculate subtotal (before any bill-level discount)
            $subtotal = $billItems2->reduce(function ($carry, $item) {
                return $carry + ((float) $item->charges * (int) $item->qty) - $item->discount;
            }, 0);



            // Step 2: Calculate discount percent from subtotal
            $discountPercent = $subtotal > 0 ? ($bill->discount / $subtotal) * 100 : 0;
        //    dd($subtotal, $discountPercent, $bill->discount);

            // Step 3: Apply this discount percent to each item to get final charge
            $total_service_charges = $billItems->reduce(function ($carry, $item) use ($discountPercent) {
                                                    $charges = (float) $item->charges;
                                                    $qty = (int) $item->qty;
                                                    $discount = (float) $item->discount;

                                                    $lineTotal = $charges * $qty - $discount;
                                                    $itemDiscount = ($lineTotal * $discountPercent) / 100;

                                                    return $carry + ($lineTotal - $itemDiscount);
                                                }, 0);

            $refund_amount = (float) $request->net_amount;
            $refund_amount = (float) $refund_amount;
            $total_paid_amount = (float) $total_paid_amount;

            if ($refund_amount > ($total_paid_amount - $total_refund_amount)) {
                return response()->json([
                    'status' => 'error',
                    'message' => 'Refund exceeds remaining paid amount.'
                ], 200);
            }

            // dd($refund_amount, $total_paid_amount, $total_refund_amount);
            // dd($refund_amount, $total_service_charges);

            if (round($total_service_charges, 2) !== round($refund_amount, 2)) {
                return response()->json([
                    'status' => 'error',
                    'message' => 'Total service charges do not match the refund amount.'
                ], 200);
            }
        }


            if ($request->hasFile('attachment')) {
                $file = $request->file('attachment');

                // Option 1: store in `storage/app/uploads`
                $path = $file->store('uploads', 'public');

                // Option 2: store with custom filename
                $filename = time().'_'.$file->getClientOriginalName();
                $path = $file->storeAs('uploads', $filename, 'public');

                $bill->attachment = $path;
                $bill->save();
            }

        if($request->cancel_all) {
            $bill->is_cancelled = 1;
            // $bill->cancelled_at = now();
            // $bill->cancelled_by = auth()->user()->id;
            $bill->save();

            $cRemark = new CancelBillRemarks;
            $cRemark->bill_id = $bill->id;
            $cRemark->remarks = $request->remark;
            $cRemark->created_by = auth()->user()->id;
            $cRemark->save();
        }


        $refund_bill_id = '';
        if(isset($request->type) && ($request->type == "refund_and_cancel"))
        {

             $receipt_no = $this->generate_receipt_no();

                $pbill = new PatientBilling;
                $pbill->visit_id = $bill->visit_id;
                $pbill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($bill->visit_id);
                $pbill->i_cover = $bill->i_cover;
                $pbill->receipt_no = $receipt_no;
                $pbill->discount = 0;
                $pbill->status = 1;
                $pbill->created_by = auth()->user()->id;
                $pbill->save();
                $patientBillingID = $pbill->id;

                $refund_bill_id = $pbill->id;

                // INSERT TRANSACTION TO PATIENT GEN BILL
                $paytype = new BillingPaymentType;
                $paytype->transaction_type = 1;
                $paytype->bill_id = $patientBillingID;
                $paytype->amount =  $refund_amount;
                $paytype->remarks = $request->remark;
                $paytype->payment_mode = $request->input_element;
                $paytype->created_by = auth()->user()->id;
                $paytype->save();

                $ref = new RefundRemark;
                $ref->bill_id = $patientBillingID;
                $ref->bill_ref_id = json_encode([$request->bill_id]);
                $ref->status = 'issued';
                $ref->cancelled_services = json_encode($request->cancel_item);
                $ref->issued_at = now();
                $ref->issued_by = auth()->user()->id;
                $ref->initiated_by = auth()->user()->id;
                $ref->initiated_at = now();
                $ref->save();

        // INSERT TRANSACTION TO PATIENT GEN BILL
        }

        foreach($request->cancel_item??[] as $item)
        {
            $billItem = PatientGenBill::find($item);
            $billItem->is_cancelled = 1;
            $billItem->service_status = 'cancelled';
            $billItem->cancelled_at = now();
            $billItem->cancelled_by = auth()->user()->id;
            $billItem->against_bill_id = $refund_bill_id;
            $billItem->save();

            $cRemark = new CancelBillRemarks;
            $cRemark->bill_item_id = $billItem->id;
            $cRemark->remarks = $request->remark;
            $cRemark->created_by = auth()->user()->id;
            $cRemark->save();
        }

        DB::commit();

        return response()->json(['status'=>'success','message'=>'Bill Item Cancelled Successfully!']);


    }


    public function generate_receipt_no(){
                      //To generate receipt no
        $lastBill = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                            ->select('visitlog.visit_status','patient_billing.*')
                            ->where('visitlog.visit_status',0)
                            ->orderBy('patient_billing.id','DESC')
                            ->first();

        $receipt_no = ($lastBill && $lastBill->receipt_no) ? $lastBill->receipt_no + 1 : 1;

        return $receipt_no;
    }

    public function initiate_refund(Request $request,$id,$billId=null)
    {

        // return redirect()->back()->with('error','Under testing');
        $patient = Patient::find($id);
        if(!$patient)
        {
            return view('admin.patient.refund.refund_initiate',compact('id'));
        }
        // $visit = Visitlog::findOrFail($id);
        $bills = PatientBilling::join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
                ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                ->leftJoin('users', 'users.id', '=', 'patient_billing.created_by')
                ->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover')
                ->leftJoin(
                    DB::raw('(SELECT bill_id, SUM(amount) AS total_payment FROM billing_payment_type GROUP BY bill_id) as billing_totals'),
                    'billing_totals.bill_id',
                    '=',
                    'patient_billing.id'
                )
                ->leftJoin(
                    DB::raw('(SELECT bill_id, SUM(charges*qty-discount) AS subtotal FROM patient_gen_bill WHERE is_cancelled IS NULL GROUP BY bill_id) as gen_totals'),
                    'gen_totals.bill_id',
                    '=',
                    'patient_billing.id'
                )
                ->leftJoin(
                    DB::raw("(SELECT DISTINCT bill_id FROM refund_remarks WHERE status = 'issued') as refunded_bills"),
                    'refunded_bills.bill_id',
                    '=',
                    'patient_billing.id'
                )
                ->where('visitlog.hospital_id', auth()->user()->org_id)
                ->where('pi.id',$patient->id);

        $summaryBills = clone $bills;
        $summaryBills = $summaryBills->select(
                    DB::raw('SUM(gen_totals.subtotal) as subtotal'),
                    DB::raw('SUM(patient_billing.discount) as total_discount'),
                    DB::raw('SUM(gen_totals.subtotal - patient_billing.discount) as total_billed'),
                    DB::raw('SUM(billing_totals.total_payment) as total_paid'),
                    DB::raw('SUM(CASE WHEN refunded_bills.bill_id IS NOT NULL THEN 1 ELSE 0 END) as refunded_count'),
                    DB::raw('CASE WHEN refunded_bills.bill_id IS NOT NULL THEN 1 ELSE 0 END as is_refunded')
                )->first();
        $bills = $bills->select(
                    'pi.Fname', 'pi.Lname', 'pi.prefix', 'pi.sex', 'pi.age', 'pi.dob','pi.id as uhid',
                    'doctor_db.name as doctor_name',
                    'health_insurance_agen.insurance_agen',
                    'patient_billing.id as bill_id',
                    'patient_billing.*',
                    'patient_billing.created_at',
                    DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
                    DB::raw('gen_totals.subtotal - patient_billing.discount as total'),
                    'billing_totals.total_payment as total_paid',
                    'gen_totals.subtotal as subtotal',
                    DB::raw('CASE WHEN refunded_bills.bill_id IS NOT NULL THEN 1 ELSE 0 END as is_refunded'),
                    DB::raw('(gen_totals.subtotal - patient_billing.discount - billing_totals.total_payment) as pendings')
                )
                ->get();


        $payments = PatientBilling::join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
                ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                ->join('billing_payment_type', 'billing_payment_type.bill_id', '=', 'patient_billing.id')
                ->leftJoin('users', 'users.id', '=', 'patient_billing.created_by')
                ->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover')
                ->where('visitlog.hospital_id', auth()->user()->org_id)
                ->where('patient_billing.status', 1)
                ->where('visitlog.patient_id', $patient->id);

        $summaryPayments = clone $payments;
        $summaryPayments = $summaryPayments->select(
                    DB::raw('SUM(CASE WHEN billing_payment_type.transaction_type = 0 THEN amount ELSE 0 END) as total_paid'),
                    DB::raw('SUM(CASE WHEN billing_payment_type.transaction_type = 1 THEN amount ELSE 0 END) as total_refund')
                )->first();
        $payments = $payments->select(
                    'pi.Fname', 'pi.Lname', 'pi.prefix', 'pi.sex', 'pi.age', 'pi.dob','pi.id as uhid',
                    'doctor_db.name as doctor_name',
                    'health_insurance_agen.insurance_agen',
                    'patient_billing.id as bill_id',
                    'billing_payment_type.*',
                    'patient_billing.created_at',
                    DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
                )->orderBy('patient_billing.id', 'DESC')->get();

        $user = auth()->user();
        $hosp_id = $user->org_id;


        $billIds = $bills->pluck('id')->toArray();

        $refunds = RefundRemark::join('patient_billing','patient_billing.id','=','refund_remarks.bill_id')
                                    ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                    ->join('pi','pi.id','=','visitlog.patient_id')
                                    ->leftJoin('billing_payment_type', 'billing_payment_type.bill_id', '=', 'refund_remarks.bill_id')
                                    ->select('refund_remarks.*',
                                        'pi.id as uhid',
                                        'refund_remarks.id as id',
                                        'refund_remarks.created_at as bill_date',
                                        'pi.Fname as patient_first_name',
                                        'pi.Lname as patient_last_name',
                                        'pi.sex as sex',
                                        'pi.dob as dob',
                                        'pi.mobile_no as phone',
                                        'patient_billing.id as bill_id',
                                        'billing_payment_type.amount as refund_amount',
                                        'billing_payment_type.payment_mode'
                                        )
                                    ->where('visitlog.hospital_id',$hosp_id)
                                    ->where(function ($query) use ($billIds) {
                                        foreach ($billIds as $billId) {
                                            $query->orWhereRaw("JSON_CONTAINS(bill_ref_id, '\"$billId\"')");
                                        }
                                    })->orderBy('refund_remarks.id','desc')->get();


        return view('admin.patient.refund.refund_initiate',compact('id','bills','billId','summaryBills','payments','summaryPayments','patient','refunds'));
    }

    public function save_initiate_refund(Request $request,$id)
    {
        $user = auth()->user();
        if (!$user->can('module-permission', ['refund', 'can_create']) && !$user->can('module-permission', ['refund', 'can_update'])) {
            if ($request->ajax() || $request->wantsJson()) {
                return response()->json(['status' => 'error', 'message' => 'Unauthorized. Refund create permission required.'], 403);
            }
            abort(403, 'Unauthorized. Refund create permission required.');
        }

        $request->validate([
            'bills' => 'required|array',
            'refund_amount' => 'required',
            'input_element' => 'required',
            'refund_remark' => 'required',
        ]);

        $patient = Patient::find($id);
        $visit = Visitlog::where('patient_id', $id)->where('visit_status', 0)->orderBy('id', 'desc')->first();


        //To generate receipt no
        $lastBill = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                            ->select('visitlog.visit_status','patient_billing.*')
                            ->where('visitlog.visit_status',0)
                            ->orderBy('patient_billing.id','DESC')
                            ->first();

        $receipt_no = ($lastBill && $lastBill->receipt_no) ? $lastBill->receipt_no + 1 : 1;

        $refund_approval_system = \App\Helpers\HospitalHelper::isSettingEnabled(auth()->user()->org_id,'refund_approval_system');
        $submitAsApproved = $request->has('submit_as_approved') || $request->has('auto_approve') || $request->input('status') === 'approved';

        // INSERT TO PATIENT BILLING
        $pbill = new PatientBilling;
        $pbill->visit_id = $visit->id;
        $pbill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($pbill->visit_id);
        $pbill->i_cover = $patient->i_cover;
        $pbill->receipt_no = $receipt_no;
        $pbill->discount = 0;
        $pbill->status = ($refund_approval_system && !$submitAsApproved) ? 0 : 1;
        $pbill->remarks = $request->refund_remark??'';
        $pbill->created_by = auth()->user()->id;
        $pbill->save();
        $patientBillingID = $pbill->id;

        // INSERT TRANSACTION TO PATIENT GEN BILL
        $paytype = new BillingPaymentType;
        $paytype->transaction_type = 1;
        $paytype->bill_id = $patientBillingID;
        $paytype->amount = $request->refund_amount;
        $paytype->payment_mode = $request->input_element;
        $paytype->remarks = $request->refund_remark??'';
        if ($request->filled('transaction_id')) {
            $paytype->transaction_id = $request->transaction_id;
        }
        $paytype->created_by = auth()->user()->id;
        $paytype->save();

        $ref = new RefundRemark;
        $ref->bill_id = $patientBillingID;
        $ref->bill_ref_id = json_encode($request->bills);
        $ref->initiated_by = auth()->user()->id;
        $ref->initiated_at = now();
        if ($submitAsApproved) {
            $ref->status = 'approved';
            $ref->approved_at = now();
            $ref->approved_by = auth()->user()->id;
        }
        $ref->save();

        if ($request->ajax() || $request->wantsJson()) {
            return response()->json([
                'status' => 'success',
                'success' => true,
                'message' => $submitAsApproved ? 'Refund Approved Successfully!' : 'Patient Refund Initiated Successfully!',
                'refund_id' => $ref->id,
                'bill_id' => $patientBillingID,
                'refund_status' => $ref->status
            ]);
        }

        toastr()->success($submitAsApproved ? 'Refund Approved Successfully!' : 'Patient Refund Initiated Successfully!');
        return redirect()->back();
    }


    public function update_initiate_refund(Request $request,$id)
    {
        $request->validate([
            'refund_amount' => 'required',
        ]);

        $patGenBill = PatientGenBill::findOrFail($id);
        $patGenBill->charges = $request->refund_amount;
        $patGenBill->amount = $request->refund_amount;

        $patBill = PatientBilling::findOrFail($patGenBill->bill_id);
        $patBill->total  = $request->refund_amount.'.00';
        $patBill->save();

        $billingPaymentType = BillingPaymentType::where('bill_id',$patGenBill->bill_id)->first();
        if($request->input_element =="cash")
        {
            $billingPaymentType->cash = $request->refund_amount;
            $billingPaymentType->upi = null;
            $billingPaymentType->debit_card = null;
        }
        if($request->input_element =="upi")
        {
            $billingPaymentType->upi = $request->refund_amount;
            $billingPaymentType->cash = null;
            $billingPaymentType->debit_card = null;
        }
        if($request->input_element =="card")
        {
            $billingPaymentType->debit_card = $request->refund_amount;
            $billingPaymentType->cash = null;
            $billingPaymentType->upi = null;
        }
        $billingPaymentType->save();
        $patGenBill->save();

        toastr()->success('Refund Amount Updated Successfully!');
        return redirect()->back();
    }
