    public function approve_refund(Request $request,$id)
    {
        $user = auth()->user();
        if (!$user->can('module-permission', ['refund', 'can_update'])) {
            if ($request->ajax() || $request->wantsJson()) {
                return response()->json(['status' => 'error', 'message' => 'Unauthorized. Refund update permission required.'], 403);
            }
            abort(403, 'Unauthorized. Refund update permission required.');
        }

        $patGenBill = RefundRemark::findOrFail($id);
        $patGenBill->status = 'approved';
        $patGenBill->approved_at = now();
        $patGenBill->approved_by = auth()->user()->id;
        $patGenBill->save();

        $refundBill = PatientBilling::findOrFail($patGenBill->bill_id);
        $refundBill->status = 1;
        $refundBill->save();

        if ($request->ajax() || $request->wantsJson()) {
            return response()->json([
                'status' => 'success',
                'success' => true,
                'message' => 'Refund Approved Successfully!',
                'refund_id' => $id,
                'refund_status' => 'approved'
            ]);
        }

        toastr()->success('Refund Approved Successfully!');
        return redirect()->back();
    }

    public function issue_refund(Request $request,$id)
    {
        $user = auth()->user();
        if (!$user->can('module-permission', ['refund', 'can_create']) && !$user->can('module-permission', ['refund', 'can_update'])) {
            if ($request->ajax() || $request->wantsJson()) {
                return response()->json(['status' => 'error', 'message' => 'Unauthorized. Refund issue permission required.'], 403);
            }
            abort(403, 'Unauthorized. Refund issue permission required.');
        }

        $refund = RefundRemark::findOrFail($id);
        $refund->status = 'issued';
        $refund->issued_at = now();
        $refund->issued_by = auth()->user()->id;
        $refund->save();

        $billingPaymentType = BillingPaymentType::where('bill_id',$refund->bill_id)->first();
        if($request->transaction_id){
            $billingPaymentType->transaction_id = $request->transaction_id;
        }
        $billingPaymentType->updated_by = auth()->user()->id;
        $billingPaymentType->save();

        if ($request->ajax() || $request->wantsJson()) {
            return response()->json([
                'status' => 'success',
                'success' => true,
                'message' => 'Refund Issued Successfully!',
                'refund_id' => $id,
                'refund_status' => 'issued'
            ]);
        }

        toastr()->success('Refund Issued Successfully!');
        return redirect()->back();
    }
    public function reject_refund(Request $request,$id)
    {
        $user = auth()->user();
        if (!$user->can('module-permission', ['refund', 'can_update'])) {
            if ($request->ajax() || $request->wantsJson()) {
                return response()->json(['status' => 'error', 'message' => 'Unauthorized. Refund update permission required.'], 403);
            }
            abort(403, 'Unauthorized. Refund update permission required.');
        }

        $patGenBill = RefundRemark::findOrFail($id);
        $patGenBill->status = 'rejected';
        $patGenBill->approved_at = now();
        $patGenBill->approved_by = auth()->user()->id;
        if ($request->filled('reason')) {
            $patGenBill->remarks = 'Rejected: ' . $request->reason . ($patGenBill->remarks ? (' | ' . $patGenBill->remarks) : '');
        }
        $patGenBill->save();

        $refundBill = PatientBilling::where('id', $patGenBill->bill_id)->first();
        if ($refundBill) {
            $refundBill->status = 0;
            $refundBill->save();
        }

        if ($request->ajax() || $request->wantsJson()) {
            return response()->json([
                'status' => 'success',
                'success' => true,
                'message' => 'Refund Rejected!',
                'refund_id' => $id,
                'refund_status' => 'rejected',
                'rejected_why' => $request->reason
            ]);
        }

        toastr()->success('Refund Rejected!');
        return redirect()->back();
    }
