    function unsettled_bill_list(Request $req){

        $user = auth()->user();
        $hosp_id = $user->org_id;

         $start_date = $req->start_date?? date('Y-m-d');
         $end_date = $req->end_date?? date('Y-m-d');


        if ($req->filled('start_date') && $req->filled('end_date')) {

            $dateError = $this->dateRangeLimit->getError(
                $req->start_date,
                $req->end_date,
                $user->org_id
            );

            if ($dateError) {
                return view(
                    'admin.patient.settlement.unsettled_bill_list'
                )->with('dateRangeError', $dateError);
            }
        }


                                $result = DB::table('patient_billing')
                                                ->join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                                                ->join('pi', 'visitlog.patient_id', '=', 'pi.id')
                                                ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                                ->select(
                                                    'patient_billing.visit_id',
                                                    'pi.prefix',
                                                    'pi.Fname',
                                                    'pi.Lname',
                                                    'pi.mobile_no',
                                                    'patient_billing.created_at as bill_date',
                                                    'patient_billing.id as bill_id',
                                                    'pi.id as uhid',
                                                    'doctor_db.name as doctor_name',
                                                    DB::raw("
                                                        (
                                                            SELECT COALESCE(SUM(charges * qty - discount), 0)
                                                            FROM patient_gen_bill
                                                            WHERE patient_gen_bill.bill_id = patient_billing.id
                                                             and patient_gen_bill.is_deleted = 0
                                                              AND (patient_gen_bill.is_cancelled IS NULL OR patient_gen_bill.is_cancelled = 0)
                                                        ) AS total_billing_amount
                                                    "),
                                                    DB::raw("
                                                        (
                                                            SELECT COALESCE(SUM(amount), 0)
                                                            FROM billing_payment_type
                                                            WHERE billing_payment_type.bill_id = patient_billing.id
                                                        ) AS total_payment
                                                    "),
                                                    DB::raw("
                                                    (
                                                        (
                                                            SELECT COALESCE(SUM(charges * qty - discount), 0)
                                                            FROM patient_gen_bill
                                                            WHERE patient_gen_bill.bill_id = patient_billing.id
                                                            and patient_gen_bill.is_deleted = 0
                                                             AND (patient_gen_bill.is_cancelled IS NULL OR patient_gen_bill.is_cancelled = 0)
                                                        )
                                                        - COALESCE(patient_billing.discount, 0)
                                                        - (
                                                            SELECT COALESCE(SUM(amount), 0)
                                                            FROM billing_payment_type
                                                            WHERE billing_payment_type.bill_id = patient_billing.id
                                                        )
                                                    ) AS balance_amount
                                                "))
                                                ->having('balance_amount', '>', 0)
                                                ->whereDate('patient_billing.created_at', '>=', $start_date)
                                                ->whereDate('patient_billing.created_at', '<=', $end_date)

                                                ->get();



        foreach($result as $res1){

            $ref_bill = billReference::select('ref_bill as bills')->where('bill_id', $res1->bill_id)->get()->toArray();

            // Extract the 'bills' values
            $res = array_column($ref_bill, 'bills');

            $settlements =  BillingPaymentType::whereIn('bill_id', $res)->get();
            $total = 0;
            foreach($settlements as $set){
                $total += $set->amount;
            }

            $total_settlement = $total;

            $res1->total_settlement = $total_settlement;
            $res1->settlements = $settlements;
        }



        return view('admin.patient.settlement.unsettled_bill_list',compact('result'));
    }


    public function save_vital(Request $req){

        $visit = Vitals::where('visit_id',$req->vid)->first();

        if(!$visit){
            $visit = new Vitals;
            $visit->visit_id = $req->vid;
            $visit->created_by = Auth::id() ?? 1;
            $visit->updated_by = Auth::id() ?? 1;
        } else {
            $visit->updated_by = Auth::id() ?? 1;
        }

        if($req->context == 'weight'){
            $visit->weight = $req->value;
        }
        if($req->context == 'temp'){
            $visit->temprature = $req->value;
        }
        if($req->context == 'height'){
            $visit->height = $req->value;
        }
        $visit->save();

        return response()->json(['status' => 'success']);
    }


