                                                    SELECT COALESCE(SUM(charges * qty), 0)
                                                    FROM patient_gen_bill
                                                    WHERE patient_gen_bill.bill_id = patient_billing.id
                                                ) AS total_billing_amount
                                            "),
                                            DB::raw("
                                                (
                                                    SELECT COALESCE(SUM(amount), 0)
                                                    FROM billing_payment_type
                                                    WHERE billing_payment_type.bill_id = patient_billing.id
                                                ) AS total_payment
                                            "),
                                            DB::raw("
                                            (
                                                (
                                                    SELECT COALESCE(SUM(charges * qty - discount), 0)
                                                    FROM patient_gen_bill
                                                    WHERE patient_gen_bill.bill_id = patient_billing.id
                                                )
                                                - COALESCE(patient_billing.discount, 0)
                                                - (
                                                    SELECT COALESCE(SUM(amount), 0)
                                                    FROM billing_payment_type
                                                    WHERE billing_payment_type.bill_id = patient_billing.id
                                                )
                                            ) AS balance_amount
                                        "))
                                        ->having('balance_amount', '>', 0)
                                        ->where('patient_billing.id',$request->bill_id)
                                        ->first();

            $total_balance = $result->balance_amount;
            $total_billing = $result->total_billing_amount;
            $total_payment = $result->total_payment;


            $ref_bill = billReference::select('ref_bill as bills')->where('bill_id', $request->bill_id)->get()->toArray();

            // Extract the 'bills' values
            $res = array_column($ref_bill, 'bills');

            $settlements =  BillingPaymentType::whereIn('bill_id', $res)->get();
            $total = 0;
            foreach($settlements as $set){
                $total += $set->amount;
            }

            $total_settlement = $total;

            $c_total_due = $total_balance - $total_settlement;

            if($request->amount > $c_total_due){
                toastr()->success('Patient Payment Received Successfully!');

                return response()->json([
                    'status' => 'error',
                    'message' => 'Amount cannot be greater than the due amount.'
                ]);
            }


/// if aleary visit for today then generate new bill
// otherwise create visit and generate new bill

try{
    DB::beginTransaction();


    $visit_id = $this->check_if_patient_already_visit_for_today($bill->patient_id, $bill->doctor_id,$hosp_id);
    // $visit_id = false;

    if($visit_id){

        $lastBill = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                ->select('visitlog.visit_status','patient_billing.*')
                ->where('visitlog.visit_status',0)
                ->orderBy('patient_billing.id','DESC')
                ->first();
        $receipt_no = ($lastBill && $lastBill->receipt_no) ? $lastBill->receipt_no + 1 : 1;

        $pbill = new PatientBilling;
        $pbill->visit_id = $visit_id;
        $pbill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($pbill->visit_id);
        $pbill->i_cover = $result->i_cover;
        $pbill->receipt_no = $receipt_no;
        $pbill->created_by = $user->id;
        $pbill->save();

        $pay = new BillingPaymentType;
        $pay->bill_id = $pbill->id;
        $pay->amount = $request->amount;
        $pay->payment_mode = $request->input_element;
        $pay->transaction_id = $request->transaction_id;
        $pay->created_by = $user->id;
        $pay->remarks = "settlement";
        $pay->save();

        $b = new billReference;
        $b->bill_id = $result->bill_id;
        $b->ref_bill = $pbill->id;
        $b->remark = "settlement";
        $b->save();

    }else{

        $visit = new Visitlog;
        $visit->patient_id = $result->uhid;
        $visit->hospital_id = $user->org_id;
        $visit->doctor_id = $bill->doctor_id;
        $visit->ch = 0;

        $currentDate = Carbon::today()->toDateString();
        $date = $currentDate." 00:00:00";
        $visit->date = $date;

        $currentTime = Carbon::now();
        $visit->visit_time = $currentTime->format('H:i:s');

        $visit->last_update= time();

        // visit id is visit no. for selected doctor in this hospital
        // fetch last visit no.
        $lastVisitNo = Visitlog::where([
                                        ['patient_id',$result->uhid],
                                        ['hospital_id',$user->org_id],
                                        ['doctor_id',$bill->doctor_id]]
                                    )
                                    ->latest('created_at')
                                    ->value('visit_id');

        // Increment the `visit_id` if it exists; otherwise, start with 1
        $visit->visit_id = $lastVisitNo ? $lastVisitNo + 1 : 1;

        // is_visited is for billing status
        $visit->is_visited = 0;
        $visit->created_by = auth()->user()->id;
        $visit->save();

        $new_visit_id = $visit->id;


    // insert id to gen_pres_log_1 table
        $gen_pres_log = new Gen_pres_log_1();
        $gen_pres_log->visit_table_id = $new_visit_id;
        $gen_pres_log->save();

        // fetch second last record
        $second_last_visit_data = Visitlog::where([
                                                        ['patient_id',$result->uhid],
                                                        ['hospital_id',$user->org_id],
                                                        ['doctor_id',$bill->doctor_id]
                                                   ])
                                            ->whereNull('visit_type')
                                            ->orderBy('id','desc')
                                            ->skip(1)
                                            ->take(1)
                                            ->first();
        if($second_last_visit_data){
            $this->copy_old_visit_data_to_new($new_visit_id, $second_last_visit_data->id);
        }

        $lastBill = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                ->select('visitlog.visit_status','patient_billing.*')
                ->where('visitlog.visit_status',0)
                ->orderBy('patient_billing.id','DESC')
                ->first();
        $receipt_no = ($lastBill && $lastBill->receipt_no) ? $lastBill->receipt_no + 1 : 1;

        $pbill = new PatientBilling;
        $pbill->visit_id = $new_visit_id;
        $pbill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($pbill->visit_id);
        $pbill->i_cover = $result->i_cover;
        $pbill->receipt_no = $receipt_no;
        $pbill->created_by = $user->id;
        $pbill->save();

        $pay = new BillingPaymentType;
        $pay->bill_id = $pbill->id;
        $pay->amount = $request->amount;
        $pay->payment_mode = $request->input_element;
        $pay->transaction_id = $request->transaction_id;
        $pay->created_by = $user->id;
        $pay->save();

        $b = new billReference;
        $b->bill_id = $result->bill_id;
        $b->ref_bill =  $pbill->id;
        $b->remark = "settlement";
        $b->save();

    }



    DB::commit();

    toastr()->success('Patient Payment Received Successfully!');


    return redirect()->route('patient.ubsettled_bill');

}catch(\Exception $e){
    DB::rollBack();

    return response()->json(['success' => false,'message' => $e->getMessage()]);
}



