    public function check_if_patient_already_visit_for_today($patient_id, $doctor_id, $hosp_id, $visit_date = null){

        // Set default date at runtime
        if (!$visit_date) {
            $visit_date = Carbon::today()->toDateString();
        }
       // dd($patient_id, $doctor_id);
        $todayRecord = Visitlog::where([
                                            ['patient_id', $patient_id],
                                            ['hospital_id', $hosp_id],
                                            ['doctor_id', $doctor_id],
                                        ])
                                        ->where('visit_status', 0)
                                        ->where('emergency',0)
                                        ->whereDate('created_at', $visit_date)
                                        ->first();

        if($todayRecord){
            return $todayRecord->id;
        }else{
            return false;
        }
    }

