    public function investigation_history_tracking(Request $request)
    {
        $vid = $request->vid;
        $visit = Visitlog::where('id',$vid)->first();
        $doctor = $visit->doctor;

        $specServices = \App\Models\SpecServiceTrack::join('hospital_services','hospital_services.id','=','doc_spec_service_track.service_id')
                        ->where('doc_spec_service_track.spec_id',$doctor->key_spec)
                        ->pluck('service_id')->toArray();

        $patServices = \App\Models\DocPatientServiceTrack::where('doc_id', $visit->doctor_id)
            ->where('pat_id', $visit->patient_id)
            ->pluck('service_id')
            ->toArray();

        $trackingServies = array_merge($specServices, $patServices);
        $trackingLookup = array_flip($trackingServies);

        $timeFilter = request()->filter_range??'180_days';
        $filterDays = date('Y-m-d',strtotime("-".str_replace('_',' ',$timeFilter)));

        $services = PatientGenBill::leftJoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                                ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                                ->select(
                                    'hospital_services.id as service_id',
                                    'hospital_services.service as service_name',
                                    'patient_gen_bill.created_at as gen_bill_date',
                                    DB::raw("lab_investigations.test_results as tests"),
                                )
                                ->where('lab_investigations.is_outsource',0)
                                ->where(function($q) {
                                    $q->whereNull('patient_gen_bill.is_deleted')
                                    ->orWhere('patient_gen_bill.is_deleted', 0);
                                })
                                ->where(function($q) {
                                    $q->whereNull('patient_gen_bill.is_cancelled')
                                    ->orWhere('patient_gen_bill.is_cancelled', 0);
                                })
                                ->where(function($q) {
                                    $q->whereNull('patient_billing.is_cancelled')
                                    ->orWhere('patient_billing.is_cancelled', 0);
                                })
                                ->where('visitlog.patient_id', $visit->patient_id)
                                ->where('lab_investigations.status', 'approved')
                                ->where('patient_gen_bill.created_at','>=',date('Y-m-d',strtotime("-".(str_replace('_',' ',$timeFilter))."")))
                                ->orderBy('patient_gen_bill.created_at','ASC')
                                ->get();
        $dates = [];

        foreach ($services as $service) {
            $date = date('d M y', strtotime($service->gen_bill_date));
            $dates[$date] = true;
        }

        $dates = array_keys($dates); // unique ordered dates
        sort($dates);

        $serviceMap = DB::table('hospital_services')->pluck('service', 'id');

        $table = []; // [parameter][date] = value

        foreach ($services as $service) {

            $date = date('d M y', strtotime($service->gen_bill_date));

            $tests = json_decode($service->tests, true);
            if (!$tests) continue;

            foreach ($tests as $groupName => $parameters) {

                foreach ($parameters as $serviceId => $data) {

                    if (!isset($trackingLookup[$serviceId])) continue;
                    if (!isset($data['value']) || $data['value'] === '') continue;

                    $parameter = $serviceMap[$serviceId] ?? 'Unknown';

                    // ≡ƒö┤ Initialize row if not exists
                    if (!isset($table[$parameter])) {
                        $table[$parameter] = array_fill_keys($dates, '-');
                    }

                    // ≡ƒö┤ Fill value
                    $table[$parameter][$date] = $data['value'];
                }
            }
        }


        return view('admin.patient.clinical.investigation_history.patient_invenstigation_tracking',compact('table','dates'));

    }
