    public function save_investigation_tracking_setup(Request $request)
    {
        $request->validate([
            'services' => 'required|array',
            'visit_id' => 'required'
        ]);
        $visit = Visitlog::findOrFail($request->visit_id);

        $existingServiceIds = \App\Models\DocPatientServiceTrack::where('doc_id', $visit->doctor_id)
            ->where('pat_id', $visit->patient_id)
            ->whereIn('service_id', $request->services)
            ->pluck('service_id')
            ->toArray();

        $newServices = array_diff($request->services, $existingServiceIds);
        $duplicateServices = array_intersect($request->services, $existingServiceIds);

        $data = [];

        foreach ($newServices as $serviceID) {
            $data[] = [
                'doc_id' => $visit->doctor_id,
                'pat_id' => $visit->patient_id,
                'service_id' => $serviceID,
                'active' => 1,
                'created_at' => now(),
                'updated_at' => now(),
            ];
        }


        if (!empty($data)) {
            \App\Models\DocPatientServiceTrack::insert($data);
        }
        $duplicateNames = \App\Models\admin\Service::whereIn('id', $duplicateServices)
                        ->pluck('service')
                        ->toArray();

        $message = 'Investigation Track Added';

        if (!empty($duplicateNames)) {
            $message .= '. ' . implode(', ', $duplicateNames) . ' already added and skipped';
        }
        return response()->json([
            'success' => true,
            'message' => $message
        ]);
    }
