    public function investigation_history_layout(Request $request)
    {
        $vid = $request->vid;
        $visit = $vid ? Visitlog::where('id', $vid)->first() : null;
        if (!$visit && $request->patient_id) {
            $visit = Visitlog::where('patient_id', $request->patient_id)->orderBy('id', 'desc')->first();
        }

        if (!$visit) {
            if ($request->get('format') === 'json' || $request->wantsJson()) {
                return response()->json(['success' => false, 'message' => 'Visit or patient record not found'], 404);
            }
            abort(404, 'Visit not found');
        }

        $orders = $this->getLabOrders(['patient_id' => $visit->patient_id, 'approved_only' => true, 'doctor_id'=>$visit->doctor_id]);

        if ($request->get('format') === 'json' || $request->wantsJson()) {
            $allParamIds = [];
            foreach ($orders as $order) {
                if (!empty($order->test_results)) {
                    $decoded = json_decode($order->test_results, true);
                    if (is_array($decoded)) {
                        foreach ($decoded as $group => $params) {
                            if (is_array($params)) {
                                foreach (array_keys($params) as $pid) {
                                    $allParamIds[] = $pid;
                                }
                            }
                        }
                    }
                }
            }

            $serviceNames = [];
            if (!empty($allParamIds)) {
                $serviceNames = \App\Models\admin\HospitalSer::whereIn('id', array_unique($allParamIds))
                    ->pluck('service', 'id')
                    ->toArray();
            }

            $formattedOrders = collect($orders ?? [])->map(function ($order) use ($serviceNames) {
                $billDate = $order->bill_date ? \Carbon\Carbon::parse($order->bill_date) : null;
                $formattedDate = $billDate ? $billDate->format('d M Y') : 'Unknown Date';

                $rows = [];
                if (!empty($order->test_results)) {
                    $decoded = json_decode($order->test_results, true);
                    if (is_array($decoded)) {
                        foreach ($decoded as $groupName => $params) {
                            if (!is_array($params)) continue;
                            foreach ($params as $paramId => $data) {
                                $name = $serviceNames[$paramId] ?? ('Test #' . $paramId);
                                $val = (isset($data['value']) && $data['value'] !== null && $data['value'] !== '') ? $data['value'] : '-';
                                $ref = (isset($data['biological_reference_range']) && $data['biological_reference_range'] !== null && $data['biological_reference_range'] !== '') ? $data['biological_reference_range'] : '-';
                                $rows[] = [
                                    (string)$name,
                                    (string)$val,
                                    (string)$ref
                                ];
                            }
                        }
                    }
                }

                return [
                    'id' => $order->id,
                    't' => $order->service_name ?? 'Investigation',
                    'd' => $formattedDate,
                    'rows' => $rows,
                    'status' => ucfirst($order->investigation_status ?? $order->status ?? 'Pending'),
                    'doctor' => $order->doctor_name ?? '',
                    'sample_time' => $order->sample_collect_time ? \Carbon\Carbon::parse($order->sample_collect_time)->format('d M Y, h:i A') : '',
                ];
            })->values();

            $patient = \App\Models\admin\Patient::find($visit->patient_id);
            $patientName = $patient ? trim(($patient->prefix ? $patient->prefix . ' ' : '') . ($patient->Fname ?? $patient->name ?? '') . ' ' . ($patient->Lname ?? '')) : '';

            return response()->json([
                'success' => true,
                'patient' => [
                    'id' => $visit->patient_id,
                    'name' => $patientName ?: ('Patient #' . $visit->patient_id),
                ],
                'orders' => $formattedOrders,
            ]);
        }

        return view('admin.patient.clinical.investigation_history.patient_invenstigation_history_layout', compact('orders', 'visit'));
    }
