    public function lab_dashboard()
    {
        $user = auth()->user();
        $hosp_id = $user->org_id;

        $hospital_setting = HospitalSetting::where([['hospital_id',1],['identifier','process_draft']])->first();
        $draft_process_status = $hospital_setting->status??0;

        $totals = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                        ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                                        ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                        ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                                        ->where('visitlog.hospital_id',$hosp_id)
                                        ->where('hospital_services.flag',"!=",'refund')
                                        ->where('hospital_services.flag',"!=",'balance')
                                        ->where('hospital_services.is_reserved',"=",0)
                                        ->select(
                                            'patient_gen_bill.*',
                                            'lab_investigations.sample_collect_time as collected_time',
                                            'lab_investigations.reporting_time as reporting_time',
                                            'lab_investigations.approval_time as approved_time',
                                            'lab_investigations.cancelled_at as rejected_time',
                                            'lab_investigations.status as status'
                                        )
                                        ->when($draft_process_status == 0, function ($query) use ($draft_process_status) {
                                            $query->where('patient_billing.status', 1);
                                        })->get();

        $total['total_orders']          = $totals->count();
        $total['sample_collected']      = $totals->whereNotNull('collected_time')->count();
        $total['report_approved']       = $totals->whereNotNull('approved_time')->count();
        $total['report_rejected']       = $totals->whereNotNull('rejected_time')->count();

        $pendings['orders']             = $totals->whereNull('collected_time')->whereNotIn('status', ['rejected', 'cancelled'])->count();
        $pendings['sample_collection']  = $totals->whereNull('collected_time')->whereNotIn('status', ['rejected', 'cancelled'])->count();
        $pendings['report_submit']      = $totals->whereNull('reporting_time')->whereNotNull('collected_time')->whereNotIn('status', ['rejected', 'cancelled'])->count();
        $pendings['report_approval']    = $totals->whereNull('approved_time')->whereNotNull('reporting_time')->whereNotIn('status', ['rejected', 'cancelled'])->count();

        // dd($total);
        // dd($totals->first());



        $patByDept = HospitalDoctor::join('doctor_db', 'doctor_db.id', '=', 'org_doc_index.doc_id')
                ->join('doctor_specialities', 'doctor_specialities.id', '=', 'doctor_db.key_spec')
                ->join('visitlog', 'visitlog.doctor_id', '=', 'doctor_db.id')
                ->select('doctor_db.key_spec', 'doctor_specialities.name AS speciality_name', DB::raw('COUNT(DISTINCT visitlog.patient_id) AS patient_count'))
                ->where('org_doc_index.org_id', $hosp_id)
                ->where('doctor_db.active', 1)
                ->where('org_doc_index.active', 1)
                ->groupBy('doctor_db.key_spec', 'doctor_specialities.name')  // Group by speciality
                ->orderBy('speciality_name', 'ASC')
                ->get();

        // dd($patByDept);
        return view('admin.patient.lab_test.lab_dashboard',compact('total','pendings','patByDept'));
    }
    public function lab_dashboard_month_chart_data(Request $request)
    {
        $hosp_id = auth()->user()->org_id;

        $month = $request->input('month', Carbon::now()->month);
        $year = $request->input('year', Carbon::now()->year);

        $daysInMonth = Carbon::create($year, $month, 1)->daysInMonth;

        // If selected month is the current month, limit to today's date
        $lastDay = ($month == Carbon::now()->month && $year == Carbon::now()->year)
            ? Carbon::now()->day
            : $daysInMonth;

        $dailyStats = collect([]);

        for ($day = 1; $day <= $lastDay; $day++) {
            $date = Carbon::create($year, $month, $day)->toDateString();

            $totals = PatientGenBill::leftJoin('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
                ->join('patient_billing', 'patient_billing.id', '=', 'patient_gen_bill.bill_id')
                ->join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                ->where('visitlog.hospital_id', $hosp_id)
                ->where('hospital_services.flag', '!=', 'refund')
                ->where('hospital_services.flag', '!=', 'balance')
                ->where('hospital_services.is_reserved', '=', 0)
                ->whereDate('patient_gen_bill.created_at', $date) // Filter by date
                ->select(
                    'patient_gen_bill.*',
                    'lab_investigations.sample_collect_time as collected_time',
                    'lab_investigations.reporting_time as reporting_time',
                    'lab_investigations.approval_time as approved_time',
                    'lab_investigations.cancelled_at as rejected_time',
                    'lab_investigations.status as status'
                )
                ->when($request->input('draft_process_status', 0) == 0, function ($query) {
                    $query->where('patient_billing.status', 1);
                })
                ->get();

            // Collect daily statistics
            $dailyStats->push([
                'day'               => $day,
                'total_orders'      => $totals->count(),
                'sample_collected'  => $totals->whereNotNull('collected_time')->count(),
                'report_approved'   => $totals->whereNotNull('approved_time')->count(),
                'report_rejected'   => $totals->whereNotNull('rejected_time')->count(),
            ]);
        }

        return response()->json([
            'success' => true,
            'data' => $dailyStats
        ]);

    }

    
    public function lab_test_orders(Request $request)
    {
        $user = auth()->user();
        $hosp_id = $user->org_id;


        // $hospital_setting = HospitalSetting::where([['hospital_id',1],['identifier','process_draft']])->first();
        // $draft_process_status = $hospital_setting->status??0;
        // $hospital_setting = HospitalSetting::where([['hospital_id',1],['identifier','draft_print_report']])->first();
        // $draft_print_status = $hospital_setting->status??0;

        $draft_process_status = HospitalSettingCache::getStatus($hosp_id,'process_draft',0);

        $draft_print_status = HospitalSettingCache::getStatus($hosp_id,'draft_print_report',0);


        $tests = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                    ->join('hospital_services_index','hospital_services.id','hospital_services_index.service')
                    ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                    //->leftJoin('billing_payment_type','billing_payment_type.bill_id','=','patient_billing.id')
                    ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                    ->join('pi','pi.id','=','visitlog.patient_id')
                    // ->leftJoin('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                    // ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                    ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                    ->select('patient_gen_bill.*',
                        'hospital_services.service as service_name',
                        'hospital_services.group_attributes as group_attributes',
                        \DB::raw("JSON_UNQUOTE(JSON_EXTRACT(hospital_services.group_attributes, '$.tat')) as tat"),
                        // \DB::raw("(
                        //     SELECT COUNT(*)
                        //     FROM stock_adjustments
                        //     WHERE stock_adjustments.order_id = patient_gen_bill.id
                        //     AND stock_adjustments.deleted_at IS NULL
                        // ) as consumption_count"),
                        // 'doctor_db.name as doctor_name',
                        'visitlog.doctor_id',
                        'pi.i_cover',
                        'pi.id as uhid',
                        'pi.dob',
                        'patient_gen_bill.created_at as bill_date',
                        'patient_gen_bill.id as pGen_bill_id',
                        'pi.prefix as prefix',
                        'pi.Fname as patient_first_name',
                        'pi.Lname as patient_last_name',
                        'pi.age as age',
                        'pi.sex as sex',
                        'pi.mobile_no as phone',
                        'pi.mnvs as mnvs',
                        // 'health_insurance_agen.insurance_agen as insurance',
                        'lab_investigations.id as lab_investigation_id',
                        'lab_investigations.in_process as in_process',
                        'lab_investigations.status as investigation_status',
                        'lab_investigations.sample_collect_time as sample_collect_time',
                        'lab_investigations.reporting_time as reporting_time',
                        'lab_investigations.approval_time as approval_time',
                        'lab_investigations.approved_by as approved_by',
                        'lab_investigations.approval_status as approval_status',
                        'lab_investigations.status as status',
                        'lab_investigations.updated_at as last_update',
                        'lab_investigations.is_outsource as is_outsource',
                        'hospital_services_index.is_outsource as outsourced',
                        'patient_billing.id as pbill_id',
                        'patient_billing.status as pbill_status',
                        'patient_billing.status as draft_status',
                        'patient_billing.discount as pbill_discount',
                        'visitlog.visit_status',
                        'visitlog.emergency'
                        )
                    ->where('visitlog.hospital_id',$hosp_id)
                    ->where('hospital_services.flag',"test")
                    // ->where('hospital_services.flag',"!=",'refund')
                    // ->where('hospital_services.flag',"!=",'balance')
                    ->where('patient_gen_bill.is_deleted',0)
                    ->whereNull('patient_gen_bill.is_cancelled')
                    ->where('hospital_services.is_reserved',"=",0)
                    ->addSelect([
                        'consumption_count' => DB::table('stock_adjustments')
                            ->selectRaw('COUNT(*)')
                            ->whereColumn(
                                'stock_adjustments.order_id',
                                'patient_gen_bill.id'
                            )
                            ->whereNull('stock_adjustments.deleted_at'),
                        // Payments for the current bill only
                        'paid_amount' => DB::table('billing_payment_type')
                            ->selectRaw("
                                COALESCE(SUM(
                                    CASE
                                        WHEN transaction_type = 0 THEN amount
                                        WHEN transaction_type = 1 THEN -amount
                                        ELSE 0
                                    END
                                ), 0)
                            ")
                            ->whereColumn(
                                'billing_payment_type.bill_id',
                                'patient_billing.id'
                            ),
                        // Bill total for the current bill only
                        'bill_amount' => DB::table('patient_gen_bill as pgb_sub')
                            ->selectRaw("
                                COALESCE(SUM(
                                    (pgb_sub.charges * pgb_sub.qty) - COALESCE(pgb_sub.discount, 0)
                                ), 0)
                            ")
                            ->whereColumn(
                                'pgb_sub.bill_id',
                                'patient_billing.id'
                            )
                            ->where(function ($q) {
                                $q->whereNull('pgb_sub.is_cancelled')
                                ->orWhere('pgb_sub.is_cancelled', 0);
                            })
                            ->where(function ($q) {
                                $q->whereNull('pgb_sub.is_deleted')
                                ->orWhere('pgb_sub.is_deleted', 0);
                            }),
                         
                    ]);
        if($request->uhid??false){
             $tests->where('pi.id',$request->uhid);
        }
        else if($request->name??false){
            $tests->where('pi.Fname','like','%'.$request->name.'%');
        }
        else if($request->mobile??false){
            $tests->where('pi.mobile_no',$request->mobile);
        }
        else if($request->bill_id??false){
            $tests->where('patient_billing.id',$request->bill_id);
        }
        else{
            $tests->whereDate('patient_gen_bill.created_at', '>=', $request->from_date??date('Y-m-d'));
            $tests->whereDate('patient_gen_bill.created_at', '<=', $request->end_date??date('Y-m-d'));
        }

        $status = $request->order_status??'all';
        if($status == 'all'){

        }
        else if($status == 'sample_pending'){
            $tests->whereNull('lab_investigations.status');
        }
        else if($status == 'report_pending'){
            $tests->whereIn('lab_investigations.status',['collected','submitted']);
            $tests->where('lab_investigations.in_process',0);
        }
        else if($status == 'report_in_process'){
            $tests->whereIn('lab_investigations.status',['collected','submitted']);
            $tests->where('lab_investigations.in_process',1);
        }
        else if($status == 'approval_pending'){
            $tests->where('lab_investigations.status','=','submitted');
            $tests->where('lab_investigations.approval_status',1);
        }
        else if($status == 'completed'){
            if(($request->print_status??'') == 'printed'){
                $tests->where('lab_investigations.is_printed',1);
            }
            elseif(($request->print_status??'') == 'not_printed'){
                $tests->where('lab_investigations.is_printed',0);
            }
            $tests->where('lab_investigations.status','=','approved');
        }
        else if($status == 'cancelled'){
            $tests->where('lab_investigations.status','=','cancelled');
        }


         $lab_order_list_version = HospitalSettingCache::get(auth()->user()->org_id, 'lab_order_page','v1');

        if($lab_order_list_version == 'v1'){
            $reporting_location = $request->reporting_location??'';
            
            if($reporting_location == 'inhouse'){
                $tests->where(function ($query) {
                    $query->where('hospital_services_index.is_outsource', 0);
                });
            }elseif($reporting_location == 'outsource'){
                $tests->where('hospital_services_index.is_outsource', 1);
            }
        }else{

            $reporting_location = $request->reporting_location??'';
            
            if($reporting_location == 'inhouse'){
                $tests->where(function ($query) {
                    $query->where('lab_investigations.is_outsource', 0)
                        ->orWhereNull('lab_investigations.is_outsource');
                });
            }elseif($reporting_location == 'outsource'){
                $tests->where('lab_investigations.is_outsource', 1);
            }

        }

        // $reporting_location = $request->reporting_location??'';
        // if($reporting_location == 'inhouse'){
        //     $tests->where(function ($query) {
        //         $query->where('lab_investigations.is_outsource', 0)
        //               ->orWhereNull('lab_investigations.is_outsource');
        //     });
        // }elseif($reporting_location == 'outsource'){
        //     $tests->where('lab_investigations.is_outsource', 1);
        // }

        $tatFilter = $request->tat ?? null;
        if ($tatFilter) {
            $now = \Carbon\Carbon::now();

            $tests->whereNotNull('hospital_services.group_attributes'); // safeguard
            $tests->where('lab_investigations.status','!=','approved'); // safeguard

            if ($tatFilter == 'over_tat') {
                // sample_time + tat < now
                $tests->whereRaw("
                    TIMESTAMPADD(HOUR,
                        CAST(JSON_UNQUOTE(JSON_EXTRACT(hospital_services.group_attributes, '$.tat')) AS UNSIGNED),
                        lab_investigations.sample_collect_time
                    ) < ?", [$now]);
            }
            else if ($tatFilter == 'near_tat') {
                // within 15 minutes window before deadline
                $tests->whereRaw("
                    TIMESTAMPADD(HOUR,
                        CAST(JSON_UNQUOTE(JSON_EXTRACT(hospital_services.group_attributes, '$.tat')) AS UNSIGNED),
                        lab_investigations.sample_collect_time
                    ) BETWEEN ? AND ?
                ", [$now, $now->copy()->addMinutes(15)]);
            }
            else if ($tatFilter == 'within_tat') {
                // sample_time + tat > now + 15 minutes
                $tests->whereRaw("
                    TIMESTAMPADD(HOUR,
                        CAST(JSON_UNQUOTE(JSON_EXTRACT(hospital_services.group_attributes, '$.tat')) AS UNSIGNED),
                        lab_investigations.sample_collect_time
                    ) > ?", [$now->copy()->addMinutes(15)]);
            }
        }

        if (!empty($request->service)) {
            $tests->whereIn('patient_gen_bill.service_id', $request->service);
        }

        $tests->when($draft_process_status == 0, function ($query) use ($draft_process_status) {
                    $query->where('patient_billing.status', 1);
                });
        $testList = $tests->orderBy('patient_gen_bill.id','DESC')->paginate(50)->withQueryString();

        $testList->getCollection()->transform(function ($item) {
            $paid = (float) ($item->paid_amount ?? 0);
            $bill = (float) ($item->bill_amount ?? 0);
            $discount = (float) ($item->pbill_discount ?? 0);
            $net = $bill - $discount;

            if ($paid == $net) {
                $item->payment_status = 'FP';
            } elseif ($paid > 0 && $paid < $net) {
                $item->payment_status = 'PP';
            } elseif ($paid == 0 && $net > 0) {
                $item->payment_status = 'UP';
            } else {
                $item->payment_status = 'UP';
            }
            return $item;
        });


        // return $testList;

        // Service filter
        // $services = HospitalService::from('hospital_services_index as hsi')
        //             ->join('hospital_services as hs', 'hs.id', '=', 'hsi.service')
        //             ->where('hsi.hospital_id', $hosp_id)
        //             ->where('hsi.active', 1)
        //             ->pluck('hs.service', 'hs.id');

        $services = HospitalServiceCache::all($hosp_id);


        $orderIds = collect($testList->items())->pluck('id');

        $serviceIds = collect($testList->items())
                        ->pluck('service_id')
                        ->unique();

        $lab_orders_Ids = collect($testList->items())
                                    ->pluck('id')
                                    ->unique();

        $lisMappings = DB::table('lis_service_mapping')
                                ->whereIn('service_id', $serviceIds)
                                ->where('hospital_id', $hosp_id)
                                ->where('active', 1)
                                ->get()
                                ->groupBy('service_id');

        $allSamples = DB::table('lab_sample_labels')
                            ->where(function ($query) use ($lab_orders_Ids) {
                                foreach ($lab_orders_Ids as $id) {
                                    $query->orWhereJsonContains('lab_order_ids', $id);
                                }
                            })
                            ->get();


        $smsCounts = \App\Models\SmsLog::selectRaw('foreign_id, COUNT(*) as total')
                                            ->where('m_t', 'lab_investigation')
                                            ->whereIn('foreign_id', $lab_orders_Ids)
                                            ->groupBy('foreign_id')
                                            ->pluck('total', 'foreign_id')
                                            ->toArray();

        $samplesByLabOrder = DB::table('lab_sample_labels')
                                    ->whereIn('lab_order_id', $lab_orders_Ids)
                                    ->get()
                                    ->groupBy('lab_order_id');


        $samplesByOrder = [];

        foreach ($allSamples as $sample) {

            foreach (json_decode($sample->lab_order_ids, true) ?? [] as $orderId) {

                $samplesByOrder[$orderId][] = $sample;

            }
        }


        $insurances = InsuranceCache::all($hosp_id);
        $doctors = DoctorCache::all($hosp_id);

        // $lab_order_list_version = HospitalSetting::where('hospital_id',auth()->user()->org_id)
        //                     ->where('identifier','lab_order_page')
        //                     ->first()->current_setting??'v1';

        // $lab_order_list_version = HospitalSettingCache::get(auth()->user()->org_id, 'lab_order_page','v1');

    
        if ($request->ajax())
        {
            return view('admin.patient.lab_test.lab_report_table_'.$lab_order_list_version, compact('testList','draft_print_status','services','samplesByOrder','lisMappings','samplesByLabOrder','insurances','doctors'))->render();
        }


        return view('admin.patient.lab_test.lab_test_orders',compact('testList','draft_print_status','lab_order_list_version','services','samplesByOrder','lisMappings','samplesByLabOrder','insurances','doctors'));
    }


    public function lab_test_orders_outsource(Request $request)
    {
        $user = auth()->user();
        $hosp_id = $user->org_id;


        // $hospital_setting = HospitalSetting::where([['hospital_id',1],['identifier','process_draft']])->first();
        // $draft_process_status = $hospital_setting->status??0;
        // $hospital_setting = HospitalSetting::where([['hospital_id',1],['identifier','draft_print_report']])->first();
        // $draft_print_status = $hospital_setting->status??0;

        $draft_process_status = HospitalSettingCache::getStatus($hosp_id,'process_draft',0);

        $draft_print_status = HospitalSettingCache::getStatus($hosp_id,'draft_print_report',0);

        $paymentSummary = DB::table('billing_payment_type')
                                ->select(
                                    'bill_id',
                                    DB::raw("
                                        SUM(
                                            CASE
                                                WHEN transaction_type = 0 THEN amount
                                                WHEN transaction_type = 1 THEN -amount
                                                ELSE 0
                                            END
                                        ) as paid_amount
                                    ")
                                )
                                ->groupBy('bill_id');

            $billSummary = DB::table('patient_gen_bill')
                                    ->select(
                                        'bill_id',
                                        DB::raw("
                                            SUM((charges*qty)-COALESCE(discount,0))
                                            as bill_amount
                                        ")
                                    )
                                    ->where(function($q){
                                        $q->whereNull('is_cancelled')
                                        ->orWhere('is_cancelled',0);
                                    })
                                    ->where(function($q){
                                        $q->whereNull('is_deleted')
                                        ->orWhere('is_deleted',0);
                                    })
                                    ->groupBy('bill_id');


            $consumptionSummary = DB::table('stock_adjustments')
                                        ->select(
                                            'order_id',
                                            DB::raw('COUNT(*) as consumption_count')
                                        )
                                        ->whereNull('deleted_at')
                                        ->groupBy('order_id');

        $tests = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                    ->leftJoin('hospital_services_index','hospital_services.id','=','hospital_services_index.service')
                    ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                    //->leftJoin('billing_payment_type','billing_payment_type.bill_id','=','patient_billing.id')
                    ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                    ->join('pi','pi.id','=','visitlog.patient_id')
                    // ->leftJoin('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                    // ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                    ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                    ->leftJoin('outsource_labs', 'outsource_labs.id', '=', 'patient_gen_bill.outsource_lab_id')
                    ->select('patient_gen_bill.*',
                        'hospital_services.service as service_name',
                        'hospital_services.group_attributes as group_attributes',
                        \DB::raw("JSON_UNQUOTE(JSON_EXTRACT(hospital_services.group_attributes, '$.tat')) as tat"),
                        // \DB::raw("(
                        //     SELECT COUNT(*)
                        //     FROM stock_adjustments
                        //     WHERE stock_adjustments.order_id = patient_gen_bill.id
                        //     AND stock_adjustments.deleted_at IS NULL
                        // ) as consumption_count"),
                        // 'doctor_db.name as doctor_name',
                        'visitlog.doctor_id',
                        'pi.i_cover',
                        'pi.id as uhid',
                        'pi.dob',
                        'patient_gen_bill.created_at as bill_date',
                        'patient_gen_bill.id as pGen_bill_id',
                        'patient_gen_bill.outsource_lab_id as outsource_lab_id',
                        'patient_gen_bill.cost as outsource_cost',
                        'outsource_labs.name as outsource_lab_name',
                        'pi.prefix as prefix',
                        'pi.Fname as patient_first_name',
                        'pi.Lname as patient_last_name',
                        'pi.age as age',
                        'pi.sex as sex',
                        'pi.mobile_no as phone',
                        'pi.mnvs as mnvs',
                        // 'health_insurance_agen.insurance_agen as insurance',
                        'lab_investigations.id as lab_investigation_id',
                        'lab_investigations.in_process as in_process',
                        'lab_investigations.status as investigation_status',
                        'lab_investigations.sample_collect_time as sample_collect_time',
                        'lab_investigations.reporting_time as reporting_time',
                        'lab_investigations.approval_time as approval_time',
                        'lab_investigations.approved_by as approved_by',
                        'lab_investigations.approval_status as approval_status',
                        'lab_investigations.status as status',
                        'lab_investigations.updated_at as last_update',
                        'lab_investigations.is_outsource as is_outsource',
                        'lab_investigations.follow_up as follow_up',
                        'lab_investigations.test_results as test_results',
                        'patient_billing.id as pbill_id',
                        'patient_billing.status as pbill_status',
                        'patient_billing.status as draft_status',
                        'visitlog.visit_status',
                        'visitlog.emergency',
                        DB::raw('COALESCE(consumption.consumption_count,0) as consumption_count'),
                        'hospital_services_index.is_outsource as is_outsource',
                        )
                    ->where('visitlog.hospital_id',$hosp_id)
                    ->where('hospital_services.flag',"test")
                    // ->where('hospital_services.flag',"!=",'refund')
                    // ->where('hospital_services.flag',"!=",'balance')
                    ->where('patient_gen_bill.is_deleted',0)
                    ->whereNull('patient_gen_bill.is_cancelled')
                    ->where('hospital_services.is_reserved',"=",0)
                    ->where('hospital_services_index.is_outsource',"=",1)

                    ->leftJoinSub($paymentSummary,'payments',function($join){
                                    $join->on('payments.bill_id','=','patient_billing.id');
                                 })

                    ->leftJoinSub($billSummary,'bill_total',function($join){
                        $join->on('bill_total.bill_id','=','patient_billing.id');
                    })
                    ->leftJoinSub($consumptionSummary, 'consumption', function ($join) {
                        $join->on('consumption.order_id', '=', 'patient_gen_bill.id');
                    })

                    ->addSelect(DB::raw("
                                            CASE

                                                WHEN COALESCE(payments.paid_amount,0)
                                                    =
                                                    (COALESCE(bill_total.bill_amount,0)
                                                        - COALESCE(patient_billing.discount,0))

                                                THEN 'FP'

                                                WHEN COALESCE(payments.paid_amount,0) > 0
                                                    AND
                                                    COALESCE(payments.paid_amount,0)
                                                    <
                                                    (COALESCE(bill_total.bill_amount,0)
                                                        - COALESCE(patient_billing.discount,0))

                                                THEN 'PP'

                                                WHEN COALESCE(payments.paid_amount,0) = 0
                                                    AND
                                                    (COALESCE(bill_total.bill_amount,0)
                                                        - COALESCE(patient_billing.discount,0)) > 0

                                                THEN 'UP'

                                                ELSE 'UP'

                                            END AS payment_status
                                        "));

        if($request->uhid??false){
             $tests->where('pi.id',$request->uhid);
        }
        else if($request->name??false){
            $tests->where(function($q) use ($request) {
                $q->where('pi.Fname','like','%'.$request->name.'%')
                  ->orWhere('pi.Lname','like','%'.$request->name.'%');
            });
        }
        else if($request->mobile??false){
            $tests->where('pi.mobile_no',$request->mobile);
        }
        else if($request->bill_id??false){
            $tests->where('patient_billing.id',$request->bill_id);
        }
        else if (empty($request->follow_up_filter) && empty($request->follow_up_date)) {
            $tests->whereDate('patient_gen_bill.created_at', '>=', $request->from_date??date('Y-m-d'));
            $tests->whereDate('patient_gen_bill.created_at', '<=', $request->end_date??date('Y-m-d'));
        }

        $todayDate = \Carbon\Carbon::today()->toDateString();
        $tomorrowDate = \Carbon\Carbon::tomorrow()->toDateString();

        if (($request->follow_up_filter ?? '') == 'today') {
            $tests->whereDate('lab_investigations.follow_up', '=', $todayDate);
        } else if (($request->follow_up_filter ?? '') == 'tomorrow') {
            $tests->whereDate('lab_investigations.follow_up', '=', $tomorrowDate);
        } else if (($request->follow_up_filter ?? '') == 'upcoming') {
            $tests->whereDate('lab_investigations.follow_up', '>', $todayDate);
        } else if (($request->follow_up_filter ?? '') == 'overdue') {
            $tests->whereDate('lab_investigations.follow_up', '<', $todayDate);
        } else if (($request->follow_up_filter ?? '') == 'due') {
            $tests->whereDate('lab_investigations.follow_up', '<=', $todayDate);
        } else if ($request->follow_up_date ?? false) {
            $tests->whereDate('lab_investigations.follow_up', '=', $request->follow_up_date);
        }

        if ($request->outsource_lab_id ?? false) {
            if ($request->outsource_lab_id == 'unassigned') {
                $tests->whereNull('patient_gen_bill.outsource_lab_id');
            } else {
                $tests->where('patient_gen_bill.outsource_lab_id', $request->outsource_lab_id);
            }
        }

        $status = $request->order_status??'all';
        if($status == 'all'){

        }
        else if($status == 'sample_pending'){
            $tests->whereNull('lab_investigations.status');
        }
        else if($status == 'report_pending'){
            $tests->whereIn('lab_investigations.status',['collected','submitted']);
            $tests->where('lab_investigations.in_process',0);
        }
        else if($status == 'report_in_process'){
            $tests->whereIn('lab_investigations.status',['collected','submitted']);
            $tests->where('lab_investigations.in_process',1);
        }
        else if($status == 'approval_pending'){
            $tests->where('lab_investigations.status','=','submitted');
            $tests->where('lab_investigations.approval_status',1);
        }
        else if($status == 'completed'){
            if(($request->print_status??'') == 'printed'){
                $tests->where('lab_investigations.is_printed',1);
            }
            elseif(($request->print_status??'') == 'not_printed'){
                $tests->where('lab_investigations.is_printed',0);
            }
            $tests->where('lab_investigations.status','=','approved');
        }
        else if($status == 'cancelled'){
            $tests->where('lab_investigations.status','=','cancelled');
        }

        // $reporting_location = $request->reporting_location??'';
        // if($reporting_location == 'inhouse'){
        //     $tests->where(function ($query) {
        //         $query->where('lab_investigations.is_outsource', 0)
        //               ->orWhereNull('lab_investigations.is_outsource');
        //     });
        // }elseif($reporting_location == 'outsource'){
            // $tests->where('lab_investigations.is_outsource', 1);
        // }

        $tatFilter = $request->tat ?? null;
        if ($tatFilter) {
            $now = \Carbon\Carbon::now();

            $tests->whereNotNull('hospital_services.group_attributes'); // safeguard
            $tests->where('lab_investigations.status','!=','approved'); // safeguard

            if ($tatFilter == 'over_tat') {
                // sample_time + tat < now
                $tests->whereRaw("
                    TIMESTAMPADD(HOUR,
                        CAST(JSON_UNQUOTE(JSON_EXTRACT(hospital_services.group_attributes, '$.tat')) AS UNSIGNED),
                        lab_investigations.sample_collect_time
                    ) < ?", [$now]);
            }
            else if ($tatFilter == 'near_tat') {
                // within 15 minutes window before deadline
                $tests->whereRaw("
                    TIMESTAMPADD(HOUR,
                        CAST(JSON_UNQUOTE(JSON_EXTRACT(hospital_services.group_attributes, '$.tat')) AS UNSIGNED),
                        lab_investigations.sample_collect_time
                    ) BETWEEN ? AND ?
                ", [$now, $now->copy()->addMinutes(15)]);
            }
            else if ($tatFilter == 'within_tat') {
                // sample_time + tat > now + 15 minutes
                $tests->whereRaw("
                    TIMESTAMPADD(HOUR,
                        CAST(JSON_UNQUOTE(JSON_EXTRACT(hospital_services.group_attributes, '$.tat')) AS UNSIGNED),
                        lab_investigations.sample_collect_time
                    ) > ?", [$now->copy()->addMinutes(15)]);
            }
        }

        if (!empty($request->service)) {
            $tests->whereIn('patient_gen_bill.service_id', $request->service);
        }

        $tests->when($draft_process_status == 0, function ($query) use ($draft_process_status) {
                    $query->where('patient_billing.status', 1);
                });
        $testList = $tests->orderBy('patient_gen_bill.id','DESC')->paginate(50)->withQueryString();


        // return $testList;

        // Service filter
        // $services = HospitalService::from('hospital_services_index as hsi')
        //             ->join('hospital_services as hs', 'hs.id', '=', 'hsi.service')
        //             ->where('hsi.hospital_id', $hosp_id)
        //             ->where('hsi.active', 1)
        //             ->pluck('hs.service', 'hs.id');

        $services = HospitalServiceCache::all($hosp_id);


        $orderIds = collect($testList->items())->pluck('id');

        $serviceIds = collect($testList->items())
                        ->pluck('service_id')
                        ->unique();

        $lab_orders_Ids = collect($testList->items())
                                    ->pluck('id')
                                    ->unique();

        $lisMappings = DB::table('lis_service_mapping')
                                ->whereIn('service_id', $serviceIds)
                                ->where('hospital_id', $hosp_id)
                                ->where('active', 1)
                                ->get()
                                ->groupBy('service_id');

        $allSamples = DB::table('lab_sample_labels')
                            ->where(function ($query) use ($lab_orders_Ids) {
                                foreach ($lab_orders_Ids as $id) {
                                    $query->orWhereJsonContains('lab_order_ids', $id);
                                }
                            })
                            ->get();



        $smsCounts = \App\Models\SmsLog::selectRaw('foreign_id, COUNT(*) as total')
                                            ->where('m_t', 'lab_investigation')
                                            ->whereIn('foreign_id', $lab_orders_Ids)
                                            ->groupBy('foreign_id')
                                            ->pluck('total', 'foreign_id')
                                            ->toArray();

        $samplesByLabOrder = DB::table('lab_sample_labels')
                                    ->whereIn('lab_order_id', $lab_orders_Ids)
                                    ->get()
                                    ->groupBy('lab_order_id');


        $samplesByOrder = [];

        foreach ($allSamples as $sample) {

            foreach (json_decode($sample->lab_order_ids, true) ?? [] as $orderId) {

                $samplesByOrder[$orderId][] = $sample;

            }
        }


        $insurances = InsuranceCache::all($hosp_id);
        $doctors = DoctorCache::all($hosp_id);
        $labs = \App\Models\OutSourceLab::where('hospital_id', $hosp_id)->where('active', 1)->orderBy('name', 'asc')->get();

        $lab_order_list_version = 'v1';

        if ($request->ajax())
        {
            return view('admin.patient.lab_test.lab_report_table_outsource', compact('testList','draft_print_status','services','samplesByOrder','lisMappings','samplesByLabOrder','insurances','doctors','labs'))->render();
        }

        return view('admin.patient.lab_test.lab_test_orders_outsource',compact('testList','draft_print_status','lab_order_list_version','services','samplesByOrder','lisMappings','samplesByLabOrder','insurances','doctors','labs'));
    }

