                'lab_investigations.reporting_time as reporting_time',
                'lab_investigations.approval_time as approval_time',
                'lab_investigations.approved_by as approved_by',
                'lab_investigations.approval_status as approval_status',
                'lab_investigations.status as status',
                'lab_investigations.updated_at as last_update',
                'lab_investigations.is_outsource as is_outsource',
                'lab_investigations.follow_up as follow_up',
                'lab_investigations.other_remarks as follow_up_notes',
                'lab_investigations.test_results as test_results',
                'lab_investigations.is_printed as is_printed',
                'patient_billing.id as pbill_id',
                'patient_billing.status as pbill_status',
                'patient_billing.status as draft_status',
                'visitlog.visit_status',
                'visitlog.emergency'
            )
            ->where('visitlog.hospital_id', $hosp_id)
            ->where('hospital_services.flag', "test")
            ->where('patient_gen_bill.is_deleted', 0)
            ->where(function($q) {
                $q->whereNull('patient_gen_bill.is_cancelled')->orWhere('patient_gen_bill.is_cancelled', 0);
            })
            ->where('hospital_services.is_reserved', 0)
            ->where(function ($q) {
                $q->where('hospital_services_index.is_outsource', 1)
                  ->orWhereNotNull('patient_gen_bill.outsource_lab_id');
            });
            // ->leftJoinSub($paymentSummary, 'payments', function($join) {
            //     $join->on('payments.bill_id', '=', 'patient_billing.id');
            // })
            // ->leftJoinSub($billSummary, 'bill_total', function($join) {
            //     $join->on('bill_total.bill_id', '=', 'patient_billing.id');
            // });

        // Search filters
        $hasSpecificSearch = $request->filled('uhid') || $request->filled('bill_id') || $request->filled('mobile') || $request->filled('name');
        $hasFollowUpFilter = !empty($request->follow_up_filter) || !empty($request->follow_up_date);

        if ($request->filled('uhid')) {
            $tests->where('pi.id', $request->uhid);
        } elseif ($request->filled('name')) {
            $name = $request->name;
            $tests->where(function($q) use ($name) {
                $q->where('pi.Fname', 'like', "%{$name}%")
                  ->orWhere('pi.Lname', 'like', "%{$name}%")
                  ->orWhere(\DB::raw("CONCAT(COALESCE(pi.Fname, ''), ' ', COALESCE(pi.Lname, ''))"), 'like', "%{$name}%");
            });
        } elseif ($request->filled('mobile')) {
            $tests->where('pi.mobile_no', 'like', "%{$request->mobile}%");
        } elseif ($request->filled('bill_id')) {
            $tests->where('patient_billing.id', $request->bill_id);
        }

        $followUpFilter = $request->input('follow_up_filter');
        $hasFollowUpFilter = !empty($followUpFilter) || !empty($request->follow_up_date);

        // Date filter
        $fromDate = $request->input('from_date');
        $toDate = $request->input('to_date', $request->input('end_date'));

        if (!$hasSpecificSearch && !$hasFollowUpFilter && !$request->filled('from_date') && !$request->filled('to_date') && !$request->filled('end_date')) {
            $fromDate = date('Y-m-d');
            $toDate = date('Y-m-d');
        }

        if (!$hasFollowUpFilter) {
            if ($fromDate) {
                $tests->whereDate('patient_gen_bill.created_at', '>=', $fromDate);
            }
            if ($toDate) {
                $tests->whereDate('patient_gen_bill.created_at', '<=', $toDate);
            }
        }

        // Follow-up date filter
        $todayDate = \Carbon\Carbon::today()->toDateString();
        $tomorrowDate = \Carbon\Carbon::tomorrow()->toDateString();
        $in7DaysDate = \Carbon\Carbon::today()->addDays(7)->toDateString();

        if ($followUpFilter == 'today') {
            $tests->whereDate('lab_investigations.follow_up', '=', $todayDate);
        } elseif ($followUpFilter == 'tomorrow') {
            $tests->whereDate('lab_investigations.follow_up', '=', $tomorrowDate);
        } elseif ($followUpFilter == 'upcoming' || $followUpFilter == 'in_7_days') {
            $tests->whereDate('lab_investigations.follow_up', '>=', $todayDate)
                  ->whereDate('lab_investigations.follow_up', '<=', $in7DaysDate);
        } elseif ($followUpFilter == 'overdue') {
            $tests->whereDate('lab_investigations.follow_up', '<', $todayDate)
                  ->whereNotNull('lab_investigations.follow_up');
        } elseif ($followUpFilter == 'due') {
            $tests->whereDate('lab_investigations.follow_up', '<=', $todayDate)
                  ->whereNotNull('lab_investigations.follow_up');
        } elseif ($followUpFilter == 'not_set') {
            $tests->whereNull('lab_investigations.follow_up');
        } elseif ($followUpFilter == 'set') {
            $tests->whereNotNull('lab_investigations.follow_up');
        } elseif ($request->filled('follow_up_date')) {
            $tests->whereDate('lab_investigations.follow_up', '=', $request->follow_up_date);
        }

        // Outsource lab filter
        $labFilter = $request->input('lab_id', $request->input('outsource_lab_id'));
        $labFilterRadio = $request->input('lab_filter');
        if ($labFilterRadio === 'unassigned') {
            $tests->whereNull('patient_gen_bill.outsource_lab_id');
        } elseif ($labFilterRadio === 'assigned') {
            $tests->whereNotNull('patient_gen_bill.outsource_lab_id');
        } elseif ($labFilter) {
            if ($labFilter === 'unassigned') {
                $tests->whereNull('patient_gen_bill.outsource_lab_id');
            } elseif ($labFilter === 'assigned') {
                $tests->whereNotNull('patient_gen_bill.outsource_lab_id');
            } else {
                $tests->where('patient_gen_bill.outsource_lab_id', $labFilter);
            }
        }

        // Order Status Pipeline
        $status = $request->order_status ?? 'all';
        if ($status == 'lab_unassigned') {
            $tests->whereNull('patient_gen_bill.outsource_lab_id');
        } elseif ($status == 'sample_pending') {
            $tests->whereNull('lab_investigations.status');
        } elseif ($status == 'report_pending') {
            $tests->whereIn('lab_investigations.status', ['collected', 'submitted'])
                  ->where('lab_investigations.in_process', 0);
        } elseif ($status == 'report_in_process') {
            $tests->whereIn('lab_investigations.status', ['collected', 'submitted'])
                  ->where('lab_investigations.in_process', 1);
        } elseif ($status == 'approval_pending') {
            $tests->where('lab_investigations.status', '=', 'submitted')
                  ->where('lab_investigations.approval_status', 1);
        } elseif ($status == 'completed') {
            $tests->where('lab_investigations.status', '=', 'approved');
            if (($request->print_status ?? '') == 'printed') {
                $tests->where('lab_investigations.is_printed', 1);
            } elseif (($request->print_status ?? '') == 'not_printed') {
                $tests->where('lab_investigations.is_printed', 0);
            }
        } elseif ($status == 'cancelled') {
            $tests->where('lab_investigations.status', '=', 'cancelled');
        }

        // Service filter
        if ($request->filled('service_id')) {
            $tests->where('patient_gen_bill.service_id', $request->service_id);
        } elseif (!empty($request->service)) {
            $serviceArr = is_array($request->service) ? $request->service : [$request->service];
            $tests->whereIn('patient_gen_bill.service_id', $serviceArr);
        }

        // Draft handling
        $tests->when($draft_process_status == 0, function ($query) {
            $query->where('patient_billing.status', 1);
        });

        // Compute KPI Summary Stats based on date & search filters
        $kpiBase = PatientGenBill::leftJoin('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
            ->leftJoin('hospital_services_index', function ($join) use ($hosp_id) {
                $join->on('hospital_services_index.service', '=', 'hospital_services.id')
                    ->where('hospital_services_index.hospital_id', '=', $hosp_id);
            })
            ->join('patient_billing', 'patient_billing.id', '=', 'patient_gen_bill.bill_id')
            ->join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
            ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
            ->where('visitlog.hospital_id', $hosp_id)
            ->where('hospital_services.flag', "test")
            ->where('patient_gen_bill.is_deleted', 0)
            ->where(function($q) {
                $q->whereNull('patient_gen_bill.is_cancelled')->orWhere('patient_gen_bill.is_cancelled', 0);
            })
            ->where('hospital_services.is_reserved', 0)
            ->where(function ($q) {
                $q->where('hospital_services_index.is_outsource', 1)
                  ->orWhereNotNull('patient_gen_bill.outsource_lab_id');
            });

        if (!$hasSpecificSearch && !$hasFollowUpFilter) {
            if ($fromDate) {
                $kpiBase->whereDate('patient_gen_bill.created_at', '>=', $fromDate);
            }
            if ($toDate) {
                $kpiBase->whereDate('patient_gen_bill.created_at', '<=', $toDate);
            }
        }

        $statsAggregates = $kpiBase->selectRaw('
            COUNT(*) as total_orders,
            COUNT(patient_gen_bill.outsource_lab_id) as assigned_orders,
            SUM(CASE WHEN patient_gen_bill.outsource_lab_id IS NULL THEN 1 ELSE 0 END) as unassigned_orders,
            SUM(CASE WHEN lab_investigations.status IS NULL THEN 1 ELSE 0 END) as sample_pending,
            SUM(CASE WHEN lab_investigations.status IN ("collected","submitted") AND COALESCE(lab_investigations.in_process, 0) = 0 THEN 1 ELSE 0 END) as report_pending,
            SUM(CASE WHEN lab_investigations.status = "submitted" AND lab_investigations.approval_status = 1 THEN 1 ELSE 0 END) as approval_pending,
            SUM(CASE WHEN lab_investigations.status = "approved" THEN 1 ELSE 0 END) as completed_orders,
            SUM(COALESCE(patient_gen_bill.cost, 0) * patient_gen_bill.qty) as total_cost
        ')->first();

        $stats = [
            'total' => (int)($statsAggregates->total_orders ?? 0),
            'assigned' => (int)($statsAggregates->assigned_orders ?? 0),
            'unassigned' => (int)($statsAggregates->unassigned_orders ?? 0),
            'sample_pending' => (int)($statsAggregates->sample_pending ?? 0),
            'report_pending' => (int)($statsAggregates->report_pending ?? 0),
            'approval_pending' => (int)($statsAggregates->approval_pending ?? 0),
            'completed' => (int)($statsAggregates->completed_orders ?? 0),
            'cost_amount' => (float)($statsAggregates->total_cost ?? 0),
        ];

        // Paginate results
        $testList = $tests->orderBy('patient_gen_bill.id', 'DESC')->paginate(25)->withQueryString();

        // Support caches & lookups
        $services = HospitalServiceCache::all($hosp_id);
        $insurances = InsuranceCache::all($hosp_id);
        $doctors = DoctorCache::all($hosp_id);
        $labs = \App\Models\OutSourceLab::where('hospital_id', $hosp_id)->where('active', 1)->orderBy('name', 'asc')->get();

        $pageServiceIds = collect($testList->items())->pluck('service_id')->unique()->filter()->values();
        $labCharges = \App\Models\OutsourceLabCharge::where('hospital_id', $hosp_id)
            ->whereIn('service_id', $pageServiceIds)
            ->get()
            ->groupBy('service_id');

        $lab_orders_Ids = collect($testList->items())->pluck('id')->unique();

        $lisMappings = \DB::table('lis_service_mapping')
            ->whereIn('service_id', $pageServiceIds)
            ->where('hospital_id', $hosp_id)
            ->where('active', 1)
            ->get()
            ->groupBy('service_id');

        $samplesByLabOrder = \DB::table('lab_sample_labels')
            ->whereIn('lab_order_id', $lab_orders_Ids)
            ->get()
            ->groupBy('lab_order_id');

        $allSamples = \DB::table('lab_sample_labels')
            ->where(function ($query) use ($lab_orders_Ids) {
                foreach ($lab_orders_Ids as $id) {
                    $query->orWhereJsonContains('lab_order_ids', $id);
                }
            })
            ->get();

        $samplesByOrder = [];
        foreach ($allSamples as $sample) {
            foreach (json_decode($sample->lab_order_ids, true) ?? [] as $orderId) {
                $samplesByOrder[$orderId][] = $sample;
            }
        }

        if ($request->ajax()) {
            $tableHtml = view('admin.patient.lab_test.partials.lab_test_outsource_tracking_table', compact(
                'testList', 'draft_print_status', 'services', 'samplesByOrder', 
                'lisMappings', 'samplesByLabOrder', 'insurances', 'doctors', 
                'labs', 'labCharges', 'stats'
            ))->render();

            return response()->json([
                'status' => 'success',
                'html' => $tableHtml,
                'stats' => $stats,
                'total' => $testList->total(),
            ]);
        }

        return view('admin.patient.lab_test.lab_test_outsource_tracking', compact(
            'testList', 'draft_print_status', 'services', 'samplesByOrder', 
            'lisMappings', 'samplesByLabOrder', 'insurances', 'doctors', 
            'labs', 'labCharges', 'stats'
        ));
    }



    public function lab_test_orders_bill_wise(Request $request)
    {
        $this->authorize('module-permission', ['outsource_lab_orders', 'can_read']);

        $user = auth()->user();
        $hosp_id = $user->org_id;

        $draft_process_status = HospitalSettingCache::getStatus($hosp_id, 'process_draft', 0);
        $draft_print_status = HospitalSettingCache::getStatus($hosp_id, 'draft_print_report', 0);

        $paymentSummary = DB::table('billing_payment_type')
            ->select(
                'bill_id',
                DB::raw("
                    SUM(
                        CASE
                            WHEN transaction_type = 0 THEN amount
                            WHEN transaction_type = 1 THEN -amount
                            ELSE 0
                        END
                    ) as paid_amount
                ")
            )
            ->where(function ($q) {
                $q->whereNull('is_deleted')->orWhere('is_deleted', 0);
            })
            ->groupBy('bill_id');

        $billSummary = DB::table('patient_gen_bill')
            ->select(
                'bill_id',
                DB::raw("
                    SUM((charges * qty) - COALESCE(discount, 0)) as bill_amount
                ")
            )
            ->where(function ($q) {
                $q->whereNull('is_cancelled')->orWhere('is_cancelled', 0);
            })
            ->where(function ($q) {
                $q->whereNull('is_deleted')->orWhere('is_deleted', 0);
            })
            ->groupBy('bill_id');

        $latestReportSub = DB::table('lab_bill_outsource_reports')
            ->select('bill_id', DB::raw('MAX(id) as latest_report_id'))
            ->where('hospital_id', $hosp_id)
            ->whereNull('deleted_at')
            ->groupBy('bill_id');

        $billsQuery = PatientBilling::from('patient_billing')
            ->join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
            ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
            ->where('visitlog.hospital_id', $hosp_id)
            ->where(function ($q) {
                $q->whereNull('patient_billing.is_cancelled')->orWhere('patient_billing.is_cancelled', 0);
            })
            ->whereExists(function ($sub) use ($hosp_id, $request) {
                $sub->select(DB::raw(1))
                    ->from('patient_gen_bill')
                    ->join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
                    ->join('hospital_services_index', function ($join) use ($hosp_id) {
                        $join->on('hospital_services_index.service', '=', 'hospital_services.id')
                            ->where('hospital_services_index.hospital_id', '=', $hosp_id);
                    })
                    ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                    ->whereColumn('patient_gen_bill.bill_id', 'patient_billing.id')
                    ->where(function ($q) {
                        $q->whereNull('patient_gen_bill.is_deleted')->orWhere('patient_gen_bill.is_deleted', 0);
                    })
                    ->where(function ($q) {
                        $q->whereNull('patient_gen_bill.is_cancelled')->orWhere('patient_gen_bill.is_cancelled', 0);
                    })
                    ->where('hospital_services.flag', 'test')
                    ->where('hospital_services.is_reserved', 0)
                    ->where('hospital_services_index.is_outsource', 1);

                if (!empty($request->service)) {
                    $sub->whereIn('patient_gen_bill.service_id', (array)$request->service);
                }

                $status = $request->order_status ?? 'all';
                if ($status == 'sample_pending') {
                    $sub->whereNull('lab_investigations.status');
                } else if ($status == 'report_pending') {
                    $sub->whereIn('lab_investigations.status', ['collected', 'submitted'])
                        ->where('lab_investigations.in_process', 0);
                } else if ($status == 'report_in_process') {
                    $sub->whereIn('lab_investigations.status', ['collected', 'submitted'])
                        ->where('lab_investigations.in_process', 1);
                } else if ($status == 'approval_pending') {
                    $sub->where('lab_investigations.status', 'submitted')
                        ->where('lab_investigations.approval_status', 1);
                } else if ($status == 'completed') {
                    $sub->where('lab_investigations.status', 'approved');
                    if (($request->print_status ?? '') == 'printed') {
                        $sub->where('lab_investigations.is_printed', 1);
                    } elseif (($request->print_status ?? '') == 'not_printed') {
                        $sub->where('lab_investigations.is_printed', 0);
                    }
                } else if ($status == 'cancelled') {
                    $sub->where('lab_investigations.status', 'cancelled');
                }

                $tatFilter = $request->tat ?? null;
                if ($tatFilter) {
                    $now = \Carbon\Carbon::now();
                    $sub->whereNotNull('hospital_services.group_attributes')
                        ->where('lab_investigations.status', '!=', 'approved');

                    if ($tatFilter == 'over_tat') {
                        $sub->whereRaw("
                            TIMESTAMPADD(HOUR,
                                CAST(JSON_UNQUOTE(JSON_EXTRACT(hospital_services.group_attributes, '$.tat')) AS UNSIGNED),
                                lab_investigations.sample_collect_time
                            ) < ?", [$now]);
                    } else if ($tatFilter == 'near_tat') {
                        $sub->whereRaw("
                            TIMESTAMPADD(HOUR,
                                CAST(JSON_UNQUOTE(JSON_EXTRACT(hospital_services.group_attributes, '$.tat')) AS UNSIGNED),
                                lab_investigations.sample_collect_time
                            ) BETWEEN ? AND ?
                        ", [$now, $now->copy()->addMinutes(15)]);
                    } else if ($tatFilter == 'within_tat') {
                        $sub->whereRaw("
                            TIMESTAMPADD(HOUR,
                                CAST(JSON_UNQUOTE(JSON_EXTRACT(hospital_services.group_attributes, '$.tat')) AS UNSIGNED),
                                lab_investigations.sample_collect_time
                            ) > ?", [$now->copy()->addMinutes(15)]);
                    }
                }
            })
            ->leftJoinSub($paymentSummary, 'payments', function ($join) {
                $join->on('payments.bill_id', '=', 'patient_billing.id');
            })
            ->leftJoinSub($billSummary, 'bill_total', function ($join) {
                $join->on('bill_total.bill_id', '=', 'patient_billing.id');
            })
            ->leftJoinSub($latestReportSub, 'latest_report', function ($join) {
                $join->on('latest_report.bill_id', '=', 'patient_billing.id');
            })
            ->leftJoin('lab_bill_outsource_reports', 'lab_bill_outsource_reports.id', '=', 'latest_report.latest_report_id')
            ->leftJoin('users as uploader', 'uploader.id', '=', 'lab_bill_outsource_reports.uploaded_by');

        // Filters
        if ($request->uhid ?? false) {
            $billsQuery->where('pi.id', $request->uhid);
        } else if ($request->name ?? false) {
            $billsQuery->where(function ($q) use ($request) {
                $q->where('pi.Fname', 'like', '%' . $request->name . '%')
                    ->orWhere('pi.Lname', 'like', '%' . $request->name . '%');
            });
        } else if ($request->mobile ?? false) {
            $billsQuery->where('pi.mobile_no', $request->mobile);
        } else if ($request->bill_id ?? false) {
            $billsQuery->where('patient_billing.id', $request->bill_id);
        } else if (empty($request->follow_up_filter) && empty($request->follow_up_date)) {
            $billsQuery->whereDate('patient_billing.created_at', '>=', $request->from_date ?? date('Y-m-d'));
            $billsQuery->whereDate('patient_billing.created_at', '<=', $request->end_date ?? date('Y-m-d'));
        }

        if (($request->report_status ?? '') == 'uploaded') {
            $billsQuery->whereNotNull('latest_report.latest_report_id');
        } else if (($request->report_status ?? '') == 'pending') {
            $billsQuery->whereNull('latest_report.latest_report_id');
        }

        $todayDate = \Carbon\Carbon::today()->toDateString();
        $tomorrowDate = \Carbon\Carbon::tomorrow()->toDateString();

        if (($request->follow_up_filter ?? '') == 'today') {
            $billsQuery->whereDate('lab_bill_outsource_reports.follow_up_date', '=', $todayDate);
        } else if (($request->follow_up_filter ?? '') == 'tomorrow') {
            $billsQuery->whereDate('lab_bill_outsource_reports.follow_up_date', '=', $tomorrowDate);
        } else if (($request->follow_up_filter ?? '') == 'upcoming') {
            $billsQuery->whereDate('lab_bill_outsource_reports.follow_up_date', '>', $todayDate);
        } else if (($request->follow_up_filter ?? '') == 'overdue') {
            $billsQuery->whereDate('lab_bill_outsource_reports.follow_up_date', '<', $todayDate);
        } else if (($request->follow_up_filter ?? '') == 'due') {
            $billsQuery->whereDate('lab_bill_outsource_reports.follow_up_date', '<=', $todayDate);
        } else if ($request->follow_up_date ?? false) {
            $billsQuery->whereDate('lab_bill_outsource_reports.follow_up_date', '=', $request->follow_up_date);
        }

        $billsQuery->when($draft_process_status == 0, function ($query) {
            $query->where('patient_billing.status', 1);
        });

        $bills = $billsQuery->select(
            'patient_billing.id as bill_id',
            'patient_billing.id as pbill_id',
            'patient_billing.bill_number',
            'patient_billing.created_at as bill_date',
            'patient_billing.status as draft_status',
            'patient_billing.status as pbill_status',
            'patient_billing.discount as bill_discount',
            'visitlog.id as visit_id',
            'visitlog.doctor_id',
            'visitlog.visit_status',
            'visitlog.emergency',
            'pi.id as uhid',
            'pi.prefix',
            'pi.Fname as patient_first_name',
            'pi.Lname as patient_last_name',
            'pi.age',
            'pi.sex',
            'pi.dob',
            'pi.mobile_no as phone',
            'pi.i_cover',
            'pi.mnvs',
            'lab_bill_outsource_reports.id as report_id',
            'lab_bill_outsource_reports.file_path as report_file_path',
            'lab_bill_outsource_reports.file_name as report_file_name',
            'lab_bill_outsource_reports.file_size as report_file_size',
            'lab_bill_outsource_reports.notes as report_notes',
            'lab_bill_outsource_reports.follow_up_date',
            'lab_bill_outsource_reports.follow_up_notes',
            'lab_bill_outsource_reports.created_at as report_uploaded_at',
            'lab_bill_outsource_reports.uploaded_by as report_uploaded_by',
            'uploader.name as uploader_name',
            DB::raw("COALESCE(payments.paid_amount, 0) as paid_amount"),
            DB::raw("COALESCE(bill_total.bill_amount, 0) as total_bill_amount"),
            DB::raw("
                CASE
                    WHEN COALESCE(payments.paid_amount,0) = (COALESCE(bill_total.bill_amount,0) - COALESCE(patient_billing.discount,0))
                    THEN 'FP'
                    WHEN COALESCE(payments.paid_amount,0) > 0 AND COALESCE(payments.paid_amount,0) < (COALESCE(bill_total.bill_amount,0) - COALESCE(patient_billing.discount,0))
                    THEN 'PP'
                    WHEN COALESCE(payments.paid_amount,0) = 0 AND (COALESCE(bill_total.bill_amount,0) - COALESCE(patient_billing.discount,0)) > 0
                    THEN 'UP'
                    ELSE 'UP'
                END AS payment_status
            ")
        )
        ->orderBy('patient_billing.id', 'DESC')
        ->paginate(50)
        ->withQueryString();

        // Batch fetch services for paginated bills
        $billIds = collect($bills->items())->pluck('bill_id')->toArray();
        $servicesByBill = collect();

        if (!empty($billIds)) {
            $billServices = PatientGenBill::join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
                ->join('hospital_services_index', function ($join) use ($hosp_id) {
                    $join->on('hospital_services_index.service', '=', 'hospital_services.id')
                        ->where('hospital_services_index.hospital_id', '=', $hosp_id);
                })
                ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                ->whereIn('patient_gen_bill.bill_id', $billIds)
                ->where(function ($q) {
                    $q->whereNull('patient_gen_bill.is_deleted')->orWhere('patient_gen_bill.is_deleted', 0);
                })
                ->where(function ($q) {
                    $q->whereNull('patient_gen_bill.is_cancelled')->orWhere('patient_gen_bill.is_cancelled', 0);
                })
                ->where('hospital_services.flag', 'test')
                ->where('hospital_services.is_reserved', 0)
                ->where('hospital_services_index.is_outsource', 1)
                ->select(
                    'patient_gen_bill.id as order_id',
                    'patient_gen_bill.bill_id',
                    'patient_gen_bill.service_id',
                    'patient_gen_bill.created_at as order_created_at',
                    'hospital_services.service as service_name',
                    'hospital_services.group_attributes',
                    DB::raw("JSON_UNQUOTE(JSON_EXTRACT(hospital_services.group_attributes, '$.tat')) as tat"),
                    'lab_investigations.id as lab_investigation_id',
                    'lab_investigations.status as investigation_status',
                    'lab_investigations.in_process',
                    'lab_investigations.approval_status',
                    'lab_investigations.sample_collect_time',
                    'lab_investigations.reporting_time',
                    'lab_investigations.follow_up',
                    'lab_investigations.is_printed'
                )
                ->orderBy('patient_gen_bill.id', 'ASC')
                ->get();

            $servicesByBill = $billServices->groupBy('bill_id');
        }

        $services = HospitalServiceCache::all($hosp_id);
        $insurances = InsuranceCache::all($hosp_id);
        $doctors = DoctorCache::all($hosp_id);

        // Fetch unread follow-up notifications for this hospital
        $followUpNotifications = LabOutsourceFollowupNotification::forHospital($hosp_id)
            ->unread()
            ->with(['bill', 'patient'])
            ->orderBy('follow_up_date', 'ASC')
            ->get();

        if ($request->ajax()) {
            return view('admin.patient.lab_test.lab_report_table_bill_wise', compact(
                'bills',
                'servicesByBill',
                'draft_print_status',
                'services',
                'insurances',
                'doctors',
                'followUpNotifications'
            ))->render();
        }

        return view('admin.patient.lab_test.lab_test_orders_bill_wise', compact(
            'bills',
            'servicesByBill',
            'draft_print_status',
            'services',
            'insurances',
            'doctors',
            'followUpNotifications'
        ));
    }

    public function lab_bill_wise_upload_report(Request $request)
    {
        $this->authorize('module-permission', ['outsource_lab_orders', 'can_create']);

        $request->validate([
            'bill_id' => 'required|integer',
            'report_file' => 'required|file|mimes:pdf|max:20480',
            'notes' => 'nullable|string|max:1000',
            'follow_up_date' => 'nullable|date',
            'follow_up_notes' => 'nullable|string|max:500',
        ]);

        $user = auth()->user();
        $hosp_id = $user->org_id;
        $billId = $request->bill_id;

        // Verify bill belongs to this hospital
        $bill = DB::table('patient_billing')
            ->join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
            ->where('patient_billing.id', $billId)
            ->where('visitlog.hospital_id', $hosp_id)
            ->first();

        if (!$bill) {
            return response()->json(['success' => false, 'message' => 'Bill not found or unauthorized.'], 404);
        }

        $file = $request->file('report_file');
        $originalName = $file->getClientOriginalName();
        $fileSize = $file->getSize();
        $mimeType = $file->getMimeType();

        $uploadPath = public_path('assets/files/outsource_lab_reports/bill_wise');
        if (!file_exists($uploadPath)) {
            mkdir($uploadPath, 0777, true);
        }

        $fileName = 'bill_' . $billId . '_' . uniqid() . '_' . time() . '.' . $file->getClientOriginalExtension();
        $file->move($uploadPath, $fileName);
        $filePath = 'assets/files/outsource_lab_reports/bill_wise/' . $fileName;

        // Check if existing report has a follow_up_date to preserve
        $existingReport = LabBillOutsourceReport::where('bill_id', $billId)
            ->where('hospital_id', $hosp_id)
            ->whereNull('deleted_at')
            ->orderBy('id', 'desc')
            ->first();

        $followUpDate = $request->filled('follow_up_date')
            ? $request->follow_up_date
            : ($existingReport ? $existingReport->follow_up_date : null);

        $followUpNotes = $request->filled('follow_up_notes')
            ? $request->follow_up_notes
            : ($existingReport ? $existingReport->follow_up_notes : null);

        // Soft delete any existing active reports for this bill
        LabBillOutsourceReport::where('bill_id', $billId)
            ->where('hospital_id', $hosp_id)
            ->update([
                'deleted_by' => $user->id,
                'deleted_at' => now(),
            ]);

        // Create new report record
        $report = LabBillOutsourceReport::create([
            'bill_id' => $billId,
            'hospital_id' => $hosp_id,
            'file_path' => $filePath,
            'file_name' => $originalName,
            'file_size' => $fileSize,
            'mime_type' => $mimeType,
            'notes' => $request->notes,
            'follow_up_date' => $followUpDate,
            'follow_up_notes' => $followUpNotes,
            'uploaded_by' => $user->id,
        ]);

        return response()->json([
            'success' => true,
            'message' => 'Outsource lab report uploaded successfully.',
            'report' => $report,
        ]);
    }

    public function lab_bill_wise_save_follow_up(Request $request)
    {
        $this->authorize('module-permission', ['outsource_lab_orders', 'can_update']);

        $request->validate([
            'bill_id' => 'required|integer',
            'follow_up_date' => 'nullable|date',
            'follow_up_notes' => 'nullable|string|max:500',
        ]);

        $user = auth()->user();
        $hosp_id = $user->org_id;

        // Verify bill belongs to this hospital
        $bill = DB::table('patient_billing')
            ->join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
            ->where('patient_billing.id', $request->bill_id)
            ->where('visitlog.hospital_id', $hosp_id)
            ->first();

        if (!$bill) {
            return response()->json(['success' => false, 'message' => 'Bill not found or unauthorized.'], 404);
        }

        // Find or create active report record for this bill
        $report = LabBillOutsourceReport::where('bill_id', $request->bill_id)
            ->where('hospital_id', $hosp_id)
            ->whereNull('deleted_at')
            ->orderBy('id', 'desc')
            ->first();

        if (!$report) {
            $report = new LabBillOutsourceReport();
            $report->bill_id = $request->bill_id;
            $report->hospital_id = $hosp_id;
            $report->file_path = '';
            $report->file_name = '';
            $report->uploaded_by = $user->id;
        }

        $report->follow_up_date = $request->follow_up_date ?: null;
        $report->follow_up_notes = $request->follow_up_notes ?: null;
        $report->save();

        return response()->json([
            'success' => true,
            'message' => 'Follow-up date updated successfully.',
            'follow_up_date' => $report->follow_up_date ? \Carbon\Carbon::parse($report->follow_up_date)->format('d/m/Y') : null,
            'follow_up_date_raw' => $report->follow_up_date ? \Carbon\Carbon::parse($report->follow_up_date)->format('Y-m-d') : null,
            'follow_up_notes' => $report->follow_up_notes,
        ]);
    }

    public function lab_bill_wise_mark_notification_read(Request $request)
    {
        $this->authorize('module-permission', ['outsource_lab_orders', 'can_read']);

        $request->validate([
            'notification_id' => 'nullable|integer',
            'all' => 'nullable|boolean',
        ]);

        $user = auth()->user();
        $hosp_id = $user->org_id;

        if ($request->boolean('all')) {
            LabOutsourceFollowupNotification::forHospital($hosp_id)
                ->unread()
                ->update([
                    'status' => 'read',
                    'read_at' => now(),
                    'read_by' => $user->id,
                ]);
        } else if ($request->notification_id) {
            $notification = LabOutsourceFollowupNotification::forHospital($hosp_id)
                ->where('id', $request->notification_id)
                ->first();

            if ($notification) {
                $notification->status = 'read';
                $notification->read_at = now();
                $notification->read_by = $user->id;
                $notification->save();
            }
        }

        return response()->json([
            'success' => true,
            'message' => 'Notification marked as read.',
        ]);
    }

    public function lab_bill_wise_view_report(Request $request, $id)
    {
        $this->authorize('module-permission', ['outsource_lab_orders', 'can_read']);

        $user = auth()->user();
        $hosp_id = $user->org_id;

        $report = LabBillOutsourceReport::where('id', $id)
            ->where('hospital_id', $hosp_id)
            ->first();

        if (!$report) {
            abort(404, 'Report not found.');
        }

        $fullPath = public_path($report->file_path);
        if (!file_exists($fullPath)) {
            abort(404, 'Report file not found on disk.');
        }

        $showHeader = $request->boolean('header');

        if (!$showHeader) {
            return response()->file($fullPath, [
                'Content-Type' => 'application/pdf',
                'Content-Disposition' => 'inline; filename="' . $report->file_name . '"',
            ]);
        }

        return $this->generateBillWiseOutsourcePdf($fullPath, (int)$report->bill_id, true);
    }

    private function generateBillWiseOutsourcePdf(
        string $filePath,
        int $billId,
        bool $showHeader
    ) {
        if (!$showHeader) {
            $headerHtml = '';
        } else {
            $headerHtml = view('components.main-header', [
                'bill' => $billId,
            ])->render();
        }

        $mpdf = new Mpdf([
            'format' => 'A4',
            'orientation' => 'P',
            'margin_left' => 0,
            'margin_right' => 0,
            'margin_top' => 0,
            'margin_bottom' => 0,
        ]);

        $pageCount = $mpdf->SetSourceFile($filePath);

        for ($pageNo = 1; $pageNo <= $pageCount; $pageNo++) {
            $templateId = $mpdf->ImportPage($pageNo);
            $size = $mpdf->GetTemplateSize($templateId);

            $origWidth = $size['width'];
            $origHeight = $size['height'];
            $orientation = $origWidth > $origHeight ? 'L' : 'P';

            // In mPDF, sheet-size array is [min_dim, max_dim] and orientation swaps if 'L'
            $mpdf->AddPageByArray([
                'orientation' => $orientation,
                'sheet-size' => [
                    min($origWidth, $origHeight),
                    max($origWidth, $origHeight),
                ],
                'margin-left' => 0,
                'margin-right' => 0,
                'margin-top' => 0,
                'margin-bottom' => 0,
            ]);

            // 1. Place original PDF page exactly unchanged at (0, 0) - no scaling, no moving content
            $mpdf->UseTemplate(
                $templateId,
                0,
                0,
                $origWidth,
                $origHeight
            );

            // 2. Overlay hospital header on EVERY page in the already-reserved header space
            if ($showHeader && !empty($headerHtml)) {
                $mpdf->WriteFixedPosHTML(
                    $headerHtml,
                    5,
                    2,
                    $origWidth - 10,
                    35
                );
            }
        }

        $fileName = 'bill_' . $billId . '_outsource_report.pdf';

        return response(
            $mpdf->Output($fileName, 'S'),
            200,
            [
                'Content-Type' => 'application/pdf',
                'Content-Disposition' => 'inline; filename="' . $fileName . '"',
            ]
        );
    }

