    public function test_item_consumption_mapping_index(Request $request)
    {
        $this->authorize('module-permission', ['lab_test', 'can_read']);

        $user = auth()->user();
        $hosp_id = $user->org_id;
        $search = $request->input('search');

        $servicesQuery = HospitalService::from('hospital_services_index as hsi')
            ->join('hospital_services as hs', 'hs.id', '=', 'hsi.service')
            ->where('hsi.hospital_id', $hosp_id)
            ->where('hsi.active', 1)
            ->where('hs.flag', 'test')
            ->select('hs.id as service_id', 'hs.service as service_name', 'hs.brief_des as service_description')
            ->orderBy('hs.service', 'asc');

        if (!empty($search)) {
            $servicesQuery->where('hs.service', 'like', "%{$search}%");
        }

        $services = $servicesQuery->paginate(20)->withQueryString();

        $serviceIds = $services->pluck('service_id')->toArray();

        // Fetch existing mappings
        $mappings = \App\Models\TestItemConsumptionMapping::where('hospital_id', $hosp_id)
            ->whereIn('service_id', $serviceIds)
            ->with('item')
            ->get()
            ->groupBy('service_id');

        return view('admin.patient.lab_test.item_consumption_mapping', compact('services', 'mappings', 'search'));
    }

    public function save_test_item_consumption_mapping(Request $request)
    {
        $this->authorize('module-permission', ['lab_test', 'can_update']);

        $request->validate([
            'service_id' => 'required|integer',
            'items' => 'nullable|array',
            'items.*.item_id' => 'required|integer',
            'items.*.qty' => 'required|numeric|min:0.001',
        ]);

        $user = auth()->user();
        $hosp_id = $user->org_id;
        $service_id = $request->input('service_id');
        $items = $request->input('items', []);

        \DB::transaction(function () use ($hosp_id, $service_id, $items) {
            // Delete existing mappings
            \App\Models\TestItemConsumptionMapping::where('hospital_id', $hosp_id)
                ->where('service_id', $service_id)
                ->delete();

            // Insert new mappings
            foreach ($items as $item) {
                \App\Models\TestItemConsumptionMapping::create([
                    'hospital_id' => $hosp_id,
                    'service_id' => $service_id,
                    'item_id' => $item['item_id'],
                    'qty' => $item['qty'],
                ]);
            }
        });

        return response()->json([
            'success' => true,
            'message' => 'Mapping saved successfully.'
        ]);
    }

    public function search_hospital_items(Request $request)
    {
        $this->authorize('module-permission', ['lab_test', 'can_read']);

        $search = trim($request->input('q'));
        $hosp_id = auth()->user()->org_id;

        $items = \DB::table('item_hospital_index as ihi')
            ->join('items as i', 'i.id', '=', 'ihi.item_id')
            ->where('ihi.hospital_id', $hosp_id)
            ->where('i.on_hold', 0)
            ->whereNull('i.deleted_at')
            ->when($search, function ($query) use ($search) {
                $query->where('i.name', 'like', "%{$search}%");
            })
            ->select('i.id', 'i.name')
            ->limit(50)
            ->get();

        return response()->json([
            'results' => $items->map(function ($item) {
                return [
                    'id' => $item->id,
                    'text' => $item->name,
                ];
            })
        ]);
    }


