    public function update_follow_up_date(Request $request)
    {
        $request->validate([
            'id' => 'required',
            'follow_up' => 'nullable|date',
            'follow_up_notes' => 'nullable|string',
        ]);

        $labInvestigation = LabInvestigation::firstOrNew(['lab_order_id' => $request->id]);
        $labInvestigation->lab_order_id = $request->id;
        $labInvestigation->follow_up = $request->follow_up ?: null;
        if ($request->has('follow_up_notes') || $request->has('notes') || $request->has('other_remarks')) {
            $labInvestigation->other_remarks = $request->follow_up_notes ?? $request->notes ?? $request->other_remarks;
        }
        if(!$labInvestigation->exists && empty($labInvestigation->status)){
            $labInvestigation->status = 'collected';
            $labInvestigation->is_outsource = 1;
        }
        $labInvestigation->save();

        $relativeText = 'Not Set';
        $relativeClass = 'text-muted';
        if ($labInvestigation->follow_up) {
            $fDate = \Carbon\Carbon::parse($labInvestigation->follow_up)->startOfDay();
            $tDate = \Carbon\Carbon::today();
            $diffInDays = $tDate->diffInDays($fDate, false);
            if ($diffInDays < 0) {
                $relativeText = 'Overdue';
                $relativeClass = 'text-danger fw-bold';
            } elseif ($diffInDays == 0) {
                $relativeText = 'Today';
                $relativeClass = 'text-warning text-dark fw-bold';
            } elseif ($diffInDays == 1) {
                $relativeText = 'Tomorrow';
                $relativeClass = 'text-info fw-bold';
            } else {
                $relativeText = 'In ' . $diffInDays . ' days';
                $relativeClass = 'text-primary fw-bold';
            }
        }

        return response()->json([
            'status' => 'success',
            'success' => true,
            'message' => 'Follow-up details updated successfully.',
            'relative_text' => $relativeText,
            'relative_class' => $relativeClass,
            'follow_up_date' => $labInvestigation->follow_up,
        ]);
    }

