    public function delete_outsource_order_report(Request $request)
    {
        $request->validate([
            'id' => 'required',
        ]);

        $investigation = LabInvestigation::where('lab_order_id', $request->id)->first();
        if (!$investigation) {
            return response()->json(['success' => false, 'message' => 'Investigation record not found.'], 404);
        }

        $results = json_decode($investigation->test_results, true) ?? [];
        if (!empty($results['file_path'])) {
            $filePath = $results['file_path'];
            unset($results['file_path']);
            unset($results['old_file']);

            // Only delete physical file if no other investigation is referencing this file
            $stillReferenced = LabInvestigation::where('id', '!=', $investigation->id)
                ->where('test_results', 'like', '%' . $filePath . '%')
                ->exists();

            if (!$stillReferenced) {
                $fullPath = public_path($filePath);
                if (file_exists($fullPath) && is_file($fullPath)) {
                    @unlink($fullPath);
                }
            }
        }

        $investigation->test_results = !empty($results) ? json_encode($results) : null;
        if ($investigation->status == 'submitted' && empty($results)) {
            $investigation->status = 'collected';
            $investigation->reporting_time = null;
        }
        $investigation->save();

        return response()->json([
            'success' => true,
            'message' => 'Report file removed successfully.'
        ]);
    }

    public function print_refund_bill(Request $request)
    {
        $request->validate([
           'bill_id'=>'required',
        ]);

        $b_id = $request->bill_id;
        $user = auth()->user();
        $org_id = $user->org_id;

        $getbill = PatientBilling::findOrFail($b_id);
        $visit = Visitlog::find($getbill->visit_id);
        $getpaytype = BillingPaymentType::where('bill_id',$b_id)->where('flag','refund')->first();
        $patient = Patient::find($visit->patient_id);
        $doctor = Doctor_db::find($visit->doctor_id);
        $insurance = HealthInsurance::find($getbill->i_cover);
        $hospital = Healtcare_org::find($org_id);
        $services = PatientGenBill::where('bill_id',$b_id)->get();


        $data["bill_tag"] =  'refund';
        $data["hospital"] =  $hospital->name;
        $data["hospital_address"] =  $hospital->address;
        $data["hospital_phone"] =  $hospital->mobile;
        $data['logo'] = $hospital->logo;
        $data["mr"] = $patient->id;
        $data["prefix"] = $patient->prefix;
        $data["fname"] = $patient->Fname;
        $data["lname"] = $patient->Lname;
        $data["gender"] = $patient->sex;
        $data["age"] = $patient->age;
        $data["doctor"] = $doctor->name;
        $data["bill_no"] = $b_id;
        $data["insurance"] = $insurance->insurance_agen??'';
        $data["staff"] = ($user->first_name??"") . " " . ($user->last_name??"");
        $data['regch'] = $getbill->reg_charges;
        $data['docch'] = $getbill->doc_charges;
        $data['docchnm'] = ""; //$doch->comment;

        $serviceData = [];
        foreach ($services as $service) {
            if($service->service_id != null){
                $sname = HospitalSer::find($service->service_id);
                $ser = $sname->service;
                $ser_id = $sname->id;
            }
            else
            { $misc = MiscellaneousCharges:: find($service->misc_service_id);
                $ser = $misc->name;
                $ser_id = $misc->id;
            }

            $serviceData[] = [
                'ser_id' => $ser_id,
                'service' => $ser,
                'qty' => $service->qty,
                'charges' => $service->charges,
                'amount' => $service->amount,
            ];
        }

        $data["subtotal"] = $getbill->subtotal;
        $data["discount"] = number_format((float)$getbill->discount, 2, '.', '');
        $data["total"] = $getbill->total;
        $data["cash"] = $getpaytype->cash;
        $data["upi"] = $getpaytype->upi;
        $data["debit"] = $getpaytype->debit_card;
        $data["credit"] = $getpaytype->credit_card;
        $data['total_paid'] = ($getpaytype->cash??0) + ($getpaytype->upi??0) + ($getpaytype->debit_card??0);

        $pdf = PDF::loadView('admin.pdf.patient_bill',['data' => $data,'serviceData'=>$serviceData]);

        if (!file_exists('assets/billing')) {
            mkdir('assets/billing', 0777, true);
        }

        //$pdf = PDF::loadView('admin.pdf.bill');
        $pdfFilename = 'pdf_file_' . $b_id . '.pdf';
        $pdfPath = 'assets/billing/'.$pdfFilename;
        $pdf->save($pdfPath);

        return response()->json(['status' =>true,  'pdf_url' => url($pdfPath)]);
    }

    public function lab_test_upload(Request $request,$id)
    {
        $user = auth()->user();
        $hosp_id = $user->org_id;

        $investigation = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                            ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                            ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                            ->join('pi','pi.id','=','visitlog.patient_id')
                            ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->leftJoin('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                            ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                            ->leftJoin('lis_service_mapping','lis_service_mapping.service_id','=','hospital_services.id')
                            ->select('patient_gen_bill.*',
                                'doctor_db.name as doctor_name',
                                'pi.id as uhid',
                                'patient_billing.created_at as bill_date',
                                'pi.*',
                                'hospital_services.is_group as is_group',
                                'hospital_services.loinc_code as loinc_code',
                                'hospital_services.service as service_name',
                                'health_insurance_agen.insurance_agen as insurance',
                                'lab_investigations.id as lab_investigation_id',
                                'lab_investigations.lab_order_id as lab_order_id',
                                'lab_investigations.status as investigation_status',
                                'lis_service_mapping.lis_context'
                                )
                            ->where('patient_gen_bill.id',$id)
                            ->where('lab_investigations.status','collected')
                            ->firstOrFail();
        if($investigation->is_group)
        {

            $testList = InvestigationGroupTest::leftJoin('hospital_services as group','group.id','=','table_investigation_group_test_index.group_id')
                                                ->leftJoin('hospital_services as service','service.id','=','table_investigation_group_test_index.test_id')
                                                ->select('group.service as group_service_name',
                                                        'group.display_full_name as display_full_name',
                                                        'group.id as group_id',
                                                        'service.id as service_id',
                                                        'service.service as service_name',
                                                        'service.short_code as short_code',
                                                        'service.input_attributes as input_attributes',
                                                        'service.loinc_code as loinc_code',
                                                        'service.is_subgroup as is_subgroup')
                                                ->where('table_investigation_group_test_index.group_id',$investigation->service_id)
                                                ->orderBy('table_investigation_group_test_index.sequence_no','asc')
                                                ->get();

                // check for subgroup
                $subgroupTestList = [];
                foreach ($testList as $service) {
                    if (isset($service['is_subgroup']) && $service['is_subgroup'] == 1) {
                        $subgroupTestList[]   = InvestigationGroupTest::leftJoin('hospital_services as group','group.id','=','table_investigation_group_test_index.group_id')
                                                ->leftJoin('hospital_services as service','service.id','=','table_investigation_group_test_index.test_id')
                                                ->select('group.service as group_service_name',
                                                        'group.display_full_name as display_full_name',
                                                        'group.id as group_id',
                                                        'service.id as service_id',
                                                        'service.service as service_name',
                                                        'service.short_code as short_code',
                                                        'service.loinc_code as loinc_code',
                                                        'service.input_attributes as input_attributes',
                                                        'service.is_subgroup as is_subgroup')
                                                ->where('table_investigation_group_test_index.group_id',$service['service_id'])
                                                ->orderBy('table_investigation_group_test_index.sequence_no','asc')
