    public function lab_sample_collection(Request $request)
    {
        $user = auth()->user();
        $hosp_id = $user->org_id;

        $bills = PatientBilling::whereHas('bill_items', function ($q) {
                    $q->whereHas('service', function ($s) {
                        $s->where('flag', 'test')
                        ->where('is_reserved', 0);
                    })->where('is_deleted', 0)->whereNull('is_cancelled');
                })
                ->whereHas('visit', function ($q) use ($hosp_id) {
                    $q->where('hospital_id', $hosp_id);
                })
                ->with(['bill_items' => function ($q) {
                    $q->where('is_deleted', 0)
                    ->whereHas('service', function ($s) {
                        $s->where('flag', 'test')
                            ->where('is_reserved', 0);
                    });
                }])
                ->whereDate('created_at', date('Y-m-d'))
                ->orderByDesc('id')
                ->get();
        if($request->ajax())
        {
            if($request->orders)
            {
                return view('admin.patient.lab_test.section_bill_list_items',['bills'=>$bills])->render();
            }
            if($request->id)
            {
                $bill = PatientBilling::with(['bill_items' => function ($q) {
                            $q->where('is_deleted', 0)
                            ->whereHas('service', function ($s) {
                                $s->where('flag', 'test')
                                    ->where('is_reserved', 0);
                            });
                        }])->findOrFail($request->id);
                return view('admin.patient.lab_test.section_sample_collection',compact('bill'))->render();
            }
        }

        return view('admin.patient.lab_test.lab_sample_collection',compact('bills'));
    }
    public function getLabOrders($filter = [])
    {
        $user = auth()->user();
        $hosp_id = $user->org_id;

        return PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                    ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                    ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                    ->join('pi','pi.id','=','visitlog.patient_id')
                    ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                    ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                    ->select('patient_gen_bill.*',
                        'hospital_services.service as service_name',
                        'hospital_services.group_attributes as group_attributes',
                        'doctor_db.name as doctor_name',
                        'pi.id as uhid',
                        'patient_gen_bill.created_at as bill_date',
                        'patient_gen_bill.id as pGen_bill_id',
                        'pi.prefix as prefix',
                        'pi.Fname',
                        'pi.Lname',
                        'pi.dob',
                        'pi.age as age',
                        'pi.sex as sex',
                        'pi.mobile_no as phone',
                        'lab_investigations.id as lab_investigation_id',
                        'lab_investigations.status as investigation_status',
                        'lab_investigations.sample_collect_time as sample_collect_time',
                        'lab_investigations.approved_by as approved_by',
                        'lab_investigations.test_results as test_results',
                        'lab_investigations.approval_status as approval_status',
                        'lab_investigations.status as status',
                        'patient_billing.id as pbill_id',
                        'patient_billing.status as pbill_status',
                        'patient_billing.status as draft_status',
                        'visitlog.visit_status',
                        )
                    ->where('visitlog.hospital_id',$hosp_id)
                    ->where('hospital_services.flag',"!=",'refund')
                    ->where('hospital_services.flag',"!=",'balance')
                    ->where('patient_gen_bill.is_deleted',0)
                    ->when($vid = $filter['visit_id']??false,function ($query) use ($vid) {
                            $query->where('visitlog.id', $vid);
                        },
                        function ($query) use ($filter) {
                            if($filter['patient_id']??false){
                                $query->where('pi.id', $filter['patient_id']);
                            }else{
                                $query->whereDate('patient_gen_bill.created_at', date('Y-m-d'));
                            }
                        }
                    )
                    ->when($filter['approved_only'] ?? false, function ($query) {
                        $query->where(
                            'lab_investigations.status',
                            'approved'
                        );
                    })
                    ->when($filter['doctor_id'] ?? false, function ($query, $doctorId) {
                          $query->where('visitlog.doctor_id', $doctorId);
                    })
                    ->where('hospital_services.is_reserved',"=",0)
                    ->where('lab_investigations.status',"!=",'cancelled')
                    ->orderBy('patient_billing.id','DESC')
                    ->get();
    }

