    public function lab_test_save_sample(Request $request)
    {

        $request->validate([
            'order_id' => 'required',
            // 'sample_type' => 'required',
            // 'sample_condition' => 'required',
            // 'sample_status' => 'required',
            // 'sample_collection_time' => 'required',
        ]);

        try{
            $investigation = LabInvestigation::firstOrNew(['lab_order_id'=>$request->order_id]);
            $investigation->lab_order_id = $request->order_id;
            $investigation->sample_condition = '';
            if(!in_array(($investigation->status??''),['submitted','approved','rejected','cancelled'])){
                $investigation->status = 'collected';
            }
            $investigation->sample_collect_time = now();
            $investigation->sample_remark = '';
            if($request->outsource??false){
                $investigation->is_outsource = $request->outsource;
            }
            $investigation->save();
        }catch(\Exception $e){
            // return $e->getMessage();
            return redirect()->back()->with('error', $e->getMessage());
        }

        if($request->ajax())
        {
            return response()->json(['success' => true, 'message' => 'Sample Collection successfully updated.']);
        }

        return redirect()->back()->with('success', 'Test Sample Collection successfully updated.');
    }
    public function lab_test_update_sample_status(Request $request)
    {
        // dd($request->all());
        $request->validate([
            'id' => 'required',
            'sample_condition' => 'required',
            // 'sample_collection_time' => 'required',
        ]);
        $sample =  \DB::table('lab_sample_labels')->where('id', $request->id)->first();
        \DB::table('lab_sample_labels')
            ->where('id', $request->id)
            ->update([
                'condition' => $request->sample_condition,
                'collect_time' => $request->sample_collection_time??now(),
                'lis_context' => $request->analyzer??null,
                'is_outsource' => $request->outsource?1:0,
                'outsource_lab_id' => $request->outsource??null,
                'collected_by' => auth()->user()->id,
            ]);

        if($request->sample_condition != 'Good')
        {
            DB::table('lab_sample_labels')->insertGetId([
                'lab_order_id' => $sample->lab_order_id,
                'sample_type' => $sample->sample_type,
                'sample_quantity' => $sample->sample_quantity,
                'sample_unit' => $sample->sample_unit,
                'vial_type' => $sample->vial_type,
            ]);
        }
        if($request->sample_condition == 'Good'){
            if($sample->lab_order_id){
                $request->merge(['order_id' => $sample->lab_order_id]);
                $this->lab_test_save_sample($request);
            }else{
                $orderIds = json_decode($sample->lab_order_ids,true);
                foreach($orderIds as $orderId){
                    $request->merge(['order_id' => $orderId]);
                    $this->lab_test_save_sample($request);
                }
            }
        }

        return response()->json(['success' => true, 'message' => 'Sample status updated.']);
    }
    public function updated_order_in_process_status(Request $request)
    {
        $request->validate([
            "id"=>"required",
            "status"=>"required",
        ]);
        $investigation = LabInvestigation::where(['lab_order_id'=>$request->id])->first();
        if(!$investigation){
            return response()->json(['success' => false,'message' => 'Invesigation not found.']);
        }
        if(!$request->status){
            $other_remark = json_decode($investigation->other_remarks,true);
            $other_remark['in_process_undo_reason'] = $request->reason??'';
            $investigation->other_remarks = json_encode($other_remark);
        }
        $investigation->in_process = $request->status;
        $investigation->in_process_time = $request->status?now():null;
        $investigation->save();
        return response()->json(['success' => true,'message' => 'Invesigation in-prcess status updated.']);
    }
    public function lab_test_save(Request $request)
    {

        $validate = Validator::make($request->all(), [
            'file' => 'nullable|file|mimes:pdf,jpg,jpeg,png,doc,docx|max:5120',
        ]);

        if ($validate->fails()) {

            if ($request->ajax()) {
                return response()->json([
                    'success' => false,
                    'status'  => 'error',
                    'errors'  => $validate->errors(),
                ], 422);
            }

            return redirect()
                ->back()
                ->withErrors($validate)
                ->withInput();
        }

        $investigation = LabInvestigation::where('lab_order_id',$request->lab_order_id)->firstOrFail();

        if ($request->culture_report??false)
        {
            $natureofSpecimen = $request->nature_of_specimen;
            $method = $request->method;
            $finalInterpretation = $request->final_interpretation;
            $service_id = $request->service_id;
            $service_name = $request->service_name;

            /* -------------------------------
            STORE ORGANISMS AS ARRAY
            -------------------------------- */
            $arrOrganisms = [];

            if (!empty($request->organism)) {
                for ($i = 0; $i < count($request->organism); $i++) {

                    $arrOrganisms[] = [
                        'organism'        => $request->organism[$i],
                        'colony_count'    => $request->colony_count[$i],
                        'organisamTypeId' => $request->organisamTypeId[$i],
                    ];
                }
            }

            /* -------------------------------
            STORE DRUGS AS ARRAY
            -------------------------------- */
            $arrDrugs = [];

            if (!empty($request->drug_name)) {

                // Prepare flat structure first
                $temp = [];
                for ($i = 0; $i < count($request->drug_name); $i++) {
                    $temp[] = [
                        'organism_id'       => $request->organisamId[$i],
                        'drug_Id'        => $request->drug_Id[$i],
                        'interpretation' => $request->interpretation[$i],
                        'mic'            => $request->mic[$i],
                    ];
                }

                // Group by drug_Id
                $grouped = [];
                foreach ($temp as $row) {
                    $grouped[$row['drug_Id']][] = [
                        'organism'       => $row['organism_id'],
                        'drug_Id'        => $row['drug_Id'],
                        'interpretation' => $row['interpretation'],
                        'mic'            => $row['mic'],
                    ];
                }

                // Final structure
                foreach ($grouped as $drugId => $drugValues) {
                    $arrDrugs[] = [
                        'drugId' => $drugId,
                        'drugs'  => $drugValues
                    ];
                }
            }

            /* -------------------------------
            FINAL JSON TO STORE
            -------------------------------- */
            $finalResults = [
                'service_id'       => $service_id,
                'service_name'     => $service_name,
                'natureofSpecimen' => $natureofSpecimen,
                'method'           => $method,
                'finalInterpretation' => $finalInterpretation,
                'organisms'        => $arrOrganisms,  // RAW ARRAY
                'drugs'            => $arrDrugs,      // RAW ARRAY
            ];
            /* echo "<pre>";
            print_r($finalResults);
            echo "</pre>";
            die(); */
            $investigation->test_results = json_encode($finalResults, JSON_PRETTY_PRINT);
            $investigation->status = 'submitted';
            $investigation->reporting_time = now();
            $investigation->save();
        }else{

            $request->validate([
                'input' => 'required',
            ]);

            //  return $request->all();

            $investigation = LabInvestigation::where('lab_order_id',$request->lab_order_id)->firstOrFail();

            $isOutsource = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                ->leftJoin('hospital_services_index','hospital_services.id','=','hospital_services_index.service')
                                ->where('patient_gen_bill.id',$request->lab_order_id)
                                ->value('hospital_services_index.is_outsource');


            $results = ($request->input??[]);
            if($request->hasFile('file')) {
                $file = $request->file('file');
                $uploadPath = public_path('assets/files/outsource_lab_reports');
                if (!file_exists($uploadPath)) {
                    mkdir($uploadPath, 0777, true);
                }
                $fileName = uniqid() . '_' . time() . '.' . $file->getClientOriginalExtension();
                $file->move($uploadPath, $fileName);

                $filePath = 'assets/files/outsource_lab_reports/' . $fileName;
                // unset($results->input);
                $results['old_file'] = $request->old_file;
                $results['file_path'] = $filePath;
            }
            else if($request->input['old_file']??false){
                $results['old_file'] = $request->input['old_file'];
                $results['file_path'] = $request->input['old_file'];
            }
            $investigation->test_results = json_encode($results);
            $investigation->status = 'submitted';
            $investigation->reporting_time = now();
            $investigation->is_outsource = $isOutsource;
            $investigation->save();
        }

        if($request->ajax())
        {
            return response()->json(['success' => true, 'message' => 'Saved Successfully.']);
        }

        return redirect()->route('lab_test.edit',[$request->lab_order_id])->with('success', 'Investigation Result added successfully');
    }


    public function lab_test_save2(Request $request)
    {
        $request->validate([
            'input' => 'nullable',
            'lab_order_id' => 'required',
            'file' => 'nullable|mimes:pdf,doc,docx,jpg,jpeg,png',
            'scope' => 'nullable|in:single,multiple',
            'selected_test_ids' => 'nullable|array',
            'selected_test_ids.*' => 'integer',
        ]);

        $primaryOrder = PatientGenBill::find($request->lab_order_id);
        if (!$primaryOrder) {
            return response()->json(['status' => false, 'message' => 'Investigation order not found.'], 404);
        }

        $billId = $primaryOrder->bill_id;
        $scope = $request->scope ?? 'single';

        // Target test orders determination & Backend security validation
        if ($scope === 'multiple') {
            $selectedTestIds = $request->selected_test_ids ?? [];
            if (empty($selectedTestIds)) {
                return response()->json([
                    'status' => false,
                    'message' => 'Please select at least one test for this report.'
                ], 422);
            }

            // Backend Validation: Fetch valid test IDs belonging ONLY to the current bill
            $validBillTestIds = PatientGenBill::join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
                ->where('patient_gen_bill.bill_id', $billId)
                ->where('hospital_services.flag', 'test')
                ->where('patient_gen_bill.is_deleted', 0)
                ->where(function($q) {
                    $q->whereNull('patient_gen_bill.is_cancelled')->orWhere('patient_gen_bill.is_cancelled', 0);
                })
                ->pluck('patient_gen_bill.id')
                ->map(fn($id) => (int)$id)
                ->toArray();

            // Validate that every submitted test ID strictly belongs to the current bill
            foreach ($selectedTestIds as $testId) {
                if (!in_array((int)$testId, $validBillTestIds)) {
                    return response()->json([
                        'status' => false,
                        'message' => 'Security Error: Test ID #' . $testId . ' does not belong to the current bill (#' . $billId . ').'
                    ], 403);
                }
            }
            $targetTestIds = array_values(array_unique(array_map('intval', $selectedTestIds)));
        } else {
            $targetTestIds = [(int)$request->lab_order_id];
        }

        // Upload physical file ONLY ONCE
        $filePath = null;
        if ($request->hasFile('file')) {
            $file = $request->file('file');
            $uploadPath = public_path('assets/files/outsource_lab_reports');
            if (!file_exists($uploadPath)) {
                mkdir($uploadPath, 0777, true);
            }
            $fileName = uniqid() . '_' . time() . '.' . $file->getClientOriginalExtension();
            $file->move($uploadPath, $fileName);
            $filePath = 'assets/files/outsource_lab_reports/' . $fileName;
        }

        // Transaction safety
        DB::beginTransaction();
        try {
            foreach ($targetTestIds as $testId) {
                $investigation = LabInvestigation::firstOrNew([
                    'lab_order_id' => $testId
                ]);
                $investigation->lab_order_id = $testId;

                $isOutsource = PatientGenBill::leftJoin('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
                    ->leftJoin('hospital_services_index', 'hospital_services.id', '=', 'hospital_services_index.service')
                    ->where('patient_gen_bill.id', $testId)
                    ->value('hospital_services_index.is_outsource');

                $results = json_decode($investigation->test_results, true) ?? [];

                // Preserve existing report path if present (Requirement 11: Do NOT silently overwrite)
                if (!empty($results['file_path']) && $filePath) {
                    $results['old_file'] = $results['file_path'];
                } elseif (!empty($request->old_file)) {
                    $results['old_file'] = $request->old_file;
                }

                if ($filePath) {
                    $results['file_path'] = $filePath;
                }

                if ($scope === 'multiple') {
                    $results['is_multi_bill_report'] = 1;
                    $results['bill_id'] = $billId;
                    $results['shared_with_orders'] = $targetTestIds;
                }

                $investigation->test_results = json_encode($results);
                $investigation->status = 'submitted';
                $investigation->reporting_time = now();
                $investigation->is_outsource = $isOutsource;
                $investigation->save();
            }

            DB::commit();

            $count = count($targetTestIds);
            return response()->json([
                'status' => true,
                'message' => ($scope === 'multiple' && $count > 1)
                    ? "Report uploaded successfully for {$count} tests."
                    : "Report uploaded successfully.",
                'file_path' => $filePath,
                'updated_test_ids' => $targetTestIds,
                'count' => $count
            ]);
        } catch (\Exception $e) {
            DB::rollBack();
            if ($filePath && file_exists(public_path($filePath))) {
                @unlink(public_path($filePath));
            }
            return response()->json([
                'status' => false,
                'message' => 'Failed to save report: ' . $e->getMessage()
            ], 500);
        }
    }

    public function get_lab_test_approve_page(Request $request)
    {


        $request->validate([
            'id'=>'required'
        ]);
        $id = $request->id;
        $user = auth()->user();
