        $investigation = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                    ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                    ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                    ->join('pi','pi.id','=','visitlog.patient_id')
                    ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                    ->leftJoin('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                    ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                    ->select('patient_gen_bill.*',
                        'hospital_services.id as service_id',
                        'hospital_services.service as service_name',
                        'hospital_services.display_full_name as display_full_name',
                        'doctor_db.name as doctor_name',
                        'pi.id as uhid',
                        'patient_billing.created_at as bill_date',
                        'pi.*',
                        'health_insurance_agen.insurance_agen as insurance',
                        'lab_investigations.id as lab_investigation_id',
                        'lab_investigations.lab_order_id as lab_order_id',
                        'lab_investigations.is_outsource as is_outsource',
                        'lab_investigations.status as investigation_status',
                        'lab_investigations.test_results as test_results',
                        )
                    ->where('patient_gen_bill.id',$id)
                    ->where('lab_investigations.status','submitted')
                    ->firstOrFail();


        $test_results = json_decode($investigation->test_results,true);
        /*  echo "<pre>";
        print_r($test_results);
        echo "</pre>";
        die(); */
        $testList = $cutureReportData = collect();
        if($test_results['natureofSpecimen']??false){
            $cutureReportData = $test_results;
        }else{
            //$testList = [];
        if(!$investigation->is_outsource){
            foreach ($test_results as $key => $tests) {
                // Skip strings like 118, "URINE", "Method"
                    if (!is_array($tests)) {
                        continue;
                    }

                    // Skip associative arrays like:
                    // ["organism" => "...", "colony_count" => ...]
                    // because they do NOT contain IDs as keys
                    if (!$this->isNumericKeyArray($tests)) {
                        continue;
                    }

                    // Extract IDs
                    $ids = array_keys($tests);

                    // Fetch data
                    $testList[$key] = HospitalSer::whereIn('id', $ids)
                        ->orderByRaw('FIELD(id, ' . implode(',', $ids) . ')')
                        ->get();
                }
            /*  foreach($test_results as $key=>$tests){
                    $testList[$key] = HospitalSer::whereIn('id', array_keys($tests))
                                                    ->orderByRaw('FIELD(id, ' . implode(',', array_keys($tests)) . ')')
                                                    ->get();
                }      */
            }
        }


        return view('admin.patient.lab_test.lab_test_approve_data',compact('id','investigation','test_results','testList', 'cutureReportData'));

    }
