    public function lab_test_approve(Request $request)
    {
       //dd($request->all());
        $request->validate([
            'lab_order_id' => 'required',
        ]);

        $investigation = LabInvestigation::where('lab_order_id',$request->lab_order_id)->firstOrFail();
        $investigation->status = 'approved';
        $investigation->approval_time = now();
        $investigation->approved_by = auth()->user()->id;
        $investigation->save();

        PatientGenBill::where('id', $request->lab_order_id)->update(['is_abdm_approved' => 1]);

        // Auto-register and link ABDM Diagnostic Report (Lab) Care Context
        try {
            $order = PatientGenBill::find($request->lab_order_id);
            if ($order) {
                $bill = PatientBilling::find($order->bill_id);
                $visit = $bill ? Visitlog::find($bill->visit_id) : null;
                $patientId = $visit ? $visit->patient_id : ($bill ? $bill->patient_id : null);
                $hospitalId = $visit ? ($visit->hospital_id ?? 1) : (auth()->check() ? (auth()->user()->org_id ?? 1) : 1);
                $isIpd = $visit && in_array((int)($visit->visit_status ?? 0), [1, 2]);
                $testName = $order->service_name ?? ($order->item_name ?? null);

                if ($patientId && \Illuminate\Support\Facades\Schema::hasTable('patient_care_contexts') && \App\Helpers\LicenseKey::isModuleActiveAndValid('abha', (int)$hospitalId)) {
                    app(\App\Services\ABDM\CareContextManagerService::class)->registerLabContext(
                        visitId: $visit ? $visit->id : null,
                        genBillId: (int)$order->id,
                        patientId: (int)$patientId,
                        hospitalId: (int)$hospitalId,
                        testName: $testName,
                        isIpd: $isIpd,
                        autoLink: true
                    );
                }
            }
        } catch (\Throwable $e) {
            \Illuminate\Support\Facades\Log::channel('abdm')->warning("[lab_test_approve] Auto-linking lab care context failed: " . $e->getMessage());
        }

        // $this->lab_test_report_send($request);
        if ($request->ajax())
        {
            return response()->json(['success'=>true,'message'=>'Test Approved']);
        }

        return redirect()->route('lab_test.orders')->with('success', 'Investigation result approved successfully');
    }
    public function lab_test_disapprove(Request $request)
    {
        $request->validate([
            'lab_order_id' => 'required',
        ]);

        $investigation = LabInvestigation::where('lab_order_id',$request->lab_order_id)->firstOrFail();
