        PatientGenBill::where('id', $request->lab_order_id)->update(['is_abdm_approved' => 0]);

        return response()->json(['success' => true,'message' => 'Disapproved successfully']);

    }
    public function lab_test_report_show_print(Request $request)
    {

        $labInvestigation = LabInvestigation::where('lab_order_id', $request->id)->first();

        if ($labInvestigation && $labInvestigation->is_outsource) {

            if($labInvestigation->status != 'approved')
            {
                return redirect()->back()->with('error', 'This report is not approved yet.');
            }
            $data = json_decode($labInvestigation->test_results);
            $file = $data->file_path ?? ""; // or file_path depending on how you saved
            $filePath = public_path($file); // full server path
            if ($file && file_exists($filePath)) {

                $this->mark_lab_test_as_printed($request->id);

                return response()->file($filePath); // stream file
            }
        }

        $views = $this->lab_test_report_print([$request->id]);

        if (!$views) {
            return redirect()->back()->with('error', 'Report not found or has no results to print.');
        }

        // return $views;
        $pdf = Pdf::loadHTML($views)
            ->setPaper('A4', 'portrait') // Set paper size and orientation
            ->setOptions([
                'isHtml5ParserEnabled' => true,
                'isRemoteEnabled' => true,
                'isPhpEnabled' => true,
            ]);
        $this->mark_lab_test_as_printed($request->id);
        // return $pdf->download('lab_report_' . $request->id . '.pdf');
        // return $views;
        return $pdf->stream();
    }


    public function lab_test_report_show_print2(Request $request)
    {


        $showHeader = $request->boolean('header');

        $labInvestigation = LabInvestigation::where(
            'lab_order_id',
            $request->id
        )->first();


        /*
        |--------------------------------------------------------------------------
        | Outsourced Report
        |--------------------------------------------------------------------------
        */

        if ($labInvestigation && $labInvestigation->is_outsource) {

            /*
            * Only approved reports can be printed
            */
            if ($labInvestigation->status !== 'approved') {

                return redirect()
                    ->back()
                    ->with(
                        'error',
                        'This report is not approved yet.'
                    );
            }


            /*
            * Get uploaded report file
            */
            $data = json_decode(
                $labInvestigation->test_results
            );

            $file = $data->file_path ?? '';

            $filePath = public_path($file);


            /*
            * If report exists, generate PDF with
            * hospital header
            */
            if ($file && file_exists($filePath)) {

                $this->mark_lab_test_as_printed(
                    $request->id
                );

                return $this->generateOutsourceLabPdf(
                    $filePath,
                    $request->id,
                    $showHeader
                );
            }
        }


        /*
        |--------------------------------------------------------------------------
        | Normal Internal Lab Report
        |--------------------------------------------------------------------------
        */

        $views = $this->lab_test_report_print([
            $request->id
        ]);


        $pdf = Pdf::loadHTML($views)
            ->setPaper('A4', 'portrait')
            ->setOptions([
                'isHtml5ParserEnabled' => true,
                'isRemoteEnabled' => true,
                'isPhpEnabled' => true,
            ]);


        $this->mark_lab_test_as_printed(
            $request->id
        );


        return $pdf->stream(
            'lab_report_' . $request->id . '.pdf'
        );
    }






private function generateOutsourceLabPdf(
    string $filePath,
    int $labOrderId,
    bool $showHeader
) {
    /*
    |--------------------------------------------------------------------------
    | Render Existing Main Header Component
    |--------------------------------------------------------------------------
    */


    if(!$showHeader) {
        $headerHtml = '';
    } else {
        $headerHtml = view('components.main-header', [
            'bill' => $labOrderId,
        ])->render();
    }

    // $headerHtml = view('components.main-header', [
    //     'bill' => $labOrderId,
    // ])->render();


    /*
    |--------------------------------------------------------------------------
    | Create mPDF Instance
    |--------------------------------------------------------------------------
    */

    $mpdf = new Mpdf([
        'format' => 'A4',
        'orientation' => 'P',

        'margin_left' => 0,
        'margin_right' => 0,
        'margin_top' => 0,
        'margin_bottom' => 0,
    ]);


    /*
    |--------------------------------------------------------------------------
    | Import Existing PDF
    |--------------------------------------------------------------------------
    */

    $pageCount = $mpdf->SetSourceFile($filePath);


    /*
    |--------------------------------------------------------------------------
    | Process Every Page
    |--------------------------------------------------------------------------
    */

    for ($pageNo = 1; $pageNo <= $pageCount; $pageNo++) {

        $templateId = $mpdf->ImportPage($pageNo);

        $size = $mpdf->GetTemplateSize($templateId);

        $orientation = $size['width'] > $size['height']
            ? 'L'
            : 'P';


        /*
        |--------------------------------------------------------------------------
        | Add Page
        |--------------------------------------------------------------------------
        */

        $mpdf->AddPageByArray([
            'orientation' => $orientation,

            'sheet-size' => [
                $size['width'],
                $size['height'],
            ],

            'margin-left' => 0,
            'margin-right' => 0,
            'margin-top' => 0,
            'margin-bottom' => 0,
        ]);


        /*
        |--------------------------------------------------------------------------
        | Place Original PDF
        |--------------------------------------------------------------------------
        */

        $mpdf->UseTemplate(
            $templateId,
            0,
            0,
            $size['width'],
            $size['height']
        );


        /*
        |--------------------------------------------------------------------------
        | Add Hospital Header
        |--------------------------------------------------------------------------
        */

        if ($pageNo === 1) {

            $mpdf->WriteFixedPosHTML(
                $headerHtml,

                5, // Left
                2, // Top

                $size['width'] - 10,
                35 // Header space height in mm
            );
        }
    }


    /*
    |--------------------------------------------------------------------------
    | Return Final PDF
    |--------------------------------------------------------------------------
    */

    $fileName = 'lab_report_' . $labOrderId . '.pdf';

    return response(
        $mpdf->Output($fileName, 'S'),
        200,
        [
            'Content-Type' => 'application/pdf',
            'Content-Disposition' =>
                'inline; filename="' . $fileName . '"',
        ]
    );
}

    private function mark_lab_test_as_printed($id)
