        if(auth()->user()->can('module-permission',['lab_test','can_read']))
        {
            $labInvestigation = LabInvestigation::where('lab_order_id', $id)->first();
            if($labInvestigation){
                $labInvestigation->is_printed = 1;
                $labInvestigation->save();
            }
        }
    }
    public function lab_test_report_trend($id,$withHeader = false)
    {
        $user = Auth::user();
        $org_id = $user->org_id;

        $order = PatientGenBill::find($id);
        $bill = $order->patientBilling;
        $visit = $bill->visit;
        $patient = $visit->patient;
        $patientID = $visit->patient_id;
        $serviceID = $order->service_id;

        $timeFilter = request()->filter_range??'15_days';
        $filterDays = date('Y-m-d',strtotime("-".str_replace('_',' ',$timeFilter)));

        $investigationList = PatientGenBill::leftJoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                                ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                ->join('pi','pi.id','=','visitlog.patient_id')
                                ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                                ->select(
                                    // 'patient_gen_bill.*',
                                    'hospital_services.id as service_id',
                                    'hospital_services.service as service_name',
                                    // 'hospital_services.is_group',
                                    // 'hospital_services.is_subgroup',
                                    // 'hospital_services.group_attributes',
                                    // 'doctor_db.name as doctor_name',
                                    // 'pi.id as uhid',
                                    // 'patient_billing.created_at as bill_date',
                                    // 'pi.*',
                                    // 'lab_investigations.id as lab_investigation_id',
                                    // 'lab_investigations.lab_order_id',
                                    // 'lab_investigations.status as investigation_status',
                                    'lab_investigations.test_results',
                                    // 'lab_investigations.is_outsource',
                                    // 'lab_investigations.sample_collect_time',
                                    // 'lab_investigations.approval_time',
                                    'patient_gen_bill.created_at as gen_bill_date'
                                )
                                ->where('lab_investigations.is_outsource',0)
                                ->where('visitlog.patient_id', $patientID)
                                ->where('patient_gen_bill.service_id', $serviceID)
                                ->whereNotNull('lab_investigations.test_results')
                                ->where('patient_gen_bill.created_at','>=',date('Y-m-d',strtotime("-".(str_replace('_',' ',$timeFilter))."")))
                                ->orderBy('patient_gen_bill.created_at','ASC')
                                ->limit(6)
                                ->get();

        if($investigationList->isEmpty())
        {
            return false;
        }
        $trend = [];      // param ΓåÆ date ΓåÆ result
        $dateHeaders = []; // Ordered date list

        foreach ($investigationList as $inv) {

            $date = \Carbon\Carbon::parse($inv->gen_bill_date)->format('d/m/y');

            // Keep unique order
            if (!in_array($date, $dateHeaders)) {
                $dateHeaders[] = $date;
            }

            $results = json_decode($inv->test_results, true);

            foreach ($results as $groupName => $itemList) {
                foreach ($itemList as $paramKey => $param) {

                    $trend[$groupName][$paramKey]['range'][$date]   = $param['biological_reference_range'] ?? null;
                    $trend[$groupName][$paramKey]['details'][$date] = $param['value'] ?? null;
                }
            }
        }

        // dd($investigationList);

        return view('admin.pdf.lab_investigation.trend_view',compact('trend', 'dateHeaders','patient','id','investigationList','order'))->render();
    }
    public function lab_test_report_print(array $id,$withHeader = false)
    {
        $user = Auth::user();
        $org_id = $user->org_id;

        $investigationList = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                    ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                    ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                    ->join('pi','pi.id','=','visitlog.patient_id')
                    ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                    ->leftJoin('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                    ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                    ->leftjoin('ipd_details','ipd_details.visit_table_id','=','visitlog.id')
                    ->select('patient_gen_bill.*',
                        'hospital_services.id as service_id',
                        'hospital_services.service as service_name',
                        'hospital_services.is_group as is_group',
                        'hospital_services.is_subgroup as is_subgroup',
                        'hospital_services.group_attributes as group_attributes',
                        'doctor_db.name as doctor_name',
                        'pi.id as uhid',
                        'patient_billing.created_at as bill_date',
                        'pi.*',
                        'health_insurance_agen.insurance_agen as insurance',
                        'lab_investigations.id as lab_investigation_id',
                        'lab_investigations.lab_order_id as lab_order_id',
                        'lab_investigations.status as investigation_status',
                        'lab_investigations.test_results as test_results',
                        'lab_investigations.is_outsource as is_outsource',
                        'lab_investigations.sample_collect_time as sample_collect_time',
                        'lab_investigations.approval_time as approval_time',
                        // 'patient_gen_bill.created_at as gen_bill_date',
                        DB::raw('COALESCE(patient_gen_bill.service_delivered_at, patient_gen_bill.created_at) as gen_bill_date'),

                        // Visit information
                        'visitlog.visit_status',
                        'visitlog.id as visit_id',
                        'ipd_details.id as ipd_no',
                        )
                    ->whereIn('patient_gen_bill.id',$id)
                    ->where('lab_investigations.test_results',"!=",NULL)
                    ->orderByRaw('FIELD(patient_gen_bill.id, ' . implode(',', $id) . ')')
                    ->get();
        // dd($investigationList[0]->visit_status);


        if($investigationList->isEmpty())
        {
            return false;
        }

        $lab_order_list_version = HospitalSetting::where('hospital_id',auth()->user()->org_id)
                            ->where('identifier','lab_result_page_version')
                            ->first()->current_setting??'v2';

    //    dd($lab_order_list_version);

        return view('admin.pdf.lab_investigation.'.$lab_order_list_version.'.page',compact('investigationList','withHeader'))->render();
    }


    public function test_report($id){

        $test = PatientGenBill::join('lab_investigations','lab_investigations.lab_order_id','=','patient_gen_bill.id')
                                ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                                ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                ->join('pi','pi.id','=','visitlog.patient_id')
                                ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                ->leftJoin('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
