     public function lab_test_report_print_bulk(Request $request)
    {
        $billIds = PatientGenBill::where('bill_id',$request->pbill_id)->pluck('id')->toArray();
        if($request->items)
        {
            // $items = explode(',', $request->items);
            // $items = array_filter($items, fn($e) => in_array($e, $billIds));
            // sort($items, SORT_NUMERIC);
            // $billIds = $items;
            $items = explode(',', $request->items);

                // keep only values present in $billIds
                $items = array_filter($items, fn($e) => in_array($e, $billIds));

                // sort in ascending order (numeric or string as needed)
                sort($items, SORT_NUMERIC); // for numbers
                // sort($items, SORT_STRING); // for strings

                $billIds = $items;
        }
        $views =  $this->lab_test_report_print($billIds);
        // return $views;
        if($views){
            $pdf = Pdf::loadHTML($views)
                ->setPaper('A4', 'portrait') // Set paper size and orientation
                ->setOptions([
                    'isHtml5ParserEnabled' => true,
                    'isRemoteEnabled' => true,
                    'isPhpEnabled' => true,
                ]);

            // return $pdf->download('lab_report_' . $request->id . '.pdf');
            return $pdf->stream('lab_report_' . $request->id . '.pdf');
        }
        else{
            return redirect()->back()->with('error','Report is not ready');
        }
        // return $views;
    }



    public function copy_tests_to_ipd(Request $request)
    {
        $request->validate(['bill_id' => 'required']);

        $bill = PatientBilling::findOrFail($request->bill_id);
        $visit = Visitlog::findOrFail($bill->visit_id);

        $patient = Patient::findOrFail($visit->patient_id);
        $billItems = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                        ->select('patient_gen_bill.*',
                            'hospital_services.service as service_name')
                        ->where('patient_gen_bill.bill_id',$bill->id)->get();

        $billPayment = BillingPaymentType::where('bill_id',$bill->id)->first();

        $IPDAdmitList = Visitlog::where('patient_id',$patient->id)->where('visit_status',1)->first();

        return view('admin.patient.lab_test.lab_test_copy_bill',compact('bill','patient','billItems','billPayment','IPDAdmitList'))->render();
    }
    public function save_tests_to_ipd(Request $request)
    {
        $request->validate(['bill_id' => 'required']);

        // dd($request->all());

        $user_id = auth()->user()->id;
        $org_id = auth()->user()->org_id;

        $bill = PatientBilling::findOrFail($request->bill_id);
        $billItems = PatientGenBill::where('bill_id',$bill->id)->get();
        $billPayments = BillingPaymentType::where('bill_id',$bill->id)->first();

        $IPDVisit = Visitlog::where('patient_id',$bill->patient_id)->where('visit_status',1)->first();
        $IPDDetails = Ipd_details::where('visit_table_id',$IPDVisit->id)->first();

        if($IPDVisit && $IPDDetails)
        {
            // STEP 1 - Generate New Refund Bill
            $newBill = new PatientBilling;

            $bill_remark = "";
            if($request->cut_percent??false){
                $bill_remark .= "Amount has been deduced with cut : ".$request->cut_percent."%  & ";
            }
            if($request->cut_amount??false){
                $bill_remark .= "Amount has been deduced with amount : ".$request->cut_amount." & ";
            }


            $newBill = $bill->replicate()->fill([
                'visit_id' => $IPDVisit->id,
                'bill_tag' => 'refund',
                'tag_ref_id' => $bill->id,
                'created_by' => $user_id,
                'bill_remark' => ($request->refund_to =='ipd')?$bill_remark."Amount has been transferred to IPD":$bill_remark.'Amount has been refunded to customer',
            ]);
            $newBill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($IPDVisit->id);


            $newBill->save();

            // STEP 2 - Copy Bill Items , Test Results
            foreach($billItems as $billItem)
            {

                //Copy Bill Items
                $gen = $billItem->replicate()->fill([
                    'bill_id' => $newBill->id,
                    'created_by' => $user_id,
                ]);
                $gen->save();

                // Copy Test Results
                $labTest = LabInvestigation::where('lab_order_id',$billItem->id)->first();
                if($labTest)
                {
                    $test = $labTest->replicate()->fill([
                        'lab_order_id'          => $gen->id,
                        'created_at'            => now(),
                        'sample_collect_time'   => now(),
                        'reporting_time'        => now()->addMinutes(5),
                        'approval_time'         => now()->addMinutes(10),
                        'updated_at'            => now()->addMinutes(10),
                    ]);
                    $test->save();
                    // Mark Old Investigation as Cancelled
                }

                // $where = ['lab_order_id'=>$billItem->id];
                // $update = ['status'=>'cancelled', 'cancelled_by'=>$user_id, 'cancelled_at'=>now(), 'cancelled_reason'=>'Tests already has done, A new bill has been generated'];
                // LabInvestigation::updateOrInsert($where,$update);



                $serviceIndex = HospitalService::where('service',$billItem->service_id)->where('hospital_id',$org_id)->first();

                // Create IPD billing
                IPDBilling::create([
                    'name' => $billItem->service_id,
                    'date' => $billItem->created_at,
                    'cgst' => $serviceIndex->service_cgst,
                    'sgst' => $serviceIndex->service_sgst,
                    'quantity' => $billItem->qty,
                    'charges' => $billItem->charges,
                    'uhid' => $bill->patient_id,
                    'admission_id' => $IPDDetails->id,
                    'hospital_id' => $org_id,
                    'flag' => 'diagnostic',
                ]);
            }


            // STEP 3 - Enter Refund Payment Details
            $paytype = new BillingPaymentType;
            $paytype->bill_id = $newBill->id;
            $paytype->payment_type = 'Refund';
            $paytype->cash = $request->input('cash',0);
            $paytype->upi =  $request->input('upi',0);
            $paytype->debit_card =  $request->input('debit',0);
            $paytype->cash_transId =  $request->input('cash_trans');
            $paytype->upi_transId = $request->input('upi_trans');
            $paytype->debit_transId = $request->input('debit_trans');
            $paytype->credit_transId = '';
            $paytype->flag = "opd";
            $paytype->created_by = $user_id;
            $paytype->save();

            // STEP 4 - Enter Payment Details to IPD bill if they submitted in IPD
            if($request->refund_to =='ipd')
            {
                $paytype = new BillingPaymentType;
                $paytype->payment_type = 'Transferred from OPD';

                if($request->cash??false)
                {
                    $paytype->payment_mode = 'Cash';
                    $paytype->cash = $request->input('cash',0);
                    $paytype->cash_transId =  $request->input('cash_trans');

                }else if($request->upi??false)
                {
                    $paytype->payment_mode = 'UPI';
                    $paytype->upi =  $request->input('upi',0);
                    $paytype->upi_transId = $request->input('upi_trans');

                }else if($request->debit??false)
                {
                    $paytype->payment_mode = 'Debit Card';
                    $paytype->debit_card =  $request->input('debit',0);
                    $paytype->debit_transId = $request->input('debit_trans');
                }
                $paytype->bill_id = $IPDDetails->id;
                $paytype->credit_transId = '';
                $paytype->flag = "ipd";
                $paytype->created_by = $request->input('collect_by_ipd');
                $paytype->save();
            }

            return response()->json(['status' => true,'message' => 'Tests Copied and Amount trasferred to successfully','refund_bill_id'=>$newBill->id]);
        }else{

            return response()->json(['status' => false,'message' => 'Patient Not Admitted']);
        }

    }



    public function generate_lab_test_sample_ids(Request $request)
    {
        $request->validate([
            'id' => 'required',
            'index' => 'required|array'
        ]);

        $investigation = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                    ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                    ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                    ->join('pi','pi.id','=','visitlog.patient_id')
                    ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                    ->select('patient_gen_bill.*',
                        'hospital_services.service as service_name',
                        'hospital_services.group_attributes as group_attributes',
                        'doctor_db.name as doctor_name',
                        'patient_gen_bill.created_at as bill_date',
                        'pi.id as uhid',
                        'pi.prefix as prefix',
                        'pi.Fname as fname',
                        'pi.Lname as lname',
                        'pi.sex as sex',
                        'pi.age as age',
                        'pi.mobile_no as phone',
                        )
                    ->where('patient_gen_bill.id',$request->id)
                    ->firstOrFail();

        $group_attributes = json_decode($investigation->group_attributes,true);
        foreach ($request->index as $i){
            if($group_attributes['sample']['sample_type'][$i]??false){
                DB::table('lab_sample_labels')->insertGetId([
                    'lab_order_id' => $investigation->id,
                    'sample_type' => $group_attributes['sample']['sample_type'][$i],
                    'sample_quantity' => $group_attributes['sample']['quantity'][$i],
                    'sample_unit' => $group_attributes['sample']['unit'][$i],
                    'vial_type' => $group_attributes['sample']['vial'][$i],
                ]);
            }
        }
        return response()->json(['success' => true,'message' => 'Sample Label Generated Successfully']);
    }
