    public function generate_test_samples_id_v3(Request $request)
    {
        // dd($request->all());
        $count = 0;

        foreach ($request->groups as $groupKey => $orders) {
            if ($groupKey === 'no-group_in') {
                // For ungrouped ΓåÆ each order gets its own sample ID
                foreach ($orders as $order) {
                    $firstService = PatientGenBill::find($order['order_id'])->service;
                    $attributes = json_decode($firstService->group_attributes ?? '{}', true);
                    $count++;
                    DB::table('lab_sample_labels')->insert([
                        'lab_order_ids'   => json_encode([(int) $order['order_id']]),
                        'sample_type'     => $attributes['sample']['sample_type'][0] ?? null,
                        'sample_quantity' => $attributes['sample']['quantity'][0] ?? null,
                        'sample_unit'     => $attributes['sample']['unit'][0] ?? null,
                        'vial_type'       => $attributes['sample']['vial'][0] ?? null,
                        'is_outsource'    => (int) $order['is_outsource'],
                    ]);
