    public function get_lab_sample_history(Request $request)
    {
        $orderID = $request->order_id;
        $billItem = PatientGenBill::findOrFail($orderID);
        $bill = PatientBilling::findOrFail($billItem->bill_id);

        $visit = $bill->visit;
        $patient = $visit->patient;

        $visitIds = Visitlog::where('patient_id', $patient->id)->pluck('id')->toArray();
        $testBillIds = PatientBilling::whereIn('visit_id', $visitIds)->pluck('id')->toArray();

        $testOrders = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                        ->whereIn('patient_gen_bill.bill_id', $testBillIds)
                        ->where('hospital_services.flag',"test")
                        ->where('hospital_services.flag',"!=",'refund')
                        ->where('hospital_services.flag',"!=",'balance')
                        ->where('patient_gen_bill.is_deleted',0)
                        ->whereNull('patient_gen_bill.is_cancelled')
                        ->where('hospital_services.is_reserved',"=",0)
                        ->pluck('patient_gen_bill.id')->toArray();

        $samples = DB::table('lab_sample_labels')
                    ->where(function ($q) use ($testOrders) {
                        foreach ($testOrders as $orderId) {
                            $q->orWhereJsonContains('lab_order_ids', $orderId);
                        }
                    })
                    ->orderBy('id', 'desc')->get();

        return view('admin.patient.lab_test.sample_history_table',compact('orderID','samples','patient'));
    }
    public function pick_sample_for_rerun(Request $request)
    {
        $sampleID = $request->sample_id;
        $orderID = $request->order_id;
        $sample = DB::table('lab_sample_labels')->where('id',$sampleID)->first();
        if($sample){
            $orderIds = json_decode($sample->lab_order_ids,true);

            $orderIds[] = (int)$orderID;

            DB::table('lab_sample_labels')->where('id',$sampleID)->update([
                'lab_order_ids' => json_encode(array_unique($orderIds))
            ]);

            return response()->json([
                'success' => true,
                'message' => 'Sample status updated successfully.',
            ]);

        }else{
            return response()->json([
                'success' => false,
                'message' => 'Sample not found.',
            ]);
        }
    }
    public function update_lab_sample_status_v3(Request $request)
    {

        $request->validate([
            'sample_condition' => 'required|array',
        ]);

        $sampleCondition = $request->input('sample_condition', []);
        $sampleCollectionTime = $request->input('sample_collection_time', []);
        $analyzer = $request->input('analyzer', []);
        $sampleOutsourceTo = $request->input('sample_outsource_to', []);

        foreach ($sampleCondition as $sampleId => $condition) {
            $sample = DB::table('lab_sample_labels')->where('id', $sampleId)->first();

            if (!$sample) {
                continue;
            }

            $orderIds = json_decode($sample->lab_order_ids, true);

            $isOutsource = isset($sampleOutsourceTo[$sampleId]) ? 1 : 0;

            if ($condition == 'Good' && is_array($orderIds)) {
                foreach ($orderIds as $orderId) {
                    $request->merge(['order_id' => $orderId,'outsource'=>$isOutsource]);
                    $this->lab_test_save_sample($request);
                }
            }

            DB::table('lab_sample_labels')
                ->where('id', $sampleId)
                ->update([
                    'condition' => $condition,
                    'collect_time' => $sampleCollectionTime[$sampleId] ?? now(),
                    'lis_context' => $analyzer[$sampleId] ?? null,
                    'is_outsource' => $isOutsource,
                    'outsource_lab_id' => $sampleOutsourceTo[$sampleId] ?? null,
                    'collected_by' => auth()->user()->id,
                ]);
        }

        return response()->json([
            'success' => true,
            'message' => 'Sample status updated successfully.',
        ]);

    }
    public function generate_test_sample_id_for_all_v2(Request $request)
    {
        $request->validate([
            'bill_id' => 'required',
        ]);

        $investigations = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                    ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                    ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                    ->join('pi','pi.id','=','visitlog.patient_id')
                    ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                    ->select('patient_gen_bill.*',
                        'hospital_services.service as service_name',
                        'hospital_services.group_attributes as group_attributes',
                        'doctor_db.name as doctor_name',
                        'patient_gen_bill.created_at as bill_date',
                        'pi.id as uhid',
                        'pi.prefix as prefix',
                        'pi.Fname as fname',
                        'pi.Lname as lname',
                        'pi.sex as sex',
                        'pi.age as age',
                        'pi.mobile_no as phone',
                        )
                    ->where('hospital_services.flag',"test")
                    ->where('hospital_services.flag',"!=",'refund')
                    ->where('hospital_services.flag',"!=",'balance')
                    ->where('patient_gen_bill.is_deleted',0)
                    ->whereNull('patient_gen_bill.is_cancelled')
                    ->where('hospital_services.is_reserved',"=",0)
                    ->where('patient_gen_bill.bill_id',$request->bill_id)
                    ->get();
        try{
            DB::beginTransaction();

            foreach($investigations as $investigation)
            {
                $attributes = json_decode($investigation->group_attributes??'[]',true);
                $lis = \DB::table('lis_service_mapping')
                                ->where('service_id',$investigation->service_id)
                                ->where('hospital_id',auth()->user()->org_id)
                                ->where('active',1)
                                ->first();
                if($attributes)
                {
                    foreach($attributes['sample']['sample_type']??[] as $i => $sampleType)
                    {
                        \DB::table('lab_sample_labels')->insertGetId([
                                'lab_order_id' => $investigation->id,
                                'sample_type' => $sampleType,
                                'sample_quantity' => $attributes['sample']['quantity'][$i],
                                'sample_unit' => $attributes['sample']['unit'][$i],
                                'vial_type' => $attributes['sample']['vial'][$i],
                                'condition' => "Good",
                                'collect_time' => now(),
                                'lis_context' => $lis->lis_context??null,
                                'collected_by' => auth()->user()->id,
                            ]);
                    }
                }

                $request->merge(['order_id' => $investigation->id]);
                $this->lab_test_save_sample($request);
            }
            DB::commit();
            return response()->json(['success' => true,'message' => 'Sample Label Generated Successfully']);
        } catch (\Throwable $th) {
            DB::rollBack();
            return response()->json(['success' => false,'message' => $th->getMessage()]);
        }

    }
