    private function lab_test_report_send(Request $request)
    {
        $org_id = Auth::user()->org_id;
        $record = \DB::table('hospital_print_settings')->where('hospital_id', $org_id)->first();
        $labSetting = json_decode($record->lab_investigation??'', true);

        $headerImage = $labSetting['header_image'] ?? null;
        $footerImage = $labSetting['footer_image'] ?? null;

        if (\App\Helpers\HospitalHelper::isSettingEnabled($org_id, 'lab_header_change_as_per_date')) {
            $dateSetting = \DB::table('hospital_setting_data')
                ->where('hospital_id', $org_id)
                ->where('key', 'lab_header_as_per_date')
                ->first();
            if ($dateSetting) {
                $dateData = json_decode($dateSetting->data, true);
                $genBill = PatientGenBill::find($request->lab_order_id);
                $reportDate = $genBill ? date('Y-m-d', strtotime($genBill->service_delivered_at ?? $genBill->created_at)) : date('Y-m-d');
                if (!empty($dateData['date']) && $reportDate < $dateData['date']) {
                    if (!empty($dateData['header_image'])) {
                        $headerImage = $dateData['header_image'];
                    }
                    if (!empty($dateData['footer_image'])) {
                        $footerImage = $dateData['footer_image'];
                    }
                }
            }
        }


        $request->id = $request->lab_order_id;
        if(isset($headerImage) && $headerImage != ''){
            $headerHtml = '<div style="text-align: center;"><img src="' . asset($headerImage) . '" style="width: 100%;" /></div>';
            $request->header = $headerHtml;
        }
        if(isset($footerImage) && $footerImage != ''){
            $footerHtml = '<div style="text-align: center;"><img src="' . asset($footerImage) . '" style="width: 100%; height: 50px;" /></div>';
            $request->footer = $footerHtml;
        }

        // Load PDF with the content
        $views = $this->lab_test_report_print([$request->lab_order_id]);

        // echo ($headerHtml);
        // dd($headerHtml);
        $pdf = Pdf::loadHTML($views)
            ->setPaper('A4', 'portrait') // Set paper size and orientation
            ->setOptions([
                'isHtml5ParserEnabled' => true,
                'isRemoteEnabled' => true,
            ]);
        $b_id = $request->lab_order_id;

        if (!file_exists('assets/files/lab_reports')) {
            mkdir('assets/files/lab_reports/', 0777, true);
        }

        $pdfFilename = 'lab_report_' . $b_id . '.pdf';
        $pdfPath = 'assets/files/lab_reports'.$pdfFilename;
        $pdf->save($pdfPath);

        $hospital = Healtcare_org::find($org_id);
        $genBill = PatientGenBill::find($b_id);
        $bill = PatientBilling::find($genBill->bill_id);


        $visit = Visitlog::find($bill->visit_id);
        $patient = Patient::find($visit->patient_id);

        // Notifier::lab_investigation([
        //     'patient_id' => $patient->id,
        //     'phone_number' => $patient->mobile_no,
        //     'params' => [
        //         'patient_name'=> $patient->prefix.' '.$patient->Fname.' '.$patient->Lname,
        //         'hospital_name'=>$hospital->name??'',
        //         'pdf'=>($pdfPath),
        //         ]
        //     ]);

        return $pdfPath;
    }
