    function lab_test_send_whatsapp(Request $request)
    {
        $b_id = $request->pbill_id;
        $org_id = auth()->user()->org_id;

        $hospital = Healtcare_org::find($org_id);
        $bill = PatientBilling::find($b_id);
        $visit = Visitlog::find($bill->visit_id);
        $patient = Patient::find($visit->patient_id);

        $whatsapp_without_verification = \App\Helpers\HospitalHelper::isSettingEnabled($org_id,'whatsapp_without_verification');

        if(!$whatsapp_without_verification){
            if(!$patient->mnvs)
            {
                return response()->json(['success' => false,'message' => 'Need to Verify Mobile Number']);
            }
        }


        $request->pbill_id = $request->pbill_id;
        $oID = $request->order_id;
        $oIDs = $request->order_ids;
        $outSourchReport = false;
        // dd($request->pbill_id);
        $billsIDs = PatientGenBill::where('bill_id',$request->pbill_id)->pluck('id')->toArray();
        if($oID??false){
            if(in_array($oID,$billsIDs)){

                $labInvestigation = LabInvestigation::where('lab_order_id', $oID)->first();
                if ($labInvestigation->is_outsource) {
                    if($labInvestigation->status != 'approved'){
                        return redirect()->back()->with('error', 'This report is not approved yet.');
                    }
                    $data = json_decode($labInvestigation->test_results);
                    $file = $data->file_path ?? ""; // or file_path depending on how you saved
                    $filePath = ''.($file);
                    $outSourchReport = $filePath;
                }
                $billsIDs = [$oID];
                $b_id = $oID;
            }else{
                return response()->json(['success' => false,'message' => 'Invalid Order ID']);
            }
        }
        if($oIDs??false){
            $billsIDs = $oIDs;
        }

        if($outSourchReport)
        {
            $pdfPath = $outSourchReport;
        }else{
            $views = $this->lab_test_report_print($billsIDs,true);
            // echo ($headerHtml);
            // dd($headerHtml);
            $pdf = Pdf::loadHTML($views)
                ->setPaper('A4', 'portrait') // Set paper size and orientation
                ->setOptions([
                    'isHtml5ParserEnabled' => true,
                    'isRemoteEnabled' => true,
                ]);


            if($oID){
                $b_id = $oID;
            }
            $pdfFilename = 'lab_report_' . $b_id . '.pdf';
            $pdfPath = 'assets/files/lab_reports/'.$pdfFilename;
            $pdf->save($pdfPath);
        }

        Notifier::lab_investigation([
            'patient_id' => $patient->id,
            'phone_number' => $patient->mobile_no,
            'order_id' => $b_id,
            'params' => [
                'patient_name'=> $patient->prefix.' '.$patient->Fname.' '.$patient->Lname,
                'hospital_name'=>$hospital->name??'',
                'hospital_contact'=>$hospital->contact_no??'',
                'pdf'=>($pdfPath),
                ]
        ]);

        return response()->json(['success' => true,'message' => 'Whastapp Send Request Added Successfully']);
    }
