    public function save_sample_lab_sample_group_service_index(Request $request)
    {
        $data = $request->input('data', []);

        // Safety check ΓÇö if no data, just skip
        if (empty($data)) {
            return response()->json(['status' => 'error', 'message' => 'No data provided'], 400);
        }

        \DB::table('lab_sample_group_index')->truncate();
        // Prepare insert array
        $insertData = [];
        foreach ($data as $row) {
            $insertData[] = [
                'sample_group_id' => $row['group_id'],
                'service_id'      => $row['service_id'],
                'created_at'      => now(),
                'updated_at'      => now()
            ];
        }

        // Insert all at once
        \DB::table('lab_sample_group_index')->insert($insertData);

        return response()->json(['status' => true, 'message' => 'Data saved successfully']);
    }
