    function copy_lis_report(Request $request,$logID,$oID)
    {
        $lisLog = \DB::table('lis_logs')->where('id',$logID)->first();
        if($lisLog->context == 'sysmex_hl_series')
        {
            $sample = \DB::table('lab_sample_labels')->whereJsonContains('lab_order_ids',(int)$oID)->first();
        }
        elseif($lisLog->context == 'erba_em200')
        {
            $sample = \DB::table('lab_sample_labels')->whereJsonContains('lab_order_ids',(int)$oID)->first();
        }
        elseif($lisLog->context == 'celltac_alpha')
        {
            $sample = \DB::table('lab_sample_labels')->whereJsonContains('lab_order_ids',(int)$oID)->first();
        }
        elseif($lisLog->context == 'nx600')
        {
            $sample = \DB::table('lab_sample_labels')->whereJsonContains('lab_order_ids',(int)$oID)->first();
        }
        else{
            $sample = \DB::table('lab_sample_labels')->where('lab_order_id',$oID)->first();
