        }
        $items = \DB::table('lis_logs')->where('id',$logID)->update([
            'sample_id'=>$sample->id,
        ]);
        return redirect()->back();
    }

    public function get_lis_loinc_mapping_modal(Request $request)
    {
        $request->validate([
            'context' => 'required|string',
            'sample_id' => 'required',
            'lab_order_id' => 'required',
        ]);

        $context = $request->context;
        $sample_id = $request->sample_id;
        $lab_order_id = $request->lab_order_id;

        // Fetch the latest LIS log for this sample & context
        $lisLog = \DB::table('lis_logs')
            ->where('sample_id', $sample_id)
            ->where('context', $context)
            ->orderBy('id', 'desc')
            ->first();

        if (!$lisLog) {
            // Fallback: fetch the latest log for this context
            $lisLog = \DB::table('lis_logs')
                ->where('context', $context)
                ->orderBy('id', 'desc')
                ->first();
        }

        $analyzerCodes = [];
        if ($lisLog) {
            switch ($lisLog->context) {
                case 'sysmex_hl_series':
                    $parsed = \App\Helpers\ASTM::processASTM($lisLog->data ?? '');
                    break;
                case 'erba_em200':
                    $parsed = \App\Helpers\ERBA_EM200_Parser::processASTM($lisLog->data ?? '');
                    break;
                case 'erba_ec90':
                    $parsed = \App\Helpers\ERBA_EC90_Parser::processASTM($lisLog->data ?? '');
                    break;
                case 'celltac_alpha':
                    $parsed = \App\Helpers\CELLTAC_ALPHA_Parser::processASTM($lisLog->data ?? '');
                    break;
                case 'nx600':
                    $parsed = \App\Helpers\NX600_Parser::processASTM($lisLog->data ?? '');
                    break;
                default:
                    $parsed = \App\Helpers\HL7::processHL7($lisLog->data ?? '');
                    break;
            }
            $results = $parsed['labResults']['results'] ?? [];
            foreach ($results as $testKey => $testVal) {
                $analyzerCodes[] = $testVal['loinc_code'] ?? $testKey;
            }
            $analyzerCodes = array_unique(array_filter($analyzerCodes));
        }

        // Fetch hospital service parameters for this lab order
        $parameters = [];
        $investigation = \DB::table('patient_gen_bill')->where('id', $lab_order_id)->first();
        if ($investigation) {
            $mainService = \DB::table('hospital_services')->where('id', $investigation->service_id)->first();
            if ($mainService) {
                if ($mainService->is_group) {
                    $childTests = \DB::table('table_investigation_group_test_index')
                        ->join('hospital_services', 'hospital_services.id', '=', 'table_investigation_group_test_index.test_id')
                        ->where('table_investigation_group_test_index.group_id', $mainService->id)
                        ->select('hospital_services.id', 'hospital_services.service', 'hospital_services.is_subgroup')
                        ->orderBy('table_investigation_group_test_index.sequence_no', 'asc')
                        ->get();
                    foreach ($childTests as $ct) {
                        if ($ct->is_subgroup) {
                            $subTests = \DB::table('table_investigation_group_test_index')
                                ->join('hospital_services', 'hospital_services.id', '=', 'table_investigation_group_test_index.test_id')
                                ->where('table_investigation_group_test_index.group_id', $ct->id)
                                ->select('hospital_services.id', 'hospital_services.service')
                                ->orderBy('table_investigation_group_test_index.sequence_no', 'asc')
                                ->get();
                            foreach ($subTests as $st) {
                                $parameters[] = [
                                    'id' => $st->id,
                                    'name' => $st->service
                                ];
                            }
                        } else {
                            $parameters[] = [
                                'id' => $ct->id,
                                'name' => $ct->service
                            ];
                        }
                    }
                } else {
                    $parameters[] = [
                        'id' => $mainService->id,
                        'name' => $mainService->service
                    ];
                }
            }
        }

        // Fetch existing custom mappings for the context
        $existingMappings = \DB::table('loinc_service_mapping')
            ->where('context', $context)
            ->pluck('service_id', 'loinc_code')
            ->toArray();

        return view('admin.patient.lab_test.modal_lis_loinc_mapping', compact(
            'context',
            'sample_id',
            'lab_order_id',
            'analyzerCodes',
            'parameters',
            'existingMappings'
        ));
    }

    public function save_lis_loinc_mapping(Request $request)
    {
        $request->validate([
            'context' => 'required|string',
        ]);

        $context = $request->context;
        $mappings = $request->input('mappings', []);

        \DB::transaction(function () use ($context, $mappings) {
            foreach ($mappings as $loincCode => $serviceId) {
                if (empty($loincCode)) continue;

                if (empty($serviceId)) {
                    // Delete mapping if empty/do not map is selected
                    \DB::table('loinc_service_mapping')
                        ->where('context', $context)
                        ->where('loinc_code', $loincCode)
                        ->delete();
                } else {
                    // Delete existing mapping under the unique key constraint to avoid collision
                    \DB::table('loinc_service_mapping')
                        ->where('loinc_code', $loincCode)
                        ->where('service_id', $serviceId)
                        ->delete();

                    // Also delete if this loincCode is mapped to something else in this context
                    \DB::table('loinc_service_mapping')
                        ->where('context', $context)
                        ->where('loinc_code', $loincCode)
                        ->delete();

                    // Also delete if this serviceId is mapped to another loincCode in this context
                    \DB::table('loinc_service_mapping')
                        ->where('context', $context)
                        ->where('service_id', $serviceId)
                        ->delete();

                    // Insert mapping
                    \DB::table('loinc_service_mapping')->insert([
                        'context' => $context,
                        'loinc_code' => $loincCode,
                        'service_id' => $serviceId,
                        'created_at' => now(),
                        'updated_at' => now(),
                    ]);
                }
            }
        });

        return response()->json([
            'status' => true,
            'message' => 'LOINC parameter mapping updated successfully!'
        ]);
    }
