    public function start_opd_billing(Request $request){
        $user = Auth::user();
        $org_id = $user->org_id;

        Validator::make($request->all(),[
            'uhid' => 'required',
            'doctor' => 'required',
        ]);

        $patient_id = $request->uhid;
        $visit_id = Visitlog::where('patient_id',$patient_id)->whereDate('created_at',date('Y-m-d'))->orderBy('id','desc')->first()->id??0;

        $others = json_decode($user->others??'{}',true);

        $restrict_service_flag = $others['restrict_service_flag']??[];

        $patient = Patient::where('id',$patient_id)->first();

        $services=HospitalService::leftJoin('hospital_services','hospital_services.id','=','hospital_services_index.service')
                                    ->leftJoin('hospital_service_charges','hospital_service_charges.service','=','hospital_services_index.service')
                                    ->where('hospital_services_index.hospital_id',$org_id)
                                    ->where('hospital_services_index.active',1)
                                    ->where('hospital_services.active',1)
                                    ->where('hospital_service_charges.insurance',$patient->i_cover)
                                    ->where('hospital_service_charges.hospital_id',$org_id)
                                    ->select('hospital_services.service',
                                                'hospital_services.spec_id',
                                                'hospital_services.id',
                                                'hospital_services.short_code',
                                                'hospital_services.flag',
                                                'hospital_services_index.service_cgst',
                                                'hospital_services_index.service_sgst',
                                                'hospital_services_index.service_igst',
                                                'hospital_services_index.is_outsource'
                                                )
                                    ->when($restrict_service_flag, function ($q) use ($restrict_service_flag) {
                                        return $q->whereIn('hospital_services.flag', $restrict_service_flag);
                                    })
                                    ->groupBy('hospital_service_charges.service')
                                    ->get();
        $discAuthUsers = User::where('active',1)->get()->toArray();

        $discounts = BillDiscount::where('active',1)->get();


        // chekc is_registered patient or new patient
        $is_registered = $patient->is_registered;
        $data = [];

        $data['is_registered'] = $is_registered;
        $data['add_consultation'] = $request->add_consultation;


        if($is_registered == 0){
            $regch = HospitalRegistrationFee::where('hospital_id',$org_id)->first();
            $regch = $regch->registration_fee??0;

            $ser = HospitalSer::where('flag','registration_charge')->first();
            $data['reg_service'] = $ser;
            $data['reg_charges'] = $regch;
        }

        // add consultant fee to bill
        if($request->add_consultation){
        $ser = HospitalSer::where('flag','consultation_charge')->first();
        $data['service'] = $ser;
        $data['opd_charges'] = $request->charges;
        }

        $data['insurance'] = $patient->i_cover;
        $data['patient_id'] = $patient->id;
        $data['doctor_id'] = $request->doctor;

        $type = "opd_billing";

        // Get all notes investigations request
        $testRequestedMap = \DB::table('visit_clinical_data')
                                ->where('visit_id', $visit_id)
                                ->where(function ($q) {
                                    $q->whereNull('add_info')
                                    ->orWhereRaw("JSON_EXTRACT(add_info, '$.inv_advice.billed') IS NULL")
                                    ->orWhereRaw("JSON_EXTRACT(add_info, '$.inv_advice.billed') != true");
                                })
                                ->select('id', 'investigation_request', 'others')
                                ->get()
                                ->flatMap(function ($row) {

                                    $services = json_decode($row->investigation_request, true) ?? [];

                                    $items = collect($services)->map(function ($item) use ($row) {

                                        return [
                                            'service_id' => is_numeric($item) ? (int) $item : null,
                                            'service_text' => is_numeric($item) ? null : trim($item),
                                            'clinical_visit_table_id' => $row->id,
                                        ];
                                    });

                                    // Extract tooth_plan if present
                                    $others = json_decode($row->others ?? '', true) ?: [];
                                    $toothPlan = $others['tooth_plan']['value'] ?? [];
                                    if (is_string($toothPlan)) {
                                        $toothPlan = json_decode($toothPlan, true) ?: [];
                                    }
                                    if (is_array($toothPlan)) {
                                        foreach ($toothPlan as $tp) {
                                            $proc = $tp['proc'] ?? ($tp['procedure'] ?? '');
                                            if (!empty($proc)) {
                                                $items->push([
                                                    'service_id' => null,
                                                    'service_text' => trim($proc),
                                                    'clinical_visit_table_id' => $row->id,
                                                ]);
                                            }
                                        }
                                    }

                                    // Extract investigations from others if present
                                    $invSources = [];
                                    if (!empty($others['investigations']['value'])) {
                                        $invSources[] = $others['investigations']['value'];
                                    } elseif (!empty($others['investigations']) && !isset($others['investigations']['value'])) {
                                        $invSources[] = $others['investigations'];
                                    }
                                    if (!empty($others['investigation_free_box_cb']['value'])) {
                                        $invSources[] = $others['investigation_free_box_cb']['value'];
                                    }
                                    foreach ($invSources as $invSource) {
                                        if (is_array($invSource)) {
                                            foreach ($invSource as $invItem) {
                                                if (is_array($invItem)) {
                                                    $invName = $invItem['name'] ?? ($invItem['service'] ?? ($invItem['investigation'] ?? ''));
                                                    if (!empty($invName)) {
                                                        $items->push([
                                                            'service_id' => null,
                                                            'service_text' => trim($invName),
                                                            'clinical_visit_table_id' => $row->id,
                                                        ]);
                                                    }
                                                } elseif (is_numeric($invItem)) {
                                                    $items->push([
                                                        'service_id' => (int) $invItem,
                                                        'service_text' => null,
                                                        'clinical_visit_table_id' => $row->id,
                                                    ]);
                                                } elseif (is_string($invItem) && trim($invItem) !== '') {
                                                    $items->push([
                                                        'service_id' => null,
                                                        'service_text' => trim($invItem),
                                                        'clinical_visit_table_id' => $row->id,
                                                    ]);
                                                }
                                            }
                                        } elseif (is_string($invSource)) {
                                            $parts = preg_split('/[,\n\r]+/', $invSource);
                                            foreach ($parts as $part) {
                                                $part = trim($part);
                                                if ($part !== '') {
                                                    $items->push([
                                                        'service_id' => is_numeric($part) ? (int) $part : null,
                                                        'service_text' => is_numeric($part) ? null : $part,
                                                        'clinical_visit_table_id' => $row->id,
                                                    ]);
                                                }
                                            }
                                        }
                                    }

                                    return $items;
                                });
        $groupedIds = $testRequestedMap
            ->whereNotNull('service_id')
            ->groupBy('service_id');

        $textServices = $testRequestedMap
            ->whereNotNull('service_text')
            ->groupBy('service_text');

        $visitRequestedServices = collect();

        if ($groupedIds->isNotEmpty()) {
            $visitRequestedServices = Service::leftJoin('hospital_services_index', 'hospital_services_index.service', '=', 'hospital_services.id')
                ->leftJoin('hospital_service_charges', function($join) use ($org_id, $patient) {
                    $join->on('hospital_services_index.service', '=', 'hospital_service_charges.service')
                        ->where('hospital_service_charges.insurance', $patient->i_cover)
                        ->where('hospital_service_charges.hospital_id', $org_id);
                })
                ->whereIn('hospital_services.id', $groupedIds->keys())
                ->select([
                    'hospital_services.id',
                    'hospital_services.service as service',
                    DB::raw('CASE WHEN hospital_services_index.active = 1 THEN true ELSE false END as inhouse'),
                    DB::raw('CASE WHEN hospital_service_charges.id IS NOT NULL THEN true ELSE false END as inbilling'),
                ])
                ->get()
                ->transform(function ($service) use ($groupedIds) {
                    $service->clinical_visit_table_ids = collect($groupedIds[$service->id] ?? [])
                        ->pluck('clinical_visit_table_id')
                        ->unique()
                        ->values();

                    return $service;
                });
        }
        if ($textServices->isNotEmpty()) {
            $textCollection = $textServices->map(function ($items, $text) {

                return (object) [
                    'id' => null, // no DB id
                    'service' => $text,
                    'inhouse' => false,
                    'inbilling' => false,
                    'clinical_visit_table_ids' => collect($items)
                        ->pluck('clinical_visit_table_id')
                        ->unique()
                        ->values(),
                ];
            })->values();

            $visitRequestedServices = $visitRequestedServices->concat($textCollection);
        }


        $bill_layout = view('admin.patient.billing.opd_billing_layout',compact('services','discAuthUsers','discounts','data','type','visitRequestedServices'))->render();

        return response()->json(['status'=>'success','bill_layout'=>$bill_layout, 'data'=>$data]);

    }

    public function patient_visit_note_investigation(Request $request)
    {
        $org_id = Auth()->User()->org_id;
        // Get all notes investigations and tooth_plan requests for active OPD visits of this hospital
        $testRequestedMap = \DB::table('visit_clinical_data')
                                ->join('visitlog', 'visitlog.id', '=', 'visit_clinical_data.visit_id')
                                ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
                                ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                ->where(function ($q) {
                                    $q->whereDate('visit_clinical_data.created_at', date('Y-m-d'))
                                      ->orWhereDate('visit_clinical_data.updated_at', date('Y-m-d'));
                                })
                                ->where(function ($q) {
                                    $q->where(function ($sub) {
                                        $sub->whereNotNull('visit_clinical_data.investigation_request')
                                            ->where('visit_clinical_data.investigation_request', '!=', '[]')
                                            ->where('visit_clinical_data.investigation_request', '!=', '[""]')
                                            ->where('visit_clinical_data.investigation_request', '!=', '');
                                    })
                                    ->orWhere(function ($sub) {
                                        $sub->whereNotNull('visit_clinical_data.others')
                                            ->where('visit_clinical_data.others', '!=', '')
                                            ->where('visit_clinical_data.others', '!=', '{}');
                                    });
                                })
                                ->where(function ($q) {
                                    $q->whereNull('visit_clinical_data.add_info')
                                    ->orWhereRaw("JSON_EXTRACT(visit_clinical_data.add_info, '$.inv_advice.billed') IS NULL")
                                    ->orWhereRaw("JSON_EXTRACT(visit_clinical_data.add_info, '$.inv_advice.billed') != true");
                                })
                                ->where('visitlog.hospital_id', $org_id)
                                ->where('pi.hospital_id', $org_id)
                                ->where('visitlog.visit_status', 0)
                                ->where(function ($q) {
                                    $q->whereNull('visitlog.is_cancelled')
                                      ->orWhere('visitlog.is_cancelled', 0);
                                })
                                ->select([
                                    'visit_clinical_data.id',
                                    'visit_clinical_data.others',
                                    'visit_clinical_data.investigation_request',
                                    'visit_clinical_data.updated_at as last_update',
                                    'pi.id as uhid',
                                    'pi.prefix',
                                    'pi.Fname',
                                    'pi.Lname',
                                    'pi.age',
                                    'pi.mobile_no',
                                    'pi.sex',
                                    'pi.dob',
                                    'pi.Fathername',
                                    'pi.spousename',
                                    'doctor_db.name as doctor_name',
                                ])
                                ->get();

        $testRequestedMap = $testRequestedMap->filter(function ($item) {
            $others = !empty($item->others) ? (is_array($item->others) ? $item->others : json_decode($item->others, true)) : [];
            $others = is_array($others) ? $others : [];

            $investigationAdvice = !empty($item->investigation_request) ? (is_array($item->investigation_request) ? $item->investigation_request : json_decode($item->investigation_request, true)) : [];
            $investigationAdvice = is_array($investigationAdvice) ? $investigationAdvice : (!empty($investigationAdvice) ? [$investigationAdvice] : []);

            $ids = [];
            $texts = [];
            foreach ($investigationAdvice as $invItem) {
                if (is_numeric($invItem)) {
                    $ids[] = (int) $invItem;
                } elseif (is_string($invItem) && trim($invItem) !== '') {
                    $texts[] = trim($invItem);
                }
            }

            $services = [];
            if (!empty($ids)) {
                $services = \App\Models\admin\Service::whereIn('id', $ids)
                    ->pluck('service')
                    ->toArray();
            }

            $finalValues = array_merge($services, $texts);
            $finalValues = array_unique(array_filter(array_map('trim', $finalValues)));
            $requestedServices = implode(', ', $finalValues);

            $existing = trim(strip_tags($others['investigation_free_box_cb']['value'] ?? ''));
            $invVal = $others['investigations']['value'] ?? '';
            if (is_array($invVal)) {
                $invVal = implode(', ', array_filter(array_map(function($v) {
                    return is_string($v) ? trim(strip_tags($v)) : '';
                }, $invVal)));
            } elseif (is_string($invVal)) {
                $invVal = trim(strip_tags($invVal));
            } else {
                $invVal = '';
            }

            if (!empty($existing)) {
                $requestedServices = $requestedServices ? $existing . ', ' . $requestedServices : $existing;
            }
            if (!empty($invVal)) {
                $requestedServices = $requestedServices ? $requestedServices . ', ' . $invVal : $invVal;
            }

            $toothPlanRaw = $others['tooth_plan']['value'] ?? [];
            if (is_string($toothPlanRaw)) {
                $toothPlanRaw = json_decode($toothPlanRaw, true) ?: [];
            }
            $toothPlanItems = [];
            if (is_array($toothPlanRaw)) {
                foreach ($toothPlanRaw as $tp) {
                    if (is_array($tp)) {
                        $tProc = trim($tp['proc'] ?? ($tp['procedure'] ?? ''));
                        if (!empty($tProc)) {
                            $toothPlanItems[] = $tProc;
                        }
                    }
                }
            }

            $item->parsed_requested_services = trim($requestedServices);
            $item->parsed_tooth_plan_items = $toothPlanItems;

            return (!empty($item->parsed_requested_services) || !empty($item->parsed_tooth_plan_items));
        })->values();

        $view = view('components.requested_investigations_table',compact('testRequestedMap'))->render();

        return response()->json(['success'=>true,'view'=>$view,'count'=>$testRequestedMap->count()]);
    }

    public function patient_visit_note_medicines(Request $request)
    {
        $org_id = Auth::user()->org_id;

        $prescriptions = \DB::table('visitlog')
            ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
            ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
            ->whereDate('visitlog.date', date('Y-m-d'))
            ->where('visitlog.hospital_id', $org_id)
            ->where('visitlog.pres_status', 1)
            ->select([
                'visitlog.id',
                'visitlog.id as visit_id',
                'visitlog.created_at as last_update',
                'pi.id as uhid',
                'pi.prefix',
                'pi.Fname',
                'pi.Lname',
                'pi.age',
                'pi.mobile_no',
                'pi.sex',
                'pi.dob',
                'doctor_db.name as doctor_name',
            ])
            ->get();

        foreach ($prescriptions as $item) {
            $medicines = \DB::table('pres_final as d')
                ->leftJoin('drug_comb_brand_index as cc', function ($join) {
                    $join->on('d.brand_id', '=', 'cc.id')
                         ->where('d.d_type', '=', 'cc');
                })
                ->leftJoin('drug_brand_index as ss', function ($join) {
                    $join->on('d.brand_id', '=', 'ss.id')
                         ->where('d.d_type', '=', 'ss');
                })
                ->select(
                    DB::raw("CASE
                                WHEN d.d_type = 'cc' THEN cc.brand_name
                                WHEN d.d_type = 'ss' THEN ss.brand_name
                                ELSE NULL
                            END as name")
                )
                ->where('d.visit_table_id', $item->visit_id)
                ->orderBy('d.id', 'asc')
                ->pluck('name')
                ->filter()
                ->toArray();

            $presManualNames = \DB::table('pres_manual')
                ->where('visit_table_id', $item->visit_id)
                ->pluck('brand_id')
                ->filter()
                ->toArray();

            $item->medicines_list = array_merge($medicines, $presManualNames);
        }

        $view = view('components.requested_medicines_table', compact('prescriptions'))->render();

        return response()->json([
            'success' => true,
            'view' => $view,
            'count' => $prescriptions->count()
        ]);
    }

    public function patient_visit_prescription_details($visit_id)
    {
        $patient = Patient::join('visitlog', 'visitlog.patient_id', '=', 'pi.id')
            ->leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
            ->select([
                'pi.id as uhid',
                'pi.prefix',
                'pi.Fname',
                'pi.Lname',
                'pi.dob',
                'pi.sex',
                'pi.mobile_no',
                'doctor_db.name as doctor_name',
                'visitlog.created_at as visit_date'
            ])
            ->where('visitlog.id', $visit_id)
            ->first();

        if (!$patient) {
            return response()->json(['success' => false, 'message' => 'Prescription details not found.']);
        }

        $medicines = $this->get_medicine_list($visit_id);
        $pres_manual = PresManual::where('visit_table_id', $visit_id)->get();

        $pres_manual = $pres_manual->map(function ($item) {
            $item->name = $item->brand_id;
            return $item;
        });

        $mergedMedicines = $medicines
            ->merge($pres_manual)
            ->sortBy('d_order')
            ->values();

        $store_id = request('store_id');
        $hospital_id = auth()->user()->org_id;

        foreach ($mergedMedicines as $med) {
            $freq_factor = 0.00;
            if (!empty($med->it)) {
                $term = \DB::table('pres_unique_terms')
                    ->where('text', $med->it)
                    ->where('type', 'instr')
                    ->first();
                if ($term) {
                    $freq_factor = (double) $term->convert_factor;
                }
            }

            $dur_factor = 0.00;
            if (!empty($med->dt)) {
                $term = \DB::table('pres_unique_terms')
                    ->where('text', $med->dt)
                    ->where('type', 'duration')
                    ->first();
                if ($term) {
                    $dur_factor = (double) $term->convert_factor;
                }
            }

            $med->calculated_qty = ceil($freq_factor * $dur_factor);

            $linkedItems = collect();
            if (!empty($med->brand_id) && !empty($med->d_type)) {
                $linkedItems = \DB::table('mars_brand_empath_item_link as link')
                    ->join('items as i', 'i.id', '=', 'link.empath_item_id')
                    ->leftJoin('purchase_units as pu', 'pu.id', '=', 'i.packaging_type_id')
                    ->where('link.mars_brand_id', $med->brand_id)
                    ->where('link.mars_brand_type', $med->d_type)
                    ->where('link.hospital_id', $hospital_id)
                    ->select([
                        'i.id as item_id',
                        'i.name as item_name',
                        'i.is_unit_sell_allowed',
                        'i.units_per_package',
                        'i.unit_type',
                        'pu.unit_name as package_unit_name',
                        'i.is_narcotic',
                        'i.is_high_risk_medicine'
                    ])
                    ->get();
            }

            foreach ($linkedItems as $li) {
                $batches = collect();
                if ($store_id) {
                    $batches = \DB::table('inventory as inv')
                        ->leftJoin('goods_received_notes as grn', 'grn.id', '=', 'inv.grn_id')
                        ->where('inv.item_id', $li->item_id)
                        ->where('inv.store_id', $store_id)
                        ->where('inv.qty', '>', 0)
                        ->whereNull('inv.deleted_at')
                        ->orderBy('inv.expiry', 'asc')
                        ->select([
                            'inv.id as row_id',
                            'inv.batch_no',
                            'inv.expiry',
                            'inv.qty as available_qty',
                            'inv.mrp',
                            'inv.selling_price',
                            'inv.procurement_price',
                            'inv.cgst',
                            'inv.sgst',
                            'inv.igst',
                            'inv.updated_at as version'
                        ])
                        ->get();
                }
                $li->batches = $batches;
            }

            $med->linked_items = $linkedItems;
        }

        $view = view('components.requested_prescription_details_table', compact('patient', 'mergedMedicines', 'visit_id'))->render();

        return response()->json([
            'success' => true,
            'view' => $view
        ]);
    }

    public function getItemDetailsAndBatches(Request $request)
    {
        $itemId = $request->item_id;
        $storeId = $request->store_id;
        $hospitalId = auth()->user()->org_id;

        $item = \DB::table('items as i')
            ->leftJoin('purchase_units as pu', 'pu.id', '=', 'i.packaging_type_id')
            ->where('i.id', $itemId)
            ->select([
                'i.id as item_id',
                'i.name as item_name',
                'i.is_unit_sell_allowed',
                'i.units_per_package',
                'i.unit_type',
                'pu.unit_name as package_unit_name',
                'i.is_narcotic',
                'i.is_high_risk_medicine'
            ])
            ->first();

        if (!$item) {
            return response()->json([
                'success' => false,
                'message' => 'Item not found'
            ]);
        }

        $batches = collect();
        if ($storeId) {
            $batches = \DB::table('inventory as inv')
                ->leftJoin('goods_received_notes as grn', 'grn.id', '=', 'inv.grn_id')
                ->where('inv.item_id', $itemId)
                ->where('inv.store_id', $storeId)
                ->where('inv.qty', '>', 0)
                ->orderBy('inv.expiry', 'asc')
                ->select([
                    'inv.id as row_id',
                    'inv.batch_no',
                    'inv.expiry',
                    'inv.qty as available_qty',
                    'inv.mrp',
                    'inv.selling_price',
                    'inv.procurement_price',
                    'inv.cgst',
                    'inv.sgst',
                    'inv.igst',
                    'inv.updated_at as version'
                ])
                ->get();
        }

        return response()->json([
            'success' => true,
            'item' => $item,
            'batches' => $batches
        ]);
    }

    public function get_opd_billing_layout(Request $request){

        $user = Auth::user();
        $org_id = $user->org_id;

        Validator::make($request->all(),[
            'uhid' => 'required',
            'doctor' => 'required',
        ]);

        $patient_id = $request->uhid;



        $patient = Patient::where('id',$patient_id)->first();
        $insu = HospitalInsurance::join('health_insurance_agen','health_insurance_agen.id','=','hospital_insurance.insurance')
                                    ->where('hospital_insurance.hospital_id',$org_id)
                                    ->where('hospital_insurance.active',1)
                                    ->select('health_insurance_agen.*')
                                    ->where('health_insurance_agen.id',$patient->i_cover)
                                    ->first();

        $services=HospitalService::leftJoin('hospital_services','hospital_services.id','=','hospital_services_index.service')
                                    ->leftJoin('hospital_service_charges','hospital_service_charges.service','=','hospital_services_index.service')
                                    ->where('hospital_services_index.hospital_id',$org_id)
                                    ->where('hospital_services_index.active',1)
                                    ->where('hospital_service_charges.insurance',$patient->i_cover)
                                    ->where('hospital_service_charges.hospital_id',$org_id)
                                    ->select('hospital_services.service',
                                                'hospital_services.spec_id',
                                                'hospital_services.id',
                                                'hospital_services.short_code',
                                                'hospital_service_charges.charges',
                                                'hospital_services.flag'
                                                )
                                    ->groupBy('hospital_service_charges.service')
                                    ->get();


        $discAuthUsers = User::where('active',1)->get()->toArray();

        $discounts = BillDiscount::where('active',1)->get();


        // chekc is_registered patient or new patient
        $is_registered = $patient->is_registered;

        $data['is_registered'] = $is_registered;
        $data['add_consultation'] = $request->add_consultation;


         if($is_registered == 0){
             $regch = HospitalRegistrationFee::where('hospital_id',$org_id)->first();
             $regch = $regch->registration_fee??0;

             $ser = HospitalSer::where('flag','registration_charge')->first();
             $data['reg_service'] = $ser;
             $data['reg_charges'] = $regch;
         }

          // add consultant fee to bill
          if($request->add_consultation){
            $ser = HospitalSer::where('flag','consultation_charge')->first();
            $data['service'] = $ser;
            $data['opd_charges'] = $request->charges;
         }

        $data['insurance'] = $patient->i_cover;
        $data['sr_no'] = $request->sr_no;
        $data['visit_id'] = $request->visit;

        $bill_layout = view('admin.patient.registration.billing_page_layout',compact('patient','insu','services','discAuthUsers','discounts','data'))->render();

        return response()->json(['status'=>'success','bill_layout'=>$bill_layout, 'data'=>$data]);

    }


    public function urology_opd_notes(Request $request){

                    $user = Auth::user();
                    $org_id = $user->org_id;

                    // $patient = Patient::where('id',20202)->first();
                    // $visit_id = 56068;
                    $currentDate = Carbon::today()->toDateString();

                    $visit = Visitlog::leftjoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                ->leftJoin('pi', 'pi.id', '=', 'visitlog.patient_id')
                                ->leftJoin('patient_billing', function ($join) {
                                    $join->on('patient_billing.visit_id', '=', 'visitlog.id');
                                    $join->on('visitlog.patient_id', '=', 'pi.id');
                                })

                                ->select('visitlog.*',
                                    'visitlog.created_at as created',
                                    'visitlog.doctor_id as did',
                                    'visitlog.id as vid',
                                    'visitlog.patient_id as pid',
                                    'doctor_db.name as doctor_name',
                                    'pi.Fname',
                                    'pi.Lname',
                                    'pi.age',
                                    'pi.sex',
                                    'pi.dob',
                                    'pi.mobile_no',
                                    'pi.prefix',
                                    'patient_billing.id as bill_id',
                                    'patient_billing.status as bill_status'

                                )
                                // ->distinct() // Ensure no duplicate rows
                                ->where('visitlog.hospital_id', $org_id)
                                ->where('visit_status', 0);

                if($request->start_date && $request->end_date){
                    $visit->whereBetween('visitlog.date', [$request->start_date, $request->end_date]);
                }else{
                    $visit->whereDate('visitlog.date', $currentDate);
                }
                if($request->doctor_id){
                    $visit->where('visitlog.doctor_id', $request->doctor_id);
                }
                    $visit->orderBy('visitlog.id', 'DESC');
                    $visit->groupBy('visitlog.id');
                    $visit = $visit->get();

                    // Initialize an array to store the visit count for each doctor
                    $doctorVisitCounts = [];

                // Loop through visits and assign serial numbers
                foreach ($visit as $visi) {
                    $doctorId = $visi->did;

                // Initialize the count if not already set
                if (!isset($doctorVisitCounts[$doctorId])) {
                    $doctorVisitCounts[$doctorId] = count($visit)+1;
                }

                // Increment the count
                    $doctorVisitCounts[$doctorId]--;

                // Assign the serial number
                    $visi->sr_no = $doctorVisitCounts[$doctorId];
                }
                // Reverse the collection order for display

                // Check if visit ID exists
                if (!empty($vid)) {
                    $visit_id = $vid;
                } elseif (!empty($visit) && isset($visit[0]->vid)) {
                    $visit_id = $visit[0]->vid;
                } else {
                    return back()->with('error', 'There is no any patient visit for today.');
                }


                $patient = Patient::join('visitlog', 'visitlog.patient_id', '=', 'pi.id')
                                    ->leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                    ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                                    ->select('pi.*', 'visitlog.doctor_id', 'doctor_db.name as doctor_name','visitlog.fud','visitlog.edit_lock','doctor_specialities.id as spid','doctor_db.id as did')
                                    ->where('visitlog.id', $visit_id)
                                    ->first();



         // ############################ Medicine Record ##############################
         $medicines = DB::table('pres_final as d')
                             ->leftJoin('drug_comb_brand_index as cc', function ($join) {
                                 $join->on('d.brand_id', '=', 'cc.id')
                                     ->where('d.d_type', '=', 'cc');
                             })
                             ->leftJoin('drug_brand_index as ss', function ($join) {
                                 $join->on('d.brand_id', '=', 'ss.id')
                                     ->where('d.d_type', '=', 'ss');
                             })
                             ->select(
                                 'd.*',
                                 DB::raw("CASE
                                             WHEN d.d_type = 'cc' THEN cc.brand_name
                                             WHEN d.d_type = 'ss' THEN ss.brand_name
                                             ELSE NULL
                                         END as name")
                             )
                             // ->having('name', 'LIKE', "%{$query}%")
                             ->where('visit_table_id', $visit_id)
                             // ->groupBy('d.brand_id')
                             ->orderBy('d.id', 'asc')
                             ->get();

             $q_medicines = DB::table('doc_drug_used_brands as d')
                             ->leftJoin('drug_comb_brand_index as cc', function ($join) {
                                 $join->on('d.brand_id', '=', 'cc.id')
                                     ->where('d.d_type', '=', 'cc');
                             })
                             ->leftJoin('drug_brand_index as ss', function ($join) {
                                 $join->on('d.brand_id', '=', 'ss.id')
                                     ->where('d.d_type', '=', 'ss');
                             })
                             ->select(
                                 'd.*',
                                 DB::raw("CASE
                                             WHEN d.d_type = 'cc' THEN cc.brand_name
                                             WHEN d.d_type = 'ss' THEN ss.brand_name
                                             ELSE NULL
                                         END as name")
                             )
                             // ->having('name', 'LIKE', "%{$query}%")
                             ->where('d.doctor_id', $patient->doctor_id)
                             // ->groupBy('d.brand_id')
                             ->orderBy('d.id', 'asc')
                             ->get();

                 foreach($q_medicines as $r){
                                 //  $r->formulation1 = $this->get_formulation($r->brand_id, $r->d_type);
                                 $formulation = $this->get_formulation($r->brand_id, $r->d_type);

                                 if($r->d_type == 'ss'){
                                     foreach($formulation as $f){
                                         $form = $f->form;
                                         $dose = $f->dose;
                                         $unit = $f->unit_name;
                                         $drug = $f->drug_name;

                                         $r->formulation = $drug.' '.$dose.' '.$unit.' ('.$form.')';

                                     }
                                 }else{
                                     foreach($formulation as $f){
                                         $form = $f->form;

                                         $strArray = [];
                                         foreach($f->comb_name as $cn){
                                             $formulation = $cn->drug_name;
                                             $dose = $cn->dose;
                                             $unit_name = $cn->unit_name;

                                             $strArray[] = $formulation. ' '.$dose.' '.$unit_name;
                                         }
                                         $str = implode(' + ', $strArray);
                                         $r->formulation = $str.'('.$form.')';
                                     }
                                 }
                             }


                $vcd = VisitClinicalData::where('visit_id', $visit_id)->first();
                if (!$vcd) {
                    $vcd = VisitClinicalData::create(['visit_id' => $visit_id, 'others' => '{}']);
                }

                // Decode the clinical data safely
                $formData = is_string($vcd->others ?? '') ? json_decode($vcd->others, true) : [];




        $form_fields = [
            ['btn_label' => 'Allergy','name' => 'alg_cb', 'options' => [], 'inputType' => 'textarea'],
            ['btn_label' => 'CC','name' => 'chief_cb', 'options' => [], 'inputType' => 'textarea'],
            ['btn_label' => 'HOPI','name' => 'hopi_cb', 'options' => [], 'inputType' => 'textarea'],
            ['btn_label' => 'PAST','name' => 'ph_cb', 'options' => [], 'inputType' => 'textarea'],
            ['btn_label' => 'Family','name' => 'fh_cb', 'options' => [], 'inputType' => 'textarea'],
            ['btn_label' => 'Social','name' => 'social_cb', 'options' => [], 'inputType' => 'textarea'],
            ['btn_label' => 'Examination','name' => 'physical_exam_cb', 'options' => [], 'inputType' => 'textarea'],
            ['btn_label' => 'Diagnosis','name' => 'user_other_diagnosis_cb', 'options' => [], 'inputType' => 'textarea'],

        ];

        $form2 = [
            ['btn_label' => 'Investigation Done Earliar','name' => 'investigation_done_earliar_cb', 'options' => [], 'inputType' => 'textarea'],
            ['btn_label' => 'Investigation Advice','name' => 'investigation_free_box_cb', 'options' => [], 'inputType' => 'textarea'],
            ['btn_label' => 'Mx Plan','name' => 'management_plan_cb', 'options' => [], 'inputType' => 'textarea'],
            ['btn_label' => 'Advice','name' => 'fup2_cb', 'options' => [], 'inputType' => 'textarea'],
        ];




        $data = compact('visit','patient','form_fields','form2','medicines','q_medicines','visit_id','formData');
        return view('admin.patient.clinical.urology_opd_notes')->with($data);
    }


    public function urology_v2(Request $request, $vid=null, $t_id=null){

        $user = Auth::user();
        $org_id = $user->org_id;

        $visit =  $this->today_visit_list($request);
        $context = FacadesRoute::currentRouteName();
            // Check if visit ID exists
        if (!empty($vid)) {
            $visit_id = $vid;
        } else {
            return view('admin.patient.clinical.urology_v2', compact('visit','context'));
            // return back()->with('error', 'There is no any patient visit for today.');
        }

        $lock = $this->isPageLocked($visit_id,$context);

        $patient = Patient::join('visitlog', 'visitlog.patient_id', '=', 'pi.id')
                        ->leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                        ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                        ->select('pi.*', 'visitlog.doctor_id','doctor_db.key_spec', 'doctor_db.name as doctor_name','visitlog.fud','visitlog.edit_lock','doctor_specialities.id as spid','doctor_db.id as did','visitlog.created_at as created_at')
                        ->where('visitlog.id', $visit_id)
                        ->first();

        $vcd = VisitClinicalData::where('visit_id', $visit_id)->where('context',$context)->first();
        if (!$vcd) {
            $vcd = VisitClinicalData::create(['visit_id' => $visit_id, 'others' => '{}', 'context'=>$context]);
        }

        // Decode the clinical data safely
        $formData = is_string($vcd->others ?? '') ? json_decode($vcd->others, true) : [];
        $diagnosis = json_decode(optional($vcd)->diagnosis, true) ?? [];

        // ############################ Medicine Record ##############################

            $medicines = $this->get_medicine_list($visit_id);

            $q_medicines = $this->get_q_medicine_list($visit_id, $patient->doctor_id);

            $dynamic_comments =  $this->get_clinical_comments($patient->did, $context);

            $templates = $this->get_templates($patient->did, $context);

            if($t_id){
                $template = Template::where('id', $t_id)->first();
                if($template){
                    $formData = json_decode($template->template, true);

                    $medicines = $this->get_template_medicine_list($t_id);
                }
            }

            $pres_manual = PresManual::where('visit_table_id', $visit_id)->get();
            $prestemplates = $this->get_templates($patient->did, 'prescription');

            $HospitalDoctor = HospitalDoctor::where('doc_id', $patient->did)->where('org_id', $org_id)->first();

            $others2 = json_decode(optional($HospitalDoctor)->others, true) ?? [];

            $search_type = $others2['search_type'];

            $vitals = Vitals::where('visit_id', $visit_id)->first();
            if(is_null($vitals)){
                $bp = [];
                $pulse = [];
            }else{
                $bp = json_decode($vitals->bp, true) ?? [];
                $pulse = json_decode($vitals->pulse, true) ?? [];
                $bp = end($bp);
                $pulse = end($pulse);
            }

            $prev_visits = VisitClinicalData::join('visitlog', 'visitlog.id', '=', 'visit_clinical_data.visit_id')
                                        ->select('visitlog.id', 'visitlog.created_at')
                                        ->where('visitlog.patient_id', $patient->id)
                                        ->where('visitlog.doctor_id', $patient->doctor_id)
                                        ->where('visitlog.hospital_id', $patient->hospital_id)
                                        ->where('visit_clinical_data.context', $context)
                                        ->orderBy('visitlog.created_at', 'desc')
                                        ->skip(1)
                                        ->take(100) // or any large number to fetch all remaining
                                        ->get();

            // return $formData;
        return view('admin.patient.clinical.urology_v2', compact('visit_id','vitals','bp','pulse','medicines','q_medicines','search_type','formData','pres_manual','prestemplates','visit','patient','templates','context','dynamic_comments','lock','prev_visits','diagnosis'));
    }


