    public function query_for_clinical_comments(Request $request)
    {
        $request->validate([
            'doctor_id' => 'required',
            'context' => 'required',
            'value' => 'required',
            'tag' => 'required'
        ]);

        $doctorID = $request->doctor_id;
        $context = $request->context;
        $tag = $request->tag;
        $text    = trim(strtolower($request->value));  // normalize user input

        $static_comments  = \App\Helpers\ClinicalHelper::getStaticComments($tag);
        $dynamic_comments = $this->get_clinical_comments($doctorID, $context);

        // Merge + unique
        $merged_comments = array_values(array_unique(array_merge(
            $static_comments[$context] ?? [],
            $dynamic_comments[$context] ?? []
        )));

        // Normalize all existing comments
        $normalized_existing = array_map(function ($item) {
            return trim(strtolower($item));
        }, $merged_comments);

        // Check if input already exists
        $inputList = explode(',', $text);
        $notExist = [];
        foreach ($inputList as $input) {
            $input = trim($input);
            if (!in_array($input, $normalized_existing, true)) {
                $notExist[] = $input;
            }
        }
        return [
            'success'       => true,
            'not_exist'     => $notExist,
        ];
    }


