    public function add_medical_history(Request $request)
    {
        $request->validate([
            'key' => 'required',
            'context' => 'required',
            'value' => 'required'
        ]);

        $key = $request->key;
        $keyMap = [
            'alerts' => 'alert_cb',
            'alg'    => 'alg_cb',
            'past'   => 'ph_cb',
            'surg'   => 'surgical_cb',
            'soc'    => 'social_cb',
            'fam'    => 'fh_cb',
        ];
        if (isset($keyMap[$key])) {
            $key = $keyMap[$key];
        }

        $visitID = $request->visit_id;
        $context = $request->context;

        // dd($request->all());

        $vcd = VisitClinicalData::where('visit_id', $visitID)
            ->where('context', $context)
            ->first();

        if (!$vcd) {
            $vcd = VisitClinicalData::create([
                'visit_id' => $visitID,
                'context' => $context,
                'others' => '{}'
            ]);
        }

        $data = json_decode($vcd->others ?? '{}', true);

        // Ensure the key exists
        if (!isset($data[$key])) {
            $data[$key] = [];
        }

        // Get existing value
        $existing = $data[$key]['value'] ?? [];

        // MIGRATION FIX: Only convert old data if not empty
        if (!is_array($existing)) {
            if (!empty($existing)) {
                $existing = [
                    [
                        'name' => $existing,
                        'extra' => ''
                    ]
                ];
            } else {
                $existing = [];
            }
        }

        // Ensure list format
        if (!array_is_list($existing)) {
            $existing = [$existing];
        }

        // Add new structured entry
        $existing[] = [
            'name' => $request->value,
            'extra' => $request->extra ?? $request->c ?? $request->y ?? $request->d ?? '',
            'note' => $request->note ?? '',
        ];

        $data[$key]['value'] = $existing;
        $data[$key]['updated_at'] = now()->format('Y-m-d H:i:s');

        $vcd->others = json_encode($data);
        $vcd->save();

        return response()->json([
            'success' => true,
            'message' => 'Medical history added successfully',
            'data' => $existing
        ]);
    }


    public function remove_medical_history(Request $request)
    {
        $request->validate([
            'key' => 'required',
            'index' => 'required|integer',
            'context' => 'required',
        ]);

        $key = $request->key;
        $keyMap = [
            'alerts' => 'alert_cb',
            'alg'    => 'alg_cb',
            'past'   => 'ph_cb',
            'surg'   => 'surgical_cb',
            'soc'    => 'social_cb',
            'fam'    => 'fh_cb',
        ];
        if (isset($keyMap[$key])) {
            $key = $keyMap[$key];
        }

        $index = $request->index;
        $visitID = $request->visit_id;
        $context = $request->context;

        $vcd = VisitClinicalData::where('visit_id', $visitID)
            ->where('context', $context)
            ->first();

        if (!$vcd) {
            return response()->json(['success' => false, 'message' => 'Record not found']);
        }

        $data = json_decode($vcd->others ?? '{}', true);

        if (!isset($data[$key]['value'])) {
            return response()->json(['success' => false, 'message' => 'Key not found']);
        }

        $items = $data[$key]['value'];

        // Normalize old simple-string format
        if (!is_array($items)) {
            $items = [
                ['name' => $items, 'duration' => '']
            ];
        }

        // Ensure it's a list
        if (!array_is_list($items)) {
            $items = [$items];
        }

        // Index check
        if (!array_key_exists($index, $items)) {
            return response()->json(['success' => false, 'message' => 'Invalid index']);
        }

        // Remove selected record
        unset($items[$index]);
        $items = array_values($items);

        // Save updated
        $data[$key]['value'] = $items;
        $data[$key]['updated_at'] = now()->format('Y-m-d H:i:s');

        $vcd->others = json_encode($data);
        $vcd->save();

        return response()->json([
            'success' => true,
            'message' => 'Entry removed successfully',
            'data' => $items
        ]);
    }



