    public function get_clinical_comments($user_id, $context, $filterKey = null)
    {
        $org_id = Auth::user()->org_id;

        $setting = HospitalSetting::where('hospital_id', $org_id)
                                    ->where('identifier', 'clinical_comments')
                                    ->first();

        $current_setting = $setting->current_setting ?? 'self';

        // // Start query
        // $query = ClinicalComment::select('context', 'comment');

        // // Apply filtering based on setting
        // if ($current_setting === 'self') {
        //     $query->where('user_id', $user_id);
        // }
        // elseif ($current_setting === 'faculty wise') {

        //     $doc = Doctor_db::find($user_id);
        //     $key_spec = $doc->key_spec;

        //     $doctorIds = Doctor_db::where('key_spec', $key_spec)
        //                             ->pluck('id'); // no ->toArray() needed

        //     $query->whereIn('user_id', $doctorIds);
        // }
        // elseif ($current_setting === 'all') {
        //     // no where clause needed (all doctors)
        // }

        // if ($filterKey !== null) {
        //     $query->where('comment', 'like', '%' .$filterKey. '%');
        // }

        // // Final fetch + group
        // $dynamic_comments = $query->orderBy('context')
        //                         ->get()
        //                         ->groupBy('context')
        //                         ->map(fn($group) => $group->pluck('comment')->toArray())
        //                         ->toArray();

        // return $dynamic_comments;


            $query = ClinicalComment::select('context', 'comment', 'count');

            // Apply filtering based on setting
            if ($current_setting === 'self') {

                $query->where('user_id', $user_id);

            } elseif ($current_setting === 'faculty wise') {

                $doc = Doctor_db::find($user_id);
                $key_spec = $doc->key_spec;

                $doctorIds = Doctor_db::where('key_spec', $key_spec)
                                        ->pluck('id');

                $query->whereIn('user_id', $doctorIds);

            } elseif ($current_setting === 'all') {
                // No user filter
            }

            if ($filterKey !== null) {
                $query->where('comment', 'like', '%' . $filterKey . '%');
            }

            // Rank comments within each context by count
            $rankedQuery = $query
                ->selectRaw('
                    ROW_NUMBER() OVER (
                        PARTITION BY context
                        ORDER BY count DESC, comment ASC
                    ) as row_num
                ');

            // Fetch top 20 for each context
            $dynamic_comments = DB::query()
                ->fromSub($rankedQuery, 'ranked_comments')
                ->where('row_num', '<=', 30)
                ->orderBy('context')
                ->orderByDesc('count')
                ->get()
                ->groupBy('context')
                ->map(fn ($group) => $group->pluck('comment')->toArray())
                ->toArray();

            return $dynamic_comments;


    }

    public function get_templates($user_id, $context){
        $user = Auth::user();
        $org_id = $user->org_id??'';

        $setting = HospitalSetting::where('hospital_id', $org_id)->where('identifier', 'clinical_comments')->first();

        $current_setting = $setting->current_setting??'';

        if (!$setting || $setting->current_setting == 'self') {

            $templates = Template::where('user_id', $user_id)->where('context',$context)->get();

        }else if($setting->current_setting == 'faculty wise'){
            $doc = Doctor_db::find($user_id);
            $key_spec = $doc->key_spec;

            $doctorIds = Doctor_db::where('key_spec', $key_spec)->pluck('id')->toArray();

              $templates = Template::whereIn('user_id', $doctorIds)->where('context',$context)->get();
        }else if($setting->current_setting == 'all'){
            $templates = Template::where('context',$context)->get();
        }

        return $templates;
    }

