            foreach($medicines as $r){

            $formulation = $this->get_formulation($r->brand_id, $r->d_type);

            if($r->d_type == 'ss'){
            foreach($formulation as $f){
                $form = $f->form;
                $dose = $f->dose;
                $unit = $f->unit_name;
                $drug = $f->drug_name;

                $r->formulation = $drug.' '.$dose.' '.$unit.' ('.$form.')';

            }
            }else{
                foreach($formulation as $f){
                    $form = $f->form;

                    $strArray = [];
                    foreach($f->comb_name as $cn){
                        $formulation = $cn->drug_name;
                        $dose = $cn->dose;
                        $unit_name = $cn->unit_name;

                        $strArray[] = $formulation. ' '.$dose.' '.$unit_name;
                    }
                    $str = implode(' + ', $strArray);
                    $r->formulation = $str.'('.$form.')';
                }
            }
        }

            // dd($medicines);
            if($visit->fud != null){

            $date = Carbon::parse($visit->fud);

            $formattedDate = $date->format('l d/m/Y');

            // Get the current date
            $currentDate = Carbon::now();

            // Calculate the difference in days
            $dayDifference = $currentDate->diffInDays($date)+1;

            // Determine if the difference is past or future
            if ($date->greaterThan($currentDate)) {
                $differenceText = "After {$dayDifference} Days";
                $followup_date = "{$formattedDate} {$differenceText}";
            } else {
                $differenceText = "Before {$dayDifference} Days";
                $followup_date = "";
            }
            // $differenceText = '';


            }else{
                $followup_date = '';
            }

            $header = $request->header;


            $vitals = Vitals::where('visit_id',$visit->id)->first();
            if(is_null($vitals)){
                $bp = [];
                $pulse = [];
            }else{
                $bp = json_decode($vitals->bp, true) ?? [];
                $pulse = json_decode($vitals->pulse, true) ?? [];
                $bp = end($bp);
                $pulse = end($pulse);
            }


            return view('admin.pdf.clinical.prescription', compact('visit', 'data', 'medicines', 'followup_date', 'header', 'bp', 'pulse', 'vitals'));

    }


    public function add_comments(Request $request)
    {
        $user_id = $request->user_id;
        $context = $request->key;
        $comment = $request->new_comment;
        $shouldExplode = $request->explode ?? false;

        // Normalize explode flag (handles "true", 1, etc.)
        $shouldExplode = filter_var($shouldExplode, FILTER_VALIDATE_BOOLEAN);

        $added = [];
        $skipped = [];

        // Case 1: Multiple comments
        if ($shouldExplode) {

            $inputList = explode(',', $comment);

            foreach ($inputList as $input) {

                $input = trim($input);

                if ($input === '') {
                    continue; // skip empty values
                }

                $exists = ClinicalComment::where('user_id', $user_id)
                    ->where('context', $context)
                    ->where('comment', $input)
                    ->exists();

                if ($exists) {
                    $skipped[] = $input;
                    continue;
                }

                $c = new ClinicalComment();
                $c->user_id = $user_id;
                $c->context = $context;
                $c->comment = $input;
                $c->save();

                $added[] = $c;
            }

            return response()->json([
                'status' => 'success',
                'message' => 'Processed multiple comments',
                'added' => $added,
                'skipped' => $skipped
            ]);
        }

        if (trim($comment ?? '') === '') {
            return response()->json([
                'status' => 'error',
                'message' => 'Comment cannot be empty!'
            ], 422);
        }

        $existingComment = ClinicalComment::where('user_id', $user_id)
            ->where('context', $context)
            ->where('comment', $comment)
            ->first();

        if ($existingComment) {
            return response()->json([
                'status' => 'error',
                'message' => 'Comment already exists!'
            ]);
        }

        $c = new ClinicalComment();
        $c->user_id = $user_id;
        $c->context = $context;
        $c->comment = trim($comment);
        $c->save();

        return response()->json([
            'status' => 'success',
            'message' => 'Comment saved successfully!',
            'data' => $c,
            'new_comment' => $c->comment
        ]);
    }
    public function fetech_comment_section(Request $request)
    {
        $doctorID = $request->doctor_id;
        $context = $request->context;
        $tag = $request->tag;

        $static_comments  = \App\Helpers\ClinicalHelper::getStaticComments($tag);
        $dynamic_comments = $this->get_clinical_comments($doctorID, $context);

        // Merge + unique
        $merged_comments = array_values(array_unique(array_merge(
