    public function fetch_patient_investigations_for_notes(Request $request)
    {
        $visit_id = $request->visit_id;
        $visit = Visitlog::findOrFail($visit_id);
        $doctor = $visit->doctor;
        $services = PatientBilling::join('patient_gen_bill', 'patient_gen_bill.bill_id', '=', 'patient_billing.id')
                                ->join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
                                ->join('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                                ->select(
                                    'patient_gen_bill.id as service_id',
                                    'hospital_services.service as test_name',
                                    DB::raw('DATE(lab_investigations.approval_time) as approval_time'),
                                    DB::raw('DATE(patient_gen_bill.created_at) as created_at'),
                                    DB::raw("lab_investigations.test_results as tests")
                                )
                                ->where('patient_billing.visit_id', $visit_id)
                                ->where(function($q) {
                                    $q->whereNull('patient_gen_bill.is_deleted')
                                    ->orWhere('patient_gen_bill.is_deleted', 0);
                                })
                                ->where(function($q) {
                                    $q->whereNull('patient_gen_bill.is_cancelled')
                                    ->orWhere('patient_gen_bill.is_cancelled', 0);
                                })
                                ->where(function($q) {
                                    $q->whereNull('patient_billing.is_cancelled')
                                    ->orWhere('patient_billing.is_cancelled', 0);
                                })
                                ->where('lab_investigations.status', 'approved')
                                ->get();

        $specServices = \App\Models\SpecServiceTrack::join('hospital_services','hospital_services.id','=','doc_spec_service_track.service_id')
                        ->where('doc_spec_service_track.spec_id',$doctor->key_spec)
                        ->pluck('service_id')->toArray();

        $patServices = \App\Models\DocPatientServiceTrack::where('doc_id', $visit->doctor_id)
            ->where('pat_id', $visit->patient_id)
            ->pluck('service_id')
            ->toArray();

        $trackingServies = array_merge($specServices, $patServices);

        // Normalize for faster lookup (O(1) instead of in_array O(n))
        $trackingLookup = array_flip(array_unique($trackingServies));

        $serviceUnitMap = DB::table('inv_test_units')->pluck('unit_name', 'id'); // [id => unit_name]

        $serviceMap = DB::table('hospital_services')
                ->where('flag','test')
                ->get(['id', 'service', 'input_attributes'])
                ->mapWithKeys(function ($item) use ($serviceUnitMap) {

                    $unitName = '';

                    if ($item->input_attributes) {
                        $schema = json_decode($item->input_attributes, true);
                        if (!empty($schema['unit'])) {
                            $unitName = $serviceUnitMap[$schema['unit']] ?? '';
                        }
                    }

                    return [
                        $item->id => [
                            'service' => $item->service,
                            'unit'    => $unitName
                        ]
                    ];
                });



        $final = [];

        // $schema = json_decode($test->input_attributes,true);
        // \App\Helpers\InvestigationHelper::getUnitName($schema['unit']);

        foreach ($services as $service) {

            $tests = json_decode($service->tests, true);
            if (!$tests) continue;

            $serviceData = [];

            foreach ($tests as $groupName => $parameters) {

                foreach ($parameters as $serviceId => $data) {

                    // ≡ƒö┤ Skip if not in tracking
                    if (!isset($trackingLookup[$serviceId])) continue;

                    // ≡ƒö┤ Skip if no value
                    if (!isset($data['value']) || $data['value'] === '') continue;

                    $serviceObj = $serviceMap[$serviceId] ?? null;

                    $serviceData[] = [
                        'parameter'  => $serviceObj['service'] ?? 'Unknown',
                        'value'      => $data['value'],
                        'unit'       => $serviceObj['unit'] ?? '',
                        'service_id' => $serviceId
                    ];
                }
            }

            // ≡ƒö┤ Skip empty services
            if (empty($serviceData)) continue;

            $final[] = [
                'service' => $service->test_name,
                'data'    => $serviceData
            ];
        }

        return response()->json(['success'=>true,'data'=>$final]);
    }
    public function fetch_patient_investigations(Request $request){
        $visit_id = $request->visit_id;

      $rows = PatientBilling::join('patient_gen_bill', 'patient_gen_bill.bill_id', '=', 'patient_billing.id')
                                ->join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
                                ->join('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
                                ->select(
                                    'patient_gen_bill.id as service_id',
                                    DB::raw('DATE(patient_gen_bill.created_at) as service_date'),
                                    'hospital_services.service',
                                    'lab_investigations.test_results as result'
                                )
                                ->where('patient_billing.visit_id', $visit_id)
                                ->where(function($q) {
                                    $q->whereNull('patient_gen_bill.is_deleted')
                                    ->orWhere('patient_gen_bill.is_deleted', 0);
                                })
                                ->where(function($q) {
                                    $q->whereNull('patient_gen_bill.is_cancelled')
                                    ->orWhere('patient_gen_bill.is_cancelled', 0);
                                })
                                ->where(function($q) {
                                    $q->whereNull('patient_billing.is_cancelled')
                                    ->orWhere('patient_billing.is_cancelled', 0);
                                })
                                ->where('lab_investigations.status', 'approved')
                                ->orderBy('service_date', 'asc')
                                ->get();

      $services = $rows->groupBy('service_date')->map(function ($items, $serviceDate) {
          $first = $items->first();
          $tests = $items->map(function ($row) {
              return [
                  'service' => $row->service,
                  'result'  => is_string($row->result) ? (json_decode($row->result, true) ?? $row->result) : $row->result,
              ];
          })->values();

          return [
              'service_id'   => $first->service_id,
              'service_date' => $serviceDate,
              'tests'        => json_encode($tests),
          ];
      })->values();
// return $services;

            return view('admin.patient.clinical.investigation_list', compact('services'))->render();

    }

