     public function fetch_linked_discharge_summary_investigations(Request $request){
        $visit_id = $request->visit_id;
        $vitals   = Vitals::where('visit_id', $visit_id)->first();

        $labInvestigation = json_decode($vitals?->linked_lab_investigation, true) ?? [];


        $groupedResults = []; // Γ£à INIT ONCE

        foreach ($labInvestigation as $inv) {

            $order_id = $inv['order_id'] ?? null;
            if (!$order_id) continue;

            $order = \App\Models\LabInvestigation::where('lab_order_id', $order_id)->first();
            if (!$order) continue;

            // $unit = LabInvestigation::join('patient_gen_bill','patient_gen_bill.id','=','lab_investigations.lab_order_id')
            //                   ->join('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
            //                   ->select('hospital_services.input_attributes')
            //                   ->first();

            $testResults = json_decode($order->test_results, true) ?? [];

            $date = !empty($inv['inv_date'])
                ? date('d-m-Y', strtotime($inv['inv_date']))
                : 'Unknown Date';

            foreach ($testResults as $testName => $tests) {

                $pairs = [];

                foreach ($tests as $testId => $test) {

                    $input_attributes = \App\Models\admin\Service::where('id', $testId)->pluck('input_attributes');
                    $schema = json_decode($input_attributes[0],true);
                    $unit = \App\Helpers\InvestigationHelper::getUnitName($schema['unit']??'');

                    if (!empty($test['value'])) {
                        $pairs[] = [
                            'label' => get_service_name($testId),
                            'value' => $test['value'],
                            'unit'  => $unit
                        ];
                    }
                }

                if (!empty($pairs)) {
                    // Γ£à APPEND, NOT OVERWRITE
                    $groupedResults[$date][$testName][] = array_chunk($pairs, 3);
                }
            }
        }


        return view(
            'components.clinical-forms.ds_investigation_table',
            compact('groupedResults')
        )->render();


}


