    public function clinical_notes(Request $request){

        $user = Auth::user();
        $org_id = $user->org_id;

        $visit_id = $request->visit_id;

        $visit = Visitlog::find($visit_id);
        $doctor_id = $visit->doctor_id;
        $patient_id = $visit->patient_id;

        $second_last_visit_data = Visitlog::where([['doctor_id',$doctor_id],['patient_id',$patient_id],['hospital_id',$org_id]])->where('visit_status',0)->whereNull('visit_type')->orderBy('id','desc')->take(1)->first();
        if($second_last_visit_data){
            $last_visit_id = $second_last_visit_data->id;

            $vcd = VisitClinicalData::where('visit_id', $last_visit_id)->get();
            return response()->json(['success' => true,'data' => $vcd]);

        }else{
            return response()->json(['success' => false,'message' => 'No previous visit data found']);
        }

    }

    public function copy_clinical_notes(Request $request){
        $id = $request->id;
        $new_visit_id = $request->visit_id;
        $context = $request->context;
        $org_id = Auth::user()->org_id ?? null;

        if ($guard = ClinicalDocumentLockService::checkAndGuard($org_id, $new_visit_id, $context)) {
            return $guard;
        }

        $vcd = VisitClinicalData::find($id);
        $notes = $vcd->others;

        VisitClinicalData::where('visit_id', $new_visit_id)->delete();

        $a = VisitClinicalData::select('*')->where('id', $id)->get()->toArray();
        foreach($a as $code){
           unset($code['id']);
           $code['visit_id'] = $new_visit_id;
           $code['context'] =  $context;
           VisitClinicalData::insert($code);
        }

        return response()->json(['status' => 'success','message' => 'Data copied successfully']);
    }

    public function save_as_template(Request $request){
        $user_id = null;
        if($request->visit_id ?? false){
            $visit = Visitlog::find($request->visit_id);
            if($visit){
                $user_id = $visit->doctor_id;
            }
        }

        if($request->user_id ?? false){
            $user_id = $request->user_id;
        } elseif($request->doctor_id ?? false){
            $user_id = $request->doctor_id;
        }

        if(!$user_id && auth()->check()){
            $user_id = auth()->id();
        }


        $visit_id = $request->visit_id;

        $freeTextboxData = $request->input('freeTextbox', []);

        // Add updated_at timestamp for each field
        $currentTime = now()->format('Y-m-d H:i:s'); // Get the current timestamp

        $formattedData = [];
        foreach ($freeTextboxData as $key => $value) {
            $formattedData[$key] = [
                'value' => $value,
                'updated_at' => $currentTime
            ];
        }
        // Convert to JSON format
        $jsonData = json_encode($formattedData, JSON_PRETTY_PRINT);

        $existingTemplate = Template::where('user_id', $user_id)
                                        ->where('name', $request->template_name)
                                        ->when($request->context, function($q) use ($request) {
                                            $q->where('context', $request->context);
                                        })
                                        ->first();

        if ($existingTemplate) {
            return response()->json([
                'status' => 'error',
                'message' => 'Template name already exists in this section for this doctor.'
            ], 422);
        }

        DB::beginTransaction();

        $tem = new Template;
        $tem->user_id = $user_id;
        $tem->name = $request->template_name;
        $tem->context = $request->context;
        $tem->template = $jsonData;
        $tem->save();


        $template_id = $tem->id;

        if(($request->e_prescription??false) == 'v3'){

        }else{
            $medicines = json_decode($request->medicine_table, true) ?? [];


            $lenght = count($medicines);

            PresTemplate::where('template_id', $template_id)->delete();

           // dd($request->medicine);
            foreach($request->medicine ?? [] as $index => $med)
            {

                $brand_id = $med['brand_id'];
                $source = $med['d_type'] ?? 'ss';
                $mark = ($med['imp'] ?? false) ? "true" : "false";
                $route = $med['route'] ?? "";
                $frequency = $med['frequency'] ?? "";
                $spl_inst = $med['special_instruction'] ?? "";
                $duration = $med['duration'] ?? "";
                $notes = $med['notes'] ?? "";

                if($med['manual'])
                {
                    $pf = new PresManual;
                } else {
                    $pf = new PresTemplate;
                    $pf->d_type = $source;
                }

                $pf->save_type = 'p';
                $pf->template_id = $tem->id;
                $pf->brand_id = $brand_id;
                $pf->nc = 'false';
                $pf->vic = $mark;
                $pf->rs = $route;
                $pf->it = $frequency;
                $pf->spl_inst = $spl_inst;
                $pf->dt = $duration;
               // $pf->notes = $notes;
                //$pf->d_order = $index + 1;
                $pf->save();

                // Extra logic only for non-manual
                if(!$med['manual'])
                {
                    $compositionID = DB::table('drug_brand_index')
                        ->where('id', $brand_id)
                        ->value('composition_id');

                    if ($compositionID) {
                        $visit = Visitlog::find($visit_id);

                        DB::table('doctor_fav_brand_composition')
                            ->updateOrInsert(
                                [
                                    'doctor_id' => $visit->doctor_id,
                                    'composition_id' => $compositionID
                                ],
                                [
                                    'frequency' => $frequency,
                                    'spl_inst'  => $spl_inst,
                                ]
                            );

                        if($notes){
                            DB::table('doctor_fav_composition_notes')
                                ->insertOrIgnore([
                                    'doctor_id' => $visit->doctor_id,
                                    'composition_id' => $compositionID,
                                    'notes' => $notes,
                                ]);
                        }
                    }
                }
            }
        }

            DB::commit();


        return response()->json([
            'status' => 'success',
            'message' => 'Template saved successfully',
            'template' => $tem,
            'data' => $tem
        ]);
    }


    public function prescription_save_as_template(Request $request)
    {
        // dd($request->all());
        DB::beginTransaction();


        $diagnoses = json_decode($request->data, true) ?? [];
        $lenght = count($diagnoses);

        $newData = [];
        for ($i = 0; $i < $lenght - 1; $i++) {
            $icd_code = $diagnoses[$i]['column_1'];
            $icd_name = null;

            if ($request->context == 'icd_code') {
                $icd = ICDCodes::where('icd_code', $icd_code)->first();
                // dd($icd);
                if ($icd) {
                    $icd_name = $icd->icd_name;
                }
            }

            $entry = [
                'name'     => $diagnoses[$i]['column_1'],
                'comment'  => $diagnoses[$i]['column_2'],
                'duration' => $diagnoses[$i]['column_3'],
                'date'     => $diagnoses[$i]['column_4'],
            ];

            // Only add icd_name if it's found
            if (!empty($icd_name)) {
                $entry['icd_name'] = $icd_name;
            }

            $newData[] = $entry;
        }





        $tem = new Template;
        $tem->user_id = $request->doctor_id;
        $tem->name = $request->template_name;
        $tem->context = $request->context;
        $tem->template = json_encode($newData);
        $tem->save();


        $template_id = $tem->id;

        if(($request->e_prescription_version??false) == 'v3'){
            $medicines = $request->medicine??[];

            PresTemplate::where('template_id', $template_id)->delete();

            foreach($medicines as $med){

                $brand_id = $med['brand_id'];
                $source = $med['d_type']??'';
                $mark = ($med['imp']??false)? "true":"false";
                $route = $med['route']??"";
                $frequency = $med['frequency']??"";
                $spl_inst = $med['special_instruction']??"";
                $duration = $med['duration']??"";


                $manual = ($med['manual'] == 1)?1:0;

                $pf = new PresTemplate;
                $pf->manual = $manual;
                $pf->save_type = 'p';
                $pf->template_id = $template_id;
                $pf->brand_id = $brand_id;
                $pf->d_type = $source;
                $pf->nc = 'false';
                $pf->vic = $mark;
                $pf->rs = $route;
                $pf->it = $frequency;
                $pf->spl_inst = $spl_inst;
                $pf->dt = $duration;
                $pf->save();
            }

        }else{

            $medicines = json_decode($request->medicine_table, true) ?? [];
            $lenght = count($medicines);

            PresTemplate::where('template_id', $template_id)->delete();

            for($i = 0; $i < $lenght; $i++)
            {
                $medicine = $medicines[$i]['column_2'];    // 105|ss

                $brand_id = explode('|', $medicine)[0]; // 105
                $source = explode('|', $medicine)[1]; // ss

                if($brand_id && $source){

                    $mark = ($medicines[$i]['column_1'])? "true":"false";
                    $route = $medicines[$i]['column_3'];

                    $pf = new PresTemplate;
                    $pf->save_type = 'p';
                    $pf->template_id = $template_id;
                    $pf->brand_id = $brand_id;
                    $pf->d_type = $source;
                    $pf->nc = 'false';
                    $pf->vic = $mark;
                    $pf->rs = $route;
                    $pf->it = $medicines[$i]['column_4'];
                    $pf->spl_inst = $medicines[$i]['column_5'];
                    $pf->dt = $medicines[$i]['column_6'];
                    $pf->save();

                    $this->add_medicine_to_doc_fav_brand2($request->doctor_id,$brand_id,$source,$mark);
                }

            }
        }


        DB::commit();


        return response()->json([
            'status' => 'success',
            'message' => 'Template saved successfully',
            'template' => [
                'id' => $tem->id,
                'name' => $tem->name,
                'context' => $tem->context,
                'created_at' => $tem->created_at ? $tem->created_at->format('Y-m-d H:i:s') : date('Y-m-d H:i:s'),
            ]
        ]);
    }

    public function prescription_save_as_template2(Request $request){

            $data = $request->input('data');


            $tem = new Template;
            $tem->user_id = $request->doctor_id;
            $tem->name = $request->template_name;
            $tem->context = $request->context;
            $tem->template = json_encode(is_array($data) ? $data : []);
            $tem->save();

            return response()->json(['status'=>'success','message'=>'Template saved successfully']);

    }


    public function prescription_search_templates(Request $request){

            $templates = Template::select('id','name','freetext as content')
                                  ->where('user_id', $request->doctor_id)
                                  ->where('context', $request->context)
                                  ->where('name', 'like', '%'.$request->search.'%')
                                  ->get();

            return response()->json([
                'status' => 'success',
                'success' => true,
                'templates' => $templates
            ]);
    }

    public function load_template(Request $request){
        $template_id = $request->template_id;

        $template = Template::find($template_id);
        if(!$template){
            return response()->json(['status' => 'error', 'message' => 'Template not found']);
        }

        $formData = is_string($template->template) ? json_decode($template->template, true) : ($template->template ?? []);

        $medicines = $this->get_template_medicine_list($template_id) ?? [];
        foreach($medicines as $r){
            $formulation = $this->get_formulation($r->brand_id, $r->d_type);
            if($r->d_type == 'ss'){
                foreach($formulation as $f){
                    $r->formulation = ($f->drug_name ?? '').' '.($f->dose ?? '').' '.($f->unit_name ?? '').' ('.($f->form ?? '').')';
                }
            }
        }

        return response()->json([
            'status' => 'success',
            'data' => $template,
            'formData' => $formData,
            'medicines' => $medicines
        ]);
    }

    public function prescription_template(Request $request){

        // dd($request->all());

        $template_id = $request->template_id;


        $q_medicines = [];

        $medicines = $this->get_template_medicine_list($template_id) ?? [];
            foreach($medicines as $r){
                            //  $r->formulation1 = $this->get_formulation($r->brand_id, $r->d_type);
                            $formulation = $this->get_formulation($r->brand_id, $r->d_type);

                            if($r->d_type == 'ss'){
                                foreach($formulation as $f){
                                    $form = $f->form;
                                    $dose = $f->dose;
                                    $unit = $f->unit_name;
                                    $drug = $f->drug_name;

                                    $r->formulation = $drug.' '.$dose.' '.$unit.' ('.$form.')';

                                }
                            }else{
                                foreach($formulation as $f){
                                    $form = $f->form;

                                    $strArray = [];
                                    foreach($f->comb_name as $cn){
                                        $formulation = $cn->drug_name;
                                        $dose = $cn->dose;
                                        $unit_name = $cn->unit_name;

                                        $strArray[] = $formulation. ' '.$dose.' '.$unit_name;
                                    }
                                    $str = implode(' + ', $strArray);
                                    $r->formulation = $str.'('.$form.')';
                                }
                            }
                        }


         return response()->json([
            'status' => 'success',
            'medicines' => $medicines
         ]);
        // return view('admin.patient.e_prescription', compact('medicines','q_medicines'));
    }


    public function show_logs(Request $request){
        $visit_id = $request->visit_id;
        $context = $request->context2;
        $key = $request->context;
        $input = $request->input_id;

        $visit = Visitlog::select('doctor_id','hospital_id','visit_id','patient_id')->where('id', $visit_id)->first();
        if (!$visit) {
            return response()->json(['status' => 'success', 'data' => [], 'input_id' => $input]);
        }

        $values = [];

        if ($context === 'surgery_notes') {
            $prev_visit_ids = Visitlog::where('patient_id', $visit->patient_id)
                                      ->where('hospital_id', $visit->hospital_id)
                                      ->pluck('id');

            $otLogs = \App\Models\OtLog::select('surgery_note_data')
                                       ->whereIn('visit_id', $prev_visit_ids)
                                       ->whereNotNull('surgery_note_data')
                                       ->get();

            foreach ($otLogs as $row) {
                $data = is_string($row->surgery_note_data)
                    ? json_decode($row->surgery_note_data, true)
                    : (is_array($row->surgery_note_data) ? $row->surgery_note_data : []);
                if (isset($data[$key]) && !empty($data[$key])) {
                    $values[] = trim($data[$key]);
                }
            }
        } else {
            $prev_visits = Visitlog::select('id')
                                       ->where('patient_id', $visit->patient_id)
                                       ->where('hospital_id', $visit->hospital_id)
                                       ->where('doctor_id', $visit->doctor_id)
                                       ->get();

            $vcd = VisitClinicalData::select('others')->whereIn('visit_id', $prev_visits)->where('context', $context)->get();

            foreach ($vcd as $row) {
                $others = json_decode($row->others, true);

                if (isset($others[$key]) && isset($others[$key]['value'])) {
                    $values[] = trim($others[$key]['value']);
                }
            }
        }

        $values = array_unique(array_filter($values));

        return response()->json(['status'=>'success','data'=>$values, 'input_id'=>$input]);

    }

    public function load_past_visit_medicine(Request $request){

        $visit_id = $request->visit_id;
        $context = $request->context;

        $visit = Visitlog::select('doctor_id','hospital_id','visit_id','patient_id')->where('id', $visit_id)->first();
        if($visit){

            $last_visit = Visitlog::select('id')->where('hospital_id', $visit->hospital_id)
                                                ->where('doctor_id', $visit->doctor_id)
                                                ->where('visit_id', ($visit->visit_id - 1))
                                                ->where('patient_id',$visit->patient_id)
                                                ->first();

            if($last_visit){
                    // get_medicine_list($last_visit->id, $context);
            }
        }

        return response()->json(['status'=>'error','message'=>'No data found']);


    }


