    public function save_ipd_discharge_summary(Request $request)
    {

        $visit_id = $request->visit_id;
        $context = $request->context;
        $org_id = Auth::user()->org_id ?? null;

        if ($guard = ClinicalDocumentLockService::checkAndGuard($org_id, $visit_id, $context)) {
            return $guard;
        }

        $vl = Visitlog::find($visit_id);

        if(auth()->user()->can('module-permission',['edit_admission_discharge_date','can_update']))
        {
            if ($request->filled('addm_date')) {
                $vl->ad2 = $request->addm_date;
                $vl->admission_date = $request->addm_date;
            }
            if ($request->filled('addm_time')) {
                $vl->at1 = $request->addm_time;
                $vl->visit_time = $request->addm_time;
            }
            if ($request->filled('dis_date')) {
                $vl->dd2 = $request->dis_date;
                $vl->discharge_date = $request->dis_date;
            }
            if ($request->filled('dis_time')) {
                $vl->dt1 = $request->dis_time;
                $vl->discharge_time = $request->dis_time;
            }
            if ($request->filled('dis_time')) {
                $vl->dt1 = $request->dis_time;
                $vl->discharge_time = $request->dis_time;
            }
            $vl->surgery_time = $request->surgery_time??null    ;
        }

        if ($request->filled('next_visit_date')) {
            $vl->fud = $request->next_visit_date;
        }

        $vl->save();



        $vcd = VisitClinicalData::where('visit_id', $visit_id)->where('context', $request->context)->first();
        if(!$vcd){
            $vcd = new VisitClinicalData;
            $vcd->visit_id = $visit_id;
        }


        $freeTextboxData = $request->input('freeTextbox', []);

        // Add updated_at timestamp for each field
        $currentTime = now()->format('Y-m-d H:i:s'); // Get the current timestamp

        $formattedData = [];
        foreach ($freeTextboxData as $key => $value) {
            $formattedData[$key] = [
                'value' => $value,
                'updated_at' => $currentTime
            ];
        }

        if ($request->has('investigations')) {
            $formattedData['investigations'] = [
                'value' => $request->input('investigations'),
                'updated_at' => $currentTime
            ];
        }


        $dischargeType = $freeTextboxData['discharge_type'] ?? null;
        if ($dischargeType) {
                Ipd_details::where('visit_table_id', $visit_id)->update([
                'discharge_type' => $formattedData['discharge_type']['value'],
            ]);
        }

        // Convert to JSON format
        $jsonData = json_encode($formattedData, JSON_PRETTY_PRINT);

        // Save to database (assuming 'patients' table has a JSON column 'free_textbox_data')

        $vcd->others = $jsonData;
        $vcd->context = $request->context;
        $vcd->is_approved = 0;
        $vcd->is_abdm_approved = 0;
        $vcd->updated_by = auth()->user()->id;
        $vcd->save();

        $diagnoses = json_decode($request->diagnosis_data, true) ?? [];
        $diagLenght = count($diagnoses);

        /* $diagnoses = json_decode($request->diagnosis_data, true) ?? [];
        $diagLenght = count($diagnoses);

        // V1 textarea diagnosis
        $textareaDiagnosis = $request->input('freeTextbox.diagnosis');*/

        $newDiagnostisData = [];
        $cd = VisitClinicalData::firstOrNew(['visit_id' => $visit_id, 'context' => $request->context]);

        if(($request->diagnosis_version??false) == 'v2'){
            for($i = 0; $i < $diagLenght; $i++){
                $newDiagnostisData[] = [
                    'name' => $diagnoses[$i]['column_1'],
                    'date' => castDateFormat($diagnoses[$i]['column_2']),
                ];
                $this->add_comment_v2($visit_id,$diagnoses[$i]['column_1'],'diagnosis');
            }
        }else{

            for($i = 0; $i < $diagLenght; $i++){
                $newDiagnostisData[] = [
                    'name' => $diagnoses[$i]['column_1'],
                    'comment' => $diagnoses[$i]['column_2'],
                    'duration' => $diagnoses[$i]['column_3'],
                    'date' => $diagnoses[$i]['column_4'],
                ];

                $this->add_comment_v2($visit_id,$diagnoses[$i]['column_1'],'diagnosis');
                $this->add_comment_v2($visit_id,$diagnoses[$i]['column_2'],'diagnosis_comment');
            }
        }

        $cd->diagnosis = $newDiagnostisData;
        $cd->save();


        ###################################################

        if(($request->e_prescription??false) && (in_array($request->e_prescription, ['v3', 'v4'])))
        {
            Pres_final::where('visit_table_id', $visit_id)->delete();
            PresManual::where('visit_table_id', $visit_id)->delete();


                foreach($request->medicine??[] as $index => $med)
                {
                    $brand_id = $med['brand_id'];
                    $source = $med['d_type'];
                    $mark = ($med['imp']??false)? "true":"false";
                    $route = $med['route']??"";
                    $frequency = $med['frequency']??"";
                    $spl_inst = $med['special_instruction']??"";
                    $duration = $med['duration']??"";

                    if(($med['manual'] ?? false) || empty($brand_id) || !is_numeric($brand_id))
                    {
                        $pf = new PresManual;
                        $pf->save_type = 'p';
                        $pf->visit_table_id = $visit_id;
                        $pf->brand_id = $brand_id;
                        // $pf->d_type = $source;
                        $pf->nc = 'false';
                        $pf->vic = $mark;
                        $pf->rs = $route;
                        $pf->it = $frequency;
                        $pf->spl_inst = $spl_inst;
                        $pf->dt = $duration;
                        $pf->d_order = $index+1;
                        $pf->save();

                    }else{

                        $pf = new Pres_final;
                        $pf->save_type = 'p';
                        $pf->visit_table_id = $visit_id;
                        $pf->brand_id = $brand_id;
                        $pf->d_type = $source;
                        $pf->nc = 'false';
                        $pf->vic = $mark;
                        $pf->rs = $route;
                        $pf->it = $frequency;
                        $pf->spl_inst = $spl_inst;
                        $pf->dt = $duration;
                        $pf->d_order = $index+1;
                        $pf->save();


                        if($source === 'ss'){
                            $b =  Drug_brand::find($brand_id);

                            $dose_id = $b->dose_id ?? '';
                            $drug_id = $b->drug_id ?? '';
                            $form_id = $b->form_id?? '';
                        }else{
                            $b = DrugCombBrand::find($brand_id);
                            $dose_id = $b->comb_dose_id_entry ??'';
                            $drug_id = $b->comb_id??'';
                            $form_id = $b->form_id??'';
                        }

                        if(($request->e_prescription??false) && (in_array($request->e_prescription, ['v4']))){
                            $compositionID = DB::table('drug_brand_index')->where('id',$brand_id)->first()->composition_id??'';
                            if ($compositionID) {
                                $visit = Visitlog::find($visit_id);
                                \DB::table('doctor_fav_brand_composition')
                                    ->updateOrInsert([
                                            'doctor_id' => $visit->doctor_id,
                                            'composition_id' => $compositionID
                                        ],
                                        [
                                            'frequency' => $frequency,
                                            'spl_inst'  => $spl_inst,
                                        ]);
                                if($notes??false){
                                    \DB::table('doctor_fav_composition_notes')
                                        ->insertOrIgnore([
                                            'doctor_id' => $visit->doctor_id,
                                            'composition_id' => $compositionID,
                                            'notes' => $notes,
                                        ]);
                                }
                                }

                        }else{

                                $this->add_medicine_to_doc_fav_brand($visit_id,$brand_id,$source,$mark);

                                $this->add_comment($visit_id,$med,'medicine');
                                if($b){
                                    $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $frequency, $source,'it' );
                                    $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $spl_inst, $source,'spl_inst' );
                                    $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $route, $source,'route' );
                                }
                        }
                    }

                }
        }else{

            // save medicines
            $medicines = json_decode($request->medicine_table, true) ?? [];
            $lenght = count($medicines);

            Pres_final::where('visit_table_id', $visit_id)->delete();

            for($i = 0; $i < $lenght; $i++){

                $medicine = $medicines[$i]['column_2'];    // 105|ss

                $brand_id = explode('|', $medicine)[0]; // 105
                $source = explode('|', $medicine)[1]; // ss

                //   return $medicines[$i]['column_1'];

                $mark = ($medicines[$i]['column_1'])? "true":"false";
                $route = $medicines[$i]['column_3'];

                $pf = new Pres_final;
                $pf->save_type = 'p';
                $pf->visit_table_id = $visit_id;
                $pf->brand_id = $brand_id;
                $pf->d_type = $source;
                $pf->nc = 'false';
                $pf->vic = $mark;
                $pf->rs = $route;
                $pf->it = $medicines[$i]['column_4'];
                $pf->spl_inst = $medicines[$i]['column_5'];
                $pf->dt = $medicines[$i]['column_6'];
                $pf->save();


                if($source === 'ss'){
                    $b =  Drug_brand::find($brand_id);

                    $dose_id = $b->dose_id ?? '';
                    $drug_id = $b->drug_id ?? '';
                    $form_id = $b->form_id?? '';
                }else{
                    $b = DrugCombBrand::find($brand_id);
                    $dose_id = $b->comb_dose_id_entry ??'';
                    $drug_id = $b->comb_id??'';
                    $form_id = $b->form_id??'';
                }

                $this->add_medicine_to_doc_fav_brand($visit_id,$brand_id,$source,$mark);

                $this->add_comment($visit_id,$medicine,'medicine');
                if($b){
                    $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $medicines[$i]['column_3'],$source,'route' );
                    $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $medicines[$i]['column_4'],$source,'it' );
                    $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $medicines[$i]['column_5'],$source,'spl_inst' );
                }

            }

            // store manula medicine s

            $medicines = json_decode($request->manual_medicine, true) ?? [];
            $lenght = count($medicines);

            PresManual::where('visit_table_id', $visit_id)->delete();

            for($i = 0; $i < $lenght; $i++){

                $brand_name = $medicines[$i]['column_2'];    // 105|ss

                $mark = ($medicines[$i]['column_1'])? "true":"false";
                $route =  $medicines[$i]['column_3'];

                $pf = new PresManual;
                $pf->save_type = 'p';
                $pf->visit_table_id = $visit_id;
                $pf->brand_id = $brand_name;
                // $pf->d_type = $source;
                $pf->nc = 'false';
                $pf->vic = $mark;
                $pf->rs = $route;
                $pf->it = $medicines[$i]['column_4'];
                $pf->spl_inst = $medicines[$i]['column_5'];
                $pf->dt = $medicines[$i]['column_6'];
                $pf->save();

            }
        }

        Visitlog::where('id', $visit_id)->update([ 'fud' => $request->next_visit_date ]);

        try {
            $visitRecord = Visitlog::find($visit_id);
            $hospId = (int)($visitRecord->hospital_id ?? (auth()->check() ? (auth()->user()->org_id ?? 1) : 1));
            if ($visitRecord && !empty($visitRecord->patient_id) && \Illuminate\Support\Facades\Schema::hasTable('patient_care_contexts') && \App\Helpers\LicenseKey::isModuleActiveAndValid('abha', $hospId)) {
                \DB::table('pi')->where('id', $visitRecord->patient_id)->update(['abdm_enabled' => 1]);
                $isDayCare = str_contains(strtolower((string)$context), 'day_care');
                app(\App\Services\ABDM\CareContextManagerService::class)->registerDischargeSummaryContext(
                    visitId: $visit_id,
                    vcdId: $vcd->id ?? null,
                    patientId: (int)$visitRecord->patient_id,
                    hospitalId: $hospId,
                    isDayCare: $isDayCare,
                    autoLink: true
                );
            }
        } catch (\Throwable $e) {
            \Illuminate\Support\Facades\Log::channel('abdm')->warning("[save_ipd_discharge_summary] ABDM care context sync failed: " . $e->getMessage());
        }

        return response()->json([ 'status' => 'success', 'message' => 'Data saved successfully!' ]);

    }




    public function save_clinical_notes(Request $request)
    {

        $visit_id = $request->visit_id;
        $context = $request->context;
        $org_id = Auth::user()->org_id ?? null;

        if ($guard = ClinicalDocumentLockService::checkAndGuard($org_id, $visit_id, $context)) {
            return $guard;
        }

        $vcd = VisitClinicalData::where('visit_id', $visit_id)->where('context', $context)->first();
        if ($vcd) {
            $vcdOtherData = json_decode($vcd->other_data ?? '[]', true) ?: [];
            $activeLock = $vcdOtherData['edit_lock'] ?? null;
            if ($activeLock && !empty($activeLock['lock_token'])) {
                $lockedAt = !empty($activeLock['locked_at']) ? \Carbon\Carbon::parse($activeLock['locked_at']) : null;
                $isExpired = !$lockedAt || now()->diffInSeconds($lockedAt) > 60;
                if (!$isExpired) {
                    $incomingToken = $request->input('lock_token');
                    if (empty($incomingToken) || !hash_equals((string)$activeLock['lock_token'], (string)$incomingToken)) {
                        return response()->json([
                            'status' => 'error',
                            'locked' => true,
                            'message' => 'Document editing has been taken over by another window or device. Changes were not saved.'
                        ], 423);
                    }
                    // Refresh lock timestamp on successful save
                    $activeLock['locked_at'] = now()->toDateTimeString();
                    $vcdOtherData['edit_lock'] = $activeLock;
                    $vcd->other_data = json_encode($vcdOtherData);
                }
            }
        }
        if (!$vcd) {
            $vcd = new VisitClinicalData;
            $vcd->visit_id = $visit_id;
        }

        $freeTextboxData = $request->input('freeTextbox', []);

        // Add updated_at timestamp for each field
        $currentTime = now()->format('Y-m-d H:i:s'); // Get the current timestamp
        $jsonKeysThatContainsArray = get_clinical_key_that_contains_array();

        $formattedData = [];
        foreach ($freeTextboxData as $key => $value)
        {
            $finalValue = $value;
            if (in_array($key, $jsonKeysThatContainsArray, true))
            {
                // If value is a string AND looks like JSON
                if (is_string($value)) {
                    $decoded = json_decode($value, true);
                    // If valid JSON array or object ΓåÆ use decoded value
                    if (json_last_error() === JSON_ERROR_NONE && is_array($decoded)) {
                        $finalValue = $decoded;
                    }
                }
            }
            $formattedData[$key] = [
                'value' => $finalValue,
                'updated_at' => $currentTime
            ];
        }

        if ($request->has('investigations')) {
            $formattedData['investigations'] = [
                'value' => $request->input('investigations'),
                'updated_at' => $currentTime
            ];
        }

        if ($request->has('examine_note_ids')) {
            foreach ($request->input('examine_note_ids') as $key => $value) {
                if($request->input('examine_note')[$key]??false){
                    $formattedData['examine_notes'][$key] = [
                        'note_id' => $value,
                        'value' => $request->input('examine_note')[$key],
                        'updated_at' => $currentTime
                    ];
                }
            }
        }

        // Convert to JSON format
        $jsonData = json_encode($formattedData, JSON_PRETTY_PRINT);

        // Save to database (assuming 'patients' table has a JSON column 'free_textbox_data')

        /* $diagnosis = $request->input('freeTextbox.diagnosis');
        $vcd->diagnosis = $diagnosis ? json_encode($diagnosis) : json_encode([]); */
        $diagnosisComponent = $request->input('freeTextbox.diagnosis_component');

        if (!empty($diagnosisComponent)) {
            $decodedDiagnosis = json_decode($diagnosisComponent, true);
            $vcd->diagnosis = json_encode($decodedDiagnosis);
        } else {
            $vcd->diagnosis = json_encode([]);
        }

        $ccComponent = $request->input('freeTextbox.chief_complaints_component');

        if (!empty($ccComponent)) {
            $decodedCC = json_decode($ccComponent, true);
            $vcd->cc = json_encode($decodedCC);
        } else {
            $vcd->cc = json_encode([]);
        }

        $vcd->others = $jsonData;
        $vcd->context = $request->context;

        if($request->investigations != null){
            $vcd->investigation_request = json_encode($request->investigations);
        }else{
            $vcd->investigation_request = '[]';
        }


        if ($request->exit && empty($vcd->closed_at)) {
            $vcd->closed_at = now();
        }

        $vcd->save();


        
       $this->saveMedicines($request, $visit_id);

        $visit = Visitlog::find($visit_id);
        $visit->fud = $request->next_visit_date;
        $visit->queue_status = 1;
        $visit->save();


        $this->saveVitals($request, $visit_id);

        return response()->json(['status' => 'success','message' => 'Data saved successfully!']);
    }

    private function saveVitals($request, $visit_id)
    {
        if (empty($visit_id)) {
            return;
        }

        $context = (string) ($request->context ?? '');

        // Only save vitals if context is coming from clinical-notes.blade.php (v2 clinical notes)
        $isV2ClinicalContext = in_array($context, [
            'v2.general.notes',
            'v2.clinical-notes',
            'clinical-notes',
            'general.notes',
            'pages.v2.clinical-notes',
        ], true) || str_starts_with($context, 'v2.');

        if (!$isV2ClinicalContext) {
            return;
        }

        $vitals = Vitals::where('visit_id', $visit_id)->first();
        $isNew = false;

        if (!$vitals) {
            $vitals = new Vitals;
            $vitals->visit_id = $visit_id;
            $vitals->created_by = Auth::id() ?? 1;
            $vitals->updated_by = Auth::id() ?? 1;
            $isNew = true;
        } else {
            $vitals->updated_by = Auth::id() ?? 1;
        }

        $vitals->context = $context;

        // Process BP (upperBP and lowerBP may arrive as arrays from upperBP[], lowerBP[])
        $upperBp = is_array($request->upperBP) ? ($request->upperBP[0] ?? null) : $request->upperBP;
        $lowerBp = is_array($request->lowerBP) ? ($request->lowerBP[0] ?? null) : $request->lowerBP;
        $upperBp = !is_null($upperBp) ? trim((string)$upperBp) : '';
        $lowerBp = !is_null($lowerBp) ? trim((string)$lowerBp) : '';

        $bpArr = json_decode($vitals->bp ?? '[]', true);
        if (!is_array($bpArr)) {
            $bpArr = [];
        }

        if ($request->has('upperBP') || $request->has('lowerBP')) {
            if ($upperBp !== '' || $lowerBp !== '') {
                if (!empty($bpArr)) {
                    $lastKey = array_key_last($bpArr);
                    $lastEntry = $bpArr[$lastKey];
                    $lastUpper = is_array($lastEntry['upper_bp'] ?? null) ? ($lastEntry['upper_bp'][0] ?? '') : ($lastEntry['upper_bp'] ?? '');
                    $lastLower = is_array($lastEntry['lower_bp'] ?? null) ? ($lastEntry['lower_bp'][0] ?? '') : ($lastEntry['lower_bp'] ?? '');

                    if ((string)$lastUpper === (string)$upperBp && (string)$lastLower === (string)$lowerBp) {
                        // Same reading, keep existing entry to prevent duplicate entries on repeated autosaves
                    } else {
                        $bpArr[$lastKey]['upper_bp'] = $upperBp;
                        $bpArr[$lastKey]['lower_bp'] = $lowerBp;
                        $bpArr[$lastKey]['updated_at'] = now()->toIso8601String();
                    }
                } else {
                    $bpArr[] = [
                        'upper_bp' => $upperBp,
                        'lower_bp' => $lowerBp,
                        'position' => $request->position ?? null,
                        'site' => $request->site ?? null,
                        'created_by' => Auth::id() ?? 1,
                        'created_at' => now()->toIso8601String(),
                    ];
                }
                $vitals->bp = json_encode($bpArr);
            } else {
                $vitals->bp = json_encode([]);
            }
        }

        // Process Pulse
        $pulseRate = !is_null($request->pulseRate) ? trim((string)$request->pulseRate) : '';
        $pulseArr = json_decode($vitals->pulse ?? '[]', true);
        if (!is_array($pulseArr)) {
            $pulseArr = [];
        }

        if ($request->has('pulseRate')) {
            if ($pulseRate !== '') {
                if (!empty($pulseArr)) {
                    $lastKey = array_key_last($pulseArr);
                    $lastEntry = $pulseArr[$lastKey];
                    $lastPulse = (string)($lastEntry['pulseRate'] ?? '');

                    if ($lastPulse === (string)$pulseRate) {
                        // Same reading, keep existing entry
                    } else {
                        $pulseArr[$lastKey]['pulseRate'] = $pulseRate;
                        $pulseArr[$lastKey]['updated_at'] = now()->toIso8601String();
                    }
                } else {
                    $pulseArr[] = [
                        'pulseRate' => $pulseRate,
                        'pulseChar' => $request->pulseCharacter ?? null,
                        'site' => $request->pulseSite ?? null,
                        'regularties' => $request->pulseRegularties ?? null,
                        'created_by' => Auth::id() ?? 1,
                        'created_at' => now()->toIso8601String(),
                    ];
                }
                $vitals->pulse = json_encode($pulseArr);
            } else {
                $vitals->pulse = json_encode([]);
            }
        }

        // Scalar vitals fields
        if ($request->has('height')) {
            $vitals->height = ($request->height !== null && $request->height !== '') ? $request->height : null;
        }
        if ($request->has('weight')) {
            $vitals->weight = ($request->weight !== null && $request->weight !== '') ? $request->weight : null;
        }
        if ($request->has('temprature')) {
            $vitals->temprature = ($request->temprature !== null && $request->temprature !== '' && $request->temprature != 0) ? $request->temprature : null;
        }
        if ($request->has('saturation')) {
            $vitals->saturation = ($request->saturation !== null && $request->saturation !== '') ? $request->saturation : null;
        }
        if ($request->has('rr')) {
            $vitals->rr = ($request->rr !== null && $request->rr !== '') ? $request->rr : null;
        }
        if ($request->has('blood_sugar')) {
            $vitals->blood_sugar = ($request->blood_sugar !== null && $request->blood_sugar !== '') ? $request->blood_sugar : null;
        }
        if ($request->has('ldl')) {
            $vitals->ldl = ($request->ldl !== null && $request->ldl !== '') ? $request->ldl : null;
        }
        if ($request->has('inr')) {
            $vitals->inr = ($request->inr !== null && $request->inr !== '') ? $request->inr : null;
        }
        if ($request->has('pain_assessment') || $request->has('pain_level') || $request->has('pain_score')) {
            $painVal = $request->pain_assessment ?? $request->pain_level ?? $request->pain_score;
            $vitals->pain_assessment = ($painVal !== null && $painVal !== '') ? (string)$painVal : null;
        }

        $hasAnyData = ($upperBp !== '' || $lowerBp !== '' || $pulseRate !== ''
            || ($request->has('height') && $request->height !== null && $request->height !== '')
            || ($request->has('weight') && $request->weight !== null && $request->weight !== '')
            || ($request->has('temprature') && $request->temprature !== null && $request->temprature !== '')
            || ($request->has('saturation') && $request->saturation !== null && $request->saturation !== '')
            || ($request->has('rr') && $request->rr !== null && $request->rr !== '')
            || ($request->has('pain_assessment') && $request->pain_assessment !== null && $request->pain_assessment !== '')
        );

        if (!$isNew || $hasAnyData) {
            if (!$vitals->bp) {
                $vitals->bp = json_encode([]);
            }
            if (!$vitals->pulse) {
                $vitals->pulse = json_encode([]);
            }
            $vitals->save();
        }
    }




    private function saveMedicines($request, $visit_id)
    {
        if(($request->e_prescription ?? false) && in_array($request->e_prescription, ['v3', 'v4']))
        {
            Pres_final::where('visit_table_id', $visit_id)->delete();
            PresManual::where('visit_table_id', $visit_id)->delete();

            foreach($request->medicine ?? [] as $index => $med)
            {
                $brand_id = $med['brand_id'];
                $source = $med['d_type'] ?? 'ss';
                $mark = ($med['imp'] ?? false) ? "true" : "false";
                $route = $med['route'] ?? "";
                $frequency = $med['frequency'] ?? "";
                $spl_inst = $med['special_instruction'] ?? "";
                $duration = $med['duration'] ?? "";
                $notes = $med['notes'] ?? "";

                if(($med['manual'] ?? false) || empty($brand_id) || !is_numeric($brand_id))
                {
                    $pf = new PresManual;
                } else {
                    $pf = new Pres_final;
                    $pf->d_type = $source;
                }

                $pf->save_type = 'p';
                $pf->visit_table_id = $visit_id;
                $pf->brand_id = $brand_id;
                $pf->nc = 'false';
                $pf->vic = $mark;
                $pf->rs = $route;
                $pf->it = $frequency;
                $pf->spl_inst = $spl_inst;
                $pf->dt = $duration;
                $pf->notes = $notes;
                $pf->d_order = $index + 1;
                $pf->save();

                // Extra logic only for non-manual
                if(!$med['manual'])
                {
                    $compositionID = DB::table('drug_brand_index')
                        ->where('id', $brand_id)
                        ->value('composition_id');

                    if ($compositionID) {
                        $visit = Visitlog::find($visit_id);

                        DB::table('doctor_fav_brand_composition')
                            ->updateOrInsert(
                                [
                                    'doctor_id' => $visit->doctor_id,
                                    'composition_id' => $compositionID
                                ],
                                [
                                    'frequency' => $frequency,
                                    'spl_inst'  => $spl_inst,
                                ]
                            );

                        if($notes){
                            DB::table('doctor_fav_composition_notes')
                                ->insertOrIgnore([
                                    'doctor_id' => $visit->doctor_id,
                                    'composition_id' => $compositionID,
                                    'notes' => $notes,
                                ]);
                        }
                    }
                }
            }
        }
        else
        {
            // OLD FORMAT LOGIC
            $medicines = json_decode($request->medicine_table, true) ?? [];

            Pres_final::where('visit_table_id', $visit_id)->delete();

            foreach($medicines as $medicineRow)
            {
                $medicine = $medicineRow['column_2'];
                [$brand_id, $source] = explode('|', $medicine);

                $pf = new Pres_final;
                $pf->save_type = 'p';
                $pf->visit_table_id = $visit_id;
                $pf->brand_id = $brand_id;
                $pf->d_type = $source;
                $pf->nc = 'false';
                $pf->vic = ($medicineRow['column_1']) ? "true" : "false";
                $pf->rs = $medicineRow['column_3'];
                $pf->it = $medicineRow['column_4'];
                $pf->spl_inst = $medicineRow['column_5'];
                $pf->dt = $medicineRow['column_6'];
                $pf->save();
            }

            // Manual medicines
            $manuals = json_decode($request->manual_medicine, true) ?? [];

            PresManual::where('visit_table_id', $visit_id)->delete();

            foreach($manuals as $row)
            {
                $pf = new PresManual;
                $pf->save_type = 'p';
                $pf->visit_table_id = $visit_id;
                $pf->brand_id = $row['column_2'];
                $pf->nc = 'false';
                $pf->vic = ($row['column_1']) ? "true" : "false";
                $pf->rs = $row['column_3'];
                $pf->it = $row['column_4'];
                $pf->spl_inst = $row['column_5'];
                $pf->dt = $row['column_6'];
                $pf->save();
            }
        }
    }


   public function today_visit_list($request,$context = false, $vac = false)
   {

        $user = Auth::user();
        $org_id = $user->org_id;

        $currentDate = Carbon::today()->toDateString();

        $visit = Visitlog::leftjoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->leftJoin('pi', 'pi.id', '=', 'visitlog.patient_id')
                            ->leftJoin('vac_enrolled_patient','vac_enrolled_patient.patient_id','=','pi.id')
                            ->leftJoin('patient_billing', function ($join) {
                                $join->on('patient_billing.visit_id', '=', 'visitlog.id');
                                $join->on('visitlog.patient_id', '=', 'pi.id');
                            });
        if ($context !== false) {
            $visit->leftJoin('visit_clinical_data', function ($join) use ($context) {
                $join->on('visit_clinical_data.visit_id', '=', 'visitlog.id')
                    ->where('visit_clinical_data.context', '=', $context);
            });
        }

        if($request->service_type??false){
            $flag = $request->service_type;

            $visit->join('patient_gen_bill','patient_gen_bill.bill_id','=','patient_billing.id');
            $visit->join('hospital_services','hospital_services.id','=','patient_gen_bill.service_id');
            $visit->where('hospital_services.flag', $flag);
        }
        if ($request->including_flag ?? false) {
            $flags = (array) $request->including_flag;
            $visit->join('patient_gen_bill', 'patient_gen_bill.bill_id', '=', 'patient_billing.id')
                ->join('hospital_services', function ($join) use ($flags) {
                    $join->on('hospital_services.id', '=', 'patient_gen_bill.service_id')
                        ->whereIn('hospital_services.flag', $flags);
                });
        }

        if ($request->including_cancelled ?? false) {
            // $visit->whereIn('visitlog.is_cancelled',[0,1]);
        }else{
            $visit->where('visitlog.is_cancelled',0);
        }

        $visit->select(
                        'visitlog.created_at as created',
                        'visitlog.doctor_id as did',
                        'visitlog.id as vid',
                        'visitlog.patient_id as pid',
                        'visitlog.date as on_hold',
                        'visitlog.token_no as token_no',
                        'visitlog.visit_time as time',
                        'visitlog.visit_id',
                        'visitlog.ch as amt',
                        'visitlog.is_visited',
                        'visitlog.visit_status',
                        'patient_billing.status as bill_status',
                        'patient_billing.id as bill_id',
                        'visitlog.queue_status as queue_status',
                        'doctor_db.name as doctor_name',
                        'pi.Fname',
                        'pi.Lname',
                        'pi.age',
                        'pi.sex',
                        'pi.dob',
                        'pi.mobile_no',
                        'pi.prefix',
                         DB::raw("CASE
                            WHEN vac_enrolled_patient.id IS NOT NULL
                            THEN 'enrolled'
                            ELSE 'not_enrolled'
                        END AS vac_status"),
                        DB::raw("
                            CASE
                                WHEN EXISTS (
                                    SELECT 1 FROM vac_log
                                    WHERE vac_log.patient_id = pi.id
                                    AND DATE(vac_log.updated_at) = '$currentDate'
                                )
                                THEN 'Seen'
                                ELSE ''
                            END AS today_vac_status
                        ")
        );
        if ($request->including_flag ?? false) {
            $visit->addSelect(DB::raw("
                IFNULL(
                    CONCAT(
                        '[',
                        GROUP_CONCAT(
                            DISTINCT JSON_OBJECT(
                                'service_id', patient_gen_bill.service_id,
                                'service_name', hospital_services.service,
                                'service_flag', hospital_services.flag,
                                'service_status', patient_gen_bill.service_status,
                                'service_billed_at', patient_gen_bill.created_at
                            )
                            ORDER BY patient_gen_bill.created_at ASC
                        ),
                        ']'
                    ),
                    '[]'
                ) as services
            "));
        }
        if ($context !== false) {
            $visit->addSelect('visit_clinical_data.closed_at');
        }
        if($request->service_type??false){
            $visit->addSelect('patient_gen_bill.service_status');
            $visit->addSelect('patient_gen_bill.created_at as service_created');
        }
        // ->distinct() // Ensure no duplicate rows
        $visit->where('visitlog.hospital_id', $org_id);
        $visit->where('visit_status', 0);

        if($request->start_date && $request->end_date){
            $visit->whereBetween('visitlog.date', [$request->start_date, $request->end_date]);
        }else{
            $visit->whereDate('visitlog.date', $currentDate);
        }
        if($request->doctor_id){
            $visit->where('visitlog.doctor_id', $request->doctor_id);
        }
        // if($request->emergency){
            // $visit->where('visitlog.emergency', 0);
            // $visit->where('visitlog.er_status', 2);
        // }
        $visit->orderBy('visitlog.id', 'DESC');
        $visit->groupBy('visitlog.id');
        $visit = $visit->get();

        // Initialize an array to store the visit count for each doctor
        $doctorVisitCounts = [];

        // Loop through visits and assign serial numbers
        foreach ($visit as $visi) {
            $doctorId = $visi->did;

        // Initialize the count if not already set
        if (!isset($doctorVisitCounts[$doctorId])) {
            $doctorVisitCounts[$doctorId] = count($visit)+1;
        }

        // Increment the count
            $doctorVisitCounts[$doctorId]--;

        // Assign the serial number
            $visi->sr_no = $doctorVisitCounts[$doctorId];
        }


        return $visit;
   }

    public function er_visit_list(Request $request){

        $user = Auth::user();
        $org_id = $user->org_id;

        $currentDate = Carbon::today()->toDateString();
        $from_date = $request->from_date ?? $currentDate;
        $to_date = $request->to_date ?? $currentDate;


        $visit = Visitlog::leftjoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->leftJoin('pi', 'pi.id', '=', 'visitlog.patient_id')
                            ->leftJoin('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                            ->leftJoin('vitals', 'vitals.visit_id', '=', 'visitlog.id')
                            // ->whereDate('visitlog.date', $currentDate)
                            ->leftJoin('vac_enrolled_patient','vac_enrolled_patient.patient_id','=','pi.id')
                            // ->whereDate('visitlog.date', '>=', $from_date)
                            // ->whereDate('visitlog.date', '<=', $to_date)
                            ->select('visitlog.*',
                                DB::raw('DATE_FORMAT(visitlog.created_at, "%d-%m-%Y") as visit_date'),
                                DB::raw('TIME_FORMAT(visitlog.created_at,"%h:%i %p") as visit_time'),
                                'visitlog.created_at as created',
                                'visitlog.doctor_id as did',
                                'visitlog.id as vid',
                                'visitlog.patient_id as pid',
                                'visitlog.on_hold as on_hold',
                                'doctor_db.name',
                                 'doctor_db.name as doctor_name',
                                'pi.prefix','pi.Fname','pi.Lname','pi.id as ageUhid','pi.dob',
                                'pi.age','pi.sex','pi.mobile_no','pi.id as uhid','pi.Address','pi.mnvs','pi.Fathername','pi.spousename',
                                DB::raw('DATE(fud) as fud'),
                                'visitlog.advice',
                                'health_insurance_agen.insurance_agen as insurance',
                                'vitals.bp', 'vitals.pulse','vitals.height','vitals.weight',
                                'vitals.temprature',
                                'vitals.rr',
                                'vitals.saturation',
                                'vitals.blood_sugar',
                                'vitals.ldl',
                                'vitals.inr',
                                 // NEW STATUS
                                DB::raw("CASE
                                            WHEN vac_enrolled_patient.id IS NOT NULL
                                            THEN 'enrolled'
                                            ELSE 'not_enrolled'
                                        END AS vac_status")
                            )
                            ->distinct() // Ensure no duplicate rows
                            ->where('visitlog.hospital_id', $org_id)
                            ->where('visitlog.emergency', 1)
                            ->where('visitlog.er_status', 0)
                            ->where('visitlog.is_cancelled', 0)
                            ->where('visitlog.visit_status', 0)
                            ->groupBy('visitlog.id')
                            ->orderBy('visitlog.id', 'DESC')
                            ->get();

            foreach($visit as $v){
                $pid = $v->pid;
                $total_surgery = Otlog::join('visitlog', 'visitlog.id', '=', 'ot_log.visit_id')
                                        ->where('visitlog.patient_id', $pid)
                                        ->count('ot_log.id') ?? 0;
                $v->total_surgery = $total_surgery;
            }

        $total_visit = count($visit);

        $doctorVisitCounts = [];

        // Append sr_no
        $visitlogs = $visit->groupBy('did')->flatMap(function ($group) {
            $srNo = count($group);
            return $group->map(function ($item) use (&$srNo) {
                $item->sr_no = $srNo--;
                return $item;
            });
        });

        $data=compact('visit');
        return response()->json([ 'data'=> $data, 'total_visit'=>$total_visit]);
    }


