      public function ipd_visit_list($request){

            $user = Auth::user();
            $org_id = $user->org_id;

            $currentDate = Carbon::today()->toDateString();


            $filter = json_decode($user->others ?? '{}', true); // fallback to empty array if null or invalid

            $floor = $request->floor ?? ($filter['floor'] ?? null);
            $area = $request->area ?? ($filter['area'] ?? null);



        $firstWardSub = DB::table('hospital_ward as hw1')
                            ->select('hw1.area', 'hw1.id as ward_id', 'hw1.floor_id')
                            ->whereRaw('hw1.id = (
                                SELECT MIN(hw2.id)
                                FROM hospital_ward as hw2
                                WHERE hw2.area = hw1.area
                            )');


            $visit = Visitlog::join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                        ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
                        ->join('ipd_details', 'ipd_details.visit_table_id', '=', 'visitlog.id')
                       ->leftJoinSub($firstWardSub, 'first_ward', function ($join) {
                                $join->on('first_ward.area', '=', 'ipd_details.ward');
                            })
                        ->leftJoin('hospital_floors', 'hospital_floors.id', '=', 'first_ward.floor_id')

                        ->select('visitlog.*',
                            'visitlog.created_at as created',
                            'visitlog.doctor_id as did',
                            'visitlog.id as vid',
                            'visitlog.patient_id as pid',
                            'doctor_db.name as doctor_name',
                            'pi.id',
                            'pi.Fname',
                            'pi.Lname',
                            'pi.age',
                            'pi.sex',
                            'pi.dob',
                            'pi.mobile_no',
                            'pi.prefix',
                            'ipd_details.id as ipd_no',

                        )
                        // ->distinct() // Ensure no duplicate rows
                        ->where('visitlog.hospital_id', $org_id)
                        ->where('visit_status', 1)
                         ->when($floor, function ($query) use ($floor) {
                            $query->where('hospital_floors.id', $floor);
                        })
                        ->when($area, function ($query) use ($area) {
                            $query->where('ipd_details.ward', $area);
                        });

        // if($request->start_date && $request->end_date){
        //     $visit->whereBetween('visitlog.date', [$request->start_date, $request->end_date]);
        // }else{
        //     $visit->whereDate('visitlog.date', $currentDate);
        // }
        if($request->doctor_id){
            $visit->where('visitlog.doctor_id', $request->doctor_id);
        }

        $visit->orderBy('visitlog.id', 'DESC');
        $visit->groupBy('visitlog.id');
        $visit = $visit->get();

        // Initialize an array to store the visit count for each doctor
        $doctorVisitCounts = [];

        // Loop through visits and assign serial numbers
        foreach ($visit as $visi) {
            $doctorId = $visi->did;

        // Initialize the count if not already set
        if (!isset($doctorVisitCounts[$doctorId])) {
            $doctorVisitCounts[$doctorId] = count($visit)+1;
        }

        // Increment the count
            $doctorVisitCounts[$doctorId]--;

        // Assign the serial number
            $visi->sr_no = $doctorVisitCounts[$doctorId];
        }

        return $visit;
   }


