    public function get_medicine_list($visit_id){
        $medicines = DB::table('pres_final as d')

        // For combination brands (cc)
        ->leftJoin('drug_comb_brand_index as cc', function ($join) {
            $join->on('d.brand_id', '=', 'cc.id')
                 ->where('d.d_type', '=', 'cc');
        })

        // For single brands (ss)
        ->leftJoin('drug_brand_index as ss', function ($join) {
            $join->on('d.brand_id', '=', 'ss.id')
                 ->where('d.d_type', '=', 'ss');
        })

        // Join composition table ONLY for ss
        ->leftJoin('drug_compositions as dc', function ($join) {
            $join->on('ss.composition_id', '=', 'dc.id');
        })

        ->select(
            'd.*',
            DB::raw("CASE
                        WHEN d.d_type = 'cc' THEN cc.brand_name
                        WHEN d.d_type = 'ss' THEN ss.brand_name
                        ELSE NULL
                    END as name"),

            DB::raw("CASE
                        WHEN d.d_type = 'cc' THEN cc.composition
                        WHEN d.d_type = 'ss' THEN dc.composition
                        ELSE NULL
                    END as formulation")
        )

        ->where('d.visit_table_id', $visit_id)
        ->orderBy('d.id', 'asc')
        ->get();

        return $medicines;

        // foreach($medicines as $r){
        //     //  $r->formulation1 = $this->get_formulation($r->brand_id, $r->d_type);
