      public function get_template_medicine_list($temp_id){
            $medicines = DB::table('pres_template as d')
                        ->leftJoin('drug_comb_brand_index as cc', function ($join) {
                            $join->on('d.brand_id', '=', 'cc.id')
                                ->where('d.d_type', '=', 'cc');
                        })
                        ->leftJoin('drug_brand_index as ss', function ($join) {
                            $join->on('d.brand_id', '=', 'ss.id')
                                ->where('d.d_type', '=', 'ss');
                        })
                        ->select(
                            'd.*',
                            DB::raw("CASE
                                        WHEN d.d_type = 'cc' THEN cc.brand_name
                                        WHEN d.d_type = 'ss' THEN ss.brand_name
                                        ELSE NULL
                                    END as name")
                        )
                        // ->having('name', 'LIKE', "%{$query}%")
                        ->where('template_id', $temp_id)
                        // ->groupBy('d.brand_id')
                        ->orderBy('d.id', 'asc')
                        ->get();

                        return $medicines;
        }

   public function get_q_medicine_list($visit_id, $doctor_id){
        $q_medicines = DB::table('doc_drug_used_brands as d')
                        ->leftJoin('drug_brand_index as ss', function ($join) {
                            $join->on('d.brand_id', '=', 'ss.id');
                        })
                        ->select(
                            'd.*',
                            DB::raw("ss.composition as formulation"),
                            DB::raw("ss.brand_name as name"),
                        )
                        // ->having('name', 'LIKE', "%{$query}%")
                        ->where('d.doctor_id', $doctor_id)
                        // ->groupBy('d.brand_id')
                        ->orderBy('d.id', 'asc')
                        ->get();


        return $q_medicines;
   }



    public function discharge_summary_v2(Request $request, $id, $t_id=null){

         $org_id = Auth()->user()->org_id;

        $visit =  $this->ipd_patient_list($request);



           $visit_id = $id; // $visits[0]->id;
            $v = Visitlog::where('id', $visit_id)->select('doctor_id as did')->first();

            $did = $v->did;

           $medicines = $this->get_medicine_list($visit_id);

           $q_medicines = $this->get_q_medicine_list($visit_id, $did);

           $patient = Patient::join('visitlog', 'visitlog.patient_id', '=', 'pi.id')
                                ->leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                                ->select('pi.*', 'visitlog.doctor_id',
                                            'doctor_db.name as doctor_name',
                                            'doctor_db.key_spec',
                                            'visitlog.fud','visitlog.edit_lock',
                                            'doctor_specialities.id as spid',
                                            'doctor_db.id as did',
                                            'visitlog.ad2',
                                            'visitlog.dd2',
                                            'visitlog.at1',
                                            'visitlog.dt1',
                                            'visitlog.visit_status',
                                            'visitlog.created_at'
                                )
                                ->where('visitlog.id', $visit_id)
                                ->first();

            $context = FacadesRoute::currentRouteName();
            $lock = $this->isPageLocked($visit_id,$context);

            $vcd = VisitClinicalData::where('visit_id', $visit_id)->where('context',$context)->first();
            if (!$vcd) {
                $vcd = VisitClinicalData::create(['visit_id' => $visit_id, 'others' => '{}', 'context' => $context]);
            }


           // Decode the clinical data safely
           $formData = is_string($vcd->others ?? '') ? json_decode($vcd->others, true) : [];

           $groupedData = "";
           $vitals = Vitals::where('visit_id', $visit_id)->first();
           if(is_null($vitals)){
               $bp = [];
               $pulse = [];
               $investigation = [];

           }else{
               $bp = json_decode($vitals->bp, true) ?? [];
               $pulse = json_decode($vitals->pulse, true) ?? [];
               $investingation = json_decode($vitals->investigation, true) ?? [];
               $bp = end($bp);
               $pulse = end($pulse);
               $investigation = $investingation;

               $groupedData = collect($investigation)
                               ->sortByDesc('inv_date') // Sort by inv_date in descending order
                               ->groupBy('inv_date');

              // Initialize an array to track columns with non-null values
               $nonNullColumns = [];

               // Check each field across all rows to determine if it contains a non-null value
               foreach ($groupedData as $date => $items) {
                   foreach ($items as $item) {
                       foreach ($item as $key => $value) {
                           if ($value !== null) {
                               $nonNullColumns[$key] = true; // Mark column as having a non-null value
                           }
                       }
                   }
               }

               // Now, filter out columns where all values are null
               $groupedData = $groupedData->map(function ($items) use ($nonNullColumns) {
                   return $items->map(function ($item) use ($nonNullColumns) {
                       // Only return the fields that are marked as having a non-null value
                       return collect($item)->filter(function ($value, $key) use ($nonNullColumns) {
                           return isset($nonNullColumns[$key]);
                       })->toArray();
                   });
               });
               // dd($groupedData);
           }


           $investigation = end($investigation);

           $dynamic_comments =  $this->get_clinical_comments($patient->did, $context);


           $templates = $this->get_templates($patient->did, $context);

              // get all doctor with same speciality
                $doctorIds = Doctor_db::where('key_spec', $patient->key_spec)
                                    ->pluck('id')
                                    ->toArray();

                $templates = Template::whereIn('user_id', $doctorIds)->where('context',$context)->get();

                if($t_id){
                    $template = Template::where('id', $t_id)->first();
                    if($template){
                        $formData = json_decode($template->template, true);
                    }
                }

                $disdate = \App\Cache\HospitalSettingCache::getStatus((int)($org_id ?? 0), 'update_discharge_date');


                $hv = \App\Cache\HospitalSettingCache::get((int)(auth()->user()->org_id ?? 0), 'discharge_summary_print', 'v1');

                $pres_manual = PresManual::where('visit_table_id', $visit_id)->get();


