    public function print_pres_urology(Request $request, $id){


            $visit = Visitlog::join('pi', 'pi.id', '=', 'visitlog.patient_id')
                            ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                            ->select('visitlog.*', 'pi.prefix','pi.Fname','pi.age','pi.dob','pi.sex',
                                    'pi.Lname',
                                    'pi.Fathername',
                                    'pi.spousename',
                                    'pi.address',
                                    'doctor_db.name as doctor_name','pi.mobile_no',
                                    'doctor_specialities.name as sp_name',
                                    'doctor_db.id as doctor_id',
                                    'doctor_db.qualification as doctor_qualification',
                                    'doctor_db.medical_reg_no as medical_reg_no',
                                    'doctor_db.doc_stamp',
                                    'pi.id as uhid','pi.id as ageUhid')
                            ->where('visitlog.id', $id)
                            ->first();


            $vcd = null;
            if ($request->context) {
                $vcd = VisitClinicalData::leftJoin('users', 'users.id', '=', 'visit_clinical_data.approved_by')
                                            ->select(
                                                'visit_clinical_data.*',
                                                'users.first_name',
                                                'users.last_name',
                                                'users.emp_code'
                                            )
                                            ->where('visit_id', $id)->where('context', $request->context)->first();
            }
            if (!$vcd) {
                $vcd = VisitClinicalData::leftJoin('users', 'users.id', '=', 'visit_clinical_data.approved_by')
                                            ->select(
                                                'visit_clinical_data.*',
                                                'users.first_name',
                                                'users.last_name',
                                                'users.emp_code'
                                            )
                                            ->where('visit_id', $id)->latest('updated_at')->first();
            }

            if (!$vcd) {
                $vcd = VisitClinicalData::create(['visit_id' => $id, 'others' => '{}']);
            }

            // Decode the clinical data safely
            $data = is_string($vcd->others ?? '') ? json_decode($vcd->others, true) : [];

          $medicines = $this->get_medicine_list($id);

         $pres_manual = PresManual::where('visit_table_id', $id)->get();



        // dd($medicines);
            if($visit->fud != null){

            $date = Carbon::parse($visit->fud);

            $formattedDate = $date->format('l d/m/Y');

            // Get the current date
            $currentDate = Carbon::now();

            // Calculate the difference in days
            $dayDifference = $currentDate->diffInDays($date)+1;

            // Determine if the difference is past or future
            if ($date->greaterThan($currentDate)) {
                $differenceText = "After {$dayDifference} Days";

                $followup_date = "{$formattedDate} {$differenceText}";
            } else {
                $differenceText = "Before {$dayDifference} Days";
                $followup_date = "";
            }
            // $differenceText = '';

            // Combine the final output

        }else{
            $followup_date = '';
        }

            $rawHeader = $request->header ?: $request->print_header;
            $header = in_array(strtolower((string)$rawHeader), ['with_header', 'true', '1', 'yes', 'on'], true) ? 'true' : 'false';

            $vitals = Vitals::where('visit_id',$visit->id)->first();
            if(is_null($vitals)){
                $bp = [];
                $pulse = [];
            }else{
                $bp = json_decode($vitals->bp, true) ?? [];
                $pulse = json_decode($vitals->pulse, true) ?? [];
                $bp = end($bp);
                $pulse = end($pulse);
            }

            // return view('admin.pdf.clinical.prescription', compact('visit', 'data', 'medicines', 'followup_date', 'header'));

            if(in_array($vcd->context,['patient.dental_notes', 'v2.dental.notes']) || str_contains(strtolower($vcd->context ?? ''), 'dental')){
                return view('admin.pdf.clinical.dental_prescription', compact('visit','vcd', 'data', 'medicines','pres_manual', 'followup_date', 'header', 'bp', 'pulse', 'vitals'));
            }

            if(in_array($vcd->context,['clinical.general_v2','clinical.general_v3','clinical.general_v4', 'v2.general.notes']) || str_contains(strtolower($vcd->context ?? ''), 'general'))
            {
                return view('admin.pdf.clinical.print_general_prescription_v2', compact('visit','vcd', 'data', 'medicines','pres_manual', 'followup_date', 'header', 'bp', 'pulse', 'vitals'));
            }
            if($vcd->context == 'clinical.er_note'){

                $vitals = Vitals::where('visit_id',$visit->id)->where('context','clinical.er_note')->get();
                return view('admin.pdf.clinical.print_er_note', compact('visit','vcd', 'data', 'medicines','pres_manual', 'followup_date', 'header', 'bp', 'pulse', 'vitals'));
            }
            $presView = json_decode(\App\Helpers\HospitalHelper::getSettingData($vcd->context,'print_prescription'), true);

            if($presView['view']??false)
            {
                return view($presView['view'], compact('visit','vcd', 'data', 'medicines','pres_manual', 'followup_date', 'header', 'bp', 'pulse', 'vitals'));
            }

            return view('admin.pdf.clinical.urology_prescription', compact('visit','vcd', 'data', 'medicines','pres_manual', 'followup_date', 'header', 'bp', 'pulse', 'vitals'));

    }


