    public function start_patient(Request $request){

        $org_id = Auth::user()->org_id;


        $doctors = HospitalDoctor::join('doctor_db','doctor_db.id','=','org_doc_index.doc_id')
                                    ->select('doctor_db.name', 'doctor_db.id')
                                    ->where('doctor_db.active',1)
                                    ->where('org_doc_index.org_id',$org_id)
                                    ->where('org_doc_index.active',1)
                                    ->orderBy('name','ASC')
                                    ->get();

        //  $doctors = DoctorCache::all($org_id);

       $patient = Patient::join('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                            ->select('pi.id',
                                        'pi.id',
                                        'pi.dob',
                                        'pi.prefix',
                                        'pi.Fname',
                                        'pi.Lname',
                                        'pi.sex',
                                        'pi.dob',
                                        'pi.age as p_age',
                                        'pi.mobile_no',
                                        'health_insurance_agen.insurance_agen')
                            ->where('pi.hospital_id', $org_id)
                            ->where('pi.id', $request->uhid)->first();

        if(!$patient){
            return response()->json(['status'=>'error','message'=>'Patient not found']);
        }

        // $v = Visitlog::where('hospital_id',$org_id)->where('patient_id',$request->uhid)->where('visit_status',1)->first();
        // if($v){
        //     return response()->json(['status'=>'error','message'=>'Patient currently admitted.']);
        // }

        // check for Draft Bill
       $patientBill = PatientBilling::join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                            ->join('pi','pi.id','=','visitlog.patient_id')
                                            ->join('doctor_db','doctor_db.id','=','visitlog.doctor_id')
                                            ->select('patient_billing.*',
                                                    'patient_billing.id as bill_id',
                                                    'doctor_db.name as doctor_name',
                                                    'visitlog.doctor_id',
                                                    'visitlog.visit_type'
                                                    )
                                            ->where('patient_billing.status',0)
                                            ->where('visitlog.patient_id', $request->uhid)
                                            ->where('visitlog.hospital_id', $org_id)
                                            ->whereDate('patient_billing.updated_at', Carbon::today())
                                            ->get();

        $totalDraftBill = $patientBill->count();

        // check for if visit already exits
         $doctorId = Visitlog::where([
                                        ['patient_id', $request->uhid],
                                        ['hospital_id', $org_id]
                                    ])
                                    ->where('visit_status', 0)
                                    ->whereDate('created_at', Carbon::today())
                                    ->orderBy('id', 'desc')
                                    ->value('doctor_id');



       return response()->json(['doctors'=>$doctors,'patient'=>$patient,'draftBIll'=>$patientBill,'totalDraftBill'=>$totalDraftBill, 'doctor_id'=>$doctorId]);
    }

    public function open_draft_bill(Request $request, $id){

        $user = Auth::user();
        $org_id = $user->org_id;

        $patientBill = PatientBilling::join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                            ->join('pi','pi.id','=','visitlog.patient_id')
                                            ->join('users','users.id','=','patient_billing.created_by')
                                            ->select('patient_billing.*',
                                                        'patient_billing.id as bill_no',
                                                        'pi.i_cover',
                                                        'users.first_name as staff_first_name',
                                                        'users.last_name as staff_last_name',
                                                        'visitlog.visit_type',
                                                        'pi.is_registered',
                                                        'pi.id as patient_id',
                                                        'visitlog.doctor_id'
                                                    )
                                            ->where('patient_billing.id',$id)
                                            ->first();
        // $patient = Patient::where('id',$patient_id)->first();

        $genBill = PatientGenBill::join('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                    ->select('patient_gen_bill.*','hospital_services.service')
                                    ->where('bill_id',$id)
                                    ->where('patient_gen_bill.is_deleted', 0)
                                        ->where(function($q) {
                                            $q->where('patient_gen_bill.is_cancelled', 0)
                                            ->orWhereNull('patient_gen_bill.is_cancelled');
                                        })
                                    ->get();

        $payment = BillingPaymentType::where('bill_id',$id)
                                    ->select(
                                        'payment_mode',
                                        DB::raw('SUM(amount) as amount'),
                                    )
                                    ->groupBy('payment_mode')
                                    ->get()
                                    ->pluck('amount','payment_mode')
                                    ->toArray();


        $services=HospitalService::leftJoin('hospital_services','hospital_services.id','=','hospital_services_index.service')
                                    ->leftJoin('hospital_service_charges','hospital_service_charges.service','=','hospital_services_index.service')
                                    ->where('hospital_services_index.hospital_id',$org_id)
                                    ->where('hospital_services_index.active',1)
                                    ->where('hospital_service_charges.insurance',$patientBill->i_cover)
                                    ->where('hospital_service_charges.hospital_id',$org_id)
                                    ->select('hospital_services.service',
                                                'hospital_services.spec_id',
