                         'comments',
                         'templates',
                         'vitals',
                         'bp',
                         'pulse',
                         'investigation'
                         );
       return view('admin.patient.discharge_summary.opd_discharge_summary')->with($data);
   }





public function saveopddischarge(Request $req)
{
    $user = Auth::user();
    $org_id = $user->org_id;


    // Define the unique identifier
    $visit_id = $req->v_id;

    // return $visit_id;

    // $record = Ipd_details::where('id', $ipd_patient_id)->first();

    $no_of_days = $req->no_of_days;
    $follow_up_on_date = $req->follow_up_on_date;

    if ($follow_up_on_date) {
        $folloup_date = date('Y-m-d', strtotime($follow_up_on_date));
    }
    if($no_of_days){
        $folloup_date = date('Y-m-d', strtotime($follow_up_on_date. ' + '.$no_of_days.' days'));
    }

    Visitlog::where('id', $visit_id)
            ->update([
                'ad2' => $req->addm_date ?: null,
                'at1' => $req->addm_time ?: null,
                'dd2' => $req->dis_date ?: null,
                'dt1' => $req->dis_time ?: null,
                'fud' => $folloup_date ?: null
            ]);


        // save data -- discharge summary

        $vcd = VisitClinicalData::where('visit_id', $visit_id)->first();

        if (!$vcd) {
            // If no record exists, create a new one
            $vcd = new VisitClinicalData();
            $vcd->visit_id = $visit_id; // Assign the visit ID
            $existingData = []; // Start with an empty array
        } else {
            // If record exists, decode existing 'others' JSON data
            $existingData = is_string($vcd->others ?? '')
                            ? json_decode($vcd->others, true)
                            : [];
        }



        $textbox = $req->free_textbox;


        foreach ($textbox as $key => $value) {

            $existingData[$key] = [
                "value" => $value,
                "updated_at" => now()->toDateTimeString()
            ];

                // $words = explode(',', $value);
                // $lastWord = trim(end($words));
                $this->add_comment($visit_id,$value,$key);

        }

        // return $existingData;

        // Update 'others' column
        $vcd->others = json_encode($existingData, JSON_PRETTY_PRINT);
        $vcd->save();

        // return $vcd;

// ----------------------------------Save Medicines ------------------------------



$medicines = json_decode($req->medicine_table, true) ?? [];
$lenght = count($medicines);

Pres_final::where('visit_table_id', $visit_id)->delete();

for($i = 0; $i < $lenght-1; $i++){

    $medicine = $medicines[$i]['column_2'];    // 105|ss

    $brand_id = explode('|', $medicine)[0]; // 105
    $source = explode('|', $medicine)[1]; // ss

    //   return $medicines[$i]['column_1'];

    $mark = ($medicines[$i]['column_1'])? "true":"false";

    $pf = new Pres_final;
    $pf->save_type = 'p';
    $pf->visit_table_id = $req->v_id;
    $pf->brand_id = $brand_id;
    $pf->d_type = $source;
    $pf->nc = 'false';
    $pf->vic = $mark;
    $pf->rs = 0;
    $pf->it = $medicines[$i]['column_3'];
    $pf->spl_inst = $medicines[$i]['column_4'];
    $pf->dt = $medicines[$i]['column_5'];
    $pf->save();


    if($source === 'ss'){
        $b =  Drug_brand::find($brand_id);

        $dose_id = $b->dose_id ?? '';
        $drug_id = $b->drug_id ?? '';
        $form_id = $b->form_id?? '';
    }else{
        $b = DrugCombBrand::find($brand_id);
        $dose_id = $b->comb_dose_id_entry ??'';
        $drug_id = $b->comb_id??'';
        $form_id = $b->form_id??'';
    }

    $this->add_medicine_to_doc_fav_brand($visit_id,$brand_id,$source,$mark);

    $this->add_comment($visit_id,$medicine,'medicine');
    if($b){
        $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $medicines[$i]['column_3'],$source,'it' );
        $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $medicines[$i]['column_4'],$source,'spl_inst' );
    }



}


return response()->json(['status'=>'success', 'message'=>'Discharge Summary Saved Successfully!']);

    // toastr()->success('Discharge Summary Saved Successfully!');
    // return redirect()->back();
}



public function opd_discharge_print($vid)
{

        $visitStatus = Visitlog::where('id', $vid)->value('visit_status');

        // Step 2: Build the query dynamically
        $patientQuery = Visitlog::join('pi', 'pi.id', '=', 'visitlog.patient_id')
                                ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                ->join('doctor_specialities', 'doctor_specialities.id', '=', 'doctor_db.key_spec')
                                ->select(
                                    'visitlog.*',
