                                    'doctor_specialities.name as sp_name',
                                    'health_insurance_agen.insurance_agen as insurance',

                                );

        // Step 3: Add the dynamic join based on visit_status
        if ($visitStatus == 0) {
            $patientQuery->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover');
        }


        // Step 4: Apply the filter and get the first record
        $patient = $patientQuery->where('visitlog.id', $vid)->first();

        // dd($patient);

    $uhid = $patient->uhid;

    $visit = Visitlog::join('pi','pi.id','=','visitlog.patient_id')
                        ->join('doctor_db','doctor_db.id','=','visitlog.doctor_id')
                        ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                        ->select('doctor_db.id as did','doctor_db.name as dname','doctor_specialities.name as spname',
                                'visitlog.dd2','visitlog.ad2',
                                'visitlog.at1','visitlog.dt1',
                                )
                        ->where('visitlog.id',$vid)->first();

//   $insu = HealthInsurance::find($patient->insurance);
//   $dischargedata = IPDDischargeSummary::where('ipd_patient_id',$id)->first();
//   $meddata = IPDMedicine::
//                     join('drug_brand_index','drug_brand_index.id','=','ipd_medicine.medicines')
//                     ->select('ipd_medicine.*','drug_brand_index.brand_name')
//                     ->where('ipd_patient_id',$vid)->get();

    $vcd = VisitClinicalData::where('visit_id', $vid)->first();
    $diagVersion = 'v1'; // default

    if ($vcd && !empty($vcd->diag_version)) {
        $diagVersion = $vcd->diag_version;
    }
    if (!$vcd) {
        $vcd = new VisitClinicalData();
        $dischargedata = []; // Start with an empty array
    } else {
        $dischargedata = is_string($vcd->others ?? '')
                        ? json_decode($vcd->others, true)
                        : [];
    }

$medicines = DB::table('pres_final as d')
                ->leftJoin('drug_comb_brand_index as cc', function ($join) {
                    $join->on('d.brand_id', '=', 'cc.id')
                        ->where('d.d_type', '=', 'cc');
                })
                ->leftJoin('drug_brand_index as ss', function ($join) {
                    $join->on('d.brand_id', '=', 'ss.id')
                        ->where('d.d_type', '=', 'ss');
                })
                ->select(
                    'd.*',
                    DB::raw("CASE
                                WHEN d.d_type = 'cc' THEN cc.brand_name
                                WHEN d.d_type = 'ss' THEN ss.brand_name
                                ELSE NULL
                            END as name")
                )
                // ->having('name', 'LIKE', "%{$query}%")
                ->where('visit_table_id', $vid)
                // ->groupBy('d.brand_id')
                ->orderBy('d.id', 'asc')
                ->get();


        $vitals = Vitals::where('visit_id', $vid)->first();
        if(is_null($vitals)){
            $bp = [];
            $pulse = [];
            $investigation = [];
        }else{
            $bp = json_decode($vitals->bp, true) ?? [];
            $pulse = json_decode($vitals->pulse, true) ?? [];
            $investingation = json_decode($vitals->investigation, true) ?? [];
            $bp = end($bp);
            $pulse = end($pulse);
            $investigation = $investingation;

            $groupedData = collect($investigation)->groupBy('inv_date');

           // Initialize an array to track columns with non-null values
            $nonNullColumns = [];

            // Check each field across all rows to determine if it contains a non-null value
            foreach ($groupedData as $date => $items) {
                foreach ($items as $item) {
                    foreach ($item as $key => $value) {
                        if ($value !== null) {
                            $nonNullColumns[$key] = true; // Mark column as having a non-null value
                        }
                    }
                }
            }

            // Now, filter out columns where all values are null
            $groupedData = $groupedData->map(function ($items) use ($nonNullColumns) {
                return $items->map(function ($item) use ($nonNullColumns) {
                    // Only return the fields that are marked as having a non-null value
                    return collect($item)->filter(function ($value, $key) use ($nonNullColumns) {
                        return isset($nonNullColumns[$key]);
                    })->toArray();
                });
            });
            // dd($groupedData);
        }



// dd($medicines);
    $data = [
        'uhid' => $patient->uhid,
        'age' => $patient->age,
        'gender' => $patient->sex,
        'prefix' => $patient->prefix,
        'fname' => $patient->Fname,
        'lname' => $patient->Lname,
        'patient_mobile' => $patient->mobile_no,
        'doc_name' => $patient->doc_name,
        'sp_name' => $patient->sp_name,
        'visit' => $visit,
        'insurance' => $patient->insurance,
        'dischargedata' => $dischargedata,
        'ipd_no' => $patient->ipd_no,
        // 'allergies' => $allergies, // Pass allergies to the view
        'medicines' => $medicines,
        'vitals' => $vitals,
        'bp' => $bp,
        'pulse' => $pulse,
        'investigation' => $investigation,
        'groupedData' => $groupedData??[]
        // 'uniqueKeys' => $uniqueKeys
    ];
    // dd($invByDate);
    extract($data);

    $view = view('admin.pdf.ipd_discharge_summary', compact(
                                                        'uhid',
                                                        'age',
                                                        'gender',
                                                        'prefix',
                                                        'fname',
                                                        'lname',
                                                        'patient_mobile',
                                                        'visit',
                                                        'insurance',
                                                        'dischargedata',
                                                        // 'allergies',
                                                        'medicines',
                                                        'doc_name',
                                                        'sp_name',
                                                        'bp',
                                                        'pulse',
                                                        'vitals',
                                                        'investigation',
                                                        'groupedData',
                                                        'ipd_no',
                                                        'vcd',
                                                        'diagVersion'
                                                        // 'uniqueKeys',
                                                        // 'groupedByDate'
                                                    ))->render();
    return $view;

}



    public function suggestions(Request $request){
        $query = $request->input('query');
        $suggestions = Patient::where('referring_doctor', 'LIKE', "%{$query}%")
            ->take(10)
            ->pluck('referring_doctor');

        return response()->json($suggestions);
    }

    public function clinical_comments(Request $request){
        $query = $request->input('query');
        $suggestions = ClinicalComment::where('comment', 'LIKE', "%{$query}%")
                                        ->where('user_id',Auth::user()->id)
                                        ->take(10)
                                        ->pluck('comment');

        return response()->json($suggestions);
    }

    public function prepareOpdBillingVisit($patientId, $doctorId, $charges, $orgId, $addVisit, $refBy = null)
    {
        // V2 has already selected/locked the encounter context; legacy callers retain same-day reuse.
        return $this->create_visit($patientId, $doctorId, $charges, $orgId, $addVisit, null, $refBy, false);
    }

    private function create_visit($patient_id, $doctor_id,$charges, $org_id, $add_visit, $visit_date = null, $ref_by = null, $reuseExisting = true){
        try{

            // Set default date at runtime
            if (!$visit_date) {
                $date = Carbon::today()->toDateString();
                $visit_time = Carbon::now();
            }else{
                $date = date('Y-m-d', strtotime($visit_date));
                $visit_time = date('H:i:s', strtotime($visit_date));
            }

            $visit_id = $reuseExisting ? $this->check_if_patient_already_visit_for_today($patient_id, $doctor_id, $org_id, $date) : null;
           // dd($visit_date, $visit_time,$visit_id);
            if($visit_id){
                if (!empty($ref_by) && $ref_by !== '__new__') {
                    Visitlog::where('id', $visit_id)->update(['ref_by' => $ref_by]);
                }
                return $visit_id;
            }

            $visit = new Visitlog;
            $visit->patient_id = $patient_id;
            $visit->hospital_id = $org_id;
            $visit->doctor_id = $doctor_id;
            $visit->ch = $charges;
            if (!empty($ref_by) && $ref_by !== '__new__') {
                $visit->ref_by = $ref_by;
            }

           // $currentDate = Carbon::today()->toDateString();
            $date = $date." 00:00:00";
            $visit->date = $date;

            $currentTime = $visit_time;
            $visit->visit_time = $currentTime;

            $visit->last_update= time();

            // visit id is visit no. for selected doctor in this hospital
            // fetch last visit no.
            $lastVisitNo = Visitlog::where([
                                            ['patient_id',$patient_id],
                                            ['hospital_id',$org_id],
                                            ['doctor_id',$doctor_id]]
                                        )
                                        ->latest('created_at')
                                        ->value('visit_id');


            // Increment the `visit_id` if it exists; otherwise, start with 1
            $visit->visit_id = $lastVisitNo ? $lastVisitNo + 1 : 1;

            // is_visited is for billing status
            $visit->is_visited =0;
            $visit->visit_status = 0;

            if ($visit_date) {
                $visit->created_at = $visit_date;
            }

            $visit->created_by = auth()->user()->id;
            $visit->visit_type = ($add_visit) ? null : 'non-clinical';
            $visit->save();

            $new_visit_id = $visit->id;


        // insert id to gen_pres_log_1 table
            $gen_pres_log = new Gen_pres_log_1();
            $gen_pres_log->visit_table_id = $new_visit_id;
            $gen_pres_log->save();

            // fetch second last record
            $second_last_visit_data = Visitlog::where([['doctor_id',$doctor_id],['patient_id',$patient_id],['hospital_id',$org_id]])->orderBy('id','desc')->skip(1)->take(1)->first();
            if($second_last_visit_data){
                $this->copy_old_visit_data_to_new($new_visit_id, $second_last_visit_data->id);
            }


            return $new_visit_id;
        }catch(\Exception $e){
            DB::rollBack();
            \Log::error('create_visit failed: ' . $e->getMessage(), ['trace' => $e->getTraceAsString()]);
            return response()->json(['status' => 'error', 'message' => $e->getMessage()], 500);
        }
    }


    public function gen_opd_bill(Request $request)
    {

        $user = Auth::user();
        $org_id = $user->org_id;

     

        $hasBillingPermission = $user->can('module-permission', ['opd_billing', 'can_create']) || $user->can('module-permission', ['opd_billing', 'can_update']);
      //  $hasVisitPermission = $user->can('module-permission', ['opd_visits', 'can_create']);

        if (!$hasBillingPermission) {
            return response()->json(['status' => 'error', 'message' => 'You do not have permission to create OPD visits or bills.'], 403);
        }

        if ($request->action == 'edit_bill' && !$user->can('module-permission', ['opd_billing', 'can_update'])) {
            return response()->json(['status' => 'error', 'message' => 'You do not have permission to edit bills. Billing update permission is required.'], 403);
        }

        if ($request->action == 'edit_bill' && !empty($request->bill_no)) {
            $existingBill = PatientBilling::where('id', $request->bill_no)->first();
            if ($existingBill) {
                if ($existingBill->is_cancelled == 1) {
                    return response()->json(['status' => 'error', 'message' => 'Cancelled bills cannot be edited.'], 422);
                }
                $hasRefunds = DB::table('refund_remarks')
                    ->where(function($q) use ($existingBill) {
                        $q->whereRaw('JSON_CONTAINS(bill_ref_id, ?)', [json_encode((string)$existingBill->id)])
                          ->orWhereRaw('JSON_CONTAINS(bill_ref_id, ?)', [json_encode((int)$existingBill->id)])
                          ->orWhere('bill_id', $existingBill->id);
                    })
                    ->where('status', 'issued')
                    ->exists();
                if ($hasRefunds) {
                    return response()->json(['status' => 'error', 'message' => 'Bills with refunds cannot be edited.'], 422);
                }
            }
        }

        if (!$hasBillingPermission) {
            if ($request->action == 'edit_bill' || $request->action2 == 'gen_bill_from_draft') {
                return response()->json(['status' => 'error', 'message' => 'You do not have permission to edit or generate bills. Billing permission is required.'], 403);
            }

            if (empty($request->add_visit)) {
                return response()->json(['status' => 'error', 'message' => 'You do not have permission to create bills without a visit. Billing permission is required.'], 403);
            }

            if ($request->filled('service_id') && is_array($request->service_id)) {
                $allowedFlags = ['registration_charge', 'consultation_charge', 'doctor_consultation'];
                $allowedServiceIds = HospitalSer::whereIn('flag', $allowedFlags)->pluck('id')->toArray();
                $nonEmptyServices = array_values(array_filter($request->service_id));
                $extraServices = array_diff($nonEmptyServices, $allowedServiceIds);

                if (count($extraServices) > 0) {
                    return response()->json(['status' => 'error', 'message' => 'You do not have permission to add services to the bill. Billing permission is required.'], 403);
                }
            }
        }

     try{
        $patientId = $request->patient_id;  
        $pi = Patient::find($patientId);  

        $patient_id = $pi->id;
        $doctor_id = $request->doctor_id;
        $charges = $request->doctor_charges??0;
        $add_visit = $request->add_visit;
        $preparedVisit = null;
        if ($request->filled('prepared_visit_id')) {
            $preparedVisit = Visitlog::where('hospital_id', $org_id)
                ->where('patient_id', $patient_id)->where('doctor_id', $doctor_id)
                ->where('visit_status', 0)->where('emergency', 0)
                ->find($request->prepared_visit_id);
            if (!$preparedVisit || (int) $pi->hospital_id !== (int) $org_id) {
                return response()->json(['success' => false, 'message' => 'The prepared visit does not match this patient and doctor.'], 422);
            }
            if ($request->filled('bill_no') && !PatientBilling::whereKey($request->bill_no)->where('visit_id', $preparedVisit->id)->exists()) {
                return response()->json(['success' => false, 'message' => 'The bill does not belong to the prepared visit.'], 422);
            }
        }

        // --- Billing Validations ---
        $chargesArr = $request->charges ?? [];
        $qtyArr = $request->qty ?? [];
        $discountArr = $request->discountArr ?? [];

        $subtotal = 0;
        $totalItemDiscount = 0;

        if (is_array($chargesArr)) {
            foreach ($chargesArr as $i => $chg) {
                $c = (float)$chg;
                if ($c < 0) {
                    return response()->json(['status' => 'error', 'message' => 'Item rate cannot be negative.'], 422);
                }
                $q = isset($qtyArr[$i]) ? (float)$qtyArr[$i] : 1;
                if ($q < 0) {
                    return response()->json(['status' => 'error', 'message' => 'Item quantity cannot be negative.'], 422);
                }
                $gross = $c * $q;
                $subtotal += $gross;

                $d = isset($discountArr[$i]) ? (float)$discountArr[$i] : 0;
                if ($d < 0) {
                    return response()->json(['status' => 'error', 'message' => 'Discount cannot be negative.'], 422);
                }
                if ($d > ($gross + 0.001)) {
                    return response()->json(['status' => 'error', 'message' => 'Fixed/Cash discount can only be ₹0 to (Item Rate × Quantity).'], 422);
                }
                $totalItemDiscount += $d;
            }
        }

        $subAfterItemDisc = max(0, $subtotal - $totalItemDiscount);

        // Bill discount validation
        $billDiscount = (float)($request->discount ?? 0);
        if ($billDiscount < 0) {
            return response()->json(['status' => 'error', 'message' => 'Bill discount cannot be negative.'], 422);
        }

        if (!empty($request->discount_type) || $request->filled('discount_per')) {
            $discPer = (float)($request->discount_per ?? $request->discount ?? 0);
            if ($discPer < 0 || $discPer > 100) {
                return response()->json(['status' => 'error', 'message' => 'Percentage discount must be between 0% and 100%.'], 422);
            }
        } elseif ($billDiscount > ($subAfterItemDisc + 0.001) && $subAfterItemDisc > 0) {
            return response()->json(['status' => 'error', 'message' => 'Bill discount cannot exceed the payable subtotal.'], 422);
        }

        // Discount RBAC enforcement: opd_discount can_update
        $canGiveDiscount = $user->can('module-permission', ['opd_discount', 'can_update']);
        if (!$canGiveDiscount) {
            $hasItemDiscount = false;
            if (is_array($discountArr)) {
                foreach ($discountArr as $dVal) {
                    if ((float)$dVal > 0) {
                        $hasItemDiscount = true;
                        break;
                    }
                }
            }
            $hasBillDiscount = ($billDiscount > 0) || ((float)($request->discount_per ?? 0) > 0);

            $isDraftOperation = $request->filled('bill_no') && ($request->action == 'edit_bill' || $request->action2 == 'gen_bill_from_draft' || $request->action == 'save_as_draft');
            if ($isDraftOperation) {
                $existingBill = PatientBilling::where('id', $request->bill_no)->first();
                if ($existingBill) {
                    $prevBillDiscount = (float)($existingBill->discount ?? 0);
                    if ($billDiscount > ($prevBillDiscount + 0.01)) {
                        return response()->json(['status' => 'error', 'message' => 'You do not have permission to give or update bill discounts.'], 403);
                    }
                }
            } else {
                if ($hasItemDiscount || $hasBillDiscount) {
                    return response()->json(['status' => 'error', 'message' => 'You do not have permission to give discounts.'], 403);
                }
            }
        }

        $calcPayable = max(0, round($subAfterItemDisc - $billDiscount, 2));
        if ($calcPayable < 0 || (float)($request->total ?? 0) < 0) {
            return response()->json(['status' => 'error', 'message' => 'Final bill amount cannot be negative.'], 422);
        }

        // Payment mode amounts validation
        $totalPaid = 0;
        if (is_array($request->payment)) {
            foreach ($request->payment as $mode => $amt) {
                $a = (float)$amt;
                if ($a < 0) {
                    return response()->json(['status' => 'error', 'message' => 'Payment mode amount cannot be negative.'], 422);
                }
                if ($a > 0) {
                    $totalPaid += $a;
                }
            }
        }


        if($request->action == 'save_as_draft'){
            $status = 0;
            $bill_no = $request->bill_no ?? null;

            // Enforce: Patient can have only one draft per day per doctor
            $today = \Carbon\Carbon::today();
            if(!empty($bill_no)){
                // Verify that this draft bill belongs to the requested doctor
                $billDoctorMatch = PatientBilling::join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                    ->where('patient_billing.id', $bill_no)
                    ->when($preparedVisit, function ($q) use ($preparedVisit) { $q->where('visitlog.id', $preparedVisit->id); })
                    ->where('visitlog.doctor_id', $doctor_id)
                    ->exists();

                if(!$billDoctorMatch){
                    // bill_no was for another doctor, switch to this doctor's draft today if any, or null for new draft
                    $doctorDraft = PatientBilling::join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                        ->where('visitlog.hospital_id', $org_id)
                        ->when($preparedVisit, function ($q) use ($preparedVisit) { $q->where('visitlog.id', $preparedVisit->id); })
                        ->where(function ($q) use ($patient_id) {
                            $q->where('visitlog.patient_id', $patient_id)
                              ->orWhere('visitlog.patient_id', preg_replace('/[^0-9]/', '', (string)$patient_id));
                        })
                        ->where('visitlog.doctor_id', $doctor_id)
                        ->whereDate('patient_billing.created_at', $today)
                        ->where(function ($q) {
                            $q->whereNull('patient_billing.status')
                              ->orWhere('patient_billing.status', 0);
                        })
                        ->where(function ($q) {
                            $q->whereNull('patient_billing.is_cancelled')
                              ->orWhere('patient_billing.is_cancelled', 0);
                        })
                        ->orderBy('patient_billing.id', 'desc')
                        ->select('patient_billing.id')
                        ->first();

                    $bill_no = $doctorDraft ? $doctorDraft->id : null;
                    $request->merge(['bill_no' => $bill_no]);
                }
            } else if (!empty($patient_id) && !empty($doctor_id)) {
                // If bill_no was not passed, enforce 1 draft per day per doctor
                $existingDraft = PatientBilling::join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                    ->where('visitlog.hospital_id', $org_id)
                    ->when($preparedVisit, function ($q) use ($preparedVisit) { $q->where('visitlog.id', $preparedVisit->id); })
                    ->where(function ($q) use ($patient_id) {
                        $q->where('visitlog.patient_id', $patient_id)
                              ->orWhere('visitlog.patient_id', preg_replace('/[^0-9]/', '', (string)$patient_id));
                    })
                    ->where('visitlog.doctor_id', $doctor_id)
                    ->whereDate('patient_billing.created_at', $today)
                    ->where(function ($q) {
                        $q->whereNull('patient_billing.status')
                          ->orWhere('patient_billing.status', 0);
                    })
                    ->where(function ($q) {
                        $q->whereNull('patient_billing.is_cancelled')
                          ->orWhere('patient_billing.is_cancelled', 0);
                    })
                    ->orderBy('patient_billing.id', 'desc')
                    ->select('patient_billing.id')
                    ->first();

                if ($existingDraft) {
                    $bill_no = $existingDraft->id;
                    $request->merge(['bill_no' => $bill_no]);
                }
            }

            if(isset($bill_no) && !empty($bill_no)){

                if ($request->has('ref_by')) {
                    $targetVisitId = PatientBilling::where('id', $bill_no)->value('visit_id');
                    if ($targetVisitId) {
                        $refVal = (!empty($request->ref_by) && $request->ref_by !== '__new__') ? $request->ref_by : null;
                        Visitlog::where('id', $targetVisitId)->update(['ref_by' => $refVal]);
                    }
                }

                $res = $this->save_edited_bill($request, $status);

                $pdf_url = $this->generate_opd_bill($request, $bill_no);
                return response()->json(['message' =>"Draft Bill Updated Successfully", 'pdf_url' => $pdf_url, 'bill_id' => $bill_no, 'success' => true], 200);
            }

        }else
        if(($request->action == 'edit_bill') || ($request->action2 == 'gen_bill_from_draft')){
            $status = 1;

            // if update doctor setting is enabled
            if (auth()->user()->can('module-permission', ['update_visit_doctor', 'can_update'])) {

            $visit =  Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                        ->select('visitlog.id','visitlog.created_at as visit_date','visitlog.doctor_id')
                        ->where('patient_billing.id', $request->bill_no)
                        ->first();

                    if ($visit && !empty($doctor_id) && $doctor_id != $visit->doctor_id) {

                        $visit_date =  $visit->visit_date;

                        $visit_id = $this->create_visit(
                            $patient_id,
                            $doctor_id,
                            $charges,
                            $org_id,
                            $add_visit,
                            $visit_date,
                            $request->ref_by ?? null
                        );

                        if ($visit_id instanceof \Illuminate\Http\JsonResponse) {
                            return $visit_id;
                        }

                        $request->visit_id = $visit_id;
                    }
            }

            if ($request->has('ref_by')) {
                $targetVisitId = $request->visit_id ?? ($visit->id ?? null);
                if (!$targetVisitId && !empty($request->bill_no)) {
                    $targetVisitId = PatientBilling::where('id', $request->bill_no)->value('visit_id');
                }
                if ($targetVisitId) {
                    $refVal = (!empty($request->ref_by) && $request->ref_by !== '__new__') ? $request->ref_by : null;
                    Visitlog::where('id', $targetVisitId)->update(['ref_by' => $refVal]);
                }
            }

            $res = $this->save_edited_bill($request, $status);
            if ($res instanceof \Illuminate\Http\JsonResponse) {
                return $res;
            }

            $pdf_url = $this->generate_opd_bill($request,$request->bill_no);


            return response()->json(['message' =>"Bill Updated Successfully", 'pdf_url' => $pdf_url,'bill_id' =>$request->bill_no, 'success' => true], 200);
        }else
        {
            $status = 1;
        }


          $request->validate([
            'patient_id' => 'required',
            'doctor_id' =>'required',
            'add_visit' => 'required',
           ]);

            // create new visit and generate bill
            DB::beginTransaction();


            $discount_in = HospitalSetting::where('hospital_id',auth()->user()->org_id)
                    ->where('identifier','discount_in_cash_or_percentage')
                    ->first()->current_setting??'cash';


            $visit_id = $preparedVisit ? $preparedVisit->id : $this->create_visit($patient_id, $doctor_id, $charges, $org_id, $add_visit, null, $request->ref_by ?? null);

            if ($visit_id instanceof \Illuminate\Http\JsonResponse) {
                return $visit_id;
            }

            $request->visit_id = $visit_id;

            if ($request->has('ref_by')) {
                $refVal = (!empty($request->ref_by) && $request->ref_by !== '__new__') ? $request->ref_by : null;
                Visitlog::where('id', $visit_id)->update(['ref_by' => $refVal]);
            }

            $visitPi = null;
            if (!empty($visit_id) && is_numeric($visit_id)) {
                $visitPi = Visitlog::join('pi', 'pi.id', '=', 'visitlog.patient_id')
                                ->select('i_cover')
                                ->where('visitlog.id', '=', $visit_id)
                                ->first();
            }
            $i_cover = $visitPi ? $visitPi->i_cover : ($pi->i_cover ?? 0);

            Patient::where('id', $patient_id)->update(['is_registered' => 1]);

            $lastBill = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                                    ->select('visitlog.visit_status','patient_billing.*')
                                    ->where('visitlog.visit_status',0)
                                    ->orderBy('patient_billing.id','DESC')
                                    ->first();
            $receipt_no = ($lastBill && $lastBill->receipt_no) ? $lastBill->receipt_no + 1 : 1;

            if(isset($request->bill_no)){
                $bill = PatientBilling::find($request->bill_no);
            }else{
                $bill = new PatientBilling;
                $bill->receipt_no = $receipt_no;
                $bill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($visit_id);
            }

            $bill->i_cover = $i_cover;
            $bill->visit_id = $visit_id;

            if($discount_in == 'cash'){
                $bill->discount = $request->input('discount');
            }else{
                $bill->discount = $request->input('discount');
                $bill->discount_per = $request->input('discount_per');
            }
            $bill->status = $status;
            $bill->claim_id = $request->input('claim_id');

            $bill->discount = $request->discount??0;
            if($request->discount != null){
                $bill->discount_type = ($request->discount_type) ? 'percentage' : 'cash';

                if($request->discount_type){
                    $discount_name = BillDiscount::find($request->discount_select)->name ??'';
                    $bill->discount_name = $discount_name;
                }

                $bill->discount_auth_by = $request->discount_auth_by;
            }
            $bill->created_by = auth()->user()->id;

              if ($request->hasFile('discount_attachment')) {
                    $file = $request->file('discount_attachment');
                    \App\Services\SecureFileService::validate($file, ['pdf', 'jpg', 'jpeg', 'png', 'webp', 'doc', 'docx'], 5120);

                    $cleanOriginalName = preg_replace('/[^a-zA-Z0-9_\.-]/', '_', $file->getClientOriginalName());
                    $filename = time() . '_' . $cleanOriginalName;

                    $destination = public_path('assets/files/attachments');
                    if (!file_exists($destination)) {
                        @mkdir($destination, 0755, true);
                    }
                    $file->move($destination, $filename);

                    $bill->attachment = $filename;
                    $bill->save();
                }

            $bill->remarks = $request->remarks ?? '';
            $bill->save();

            $b_id = $bill->id;
            // dd($bill->toArray());

            foreach($request->payment as $key=>$amount){
                if($amount > 0){
                    $payment = new BillingPaymentType;
                    $payment->bill_id = $b_id;
                    $payment->payment_mode = $key;
                    $payment->amount = $amount;
                    $payment->transaction_id = $request->trx[$key] ?? null;
                    $payment->created_by = auth()->user()->id;
                    $payment->save();
                }
            }


            foreach($request->service_id as $i=>$ser_id){

                 if (empty($ser_id)) {
                        continue; // skip empty row
                    }


                $service = HospitalSer::find($ser_id);

                    if($service && ($service->flag=="lab_package"))
                    {
                        $packageService = $service->service;
                        $packageServiceCharge = HospitalServiceCharges::where('hospital_id',$org_id)
                                                                        ->where('insurance',$i_cover)
                                                                        ->where('service',$service->id)
                                                                        ->first()->charges??0;

                        $testIncludes = InvestigationGroupTest::where('group_id', $ser_id)->orderBy('sequence_no', 'asc')->get();
                        $subTotal = 0;
                        foreach($testIncludes as $test)
                        {
                            $sCharge = HospitalServiceCharges::where('hospital_id',$org_id)->where('insurance',$i_cover)->where('service',$test->test_id)->first();
                            $subTotal += $sCharge->charges??0;

                            $gen= new PatientGenBill;
                            $gen->bill_id = $b_id;
                            $gen->service_id = $test->test_id;
                            $gen->charges = $sCharge->charges??0;
                            $gen->qty = 1;
                            $gen->doctor_id = $doctor_id;
                            $gen->i_cover = $i_cover;
                            $gen->created_by = auth()->user()->id;
                            $gen->save();
                        }

                        $bill = PatientBilling::find($b_id);
                        $bill->discount = $bill->discount + ($subTotal - $packageServiceCharge);
                        $bill->save();


                    }else{
                        if($discount_in == 'cash'){
                            $dis_value = $request->discountArr[$i] ?? 0;
                        }else{
                            $dis_value = ($request->charges[$i]??0)  * ($request->qty[$i]??1) * ($request->discountArr[$i]??0) / 100;
                        }

                        $gen= new PatientGenBill;
                        $gen->bill_id = $b_id;
                        $gen->service_id = $ser_id;
                        $gen->charges = $request->charges[$i] ?? 0;
                        $gen->qty = $request->qty[$i] ?? 1;
                        $gen->cgst = $request->cgst[$i] ?? 0;
                        $gen->sgst = $request->sgst[$i] ?? 0;
                        $gen->igst = $request->igst[$i] ?? 0;

                        if($discount_in == 'cash'){
                            $gen->discount  = $dis_value;
                        }else{
                             $gen->discount  = $dis_value;
                             $gen->discount_per  = $request->discountArr[$i]?? null;
                        }

                        $gen->doctor_id = $doctor_id;
                        $gen->i_cover = $i_cover;
                        // $gen->discount = $request->discountArr[$i] ?? 0;
                        $gen->doctor_id = $doctor_id;
                        $gen->i_cover = $i_cover;
                        $gen->created_by = auth()->user()->id;
                        $gen->save();


                    }
            }


            if ($calcPayable <= 0.01) {
                $bill->is_settled = 1;
                $bill->is_partially_settled = 0;
            } elseif ($totalPaid >= ($calcPayable - 0.001)) {
                $bill->is_settled = 1;
                $bill->is_partially_settled = 0;
            } elseif ($totalPaid > 0) {
                $bill->is_settled = 0;
                $bill->is_partially_settled = 1;
            } else {
                $bill->is_settled = 0;
                $bill->is_partially_settled = 0;
            }
            $bill->save();

            if ($totalPaid >= ($calcPayable - 0.001) || $calcPayable <= 0.01) {
