        //     $pdfPath = 'assets/billing/'.$pdfFilename;
        //     $pdf->save($pdfPath);

            $hospital = Healtcare_org::where('id', $org_id)->first();

            Notifier::bill_complete([
                'patient_id' => $data->patient_id,
