    public function generate_opd_bill($request, $b_id){

          $data = PatientBilling::join('visitlog','visitlog.id','patient_billing.visit_id')
                                        ->join('pi','pi.id','visitlog.patient_id')
                                        ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                        ->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover')
                                        ->join('users','users.id','=','patient_billing.created_by')
                                        ->select(
                                            'pi.id as patient_id',
                                            'pi.prefix as prefix',
                                            'pi.Fname as Fname',
                                            'pi.Lname as Lname',
                                            'pi.sex as gender',
                                            'pi.age as age',
                                            'pi.mobile_no as mobile_no',
                                            'doctor_db.name as doctor_name',
                                            'pi.i_cover as i_cover',
                                            'health_insurance_agen.insurance_agen as insurance',
                                            'patient_billing.created_at as created_at',
                                            'patient_billing.status as status',
                                            'patient_billing.id as bill_no',
                                            'patient_billing.discount as discount',
                                            'users.first_name',
                                            'users.last_name',
                                            'patient_billing.discount_auth_by as discount_auth_by',
                                            'patient_billing.discount_name as discount_name',
                                        )
                                        ->where('patient_billing.id',$b_id)
                                        ->first();
                //   dd($data);

            $services = PatientGenBill::leftJoin('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
                                    ->where('patient_gen_bill.bill_id',$b_id)
                                    ->where('patient_gen_bill.is_deleted', 0)
                                    ->where(function($query) {
                                            $query->where('patient_gen_bill.is_cancelled', '!=', 1)
                                                    ->orWhereNull('patient_gen_bill.is_cancelled'); // Allow NULL values
                                        })
                                    ->select('patient_gen_bill.*','hospital_services.service','hospital_services.flag')
                                    ->get();

            $payment = BillingPaymentType::where('bill_id',$b_id)
                ->select(
                    'payment_mode',
                    DB::raw('SUM(amount) as amount'),
                )
                ->groupBy('payment_mode')
                ->get()
                ->pluck('amount','payment_mode')->toArray();

            $billtype = BillingPaymentType::where('bill_id',$b_id)->first();
            $transaction_type = $billtype->transaction_type??'';

            $overallPayments = DB::table(DB::raw("
                (
                    /*
                    |--------------------------------------------------------------------------
                    | DIRECT PAYMENTS
                    |--------------------------------------------------------------------------
                    */
                    SELECT

                        bpt.id as payment_id,

                        bpt.bill_id as reference_bill_id,

                        'PAYMENT' as event_type,

                        bpt.transaction_type,

                        bpt.payment_mode,

                        bpt.amount,

                        bpt.created_at

                    FROM billing_payment_type bpt

                    WHERE bpt.bill_id = {$b_id}

                    AND (bpt.is_deleted = 0 OR bpt.is_deleted IS NULL)

                    AND IFNULL(bpt.amount,0) > 0

                    AND NOT EXISTS (
                        SELECT 1
                        FROM refund_remarks rr
                        WHERE rr.bill_id = bpt.bill_id
                        AND rr.status = 'issued'
                    )



                    UNION ALL



                    /*
                    |--------------------------------------------------------------------------
                    | SETTLEMENT PAYMENTS
                    |--------------------------------------------------------------------------
                    */
                    SELECT

                        bpt.id as payment_id,

                        br.ref_bill as reference_bill_id,

                        'SETTLEMENT' as event_type,

                        bpt.transaction_type,

                        bpt.payment_mode,

                        bpt.amount,

                        bpt.created_at

                    FROM bill_reference br

                    JOIN billing_payment_type bpt
                        ON bpt.bill_id = br.ref_bill

                    WHERE br.bill_id = {$b_id}

                    AND (bpt.is_deleted = 0 OR bpt.is_deleted IS NULL)

                    AND IFNULL(bpt.amount,0) > 0



                    UNION ALL



                    /*
                    |--------------------------------------------------------------------------
                    | REFUND PAYMENTS
                    |--------------------------------------------------------------------------
                    */
                    SELECT

                        bpt.id as payment_id,

                        rr.bill_id as reference_bill_id,

                        'REFUND' as event_type,

                        bpt.transaction_type,

                        bpt.payment_mode,

                        bpt.amount,

                        bpt.created_at

                    FROM refund_remarks rr

                    JOIN billing_payment_type bpt
                        ON bpt.bill_id = rr.bill_id

                    WHERE JSON_UNQUOTE(JSON_EXTRACT(rr.bill_ref_id, '$[0]')) = {$b_id}

                    AND rr.status = 'issued'

                    AND (bpt.is_deleted = 0 OR bpt.is_deleted IS NULL)

                    AND IFNULL(bpt.amount,0) > 0

                ) as bill_payments
                "))
                ->orderBy('created_at', 'ASC')
                ->get();

                $discount = PatientBilling::select('users.first_name','users.last_name','patient_billing.discount_name')
                                            ->join('users','users.id','patient_billing.discount_auth_by')
                                            ->where('patient_billing.id',$b_id)
                                            ->first();


                if($request->has('version')){
                    $version = $request->version;
                }else{
                    $version = HospitalSetting::where('hospital_id',auth()->user()->org_id)
                                                ->where('identifier','opd_bill_print')
                                                ->first()->current_setting??'v1';
                }


               if($version == 'v2'){

                    $services = PatientGenBill::join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
                                                ->leftJoin('category_service_index', 'category_service_index.service_id', '=', 'hospital_services.id')
                                                ->leftJoin('categories', 'categories.id', '=', 'category_service_index.category_id')
                                                ->where('patient_gen_bill.bill_id', $b_id)
                                                ->where('patient_gen_bill.is_deleted', 0)
                                                ->where(function($query) {
                                                    $query->where('patient_gen_bill.is_cancelled', '!=', 1)
                                                            ->orWhereNull('patient_gen_bill.is_cancelled'); // Allow NULL values
                                                })
                                                ->select(
                                                    DB::raw('COALESCE(categories.name, hospital_services.flag) as group_name'),
                                                    DB::raw('SUM(patient_gen_bill.qty) as total_qty'),
                                                    DB::raw('ROUND(SUM((patient_gen_bill.charges * patient_gen_bill.qty) - patient_gen_bill.discount), 2) as total_amount')
                                                )
                                                ->groupBy('group_name')
                                                ->get();

                }

            $totalPaid = array_sum($payment);
            $totalInWords = $this->numberToWords($totalPaid);
            $pdf = PDF::loadView('admin.pdf.opd_bill.'.$version,['version'=>$version,'data' => $data,'serviceData'=>$services, 'payments'=>$payment,'discount'=>$discount,'overallPayments'=>$overallPayments,'transaction_type'=>$transaction_type,'totalInWords'=>$totalInWords]);

           // download PDF file with download method
           // return $pdf->stream('pdf_file.pdf');
            if (!file_exists('assets/billing')) {
                mkdir('assets/billing', 0777, true);
            }

            //$pdf = PDF::loadView('admin.pdf.bill');
            $pdfFilename = 'pdf_file_' . $b_id . $version.'.pdf';
            $pdfPath = 'assets/billing/'.$pdfFilename;
            $pdf->save($pdfPath);

            return url($pdfPath);

    }



