    public function emergency_module(Request $request,$id=null)
    {
        $request->merge(['emergency'=>true]);
        $visits = $this->er_visit_list($request);
        $context = FacadesRoute::currentRouteName();


        // return $visits;

        if ($visits instanceof \Illuminate\Http\JsonResponse) {
            $data = $visits->getData();
            $visits = collect($data->data->visit ?? []);
        }

        // if already array
        elseif (is_array($visits)) {
            $visits = collect($visits);
        }
        $org_id = auth()->user()->org_id;

        if(!$id){
            return view('admin.patient.emergency.emergency_module',compact('visits','context'));
        }

        $visitLog = Visitlog::find($id);
        $patient = $visitLog->patient;
        $uhid = $patient->id;


        // dd($ipd->i_cover);
        $service = HospitalService::join('hospital_services','hospital_services.id','=','hospital_services_index.service')
                                    ->join('hospital_service_charges','hospital_service_charges.service','=','hospital_services_index.service')
                                    ->where('hospital_services_index.hospital_id',$org_id)
                                    ->where('hospital_service_charges.hospital_id',$org_id)
                                    ->where('hospital_services_index.active',1)
                                    ->where('hospital_service_charges.insurance',$patient->i_cover)
                                    ->where('hospital_service_charges.is_active',1)
                                    ->select('hospital_services.*')
                                    ->get();


        $bill = PatientBilling::where('visit_id', $id)->first();

        $serviceDoneQuery = PatientGenBill::join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
            ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
            ->where('patient_gen_bill.bill_id', $bill->id)
            ->where('patient_gen_bill.is_deleted', 0)
            ->select(
                'patient_gen_bill.*',
                'hospital_services.service as service_name',
                'hospital_services.flag as flag',
                'lab_investigations.status as status'
            );

        $flags = [
            'investigations' => 'test',
            'procedures' => 'procedure',
            'radiology' => 'radiology'
        ];

        foreach ($flags as $key => $flag) {
            $investigations[$key] = (clone $serviceDoneQuery)->where('hospital_services.flag', $flag)->get();
        }

        $serviceOrdered = \App\Models\IpdServiceRequest::where('visit_id',$id)->get();

        $itemsRequested = \App\Models\InventoryBillingRequest::where('visit_id', $id)->get();

        $itemsRequested2 = \App\Models\InventoryBilling::where('visit_id', $id)->get();
        $bill_ref_ids = $itemsRequested2
                                        ->pluck('id')
                                        ->unique()
                                        ->values()
                                        ->toArray ();

        $pharmacyBillItems = InventoryBillingItem::join('inventory', 'inventory.id', '=', 'inventory_billing_items.inv_id')
                                                ->join('items', 'items.id', '=', 'inventory.item_id')
                                                ->join('pharma_companies', 'pharma_companies.id', '=', 'items.manufacturer_id')
                                                ->select('inventory_billing_items.*', 'items.name', 'pharma_companies.name as manufacturer_name', 'inventory.expiry', 'inventory.batch_no')
                                                ->whereIn('inventory_billing_items.bill_id', $bill_ref_ids)
                                                ->get();

        $totalPharmacyBillingAmount = InventoryBillingItem::whereIn('bill_id', $bill_ref_ids)
                                                    ->get()
                                                    ->sum(function ($item) {

                                                        $amount = $item->price * $item->qty;

                                                        return $item->mode === 'sale_return'
                                                            ? -abs($amount)
                                                            : abs($amount);
                                                    });



         $paymentd = BillingPaymentType::join('patient_billing', 'patient_billing.id', '=', 'billing_payment_type.bill_id')
                                        // ->join('ipd_details', 'ipd_details.visit_table_id', '=', 'patient_billing.visit_id')
                                        ->leftJoin('service_payment_index', 'service_payment_index.payment_id', '=', 'billing_payment_type.id')
                                        ->select(
                                            'patient_billing.id as bill_id',
                                            'billing_payment_type.*',


                                            // total settled for services
                                            DB::raw('COALESCE(SUM(CASE WHEN service_payment_index.usage_type = "service" THEN service_payment_index.settled_amount ELSE 0 END),0) as total_settled'),

                                            // total used for refunds
                                            DB::raw('COALESCE(SUM(CASE WHEN service_payment_index.usage_type = "refund" THEN service_payment_index.settled_amount ELSE 0 END),0) as total_refunded'),

                                            // remaining/excess = total payment - (settled + refunded)
                                            DB::raw('(billing_payment_type.amount - COALESCE(SUM(service_payment_index.settled_amount),0)) as excess')
                                        )
                                        ->where('patient_billing.id', $bill->id)
                                        ->groupBy(
                                            'patient_billing.id',
                                            'billing_payment_type.id',

                                            'billing_payment_type.amount',
                                            'billing_payment_type.bill_id',
                                            'billing_payment_type.tds',
                                            'billing_payment_type.transaction_id',
                                            'billing_payment_type.remarks',
                                            'billing_payment_type.payment_mode',
                                            'billing_payment_type.transaction_type',
                                            'billing_payment_type.created_by',
                                            'billing_payment_type.created_at',
                                            'billing_payment_type.updated_at'
                                        )
                                        // ->havingRaw('excess > 0') // only payments with remaining amount
                                        ->get();

            $totalPaidAmount = $paymentd->sum(function ($item) {
                    return $item->transaction_type == 1
                        ? -$item->amount   // refund => negative
                        : $item->amount;   // normal => positive
                });


            $doctors = HospitalDoctor::join('doctor_db', 'doctor_db.id', '=', 'org_doc_index.doc_id')
                                    ->where('org_doc_index.org_id', Auth::user()->org_id)
                                    ->where('org_doc_index.active', 1)
                                    ->select('doctor_db.id','doctor_db.name')
                                    ->get();

        $con_req = DoctorConsultationReq::join('doctor_db','doctor_db.id','=','doctor_consultation_request.doctor_id')
                                         ->select('doctor_consultation_request.*','doctor_db.name')
                                         ->where('doctor_consultation_request.visit_id',$id)
                                         ->get();

        $registrationServiceItem = PatientGenBill::join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
            ->where('hospital_services.flag', 'registration_charge')
            ->where('patient_gen_bill.bill_id', $bill->id ?? 0)
            ->first();

        // $applyRegCharges = \App\Helpers\HospitalHelper::isSettingEnabled(Auth()->user()->org_id, 'reg_charges_in_ipd');

        if ($registrationServiceItem) {
            $registration_fee = $registrationServiceItem->charges * $registrationServiceItem->qty - $registrationServiceItem->discount  ?? 0;
        } else {
            $registration_fee = 0;
        }


          $miscellaneous = HospitalService::join('hospital_services', 'hospital_services.id', '=', 'hospital_services_index.service')
            ->where('hospital_services_index.hospital_id', $org_id)
            ->where('hospital_services_index.active', 1)
            ->where('hospital_services.flag', 'miscellaneous')
            ->orWhere('hospital_services.flag', 'nursing_charges')
            ->select('hospital_services.*')
            ->get();



        return view('admin.patient.emergency.emergency_module',compact('visitLog','patient','totalPaidAmount','registration_fee','miscellaneous','totalPharmacyBillingAmount','uhid','doctors','con_req','org_id','visits','context', 'service', 'flags', 'investigations','serviceOrdered','itemsRequested','paymentd','bill'));
    }


    public function fetch_er_charges(Request $request){
        $service = $request->service;
        $hospital_id = $request->hospital_id;
        $i_cover = $request->i_cover;
        $module = $request->module;
        $org_id = Auth()->User()->org_id;


        $er = EmergencyServiceCharges::where('hospital_id', $hospital_id)->where('service_id', $service)->first();

        $org = Healtcare_org::find($org_id);
        $er_hike_per = $org->er_hike_per ?? 0;

        // dd($er_hike_per);

        if($er){
                return response()->json([
                    'charges' => $er->charges,
                    'cgst' => 0,
                    'sgst' => 0,
                ]);
        }else{

                 $gst = HospitalService::where('hospital_id', $hospital_id)->where('active', 1)->where('service', $service)->first();
                    // Fetch the room charges based on room type
                 $room = HospitalServiceCharges::where('hospital_id', $hospital_id)->where('insurance', $i_cover)->where('service', $service)->first();

                    if ($room && $gst) {
                        $charges = $room->charges;

                        // Emergency: increase by 20%
                        if ($module === 'emergency') {
                            $charges = $charges + ($charges * $er_hike_per / 100);
                            // or: $charges *= 1.20;
                        }

                        $cgst = $charges * ($gst->service_cgst / 100);
                        $sgst = $charges * ($gst->service_sgst / 100);

                        return response()->json([
                            'charges' => $charges,
                            'cgst' => $cgst,
                            'sgst' => $sgst,

                        ]);
                    }
        }




    }

    public function consultation_request(Request $request, $id){

        $request->validate([
                            'doctor'   => 'nullable|array',
                            'doctor.*' => 'integer',
                        ]);


                        // dd($request->all());
        foreach ($request->doctor ?? [] as $did) {
            // dd($did);
            $dcr = new DoctorConsultationReq;
            $dcr->doctor_id = $did;
            $dcr->visit_id = $id;
            $dcr->remarks = $request->remarks ?? '';
            $dcr->created_by = Auth()->User()->id;
            $dcr->save();
        }

         return redirect()->back()->with('success', 'Request Send successfully');

    }

    public function update_consultation_status(Request $request){
            $id = $request->id;
            $status = $request->status;
            $charges = $request->charges;
            $remarks = $request->remarks;

            $con = DoctorConsultationReq::find($id);

            if($status == 1){
                $bill = PatientBilling::where('visit_id',$con->visit_id)->first();
                $doctorServiceId = HospitalSer::where('flag', 'doctor_consultation')->value('id');

                if (is_null($charges) || $charges === '') {
                    $ipd = Ipd_details::where('visit_table_id', $con->visit_id)->first();
                    if ($ipd) {
                        $bed_type = $ipd->bed_type;
                        $doctor_id = $con->doctor_id;
                        $charges = DocCharge::where('entry_id', $doctor_id)
                            ->where('status', 1)
                            ->whereRaw('JSON_CONTAINS(ward_id, ?)', ['"' . $bed_type . '"'])
                            ->value('ch');
                    }
                }

                if (is_null($charges) || $charges === '') {
                    return response()->json([
                        'status' => 'charge_required',
                        'message' => 'No active doctor consultation charge found for this bed type. Please enter charges manually:'
                    ]);
                }

                $con->status = $status;
                $con->approved_by = Auth()->user()->id;
                $con->save();

                if ($bill) {
                    $visit = Visitlog::find($con->visit_id);
                $pi = Visitlog::join('pi', 'pi.id', '=', 'visitlog.patient_id')
                                ->select('i_cover')
                                ->where('visitlog.id', '=', $con->visit_id)
                                ->first();
                $i_cover = $pi ? $pi->i_cover : 0;

                    $gen = new PatientGenBill;
                    $gen->bill_id = $bill->id;
                    $gen->service_id = $doctorServiceId;
                    $gen->charges = $charges;
                    $gen->qty = 1;
                    $gen->doctor_id = $con->doctor_id;
                    $gen->i_cover = $i_cover;
                    $gen->service_delivered_at = date('Y-m-d H:i:s');
                    $gen->additional_info = json_encode(['doctor_id'=> $con->doctor_id,'cgst' => 0, 'sgst' => 0]);
                    $gen->is_er = ($visit && $visit->emergency) ? 1 : 0;
                    $gen->created_by = auth()->user()->id;
                    $gen->save();
                }
            } else {
                $con->status = $status;
                $con->approved_by = Auth()->user()->id;
                $con->save();
            }

            return response()->json(['status' => 'success', 'message' => 'Record updated successfully']);
    }


    public function save_clinical_template(Request $request){
       $visit_id = $request->visit_id;

       $vcd = VisitClinicalData::where('visit_id', $visit_id)->first();
       $user = Visitlog::where('id', $visit_id)->first();
       if ($vcd) {
           $temp_data = $vcd->others;

           $template = new Template;
           $template->user_id = $user->doctor_id;
           $template->name = $request->template_name;
           $template->context = 'clinical_notes';
           $template->template = $temp_data;
           $template->save();
       }else{
           return response()->json(['status' => 'error', 'message' => 'No data found']);
       }

       return response()->json(['status' => 'success', 'message' => 'Template saved successfully']);
    }

