        public function save_admission_assessment(Request $request){

            $textbox = $request->data; // Data received from the front-end
            $existingData = [];

            foreach ($textbox as $tableName => $tableData) {
                // Skip '_token' if it exists
                if ($tableName === '_token') {
                    continue;
                }

                foreach ($tableData as $key => $data) {
                    // Skip '_token' or any unwanted keys
                    if ($key === '_token') {
                        continue;
                    }

                    // Ensure the tableName group exists
                    if (!isset($existingData[$tableName])) {
                        $existingData[$tableName] = [];
                    }

                    // Store the data for each key in the group
                    $existingData[$tableName][$key] = [
                        "label" => $data['label'] ?? null,
                        "value" => $data['value'] ?? null,
                        "updated_at" => now()->toDateTimeString()
                    ];
                }
            }


            //   dd($request->all());
            $vcd = VisitClinicalData::where('visit_id', $request->visit_id)->where('context', $request->context)->first();
            if (!$vcd) {
                $vcd = new VisitClinicalData;
                $vcd->visit_id = $request->visit_id;
                $vcd->context = $request->context;
                $vcd->others = json_encode($existingData, JSON_PRETTY_PRINT);
                $vcd->created_by = Auth::user()->id;
                $vcd->save();

            }else{
                $vcd->others = json_encode($existingData, JSON_PRETTY_PRINT);
                $vcd->updated_by = Auth::user()->id;
                $vcd->save();
            }

            return response()->json(['status'=>'success', 'message'=>'Record updated Successfully']);

            }



    public function save_freetext2(Request $request){
        $visit_id = $request->visit_id;
        $context = $request->context;
        $org_id = Auth::user()->org_id ?? null;

        if ($guard = ClinicalDocumentLockService::checkAndGuard($org_id, $visit_id, $context)) {
            return $guard;
        }

        $vcd = VisitClinicalData::where('visit_id', $visit_id)->first();

        if (!$vcd) {
            // If no record exists, create a new one
            $vcd = new VisitClinicalData();
            $vcd->visit_id = $visit_id; // Assign the visit ID
            $existingData = []; // Start with an empty array
        } else {
            // If record exists, decode existing 'others' JSON data
            $existingData = is_string($vcd->ot_data ?? '')
                            ? json_decode($vcd->ot_data, true)
                            : [];
        }

        $textbox = $request->freeTextbox;

        foreach ($textbox as $key => $value) {
            $existingData[$key] = [
                "value" => $value,
                "updated_at" => now()->toDateTimeString()
            ];
        }

        // Update 'others' column
        $vcd->ot_data = json_encode($existingData, JSON_PRETTY_PRINT);
        $vcd->save();


        return response()->json(['status'=>'success', 'message'=>'Record updated Successfully']);
    }

