            if ($key === '_token') {
                continue;
            }

            // Ensure the tableName group exists
            if (!isset($existingData[$tableName])) {
                $existingData[$tableName] = [];
            }

            // Store the data for each key in the group
            $existingData[$tableName][$key] = [
                "label" => $data['label'] ?? null,
