    public function print_surgical_notes(Request $request, $id){

        $vcd = VisitClinicalData::where('visit_id', $id)->where('context', 'patient.eye_clinical.v2')->first();
        if (!$vcd) {
            $vcd = VisitClinicalData::create(['visit_id' => $id, 'others' => '{}', 'context' => 'patient.eye_clinical.v2']);
        }
        $surgery_notes = json_decode($vcd->ot_data, true);

