            $existingData[$key] = [
                "value" => $value,
                "updated_at" => now()->toDateTimeString()
            ];

            $words = array_map('trim', explode(',', $value));

            // Get the last word
            $word = end($words);

            // $this->add_comment($visit_id,$word,$key);
