    public function add_medicine_to_doc_fav_brand($visit_id,$brand_id,$source,$mark){
        $visit = Visitlog::find($visit_id);

        $brand = DocDrugBrand::where('doctor_id', $visit->doctor_id)->where('brand_id', $brand_id)->where('d_type', $source)->first();
        if($brand){
            return;
        }

        $new = new DocDrugBrand;
        $new->doctor_id = $visit->doctor_id;
        $new->brand_id = $brand_id;
        $new->d_type = $source;
        $new->mark = $mark;
        $new->save();

        return;

    }


