    public function previous_comment(Request $request){

        $records = VisitClinicalData::where('context', $request->context)->get();

        $comments = [];

        $key = $request->target; // the key you want to fetch, e.g. 'alert'

        foreach ($records as $record) {
            if (!empty($record->others)) {
                $others = json_decode($record->others, true);

                if (isset($others[$key]['value'])) {
                    $comments[] = $others[$key]['value'];
                }
            }
        }

        return response()->json($comments);
    }

