    public function get_instructions(Request $request){

        //  return $request->input('query');

        $brand = $request->parameter; // Example input: "699|ss"
        $instruction = $request->input('query');
        $flag = $request->input('flag');

        list($brand_id, $source) = explode('|', $brand);

        if($source == 'ss'){
            $b =  Drug_brand::find($brand_id);
            $dose_id = $b->dose_id;
            $drug_id = $b->drug_id;
            $form_id = $b->form_id;
        }else{
            $b = DrugCombBrand::find($brand_id);
            $dose_id = $b->comb_dose_id_entry;
            $drug_id = $b->comb_id;
            $form_id = $b->form_id;
        }

        $inst = MedicineInstruction::where([
                                                'dose_id' => $dose_id,
                                                'drug_id' => $drug_id,
                                                'form_id' => $form_id,
                                                'flag' => $flag
                                            ])
                                            ->where('user_input', 'like', '%' . $instruction . '%')
                                            ->select('user_input', \DB::raw('count(*) as count'))  // Select user_input and count
                                            ->groupBy('user_input')  // Group by user_input
                                            ->orderByDesc(\DB::raw('count(*)'))  // Order by count in descending order
                                            ->get();  // Fetch the results

        // Optionally, convert to array if needed
        $instArray = $inst->toArray();
        return response()->json($instArray);

    }


    function instructions(Request $request){
        // dd($request->all());

        $brand_id = $request->brand_id;
