                            ->where('pres_manual.it', '!=', '')
                            ->select('pres_manual.it')
                            ->groupBy('pres_manual.it')
                            ->orderByRaw('COUNT(pres_manual.it) DESC')
                            ->limit(1)
                            ->value('pres_manual.it');

            $route = PresManual::where('pres_manual.brand_id', $brand_id)
                            ->leftJoin('visitlog', 'visitlog.id', '=', 'pres_manual.visit_table_id')
