            $form_id = $b->form_id;
        }else{
            $b = DrugCombBrand::find($brand_id);
            $dose_id = $b->comb_dose_id_entry;
            $drug_id = $b->comb_id;
            $form_id = $b->form_id;
        }


        $flags = ['it', 'spl_inst','route'];
        $results = MedicineInstruction::where([
                                    'dose_id' => $dose_id,
                                    'drug_id' => $drug_id,
