                                ->groupBy('user_input', 'flag')
                                ->orderByDesc(\DB::raw('count(*)'))
                                ->get();
        //  return $results;
        // Separate the results
            $instructions = $results->where('flag', 'it')->pluck('user_input')->first(); // Use first() instead of [0]
            $spl_inst = $results->where('flag', 'spl_inst')->pluck('user_input')->first();
            $route = $results->where('flag', 'route')->pluck('user_input')->first();

            // $notes = DB::table('pres_final')->join('drug_brand_index', 'drug_brand_index.id', '=', 'pres_final.brand_id')
            //             ->where('pres_final.brand_id', $drug_id)
            //             ->whereNotNull('pres_final.notes')
            //             ->where('pres_final.notes', '!=', '')
            //             ->distinct()
            //             ->pluck('pres_final.notes');

            return response()->json([
                'status' => 'success',
                'instructions' => $instructions ?? null, // Fallback to null if not found
                'spl_inst' => $spl_inst ?? null,
                'route' => $route ?? null,
                'notes' => $notes ?? null
            ]);
    }
    public function instructions_single(Request $request){
        $request->validate([
            'brand_id' => 'required',
            'doctor_id' => 'required',
        ]);

        $brand_id = $request->brand_id;
        $doctorID = $request->doctor_id;

        $brand = DB::table('drug_brand_index')->where('id', $brand_id)->first();
        $compositionID = $brand->composition_id ?? null;

        $instructions = null;
        $spl_inst = null;
        $route = null;
        $duration = null;
        $notes = [];

        try {
            // 1. Doctor's saved/favorite setting for this composition
            if (!empty($compositionID)) {
                $record = DB::table('doctor_fav_brand_composition')
                    ->where('composition_id', $compositionID)
                    ->where('doctor_id', $doctorID)
                    ->first();

                if ($record) {
                    $instructions = $record->frequency ?? null;
                    $spl_inst = $record->spl_inst ?? null;
                }

                $notes = DB::table('doctor_fav_composition_notes')
                    ->where('composition_id', $compositionID)
                    ->where('doctor_id', $doctorID)
                    ->pluck('notes')->toArray() ?? [];
            }

            // 2. Doctor's latest prescription for this exact brand
            if (empty($instructions)) {
                $prevPres = DB::table('pres_final as pf')
                    ->join('visitlog as v', 'v.id', '=', 'pf.visit_table_id')
                    ->where('pf.brand_id', $brand_id)
                    ->where('v.doctor_id', $doctorID)
                    ->whereNotNull('pf.it')
                    ->where('pf.it', '!=', '')
                    ->orderByDesc('pf.id')
                    ->select('pf.it as frequency', 'pf.spl_inst', 'pf.rs as route', 'pf.dt as duration', 'pf.notes')
                    ->first();

                if ($prevPres) {
                    $instructions = $prevPres->frequency;
                    if (empty($spl_inst)) $spl_inst = $prevPres->spl_inst;
                    if (empty($route)) $route = $prevPres->route;
                    if (empty($duration)) $duration = $prevPres->duration;
                    if (empty($notes) && !empty($prevPres->notes)) {
                        $notes = [$prevPres->notes];
                    }
                }
            }

            // 3. Most used settings for this composition across all doctors
            if (empty($instructions) && !empty($compositionID)) {
                $favGlobal = DB::table('doctor_fav_brand_composition')
                    ->where('composition_id', $compositionID)
                    ->whereNotNull('frequency')
                    ->where('frequency', '!=', '')
                    ->select('frequency', 'spl_inst', DB::raw('COUNT(*) as total'))
                    ->groupBy('frequency', 'spl_inst')
                    ->orderByDesc('total')
                    ->first();

                if ($favGlobal) {
                    $instructions = $favGlobal->frequency;
                    if (empty($spl_inst)) $spl_inst = $favGlobal->spl_inst;
                }
            }

            // 4. Most used in pres_final across all prescriptions for this brand
            if (empty($instructions)) {
                $mostUsed = DB::table('pres_final')
                    ->where('brand_id', $brand_id)
                    ->whereNotNull('it')
                    ->where('it', '!=', '')
                    ->select('it as frequency', 'spl_inst', 'rs as route', 'dt as duration', DB::raw('COUNT(*) as total'))
                    ->groupBy('it', 'spl_inst', 'rs', 'dt')
                    ->orderByDesc('total')
                    ->first();

                if ($mostUsed) {
                    $instructions = $mostUsed->frequency;
                    if (empty($spl_inst)) $spl_inst = $mostUsed->spl_inst;
                    if (empty($route)) $route = $mostUsed->route;
                    if (empty($duration)) $duration = $mostUsed->duration;
                }
            }

            // 5. Fallback: Most used in medicine_instructions
            if (empty($instructions) && $brand && !empty($brand->dose_id) && !empty($brand->drug_id) && !empty($brand->form_id)) {
                $topFreq = DB::table('medicine_instructions')
                    ->where('dose_id', $brand->dose_id)
                    ->where('drug_id', $brand->drug_id)
                    ->where('form_id', $brand->form_id)
                    ->where('flag', 'it')
                    ->orderByDesc('count')
                    ->value('user_input');
                if ($topFreq) {
                    $instructions = $topFreq;
                }
                if (empty($spl_inst)) {
                    $topSpl = DB::table('medicine_instructions')
                        ->where('dose_id', $brand->dose_id)
                        ->where('drug_id', $brand->drug_id)
                        ->where('form_id', $brand->form_id)
                        ->where('flag', 'spl_inst')
                        ->orderByDesc('count')
                        ->value('user_input');
                    if ($topSpl) {
                        $spl_inst = $topSpl;
                    }
                }
            }
        } catch (\Throwable $e) {
            \Log::warning('Error in instructions_single: ' . $e->getMessage());
        }

        return response()->json([
            'status' => 'success',
            'instructions' => $instructions ?? null,
            'spl_inst' => $spl_inst ?? null,
            'route' => $route ?? null,
            'duration' => $duration ?? null,
            'notes' => $notes ?? null
        ]);
    }

    public function add_medicine_instruction($visit_id, $dose_id, $drug_id, $form_id, $instruction, $source,$flag){

        $visit = Visitlog::find($visit_id);
        $doctor_id = $visit->doctor_id;

        if(!empty($instruction)){
              $mi = MedicineInstruction::where(['dose_id' => $dose_id, 'drug_id' => $drug_id, 'form_id' => $form_id,'user_input' => $instruction])->first();

            if(!$mi){
                $mi = new MedicineInstruction;
                $mi->user_id = $doctor_id;
                $mi->dose_id = $dose_id;
                $mi->drug_id = $drug_id;
                $mi->form_id = $form_id;
                $mi->user_input = $instruction;
                $mi->source = $source;
                $mi->flag = $flag;
                $mi->save();
            }else{
                $mi->count += 1;
                $mi->save();
            }
        }

    }

