    public function save_pulse(Request $request)
    {
        $user = Auth::user();
        $org_id = $user->org_id ?? 1;

        $visit = Visitlog::find($request->visit_id);

        DB::beginTransaction();
        try {
            $vitals = Vitals::where('visit_id',$request->visit_id)->first();
            if(!$vitals){
                $vital = new Vitals;
                $vital->visit_id = $request->visit_id;
                $vital->created_by = $user->id;
                $vital->updated_by = $user->id;

                if ($request->has('upperBP') && (!empty($request->upperBP[0]) || !empty($request->lowerBP[0]))) {
                    $bp[] = [
                        'upper_bp' => $request->upperBP,
                        'lower_bp' => $request->lowerBP,
                        'position' => $request->position,
                        'site' => $request->site,
                        'created_by' => $user->id,
                        'created_at' => now()
                    ];
                    $vital->bp = json_encode($bp);
                } else {
                    $vital->bp = json_encode([]);
                }

                if ($request->has('pulseRate') && !empty($request->pulseRate)) {
                    $pulse[] = [
                        'pulseRate' => $request->pulseRate,
                        'pulseChar' => $request->pulseCharacter,
                        'site' => $request->pulseSite,
                        'regularties' => $request->pulseRegularties,
                        'created_by' => $user->id,
                        'created_at' => now()
                    ];
                    $vital->pulse = json_encode($pulse);
                } else {
                    $vital->pulse = json_encode([]);
                }

                if ($request->has('height')) $vital->height = ($request->height !== null && $request->height !== '' && $request->height != 0) ? $request->height : null;
                if ($request->has('weight')) $vital->weight = ($request->weight !== null && $request->weight !== '' && $request->weight != 0) ? $request->weight : null;
                if ($request->has('temprature')) $vital->temprature = ($request->temprature !== null && $request->temprature !== '' && $request->temprature != 0) ? $request->temprature : null;
                if ($request->has('saturation')) $vital->saturation = ($request->saturation !== null && $request->saturation !== '') ? $request->saturation : null;
                if ($request->has('blood_sugar')) $vital->blood_sugar = ($request->blood_sugar !== null && $request->blood_sugar !== '') ? $request->blood_sugar : null;
                if ($request->has('ldl')) $vital->ldl = ($request->ldl !== null && $request->ldl !== '') ? $request->ldl : null;
                if ($request->has('inr')) $vital->inr = ($request->inr !== null && $request->inr !== '') ? $request->inr : null;
                if ($request->has('rr')) $vital->rr = ($request->rr !== null && $request->rr !== '') ? $request->rr : null;
                $vital->save();

                $vitals = $vital;
            }else{
                if ($request->has('upperBP') && (!empty($request->upperBP[0]) || !empty($request->lowerBP[0]))) {
                    $bpArr = json_decode($vitals->bp, true);
                    if (!is_array($bpArr)) {
                        $bpArr = [];
                    }
                    $bpArr = array_merge($bpArr, [[
                        'upper_bp' => $request->upperBP,
                        'lower_bp' => $request->lowerBP,
                        'position' => $request->position,
                        'site' => $request->site,
                        'created_by' => $user->id,
                        'created_at' => now()
                    ]]);
                    $vitals->bp = json_encode($bpArr);
                }

                if ($request->has('pulseRate') && !empty($request->pulseRate)) {
                    $pulseArr = json_decode($vitals->pulse, true);
                    if (!is_array($pulseArr)) {
                        $pulseArr = [];
                    }
                    $pulseArr = array_merge($pulseArr, [[
                        'pulseRate' => $request->pulseRate,
                        'pulseChar' => $request->pulseCharacter,
                        'site' => $request->pulseSite,
                        'regularties' => $request->pulseRegularties,
                        'created_by' => $user->id,
                        'created_at' => now()
                    ]]);
                    $vitals->pulse = json_encode($pulseArr);
                }

                if ($request->has('height')) $vitals->height = ($request->height !== null && $request->height !== '' && $request->height != 0) ? $request->height : null;
                if ($request->has('weight')) $vitals->weight = ($request->weight !== null && $request->weight !== '' && $request->weight != 0) ? $request->weight : null;
                if ($request->has('temprature')) $vitals->temprature = ($request->temprature !== null && $request->temprature !== '' && $request->temprature != 0) ? $request->temprature : null;
                if ($request->has('saturation')) $vitals->saturation = ($request->saturation !== null && $request->saturation !== '') ? $request->saturation : null;
                if ($request->has('blood_sugar')) $vitals->blood_sugar = ($request->blood_sugar !== null && $request->blood_sugar !== '') ? $request->blood_sugar : null;
                if ($request->has('ldl')) $vitals->ldl = ($request->ldl !== null && $request->ldl !== '') ? $request->ldl : null;
                if ($request->has('inr')) $vitals->inr = ($request->inr !== null && $request->inr !== '') ? $request->inr : null;
                if ($request->has('rr')) $vitals->rr = ($request->rr !== null && $request->rr !== '') ? $request->rr : null;
                $vitals->save();
            }

            DB::commit();
        } catch (\Throwable $e) {
            DB::rollBack();
            throw $e;
        }

        // ABDM Care Context synchronization using existing CareContextManagerService
        if (\Illuminate\Support\Facades\Schema::hasTable('patient_care_contexts') && !empty($vitals->id)) {
            try {
                $patient_id  = $visit->patient_id ?? 0;
                $hospital_id = $visit->hospital_id ?? ($org_id ?? 1);
                $isIpd       = in_array((int)($visit->visit_status ?? 0), [1, 2]);

                if (!empty($patient_id)) {
                    $ccManager = app(\App\Services\ABDM\CareContextManagerService::class);
                    $ccManager->registerVitalsContext(
                        visitId: $request->visit_id,
                        vitalId: $vitals->id,
                        patientId: (int)$patient_id,
                        hospitalId: (int)$hospital_id,
                        isIpd: $isIpd
                    );
                }
            } catch (\Throwable $ccEx) {
                \Illuminate\Support\Facades\Log::channel('abdm')->warning("save_pulse care context sync failed for vital {$vitals->id}: " . $ccEx->getMessage());
            }
        }

        // Return a response
        return response()->json([
            'message' => 'Data saved successfully',
            'data' => $vitals,
        ]);
    }


