    function callRouteAction($routeName, $params = [])
    {
        $route = \Route::getRoutes()->getByName($routeName);

        if (!$route) {
            throw new \Exception("Route not found: $routeName");
        }

        $action = $route->getActionName();

        [$controller, $method] = explode('@', $action);

        $instance = app($controller);

        return app()->call([$instance, $method], $params);
    }



        public function getViewHtmlFromRoute($route_name, $visit_id, $context)
        {

            $response = callRouteAction($route_name, [
                'id' => $visit_id,
                'context' => $context,
                'header' => true
            ]);

            // Return the HTML that your controller/view normally outputs
            return $response;
        }

        public function send_open_prescription(Request $request)
        {
            $org_id    = auth()->user()->org_id;
            $visit_id  = $request->vid;
            $print_url = $request->print_url;
            $context   = $request->context;
            $route_name = $request->print_url_name;

            DB::beginTransaction();

            $visit = Visitlog::find($visit_id);
            $patient = Patient::find($visit->patient_id);

            $whatsapp_without_verification = \App\Helpers\HospitalHelper::isSettingEnabled($org_id,'whatsapp_without_verification');

            if(!$whatsapp_without_verification){
                if(!$patient->mnvs)
                {
                    return response()->json(['status' => 'error','message' => 'Need to Verify Mobile Number']);
                }
            }

            $html = $this->getViewHtmlFromRoute($route_name, $visit_id, $context);
            $visit = Visitlog::join('pi', 'pi.id', '=', 'visitlog.patient_id')
                            ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                            ->select('visitlog.id', 'pi.prefix','pi.Fname','pi.age','pi.sex',
                                    'pi.Lname', 'doctor_db.name as doctor_name','pi.mobile_no',
                                    'doctor_specialities.name as sp_name',
                                    'doctor_db.id as doctor_id','pi.id as uhid')
                            ->where('visitlog.id', $visit_id)
                            ->first();


                $pdf = \PDF::loadHTML($html);
                // download PDF file with download method
                if (!file_exists('assets/files/prescription')) {
                    mkdir('assets/files/prescription', 0777, true);
                }

                //$pdf = PDF::loadView('admin.pdf.bill');
                $pdfFilename = 'pdf_file_' . $visit_id . '.pdf';
                $pdfPath = 'assets/files/prescription/'.$pdfFilename;
                $pdf->save($pdfPath);


                $hospital = Healtcare_org::where('id', $org_id)->first();

                $isEnabled = Notifier::prescription([
                    'patient_id' => $visit->uhid,
                    'phone_number' => $visit->mobile_no,
                    'params' => [
                        'patient_name'=> $visit->prefix.' '.$visit->Fname.' '.$visit->Lname,
                        'hospital_name'=>$hospital->name??'',
                        'hospital_contact'=>$hospital->contact_no??'',
                        'dr_name'=>$visit->doctor_name??'',
                        'pdf'=>($pdfPath),
                        ]
                    ]);

                DB::commit();
            if($isEnabled){
                return response()->json(['status' => 'success', 'message'=>'Prescription Sended Successfully', 'pdf_path' => $pdfPath]);
            }else{
                return response()->json(['status' => 'error', 'message'=>'Whatsapp Setting Not Enabled', 'pdf_path' => $pdfPath]);
            }

        }

