                                            'patient_billing.created_at as created_at',
                                            'patient_billing.status as status',
                                            'patient_billing.id as bill_no',
                                            'patient_billing.discount as discount',
                                            'users.first_name',
                                               'users.last_name'
                                        )
                                        ->where('patient_billing.id',$b_id)
                                        ->first();
            $whatsapp_without_verification = \App\Helpers\HospitalHelper::isSettingEnabled($org_id,'whatsapp_without_verification');

            if(!$whatsapp_without_verification){
                if(!$data->mnvs){
                    return response()->json([
                        'success'=>false,
                        'message'=>'Patient mobile number is not verified.'
                    ]);
                }
            }
            $services = PatientGenBill::where('bill_id',$b_id)->get();

            $payment = BillingPaymentType::where('bill_id',$b_id)
                ->select(
                    'payment_mode',
                    DB::raw('SUM(amount) as amount'),
                )
                ->groupBy('payment_mode')
                ->get()
                ->pluck('amount','payment_mode')->toArray();

            $paymentAmount = array_sum($payment);

            $discount = PatientBilling::select('users.first_name','users.last_name','patient_billing.discount_name')
                                        ->join('users','users.id','patient_billing.discount_auth_by')
                                        ->where('patient_billing.id',$b_id)
                                        ->first();
                            // dd($discount);


            $pdf = PDF::loadView('admin.pdf.patient_bill',['data' => $data,'serviceData'=>$services, 'payments'=>$payment,'discount'=>$discount]);


            if (!file_exists('assets/billing')) {
                mkdir('assets/billing', 0777, true);
            }

            //$pdf = PDF::loadView('admin.pdf.bill');
            $pdfFilename = 'pdf_file_' . $b_id . '.pdf';
            $pdfPath = 'assets/billing/'.$pdfFilename;
            $pdf->save($pdfPath);

            $hospital = Healtcare_org::where('id', $org_id)->first();

            Notifier::bill_complete([
                'patient_id' => $data->patient_id,
                'phone_number' => $data->mobile_no,
                'params' => [
                    'patient_name'=> $data->prefix.' '.$data->Fname.' '.$data->Lname,
                    'bill_amount'=> $paymentAmount,
                    'hospital_name'=>$hospital->name??'',
                    'hospital_contact'=>$hospital->contact_no??'',
                    'link' => $hospital->external_app_link?:url('book-appointment/select-doctor/'.encryptID($hospital->id)),
                    'pdf'=>($pdfPath),
                    ]
                ]);

            return response()->json([
                'success' => true,
                'message' => 'Bill is sent successfully',
            ]);

        }else{
            return response()->json([
                'success' => false,
                'message' => 'Notification not enabled'
            ]);
        }

    }
