    public function ipd_gen_bill(Request $request)
    {
        $user = Auth::user();
        $org_id = $user->org_id;

        if($request->input('action') == 'save_as_draft'){
            $response =  $this->save_as_draft($user,$request);
            return $response;
        }else{

            try {

                DB::beginTransaction();

                $b_id = $request->input('b_id');

                $cc=$request->bill_id;
                if($cc != null)
                {
                    $c=count($cc);
                }
                else{
                    $c=0;
                }

                $regch = ($request->regcharges) ? $request->regcharges : null;
                $docch = ($request->doccharges) ? $request->doccharges : null;

                $bill = PatientBilling::find($b_id);
                $bill->reg_charges = $regch;
                $bill->doc_charges = $docch;
                $bill->subtotal = $request->input('subtotal');
                $bill->discount = $request->input('discount');
                $bill->discount_name= $request->input('discount_name');
                $bill->total = $request->input('total');
                $bill->bill_tag = 'ipd';
                $bill->status = 1;

                $visit= Visitlog::find($bill->visit_id);
                $visit->is_visited =0;
                $visit->save();

                $patient= Patient::find($visit->patient_id);

                $bill->doctor_id = $visit->doctor_id;
                $bill->i_cover = $patient->i_cover;

                $total_collect = $request->input('collectamount');
                $total = $request->input('total');

                if($total_collect < $total){
                    $bill->is_open = 1;
                }

                $bill->created_by = auth()->user()->id;
                $bill->save();

                $paytype = BillingPaymentType::firstOrNew(['bill_id'=>$b_id]);
                $paytype->bill_id = $b_id;
                $paytype->cash = $request->input('paycash');
                $paytype->upi = $request->input('payupi');
                $paytype->debit_card = $request->input('paydebit');
                $paytype->credit_card = $request->input('paycredit');
                $paytype->cash_transId = $request->input('cashtransid');
                $paytype->upi_transId = $request->input('upitransid');
                $paytype->debit_transId = $request->input('debittransid');
                $paytype->credit_transId = $request->input('credittransid');
                $paytype->flag = "ipd";
                $paytype->created_by = auth()->user()->id;
                $paytype->save();

                $patient = Patient::find($bill->patient_id);
                $patient->is_registered =1;
                $patient->save();

                $visitipd = Visitlog::join('ipd_details','ipd_details.visit_table_id','=','visitlog.id')
                                        ->select('ipd_details.id as ipd_no')
                                        ->where('visitlog.id', $bill->visit_id)
                                        ->first();

                $ipd_no = $visitipd->ipd_no;


            PatientGenBill::where('bill_id', $b_id)->delete();
            for ($i = 0; $i < $c; $i++) {
                $serid = !empty($request->service_id[$i]) ? $request->service_id[$i] : null;
                $miscserid = !empty($request->misc_id[$i]) ? $request->misc_id[$i] : null;

                $service = HospitalSer::find($serid);
                if($service && ($service->flag=="package"))
                {
                    $packageService = $service->service;
                    $packageServiceCharge = HospitalServiceCharges::where('hospital_id',$org_id)->where('insurance',$bill->i_cover)->where('service',$service->id)->first()->charges??0;

                    $testIncludes = InvestigationGroupTest::where('group_id', $serid)->orderBy('sequence_no', 'asc')->get();

                    $subTotal = 0;
                    foreach($testIncludes as $test)
                    {
                        $sCharge = HospitalServiceCharges::where('hospital_id',$org_id)->where('insurance',$bill->i_cover)->where('service',$test->test_id)->first();
                        $subTotal += $sCharge->charges??0;

                        $gen= new PatientGenBill;
                        $gen->bill_id = $cc[$i];
                        $gen->service_id = $test->test_id;
                        $gen->misc_service_id = $miscserid;
                        $gen->charges = $sCharge->charges??0;
                        $gen->qty = 1;
                        $gen->amount = $sCharge->charges??0;
                        $gen->created_by = auth()->user()->id;
                        $gen->save();

                        $ipd_gen = new IPDBilling();
                        $ipd_gen->admission_id = $ipd_no;
                        $ipd_gen->uhid = $visit->patient_id;
                        $ipd_gen->hospital_id = $org_id;
                        $ipd_gen->name = $test->test_id;
                        $ipd_gen->charges = $sCharge->charges??0;
                        $ipd_gen->quantity = 1;
                        $ipd_gen->flag = 'diagnostic';
                        $ipd_gen->save();
                    }

                    $bill = PatientBilling::find($b_id);
                    $bill->bill_tag = 'package';
                    $bill->tag_ref_id = $serid;
                    $bill->discount = $bill->discount + ($subTotal - $packageServiceCharge);
                    $bill->save();

                }else{

                    $gen= new PatientGenBill;
                    $gen->bill_id = $cc[$i];
                    $gen->service_id = $serid;
                    $gen->misc_service_id = $miscserid;
                    $gen->charges = $request->charges[$i];
                    $gen->qty = $request->qty[$i];
                    $gen->amount = $request->amount[$i];
                    $gen->created_by = auth()->user()->id;
                    $gen->save();

                    $ipd_gen = new IPDBilling();
                    $ipd_gen->admission_id = $ipd_no;
                    $ipd_gen->uhid = $visit->patient_id;
                    $ipd_gen->hospital_id = $org_id;
                    $ipd_gen->name = $serid;
                    $ipd_gen->charges = $request->charges[$i];
                    $ipd_gen->quantity = $request->qty[$i];
                    $ipd_gen->flag = 'diagnostic';
                    $ipd_gen->save();
                }

            }






            // $doch = Doccharge::find($visit->ch_id);
            // $hosp = User::find($org_id);
            $getbill = PatientBilling::find($b_id);
            $getpaytype = BillingPaymentType::where('bill_id',$b_id)->where('flag','ipd')->first();
            $patient = Patient::find($getbill->patient_id);
            $doctor = Doctor_db::find($getbill->doctor_id);
            $insurance = HealthInsurance::find($patient->i_cover);
            $hospital = Healtcare_org::find($org_id);


        //  return response()->json($insurance);

            $services = PatientGenBill::where('bill_id',$b_id)->get();


            $data["bill_tag"] =  $getbill->bill_tag;
            $data["bill_remark"] =  $getbill->bill_remark??'';
            $data['status'] = $getbill->status;


        $services = PatientGenBill::where('bill_id',$b_id)->get();
        $discountAuthPerson = User::find($request->discount_auth_by??0);




            if($getbill->bill_tag == 'package'){
                $packageService = HospitalSer::find($getbill->tag_ref_id);
                $data['package_name'] = $packageService->service;
            }

            $data["bill_package"] =  $packageService??'';
            $data["bill_package_charges"] =  $packageServiceCharge??'';
            $data["hospital"] =  $hospital->name;
            $data["hospital_address"] =  $hospital->address;
            $data["hospital_phone"] =  $hospital->mobile;
            $data['logo'] = $hospital->logo;
            $data["mr"] = $patient->id;
            $data["prefix"] = $patient->prefix;
            $data["fname"] = $patient->Fname;
            $data["lname"] = $patient->Lname;
            $data["gender"] = $patient->sex;
            $data["age"] = $patient->age;
            $data["doctor"] = $doctor->name;
            $data["bill_no"] = $b_id;
            $data["insurance"] = $insurance->insurance_agen;
            $data["staff"] = ($user->first_name??"") . " " . ($user->last_name??"");
            $data["discount_authorized_by"] = ($discountAuthPerson) ? ($discountAuthPerson->first_name??"") . " " . ($discountAuthPerson->last_name??"") : '';
            $data['regch'] = $getbill->reg_charges;
            $data['docch'] = $getbill->doc_charges;
            $data['docchnm'] = ""; //$doch->comment;
            $data['created_at'] = $getbill->created_at;


            $serviceData = [];
            foreach ($services as $service) {
                if($service->service_id != null){
                    $sname = HospitalSer::find($service->service_id);
                    $ser = $sname->service;
                    $ser_id = $sname->id;
                }
                else
                { $misc = MiscellaneousCharges:: find($service->misc_service_id);
                   $ser = $misc->name;
                   $ser_id = $misc->id;
                }

                $serviceData[] = [
                    'ser_id' => $ser_id,
                    'service' => $ser,
                    'qty' => $service->qty,
                    'charges' => $service->charges,
                    'amount' => $service->amount,
                ];
            }
           // $data["services"] = $serviceData;
            $data["subtotal"] = $getbill->subtotal;
            $data["discount"] = number_format((float)$getbill->discount, 2, '.', '');
            $data["total"] = $getbill->total;
            $data["cash"] = $getpaytype->cash;
            $data["upi"] = $getpaytype->upi;
            $data["debit"] = $getpaytype->debit_card;
            $data["credit"] = $getpaytype->credit_card;
            $data['total_paid'] = ($getpaytype->cash??0) + ($getpaytype->upi??0) + ($getpaytype->debit_card??0);
            $pdf = PDF::loadView('admin.pdf.patient_bill',['data' => $data,'serviceData'=>$serviceData]);


        // download PDF file with download method
        // return $pdf->stream('pdf_file.pdf');
            if (!file_exists('assets/billing')) {
                mkdir('assets/billing', 0777, true);
            }

        //$pdf = PDF::loadView('admin.pdf.bill');
            $pdfFilename = 'pdf_file_' . $b_id . '.pdf';
            $pdfPath = 'assets/billing/'.$pdfFilename;
            $pdf->save($pdfPath);


            Notifier::bill_complete([
                'patient_id' => $patient->id,
                'phone_number' => $patient->mobile_no,
                'params' => [
                    'patient_name'=> $patient->prefix.' '.$patient->Fname.' '.$patient->Lname,
                    'bill_amount'=> $getbill->total,
                    'hospital_name'=>$hospital->name??'',
                    'hospital_contact'=>$hospital->contact_no??'',
                    'link' => $hospital->external_app_link?:url('book-appointment/select-doctor/'.encryptID($hospital->id)),
                    'pdf'=>($pdfPath),
                    ]
                ]);
            DB::commit();

        return response()->json(['message' =>"Service Charges Saved Successfully",  'pdf_url' => url($pdfPath)], 200);

        }catch (\Exception $e) {
            DB::rollback(); // Rollback the transaction if an error occurs
            throw $e;
        }
        }
    }



    public function save_as_draft($user, $request){
        $b_id = $request->input('bill_id');

        if(isset($b_id) && !empty($b_id)){
            $status = 0;
            $res = $this->save_edited_bill($request, $status);

            return response()->json(['message' =>"Draft Bill Updated Successfully"], 200);
        }

        dd($b_id);

        $pi = Visitlog::join('pi', 'pi.id', '=', 'visitlog.patient_id')
                                    ->select('i_cover', 'visitlog.doctor_id')
                                    ->where('visitlog.id', '=', $request->visit_id)
                                    ->firstOrFail($request->visit_id);
        $i_cover = $pi->i_cover;
        $doctor_id = $pi->doctor_id;


        $lastBill = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                                ->select('visitlog.visit_status','patient_billing.*')
                                ->where('visitlog.visit_status',0)
                                ->orderBy('patient_billing.id','DESC')
                                ->first();
        $receipt_no = ($lastBill && $lastBill->receipt_no) ? $lastBill->receipt_no + 1 : 1;

        $bill = new PatientBilling;
        $bill->visit_id = $request->visit_id;
        $bill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($bill->visit_id);
        $bill->i_cover = $i_cover;
        $bill->receipt_no = $receipt_no;
        $bill->discount = $request->input('discount');
        $bill->status = 0;
        $bill->discount = $request->discount;
        if($request->discount != null){
            $bill->discount_auth_by = $request->discount_auth_by;
        }
        $bill->created_by = auth()->user()->id;
        $bill->save();


        foreach ($request->payment as $key => $amount) {
            if ($amount > 0) {
                // Check if a record with the same bill_id and payment_mode exists
                $payment = BillingPaymentType::firstOrNew([
                    'bill_id' => $bill->id,
                    'payment_mode' => $key,
                ]);

                $payment->amount = $amount;
                $payment->transaction_id = $request->trx[$key] ?? null;
                $payment->created_by = auth()->user()->id;
                $payment->save();
            }
        }

        PatientGenBill::where('bill_id', $bill->id)->update(['is_deleted'=>1]);
        foreach($request->service_id as $i=>$ser_id){
                $gen= new PatientGenBill;
                $gen->bill_id = $bill->id;
                $gen->service_id = $ser_id;
                $gen->charges = $request->charges[$i];
                $gen->qty = $request->qty[$i];
                $gen->doctor_id = $doctor_id;
                $gen->i_cover = $i_cover;
                $gen->created_by = auth()->user()->id;
                $gen->save();
        }



        return response()->json(['status'=>'success','message'=>'Draft saved successfully...','bill_id'=>$bill->id]);

    }


    public function patient_search(Request $request)
    {

        $request->validate([
            'q' => 'required|string',
        ]);

        $q = trim($request->q);

        $patients = Patient::select(
            'id',
            'Fname as fname',
            'Lname as lname',
            'age',
            'dob',
            'sex'
        );

        // Case 1: 10-digit phone number
        if (preg_match('/^\d{10}$/', $q)) {
            $patients->where('mobile_no', $q);
        }
        // Case 2: Numeric (ID)
        elseif (is_numeric($q)) {
            $patients->where('id', $q);
        }
        // Case 3: Name search (Fname + Lname)
        else {
            $patients->whereRaw(
                "CONCAT(TRIM(Fname), ' ', TRIM(Lname)) LIKE ?",
                ['%' . $q . '%']
            );
        }

        return response()->json([
            'success' => true,
            'patients' => $patients->limit(20)->get()
        ]);
    }
