    public function patient_advsearch(Request $request)
    {
        $user = Auth::user();
        $org_id = $user->org_id;

        $users = Patient::query();

     // print_r($request->dob);
        $fname = $request->firstname;
        $lname = $request->lname;
        $email = $request->email;
        $mobile = $request->mobile;
        $gender = $request->gender;
        $age = $request->age;
        $dob = $request->dob;
        $i_cover = $request->i_cover;
        $fathername = $request->fathername;
        $spousename = $request->spousename;
        $gname = $request->gname;
        $whatsno = $request->whatsno;


        // Check if no search parameters are provided
    if (!$fname && !$lname && !$email && !$mobile && !$gender && !$age && !$dob && !$i_cover && !$fathername && !$spousename && !$gname && !$whatsno) {
        return response()->json(['success' => true, 'message' => 'No data found!', 'data' => []]);
    }
    if (!$fname && !$mobile && !$gender) {
        return response()->json(['success' => true, 'message' => 'No data found!', 'data' => []]);
    }

        if ($fname) {
            $users->where('Fname','LIKE','%'.$fname.'%');
        }
       if ($lname) {
            $users->where('Lname','LIKE','%'.$lname.'%');
        }
        if ($email) {
            $users->where('email_id','LIKE','%'.$email.'%');
        }
        if ($mobile) {
            $users->where('mobile_no',$mobile);
        }

        if ($gender) {
            $users->where('sex','LIKE','%'.$gender.'%');
        }

        if ($age) {
            $users->where('age',$age);
        }
        if ($dob) {
            $users->where('dob','LIKE','%'.$dob.'%');
        }
        if ($i_cover) {
            $users->where('i_cover','LIKE','%'.$i_cover.'%');
        }
        if ($fathername) {
            $users->where('Fathername','LIKE','%'.$fathername.'%');
        }
        if ($spousename) {
            $users->where('spousename','LIKE','%'.$spousename.'%');
        }
        if ($gname) {
            $users->where('guardian_name','LIKE','%'.$gname.'%');
        }
        if ($whatsno) {
            $users->where('whats_app_no',$whatsno);
        }

        $users->where('hospital_id',$org_id);
        $users->leftjoin('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')->select('health_insurance_agen.insurance_agen','pi.*');


        $users = $users->get();

        $hasAbdmLicense = \App\Helpers\LicenseKey::isModuleActiveAndValid('abha', (int)$org_id);

        return response()->json([
            'success' => true,
            'message' => 'Adjustment saved successfully!',
            'data' => $users,
            'has_abdm_license' => $hasAbdmLicense,
        ]);
    }


    public function getpatient_details($id, $tid=null)
    {
        $user = Auth::user();
        $org_id = $user->org_id;

        $searchVal = trim($id);
        $cleanAbha = str_replace('-', '', $searchVal);
        $cleanDigits = preg_replace('/\D/', '', $searchVal);

        $patient = Patient::where('hospital_id', $org_id)
            ->where(function ($q) use ($searchVal, $cleanAbha, $cleanDigits) {
                $q->where('id', $searchVal)
                  ->orWhere('uhid', $searchVal)
                  ->orWhere('abha_number', $searchVal)
                  ->orWhere('abha_address', $searchVal)
                  ->orWhere('abha_add', $searchVal);

                if (!empty($cleanAbha) && $cleanAbha !== $searchVal) {
                    $q->orWhere('abha_number', $cleanAbha);
                }

                if (strlen($cleanDigits) === 10) {
                    $q->orWhere('mobile_no', $cleanDigits)
                      ->orWhere('phone', $cleanDigits)
                      ->orWhere('whats_app_no', $cleanDigits);
                }
            })
            ->first();

        if($patient){

            $insu = HealthInsurance::find($patient->i_cover);
            if(!$insu){
                return response()->json([
                    'success' => false,
                    'message' => 'Insurance not found'
                ]);
            }

            $sms_status = (SmsSetting::where('status',1)->count())>0 ? 1:0;

            if($sms_status){
                $sms_status = Notifier::is_enabled('registration_otp');
            }

         $last_visit = Visitlog::join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                ->select('visitlog.*', 'doctor_db.name as doctor_name')
                                ->where('visitlog.patient_id', $patient->id)
                                ->where('visitlog.hospital_id', $org_id)
                                ->latest()
                                ->first();

            if ($last_visit) {
                $givenDate = Carbon::parse($last_visit->created_at);
                $today = Carbon::today();
                $daysDifference = $today->diffInDays($givenDate);
                $note = 'Last Visit: '. $daysDifference . ' days ago (' . $last_visit->doctor_name . ')';
            } else {
                $daysDifference = "";
                $note = "";

            }
            $ipdVisit = Visitlog::where('patient_id', $patient->id)->where('visit_status', 1)->first();
            if($ipdVisit){
                $ipd = \App\Models\admin\Ipd_details::leftJoin('room_type', 'room_type.id', '=', 'ipd_details.bed_type')
                        ->join('visitlog', 'visitlog.id', '=', 'ipd_details.visit_table_id')
                        ->join('patient_billing', 'patient_billing.visit_id', '=', 'visitlog.id')
                        ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                        ->join('health_insurance_agen','health_insurance_agen.id','=','ipd_details.i_cover')
                        ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                        ->where('ipd_details.visit_table_id',$ipdVisit->id)
                        ->select([
                                'ipd_details.*',
                                'patient_billing.id as bill_id',
                                'visitlog.admission_date as admission_date',
                                'visitlog.admission_time as admission_time',
                                'visitlog.dd2 as discharge_date',
                                'visitlog.discharge_time as discharge_time',
                                'doctor_db.name as doctor_name',
                                'health_insurance_agen.insurance_agen as insurance_name',
                                DB::raw('COALESCE(room_type.room_type, "N/A") as bed_type'),
                                'doctor_specialities.name as department'
                        ])
                        ->first();

                $packagesService = PatientGenBill::join('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                    ->where('hospital_services.flag','package')
                                    ->where('patient_gen_bill.bill_id', $ipd->bill_id??0)
                                    ->where('patient_gen_bill.is_deleted', 0)
                                    ->get();

                $procedureService = PatientGenBill::join('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                    ->where('hospital_services.flag','procedure')
                                    ->where('patient_gen_bill.bill_id', $ipd->bill_id??0)
                                    ->where('patient_gen_bill.is_deleted', 0)
                                    ->get();

                $ipd->packagesService = $packagesService;
                $ipd->procedureService = $procedureService;
                $ipd->ipd_category = \App\Helpers\HospitalHelper::ipdCategory(auth()->user()->org_id,$ipd->id);


                if($tid){
                  $ipd->ipd_doc =  IpdDocument::where('template_id', $tid)->where('ipd_no', $ipd->id)->first();
                }

            }



           $todayDraftBills = PatientBilling::join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                                            ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')

                                            ->select('patient_billing.*','doctor_db.name as doctor_name')
                                            ->where('visitlog.patient_id', $patient->id)
                                            ->where('patient_billing.status', 0)
                                            ->whereDate('patient_billing.created_at', today())

                                            ->where(function($query) {
                                                $query->where('patient_billing.is_cancelled', '!=', 1)
                                                        ->orWhereNull('patient_billing.is_cancelled'); // Allow NULL values
                                            })
                                            ->get();




            $others = is_array($patient->others) ? $patient->others : (json_decode($patient->others ?: '{}', true) ?: []);
            $patient->has_demographic_history = !empty($others['abdm_demographic_history']);
            $patient->history_count = count($others['abdm_demographic_history'] ?? []);

            return response()->json([
                'success' => true,
                'sms_status' => $sms_status,
                'patient' => [
                    'id' => $patient->id,
                    'prefix' => $patient->prefix,
                    'fname' => $patient->Fname,
                    'lname' => $patient->Lname,
                    'Fathername' => $patient->Fathername,
                    'spuosename' => $patient->spousename,
                    'age' => $patient->age,
                    'dob' => $patient->dob,
                    'sex' => $patient->sex,
                    'i_cover' => $insu->insurance_agen??""
                ],
                'data' => $patient,
                'last_visit' => $last_visit,
                'last_visit_days' => $note,
                'ipd' => $ipd??null,
                'today_draft_bills' => $todayDraftBills
            ]);
        }else{
            return response()->json([
                'success' => false,
                'message' => 'No record found'
            ]);
        }
    }

    public function bill_list($id)
    {
        $bill = PatientBilling::join('visitlog','visitlog.id','=','patient_billing.visit_id')
                ->join('pi','pi.id','=','visitlog.patient_id')
                ->join('doctor_db','doctor_db.id','=','visitlog.doctor_id')
                ->leftJoin('users','users.id','=','patient_billing.created_by')
                ->join('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                ->leftJoin(
                    DB::raw('(SELECT bill_id, SUM(amount) AS total_payment FROM billing_payment_type GROUP BY bill_id) as billing_totals'),
                    'billing_totals.bill_id',
                    '=',
                    'patient_billing.id'
                )
                ->leftJoin(
                    DB::raw('(SELECT bill_id, SUM(charges*qty-discount) AS subtotal,
                     SUM(
                            (
                                (charges * qty - IFNULL(discount, 0))
                                * (
                                    IFNULL(cgst, 0)
                                    + IFNULL(sgst, 0)
                                    + IFNULL(igst, 0)
                                ) / 100
                            )
                        ) AS total_tax
                    FROM patient_gen_bill WHERE is_deleted = 0 GROUP BY bill_id) as gen_totals'),
                    'gen_totals.bill_id',
                    '=',
                    'patient_billing.id'
                )
                ->select('pi.Fname','pi.Lname','pi.prefix','pi.sex','pi.age','pi.id as uhid',
                        'doctor_db.name as doctor_name',
                        'health_insurance_agen.insurance_agen',
                        'patient_billing.id as bill_id',
                        'patient_billing.*',
                        'patient_billing.*',
                        'patient_billing.created_at',
                        DB::raw('CONCAT(users.first_name," ",users.last_name) as collected_by'),
                            DB::raw('IFNULL(billing_totals.total_payment, 0) as total'),
                            DB::raw('IFNULL(gen_totals.subtotal, 0) as subtotal'),
                            DB::raw('IFNULL(gen_totals.total_tax, 0) as total_tax')
                        )
                        ->groupBy('patient_billing.id')
                        ->where('patient_billing.visit_id', $id)
                        ->get();

        return response()->json(['success' => true, 'data'=>$bill]);
    }

