                                            ->leftJoin('users as discount_auth','users.id','=','patient_billing.discount_auth_by')
                                            ->select(
                                                'pi.id as patient_id',
                                                'pi.prefix as prefix',
                                                'pi.Fname as Fname',
                                                'pi.Lname as Lname',
                                                'pi.sex as gender',
                                                'pi.age as age',
                                                'pi.mobile_no as mobile_no',
                                                'doctor_db.name as doctor_name',
                                                'pi.i_cover as i_cover',
                                                'health_insurance_agen.insurance_agen as insurance',
                                                'patient_billing.created_at as created_at',
                                                'patient_billing.status as status',
                                                'patient_billing.id as bill_no',
                                                'patient_billing.discount as discount',
                                                'users.first_name',
                                                'users.last_name',
                                                'patient_billing.receipt_no',
                                                DB::raw('CONCAT(discount_auth.first_name," ",discount_auth.last_name) as discount_by'),
                                            )
                                            ->where('patient_billing.id',$id)
                                            ->first();

        $discount = PatientBilling::select('users.first_name','users.last_name','patient_billing.discount_name')
                                    ->join('users','users.id','patient_billing.discount_auth_by')
                                    ->where('patient_billing.id',$id)
                                    ->first();


        $bill = view('admin.pdf.refund_bill',['data' => $data,'serviceData'=>$services,'payments'=>$payment,'transaction_type'=>$transaction_type,
                                                'ref_bill'=>$ref_bill,'discount'=>$discount])->render();
        return $bill;
    }


    public function bill_cancel_request(Request $request){
               $bills = BillCancelRequest::join('patient_billing','patient_billing.id','=','bills_cancel_request.bill_id')
                                            ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                            ->join('pi','pi.id','=','visitlog.patient_id')
                                            ->select(
                                                'pi.prefix','pi.Fname','pi.Lname',
                                                'pi.id as uhid',
                                                'bills_cancel_request.id as req_id',
                                                'bills_cancel_request.created_at',
                                                'bills_cancel_request.status',
                                                'patient_billing.id as bill_id',
                                                'bills_cancel_request.services',
                                                'bills_cancel_request.created_by',
                                                'bills_cancel_request.remarks'
                                            );

                    if($request->type != 'allPending'){
                        if ($request->start_date && $request->end_date) {
                            $bills->whereBetween(DB::raw('DATE(bills_cancel_request.created_at)'), [$request->start_date, $request->end_date]);
                        }else{
                            $bills->whereBetween(DB::raw('DATE(bills_cancel_request.created_at)'), [date('Y-m-d'), date('Y-m-d')]);
                        }

                        if (!empty($request->type) && $request->type != 'all' && $request->type != 'allPending') {
                            $bills->where('bills_cancel_request.status', $request->type);
                        }
                    }else{
                        if(!empty($request->type) && $request->type == 'allPending'){
                          $bills->where('bills_cancel_request.status', 'pending');
                        }
                    }


                    $bills = $bills->orderBy('bills_cancel_request.created_at', 'DESC')->get();

            return view('admin.patient.billing.cancel_bill_request' , compact('bills'));

    }


    public function update_status_cancel_req(Request $request){
        $status = $request->status;
        $req_id = $request->id;

          BillCancelRequest::where('id',$req_id)->update(['status'=>$status,'updated_by'=>auth()->user()->id]);

          return response()->json(['status'=>'success','message'=>'Status updated successfully']);
    }


    public function bill_show_v2($id)
