                    )
                    ->groupBy('payment_mode')
                    ->orderBy('id')
                    ->where('amount','!=',0)
                    ->get();

                    // dd($payment);
        $bill = PatientBilling::leftJoin('users','users.id','=','patient_billing.created_by')
