    public function vital_visit_add(Request $request, $id=null)
    {

        $org_id = Auth::user()->org_id;
        $today_visit_list = $this->today_visit_list($request);

        if(!$id){
            $id = $today_visit_list[0]->id;
        }
        $visit = visitlog::find($id);

       $visit_id = $id;
       $comments =  ClinicalComment::select('comment','context')->where('user_id', $visit->doctor_id)->orderBy('id','DESC')->get();

       $quick_icd = ClinicalComment::join('icd_codes','icd_codes.id','=','clinical_comments.comment')
                                    ->select('icd_codes.icd_name','icd_codes.icd_code','clinical_comments.comment','clinical_comments.created_at','icd_codes.id as id')
                                    ->where('user_id', $visit->doctor_id)
                                    ->where('context','icd_code')
                                    ->get();

        $vcd = VisitClinicalData::where('visit_id',$visit_id)->first();
        $cc = json_decode(optional($vcd)->cc, true) ?? [];
        $diagnosis = json_decode(optional($vcd)->diagnosis, true) ?? [];
        $others = json_decode(optional($vcd)->others, true) ?? [];
        $pef = json_decode(optional($vcd)->physical_examination_finding, true) ?? [];
        $by_when = $vcd->by_when??'';
        $by_when_sel = $vcd->by_when_type??'';


        $medicines = DB::table('pres_final as d')
                            ->leftJoin('drug_comb_brand_index as cc', function ($join) {
                                $join->on('d.brand_id', '=', 'cc.id')
                                    ->where('d.d_type', '=', 'cc');
                            })
                            ->leftJoin('drug_brand_index as ss', function ($join) {
                                $join->on('d.brand_id', '=', 'ss.id')
                                    ->where('d.d_type', '=', 'ss');
                            })
                            ->select(
                                'd.*',
                                DB::raw("CASE
                                            WHEN d.d_type = 'cc' THEN cc.brand_name
                                            WHEN d.d_type = 'ss' THEN ss.brand_name
                                            ELSE NULL
                                        END as name")
                            )
                            // ->having('name', 'LIKE', "%{$query}%")
                            ->where('visit_table_id', $visit_id)
                            // ->groupBy('d.brand_id')
                            ->orderBy('d.id', 'asc')
                            ->get();


            $q_medicines = DB::table('doc_drug_used_brands as d')
                            ->leftJoin('drug_comb_brand_index as cc', function ($join) {
                                $join->on('d.brand_id', '=', 'cc.id')
                                    ->where('d.d_type', '=', 'cc');
                            })
                            ->leftJoin('drug_brand_index as ss', function ($join) {
                                $join->on('d.brand_id', '=', 'ss.id')
                                    ->where('d.d_type', '=', 'ss');
                            })
                            ->select(
                                'd.*',
                                DB::raw("CASE
                                            WHEN d.d_type = 'cc' THEN cc.brand_name
                                            WHEN d.d_type = 'ss' THEN ss.brand_name
                                            ELSE NULL
                                        END as name")
                            )
                            // ->having('name', 'LIKE', "%{$query}%")
                            ->where('d.doctor_id', $visit->doctor_id)
                            // ->groupBy('d.brand_id')
                            ->orderBy('d.id', 'asc')
                            ->get();

                foreach($q_medicines as $r){
                                //  $r->formulation1 = $this->get_formulation($r->brand_id, $r->d_type);
                                $formulation = $this->get_formulation($r->brand_id, $r->d_type);

                                if($r->d_type == 'ss'){
                                    foreach($formulation as $f){
                                        $form = $f->form;
                                        $dose = $f->dose;
                                        $unit = $f->unit_name;
                                        $drug = $f->drug_name;

                                        $r->formulation = $drug.' '.$dose.' '.$unit.' ('.$form.')';

                                    }
                                }else{
                                    foreach($formulation as $f){
                                        $form = $f->form;

                                        $strArray = [];
                                        foreach($f->comb_name as $cn){
                                            $formulation = $cn->drug_name;
                                            $dose = $cn->dose;
                                            $unit_name = $cn->unit_name;

                                            $strArray[] = $formulation. ' '.$dose.' '.$unit_name;
                                        }
                                        $str = implode(' + ', $strArray);
                                        $r->formulation = $str.'('.$form.')';
                                    }
                                }
                            }

        $testr = InvestigationRequest::join('hospital_services', 'hospital_services.id', '=', 'investigation_request.service_id')
                                        ->select('investigation_request.*', 'hospital_services.service')
                                        ->where('visit_id', $visit_id)
                                        ->get();
            // return $testr;
        $icd =  PatientICDData::leftjoin('icd_codes','icd_codes.icd_code','=','patient_icd_data.icd_code')
                                ->where('patient_icd_data.visit_table_id', $visit_id)
                                ->get();
        // return $icd;

        $vitals = Vitals::where('visit_id', $visit_id)->first();
        if(is_null($vitals)){
            $bp = [];
            $pulse = [];
        }else{
            $bp = json_decode($vitals->bp, true) ?? [];
            $pulse = json_decode($vitals->pulse, true) ?? [];
            $bp = end($bp);
            $pulse = end($pulse);
        }
        // return $q_medicines;

        $HospitalDoctor = HospitalDoctor::where('doc_id', $visit->doctor_id)->where('org_id', $org_id)->first();

        $others2 = json_decode(optional($HospitalDoctor)->others, true) ?? [];

        $search_type = $others2['search_type'];
        // return $icd;

        // vaccination part started......

        // fetch vaccines -


        $week_array = VacSchedule::select('id', 'name', 'valid_name','key')
                                    ->get()
                                    ->mapWithKeys(function ($item) {
                                        return [$item->id => ['name' => $item->name, 'valid_name' => $item->valid_name,'key' => $item->key]];
                                    })
                                    ->toArray();


            $vac_chart = DB::table('vac_chart')
                                ->leftJoin('drugs', function ($join) {
                                    $join->on('vac_chart.vac_id', '=', 'drugs.id')
                                        ->where('vac_chart.d_type', '=', 'ss');
                                })
                                ->leftJoin('drug_comb', function ($join) {
                                    $join->on('vac_chart.vac_id', '=', 'drug_comb.id')
                                        ->where('vac_chart.d_type', '=', 'cc');
                                })
                                ->select(
                                    'vac_chart.*',
                                    DB::raw('CASE
                                                WHEN vac_chart.d_type = "ss" THEN drugs.drug_name
                                                WHEN vac_chart.d_type = "cc" THEN drug_comb.name
                                            END as name')
                                )
                                // ->where('type', 0)
                                ->get();


        // $others_vac = VacChart::where('type', 1)->get();


        // return $vac_chart;
        $patient = Patient::find($visit->patient_id);

        $data = compact('visit','patient','medicines','visit_id','cc','diagnosis','quick_icd','comments','icd','others','pef','testr',
                        'vitals','bp','pulse','q_medicines','search_type','by_when','by_when_sel','vac_chart','week_array'
                        );
        return view('admin.patient.visit_vital_add')->with($data);
    }


