    public function nursing_vitals(Request $request, $id = null, $t_id = null) {
        $visits = $this->ipd_visit_list($request);
        $context = FacadesRoute::currentRouteName();
        $formData = [];

        if (!empty($id)) {
            $visit_id = $id;
        } else {
            return view('admin.patient.clinical.nursing_vitals', compact('visits', 'context', 'formData'));
        }

        $visit_id = $id;
        $v = Visitlog::where('id', $visit_id)->select('doctor_id as did')->first();
        if (!$v) {
            return view('admin.patient.clinical.nursing_vitals', compact('visits', 'context', 'formData'));
        }
        $did = $v->did;

        $patient = Patient::join('visitlog', 'visitlog.patient_id', '=', 'pi.id')
                             ->leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                             ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                             ->leftJoin('ipd_details', 'ipd_details.visit_table_id', '=', 'visitlog.id')
                             ->select('pi.*', 'visitlog.doctor_id',
                                         'doctor_db.name as doctor_name',
                                         'visitlog.fud','visitlog.edit_lock',
                                         'visitlog.created_at as created_at',
                                         'doctor_specialities.id as spid',
                                         'doctor_db.id as did',
                                         'visitlog.ad2',
                                         'visitlog.dd2',
                                         'visitlog.at1',
                                         'visitlog.dt1',
                                         'doctor_db.key_spec',
                                         'ipd_details.id as ipd_no',
                                         'ipd_details.ward',
                                         'ipd_details.bed_no'
                             )
                             ->where('visitlog.id', $visit_id)
                             ->first();

        $vcd = \App\Models\VisitClinicalData::where('visit_id', $visit_id)
                                            ->where('context', 'clinical.nursing_notes')
                                            ->first();
        $nursingNotes = [];
        if ($vcd && $vcd->ot_data) {
            $nursingNotes = json_decode($vcd->ot_data, true) ?? [];
        }

        $vitalLock = $this->vitalLock;
        if ($request->ajax()) {
            return view('admin.patient.clinical.nursing_vitals_flowsheet', compact('visit_id', 'visits', 'patient', 'context', 'formData', 'nursingNotes', 'vitalLock'));
        }

        $visitLog = Visitlog::find($visit_id);
        $org_id = auth()->user()->org_id;
        $service = HospitalService::join('hospital_services','hospital_services.id','=','hospital_services_index.service')
                                    ->join('hospital_service_charges','hospital_service_charges.service','=','hospital_services_index.service')
                                    ->where('hospital_services_index.hospital_id',$org_id)
                                    ->where('hospital_service_charges.hospital_id',$org_id)
                                    ->where('hospital_services_index.active',1)
                                    ->where('hospital_service_charges.insurance',$patient->i_cover)
                                    ->where('hospital_service_charges.is_active',1)
                                    ->select('hospital_services.*')
                                    ->get();

        $doctors = HospitalDoctor::join('doctor_db', 'doctor_db.id', '=', 'org_doc_index.doc_id')
                                    ->where('org_doc_index.org_id', Auth::user()->org_id)
                                    ->where('org_doc_index.active', 1)
                                    ->select('doctor_db.id','doctor_db.name')
                                    ->get();

        $con_req = DoctorConsultationReq::join('doctor_db','doctor_db.id','=','doctor_consultation_request.doctor_id')
                                         ->select('doctor_consultation_request.*','doctor_db.name')
                                         ->where('doctor_consultation_request.visit_id',$visit_id)
                                         ->get();

        $serviceOrdered = \App\Models\IpdServiceRequest::where('visit_id',$visit_id)->get();
        $itemsRequested = \App\Models\InventoryBillingRequest::where('visit_id', $visit_id)->get();



        $matching_visit_ids = DB::table('visitlog')
            ->where('patient_id', $visitLog->patient_id)
            ->where('created_at', '>=', $visitLog->created_at)
            ->pluck('id')
            ->toArray();

        $matching_billing_ids = DB::table('patient_billing')
            ->whereIn('visit_id', $matching_visit_ids)
            ->pluck('id')
            ->toArray();

        $serviceDoneQuery = PatientGenBill::join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
            ->leftJoin('lab_investigations', 'lab_investigations.lab_order_id', '=', 'patient_gen_bill.id')
            ->leftJoin('patient_billing', 'patient_billing.id', '=', 'patient_gen_bill.bill_id')
            ->whereIn('patient_gen_bill.bill_id', $matching_billing_ids)
            ->where('patient_gen_bill.is_deleted', 0)
            ->select(
                'patient_gen_bill.*',
                'hospital_services.service as service_name',
                'hospital_services.flag as flag',
                'lab_investigations.status as status',
                'patient_billing.visit_id as visit_id'
            );

        $flags = [
            'investigations' => 'test',
            'procedures' => 'procedure',
            'radiology' => 'radiology'
        ];

        foreach ($flags as $key => $flag) {
            $investigations[$key] = (clone $serviceDoneQuery)->where('hospital_services.flag', $flag)->get();
            if($investigations[$key]->isEmpty()){
                unset($flags[$key]);
            }
        }

        return view('admin.patient.clinical.nursing_vitals', compact('visit_id', 'visits', 'patient', 'context', 'formData', 'nursingNotes', 'visitLog','doctors', 'con_req', 'service', 'serviceOrdered', 'itemsRequested','flags','investigations', 'vitalLock'));
    }

