   public function update_notes_doctor(Request $request)
    {
        $request->validate([
            'visit_id' => 'required|integer',
            'context' => 'required',
            'index' => 'required|integer',
            'doctor_id' => 'required|integer',
        ]);

        $record = VisitClinicalData::where('visit_id',$request->visit_id)->where('context', $request->context)->first();

        $notes = json_decode($record->ot_data, true);

        if (!is_array($notes)) {
            return response()->json([
                'status' => false,
                'message' => 'Invalid notes data.'
            ], 422);
        }

        if (!isset($notes[$request->index])) {
            return response()->json([
                'status' => false,
                'message' => 'Invalid note index.'
            ], 422);
        }

        $notes[$request->index]['doctor_id'] = $request->doctor_id;

        $record->ot_data = json_encode($notes);
        $record->save();

        return response()->json([
            'status' => 'success',
            'message' => 'Doctor updated successfully.'
        ]);
    }

