    private function getFlowsheetSlotHourStr($createdAtStr) {
        try {
            $noteTime = \Carbon\Carbon::parse($createdAtStr);
            $minutes = (int)$noteTime->format('i');
            $seconds = (int)$noteTime->format('s');
            if ($minutes > 0 || $seconds > 0) {
                $noteTime->setTime((int)$noteTime->format('H'), 0, 0);
                $noteTime->modify('+1 hour');
            } else {
                $noteTime->setTime((int)$noteTime->format('H'), 0, 0);
            }
            return $noteTime->format('Y-m-d H');
        } catch (\Exception $e) {
            return null;
        }
    }

    private function notesMatch($existingNote, $incomingNote) {
        if (!isset($existingNote['created_at']) || !isset($incomingNote['created_at'])) {
            return false;
        }

        if ($existingNote['created_at'] === $incomingNote['created_at']) {
            return true;
        }

        try {
            $existingTime = \Carbon\Carbon::parse($existingNote['created_at'])->format('Y-m-d H:i');
            $incomingTime = \Carbon\Carbon::parse($incomingNote['created_at'])->format('Y-m-d H:i');
            if ($existingTime === $incomingTime) {
                return true;
            }
        } catch (\Exception $e) {}

        try {
            $exSlot = $this->getFlowsheetSlotHourStr($existingNote['created_at']);
            $inSlot = $this->getFlowsheetSlotHourStr($incomingNote['created_at']);
            if ($exSlot && $inSlot && $exSlot === $inSlot) {
                return true;
            }
        } catch (\Exception $e) {}

        return false;
    }

    public function save_ipd_notes(Request $request)
    {
        $visit_id = $request->visit_id;

        $rawNotes = $request->notes ?? [];
        ksort($rawNotes);
        $incomingNotes = array_values($rawNotes);

        // Filter out notes without a valid created_at date
        $incomingNotes = array_filter($incomingNotes, function($note) {
            return !empty($note['created_at']);
        });
        $incomingNotes = array_values($incomingNotes);

        $vcd = VisitClinicalData::where('visit_id', $visit_id)->where('context',$request->context)->first();
        if(!$vcd){
            $vcd = new VisitClinicalData;
            $vcd->visit_id = $visit_id;
        }

        $existingNotes = json_decode($vcd->ot_data, true) ?? [];
        // Filter out existing notes without a valid created_at date
        $existingNotes = array_filter($existingNotes, function($note) {
            return !empty($note['created_at']);
        });
        $existingNotes = array_values($existingNotes);

        // Preprocess incoming notes to preserve or set created_by and actual_created_at
        $processedNotes = [];
        foreach ($incomingNotes as $incomingNote) {
            $existingNote = null;
            foreach ($existingNotes as $extNote) {
                if ($this->notesMatch($extNote, $incomingNote)) {
                    $existingNote = $extNote;
                    break;
                }
            }

            if ($existingNote) {
                if (isset($existingNote['actual_created_at'])) {
                    $incomingNote['actual_created_at'] = $existingNote['actual_created_at'];
                }
                if (isset($existingNote['created_by'])) {
                    $incomingNote['created_by'] = $existingNote['created_by'];
                }
            } else {
                if (!isset($incomingNote['actual_created_at'])) {
                    $incomingNote['actual_created_at'] = now()->format('Y-m-d H:i:s');
                }
                if (!isset($incomingNote['created_by'])) {
                    $incomingNote['created_by'] = auth()->id();
                }
            }
            $processedNotes[] = $incomingNote;
        }
        $notes = $processedNotes;

        $freeTextboxData = $request->input('freeTextbox', []);

        // Add updated_at timestamp for each field
        $currentTime = now()->format('Y-m-d H:i:s'); // Get the current timestamp

        $formattedData = [];
        foreach ($freeTextboxData as $key => $value) {
            $formattedData[$key] = [
                'value' => $value,
                'updated_at' => $currentTime
            ];
        }

        if ($request->has('investigations')) {
            $formattedData['investigations'] = [
                'value' => $request->input('investigations'),
                'updated_at' => $currentTime
            ];
        }

        // Convert to JSON format
        $jsonData = json_encode($formattedData, JSON_PRETTY_PRINT);

        $vcd->others = $jsonData;
        $vcd->ot_data =  json_encode($notes);
        $vcd->context = $request->context;
        $vcd->updated_by = auth()->id();
        $vcd->save();

        return response()->json([
            'status' => 'success',
            'message' => 'Data saved successfully!',
        ]);
    }

    public function save_nursing_notes(Request $request)
    {
        $visit_id = $request->visit_id;

        $rawNotes = $request->notes ?? [];
        ksort($rawNotes);
        $incomingNotes = array_values($rawNotes);

        // Filter out notes without a valid created_at date
        $incomingNotes = array_filter($incomingNotes, function($note) {
            return !empty($note['created_at']);
        });
        $incomingNotes = array_values($incomingNotes);

        // Check for future slots/times first
        $source = $request->input('source');
        foreach ($incomingNotes as $note) {
            if (isset($note['created_at'])) {
                $noteTime = \Carbon\Carbon::parse($note['created_at']);
                $isFuture = false;
                if ($source === 'vitals_flowsheet') {
                    $isFuture = $noteTime->copy()->subHour()->isAfter(now());
                } else {
                    $isFuture = $noteTime->isAfter(now());
                }
                if ($isFuture) {
                    return response()->json([
                        'status' => 'error',
                        'message' => 'Cannot add or update vitals/notes for future dates or times.'
                    ]);
                }
            }
        }

        $vcd = VisitClinicalData::where('visit_id', $visit_id)->where('context',$request->context)->first();
        if(!$vcd){
            $vcd = new VisitClinicalData;
            $vcd->visit_id = $visit_id;
        }

        $existingNotes = json_decode($vcd->ot_data, true) ?? [];
        // Filter out existing notes without a valid created_at date
        $existingNotes = array_filter($existingNotes, function($note) {
            return !empty($note['created_at']);
        });
        $existingNotes = array_values($existingNotes);

        // Preprocess incoming notes to preserve or set created_by and actual_created_at
        $processedNotes = [];
        foreach ($incomingNotes as $incomingNote) {
            $existingNote = null;
            foreach ($existingNotes as $extNote) {
                if ($this->notesMatch($extNote, $incomingNote)) {
                    $existingNote = $extNote;
                    break;
                }
            }

            if ($existingNote) {
                if (isset($existingNote['actual_created_at'])) {
                    $incomingNote['actual_created_at'] = $existingNote['actual_created_at'];
                }
                if (isset($existingNote['created_by'])) {
                    $incomingNote['created_by'] = $existingNote['created_by'];
                }
            } else {
                if (!isset($incomingNote['actual_created_at'])) {
                    $incomingNote['actual_created_at'] = now()->format('Y-m-d H:i:s');
                }
                if (!isset($incomingNote['created_by'])) {
                    $incomingNote['created_by'] = auth()->id();
                }
            }
            $processedNotes[] = $incomingNote;
        }
        $incomingNotes = $processedNotes;

        if ($this->vitalLock) {
            $mergedNotes = [];
            foreach ($existingNotes as $existingIndex => $existingNote) {
                $isLocked = false;
                if (!isset($existingNote['created_at'])) {
                    $isLocked = true;
                } else {
                    $noteTime = \Carbon\Carbon::parse($existingNote['created_at']);
                    $isBackwardDate = $noteTime->copy()->startOfDay()->isBefore(\Carbon\Carbon::today());

                    if ($isBackwardDate) {
                        $isLocked = true;
                    } else {
                        $creatorId = $existingNote['created_by'] ?? null;
                        if ($creatorId != auth()->id()) {
                            $isLocked = true;
                        } else {
                            // 1-hour window check for both vitals and nursing notes as per user feedback
                            $actualTimeStr = $existingNote['actual_created_at'] ?? $existingNote['created_at'] ?? null;
                            if ($actualTimeStr) {
                                $actualTime = \Carbon\Carbon::parse($actualTimeStr);
                                if (now()->diffInMinutes($actualTime) > 60) {
                                    $isLocked = true;
                                }
                            }
                        }
                    }
                }

                // Match incoming note by date/time
                $matchedIncomingKey = null;
                foreach ($incomingNotes as $incomingKey => $incomingNote) {
                    if ($this->notesMatch($existingNote, $incomingNote)) {
                        $matchedIncomingKey = $incomingKey;
                        break;
                    }
                }

                if ($isLocked) {
                    // Enforce locked state by keeping the existing database values
                    $mergedNotes[] = $existingNote;
                    if ($matchedIncomingKey !== null) {
                        unset($incomingNotes[$matchedIncomingKey]);
                    }
                } else {
                    // If not locked, allow updates/deletions
                    if ($matchedIncomingKey !== null) {
                        $mergedNotes[] = $incomingNotes[$matchedIncomingKey];
                        unset($incomingNotes[$matchedIncomingKey]);
                    }
                }
            }

            // Append any remaining/new incoming notes
            foreach ($incomingNotes as $newNote) {
                $mergedNotes[] = $newNote;
            }
            $notes = $mergedNotes;
        } else {
            $notes = $incomingNotes;
        }

        $freeTextboxData = $request->input('freeTextbox', []);

        // Add updated_at timestamp for each field
        $currentTime = now()->format('Y-m-d H:i:s'); // Get the current timestamp

        $formattedData = [];
        foreach ($freeTextboxData as $key => $value) {
            $formattedData[$key] = [
                'value' => $value,
                'updated_at' => $currentTime
            ];
        }

        if ($request->has('investigations')) {
            $formattedData['investigations'] = [
                'value' => $request->input('investigations'),
                'updated_at' => $currentTime
            ];
        }

        // Convert to JSON format
        $jsonData = json_encode($formattedData, JSON_PRETTY_PRINT);

        $vcd->others = $jsonData;
        $vcd->ot_data =  json_encode($notes);
        $vcd->context = $request->context;
        $vcd->updated_by = auth()->id();
        $vcd->save();

        return response()->json([
            'status' => 'success',
            'message' => 'Data saved successfully!',
        ]);
    }

