      public function delete_ipd_notes(Request $request){

        $visit_id = $request->visit_id;
        $context = $request->context;
        $index = $request->index;

        $vcd = VisitClinicalData::join('visitlog','visitlog.id','=','visit_clinical_data.visit_id')
            ->select('visit_clinical_data.*','visitlog.doctor_id')
            ->where('visit_clinical_data.visit_id', $visit_id)
            ->where('visit_clinical_data.context', $context)
            ->first();

        if (!$vcd) {
            return response()->json([
                'status' => 'error',
                'message' => 'Data not found'
            ]);
        }

        $notes = json_decode($vcd->ot_data, true);

        if (!is_array($notes)) {
            return response()->json([
                'status' => 'error',
                'message' => 'Invalid notes format'
            ]);
        }

        if (isset($notes[$index])) {
            $existingNote = $notes[$index];

            if ($this->vitalLock) {
                if (!isset($existingNote['created_at'])) {
                    return response()->json([
                        'status' => 'error',
                        'message' => 'Legacy entries cannot be deleted.'
                    ]);
                }
                $noteTime = \Carbon\Carbon::parse($existingNote['created_at']);
                $isBackwardDate = $noteTime->copy()->startOfDay()->isBefore(\Carbon\Carbon::today());

                if ($isBackwardDate) {
                    return response()->json([
                        'status' => 'error',
                        'message' => 'Backward date entries cannot be deleted.'
                    ]);
                }

                $creatorId = $existingNote['created_by'] ?? null;
                if ($creatorId != auth()->id()) {
                    return response()->json([
                        'status' => 'error',
                        'message' => 'You can only delete your own entries.'
                    ]);
                }

                // 1-hour window check for delete
                $actualTimeStr = $existingNote['actual_created_at'] ?? $existingNote['created_at'] ?? null;
                if ($actualTimeStr) {
                    $actualTime = \Carbon\Carbon::parse($actualTimeStr);
                    if (now()->diffInMinutes($actualTime) > 60) {
                        return response()->json([
                            'status' => 'error',
                            'message' => 'Entries can only be deleted within 1 hour of creation.'
                        ]);
                    }
                }
            }

            unset($notes[$index]);
            $notes = array_values($notes);
            $updatedJson = json_encode($notes);

            if ($updatedJson === false) {
                return response()->json([
                    'status' => 'error',
                    'message' => 'Failed to encode notes'
                ]);
            }

            $vcd->ot_data = $updatedJson;
            $vcd->save();

            return response()->json([
                'status' => 'success',
                'message' => 'Notes deleted successfully!',
                'data' => $vcd
            ]);
        } else {
            return response()->json([
                'status' => 'error',
                'message' => 'Note index not found!'
            ]);
        }

     }

