     public function save_template_general(Request $request){


        $visit_id = $request->visit_id;
        $context = $request->context;
        $index = $request->index;
        $template_name = $request->template_name;


        $vcd = VisitClinicalData::join('visitlog','visitlog.id','=','visit_clinical_data.visit_id')
                                    ->select('visit_clinical_data.*','visitlog.doctor_id')
                                    ->where('visit_clinical_data.visit_id', $visit_id)
                                    ->where('visit_clinical_data.context',$context)
                                    ->first();
        if(!$vcd){
            return response()->json([
                'status' => 'error',
                'message' => 'Data not found'
            ]);
        }

        DB::beginTransaction();

        try {


            $tem = new Template;
            $tem->user_id = $vcd->doctor_id;
            $tem->name = $template_name;
            $tem->context = $request->context;
            $tem->template = $vcd->others;
            $tem->cc = $vcd->cc;
            $tem->diagnosis = $vcd->diagnosis;
            $tem->physical_examination_finding = $vcd->physical_examination_finding;
            $tests = $request->tests ?? $request->input('tests');
            if($tests != null){
                $tem->investigation_request = json_encode($tests);
            } else if ($vcd && $vcd->investigation_request != null) {
                $tem->investigation_request = $vcd->investigation_request;
            }
            $tem->save();


            $template_id = $tem->id;

            if(($request->e_prescription??false) == 'v4'){

                $medicines = $request->medicine??[];

                PresTemplate::where('template_id', $template_id)->delete();

                foreach($medicines as $med){

                    $brand_id = $med['brand_id'];
                    $source = $med['d_type']??'ss';
                    $mark = ($med['imp']??false)? "true":"false";
                    $route = $med['route']??"";
                    $frequency = $med['frequency']??"";
                    $spl_inst = $med['special_instruction']??"";
                    $duration = $med['duration']??"";


                    $manual = ($med['manual'] == 1)?1:0;

                    $pf = new PresTemplate;
                    $pf->manual = $manual;
                    $pf->save_type = 'p';
                    $pf->template_id = $template_id;
                    $pf->brand_id = $brand_id;
                    $pf->d_type = $source;
                    $pf->nc = 'false';
                    $pf->vic = $mark;
                    $pf->rs = $route;
                    $pf->it = $frequency;
                    $pf->spl_inst = $spl_inst;
                    $pf->dt = $duration;
                    $pf->save();
                }

            }else{

                $medicines = json_decode($request->medicine_table, true) ?? [];
                $lenght = count($medicines);

                PresTemplate::where('template_id', $template_id)->delete();

                for($i = 0; $i < $lenght-1; $i++){

                    $medicine = $medicines[$i]['column_2'];    // 105|ss

                    $brand_id = explode('|', $medicine)[0]; // 105
                    $source = explode('|', $medicine)[1]; // ss

                    //   return $medicines[$i]['column_1'];

                    $mark = ($medicines[$i]['column_1'])? "true":"false";
                    $route = $medicines[$i]['column_3'];

                    $pf = new PresTemplate;
                    $pf->save_type = 'p';
                    $pf->template_id = $template_id;
                    $pf->brand_id = $brand_id;
                    $pf->d_type = $source;
                    $pf->nc = 'false';
                    $pf->vic = $mark;
                    $pf->rs = $route;
                    $pf->it = $medicines[$i]['column_4'];
                    $pf->spl_inst = $medicines[$i]['column_5'];
                    $pf->dt = $medicines[$i]['column_6'];
                    $pf->save();

                }
            }

            DB::commit();

        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json(['status' => 'error', 'message' => $e->getMessage()]);
        }


        return response()->json(['status'=>'success','message'=>'Template saved successfully']);



     }


