    public function er_note(Request $request, $id=null, $t_id=null)
    {
        $context = FacadesRoute::currentRouteName();
        $visit = collect();

        if($request->patient??false)
        {
            $id = Visitlog::where('patient_id', $request->patient)->where('date',date('Y-m-d'))->first()->id??null;
            if(!$id){
                $lastVisit = Visitlog::where('patient_id', $request->patient)->orderBy('date','DESC')->first();
                $prev_visits = collect();
                if($lastVisit){
                    $prev_visits = VisitClinicalData::join('visitlog', 'visitlog.id', '=', 'visit_clinical_data.visit_id')
                                        ->select('visitlog.id', 'visitlog.created_at')
                                        ->where('visitlog.patient_id', $lastVisit->patient_id)
                                        ->where('visitlog.doctor_id', $lastVisit->doctor_id)
                                        ->where('visitlog.hospital_id', $lastVisit->hospital_id)
                                        ->where('visit_clinical_data.context', $context)
                                        ->orderBy('visitlog.created_at', 'desc')
                                        ->skip(1)
                                        ->take(10)
                                        ->get();
                }
                return view('admin.patient.clinical.er_note',compact('visit','context','lastVisit','prev_visits'));
            }
        }

        if(!$id){
            return view('admin.patient.clinical.er_note',compact('visit','context'));
        }

        $vcd = VisitClinicalData::firstOrCreate(['visit_id' => $id,'context' => $context]);
        if ($t_id) {
            try {
                DB::transaction(function () use ($id, $context,$vcd, $t_id) {
                    $vcd = VisitClinicalData::where('id', $vcd->id)
                        ->lockForUpdate()
                        ->first();

                    $template = Template::find($t_id);

                    if (!$template) {
                        throw new \Exception('Template not found');
                    }

                    Pres_final::where('visit_table_id', $id)
                        ->lockForUpdate()
                        ->get();

                    $medicines = $this->get_template_medicine_list($t_id) ?? [];

                    $index = Pres_final::where('visit_table_id', $id)
                        ->max('d_order') ?? 0;

                    foreach ($medicines as $m) {
                        $pf = new Pres_final();
                        $pf->save_type = 'p';
                        $pf->visit_table_id = $id;
                        $pf->brand_id = $m->brand_id;
                        $pf->d_type = $m->d_type;
                        $pf->nc = 'false';
                        $pf->vic = $m->vic;
                        $pf->rs = $m->rs;
                        $pf->it = $m->it;
                        $pf->spl_inst = $m->spl_inst;
                        $pf->dt = $m->dt;
                        $pf->d_order = ++$index;
                        $pf->save();
                    }

                    $decodeArray = function ($data) {
                        if (empty($data)) { return []; }
                        if (is_array($data)) { return $data; }
                        $decoded = json_decode($data, true);
                        return (json_last_error() === JSON_ERROR_NONE && is_array($decoded)) ? $decoded : [];
                    };

                    $normalizeItem = function ($item) {
                        if (is_array($item)) { ksort($item); }
                        return $item;
                    };

                    $mergeUnique = function ($a, $b) use ($decodeArray,$normalizeItem) {
                        $merged = array_merge($decodeArray($a),$decodeArray($b));
                        $unique = [];
                        $seen = [];
                        foreach ($merged as $item) {
                            if ($item === null || $item === '') { continue; }
                            if (is_array($item) && empty(array_filter($item, function ($v) { return $v !== null && $v !== ''; }))) { continue; }
                            $item = $normalizeItem($item);
                            $key = is_array($item) ? json_encode($item) : (string) $item;
                            if (!isset($seen[$key])) {
                                $seen[$key] = true;
                                $unique[] = $item;
                            }
                        }
                        return array_values($unique);
                    };

                    $vcd->cc = $mergeUnique($vcd->cc, $template->cc);
                    $vcd->diagnosis = $mergeUnique($vcd->diagnosis, $template->diagnosis);
                    $vcd->others = $mergeUnique($vcd->others, $template->template);
                    $vcd->save();
                }, 5);

                return redirect()->route('clinical.er_note', ['vid' => $id]);
            } catch (\Throwable $e) {
                return response()->json([
                    'status' => 'error',
                    'message' => $e->getMessage()
                ]);
            }
        }

        $lock = $this->isPageLocked($id,$context);

        $patient = Patient::join('visitlog', 'visitlog.patient_id', '=', 'pi.id')
                        ->leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                        ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                        ->join('org_doc_index', 'org_doc_index.doc_id', '=', 'visitlog.doctor_id')
                        ->select('pi.*', 'visitlog.doctor_id',
                                    'doctor_db.name as doctor_name',
                                    'visitlog.fud','visitlog.edit_lock',
                                    'doctor_specialities.id as spid',
                                    'doctor_db.id as did',
                                    'visitlog.ad2',
                                    'visitlog.dd2',
                                    'visitlog.at1',
                                    'visitlog.dt1',
                                    'visitlog.created_at as created_at',
                                    'doctor_db.key_spec',
                                    'org_doc_index.others as search_type'
                        )
                        ->where('visitlog.id', $id)
                        ->first();

        $lastIPD = Visitlog::leftJoin('ipd_details','ipd_details.visit_table_id','=','visitlog.id')
                    ->whereIn('visitlog.visit_status', [1,2])->orderBy('id', 'desc')
                    ->where('visitlog.patient_id', $patient->id)
                    ->select([
                        'visitlog.id',
                        'ipd_details.id as ipd_no',
                        'visitlog.ad2 as admission_date',
                        'visitlog.visit_time as admission_time',
                        'visitlog.dd2 as discharge_date',
                        'visitlog.dt1 as discharge_time',
                        'visitlog.visit_status',
                    ])
                    ->limit(1)->first();

        $prev_visits = VisitClinicalData::join('visitlog', 'visitlog.id', '=', 'visit_clinical_data.visit_id')
                                        ->select('visitlog.id', 'visitlog.created_at')
                                        ->where('visitlog.patient_id', $patient->id)
                                        ->where('visitlog.doctor_id', $patient->doctor_id)
                                        ->where('visitlog.hospital_id', $patient->hospital_id)
                                        ->where('visit_clinical_data.context', $context)
                                        ->orderBy('visitlog.created_at', 'desc')
                                        ->skip(1)
                                        ->take(100)
                                        ->get();

        $visit_id = $id;
        $followup_date = $patient->fud ?? '';
        $comments = collect();
        $quick_icd = collect();

        $cc = json_decode(optional($vcd)->cc, true) ?? [];
        $diagnosis = json_decode(optional($vcd)->diagnosis, true) ?? [];
        $others = json_decode(optional($vcd)->others, true) ?? [];
        $pef = json_decode(optional($vcd)->physical_examination_finding, true) ?? [];
        $testr = json_decode(optional($vcd)->investigation_request, true) ?? [];

        $by_when = $vcd->by_when??'';
        $by_when_sel = $vcd->by_when_type??'';

        $vitalsList = Vitals::where('visit_id', $visit_id)->where('context', $context)->get();

        $logs = $this->formatVitalsLogs($vitalsList);

        // Get the latest vital row to set as $vitals
        $vitals = Vitals::where('visit_id', $visit_id)->where('context', $context)->latest('created_at')->first();

        // Backwards compatibility for templates accessing vitals_log property
        if ($vitals) {
            $vitals->vitals_log = json_encode($logs);
        } else {
            // Handle legacy record that doesn't have a context yet
            $vitals = Vitals::where('visit_id', $visit_id)->whereNull('context')->first();
            if ($vitals) {
                $vitals->context = $context;
                $vitals->save();
            }
        }

        if(is_null($vitals)){
            $bp = [];
            $pulse = [];
        }else{
            $bp = json_decode($vitals->bp, true) ?? [];
            $pulse = json_decode($vitals->pulse, true) ?? [];
            $bp = end($bp);
            $pulse = end($pulse);
        }

        $icd = collect();
        $medicines = $this->get_medicine_list($visit_id);
        $q_medicines = $this->get_q_medicine_list($visit_id, $patient->doctor_id);
        $pres_manual = PresManual::where('visit_table_id', $visit_id)->get();
        $templates = $this->get_templates($patient->did, $context);
        $prestemplates = $this->get_templates($patient->did, 'prescription');

        $st = json_decode($patient->search_type, true) ?? [];
        $search_type = $st['search_type'] ?? '';

        $formData = $others;
        $dynamic_comments = $this->get_clinical_comments($patient->did, $context);

        return view('admin.patient.clinical.er_note',compact('vitals','bp','pulse','visit_id','context','visit','patient','pef','others','testr','followup_date','comments','vcd','search_type',
                                                                            'cc','diagnosis', 'icd', 'medicines', 'q_medicines','by_when','by_when_sel','templates','pres_manual','prev_visits','prestemplates','formData','dynamic_comments','lock','lastIPD'));
    }

    public function general_prescription_v4(Request $request, $id=null, $t_id=null)
       {

            $context = FacadesRoute::currentRouteName();
            // $request->merge(['return_collection' => true]);
            // $visit = $this->fetch_visit_data_v2($request);
            $visit = collect();

            if($request->patient??false)
            {
                $id = Visitlog::where('patient_id', $request->patient)->where('date',date('Y-m-d'))->first()->id??null;
                if(!$id){
                    $lastVisit = Visitlog::where('patient_id', $request->patient)->orderBy('date','DESC')->first();
                    $prev_visits = collect();
                    if($lastVisit){
                        $prev_visits = VisitClinicalData::join('visitlog', 'visitlog.id', '=', 'visit_clinical_data.visit_id')
                                            ->select('visitlog.id', 'visitlog.created_at')
                                            ->where('visitlog.patient_id', $lastVisit->patient_id)
                                            ->where('visitlog.doctor_id', $lastVisit->doctor_id)
                                            ->where('visitlog.hospital_id', $lastVisit->hospital_id)
                                            ->where('visit_clinical_data.context', $context)
                                            ->orderBy('visitlog.created_at', 'desc')
                                            ->skip(1)
                                            ->take(10) // or any large number to fetch all remaining
                                            ->get();
                    }
                    return view('admin.patient.clinical.general_prescription_v4',compact('visit','context','lastVisit','prev_visits'));
                }
            }

            if(!$id){
                return view('admin.patient.clinical.general_prescription_v4',compact('visit','context'));
            }

            $vcd = VisitClinicalData::firstOrCreate(['visit_id' => $id,'context' => $context]);
            if ($t_id) {
                try {
                    DB::transaction(function () use ($id, $context,$vcd, $t_id) {
                        /*
                        |--------------------------------------------------------------------------
                        | Lock VisitClinicalData safely
                        |--------------------------------------------------------------------------
                        */
                        $vcd = VisitClinicalData::where('id', $vcd->id)
                            ->lockForUpdate()
                            ->first();

                        /*
                        |--------------------------------------------------------------------------
                        | Template
                        |--------------------------------------------------------------------------
                        */

                        $template = Template::find($t_id);

                        if (!$template) {
                            throw new \Exception('Template not found');
                        }

                        /*
                        |--------------------------------------------------------------------------
                        | Lock prescription rows before computing order
                        |--------------------------------------------------------------------------
                        */

                        Pres_final::where('visit_table_id', $id)
                            ->lockForUpdate()
                            ->get();

                        /*
                        |--------------------------------------------------------------------------
                        | Medicines
                        |--------------------------------------------------------------------------
                        */

                        $medicines = $this->get_template_medicine_list($t_id) ?? [];

                        $index = Pres_final::where('visit_table_id', $id)
                            ->max('d_order') ?? 0;

                        foreach ($medicines as $m) {

                            $pf = new Pres_final();

                            $pf->save_type = 'p';
                            $pf->visit_table_id = $id;
                            $pf->brand_id = $m->brand_id;
                            $pf->d_type = $m->d_type;
                            $pf->nc = 'false';
                            $pf->vic = $m->vic;
                            $pf->rs = $m->rs;
                            $pf->it = $m->it;
                            $pf->spl_inst = $m->spl_inst;
                            $pf->dt = $m->dt;
                            $pf->d_order = ++$index;

                            $pf->save();
                        }

                        /*
                        |--------------------------------------------------------------------------
                        | JSON Helpers
                        |--------------------------------------------------------------------------
                        */
                        $decodeArray = function ($data) {

                            if (empty($data)) {
                                return [];
                            }

                            if (is_array($data)) {
                                return $data;
                            }

                            $decoded = json_decode($data, true);

                            return (
                                json_last_error() === JSON_ERROR_NONE
                                && is_array($decoded)
                            )
                                ? $decoded
                                : [];
                        };

                        $normalizeItem = function ($item) {

                            if (is_array($item)) {
                                ksort($item);
                            }

                            return $item;
                        };

                        $mergeUnique = function ($a, $b) use (
                            $decodeArray,
                            $normalizeItem
                        ) {

                            $merged = array_merge(
                                $decodeArray($a),
                                $decodeArray($b)
                            );

                            $unique = [];
                            $seen = [];

                            foreach ($merged as $item) {

                                /*
                                |--------------------------------------------------------------------------
                                | Skip garbage values
                                |--------------------------------------------------------------------------
                                */

                                if ($item === null) {
                                    continue;
                                }

                                if ($item === '') {
                                    continue;
                                }

                                if (
                                    is_array($item)
                                    && empty(array_filter($item, function ($v) {
                                        return $v !== null && $v !== '';
                                    }))
                                ) {
                                    continue;
                                }

                                $item = $normalizeItem($item);

                                $key = is_array($item)
                                    ? json_encode($item)
                                    : (string) $item;

                                if (!isset($seen[$key])) {

                                    $seen[$key] = true;

                                    $unique[] = $item;
                                }
                            }

                            return array_values($unique);
                        };

                        /*
                        |--------------------------------------------------------------------------
                        | Merge Clinical Data
                        |--------------------------------------------------------------------------
                        */

                        $vcd->cc = $mergeUnique(
                            $vcd->cc,
                            $template->cc
                        );

                        $vcd->diagnosis = $mergeUnique(
                            $vcd->diagnosis,
                            $template->diagnosis
                        );

                        $vcd->others = $mergeUnique(
                            $vcd->others,
                            $template->template
                        );

                        $vcd->physical_examination_finding = $mergeUnique(
                            $vcd->physical_examination_finding,
                            $template->physical_examination_finding
                        );

                        $templateTests = ($template->context == 'investigation_advice')
                            ? $template->freetext
                            : $template->investigation_request;

                        $vcd->investigation_request = $mergeUnique(
                            $vcd->investigation_request,
                            $templateTests
                        );

                        $vcd->save();

                    }, 5);

                    return redirect()->route(
                        'clinical.general_v4',
                        ['vid' => $id]
                    );

                } catch (\Throwable $e) {

                    return response()->json([
                        'status' => 'error',
                        'message' => $e->getMessage(),
                        'line' => $e->getLine(),
                        'file' => basename($e->getFile())
                    ]);
                }
            }

            $lock = $this->isPageLocked($id,$context);

            $patient = Patient::join('visitlog', 'visitlog.patient_id', '=', 'pi.id')
                            ->leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                            ->join('org_doc_index', 'org_doc_index.doc_id', '=', 'visitlog.doctor_id')
                            ->select('pi.*', 'visitlog.doctor_id',
                                        'doctor_db.name as doctor_name',
                                        'visitlog.fud','visitlog.edit_lock',
                                        'doctor_specialities.id as spid',
                                        'doctor_db.id as did',
                                        'visitlog.ad2',
                                        'visitlog.dd2',
                                        'visitlog.at1',
                                        'visitlog.dt1',
                                        'visitlog.created_at as created_at',
                                        'doctor_db.key_spec',
                                        'org_doc_index.others as search_type'
                            )
                            ->where('visitlog.id', $id)
                            ->first();

        $lastIPD = Visitlog::leftJoin('ipd_details','ipd_details.visit_table_id','=','visitlog.id')
                    ->whereIn('visitlog.visit_status', [1,2])->orderBy('id', 'desc')
                    ->where('visitlog.patient_id', $patient->id)
                    ->select([
                        // 'visitlog.*',
                        'visitlog.id',
                        'ipd_details.id as ipd_no',
                        'visitlog.ad2 as admission_date',
                        'visitlog.visit_time as admission_time',
                        'visitlog.dd2 as discharge_date',
                        'visitlog.dt1 as discharge_time',
                        'visitlog.visit_status',
                    ])
                    ->limit(1)->first();
        // dd($lastIPD);

        $prev_visits = VisitClinicalData::join('visitlog', 'visitlog.id', '=', 'visit_clinical_data.visit_id')
                                        ->select('visitlog.id', 'visitlog.created_at')
                                        ->where('visitlog.patient_id', $patient->id)
                                        ->where('visitlog.doctor_id', $patient->doctor_id)
                                        ->where('visitlog.hospital_id', $patient->hospital_id)
                                        ->where('visit_clinical_data.context', $context)
                                        ->orderBy('visitlog.created_at', 'desc')
                                        ->skip(1)
                                        ->take(100) // or any large number to fetch all remaining
                                        ->get();




        $visit_id = $id;

        $followup_date = $patient->fud ?? '';


        $comments =  collect();

        $quick_icd = collect();

        $cc = json_decode(optional($vcd)->cc, true) ?? [];
        $diagnosis = json_decode(optional($vcd)->diagnosis, true) ?? [];
        $others = json_decode(optional($vcd)->others, true) ?? [];
        $pef = json_decode(optional($vcd)->physical_examination_finding, true) ?? [];
        $testr = json_decode(optional($vcd)->investigation_request, true) ?? [];

        $by_when = $vcd->by_when??'';
        $by_when_sel = $vcd->by_when_type??'';

        $vitals = Vitals::where('visit_id', $visit_id)->first();
