    public function get_previous_notes_list(Request $request, $visit_id)
    {
        $current_visit = Visitlog::find($visit_id);
        if (!$current_visit) {
            return response()->json(['error' => 'Visit not found'], 404);
        }

        $user = auth()->user();

        $query = VisitClinicalData::join('visitlog', 'visitlog.id', '=', 'visit_clinical_data.visit_id')
            ->leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
            ->leftJoin('org_doc_index', function($join) use ($user) {
                $join->on('org_doc_index.doc_id', '=', 'visitlog.doctor_id')
                     ->where('org_doc_index.org_id', '=', $user->org_id);
            })
            ->select(
                'visit_clinical_data.visit_id',
                'visit_clinical_data.context',
                'visitlog.created_at',
                'doctor_db.name as doctor_name',
                'visit_clinical_data.is_approved',
                'org_doc_index.id as note_doctor_index_id'
            )
            ->where('visitlog.patient_id', $current_visit->patient_id)
            ->where('visitlog.visit_status', 0)
            ->where('visit_clinical_data.visit_id', '!=', $visit_id);

        $loginDocId = null;
        if ($user && $user->is_doctor) {
            $loginDocId = $user->doctor_index_id;
            $query->where(function($q) use ($loginDocId) {
                $q->where('org_doc_index.id', '=', $loginDocId)
                  ->orWhereNull('org_doc_index.id')
                  ->orWhereNull('org_doc_index.others')
                  ->orWhereNull('org_doc_index.others->note_sharing')
                  ->orWhere('org_doc_index.others->note_sharing', '!=', 0);
            });
        }

        $notes = $query->orderBy('visitlog.id', 'desc')
            ->paginate(10);

        return view('admin.patient.clinical.previous_notes_list_modal', compact('notes', 'visit_id', 'loginDocId'));
    }

    public function check_previous_doctor(Request $request, $visit_id)
    {
        $current_visit = Visitlog::find($visit_id);
        if (!$current_visit) {
            return response()->json(['different_doctor' => false]);
        }

        $previous_note = VisitClinicalData::join('visitlog', 'visitlog.id', '=', 'visit_clinical_data.visit_id')
            ->leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
            ->select(
                'visit_clinical_data.visit_id',
                'visit_clinical_data.context',
                'visitlog.created_at',
                'visitlog.doctor_id',
                'doctor_db.name as doctor_name'
            )
            ->where('visitlog.patient_id', $current_visit->patient_id)
            ->where('visitlog.id', '<', $visit_id)
            ->where('visitlog.visit_status', 0)
            ->orderBy('visitlog.id', 'desc')
            ->first();

        if ($previous_note && $previous_note->doctor_id != $current_visit->doctor_id) {
            $formatted_date = \Carbon\Carbon::parse($previous_note->created_at)->format('d/m/Y h:i A');
            return response()->json([
                'different_doctor' => true,
                'doctor_name' => $previous_note->doctor_name ?? 'another doctor',
                'date' => $formatted_date,
                'visit_id' => $previous_note->visit_id,
                'context' => $previous_note->context
            ]);
        }

        return response()->json(['different_doctor' => false]);
    }

