        public function saveVitalLog(Request $request)
        {
            $user = \Illuminate\Support\Facades\Auth::user();
            $visit_id = $request->visit_id;
            $context = $request->context ?? 'clinical.er_note';
            $logId = $request->vital_log_id;
            $isUpdate = false;

            if ($logId) {
                $vitals = Vitals::find($logId);
                if ($vitals) {
                    $isUpdate = true;
                }
            }

            if (empty($vitals)) {
                $vitals = new Vitals;
                $vitals->visit_id = $visit_id;
                $vitals->context = $context;
                $vitals->created_by = $user->id;
                $vitals->updated_by = $user->id;
            } else {
                $vitals->updated_by = $user->id;
            }

            $vitals->temprature = $request->temprature ?? null;
            $vitals->saturation = $request->saturation ?? null;
            $vitals->rr = $request->rr ?? null;
            $vitals->pain_assessment = $request->pain_assessment ?? null;
            $vitals->gcs_eye = $request->gcs_eye ?? null;
            $vitals->gcs_verbal = $request->gcs_verbal ?? null;
            $vitals->gcs_motor = $request->gcs_motor ?? null;
            $vitals->gcs_total = $request->gcs_total ?? null;

            // BP & Pulse JSON columns
            $bpArr = [
                [
                    'upper_bp' => $request->upperBP ?? '',
                    'lower_bp' => $request->lowerBP ?? '',
                    'position' => $request->position ?? null,
                    'site' => $request->site ?? null,
                    'created_by' => (int)$user->id,
                    'created_at' => now()->toIso8601String()
                ]
            ];
            $vitals->bp = json_encode($bpArr);

            $pulseArr = [
                [
                    'pulseRate' => $request->pulseRate ?? '',
                    'pulseChar' => $request->pulseCharacter ?? null,
                    'site' => $request->pulseSite ?? null,
                    'regularties' => $request->pulseRegularties ?? null,
                    'created_by' => (int)$user->id,
                    'created_at' => now()->toIso8601String()
                ]
            ];
            $vitals->pulse = json_encode($pulseArr);

            // Time of vital taken stored in created_at column
            if ($request->vital_time) {
                $vitals->created_at = \Carbon\Carbon::parse($request->vital_time);
            }
            $vitals->save();

            // Fetch all entries for this visit & context to build logs history list
            $allVitals = Vitals::where('visit_id', $visit_id)
                ->where('context', $context)
                ->get();

            $logs = $this->formatVitalsLogs($allVitals);

            // Get the latest log entry to sync to clinical data GCS
            $latest = end($logs);

            // Sync GCS components to visit_clinical_data others JSON for print template support
            $vcd = VisitClinicalData::where('visit_id', $visit_id)->where('context', $context)->first();
            if (!$vcd) {
                $vcd = new VisitClinicalData;
                $vcd->visit_id = $visit_id;
                $vcd->context = $context;
            }
            $existingData = !empty($vcd->others) ? json_decode($vcd->others, true) : [];
            if (!is_array($existingData)) {
                $existingData = [];
            }
            if ($latest) {
                $existingData['gcs_eye'] = ['value' => $latest['gcs_eye'] ?? '', 'updated_at' => now()->toDateTimeString()];
                $existingData['gcs_verbal'] = ['value' => $latest['gcs_verbal'] ?? '', 'updated_at' => now()->toDateTimeString()];
                $existingData['gcs_motor'] = ['value' => $latest['gcs_motor'] ?? '', 'updated_at' => now()->toDateTimeString()];
                $existingData['gcs_total'] = ['value' => $latest['gcs_total'] ?? '', 'updated_at' => now()->toDateTimeString()];
            }
            $vcd->others = json_encode($existingData, JSON_PRETTY_PRINT);
            $vcd->save();

            return response()->json([
                'status' => 'success',
                'message' => $isUpdate ? 'Vital log updated successfully' : 'Vital log added successfully',
                'logs' => $logs
            ]);
        }

        public function deleteVitalLog(Request $request)
        {
            $visit_id = $request->visit_id;
            $context = $request->context ?? 'clinical.er_note';
            $logId = $request->vital_log_id;

            $vitals = Vitals::find($logId);
            if ($vitals) {
                $vitals->delete();
            }

            // Fetch remaining logs
            $allVitals = Vitals::where('visit_id', $visit_id)
                ->where('context', $context)
                ->get();

            $logs = $this->formatVitalsLogs($allVitals);

            $latest = end($logs);

            // Sync remaining GCS components to visit_clinical_data others JSON
            $vcd = VisitClinicalData::where('visit_id', $visit_id)->where('context', $context)->first();
            if ($vcd) {
                $existingData = !empty($vcd->others) ? json_decode($vcd->others, true) : [];
                if (is_array($existingData)) {
                    if ($latest) {
                        $existingData['gcs_eye'] = ['value' => $latest['gcs_eye'] ?? '', 'updated_at' => now()->toDateTimeString()];
                        $existingData['gcs_verbal'] = ['value' => $latest['gcs_verbal'] ?? '', 'updated_at' => now()->toDateTimeString()];
                        $existingData['gcs_motor'] = ['value' => $latest['gcs_motor'] ?? '', 'updated_at' => now()->toDateTimeString()];
                        $existingData['gcs_total'] = ['value' => $latest['gcs_total'] ?? '', 'updated_at' => now()->toDateTimeString()];
                    } else {
                        unset($existingData['gcs_eye'], $existingData['gcs_verbal'], $existingData['gcs_motor'], $existingData['gcs_total']);
                    }
                    $vcd->others = json_encode($existingData, JSON_PRETTY_PRINT);
                    $vcd->save();
                }
            }

            return response()->json([
                'status' => 'success',
                'message' => 'Vital log deleted successfully',
                'logs' => $logs
            ]);
        }

        private function formatVitalsLogs($vitalsList)
        {
            $logs = [];
            foreach ($vitalsList as $item) {
                $bpArr = json_decode($item->bp, true) ?? [];
                $bp = is_array($bpArr) ? (end($bpArr) ?: []) : [];
                if (!is_array($bp)) {
                    $bp = [];
                }

                $pulseArr = json_decode($item->pulse, true) ?? [];
                $pulse = is_array($pulseArr) ? (end($pulseArr) ?: []) : [];
                if (!is_array($pulse)) {
                    $pulse = [];
                }

                $logs[] = [
                    'id' => (string)$item->id,
                    'vital_time' => $item->created_at ? $item->created_at->toDateTimeString() : '',
                    'upper_bp' => $bp['upper_bp'] ?? '',
                    'lower_bp' => $bp['lower_bp'] ?? '',
                    'position' => $bp['position'] ?? '',
                    'site' => $bp['site'] ?? '',
                    'pulseRate' => $pulse['pulseRate'] ?? '',
                    'character' => $pulse['pulseChar'] ?? '',
                    'pulseSite' => $pulse['site'] ?? '',
                    'regularties' => $pulse['regularties'] ?? '',
                    'temprature' => $item->temprature ?? '',
                    'saturation' => $item->saturation ?? '',
                    'rr' => $item->rr ?? '',
                    'gcs_eye' => $item->gcs_eye ?? '',
                    'gcs_verbal' => $item->gcs_verbal ?? '',
                    'gcs_motor' => $item->gcs_motor ?? '',
                    'gcs_total' => $item->gcs_total ?? '',
                    'pain_assessment' => $item->pain_assessment ?? '',
                    'updated_at' => $item->updated_at ? $item->updated_at->toDateTimeString() : '',
                ];
            }

            // Sort logs by vital_time (chronological)
            usort($logs, function($a, $b) {
                return strcmp($a['vital_time'], $b['vital_time']);
            });

            return $logs;
        }

        public function saveTriage(Request $request)
        {
            $request->validate([
                'visit_id' => 'required|integer',
                'triage_level' => 'nullable|string'
