            $vcd->save();

            return response()->json([
                'status' => 'success',
                'message' => 'Triage level saved successfully'
            ]);
        }


    public function approve_prescription(Request $request){
        $visit_id = $request->visit_id;
        $context = $request->context;

        $vcdList = VisitClinicalData::where('visit_id', $visit_id)->where('context', $context)->get();
        if ($vcdList->isNotEmpty()) {
            foreach ($vcdList as $vcd) {
                $vcd->is_approved = 1;
                $vcd->is_abdm_approved = 1;
                $vcd->closed_at = now();
                $vcd->approved_by = Auth::user()->id ?? 1;
                $vcd->save();
            }
        } else {
            $vcd = VisitClinicalData::create([
                'visit_id'         => $visit_id,
                'context'          => $context,
                'is_approved'      => 1,
                'is_abdm_approved' => 1,
                'closed_at'        => now(),
                'approved_by'      => Auth::user()->id ?? 1,
            ]);
        }

        Visitlog::where('id', $visit_id)->update([
            'queue_status' => 2,
            'pres_status'  => 1,
            'abdm_enabled' => 1,
        ]);

        $visit = Visitlog::find($visit_id);
        $hospId = (int)($visit->hospital_id ?? (auth()->check() ? (auth()->user()->org_id ?? 1) : 1));
        if ($visit && !empty($visit->patient_id)) {
            if (\App\Helpers\LicenseKey::isModuleActiveAndValid('abha', $hospId)) {
                \DB::table('pi')->where('id', $visit->patient_id)->update(['abdm_enabled' => 1]);
                try {
                    $primaryVcdId = $vcdList->isNotEmpty() ? $vcdList->first()->id : ($vcd->id ?? null);
                    $isDischarge = str_contains(strtolower((string)$context), 'discharge') || str_contains(strtolower((string)$context), 'day_care');

                    if ($isDischarge) {
                        $isDayCare = str_contains(strtolower((string)$context), 'day_care');
                        app(\App\Services\ABDM\CareContextManagerService::class)->registerDischargeSummaryContext(
                            visitId: $visit_id,
                            vcdId: $primaryVcdId,
                            patientId: (int)$visit->patient_id,
                            hospitalId: $hospId,
                            isDayCare: $isDayCare,
                            autoLink: true
                        );
                    } else {
                        app(\App\Services\ABDM\CareContextManagerService::class)->syncOpdVisitCareContexts(
                            $visit_id,
                            $primaryVcdId,
                            (int)$visit->patient_id,
                            $hospId,
                            true
                        );
                    }
                } catch (\Throwable $ex) {
                    \Illuminate\Support\Facades\Log::channel('abdm')->warning("[approve_prescription] Care context sync failed: " . $ex->getMessage());
                }
            }
        }

        PatientGenBill::join('patient_billing', 'patient_gen_bill.bill_id', '=', 'patient_billing.id')
            ->join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
            ->where('patient_billing.visit_id', $visit_id)
            ->where('hospital_services.flag', 'consultation_charge')
            ->update(['patient_gen_bill.service_status' => 'completed']);

        DB::table('drug_brand_index as ss')
            ->join('pres_final as d', 'd.brand_id', '=', 'ss.id')
            ->where('d.visit_table_id', $visit_id)
            ->increment('ss.use_count');

        return response()->json(['status'=> 'success', 'message'=>'Prescription Approved Successfully']);
    }

    public function reopen_prescription(Request $request){
        $visit_id = $request->visit_id;
        $context = $request->context;

        VisitClinicalData::where('visit_id', $visit_id)->where('context', $context)->update([
            'is_approved' => 0,
            'approved_by' => null,
            'closed_at' => null
        ]);

        Visitlog::where('id', $visit_id)->update([
            'queue_status' => 1,
            'pres_status' => 0
        ]);

        PatientGenBill::join('patient_billing', 'patient_gen_bill.bill_id', '=', 'patient_billing.id')
            ->join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
            ->where('patient_billing.visit_id', $visit_id)
            ->where('hospital_services.flag', 'consultation_charge')
            ->update(['patient_gen_bill.service_status' => 'on_going']);

        return response()->json(['status' => 'success', 'message' => 'Prescription reopened for editing']);
    }

    public function load_visit_logs(Request $request, $vid, $context){
        $vcd = VisitClinicalData::where('visit_id', $vid)->where('context', $context)->first();
        if(!$vcd){
            return response()->json([ 'status' => 'error', 'message' => 'Data not found' ]);
        }

        $medicines = $this->get_medicine_list($vid);
        $pres_manual = PresManual::where('visit_table_id', $vid)->get();


          foreach($medicines as $r){
                            //  $r->formulation1 = $this->get_formulation($r->brand_id, $r->d_type);
                            $formulation = $this->get_formulation($r->brand_id, $r->d_type);

                            if($r->d_type == 'ss'){
                                foreach($formulation as $f){
                                    $form = $f->form;
                                    $dose = $f->dose;
                                    $unit = $f->unit_name;
                                    $drug = $f->drug_name;

                                    $r->formulation = $drug.' '.$dose.' '.$unit.' ('.$form.')';

                                }
                            }else{
                                foreach($formulation as $f){
                                    $form = $f->form;

                                    $strArray = [];
                                    foreach($f->comb_name as $cn){
                                        $formulation = $cn->drug_name;
                                        $dose = $cn->dose;
                                        $unit_name = $cn->unit_name;

                                        $strArray[] = $formulation. ' '.$dose.' '.$unit_name;
                                    }
                                    $str = implode(' + ', $strArray);
                                    $r->formulation = $str.'('.$form.')';
                                }
                            }
                        }

        // dd($pres_manual);
        $visit = Visitlog::select('doctor_db.name as doctor_name','visitlog.fud','visitlog.created_at')
                            ->join('doctor_db', 'visitlog.doctor_id', '=', 'doctor_db.id')
                            ->where('visitlog.id', $vid)
                            ->first();


        $icd_data = PatientICDData::leftjoin('icd_codes','icd_codes.icd_code','=','patient_icd_data.icd_code')
                                ->where('patient_icd_data.visit_table_id', $vid)
                                ->get();

           $vitals = Vitals::where('visit_id', $vid)->first();
            if(is_null($vitals)){
                $bp = [];
                $pulse = [];
            }else{
                $bp = json_decode($vitals->bp, true) ?? [];
                $pulse = json_decode($vitals->pulse, true) ?? [];
                $bp = end($bp);
                $pulse = end($pulse);
            }


        return view('components.visit-card',compact('vcd','medicines','pres_manual','visit', 'icd_data', 'vitals', 'bp', 'pulse','context'))->render();

    }


