    public function save_general_prescription(Request $request){
        $user = Auth::user();
        $org_id = $user->org_id;
        $visit_id = $request->visit_id;
        $context = $request->context;

        if ($guard = ClinicalDocumentLockService::checkAndGuard($org_id, $visit_id, $context)) {
            return $guard;
        }

        DB::beginTransaction();

        $vcd = VisitClinicalData::where('visit_id', $visit_id)->where('context', $context)->first();
        if(!$vcd){
            $vcd = new VisitClinicalData;
            $vcd->visit_id = $visit_id;
            $vcd->context = $context;
        }

        // physican examination
        $data['general'] = $request->general??'';
        $data['cvs'] = $request->cvs ?? '';
        $data['rs'] = $request->rs ?? '';
        $data['cns'] = $request->cns ?? '';
        $data['pa'] = $request->pa ?? '';
        $data['rss'] = $request->rss ?? '';

        $vcd->physical_examination_finding = json_encode($data, JSON_PRETTY_PRINT);

        if (!empty($request->cc)) {
            // Clean and store the cc array
            $ccData = array_filter($request->cc); // Removes any empty values (optional)\\
            $vcd->cc = json_encode(array_values($ccData), JSON_PRETTY_PRINT);

            foreach ($ccData as $cc) {
                $this->add_comment_v2($visit_id, $cc, 'complaint');
            }
        }else{
            $vcd->cc = '[]';
        }

        $vcd->by_when = $request->by_when ?? '';
        $vcd->by_when_type = $request->by_when_sel ?? '';

        if($request->tests != null){
            $vcd->investigation_request = json_encode($request->tests);
         }else{
            $vcd->investigation_request = '[]';
         }
        $vcd->save();

        // end complains
        Visitlog::where('id', $visit_id)->update([
            'fud' => $request->next_visit_date
        ]);

        if(($request->e_prescription??false) && (in_array($request->e_prescription, ['v3', 'v4']))){
            Pres_final::where('visit_table_id', $visit_id)->delete();
            PresManual::where('visit_table_id', $visit_id)->delete();

            foreach($request->medicine??[] as $index => $med)
            {
                $brand_id = $med['brand_id'];
                $source = $med['d_type']??'ss';
                $mark = ($med['imp']??false)? "true":"false";
                $route = $med['route']??"";
                $frequency = $med['frequency']??"";
                $spl_inst = $med['special_instruction']??"";
                $duration = $med['duration']??"";
                $notes = $med['notes']??"";
                $indication = $med['indication'] ?? null;

                if(($med['manual'] ?? false) || empty($brand_id) || !is_numeric($brand_id))
                {
                    $pf = new PresManual;
                    $pf->save_type = 'p';
                    $pf->visit_table_id = $visit_id;
                    $pf->brand_id = $brand_id;
                    // $pf->d_type = $source;
                    $pf->nc = 'false';
                    $pf->vic = $mark;
                    $pf->rs = $route;
                    $pf->it = $frequency;
                    $pf->spl_inst = $spl_inst;
                    $pf->dt = $duration;
                    $pf->notes = $notes;
                    $pf->indication = $indication;
                    $pf->d_order = $index+1;
                    $pf->save();

                }else{

                    $pf = new Pres_final;
                    $pf->save_type = 'p';
                    $pf->visit_table_id = $visit_id;
                    $pf->brand_id = $brand_id;
                    $pf->d_type = $source;
                    $pf->nc = 'false';
                    $pf->vic = $mark;
                    $pf->rs = $route;
                    $pf->it = $frequency;
                    $pf->spl_inst = $spl_inst;
                    $pf->notes = $notes;
                    $pf->dt = $duration;
                    $pf->indication = $indication;
                    $pf->d_order = $index+1;
                    $pf->save();


                    // if($source === 'ss'){
                    //     $b =  Drug_brand::find($brand_id);

                    //     $dose_id = $b->dose_id ?? '';
                    //     $drug_id = $b->drug_id ?? '';
                    //     $form_id = $b->form_id?? '';
                    // }else{
                    //     $b = DrugCombBrand::find($brand_id);
                    //     $dose_id = $b->comb_dose_id_entry ??'';
                    //     $drug_id = $b->comb_id??'';
                    //     $form_id = $b->form_id??'';
                    // }


                    // $this->add_medicine_to_doc_fav_brand($visit_id,$brand_id,$source,$mark);

                    // $this->add_comment($visit_id,$med,'medicine');

                    // if($b){
                    //     $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $frequency, $source,'it' );
                    //     $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $spl_inst, $source,'spl_inst' );
                    //     $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $route, $source,'route' );
                    // }
