                  $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $medicines[$i]['column_4'],$source,'it' );
                  $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $medicines[$i]['column_5'],$source,'spl_inst' );
              }

          }

          // store manula medicine s

          $medicines = json_decode($request->manual_medicine, true) ?? [];
          $lenght = count($medicines);

          PresManual::where('visit_table_id', $visit_id)->delete();

          for($i = 0; $i < $lenght; $i++){

              $brand_name = $medicines[$i]['column_2'];    // 105|ss

              $mark = ($medicines[$i]['column_1'])? "true":"false";
