        $lenght = count($icd_codes);
        // dd($icd_codes);
        PatientICDData::where('visit_table_id', $visit_id)->delete();

        for($i = 0; $i < $lenght; $i++){

            $cleanCode = preg_replace('/\s+/', '', $icd_codes[$i]['column_1']);

