        $cd->diagnosis = $newData;
        $cd->save();
        // ########################## save free text box notes ###########################

        $vcd = VisitClinicalData::where('visit_id', $visit_id)->where('context', $context)->first();

        $existingData = isset($vcd) && is_string($vcd->others ?? '')
                        ? json_decode($vcd->others, true)
                        : [];

        $textbox = array_merge(
            $request->freeTextbox ?? [],
            $request->free_textbox ?? []
        );
        foreach ($textbox as $key => $value) {
            $existingData[$key] = [
                "value" => $value,
                "updated_at" => now()->toDateTimeString()
            ];
        }

        $vcd->others = json_encode($existingData, JSON_PRETTY_PRINT);
        $vcd->is_approved = 0;
        $vcd->is_abdm_approved = 0;
        $vcd->save();


        PatientGenBill::join('patient_billing', 'patient_gen_bill.bill_id', '=', 'patient_billing.id')
            ->join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
            ->where('patient_billing.visit_id', $visit_id)
            ->where('hospital_services.flag', 'consultation_charge')
            ->update(['patient_gen_bill.service_status' => 'on_going']);

        DB::commit();


        // Return a response
        return response()->json([
            'message' => 'Data saved successfully',
            'data' => $data,
        ]);


    }

