    public function add_comment_v2($visit_id, $cmt, $context)
    {
        try {
            $cmt = trim((string)$cmt);
            if ($cmt === '') {
                return;
            }

            $visit = Visitlog::find($visit_id);
            if (!$visit || empty($visit->doctor_id)) {
                return;
            }

            $doctorId = $visit->doctor_id;

            if ($context === 'diagnosis') {
                $diagCmt = mb_substr($cmt, 0, 255);
                try {
                    \DB::statement(
                        "INSERT INTO clinical_comment_diagnosis (`user_id`, `comment`, `count`)
                         VALUES (?, ?, 1)
                         ON DUPLICATE KEY UPDATE `count` = `count` + 1",
                        [$doctorId, $diagCmt]
                    );
                } catch (\Throwable $e) {
                    \Log::warning("ClinicalCommentDiag save failed: " . $e->getMessage());
                }
            }

            $commentCmt = mb_substr($cmt, 0, 1000);
            try {
                $existingComment = ClinicalComment::where('user_id', $doctorId)
                    ->where('comment', $commentCmt)
                    ->where('context', $context)
                    ->first();

                if (!$existingComment) {
                    $comment = new ClinicalComment;
                    $comment->user_id = $doctorId;
                    $comment->comment = $commentCmt;
                    $comment->context = $context;
                    $comment->count = 1;
                    $comment->save();
                } else {
                    $existingComment->count = ($existingComment->count ?? 0) + 1;
                    $existingComment->save();
                }
            } catch (\Throwable $e) {
                \Log::warning("ClinicalComment save failed: " . $e->getMessage());
            }
        } catch (\Throwable $e) {
            \Log::warning("add_comment_v2 failed: " . $e->getMessage());
        }

        return;
    }


        public function freetext_save_as_template(Request $request){

            $request->validate( [
                'template_name' => 'required',
                'value' => 'required',
                'context' => 'required'
            ]);


            $temp = new Template;
            $temp->user_id = $request->doctor_id;
            $temp->name = $request->template_name;
            $temp->context = $request->context;
            if(is_array($request->value)){
                $temp->freetext = json_encode($request->value);
            }else{
                $temp->freetext = $request->value;
            }
            $temp->save();

            return response()->json([
                'status' => 'success',
                'message' => 'Template saved successfully'
            ]);
        }


        public function search_templates(Request $request){

            $templates = Template::select('id','name','freetext as content')
                                  ->where('user_id', $request->doctor_id)
                                  ->where('context', $request->context)
                                  ->where('name', 'like', '%'.$request->search.'%')
                                  ->get();

            if ($request->context === 'investigation_advice') {
                $templates->transform(function($template) {
                    $decoded = json_decode($template->content, true) ?? [];
                    $mapped = [];
                    foreach ($decoded as $item) {
                        $mapped[] = [
                            'id' => $item,
                            'text' => \App\Helpers\ServiceHelper::getServiceName($item)
                        ];
                    }
                    $template->content = json_encode($mapped);
                    return $template;
                });
            }

            return response()->json([
                'status' => 'success',
                'success' => true,
                'templates' => $templates
            ]);
        }


    public function add_vitals(Request $request, $id=null){

        $vitalPageVersion = \App\Models\HospitalSetting::where('hospital_id',auth()->user()->org_id)
                                                ->where('identifier','vitals_page_version')
                                                ->first()->current_setting??'v1';
        if($vitalPageVersion == 'v2'){

            $doctors = $request->doctors??[];

            $docs = HospitalDoctor::join('doctor_db', 'doctor_db.id', '=', 'org_doc_index.doc_id')
                        ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                        ->select('doctor_db.id as doc_id',
                                'org_doc_index.id as doc_index_id',
                                    'doctor_db.name as doc_name',
                                    'org_doc_index.slot_new',
                                    'org_doc_index.slot_review',
                                    'org_doc_index.room_no',
                                    'org_doc_index.ost',
                                    'org_doc_index.oet',
                                    'org_doc_index.bst',
                                    'org_doc_index.bet',
                                    'org_doc_index.opd_status',
                                    'doctor_db.contact_no',
                                    'doctor_specialities.name as speciality',
                                    )
                        ->where('org_id', auth()->user()->org_id)
                        ->when(!empty($doctors), function ($query) use ($doctors) {
                            $query->whereIn('doctor_db.id', $doctors);
                        })
                        ->orderBy('doctor_db.id', 'asc')
                        ->get();

            return view('admin.patient.clinical.vitals_v2',compact('id','docs'))->render();
        }
        $visit = $this->today_visit_list($request);
        $context = FacadesRoute::currentRouteName();


        if(!$id){
            if (!empty($visit) && isset($visit[0]->vid)) {
                $visit_id = $visit[0]->vid;
            } else {
                return back()->with('error', 'There is no any patient visit for today.');
            }

            return view('admin.patient.clinical.vitals',compact('visit','context'));
        }


        $patient = Patient::join('visitlog', 'visitlog.patient_id', '=', 'pi.id')
                            ->leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                            ->select('pi.*', 'visitlog.doctor_id',
                                        'doctor_db.name as doctor_name',
                                        'visitlog.fud','visitlog.edit_lock',
                                        'doctor_specialities.id as spid',
                                        'doctor_db.id as did',
                                        'visitlog.ad2',
                                        'visitlog.dd2',
                                        'visitlog.at1',
                                        'visitlog.dt1',
                                        'visitlog.created_at as created_at',
                                        'doctor_db.key_spec'
                            )
                            ->where('visitlog.id', $id)
                            ->first();




       $visit_id = $id;

        $vitals = Vitals::where('visit_id', $visit_id)->first();
        if(is_null($vitals)){
            $bp = [];
            $pulse = [];
        }else{
            $bp = json_decode($vitals->bp, true) ?? [];
            $pulse = json_decode($vitals->pulse, true) ?? [];
            $bp = end($bp);
            $pulse = end($pulse);
        }
        return view('admin.patient.clinical.vitals',compact('vitals','bp','pulse','visit_id','context','visit','patient'));
    }

