    public function vaccine_save(Request $request){

        if($request->action == 'reset'){
            if($request->type == 1){
                VacLog::where(['visit_id' => $request->visit_id,'brand_id' => $request->vaccine_id,'dose'=> $request->week_key])->delete();
            }else{
                $itemArray = explode(",", $request->items);
                foreach($itemArray as $item){
                       $arr = explode("-", $item);
                       $brand_id = $arr[0];
                       $d_type = $arr[1];
                       $dose = $arr[2];

                       VacLog::where(['visit_id' => $request->visit_id,'vac_id' => $brand_id,'dose' => $dose])->delete();
                }

            }

            return response()->json(['status' => 'success','message' => 'Vaccine added successfully']);
        }

        if($request->type == 1){

            $vcc = VacLog::firstOrNew(['visit_id' => $request->visit_id,'vac_id' => $request->vaccine_id,'week_key'=> $request->week_key]);
            $vcc->vac_date = ($request->action == 'given') ? $request->vac_date : $request->vac_date2;
            $vcc->vac_id = $request->vaccine_id;
            $vcc->comment = ($request->action == 'given') ? $request->vcc_note : $request->vac_note2;
            $vcc->week_key = $request->week_key;
            $vcc->brand_id = $request->brand_id;
            $vcc->d_type = $request->d_type;
            $vcc->status = ($request->action == 'given') ? 1 : 0;
            $vcc->save();

        }else{
            $itemArray = explode(",", $request->items);
            foreach($itemArray as $item){
                   $arr = explode("-", $item);
                   $brand_id = $arr[0];
                   $d_type = $arr[1];
                   $week_key = $arr[2];

                   $vcc = VacLog::firstOrNew(['visit_id' => $request->visit_id,'vac_id' => $request->vaccine_id,'week_key'=> $week_key]);
                   $vcc->vac_date = $request->vac_date;
                   $vcc->vac_id = $brand_id;
                   $vcc->comment = $request->vcc_note;
                   $vcc->week_key = $week_key;
                   $vcc->brand_id = $brand_id;
                   $vcc->d_type = $d_type;
                   $vcc->status = ($request->action == 'given') ? 1 : 0;
                   $vcc->save();
            }
        }


        return response()->json(['status' => 'success','message' => 'Vaccine added successfully']);

    }

    public function vaccine_report($visit_id){

        $vaccines = VacLog::join('drug_brand_index','drug_brand_index.id','=','vac_log.brand_id')
                            ->select('vac_log.*','drug_brand_index.brand_name as brand_name')
                            ->where('vac_log.visit_id', $visit_id)
                            ->where('vac_log.status', 1)
                            ->get();

        $vaccine2 = VacLog::join('drug_brand_index','drug_brand_index.id','=','vac_log.brand_id')
                            ->select('vac_log.*','drug_brand_index.brand_name as brand_name')
                            ->where('vac_log.visit_id', $visit_id)
                            ->where('vac_log.status', 0)
