    public function get_composition(Request $request){

        $medicine = $request->brand_id;  // 105|R2|ss
        $brand_id = explode('|', $medicine)[0]; // 105

        $d_type = explode('|', $medicine)[1]; // ss
    try{

        if($d_type === 'ss'){
            $res = DocDrugBrand::join('drug_brand_index','drug_brand_index.id','=','doc_drug_used_brands.brand_id')
                                ->join('pharma_companies','pharma_companies.id','=','drug_brand_index.pharma_company')
                                ->join('drug_dosage_forms','drug_dosage_forms.id','=','drug_brand_index.form_id')
                                ->join('drug_dosages','drug_dosages.id','=','drug_brand_index.dose_id')
                                ->join('drug_dose_units','drug_dose_units.id','=','drug_dosages.dose_unit')
                                ->join('drugs','drugs.id','=','drug_brand_index.drug_id')
                                ->leftjoin('cost_table as CT2','CT2.id','=','drug_brand_index.unit_cost')
                                ->leftjoin('cost_table as CT1','CT1.id','=','drug_brand_index.pack_cost')
                                // ->join('drug_packing','drug_packing.id','=','drug_brand_index.packing_id')
                                ->join('brand_avail_code_text','brand_avail_code_text.id','=','drug_brand_index.local_avail')
                                ->select('drug_brand_index.id as brand_id','drug_brand_index.brand_name','pharma_companies.name as pharma_name',
                                        'drug_dosage_forms.form','drug_dosages.dose','drug_dose_units.unit_name','drugs.drug_name',
                                        'drugs.indian_list','CT2.cost as unit_cost2','CT1.cost as pack_cost2',
                                        'brand_avail_code_text.full_text as local_avail')
                                // ->where('doc_drug_used_brands.doctor_id', 1)
                                ->where('doc_drug_used_brands.brand_id', $brand_id)
                                ->get();
        }else{

        $res =  DocDrugBrand::leftJoin('drug_comb_brand_index as A','doc_drug_used_brands.brand_id','=','A.id')
                            ->leftJoin('pharma_companies as F','A.pharma_id','=','F.id')
                            ->leftJoin('drug_dosage_forms as G','A.form_id','=','G.id')
                            ->leftJoin('drug_packing','A.packing_id','=','drug_packing.id')
                            ->leftJoin('cost_table as CT1','A.pack_cost','=','CT1.id')
                            ->leftJoin('cost_table as CT2','A.unit_cost','=','CT2.id')
                            ->leftJoin('brand_avail_code_text','A.local_avail','=','brand_avail_code_text.id')
                            ->select('A.id as brand_id','A.comb_id','A.brand_name','A.comb_dose_id_entry as cudi','A.form_id','A.sample_avail',
                                    'F.name as pharma_name','G.form','CT2.cost as unit_cost2','CT1.cost as pack_cost2','drug_packing.p_name',
                                    'brand_avail_code_text.full_text as local_avail')
                            ->where('doc_drug_used_brands.brand_id', $brand_id)
                            ->get();

            foreach($res as $r){
                $r['comb_name'] = $this->get_composition_by_cudi($r->cudi);
            }

        }

        return $res;

    } catch (\Exception $e) {
        echo $e->getMessage();exit;

    }
    }


