    public function get_composition_by_cudi($cudi){
        $qry = "SELECT
                        A.drug_id,
                        B.drug_name,
                        B.indian_list,
                        A.dose_id,
                        C.dose,
                        D.unit_name

                        FROM

                        drug_comb_dose_index AS A
                        LEFT JOIN
                        drugs AS B ON A.drug_id = B.id
                        LEFT JOIN
                        drug_dosages AS C ON A.dose_id = C.id
                        LEFT JOIN
                        drug_dose_units AS D ON C.dose_unit = D.id
                        WHERE
                        A.drug_comb_dose_name_entry_id = ?";


                $res2 = DB::select($qry, [$cudi]);
                return $res2;

    }

