    public function get_vital_list(Request $request){

        $visit_id = $request->visit_id;
        $vcd = VisitClinicalData::where('visit_id',$visit_id)->first();

        $cc = json_decode(optional($vcd)->cc, true) ?? [];
        $diagnosis = json_decode(optional($vcd)->diagnosis, true) ?? [];
        $pef = json_decode(optional($vcd)->physical_examination_finding, true) ?? [];

        $vitals = Vitals::where('visit_id', $visit_id)->first();

        return response()->json(['cc' => $cc,'diagnosis' => $diagnosis, 'pef' => $pef,'vitals' => $vitals]);


    }

    public function physical_examination(Request $request){

        $visit_id = $request->visit_id;

        $data['general'] = $request->general;
        $data['cvs'] = $request->cvs;
        $data['rs'] = $request->rs;
        $data['cns'] = $request->cns;
        $data['pa'] = $request->pa;
        $data['rss'] = $request->rss;

       $res = VisitClinicalData::where('visit_id', $visit_id)->update(['physical_examination_finding'=> json_encode($data)]);

       if($res){
            return response()->json(['status' => 'success','message' => 'Physical Examination added successfully']);
       }else{
            return response()->json(['status' => 'error','message' => 'Something went wrong']);
       }

    }


    public function icd_search(Request $request)
    {
        $query = $request->input('q');
        if (empty($query)) {
            return response()->json([]);
        }

        // Only return services that start with the query and have the flag 'test'
        $icd_codes = ICDCodes::where('icd_name', 'LIKE', "{$query}%")
                                ->orWhere('icd_code', 'LIKE', "{$query}%")
                                ->get(['id', 'icd_name','icd_code']); // Alias 'service' to 'text' for Select2

        return response()->json($icd_codes);
    }


    public function print_clinical_notes($id){
        $visit = Visitlog::join('pi', 'pi.id', '=', 'visitlog.patient_id')
                            ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                            ->select('visitlog.*', 'pi.prefix','pi.Fname','pi.age','pi.sex',
                            'pi.Lname', 'doctor_db.name as doctor_name',
                            'doctor_specialities.name as sp_name',
                            'doctor_db.id as doctor_id','pi.id as uhid')
                            ->where('visitlog.id', $id)
                            ->first();

        $vcd = VisitClinicalData::where('visit_id', $id)->first();
        if (!$vcd) {
        $vcd = VisitClinicalData::create(['visit_id' => $id, 'others' => '{}']);
        }

                    // Decode the clinical data safely
        $diagnosis = is_string($vcd->diagnosis ?? '') ? json_decode($vcd->diagnosis, true) : [];
        $cc = is_string($vcd->cc ?? '') ? json_decode($vcd->cc, true) : [];
        $pef = is_string($vcd->physical_examination_finding ?? '') ? json_decode($vcd->physical_examination_finding, true) : [];
        $others = is_string($vcd->others ?? '') ? json_decode($vcd->others, true) : [];

        $investigations =  InvestigationRequest::join('hospital_services', 'hospital_services.id', '=', 'investigation_request.service_id')
                                                ->select('investigation_request.*', 'hospital_services.service')
                                                ->where('visit_id', $id)
                                                ->get();



        $icd =  PatientICDData::join('icd_codes','icd_codes.icd_code','=','patient_icd_data.icd_code')
                                ->where('patient_icd_data.visit_table_id', $id)
                                ->get();


                    $medicines = DB::table('pres_final as d')
                            ->leftJoin('drug_comb_brand_index as cc', function ($join) {
                                $join->on('d.brand_id', '=', 'cc.id')
                                    ->where('d.d_type', '=', 'cc');
                            })
                            ->leftJoin('drug_brand_index as ss', function ($join) {
                                $join->on('d.brand_id', '=', 'ss.id')
                                    ->where('d.d_type', '=', 'ss');
                            })
                            ->select(
                                'd.*',
                                DB::raw("CASE
                                            WHEN d.d_type = 'cc' THEN cc.brand_name
                                            WHEN d.d_type = 'ss' THEN ss.brand_name
                                            ELSE NULL
                                        END as name")
                            )
                            // ->having('name', 'LIKE', "%{$query}%")
                            ->where('visit_table_id', $id)
                            // ->groupBy('d.brand_id')
                            ->orderBy('d.id', 'asc')
                            ->get();


                            foreach($medicines as $r){

                                $formulation = $this->get_formulation($r->brand_id, $r->d_type);

                                if($r->d_type == 'ss'){
                                    foreach($formulation as $f){
                                        $form = $f->form;
                                        $dose = $f->dose;
                                        $unit = $f->unit_name;
                                        $drug = $f->drug_name;

                                        $r->formulation = $drug.' '.$dose.' '.$unit.' ('.$form.')';

                                    }
                                }else{
                                    foreach($formulation as $f){
                                        $form = $f->form;

                                        $strArray = [];
                                        foreach($f->comb_name as $cn){
                                            $formulation = $cn->drug_name;
                                            $dose = $cn->dose;
                                            $unit_name = $cn->unit_name;

                                            $strArray[] = $formulation. ' '.$dose.' '.$unit_name;
                                        }
                                        $str = implode(' + ', $strArray);
                                        $r->formulation = $str.'('.$form.')';
                                    }
                                }
                            }

                            // dd($medicines);
                    $date = Carbon::parse($visit->fud);

                    $formattedDate = $date->format('l d/m/Y');

                    // Get the current date
                    $currentDate = Carbon::now();

                    // Calculate the difference in days
                    $dayDifference = $currentDate->diffInDays($date)+1;

                    // Determine if the difference is past or future
                    if ($date->greaterThan($currentDate)) {
                    $differenceText = "After {$dayDifference} Days";
                    } else {
                    $differenceText = "Before {$dayDifference} Days";
                    }

                    // Combine the final output
                    $followup_date = "{$formattedDate} {$differenceText}";

                    $vitals = Vitals::where('visit_id',$visit->id)->first();
                    if(is_null($vitals)){
                        $bp = [];
                        $pulse = [];
                    }else{
                        $bp = json_decode($vitals->bp, true) ?? [];
                        $pulse = json_decode($vitals->pulse, true) ?? [];
                        $bp = end($bp);
                        $pulse = end($pulse);
                    }

            return view('admin.pdf.clinical.v1.clinical_notes', compact('visit', 'diagnosis','cc','others','vitals','bp','icd','pulse', 'medicines', 'followup_date','investigations'));

    }


    public function icd_save(Request $request){

        $user = Auth::user();
        $visit = Visitlog::find($request->visit_id);

        $icd_code = $request->quick_icd_code ?? $request->icd_code;

        $existingCheck = PatientICDData::where('visit_id', $request->visit_id)->where('icd_code', $icd_code)->first();

        if (!$existingCheck) {

        $ICD = new PatientICDData;
        $ICD->visit_id = $request->visit_id;
        $ICD->icd_code = $icd_code;
        $ICD->comment = $request->comment;
        $ICD->save();

            $existingComment = ClinicalComment::where('user_id', $visit->doctor_id)
                                                ->where('comment', $icd_code)
                                                ->where('context', 'icd_code')
                                                ->first();

            if (!$existingComment) {
                $comment = new ClinicalComment;
                $comment->user_id = $visit->doctor_id;
                $comment->comment = $icd_code;
                $comment->context = 'icd_code';
                $comment->save();
            }

            return response()->json(['status'=>'success', 'message' => 'ICD Code Added Successfully']);
        }else{
            return response()->json(['status'=>'error', 'message' => 'ICD Code Already Added']);
        }



    }

    public function save_diagnosis(Request $request){

        $user = Auth::User();

        $cd = VisitClinicalData::firstOrNew(['visit_id' => $request->visit_id]);
        $existingData = json_decode($cd->{$request->type} ?? '[]', true);
        $newData = [
            'name' => $request->name,
            'comment' => $request->comment,
        ];
        $existingData[] = $newData;
        if ($request->type == 'diagnosis') {
            $cd->diagnosis = json_encode($existingData);
        }

        if ($request->type == 'cc') {
            $cd->cc = json_encode($existingData);
        }
        $cd->save();

        $cc = new ClinicalComment;
        $cc->user_id = $user->id;
        $cc->comment = $request->name;
        $cc->context = $request->type;
        $cc->save();

        return response()->json(['status'=>'success', 'message'=>'Saved Successfully']);

    }

