    public function print_combine_bill(Request $req){


        $bill_ids = $req->bill_ids;

        $status =  is_paid_bill($bill_ids[0]);

        if(!$status){
            //return response()->json(['status'=>'There is pending bill. Print Not Allowed.']);

            return response()->json(['status'=>'error', 'view'=>'There is pending bill. Print Not Allowed.']);
        }

        // combine both bill
        $patient = PatientBilling::join('visitlog','visitlog.id','=','patient_billing.visit_id')
                                  ->join('pi','pi.id','=','visitlog.patient_id')
                                  ->join('doctor_db','doctor_db.id','=','visitlog.doctor_id')
                                  ->join('users','users.id','=','patient_billing.created_by')
                                  ->join('health_insurance_agen','health_insurance_agen.id','=','pi.i_cover')
                                  ->select('pi.Fname','pi.Lname','pi.prefix','pi.sex','pi.age','pi.id as uhid',
                                            'doctor_db.name as doctor_name','health_insurance_agen.insurance_agen',
                                            'patient_billing.id as bill_id','patient_billing.created_at', 'users.first_name',
                                            'users.last_name', 'users.emp_code'
                                  )
                                  ->where('patient_billing.id',$bill_ids[0])
                                  ->first();

        $services = PatientGenBill::join('hospital_services', 'hospital_services.id', '=', 'patient_gen_bill.service_id')
                                  ->leftJoin('patient_billing', 'patient_billing.id', '=', 'patient_gen_bill.bill_id')
                                  ->select(
                                      'patient_gen_bill.service_id',
                                      'patient_gen_bill.charges',
                                      'patient_gen_bill.discount',
                                      'patient_gen_bill.qty',
                                      'patient_gen_bill.discount',
                                      'hospital_services.service',
                                      'patient_gen_bill.bill_id'
                                  )
                                  ->whereIn('patient_gen_bill.bill_id', $bill_ids)
                                  ->where(function($query) {
                                      $query->where('patient_billing.is_cancelled', '!=', 1)
                                            ->orWhereNull('patient_billing.is_cancelled'); // Allow NULL values
                                  })
                                  ->where('patient_gen_bill.is_deleted', 0)
                                  ->get();



            $payment = BillingPaymentType::leftJoin('patient_billing', 'patient_billing.id', '=', 'billing_payment_type.bill_id')
                                            ->whereIn('billing_payment_type.bill_id', $bill_ids)
                                            ->where(function ($query) {
                                                $query->where('patient_billing.is_cancelled', '!=', 1)
                                                    ->orWhereNull('patient_billing.is_cancelled');
                                            })
                                            ->select(
                                                'billing_payment_type.payment_mode',
                                                DB::raw("SUM(CASE
                                                            WHEN billing_payment_type.transaction_type = 0 THEN billing_payment_type.amount
                                                            WHEN billing_payment_type.transaction_type = 1 THEN -billing_payment_type.amount
                                                            ELSE 0
                                                        END) as amount")
                                            )
                                            ->groupBy('billing_payment_type.payment_mode')
                                            ->get()
                                            ->pluck('amount', 'payment_mode')
                                            ->toArray();



        $discount =  DB::table('patient_billing')
                                ->selectRaw('
                                    SUM(CAST(discount AS UNSIGNED)) as total_discount
                                ')
                                ->whereIn('patient_billing.id', $bill_ids)
                                ->first();

   //    $payment->total_payment =  (int)$payment['cash']??0 + (int)$payment['upi']??0 + (int)$payment['card']??0;
         $payment['total_payment'] = ((int)($payment['cash'] ?? 0)) + ((int)($payment['upi'] ?? 0)) + ((int)($payment['card'] ?? 0)) + ((int)($payment['neft_rtgs'] ?? 0));
       $view = view('admin.patient.billing.combine_bill', compact('bill_ids','patient','services','payment','discount'))->render();
       return response()->json(['status'=>'success', 'view'=>$view]);
    }


