    public function get_opd_queue_multiple_doctor_data(Request $request)
    {
        $org_id = $request->org_id;
        $doctors = $request->doctors ?? [];

        $request->merge(['return_collection' => true]);
        $visits = $this->fetch_visit_data_v2($request);

        $groupedData = [];

        $doctorsData = DB::table('org_doc_index')->whereIn('doc_id', $doctors)->pluck('opd_status', 'doc_id');

        foreach ($doctors as $doctorId)
        {
            $doctorQueue = $visits
                    ->where('doctor_id', $doctorId)
                    ->filter(function ($item) {
                        return !is_null($item->token_no);
                    })
                    ->map(function ($item) {
                        return (object) [
                            'vid' => $item->vid,
                            'token_no' => $item->token_no,
                            'queue_status' => $item->queue_status,
                            'patient' => $item->full_name ?? '',
                            'doctor_name' => $item->doctor_name ?? '',
                            'did' => $item->doctor_id ?? $item->doctor_id ?? '',
                        ];
                    })
                    ->sortBy([
                        fn ($item) => match ((int)$item->queue_status) {
                            2 => 0, // pending recall
                            1 => 1, // serving
                            0 => 2, // waiting
                            default => 3,
                        },
                        fn ($item) => $item->token_no,
                    ])
                    ->values();

            // CURRENTLY SERVING
            $serving = $doctorQueue->firstWhere('queue_status', 1);

            // WAITING QUEUE
            $waiting = $doctorQueue
                        ->filter(function ($item) {
                            return in_array((int)$item->queue_status, [0, 2]);
                        })
                        ->sortBy('token_no')
                        ->values();

            // COMPLETED QUEUE
            $completed = $doctorQueue
                        ->filter(function ($item) {
                            return $item->queue_status == 3;
                        })
                        ->sortByDesc('token_no')
                        ->values();

            $groupedData[$doctorId] = [
                'serving' => $serving,
                'waiting' => $waiting,
                'completed' => $completed,
                'total' => $doctorQueue->count(),
                'opd_status' => $doctorsData[$doctorId] ?? 0,
            ];
        }

        return response()->json([
            'success' => true,
            'data' => $groupedData
        ]);
    }
