    public function generate_queue_token(Request $request){
        $request->validate([
            'visit_id' => 'required',
        ]);

        try{
            $visit = Visitlog::find($request->visit_id);

            $maxTokenNo = Visitlog::where('doctor_id', $visit->doctor_id)
                            ->whereDate('date', date('Y-m-d',strtotime($visit->date)))
                            ->max('token_no')??0;

            $visit->token_no = $maxTokenNo + 1;
            $visit->queue_status = 0;
            $visit->save();

            if(env('OPD_QUEUE_WEBSOCKET_ENABLED',false)){
                event(new \App\Events\OPDQueueUpdated(
                    $visit->doctor_id,
                    $this->get_opd_queue_multiple_doctor_data(new Request([
                        'org_id' => $visit->hospital_id,
                        'doctors' => [$visit->doctor_id]
                    ]))
                ));
            }

            return response()->json(['success'=>true, 'message'=> 'Token generated successfully']);
        }catch(\Exception $e){
            return response()->json(['success'=>false, 'message'=> $e->getMessage()]);
        }
    }
    public function update_queue_status(Request $request)
    {
        $visit = Visitlog::find($request->visit_id);

        if ($request->status == 1) {
            $alreadyServing = Visitlog::where('doctor_id', $visit->doctor_id)
                                      ->whereDate('date', date('Y-m-d',strtotime($visit->date)))
                                      ->where('queue_status', 1)
                                      ->where('id', '!=', $visit->vid)
                                      ->whereNotNull('token_no')
                                      ->exists();
            if ($alreadyServing) {
                return response()->json([
                    'success' => false,
                    'message' => 'Another token is already serving. Please complete or hold it first.'
                ]);
            }
        }

        $visit->queue_status = $request->status;
        $visit->save();

        // if(($request->action??false) && ($request->action == 'call_next')){
        //     $nextVisit = Visitlog::where('doctor_id', $visit->doctor_id)
        //                     ->whereDate('date', date('Y-m-d',strtotime($visit->date)))
        //                     ->where('queue_status', 0)
        //                     ->orderBy('token_no', 'asc')
        //                     ->first();

        //     if($nextVisit){
        //         $nextVisit->queue_status = 1; // Set next patient as serving
        //         $nextVisit->save();
        //     }
        // }

        if(env('OPD_QUEUE_WEBSOCKET_ENABLED',false)){
            event(new \App\Events\OPDQueueUpdated(
                $visit->doctor_id,
                $this->get_opd_queue_multiple_doctor_data(new Request([
                    'org_id' => $visit->hospital_id,
                    'doctors' => [$visit->doctor_id]
                ]))
            ));
        }

        return response()->json(['status'=>'success', 'message'=> 'Status updated successfully']);
    }

