   public function search(Request $request)
    {
        $query = $request->input('q');
        $doctorId = $request->input('doctor_id');

        if (empty($query)) {
            return response()->json([]);
        }

        $comments = ClinicalComment::select('comment', 'context')
            ->where('context', 'complaint')
            ->orderBy('id', 'DESC')
            ->get();

        $filteredComments = collect($comments)
            ->filter(function ($comment) use ($query) {
                return Str::contains(Str::lower($comment->comment), Str::lower($query));
            })
            ->sort(function ($a, $b) use ($query) {
                $aComment = strtolower($a->comment);
                $bComment = strtolower($b->comment);
                $query = strtolower($query);

                // Count query occurrences and position
                $aPos = strpos($aComment, $query);
                $bPos = strpos($bComment, $query);

                $aCount = substr_count($aComment, $query);
                $bCount = substr_count($bComment, $query);

                // Sort by:
                // 1. Higher match count
                // 2. Earlier match position
                // 3. Shorter length
                return [$bCount, $aPos === false ? PHP_INT_MAX : $aPos, strlen($aComment)]
                    <=> [$aCount, $bPos === false ? PHP_INT_MAX : $bPos, strlen($bComment)];
            })
            ->pluck('comment')
            ->values()
            ->all();

        return response()->json($filteredComments);
}



public function diagnosis_search(Request $request)
{
    $query = $request->input('q');
    $doctorId = $request->input('doctor_id');

    if (empty($query)) {
        return response()->json([]);
    }

    // Only return symptoms that start with the query
    $symptoms = Symptom::where(function ($queryBuilder) use ($query, $doctorId) {
        $queryBuilder->where('name', 'LIKE', "{$query}%")
                     ->where(function ($query) use ($doctorId) {
                         $query->whereNull('doctor_id')
                               ->orWhere('doctor_id', $doctorId)
                               ->orWhere('doctor_id', 'global');
                     })
                     ->where('status', 'diagnosis');
    })->get(['id', 'name']);

    return response()->json($symptoms);
}

public function add_investigation(Request $request)
{
    $visit_id = $request->visit_id;

    $len = count($request->tests);
    for ($i = 0; $i < $len; $i++) {
        $ir = new InvestigationRequest;
        $ir->visit_id = $visit_id;
        $ir->service_id = $request->tests[$i];
        $ir->save();
    }

    return response()->json(['status' => 'success','message' => 'Investigation added successfully']);
}

