public function delete_alert(Request $request)
{
    Sticker::where('visit_table_id', $request->visit_id)->where('id', $request->id)->delete();
    return response()->json(['status' => 'success','message' => 'Investigation deleted successfully']);
}

public function delete_icd(Request $request){
    PatientICDData::where('visit_id', $request->visit_id)->where('id', $request->id)->delete();
    return response()->json(['status' => 'success','message' => 'Investigation deleted successfully']);
}

public function test_search(Request $request)
{
    $query = $request->input('q');

    if (empty($query)) {
        return response()->json([]);
    }

    // Only return services that start with the query and have the flag 'test'
    $services = Service::where('hospital_services.service', 'LIKE', "{$query}%")
                        ->leftJoin('hospital_services_index', 'hospital_services_index.service', '=', 'hospital_services.id')
                        ->where('hospital_services.flag', 'test')
                        ->select([
                            'hospital_services.id',
                            'hospital_services.service as service',
                            DB::raw(
                                'CASE WHEN hospital_services_index.active = 1 THEN true ELSE false END as inhouse'
                            )
                        ])
                       ->get();

    return response()->json($services);
}


public function add_alert(Request $request)
{
    $visit_id = $request->visit_id;

    $sticker = new Sticker;
    $sticker->visit_table_id = $visit_id;
    $sticker->sticker = $request->alert;
    $sticker->c_date = date('Y-m-d');
    $sticker->save();

    // $this->add_comment($visit_id,$request->alert,'alert');


    return response()->json(['status' => 'success','message' => 'Alert added successfully']);

}



