     public function medicinesearch(Request $request)
        {
            $query = $request->input('q');
            if (empty($query)) {
                return response()->json([]);
            }

            $medicines = DB::table('doc_drug_used_brands as d')
                            ->leftJoin('drug_comb_brand_index as cc', function ($join) {
                                $join->on('d.brand_id', '=', 'cc.id')
                                    ->where('d.d_type', '=', 'cc');
                            })
                            ->leftJoin('drug_brand_index as ss', function ($join) {
                                $join->on('d.brand_id', '=', 'ss.id')
                                    ->where('d.d_type', '=', 'ss');
                            })
                            ->select(
                                'd.*',
                                DB::raw("CASE
                                            WHEN d.d_type = 'cc' THEN cc.brand_name
                                            WHEN d.d_type = 'ss' THEN ss.brand_name
                                            ELSE NULL
                                        END as name")
                            )
                            ->having('name', 'LIKE', "%{$query}%")
                            ->groupBy('d.brand_id')
                            ->get();


            return response()->json($medicines);
        }



        public function medicinesearch2(Request $request)
        {
                $search = $request->input('q');
                $page = $request->input('page', 1);
                if (empty($search)) {
                    return response()->json([]);
                }



        if($request->search_type == 'quick'){
            $doctor_id = $request->doctor_id;

            $results = DB::table('doc_drug_used_brands as d')
                                ->leftJoin('drug_comb_brand_index as cc', function ($join) {
                                    $join->on('d.brand_id', '=', 'cc.id')
                                        ->where('d.d_type', '=', 'cc');
                                })
                                ->leftJoin('drug_brand_index as ss', function ($join) {
                                    $join->on('d.brand_id', '=', 'ss.id')
                                        ->where('d.d_type', '=', 'ss');
                                })
                                ->select(
                                    'd.*',
                                    DB::raw("CASE
                                                WHEN d.d_type = 'cc' THEN cc.brand_name
                                                WHEN d.d_type = 'ss' THEN ss.brand_name
                                                ELSE NULL
                                            END as name")
                                )
                                ->having('name', 'LIKE', "%{$search}%")
                                ->where('d.doctor_id', $doctor_id)
                                // ->groupBy('d.brand_id')
                                ->orderBy('d.id', 'asc')
                                ->get();


            }else{


                $search = strtolower($search);

                $unionSql = "
                    (
                        SELECT `id` AS `brand_id`, `brand_name` AS `name`, 'ss' AS d_type
                        FROM `drug_brand_index`
                        WHERE LOWER(brand_name) LIKE ?
                    )
                    UNION
                    (
                        SELECT `id` AS `brand_id`, `brand_name` AS `name`, 'cc' AS d_type
                        FROM `drug_comb_brand_index`
                        WHERE LOWER(brand_name) LIKE ?
                    )
                ";

                $results = DB::table(DB::raw("({$unionSql}) as merged"))
                    ->addBinding(["%{$search}%", "%{$search}%"]) // bindings for both LIKEs in union
                    ->whereRaw('LOWER(name) LIKE ?', ["%{$search}%"]) // main filter
                    ->orderByRaw("
                        CASE
                            WHEN LOWER(name) LIKE ? THEN 0
                            WHEN LOWER(name) LIKE ? THEN 1
                            WHEN LOWER(name) LIKE ? THEN 2
                            ELSE 3
                        END,
                        LENGTH(name)
                    ", [
                        "{$search}%",
                        "% {$search}%",
                        "%{$search}%"
                    ])
                    ->get();



            }

            foreach($results as $r){
                //  $r->formulation1 = $this->get_formulation($r->brand_id, $r->d_type);
                $formulation = $this->get_formulation($r->brand_id, $r->d_type);
                $r->formulation = '';

                // dd($formulation);

                if($r->d_type == 'ss'){
                    foreach($formulation as $f){
                        $form = $f->form ?? '';
                        $dose = $f->dose ?? '';
                        $unit = $f->unit_name ?? '';
                        $drug = $f->drug_name ?? '';

                        $r->formulation = $drug.' '.$dose.' '.$unit.' ('.$form.')';

                    }
                }else{
                    foreach($formulation as $f){
                        $form = $f->form;

                        $strArray = [];
                        foreach($f->comb_name as $cn){
                            $formulation = $cn->drug_name;
                            $dose = $cn->dose;
                            $unit_name = $cn->unit_name;

                            $strArray[] = $formulation. ' '.$dose.' '.$unit_name;
                        }
                        $str = implode(' + ', $strArray);
                        $r->formulation = $str.'('.$form.')';
                    }
                }
            }


            // return response()->json($results);
            return response()->json([
                'items' => $results, // Paginated results
                // 'pagination' => [
                //     'has_more' => $results->hasMorePages(), // Boolean for more results
                // ]
            ]);
        }
        public function medicinesearch3(Request $request)
        {
            $search = $request->input('q');
            $page = $request->input('page', 1);
            if (empty($search)) {
                return response()->json([]);
            }
            if($request->search_type == 'quick'){
                $doctor_id = $request->doctor_id;

                $results = DB::table('doc_drug_used_brands as d')
                                    ->leftJoin('drug_comb_brand_index as cc', function ($join) {
                                        $join->on('d.brand_id', '=', 'cc.id')
                                            ->where('d.d_type', '=', 'cc');
                                    })
                                    ->leftJoin('drug_brand_index as ss', function ($join) {
                                        $join->on('d.brand_id', '=', 'ss.id')
                                            ->where('d.d_type', '=', 'ss');
                                    })
                                    ->select(
                                        'd.*',
                                        DB::raw("CASE
                                                    WHEN d.d_type = 'cc' THEN cc.brand_name
                                                    WHEN d.d_type = 'ss' THEN ss.brand_name
                                                    ELSE NULL
                                                END as name")
                                    )
                                    ->having('name', 'LIKE', "%{$search}%")
                                    ->where('d.doctor_id', $doctor_id)
                                    // ->groupBy('d.brand_id')
                                    ->orderBy('d.id', 'asc')
                                    ->limit(50)
                                    ->get();
            }else{
                $search = strtolower($search);
                $unionSql = "
                    (
                        SELECT `id` AS `brand_id`, `brand_name` AS `name`, 'ss' AS d_type
                        FROM `drug_brand_index`
                        WHERE LOWER(brand_name) LIKE ?
                    )
                    UNION
                    (
                        SELECT `id` AS `brand_id`, `brand_name` AS `name`, 'cc' AS d_type
                        FROM `drug_comb_brand_index`
                        WHERE LOWER(brand_name) LIKE ?
                    )
                ";

                $results = DB::table(DB::raw("({$unionSql}) as merged"))
                    ->addBinding(["%{$search}%", "%{$search}%"]) // bindings for both LIKEs in union
                    ->whereRaw('LOWER(name) LIKE ?', ["%{$search}%"]) // main filter
                    ->orderByRaw("
                        CASE
                            WHEN LOWER(name) LIKE ? THEN 0
                            WHEN LOWER(name) LIKE ? THEN 1
                            WHEN LOWER(name) LIKE ? THEN 2
                            ELSE 3
                        END,
                        LENGTH(name)
                    ", [
                        "{$search}%",
                        "% {$search}%",
                        "%{$search}%"
                    ])
                    ->limit(50)
                    ->get();
            }
            foreach($results as $r){
                //  $r->formulation1 = $this->get_formulation($r->brand_id, $r->d_type);
                $formulation = $this->get_formulation($r->brand_id, $r->d_type);
                $r->formulation = '';

                // dd($formulation);

                if($r->d_type == 'ss'){
                    foreach($formulation as $f){
                        $form = $f->form ?? '';
                        $dose = $f->dose ?? '';
                        $unit = $f->unit_name ?? '';
                        $drug = $f->drug_name ?? '';

                        $r->formulation = $drug.' '.$dose.' '.$unit.($form?' ('.$form.')':'');

                    }
                }else{
                    foreach($formulation as $f){
                        $form = $f->form;

                        $strArray = [];
                        foreach($f->comb_name as $cn){
                            $formulation = $cn->drug_name;
                            $dose = $cn->dose;
                            $unit_name = $cn->unit_name;

                            $strArray[] = $formulation. ' '.$dose.' '.$unit_name;
                        }
                        $str = implode(' + ', $strArray);
                        $r->formulation = $str.($form?'('.$form.')':'');
                    }
                }
            }

            return response()->json($results);
        }
