        public function save_visit_other(Request $request){

            // return $request->all();
            $visit = Visitlog::find($request->visit_id);

            VisitClinicalData::where('visit_id', $request->visit_id)->delete();
            $data = [];
            for($i = 0; $i < count($request->diagnosis); $i++){
                $data[] = [
                    'name' => $request->diagnosis[$i],
                    'comment' => $request->d_comment[$i],
                ];

                $existingComment = ClinicalComment::where('user_id', $visit->doctor_id)
                                                    ->where('comment', $request->d_comment[$i])
                                                    ->where('context', 'diagnosis')
                                                    ->first();

                if (!$existingComment) {
                $comment = new ClinicalComment;
                $comment->user_id = $visit->doctor_id;
                $comment->comment = $request->d_comment[$i];
                $comment->context = 'diagnosis';
                $comment->save();
                }


            }

            $cc = [];
            for($i = 0; $i < count($request->cc); $i++){
                $cc[] = [
                    'name' => $request->cc[$i],
                    'comment' => $request->c_comment[$i],
                ];

                $existingComment = ClinicalComment::where('user_id', $visit->doctor_id)
                                                    ->where('comment', $request->c_comment[$i])
                                                    ->where('context', 'cc')
                                                    ->first();

                    if (!$existingComment) {
                    $comment = new ClinicalComment;
                    $comment->user_id = $visit->doctor_id;
                    $comment->comment = $request->c_comment[$i];
                    $comment->context = 'cc';
                    $comment->save();
                    }
            }

            $cd = new VisitClinicalData;
            $cd->visit_id = $request->visit_id;
            $cd->diagnosis = json_encode($data);
            $cd->cc = json_encode($cc);
            $cd->save();

            return response()->json(['status'=>'success', 'message'=>'Saved Successfully']);

        }

        public function save_medicine(Request $request){

            $visit = Visitlog::find($request->visit_id);
            Pres_final::where('visit_table_id',$request->visit_id)->delete();
            $lenght = count($request->medicines);
            for($i = 0; $i < $lenght-1; $i++){

                $medicine = $request->medicines[$i];  // 105|R2|ss
                $brand_id = explode('|', $medicine)[0]; // 105

                $d_type = explode('|', $medicine)[1]; // ss

                $pf = new Pres_final;
                $pf->save_type = 'p';
                $pf->visit_table_id = $request->visit_id;
                $pf->brand_id = $brand_id;
                $pf->d_type = $d_type;
                $pf->nc = 'false';
                $pf->vic = 'true';
                $pf->rs = 0;
                $pf->it = $request->dosage[$i]." (". $request->when_to_take[$i].")";
                $pf->dt = $request->frequency[$i];
                $pf->save();

                $existingComment = ClinicalComment::where('user_id', $visit->doctor_id)
                                                    ->where('comment', $request->c_comment[$i])
                                                    ->where('context', 'medicine')
                                                    ->first();

                if (!$existingComment) {
                    $comment = new ClinicalComment;
                    $comment->user_id = $visit->doctor_id;
                    $comment->comment = $brand_id;;
                    $comment->context = 'medicine';
                    $comment->save();
                }

            }

            return response()->json(['status'=>'success', 'message' => 'Medicine Added Successfully']);

        }

