          //complaints save

 // Retrieve existing complaint IDs for the given visit
$existingComplaints = ClinicalComplaints::where('visit_id', $v_id)
    ->pluck('complaints')
    ->toArray();

$existingComplaintIds = [];
foreach ($existingComplaints as $existingComplaint) {
    $existingComplaintIds = array_merge($existingComplaintIds, explode(',', $existingComplaint));
}

$complaints = $req->input('insurance', []);
$newComplaintIds = [];

if (is_array($complaints)) {
    foreach ($complaints as $complaint) {
        if (is_numeric($complaint)) {
            // If it's an existing complaint (ID) and not already in existingComplaintIds
            if (!in_array($complaint, $existingComplaintIds)) {
                $newComplaintIds[] = $complaint;
            }
        } else {
            // Fetch the ID of the string from the Symptom table
            $complaintId = Symptom::where('name', $complaint)->value('id');
            if ($complaintId && !in_array($complaintId, $existingComplaintIds)) {
                $newComplaintIds[] = $complaintId;
            }
        }
    }
}

if (!empty($newComplaintIds)) {
    foreach ($newComplaintIds as $newComplaintId) {
        $clinicalComplaint = new ClinicalComplaints();
        $clinicalComplaint->doctor_id = $req->input('doctor_id');
        $clinicalComplaint->hospital_id = $org_id;
        $clinicalComplaint->visit_id = $v_id;
        $clinicalComplaint->patient_id = $visit->patient_id;
        $clinicalComplaint->complaints = $newComplaintId;
        $clinicalComplaint->save();
    }
}

    // Fetch existing tests for the visit
    $existingTests = ClinicalTests::where('visit_id', $v_id)
        ->pluck('tests')
        ->toArray();

    // Convert existing tests to a flat array of test names
    $existingTestList = [];
    foreach ($existingTests as $tests) {
        $existingTestList = array_merge($existingTestList, explode(',', $tests));
    }

    // Fetch new tests from the request
    $testsInput = $req->input('tests', []);

    // Filter out existing tests
    $newTests = array_diff($testsInput, $existingTestList);

    if (!empty($newTests)) {
        // Convert new tests to a comma-separated string
        $tests = implode(',', $newTests);

        $clinicaltest = new ClinicalTests();
        $clinicaltest->doctor_id = $req->input('doctor_id');
        $clinicaltest->hospital_id = $org_id;
        $clinicaltest->visit_id = $v_id;
