$diagnoses = $req->input('diagnosis', []);
$durations = $req->input('duration', []);
$dates = $req->input('date', []);
$descriptions = $req->input('description', []);
$checkStatuses = $req->input('check_status', []);

$maxCount = max(count($diagnosisIds), count($diagnoses), count($durations), count($dates), count($descriptions), count($checkStatuses));

for ($i = 0; $i < $maxCount; $i++) {
    $diagnosisId = $diagnosisIds[$i] ?? null;
    $diagnosis = $diagnoses[$i] ?? null;
    $duration = $durations[$i] ?? null;
    $date = $dates[$i] ?? null;
    $description = $descriptions[$i] ?? null;
    $checkStatus = $checkStatuses[$i] ?? null;

    if ($diagnosis) {
        if ($diagnosisId) {
            // Check if the diagnosis already exists for updating
            $existingDiagnosis = ClinicalDiagnosis::find($diagnosisId);
            if ($existingDiagnosis) {
                $existingDiagnosis->update([
                    'diagnosis' => $diagnosis,
                    'duration' => $duration,
                    'date' => $date,
                    'description' => $description,
                    'check_status' => $checkStatus,
                ]);
            }
        } else {
            // Create new diagnosis record
            $diagnosisId = is_numeric($diagnosis) ? $diagnosis : Symptom::where('name', $diagnosis)->value('id');
            ClinicalDiagnosis::create([
                'hospital_id' => $org_id,
                'doctor_id' => $req->input('doctor_id'),
                'visit_id' => $v_id,
                'patient_id' => $visit->patient_id,
                'diagnosis' => $diagnosisId,
                'duration' => $duration,
                'date' => $date,
                'description' => $description,
                'check_status' => $checkStatus,
            ]);
        }
    }
}





