        public function copy_other_diagnosis_data(Request $req){


            $diagnosis =  Visit_other_diagnosis_v2::where('is_transferred',0)->groupBy('visit_table_id')->orderBy('id','asc')->get();


            $data = [];
            foreach($diagnosis as $d){
