        public function get_object_visit($visit_id){
            $res = Visit_other_diagnosis_v2::where('visit_table_id',$visit_id)->get();

                $data = [];
                foreach($res as $r){
                    $d['name'] = $r->od;
                    $d['comment'] = $r->comment;
                    $d['duration'] = '';
                    $d['date'] = '';
                    $d['is_active'] = '';

                    array_push($data,$d);

                }

            return $data;
        }




        public function copy_clinical_history_comment_data(Request $req){

                $comments =  Clinical_history_comment_data::where('is_transferred',0)->groupBy('visit_table_id')->limit(1)->orderBy('id','asc')->get();

                $data = [];
                foreach($comments as $c){
                    $visit_comments = $this->get_object_visit_wise($c->visit_table_id);

                    $data[] = [
                        'visit_id' => $c->visit_table_id,
                        'comment' => $visit_comments
                    ];

                }


                foreach($data as $d){

                    $cd = VisitClinicalData::firstOrNew(['visit_id' => $d['visit_id']]);
                    $cd->others = json_encode($d['comment']);
                    $cd->save();

                    Clinical_history_comment_data::where('visit_table_id', $d['visit_id'])->update(['is_transferred'=> 1]);
                }


                return "success";
            }


            public function get_object_visit_wise($visit_id){
                $jsonData = Clinical_history_comment_data::where('visit_table_id',$visit_id)->get();

                $collection = collect($jsonData);

                // Transform into the desired structure
                $data = $collection->mapWithKeys(function ($item) {
                    return [
                        $item['cb_id'] => [
                            'source' => $item['cb_id'],
                            'value' => $item['comment'],
                            'updated_at' => ''
                        ]
                    ];
                })->toArray();

                return $data;
            }



