            public function isPageLocked($vid,$context)
            {
                if(empty($vid) || empty($context)) return false;
                $sessionId = session()->getId();
                $tabId = request('tab_id');
                $visit = VisitClinicalData::where('visit_id',$vid)->where('context',$context)->first();
                if (!$visit) {
                    $visit = VisitClinicalData::create(['visit_id' => $vid, 'others' => '{}', 'context'=>$context]);
                }
                $others = json_decode($visit->other_data ?? '[]',true);

                $lock = $others['edit_lock'] ?? null;

                $lockedAt = \Carbon\Carbon::parse($lock['locked_at'] ?? now()->subMinutes(2));
                if (!$lock || now()->diffInSeconds($lockedAt) > 60) {
                    // No lock or lock expired (extended TTL: 60s)
                    $others['edit_lock'] = [
                        'session_id' => $sessionId,
                        'tab_id' => $tabId ?: ($lock['tab_id'] ?? null),
                        'locked_by' => auth()->user()->id ?? null,
                        'locked_at' => now()->toDateTimeString(),
                    ];
                    $visit->other_data = json_encode($others);
                    $visit->save();

                    $lock = false;
                } elseif ($lock['session_id'] === $sessionId) {
                    // Same session - allow all tabs of the same session without locking
                    if (!empty($tabId) && empty($lock['tab_id'])) {
                        $others['edit_lock']['tab_id'] = $tabId;
                        $visit->other_data = json_encode($others);
                        $visit->save();
                    }
                    $lock = false;
                } else {
                    $lock = true;
                }

                return $lock;
            }

            public function takeOverEdit(Request $req)
            {
                $req->validate(['vid'=>'required','context'=>'required']);
                $sessionId = session()->getId();
                $tabId = $req->tab_id;
                $visit = VisitClinicalData::where('visit_id',$req->vid)->where('context',$req->context)->first();
                if (!$visit) {
                    $visit = VisitClinicalData::create(['visit_id' => $req->vid, 'others' => '{}', 'context'=>$req->context]);
                }
                $others = json_decode($visit->other_data ?? '[]',true);

                $others['edit_lock'] = [
                    'session_id' => $sessionId,
                    'tab_id' => $tabId,
                    'locked_by' => auth()->user()->id ?? null,
                    'locked_at' => now()->toDateTimeString(),
                ];

                $visit->other_data = json_encode($others);
                $visit->save();

                return response()->json(['status' => true, 'lock' => $others['edit_lock']]);
            }

            public function pingOverEdit(Request $req)
            {
                $req->validate(['vid'=>'required','context'=>'required']);
                $sessionId = session()->getId();
                $tabId = $req->tab_id;
                $visit = VisitClinicalData::where('visit_id',$req->vid)->where('context',$req->context)->first();
                if (!$visit) {
                    return response()->json(['status' => false, 'reason' => 'not_found']);
                }
                $others = json_decode($visit->other_data ?? '[]',true);

                $lock = $others['edit_lock'] ?? null;

                $lockedAt = \Carbon\Carbon::parse($lock['locked_at'] ?? now()->subMinutes(2));
                $diffSec = now()->diffInSeconds($lockedAt);
                $isExpired = $diffSec > 60;

                // If someone else took the lock (different user session OR different tab)
                if ($lock && !$isExpired) {
                    if ($lock['session_id'] !== $sessionId) {
                        $lockedByName = $lock['locked_by_name'] ?? null;
                        if (!$lockedByName && !empty($lock['locked_by'])) {
                            $u = \App\Models\User::find($lock['locked_by']);
                            $lockedByName = $u ? ($u->name ?: $u->email) : ('User #' . $lock['locked_by']);
                        }
                        return response()->json([
                            'status' => false,
                            'reason' => 'user_conflict',
                            'locked' => true,
                            'locked_by' => $lock['locked_by'] ?? null,
                            'locked_by_name' => $lockedByName ?? 'another user',
                            'locked_at' => $lock['locked_at'] ?? null,
                            'seconds_remaining' => max(0, 60 - $diffSec),
                            'message' => [
                                'session_id' => $lock['session_id'],
                                'locked_by' => $lock['locked_by'] ?? null,
                                'locked_by_name' => $lockedByName ?? 'another user',
                                'locked_at' => $lock['locked_at'] ?? null,
                                'seconds_remaining' => max(0, 60 - $diffSec),
                            ]
                        ]);
                    }
                }

                // Update lock timestamp (TTL: 60s)
                $currentUser = auth()->user();
                $currentUserName = $currentUser ? ($currentUser->name ?: $currentUser->email) : 'User';
                $others['edit_lock'] = [
                    'session_id' => $sessionId,
                    'tab_id' => $tabId ?: ($lock['tab_id'] ?? null),
                    'locked_by' => $currentUser ? $currentUser->id : 1,
                    'locked_by_name' => $currentUserName,
                    'locked_at' => now()->toDateTimeString(),
                ];

                $visit->other_data = json_encode($others);
                $visit->save();

                return response()->json(['status' => true, 'locked' => false, 'message' => $others['edit_lock']]);
            }

            public function releasePageLock(Request $req)
            {
                $req->validate(['vid'=>'required','context'=>'required']);
                $sessionId = session()->getId();
                $tabId = $req->tab_id;
                $visit = VisitClinicalData::where('visit_id',$req->vid)->where('context',$req->context)->first();
                if ($visit) {
                    $others = json_decode($visit->other_data ?? '[]',true);
                    $lock = $others['edit_lock'] ?? null;
                    if ($lock && $lock['session_id'] === $sessionId && (empty($tabId) || (!empty($lock['tab_id']) && $lock['tab_id'] === $tabId))) {
                        unset($others['edit_lock']);
                        $visit->other_data = json_encode($others);
                        $visit->save();
                    }
                }
                return response()->json(['status' => true]);
            }

            public function update_context(Request $req){

               // get all records where context is null
               $vcd = VisitClinicalData::join('visitlog', 'visitlog.id', '=', 'visit_clinical_data.visit_id')
               ->whereNull('visit_clinical_data.context')
               ->select('visit_clinical_data.visit_id', 'visitlog.visit_status')
               ->get();

           $updated = 0;

           foreach ($vcd as $v) {
               $visit_id = $v->visit_id;
               $context = ($v->visit_status == 0) ? 'patient.urology_v2' : 'patient.discharge_summary_v4';

               $res = VisitClinicalData::where('visit_id', $visit_id)->update(['context' => $context]);

               if ($res) {
                   $updated++;
               } else {
                   // Debug: optional log
                   \Log::warning("Update failed for visit_id: $visit_id");
               }
           }

               return "success";


            }




    public function handwrite_prescription(Request $request, $vid=null, $t_id=null){

        $user = Auth::user();
        $org_id = $user->org_id;

        $visit =  $this->today_visit_list($request);
        $context = FacadesRoute::currentRouteName();
        if (!empty($vid)) {
            $visit_id = $vid;
        } else {
            return view('admin.patient.clinical.open_prescription', compact('visit','context'));
        }

        $lock = $this->isPageLocked($visit_id,$context);

        $patient = Patient::join('visitlog', 'visitlog.patient_id', '=', 'pi.id')
                        ->leftJoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                        ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                        ->select('pi.*','visitlog.created_at as created_at','visitlog.visit_id as visit_no', 'visitlog.doctor_id','doctor_db.key_spec', 'doctor_db.name as doctor_name','doctor_db.others as doctor_other_data','visitlog.fud','visitlog.edit_lock','doctor_specialities.id as spid','doctor_db.id as did')
                        ->where('visitlog.id', $visit_id)
                        ->first();


        $vcd = VisitClinicalData::where('visit_id', $visit_id)->where('context',$context)->first();
        if (!$vcd) {
            $vcd = VisitClinicalData::create(['visit_id' => $visit_id, 'others' => '{}', 'context'=>$context]);
        }
        // Decode the clinical data safely
        $formData = is_string($vcd->others ?? '') ? json_decode($vcd->others, true) : [];
        $medicines = $this->get_medicine_list($visit_id);
        $q_medicines = $this->get_q_medicine_list($visit_id, $patient->doctor_id);

        // $dynamic_comments =  $this->get_clinical_comments($patient->did, $context);

        $dynamic_comments = ClinicalComment::select('context', 'comment','others')
                                                    ->where('user_id', $patient->doctor_id)
                                                    ->where('context',$context)
                                                    ->get()->toArray();

        $templates = $this->get_templates($patient->did, $context);
        if($t_id){
            $template = Template::where('id', $t_id)->first();
            if($template){
                $formData = json_decode($template->template, true);
            }
        }

        $recentVisits =  Visitlog::leftjoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                        ->leftJoin('pi', 'pi.id', '=', 'visitlog.patient_id')
                        ->leftJoin('patient_billing', function ($join) {
                            $join->on('patient_billing.visit_id', '=', 'visitlog.id');
                            $join->on('visitlog.patient_id', '=', 'pi.id');
                        })

                        ->select('visitlog.*',
                            'visitlog.created_at as created',
                            'visitlog.doctor_id as did',
                            'visitlog.id as vid',
                            'visitlog.patient_id as pid',
                            'doctor_db.name as doctor_name',
                            'pi.Fname',
                            'pi.Lname',
                            'pi.age',
                            'pi.sex',
                            'pi.dob',
                            'pi.mobile_no',
                            'pi.prefix',
                            'patient_billing.id as bill_id',
                            'patient_billing.status as bill_status'

                        )
                        ->where('visitlog.hospital_id', $org_id)
                        ->where('visitlog.visit_status', 0)
                        ->where('visitlog.patient_id', $patient->id)
                        ->where('visitlog.doctor_id', $patient->doctor_id)
                        ->orderBy('visitlog.id', 'DESC')
                        ->groupBy('visitlog.id')
                        ->limit(20)
                        ->skip(1)
                        ->get();

        return view('admin.patient.clinical.handwrite_prescription', compact('visit_id','medicines','q_medicines','formData','visit','patient','templates','context','dynamic_comments','lock','recentVisits'));
    }
