    public function save_doctor_patient_tag(Request $request){
        $request->validate([
            'did' => 'required',
            'uhid' => 'required',
            'tag' => 'required',
        ]);

        $tag = trim($request->tag);

        $exists = \DB::table('doctor_patient_tags')
            ->where('doctor_id', $request->did)
            ->where('patient_id', $request->uhid)
            ->whereRaw('LOWER(tag) = ?', [strtolower($tag)])
            ->exists();

        if ($exists) {
            return response()->json(['status'  => false,'message' => 'Tag already exists']);
        }

        $id = \DB::table('doctor_patient_tags')->insertGetId([
            'doctor_id' => $request->did,
            'patient_id' => $request->uhid,
            'tag' => $tag,
            'created_at' => now(),
            'updated_at' => now(),
        ]);

        return response()->json([
            'status' => true,
            'message' => 'Tag Added Successfully',
        ]);
    }
    public function remove_doctor_patient_tag(Request $request){
        $request->validate([
            'did' => 'required',
            'uhid' => 'required',
            'tag' => 'required',
        ]);

        $deleted = \DB::table('doctor_patient_tags')
            ->where('doctor_id', $request->did)
            ->where('patient_id', $request->uhid)
            ->where('tag', $request->tag)
            ->delete();

        if ($deleted) {
            return response()->json(['status' => true, 'message' => 'Tag removed successfully']);
        } else {
            return response()->json(['status' => false, 'message' => 'Tag not found']);
        }
    }
