    public function fetch_visit_data_v2(Request $request)
    {
        $visit =  Visitlog::leftjoin('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                    ->leftJoin('pi', 'pi.id', '=', 'visitlog.patient_id');

        $visit->where('visitlog.hospital_id', auth()->user()->org_id);
        $visit->where('visit_status', 0);

        $loginDoc = \App\Models\admin\HospitalDoctor::find(auth()->user()->doctor_index_id??'')->doc_id??false;

        if($request->start_date && $request->end_date){
            $visit->whereBetween('visitlog.date', [$request->start_date, $request->end_date]);
        }else{
            // $visit->whereBetween('visitlog.date', [date('Y-m-d', strtotime('-20 days')), date('Y-m-d')]);
            $visit->whereDate('visitlog.date', date('Y-m-d'));
        }
        if($loginDoc){
            $visit->where('visitlog.doctor_id', $loginDoc);
        }
        if($request->doctors??false){
            $visit->whereIn('visitlog.doctor_id', $request->doctors);
        }
        if($request->emergency){
            $visit->where('visitlog.emergency', 1);
        }
        $visit->orderBy('visitlog.id', 'DESC');
        $visit->groupBy('visitlog.id');
        $visit->select([
                        'visitlog.created_at as created',
                        'visitlog.id as vid',
                        'visitlog.date as on_hold',
                        'visitlog.queue_status as queue_status',
                        'visitlog.token_no as token_no',
                        'doctor_db.id as doctor_id',
                        'doctor_db.name as doctor_name',
                        DB::raw("CONCAT(pi.prefix, ' ', pi.Fname, ' ', COALESCE(pi.Lname, '')) as full_name"),
                        'pi.id as uhid',
                        'pi.age',
                        'pi.sex',
                        'pi.dob',
                        'pi.Address',
                        'pi.Fathername',
                        'pi.spousename',
                    ]);
        $visit = $visit->get();


        $vIDs = $visit->pluck('vid')->toArray();
        $billIDs = PatientBilling::whereIn('visit_id', $vIDs)->pluck('id')->toArray();


        $subTotalsQuery = DB::table('patient_gen_bill')
                        ->select(
                            'bill_id',
                            DB::raw("
                            SUM(
                                    (patient_gen_bill.charges * patient_gen_bill.qty)
                                    - IFNULL(patient_gen_bill.discount, 0)
                                ) as subtotal
                            ")
                        )
                        ->where('patient_gen_bill.is_deleted', 0)
                        ->where(function ($q) {
                            $q->whereNull('patient_gen_bill.is_cancelled')
                            ->orWhere('patient_gen_bill.is_cancelled', 0);
                        })
                        ->whereIn('patient_gen_bill.bill_id', $billIDs)
                        ->groupBy('bill_id');

        $paymentTotalQuery = BillingPaymentType::select(
                        'bill_id',
                        DB::raw('SUM(CASE
                                    WHEN billing_payment_type.transaction_type = 0 THEN amount
                                    WHEN billing_payment_type.transaction_type = 1 THEN -amount
                                    ELSE 0
                                END) as total_payment'),
                    )
                    ->whereIn('bill_id', $billIDs)
                    ->groupBy('bill_id');

        $visitServices = PatientGenBill::join('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                                ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                                ->leftJoinSub($subTotalsQuery, 'subtotals', function($join){
                                    $join->on('subtotals.bill_id','=','patient_billing.id');
                                })
                                ->leftJoinSub($paymentTotalQuery, 'payments', function($join){
                                    $join->on('payments.bill_id','=','patient_billing.id');
                                })
                                ->whereIn('patient_billing.visit_id', $vIDs)
                                ->whereIn('hospital_services.flag', ['procedure','consultation_charge'])
                                ->select([
                                    'hospital_services.service as service_name',
                                    'hospital_services.flag as service_flag',
                                    'patient_gen_bill.id as order_id',
                                    'patient_gen_bill.bill_id',
                                    'patient_gen_bill.created_at',
                                    'patient_gen_bill.charges',
                                    'patient_gen_bill.qty',
                                    'patient_gen_bill.discount',
                                    'patient_gen_bill.service_status',
                                    'patient_billing.visit_id',
                                    // Final per-item net amount
                                    DB::raw("
                                        (
                                            (patient_gen_bill.charges * patient_gen_bill.qty)
                                            -
                                            CASE
                                                WHEN subtotals.subtotal > 0 THEN
                                                    IFNULL(patient_gen_bill.discount,0)
                                                    +
                                                    (
                                                        (
                                                            (
                                                                patient_gen_bill.charges
                                                                * patient_gen_bill.qty
                                                            )
                                                            - IFNULL(patient_gen_bill.discount,0)
                                                        )
                                                        * (
                                                            IFNULL(patient_billing.discount,0)
                                                            / subtotals.subtotal
                                                        )
                                                    )
                                                ELSE
                                                    IFNULL(patient_gen_bill.discount,0)
                                            END
                                        ) as item_net_amount
                                    "),
                                    DB::raw("
                                        CASE
                                        -- Fully discounted / zero bill
                                        WHEN (
                                            subtotals.subtotal
                                            - IFNULL(patient_billing.discount,0)
                                        ) <= 0
                                        THEN 'fully_paid'

                                        -- No payment
                                        WHEN IFNULL(payments.total_payment,0) <= 0
                                        THEN 'no_payment'

                                        -- Fully paid
                                        WHEN IFNULL(payments.total_payment,0)
                                            >=
                                            (
                                                subtotals.subtotal
                                                - IFNULL(patient_billing.discount,0)
                                            )
                                        THEN 'fully_paid'

                                        -- Remaining cases
                                        ELSE 'partial_paid'

                                    END as payment_status"),
                                ])
                                ->get()
                                ->groupBy('visit_id');

        // dd($visitServices->toArray());
        $allowedFlags = ['procedure', 'consultation_charge'];

        $visit = $visit->filter(function ($item) use ($visitServices, $allowedFlags) {
            $services = $visitServices[$item->vid] ?? collect([]);
            return $services->contains(function ($service) use ($allowedFlags) {
                return in_array($service->service_flag, $allowedFlags);
            });
        })->values();

        // merge gen_bill_items
        $visit->transform(function ($item) use ($visitServices) {

            $item->gen_bill_items = $visitServices[$item->vid] ?? collect([]);

            // free memory after attaching
            unset($visitServices[$item->vid]);

            return $item;
        });

        if($request->return_collection??false) {
            return $visit;
        }

        return response()->json($visit);
    }




