    public function save_clinical_prescription_notes(Request $request){

        // dd($request->all());
        $visit_id = $request->visit_id;
        $vcd = VisitClinicalData::where('visit_id', $visit_id)->where('context',$request->context)->first();



        if(!$vcd){
            $vcd = new VisitClinicalData;
            $vcd->visit_id = $visit_id;
            $vcd->context = $request->context;
        }

        $freeTextboxData = $request->input('freeTextbox', []);

        // Add updated_at timestamp for each field
        $currentTime = now()->format('Y-m-d H:i:s'); // Get the current timestamp

        $formattedData = [];
        foreach ($freeTextboxData as $key => $value) {
            if (strpos($value, 'data:image/') === 0) {
                // Extract the extension (like png, jpg)
                preg_match('/^data:image\/(\w+);base64,/', $value, $type);
                $extension = strtolower($type[1]) ?? 'png'; // default to png

                // Clean the base64 string
                $value = preg_replace('/^data:image\/\w+;base64,/', '', $value);
                $value = str_replace(' ', '+', $value);

                // Decode it
                $imageData = base64_decode($value);

                $dateMonth = date('Y/m/');

                // Create a unique filename
                $fileName = 'assets/files/clinical/' .$dateMonth. uniqid($key . '_') . '.' . $extension;

                // Ensure the directory exists
                if (!file_exists(public_path('assets/files/clinical/'.$dateMonth))) {
                    mkdir(public_path('assets/files/clinical/'.$dateMonth), 0755, true);
                }

                // Save the file
                file_put_contents(public_path($fileName), $imageData);

                if($vcd->others)
                {
                    $data = json_decode( $vcd->others,true);
                    if (
                        ($data[$key]['value']??false) &&
                        (($data[$key]['visit_id']??false) == $visit_id) &&
                        file_exists(public_path($data[$key]['value']))
                        ) {
                        unlink(public_path($data[$key]['value'] ));
                    }
                }

                // Save only the relative path
                $formattedData[$key] = [
                    'value' => $fileName,
                    'type' => 'canvas',
                    'visit_id' => $visit_id,
                    'updated_at' => $currentTime
                ];
            }else{

                $formattedData[$key] = [
                    'value' => $value,
                    'updated_at' => $currentTime
                ];
            }
        }
        if($request->has('rx_category')){
            $rxCategory = $request->input('rx_category', []);
            $formattedData['rx_category'] = [
                'name' => $rxCategory['name']??'',
                'others' => $rxCategory['others']??[],
                'updated_at' => $currentTime
            ];
        }

        if ($request->has('investigations')) {
            $formattedData['investigations'] = [
                'value' => $request->input('investigations'),
                'updated_at' => $currentTime
            ];
        }
        if ($request->has('prescription')) {
            if($vcd->others)
            {
                $data = json_decode( $vcd->others,true);
                foreach(($data['prescription']??[]) as $key => $pres){
                    if (
                        ($pres['value']??false) &&
                        (($pres['visit_id']??false) == $visit_id) &&
                    file_exists(public_path($pres['value']))
                    ) {
                        unlink(public_path($pres['value'] ));
                    }
                }
            }
            foreach ($request->input('prescription') as $key => $value) {
                if (strpos($value, 'data:image/') === 0) {
                    // Extract the extension (like png, jpg)
                    preg_match('/^data:image\/(\w+);base64,/', $value, $type);
                    $extension = strtolower($type[1]) ?? 'png'; // default to png

                    // Clean the base64 string
                    $value = preg_replace('/^data:image\/\w+;base64,/', '', $value);
                    $value = str_replace(' ', '+', $value);

                    // Decode it
                    $imageData = base64_decode($value);

                    $dateMonth = date('Y/m/');

                    // Create a unique filename
                    $fileName = 'assets/files/clinical/' .$dateMonth. uniqid($key . '_') . '.' . $extension;

                    // Ensure the directory exists
                    if (!file_exists(public_path('assets/files/clinical/'.$dateMonth))) {
                        mkdir(public_path('assets/files/clinical/'.$dateMonth), 0755, true);
                    }

                    // Save the file
                    file_put_contents(public_path($fileName), $imageData);



                    // Save only the relative path
                    $formattedData['prescription'][$key] = [
                        'value' => $fileName,
                        'type' => 'canvas',
                        'visit_id' => $visit_id,
                        'updated_at' => $currentTime
                    ];
                }else{

                    $formattedData['prescription'][$key] = [
                        'value' => $value,
                        'updated_at' => $currentTime
                    ];
                }
            }
        }

        // Convert to JSON format
        $jsonData = json_encode($formattedData, JSON_PRETTY_PRINT);
        // Save to database (assuming 'patients' table has a JSON column 'free_textbox_data')

        $vcd->others = $jsonData;
        $vcd->context = $request->context;
        $vcd->save();


            ###################################################

            $medicines = json_decode($request->medicine_table, true) ?? [];
            $lenght = count($medicines);

            Pres_final::where('visit_table_id', $visit_id)->delete();

            for($i = 0; $i < $lenght-1; $i++){

                $medicine = $medicines[$i]['column_2'];    // 105|ss

                $brand_id = explode('|', $medicine)[0]; // 105
                $source = explode('|', $medicine)[1]; // ss

                //   return $medicines[$i]['column_1'];

                $mark = ($medicines[$i]['column_1'])? "true":"false";

                $pf = new Pres_final;
                $pf->save_type = 'p';
                $pf->visit_table_id = $visit_id;
                $pf->brand_id = $brand_id;
                $pf->d_type = $source;
                $pf->nc = 'false';
                $pf->vic = $mark;
                $pf->rs = 0;
                $pf->it = $medicines[$i]['column_3'];
                $pf->spl_inst = $medicines[$i]['column_4'];
                $pf->dt = $medicines[$i]['column_5'];
                $pf->save();


                if($source === 'ss'){
                    $b =  Drug_brand::find($brand_id);

                    $dose_id = $b->dose_id ?? '';
                    $drug_id = $b->drug_id ?? '';
                    $form_id = $b->form_id?? '';
                }else{
                    $b = DrugCombBrand::find($brand_id);
                    $dose_id = $b->comb_dose_id_entry ??'';
                    $drug_id = $b->comb_id??'';
                    $form_id = $b->form_id??'';
                }

                $this->add_medicine_to_doc_fav_brand($visit_id,$brand_id,$source,$mark);

                $this->add_comment($visit_id,$medicine,'medicine');
                if($b){
                    $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $medicines[$i]['column_3'],$source,'it' );
                    $this->add_medicine_instruction($visit_id,$dose_id , $drug_id, $form_id, $medicines[$i]['column_4'],$source,'spl_inst' );
                }

            }


            $visit = Visitlog::find($visit_id);
            $visit->fud = $request->next_visit_date;
            $visit->save();

        return response()->json([
            'status' => 'success',
            'message' => 'Data saved successfully!',
        ]);

    }

    public function print_open_prescription(Request $request, $id){

        $visit = Visitlog::join('pi', 'pi.id', '=', 'visitlog.patient_id')
                        ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                        ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                        ->select('visitlog.*', 'pi.prefix','pi.Fname','pi.age','pi.dob','pi.sex',
                                'pi.Lname', 'doctor_db.name as doctor_name','pi.mobile_no',
                                'doctor_specialities.name as sp_name',
                                'doctor_db.id as doctor_id','pi.id as uhid')
                        ->where('visitlog.id', $id)
                        ->first();

        $context = $request->context;


        $vcd = VisitClinicalData::where('visit_id', $id)->where('context', $request->context)->first();


        if (!$vcd) {

            return response()->json(['status'=>'error','message'=> 'No record Found']);
            // $vcd = VisitClinicalData::create(['visit_id' => $id, 'others' => '{}']);
        }

        // Decode the clinical data safely
        $data = is_string($vcd->others ?? '') ? json_decode($vcd->others, true) : [];

        $medicines = $this->get_medicine_list($id);


        foreach($medicines as $r){

            $formulation = $this->get_formulation($r->brand_id, $r->d_type);

            if($r->d_type == 'ss'){
                foreach($formulation as $f){
                    $form = $f->form;
                    $dose = $f->dose;
                    $unit = $f->unit_name;
                    $drug = $f->drug_name;

                    $r->formulation = $drug.' '.$dose.' '.$unit.' ('.$form.')';

                }
            }else{
                foreach($formulation as $f){
                    $form = $f->form;

                    $strArray = [];
                    foreach($f->comb_name as $cn){
                        $formulation = $cn->drug_name;
                        $dose = $cn->dose;
                        $unit_name = $cn->unit_name;

                        $strArray[] = $formulation. ' '.$dose.' '.$unit_name;
                    }
                    $str = implode(' + ', $strArray);
                    $r->formulation = $str.'('.$form.')';
                }
            }
        }

        // dd($medicines);
        if($visit->fud){

            $date = Carbon::parse($visit->fud);

            $formattedDate = $date->format('l d/m/Y');

            // Get the current date
            $currentDate = Carbon::now();

            // Calculate the difference in days
            $dayDifference = $currentDate->diffInDays($date)+1;

            // Determine if the difference is past or future
            if ($date->greaterThan($currentDate)) {
                $differenceText = "After {$dayDifference} Days";

                $followup_date = "{$formattedDate} {$differenceText}";
            } else {
                $differenceText = "Before {$dayDifference} Days";
                $followup_date = "";
            }
            // $differenceText = '';

            // Combine the final output

        }else{
            $followup_date = '';
        }

        $header = $request->header;


        $vitals = Vitals::where('visit_id',$visit->id)->first();
        if(is_null($vitals)){
            $bp = [];
            $pulse = [];
        }else{
            $bp = json_decode($vitals->bp, true) ?? [];
            $pulse = json_decode($vitals->pulse, true) ?? [];
            $bp = end($bp);
            $pulse = end($pulse);
        }


        $pres_manual = PresManual::where('visit_table_id',$visit->id)->get();

        return view('admin.pdf.clinical.open_canvas_prescription', compact('visit', 'data','followup_date', 'header', 'bp', 'pulse','pres_manual','vitals', 'vcd','context'));


    }

