    public function load_past_visit_data(Request $request){
        $visit_id = $request->visit_id;
        $context = $request->context;
        $key = $request->input_id;
        $context2 = $request->context2;

        $visit = Visitlog::select('doctor_id','hospital_id','visit_id','patient_id')->where('id', $visit_id)->first();
        if($visit){

            $last_visit = Visitlog::select('id')->where('hospital_id', $visit->hospital_id)->where('doctor_id', $visit->doctor_id)->where('visit_id', ($visit->visit_id - 1))->where('patient_id',$visit->patient_id)->first();

            if($last_visit){
               $vcd = VisitClinicalData::where('visit_id', $last_visit->id)->where('context', $context2)->first();
               if($vcd){
                $data = is_string($vcd->others ?? '') ? json_decode($vcd->others, true) : [];
                $value = isset($data[$key]['value']) ? $data[$key]['value'] : null;

                return response()->json(['status'=>'success', 'value' => $value]);
               }

            }
        }

        return response()->json(['status'=>'error','message'=>'No data found']);
    }


