    public function fetch_procedure_orders(Request $req){

        $user = auth()->user();
        $hosp_id = $user->org_id;

        $start_date =  $req->start_date ??  date('Y-m-d');
        $end_date = $req->end_date ?? date('Y-m-d');
        $report_status =   $req->status ?? 'pending';

        $hospital_setting = HospitalSetting::where([['hospital_id',1],['identifier','process_draft']])->first();

        $draft_process_status = $hospital_setting->status??0;


        $itemQuery = PatientGenBill::leftjoin('hospital_services','hospital_services.id','=','patient_gen_bill.service_id')
                            ->join('patient_billing','patient_billing.id','=','patient_gen_bill.bill_id')
                            ->join('visitlog','visitlog.id','=','patient_billing.visit_id')
                            ->join('pi','pi.id','=','visitlog.patient_id')
                            ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->leftJoin('procedure_logs', 'procedure_logs.order_id', '=', 'patient_gen_bill.id')
                            ->select('patient_gen_bill.*',
                                'hospital_services.service as service_name',
                                'doctor_db.name as doctor_name',
                                'pi.id as uhid',
                                'patient_gen_bill.created_at as bill_date',
                                'pi.prefix as prefix',
                                'pi.Fname as patient_first_name',
                                'pi.Lname as patient_last_name',
                                'pi.sex as sex',
                                'pi.mobile_no as phone',
                                'patient_billing.status as draft_status',
                                'patient_billing.status as pbill_status',
                                'visitlog.visit_status',
                                'procedure_logs.status as status',
                                )
                            ->whereDate('patient_gen_bill.created_at', '>=', $start_date)
                            ->whereDate('patient_gen_bill.created_at', '<=', $end_date)
                            ->where('visitlog.hospital_id',$hosp_id)
                            ->where('hospital_services.flag',"!=",'refund')
                            ->where('hospital_services.flag',"!=",'balance')
                            ->where('hospital_services.flag','procedure')
                            ->where('hospital_services.is_reserved',0)
                            ->when($draft_process_status == 0, function ($query) {
                                $query->where('patient_billing.status', 1);
                            })
                            ->orderBy('patient_billing.id','DESC');


        if($report_status == 'pending'){
            $testList = $itemQuery->where(function ($query) {
                                            $query->whereIn('procedure_logs.status', ['pending','assigned',''])
                                                ->orWhereNull('procedure_logs.status');
                                        })
                                        ->get();
        }else if($report_status == 'completed'){
            $testList = $itemQuery->whereIn('procedure_logs.status', ['approved'])->get();
        }else if($report_status == 'cancelled'){
            $testList = $itemQuery->whereIn('procedure_logs.status', ['cancelled'])->get();
        }else if($report_status == 'rejected'){
            $testList = $itemQuery->whereIn('procedure_logs.status', ['rejected'])->get();
        }else{
            $testList = [];
        }

        $hospital_setting = HospitalSetting::where([['hospital_id',1],['identifier','draft_print_report']])->first();

        $draft_print_status = $hospital_setting->status??0;

        $report_view = view('admin.patient.procedures.procedure_records_table', compact('testList','draft_print_status'))->render();
        return response()->json(['succes' => true, 'report_view' => $report_view]);
    }

    public function print_procedure_supporting_doc(Request $request)
    {
        $request->validate([
            'template_id' => 'required'
        ]);
        if($request->order_id??false){
            $patientData = PatientGenBill::join('patient_billing', 'patient_billing.id', '=', 'patient_gen_bill.bill_id')
                ->join('visitlog', 'visitlog.id', '=', 'patient_billing.visit_id')
                ->join('pi', 'pi.id', '=', 'visitlog.patient_id')
                ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                ->select(
                    DB::raw('CONCAT_WS(" ", pi.prefix, pi.Fname, pi.Lname) as patient_name'),
                    'pi.id as uhid',
                    'doctor_db.name as doctor_name',
                )
                ->where('patient_gen_bill.id', $request->order_id)
                ->first()->toArray();

            $request->merge($patientData);
            $request->merge(['current_date'=>date('d-m-Y'),'current_time'=>date('h:i A')]);
        }
        $inputVariables = $request->all();

        $creator = auth()->user();

        $SNDT['first_name'] = $creator->first_name ?? '';
        $SNDT['last_name'] = $creator->last_name ?? '';
        $SNDT['emp_code'] = $creator->emp_code ?? '';
        $SNDT['created_at'] = now();

        return \App\Services\HospitalTemplateManager::renderById($request->template_id, $inputVariables, 'text-success fw-bold',$SNDT);
    }
