    public function save_procedure_assign_staff(Request $request){
        $request->validate([
            'order_id' => 'required',
            'user_id' => 'required',
            'user_type' => 'required',
        ]);

        $procedure = ProcedureLog::firstOrNew(['order_id'=>$request->order_id]);
        if(!($procedure->status??false)){
            $procedure->status = 'assigned';
            $status['staff_assigned_by'] = date('Y-m-d H:i:s');
            $status['staff_assigned_at'] = date('Y-m-d H:i:s');
            $procedure->status_update_data = json_encode($status);
        }
        $procedure->save();

        $procedureUser = new ProcedureUserLog;
        $procedureUser->procedure_log_id = $procedure->id;
        $procedureUser->user_id = $request->user_id;
        $procedureUser->user_type = $request->user_type;
        $procedureUser->role = $request->role;
        $procedureUser->save();

        return response()->json(['succes' => true, 'message' => 'Assigned successfully']);

    }
