    public function save_examine_note_create(Request $request)
    {
        $request->validate([
            'title' => 'required',
            'context' => 'required',
            'doctor_id' => 'required',
        ]);

        if ($request->id) {
            $note = \App\Models\ExamineNoteTemplate::withTrashed()->find($request->id);
            $data = json_decode($note->parameters ?? '[]', true) ?? [];
        } else {
            $note = new \App\Models\ExamineNoteTemplate;
            $data = [];
        }

        $note->context = $request->context;
        $note->context_id = $request->doctor_id;
        $note->comment = $request->title;

        // SECTION EDIT MODE ΓÇö update only one section
        if ($request->has('section_index')) {
            $idx = intval($request->section_index);

            // rebuild only the updated section from request
            $updated = $this->buildSection(
                $idx,   // request only sends 1 section in this mode
                $request
            );

            if (isset($data[$idx])) {
                $data[$idx] = $updated;
            }
        }

        // FULL CREATE / FULL EDIT MODE ΓÇö rebuild all sections
        else {
            $data = [];

            foreach ($request->sectionName as $secIndex => $sectionName) {
                $data[] = $this->buildSection($secIndex, $request);
            }
        }

        $note->parameters = json_encode($data);
        $note->save();

        return response()->json(['success' => true, 'message' => 'Successfully saved', 'id' => $note->id]);
    }
    private function buildSection($secIndex, $request)
    {
        $section = [];
        $section['name'] = $request->sectionName[$secIndex] ?? '';
        $section['is_bilateral'] = $request->section_bilateral[$secIndex] ?? "";
        $section['section_type'] = $request->section_type[$secIndex] ?? "";
        $section['data'] = [];

        foreach ($request->char_name[$secIndex] ?? [] as $index => $value) {

            $charOptions = $request->char_options[$secIndex][$index] ?? [];

            if (is_string($charOptions)) {
                $charOptions = json_decode($charOptions, true) ?? [];
            }

            $field = [
                'name'  => $value,
                'type'  => $request->char_type[$secIndex][$index] ?? '',
            ];

            if (!empty($charOptions)) {
                $field['options'] = $charOptions;
            }

            $section['data'][] = $field;
        }

        return $section;
    }



