                        // 'lab_investigations.status as status',
                        'patient_billing.id as pbill_id',
                        'patient_billing.status as pbill_status',
                        'patient_billing.status as draft_status',
                        'visitlog.visit_status',
                        'visitlog.emergency',
                        'hospital_services_index.is_outsource as is_outsource',
                        )
                    ->where('visitlog.hospital_id',$hosp_id)
                    ->where('hospital_services.flag',"radiology")
                    ->where('hospital_services.flag',"!=",'refund')
                    ->where('hospital_services.flag',"!=",'balance')
                    ->where('patient_gen_bill.is_deleted',0)
                    ->where('hospital_services.is_reserved',"=",0)
                    ->where('hospital_services_index.is_outsource',"=",1)
                    ;

        if($request->uhid??false){
             $tests->where('pi.id',$request->uhid);
        }
        else if($request->name??false){
            $tests->where('pi.Fname','like','%'.$request->name.'%');
        }
        else if($request->mobile??false){
            $tests->where('pi.mobile_no',$request->mobile);
        }
        else if($request->bill_id??false){
            $tests->where('patient_billing.id',$request->bill_id);
        }
        else{
            $tests->whereDate('patient_gen_bill.created_at', '>=', $request->from_date??date('Y-m-d'));
            $tests->whereDate('patient_gen_bill.created_at', '<=', $request->end_date??date('Y-m-d'));
        }


        $testList = $tests->orderBy('patient_gen_bill.id','DESC')->paginate(50)->withQueryString();

        $tests = [];
        if ($request->ajax())
        {
            return view('admin.patient.radiology.radiology_orders_table_outsource', compact('testList','draft_print_status'))->render();
        }


        return view('admin.patient.radiology.radiology_orders_outsource',compact('testList','draft_print_status'));
    }




