    public function markTemplateDefault(Request $request)
    {
        $request->validate([
            'id' => 'required|exists:templates,id',
            'is_default' => 'required|boolean',
        ]);

        try {
            DB::transaction(function () use ($request) {

                $template = Template::findOrFail($request->id);

                // Agar current template ko default mark kiya ja raha hai
                if ($request->boolean('is_default')) {

                    // Same context ke sab templates ko non-default karo
                    Template::where('context', $template->context)
                        ->where('id', '!=', $template->id)
                        ->update([
                            'is_default' => false,
                        ]);
                }

                // Selected template update karo
                $template->update([
                    'is_default' => $request->boolean('is_default'),
                ]);
            });

            return response()->json([
                'status' => true,
                'message' => 'Default template updated successfully.',
            ]);

        } catch (\Exception $e) {

            return response()->json([
                'status' => false,
                'message' => 'Unable to update default template.',
                'error' => $e->getMessage(),
            ], 500);
        }
    }

    public function save_procedure_report_data(Request $request){

        // dd($request->all());
        $visit_id = $request->visit_id;
        $order_id = $request->order_id;
        $vcd = ProcedureLog::where('order_id', $order_id)->first();
        if(!$vcd){
            $vcd = new ProcedureLog;
            $vcd->order_id = $order_id;
        }

        $freeTextboxData = $request->input('freeTextbox', []);
        // Add updated_at timestamp for each field
        $currentTime = now()->format('Y-m-d H:i:s'); // Get the current timestamp
        $formattedData = [];
        foreach ($freeTextboxData as $key => $value) {
            $formattedData[$key] = [
                'value' => $value,
                'show_label' => false,
                'updated_at' => $currentTime
            ];
        }
        // Convert to JSON format
        $jsonData['report'] = $formattedData;
        $jsonData['data_type'] = $request->input('data_type','json');
        $jsonData['extra_content'] = $request->input('extra_content');

        $statusUpdateData = json_decode($vcd->status_update_data??'[]',true);

        // Save to database (assuming 'patients' table has a JSON column 'free_textbox_data')
        $statusUpdateData['submitted_by'] = auth()->user()->id;
        $statusUpdateData['submitted_at'] = now();

        $vcd->report_data = json_encode($jsonData);
        $vcd->status_update_data = json_encode($statusUpdateData);
        $vcd->status = 'submitted';
        $vcd->save();

        return response()->json([
            'status' => 'success',
            'message' => 'Data saved successfully!',
        ]);

    }

