    public function save_radiology_attachment(Request $request)
    {
        $request->validate([
            'id' => 'required',
            'file' => 'required|file|max:25600',
        ]);
        $order_id = $request->id;
        $vcd = ProcedureLog::where('order_id', $order_id)->first();
        if(!$vcd){
            $vcd = new ProcedureLog;
            $vcd->order_id = $order_id;
        }
        $filePath = null;
        $originalName = '';
        $extension = '';

        if($request->hasFile('file')) {
            $file = $request->file('file');
            $monthFolder = date('Y-m');
            $uploadSubDir = 'assets/files/radiology/' . $monthFolder;
            $uploadPath = public_path($uploadSubDir);

            if (!file_exists($uploadPath)) {
                mkdir($uploadPath, 0777, true);
            }

            $originalName = $file->getClientOriginalName();
            $extension = strtolower($file->getClientOriginalExtension());
            $fileName = uniqid() . '_' . time() . '.' . $extension;
            $file->move($uploadPath, $fileName);

            $filePath = $uploadSubDir . '/' . $fileName;

            // Remove previous attachment file if it existed
            if (!empty($vcd->attachments) && $vcd->attachments !== $filePath && file_exists(public_path($vcd->attachments))) {
                @unlink(public_path($vcd->attachments));
            }
        }

        // Set status to submitted if not already approved
        if ($vcd->status !== 'approved') {
            $vcd->status = 'submitted';
        }
        $vcd->attachments = $filePath;
        $vcd->save();

        if($request->ajax())
        {
            return response()->json([
                'status' => 'success',
                'success' => true,
                'message' => 'Attachment uploaded successfully.',
                'file_path' => $filePath,
                'file_url' => asset($filePath),
                'file_name' => $originalName,
                'extension' => $extension,
                'order_id' => $order_id,
                'order_status' => $vcd->status,
            ]);
        }
        return redirect()->back()->with('success', 'Attachment uploaded successfully');
    }

    public function remove_radiology_attachment(Request $request)
    {
        $request->validate([
            'id' => 'required',
        ]);
        $order_id = $request->id;
        $vcd = ProcedureLog::where('order_id', $order_id)->first();

        if ($vcd && !empty($vcd->attachments)) {
            $oldPath = public_path($vcd->attachments);
            if (file_exists($oldPath)) {
                @unlink($oldPath);
            }
            $vcd->attachments = null;
            $reportData = json_decode($vcd->report_data ?? '{}', true);
            if ($vcd->status !== 'approved' && empty($reportData['report'] ?? [])) {
                $vcd->status = null;
            }
            $vcd->save();
        }

        return response()->json([
            'status' => 'success',
            'success' => true,
            'message' => 'Attachment removed successfully.',
            'order_id' => $order_id,
            'order_status' => $vcd ? ($vcd->status ?? 'pending') : 'pending',
        ]);
    }

    public function approve_invenstigation(Request $request){
        $order_id = $request->oid;
        $context = $request->context;

        $vcd = ProcedureLog::where('order_id', $order_id)->first();
        if(!$vcd){
            $vcd = new ProcedureLog;
            $vcd->order_id = $order_id;
        }
        $vcd->status = 'approved';
        $vcd->save();

        PatientGenBill::where('id', $order_id)->update(['is_abdm_approved' => 1]);

        // Auto-register and link ABDM Diagnostic Report (Radiology) Care Context
        try {
            $order = PatientGenBill::find($order_id);
            if ($order) {
                $bill = PatientBilling::find($order->bill_id);
                $visit = $bill ? Visitlog::find($bill->visit_id) : null;
                $patientId = $visit ? $visit->patient_id : ($bill ? $bill->patient_id : null);
                $hospitalId = $visit ? ($visit->hospital_id ?? 1) : (auth()->check() ? (auth()->user()->org_id ?? 1) : 1);
                $isIpd = $visit && in_array((int)($visit->visit_status ?? 0), [1, 2]);
                $testName = $order->service_name ?? ($order->item_name ?? null);

                if ($patientId && \Illuminate\Support\Facades\Schema::hasTable('patient_care_contexts') && \App\Helpers\LicenseKey::isModuleActiveAndValid('abha', (int)$hospitalId)) {
                    app(\App\Services\ABDM\CareContextManagerService::class)->registerRadiologyContext(
                        visitId: $visit ? $visit->id : null,
                        genBillId: (int)$order->id,
                        patientId: (int)$patientId,
                        hospitalId: (int)$hospitalId,
                        testName: $testName,
                        isIpd: $isIpd,
                        autoLink: true
                    );
                }
            }
        } catch (\Throwable $e) {
            \Illuminate\Support\Facades\Log::channel('abdm')->warning("[approve_invenstigation] Auto-linking radiology care context failed: " . $e->getMessage());
        }

        return response()->json(['status'=> 'success', 'message'=>'Investigation Approved Successfully']);

    }
    public function dis_approve_invenstigation(Request $request){
        $order_id = $request->oid;
        $context = $request->context;

        $vcd = ProcedureLog::where('order_id', $order_id)->first();
        if ($vcd) {
            $vcd->status = 'submitted';
            $vcd->save();
        }

        PatientGenBill::where('id', $order_id)->update(['is_abdm_approved' => 0]);

        return response()->json(['status'=> 'success', 'message'=>'Investigation Disapproved Successfully']);

    }
    public function send_whatsapp_radiology_attachment(Request $request)
    {
        $org_id = auth()->user()->org_id;
        $order_id = $request->id;

        $hospital = Healtcare_org::find($org_id);
        $genBil = PatientGenBill::find($order_id);
        $bill = PatientBilling::find($genBil->bill_id);
        $visit = Visitlog::find($bill->visit_id);
        $patient = Patient::find($visit->patient_id);

        $vcd = ProcedureLog::where('order_id', $order_id)->first();

        if(!$vcd)
        {
            return response()->json(['success' => false,'message' => 'Order not Found']);
        }
        if(!$vcd->attachments)
        {
            return response()->json(['success' => false,'message' => 'No attachment found']);
        }

        if(!$patient->mnvs)
        {
            return response()->json(['success' => false,'message' => 'Need to Verify Mobile Number']);
        }


        $pdfPath = $vcd->attachments;
        // dd($pdfPath);

        Notifier::radiology_investigation([
            'patient_id' => $patient->id,
            'phone_number' => $patient->mobile_no,
            'order_id' => $order_id,
            'params' => [
                'patient_name'=> $patient->prefix.' '.$patient->Fname.' '.$patient->Lname,
                'hospital_name'=>$hospital->name??'',
                'hospital_contact'=>$hospital->contact_no??'',
                'pdf'=>($pdfPath),
                ]
        ]);

        return response()->json(['success' => true,'message' => 'Whastapp Send Request Added Successfully']);

    }
    public function procedure_report_print(Request $request, $id)
    {

        $orderID = $id;
         // Step 1: Retrieve visit_status first
        $order = PatientGenBill::findOrFail($orderID);
        $bill = $order->patientBilling;
        $service = $order->service;
        $visit = $bill->visit;
        $patient = $visit->patient;
        $doctor = $visit->doctor;

        $ipd = Ipd_details::join('visitlog', 'visitlog.id', '=', 'ipd_details.visit_table_id')
            ->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'ipd_details.i_cover')
            ->select(
                'ipd_details.id as ipd_id',
                'health_insurance_agen.insurance_agen as insurance',
            )
            ->where('ipd_details.visit_table_id', $visit->id)
            ->first();


        $vcd = ProcedureLog::where('order_id', $orderID)->first();
        if (!$vcd) {
            $vcd = new ProcedureLog();
            $procedureData = []; // Start with an empty array
        } else {
            $procedureData = json_decode($vcd->report_data??'{}', true) ;
        }
        $header = $request->header??false;

        $flag = $service->flag;
        $sub_flag = $service->sub_flag;

        // Resolve reporting doctor for radiology report
        $printSetting = \DB::table('hospital_print_settings')->where('hospital_id', auth()->user()->org_id ?? $visit->hospital_id ?? 1)->first();
        $radiologySetting = json_decode($printSetting->radiology ?? '{}', true) ?: [];

        $assignedDocLog = ($vcd && $vcd->id) ? \App\Models\ProcedureUserLog::where('procedure_log_id', $vcd->id)->where('user_type', 'doctor')->latest()->first() : null;
        $assignedDoctor = $assignedDocLog ? \App\Models\admin\Doctor_db::find($assignedDocLog->user_id) : null;
        $settingsDoctor = !empty($radiologySetting['doctor_id']) ? \App\Models\admin\Doctor_db::find($radiologySetting['doctor_id']) : null;
        $visitDoctor = $visit->doctor;

        $reportingDoctor = null;
        if ($assignedDoctor && !empty($assignedDoctor->signature)) {
            $reportingDoctor = $assignedDoctor;
        } elseif ($settingsDoctor && !empty($settingsDoctor->signature)) {
            $reportingDoctor = $settingsDoctor;
        } elseif ($visitDoctor && !empty($visitDoctor->signature)) {
            $reportingDoctor = $visitDoctor;
        } elseif ($assignedDoctor) {
            $reportingDoctor = $assignedDoctor;
        } elseif ($settingsDoctor) {
            $reportingDoctor = $settingsDoctor;
        } else {
            $reportingDoctor = $visitDoctor;
        }

        $doctor = $reportingDoctor ?: $visitDoctor;

        $data = [
            'uhid' => $patient->id,
            'ipd_no' => $ipd->ipd_id??'',
            'order' => $order,
            'age' => $patient->age,
            'dob' => $patient->dob,
            'gender' => $patient->sex,
            'prefix' => $patient->prefix,
            'fname' => $patient->Fname,
            'lname' => $patient->Lname,
            'Fathername' => $patient->Fathername,
            'spousename' => $patient->spousename,
            'patient_mobile' => $patient->mobile_no,
            'doctor' => $doctor,
            'doc_name' => ($doctor && $doctor->name) ? $doctor->name : ($radiologySetting['default_doctor_name'] ?? ''),
            'qualification' => ($doctor && $doctor->qualification) ? $doctor->qualification : ($radiologySetting['default_doctor_designation'] ?? ''),
            'sp_name' => ($doctor && $doctor->specialization) ? $doctor->specialization->name : '',
            'visit' => $visit,
            'header' => $header,
            'insurance' => $patient->insurance,
            'category' => $ipd->insurance??'',
            'procedureData' => $procedureData,
            'flag' => $flag,
            'sub_flag' => $sub_flag,
        ];
        extract($data);

        $version = HospitalSetting::where('hospital_id',auth()->user()->org_id)
                    ->where('identifier',$flag.'_report_print_version')
                    ->first()->current_setting??'v1';

                    // dd($flag);

        return  view('admin.pdf.'.$flag.'.'.$flag.'_report_'.$version)->with($data)->render();
    }

