            public function getDrugs(Request $request)
            {
                $type        = $request->type;
                $name        = $request->name;
                $organisamId = $request->organisamId;
                $savedDrugs  = $request->savedDrugs ?? [];
                /* $drugs = Drug::query()
                    ->leftJoin('organism_drug_mapping AS odm', 'drugs.id', '=', 'odm.drug_id')
                    ->where('odm.organism_id', $organisamId)
                    ->select('drugs.*')
                    ->distinct()
                    ->get(); */

                    $drugs = Drug::query()
                    ->where('antibiotic', 1)
                    ->when($type !== 'common', function ($q) use ($type) {
                        $q->where(function($q2) use ($type) {
                            $q2->where('antibiotic_type', $type)
                            ->orWhere('common_drug', 1);
                        });
                    })
                    ->when($type === 'common', function ($q) {
                        $q->where('common_drug', 1);
                    })
                    ->where(function($q) use ($organisamId) {
                        $q->whereExists(function($sub) use ($organisamId) {
                            $sub->from('organism_drug_mapping as odm')
                                ->whereColumn('odm.drug_id', 'drugs.id')
                                ->where('odm.organism_id', $organisamId);
                        })
                        ->orWhere('common_drug', 1);
                    })
                    ->orderBy('drug_name')
                    ->get();

                $orgAndComnDrugs = Drug::query()
                    ->leftJoin('organism_drug_mapping AS odm', 'drugs.id', '=', 'odm.drug_id')
                    ->where(function($q) use ($organisamId, $type) {
                        $q->where('odm.organism_id', $organisamId)
                        ->orWhere('common_drug', 1);
                    })
                    ->when($type, function($q) use ($type) {
                        $q->orWhere('antibiotic_type', $type);
                    })
                    ->select('drugs.*')
                    ->distinct()
                    ->get()
                    ->unique('id')
                    ->values()
                    ->map(fn($d) => ['id' => $d->id, 'drug_name' => $d->drug_name]);

                return response()->json([
                    'html' => view('admin.patient.lab_test.drug_table', [
                        'drugs'       => $drugs,
                        'name'        => $name,
                        'organisamId' => $organisamId,
                        'savedDrugs'  => $savedDrugs,
                        'type'        => $type,
                        //'orgAndComnDrugs' => $orgAndComnDrugs,
                         'orgAndComnDrugs' => [$organisamId => $orgAndComnDrugs],
                    ])->render(),
                    //'orgAndComnDrugs' => $orgAndComnDrugs,
                    'orgAndComnDrugs' => [$organisamId => $orgAndComnDrugs],
                    'organisamId'     => $organisamId
                ]);
            }



        private function isNumericKeyArray($arr)
        {
            foreach (array_keys($arr) as $k) {
                if (!is_numeric($k)) {
                    return false;
                }
            }
            return true;
        }






