    public function services_fetch(Request $request)
    {
        $excludeIds = explode(',', $request->get('exclude_ids', ''));
        $keyword = $request->get('keyword');

        dd($request->all());

        $items = HospitalItems::where('hospital_id', auth()->user()->org_id)
            ->with(['item', 'item.packageUnit'])
            ->whereHas('item', function ($query) use ($keyword, $excludeIds) {
                $query->whereIn('tag', auth()->user()->inventoryUserTypes());
                $query->where('on_hold', 0);

                if (!empty($keyword)) {
                    $query->where('name', 'like', '%' . $keyword . '%');
                }

                if (!empty($excludeIds)) {
                    $query->whereNotIn('id', $excludeIds);
                }
            })
            ->limit(20)
            ->get()->toArray();
        return response()->json($items);
    }


