    public function save_opd_billing(Request $request){
        $user = Auth::user();
        $org_id = $user->org_id;

        $validator = Validator::make($request->all(),[
            'uhid' => 'required',
            'doctor_id' => 'required',
        ]);

        if ($validator->fails()) {
            return response()->json(['status' => false, 'message' => $validator->errors()->first()]);
        }


        $services = $request->input('service', []);

        $serviceIds      = $services['id']        ?? [];
        $serviceCharges  = $services['charges']   ?? [];
        $serviceQty      = $services['quantity']  ?? [];
        $serviceDiscount = $services['discount']  ?? [];
        $serviceAmount   = $services['amount']    ?? [];

        $combinedServices = [];

        for ($i = 0; $i < count($serviceIds); $i++) {
            if (empty($serviceIds[$i])) {
                continue; // skip empty row
            }

            $combinedServices[] = [
                'service_id' => $serviceIds[$i],
                'charges'    => $serviceCharges[$i] ?? 0,
                'qty'        => $serviceQty[$i] ?? 1,
                'discount'   => $serviceDiscount[$i] ?? 0,
                'amount'     => $serviceAmount[$i] ?? 0,
            ];
        }

        $paymentModes = $request->input('pay_mode', []);

            $paymentsFinal = [];

            foreach ($paymentModes as $mode => $amount) {
                $amount = floatval($amount);

                if ($amount > 0) {
                    $paymentsFinal[] = [
                        'mode' => $mode,
                        'amount' => $amount,
                        'trx' => $request->trx[$mode] ?? null,
                    ];
                }
            }

            DB::beginTransaction();

            $patient_id = $request->uhid;
            $doctor_id = $request->doctor_id;

            $pi = Patient::where('id', $request->uhid)->first();
            $i_cover = $pi->i_cover;

            Patient::where('id', $patient_id)->update(['is_registered' => 1]);

            $visit_id = $this->create_visit($patient_id, $doctor_id, 0, $org_id, 0, null, $request->ref_by ?? null);
            if ($request->has('ref_by')) {
                $refVal = (!empty($request->ref_by) && $request->ref_by !== '__new__') ? $request->ref_by : null;
                Visitlog::where('id', $visit_id)->update(['ref_by' => $refVal]);
            }



            $lastBill = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                                    ->select('visitlog.visit_status','patient_billing.*')
                                    ->where('visitlog.visit_status',0)
                                    ->orderBy('patient_billing.id','DESC')
                                    ->first();

            $status = 1;
            $receipt_no = ($lastBill && $lastBill->receipt_no) ? $lastBill->receipt_no + 1 : 1;

            if(isset($request->bill_no)){
                $bill = PatientBilling::find($request->bill_no);
            }else{
                $bill = new PatientBilling;
                $bill->receipt_no = $receipt_no;
                $bill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($visit_id);
            }

            $subtotal = floatval($request->subtotal_input ?? 0);
            $discount_amt = 0;

            if ($request->filled('final_discount')) {

                $disc = floatval($request->final_discount);
                $type = $request->discount_type;   // "percentage" or "flat"

                if ($type === 'percentage') {

                    // % discount
                    $discount_amt = ($disc / 100) * $subtotal;

                } elseif ($type === 'flat') {

                    // flat Γé╣ discount
                    $discount_amt = $disc;
                }
            }



            // prevent discount > subtotal
            $discount_amt = min($discount_amt, $subtotal);

            $bill->i_cover = $i_cover;
            $bill->visit_id = $visit_id;
            $bill->discount = $discount_amt;
            $bill->status = $status;
            $bill->claim_id = $request->input('claim_id');
            if($request->discount != null){
                $bill->discount_type = $request->discount_type;

                // if($request->discount_type){
                //     $discount_name = BillDiscount::find($request->discount_select)->name ??'';
                //     $bill->discount_name = $discount_name;
                // }

               // $bill->discount_auth_by = $request->discount_auth_by;
            }
            $bill->created_by = auth()->user()->id;

              if ($request->hasFile('discount_attachment')) {
                    $file = $request->file('discount_attachment');
                    \App\Services\SecureFileService::validate($file, ['pdf', 'jpg', 'jpeg', 'png', 'webp', 'doc', 'docx'], 5120);

                    $cleanOriginalName = preg_replace('/[^a-zA-Z0-9_\.-]/', '_', $file->getClientOriginalName());
                    $filename = time() . '_' . $cleanOriginalName;

                    $destination = public_path('assets/files/attachments');
                    if (!file_exists($destination)) {
                        @mkdir($destination, 0755, true);
                    }
                    $file->move($destination, $filename);

                    $bill->attachment = $filename;
                    $bill->save();
                }

            $bill->remarks = $request->remarks ?? '';
            $bill->save();

            $b_id = $bill->id;


        $bill->discount = $request->final_discount ?? 0;

        if ($request->final_discount) {
            $bill->discount_type = $request->discount_type ? 'percentage' : 'cash';
        }


        foreach ($combinedServices as $item) {

            $service = HospitalSer::find($item['service_id']);

            if ($service && $service->flag == "lab_package") {

                $packageServiceCharge = HospitalServiceCharges::where('hospital_id',$org_id)
                    ->where('insurance',$i_cover)
                    ->where('service',$service->id)
                    ->value('charges') ?? 0;

                $tests = InvestigationGroupTest::where('group_id', $item['service_id'])
                                                ->orderBy('sequence_no')
                                                ->get();

                $subTotal = 0;

                foreach ($tests as $t) {
                    $charge = HospitalServiceCharges::where('hospital_id',$org_id)
                                ->where('insurance',$i_cover)
                                ->where('service',$t->test_id)
                                ->value('charges') ?? 0;

                    $subTotal += $charge;

                    PatientGenBill::create([
                        'bill_id' => $b_id,
                        'service_id' => $t->test_id,
                        'charges' => $charge,
                        'qty' => 1,
                        'doctor_id' => $doctor_id,
                        'i_cover' => $i_cover,
                        'created_by' => auth()->id(),
                    ]);
                }

                // Adjust discount for package
                $bill = PatientBilling::find($b_id);
                $bill->discount += ($subTotal - $packageServiceCharge);
                $bill->save();

            } else {

                // dd($item);

                $gbill = new PatientGenBill;
                $gbill->bill_id = $b_id;
                $gbill->service_id = $item['service_id'];
                $gbill->charges = $item['charges'];
                $gbill->qty = $item['qty'];
                $gbill->discount = $item['discount'];
                $gbill->doctor_id = $doctor_id;
                $gbill->i_cover = $i_cover;
                $gbill->created_by = auth()->id();
                $gbill->save();

            }
        }


        foreach ($paymentsFinal as $pay) {

            $billPayment = new BillingPaymentType;
            $billPayment->bill_id = $b_id;
            $billPayment->payment_mode = $pay['mode'];
            $billPayment->amount = $pay['amount'];
            $billPayment->transaction_id = $pay['trx'];
            $billPayment->created_by = auth()->id();
            $billPayment->save();
        }

        DB::commit();


        $request->merge([
            'patient_id' => $patient_id
        ]);

    //    dd($b_id);
        $pdfPath = $this->generate_opd_bill($request,$b_id);

        return response()->json([
                'success' => true,
                'message' =>"Bill Saved Successfully",
                'id' =>$b_id,
                'print_url'=> $pdfPath
            ], 200);

    }


