    public function store_video_consent(Request $request)
    {
        $request->validate([
            'recording' => ['required', 'file', 'max:512000'], // ~500MB
        ]);

        // $file = $request->file('recording');

        // // you can change extension if you want
        // $filename = 'recording_' . now()->format('Ymd_His') . '.webm';

        // $path = $file->storeAs('recordings', $filename, 'public');

        $file = $request->file('recording');

        $filename = 'recording_' . now()->format('Ymd_His') . '.webm';

        $destination = public_path('assets/files/recordings/');

        $file->move($destination, $filename);

        return response()->json([
            'success' => true,
            'path' => 'assets/files/recordings/'.$filename,
