    public function autoUpload(Request $request)
    {
        // Γ£à Validation
        $validator = Validator::make($request->all(), [
            'patient_id' => 'required|string|max:50',
            'file' => 'required|file|mimes:jpg,jpeg,png,pdf|max:10240', // 10MB
        ]);

        if ($validator->fails()) {
            return response()->json([
                'status' => false,
                'errors' => $validator->errors()
            ], 422);
        }

        // Γ£à Sanitize Patient ID
        $patientId = preg_replace('/[^A-Za-z0-9_-]/', '', $request->patient_id);

        // Γ£à Dynamic Folder
        $folderPath = "patients/{$patientId}";

        // Γ£à Unique File Name
        $file = $request->file('file');
        $filename = time() . '_' . $file->getClientOriginalName();

        // Γ£à Store File (Safe Location)
        $storedPath = $file->storeAs($folderPath, $filename, 'local');

        return response()->json([
            'status' => true,
            'message' => 'File uploaded successfully',
            'patient_id' => $patientId,
            'path' => $storedPath
        ]);
    }


    public function upload_by_qr(Request $request)
    {
        // Γ£à 1. Validate File
        $validator = Validator::make($request->all(), [
            'file' => 'required|file|mimes:jpg,jpeg,png,pdf|max:10240'
        ]);

        if ($validator->fails()) {
            return response()->json([
                'status' => false,
                'errors' => $validator->errors()
            ], 422);
        }

        // Γ£à 2. Move to TEMP
        $file = $request->file('file');
        $tempName = time() . '_' . preg_replace('/\s+/', '_', $file->getClientOriginalName());
        $tempPath = sys_get_temp_dir() . DIRECTORY_SEPARATOR . $tempName;

        $file->move(sys_get_temp_dir(), $tempName);

        if (!file_exists($tempPath)) {
            return response()->json([
                'status' => false,
                'message' => 'Temporary file not created'
            ], 500);
        }

        // Γ£à 3. Detect Extension
        $extension = strtolower(pathinfo($tempPath, PATHINFO_EXTENSION));
        $qrImagePath = $tempPath;

        // Γ£à 4. If PDF ΓåÆ Convert to IMAGE
        if ($extension === 'pdf') {
            $convertedImage = sys_get_temp_dir() . DIRECTORY_SEPARATOR . time() . '_pdf.png';

            $cmdPdf = 'magick -density 300 "' . $tempPath . '"[0] -quality 100 "' . $convertedImage . '"';
            exec($cmdPdf, $outPdf, $pdfStatus);

            if (!file_exists($convertedImage)) {
                @unlink($tempPath);
                return response()->json([
                    'status' => false,
                    'message' => 'PDF to image conversion failed',
                    'debug' => $outPdf
                ], 500);
            }

            $qrImagePath = $convertedImage;
        }

        // Γ£à 5. Try to enhance image (OPTIONAL, NOT MANDATORY)
        $enhancedImage = sys_get_temp_dir() . DIRECTORY_SEPARATOR . time() . '_enhanced.png';

        $cmdEnhance = 'magick "' . $qrImagePath . '" -colorspace Gray -contrast -contrast -sharpen 0x1 "' . $enhancedImage . '"';
        exec($cmdEnhance, $outEnhance, $enhanceStatus);

        // Γ£à 6. Decide what image to scan
        $scanImage = file_exists($enhancedImage) ? $enhancedImage : $qrImagePath;

        // Γ£à 7. Read QR
        try {
          //  dd($scanImage);
            $qrReader = new \Zxing\QrReader($scanImage);
            $patientId = trim($qrReader->text());
            // dd($patientId);
        } catch (\Throwable $e) {
            $patientId = null;
        }

        if (!$patientId) {
            @unlink($tempPath);
            if ($extension === 'pdf') @unlink($qrImagePath);
            if (file_exists($enhancedImage)) @unlink($enhancedImage);

            return response()->json([
                'status' => false,
                'message' => 'QR not detected in uploaded file'
            ], 400);
        }

        // Γ£à 8. Sanitize Patient ID
        $patientId = preg_replace('/[^A-Za-z0-9_-]/', '', $patientId);

        // Γ£à 9. PUBLIC Destination Folder
        $publicBasePath = public_path('assets/files/scanned_documents/');
        $patientFolder = $publicBasePath . $patientId . DIRECTORY_SEPARATOR;

        if (!is_dir($patientFolder)) {
            mkdir($patientFolder, 0777, true);
        }

        // Γ£à 10. Move ORIGINAL FILE to patient folder
        $finalFileName = time() . '_' . $file->getClientOriginalName();
        $finalPath = $patientFolder . $finalFileName;

        rename($tempPath, $finalPath);

            $doc = new ScannedDoc;
            $doc->patient_id = $patientId;
            $doc->tag = 'scanned';
            $doc->path = "assets/files/scanned_documents/{$patientId}/{$finalFileName}";
            $doc->remarks = 'Uploaded via QR Auto-Mapping';
            $doc->save();

        // Γ£à 11. Cleanup
        if ($extension === 'pdf' && file_exists($qrImagePath)) @unlink($qrImagePath);
        if (file_exists($enhancedImage)) @unlink($enhancedImage);

        return response()->json([
            'status' => 'success',
            'message' => 'File uploaded & auto-mapped by QR',
            'patient_id' => $patientId,
            'public_path' => "assets/files/scanned_documents/{$patientId}/{$finalFileName}"
        ]);
    }


