    public function camera_upload_consent(Request $request)
    {
       $request->validate([
            'image'     => 'required',
            'visit_id'  => 'required|integer',
            // 'file_type' => 'required|string',
        ]);

        $visit = Visitlog::find($request->visit_id);
        if (!$visit) {
            return response()->json([
                'status' => false,
                'message' => 'Invalid Visit ID'
            ], 400);
        }

        $image = $request->image;

        // Γ£à Decode Base64
        $image = preg_replace('/^data:image\/\w+;base64,/', '', $image);
        $image = str_replace(' ', '+', $image);
        $imageData = base64_decode($image);

        /* Γ£à YOUR REQUIRED PATH */
        $publicBasePath = 'assets/files/scanned_documents/';
        $patientId = $request->patient_id;

        $patientFolder = $publicBasePath . $patientId . DIRECTORY_SEPARATOR;

        if (!is_dir($patientFolder)) {
            mkdir($patientFolder, 0777, true);
        }

        /* Γ£à SAFE UNIQUE FILE NAME */
        $fileName = 'camera_' . time() . '_' . rand(1000,9999) . '.png';
        $fullPath = $patientFolder . $fileName;

        file_put_contents($fullPath, $imageData);



        $doc = new ScannedDoc;
        $doc->patient_id = $visit->patient_id;
        $doc->tag = $request->file_type;
        $doc->path = $fullPath;
        $doc->remarks = $request->remarks ?? '';
        $doc->save();

        return response()->json([
            'status' => true,
            'path'   => 'assets/files/scanned_documents/' . $patientId . '/' . $fileName
        ]);
    }


