    public function m_patient_register_save(Request $request)
    {
        $validator = Validator::make($request->all(),[
            'name' => 'required',
            'prefix' => 'required',
            'mobile_no' => 'required|digits:10',
            'age' => 'required',
            'gender' => 'required',
            'email_id' => 'nullable|email',
        ]);

        if ($validator->fails()) {
            return response()->json(['status' => 'error', 'message' => $validator->errors()->first()]);
        }

        DB::beginTransaction();
        $id = HealthInsurance::whereRaw('LOWER(insurance_agen) = ?', ['cash'])->value('id');

        $currentDate = Carbon::now()->toDateString();
        $currentTime = Carbon::now()->toTimeString();


        $patient = new Patient;
        $patient->prefix = $request->prefix;
        $patient->Fname = $request->name;
        $patient->Lname = '';
        $patient->mobile_no = $request->mobile_no;
        $patient->country_code = $request->country_code;
        $patient->sex = $request->gender;
        $patient->age = $request->age;
        if($request->dob){
            $patient->dob = date("Y-m-d", strtotime($request->dob));
        }else{
            $age = $request->age;
            $patient->dob = date('Y-m-d', strtotime('-'.$age.' years'));
            $patient->is_dob_calc = 1;
        }
        $patient->date = $currentDate;
        $patient->time = $currentTime;
        $patient->i_cover = $id;
        $patient->email_id = $request->email_id;
        $patient->hospital_id = auth()->user()->org_id;
        $patient->created_by = auth()->user()->id;
        $patient->save();

        DB::commit();

        return response()->json(['status' => 'success', 'message' =>"Patient Registered Successfully", 'id' => $patient->id]);

    }

    public function m_update_profile(Request $req){
        $user = Auth::user();
        $org_id = $user->org_id;

            $validate =  Validator::make($req->all(),[
                'prefix'=> 'required',
                'name' => 'required',
                'gender' => 'required',
                'age' => 'required',
                'mobile_no' => 'required|digits:10',
                'email_id' => 'nullable|email',
            ]);

            if($validate->fails()){
                    return response()->json([
                        'status' => 'error',
                        'errors' => $validate->errors()
                    ]);
            }

        if(auth()->user()->can('module-permission',['patient','can_update']))
          {
            $patient = Patient::findOrFail($req->uhid);

            $addMsg = '';

            if($patient->mobile_no != $req->mobile_no){
                $patient->mnvs = 0;
                $patient->mnvs_otp = 0;
                $patient->mnvs_otp_expiry = null;
                $patient->save();

                $addMsg = 'Mobile Number Updated.';
            }


            $patient->prefix = $req->prefix;
            $patient->Fname = $req->name;
            $patient->age = $req->age;
            $patient->sex = $req->gender;
            $patient->mobile_no = $req->mobile_no;
            $patient->country_code = $req->country_code;
            $patient->email_id = $req->email_id;
            $patient->save();
            return response()->json(['status'=> 'success', 'msg'=>'Record updated successfully.' ]);
        }else{
            return response()->json(['status'=> 'error', 'msg'=>'You do not have permission to update patient details.']);
        }

        return response()->json(['status'=> 'error', 'msg'=>'Something went wrong.']);

    }


    public function m_patient_create_visit(Request $request)
    {
        $validator = Validator::make($request->all(),[
            'patient_id' => 'required|integer',
            'doctor' => 'required|integer',
        ]);

        if ($validator->fails()) {
            return response()->json(['status' => 'error', 'message' => $validator->errors()->first()]);
        }

        $org_id = auth()->user()->org_id;
        $patient_id = $request->patient_id;
        $doctor_id = $request->doctor;

         DB::beginTransaction();

        $visit_id = $this->create_visit($patient_id, $doctor_id, 0, $org_id, 0, null, $request->ref_by ?? null);
        if ($request->has('ref_by')) {
            $refVal = (!empty($request->ref_by) && $request->ref_by !== '__new__') ? $request->ref_by : null;
            Visitlog::where('id', $visit_id)->update(['ref_by' => $refVal]);
        }


            $regService = \App\Models\admin\HospitalSer::where('flag','registration_charge')->first();
            $consultService = \App\Models\admin\HospitalSer::where('flag','consultation_charge')->first();
            $patient = Patient::find($patient_id);

            $lastBill = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                                ->select('visitlog.visit_status','patient_billing.*')
                                ->where('visitlog.visit_status',0)
                                ->orderBy('patient_billing.id','DESC')
                                ->first();
            $receipt_no = ($lastBill && $lastBill->receipt_no) ? $lastBill->receipt_no + 1 : 1;

            $total_charges = 0;


            $bill = new PatientBilling;
            $bill->visit_id = $visit_id;
            $bill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($bill->visit_id);
            $bill->i_cover = $patient->i_cover;
            $bill->status = 1;
            $bill->receipt_no = $receipt_no;
            $bill->discount = 0;
            $bill->created_by = auth()->user()->id;
            $bill->save();

            if($patient->is_registered != 1)
            {
                // insert registration fee
                $genBillReg = new PatientGenBill;
                $genBillReg->bill_id = $bill->id;
                $genBillReg->service_id = $regService->id;
                $genBillReg->charges =  0;
                $genBillReg->qty = 1;
                $genBillReg->discount =  0;
                $genBillReg->doctor_id = $doctor_id;
                $genBillReg->i_cover = $patient->i_cover;
                $genBillReg->created_by = auth()->user()->id;
                $genBillReg->save();

                $patient->is_registered = 1;
                $patient->save();
            }

            // insert consultation fee
            $genBillConsult = new PatientGenBill;
            $genBillConsult->bill_id = $bill->id;
            $genBillConsult->service_id = $consultService->id;
            $genBillConsult->charges =  0;
            $genBillConsult->qty = 1;
            $genBillConsult->discount = 0;
            $genBillConsult->doctor_id = $doctor_id;
            $genBillConsult->i_cover = $patient->i_cover;
            $genBillConsult->created_by = auth()->user()->id;
            $genBillConsult->save();

        DB::commit();

        return response()->json(['status' => 'success', 'message' =>"Visit Created Successfully", 'visit_id' => $visit_id]);

    }

    public function camera_viewer(Request $request)
