    public function m_surgery_save(Request $request, $id)
    {
        $user = Auth::user();
        $org_id = $user->org_id;

        $validator = Validator::make($request->all(),[
            'ot' => 'required',
            'date' => 'required',
            'time' => 'required',
            'surgery' => 'required',
            'anesthesia_type' => 'required',
            'primary_surgeon' => 'required',
            'implant_file' => 'nullable|file|mimes:pdf,jpg,jpeg,png|max:5120',
        ]);

        if ($validator->fails()) {
            return response()->json(['status' => 'error', 'message' => $validator->errors()->first()]);
        }

        try {
            DB::beginTransaction();

            $data = $request->all();
            $visit = Visitlog::find($id);
            $patient = Patient::find($visit->patient_id);


            $otlog = new OtLog;
            $otlog->visit_id = $id;
            $otlog->ot = $request->ot;
