    public function save_patient_checklist(Request $request, $id)
    {
        $validate = Validator::make($request->all(), [
            'checklist'        => 'nullable|array',
            'checklist.*.file' => 'nullable|file|mimes:pdf,jpg,jpeg,png,doc,docx|max:5120',
        ]);

        if ($validate->fails()) {
            return response()->json([
                'status' => 'error',
                'errors' => $validate->errors()
            ], 422);
        }

        $ot = OtLog::findOrFail($id);

        $visit = Visitlog::find($ot->visit_id);

        if ($visit) {
            $visit->fud = $request->fud;
            $visit->save();
        }

        $checklist = $request->input('checklist', []);

        foreach ($checklist as $key => &$item) {

            // Checkbox normalization
            $item['is_active'] = isset($item['is_active']) ? 1 : 0;

            // File upload
            if ($request->hasFile("checklist.$key.file")) {

                $file = $request->file("checklist.$key.file");

                // Extra safety check
                if ($file->isValid()) {

                    $uploadDir = public_path('assets/files/clinical');

                    if (!file_exists($uploadDir)) {
                        mkdir($uploadDir, 0755, true);
                    }

                    $fileName = uniqid() . '_' . time() . '.' . $file->getClientOriginalExtension();

                    $file->move($uploadDir, $fileName);

                    // Save relative path
                    $item['file'] = 'assets/files/clinical/' . $fileName;
                }
            } else {
                $item['file'] = null;
            }
        }

        unset($item);

        $model = PreOpChecklist::updateOrCreate(
            [
                'ot_case_id' => $id,
                'context'    => $request->context,
            ],
            [
                'checklist' => $checklist,
                'other'     => $request->other,
            ]
        );

        return response()->json([
            'status'  => 'success',
            'message' => 'Updated Successfully'
        ]);
    }

