    public function send_whatsapp_alert(Request $request){
        $org_id = Auth()->user()->org_id;
        $ot_id = $request->vid;

         $otlog = OtLog::where('ot_log.id',$ot_id)
                        ->first();

        $visit = Visitlog::join('pi', 'pi.id', '=', 'visitlog.patient_id')
                            ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                            ->join('doctor_specialities','doctor_specialities.id','=','doctor_db.key_spec')
                            ->select('visitlog.id', 'pi.prefix','pi.Fname','pi.age','pi.sex',
                                    'pi.Lname', 'doctor_db.name as doctor_name','pi.mobile_no',
                                    'doctor_specialities.name as sp_name',
                                    'doctor_db.contact_no as doc_contact_no',
                                    'doctor_db.id as doctor_id','pi.id as uhid')
                            ->where('visitlog.id', $otlog->visit_id)
                            ->first();

        $patient = Patient::find($visit->uhid);

        $whatsapp_without_verification = \App\Helpers\HospitalHelper::isSettingEnabled($org_id,'whatsapp_without_verification');

        if(!$whatsapp_without_verification){
            if(!$patient->mnvs)
            {
                return response()->json(['status' => 'error','message' => 'Need to Verify Mobile Number']);
            }
        }

        $hospital = Healtcare_org::where('id', $org_id)->first();

        Notifier::appointment_confirmation([
            'patient_id' => 0,
            'phone_number' => $patient->mobile,
            'appointment_id' => $otlog->id,
            'params' => [
                'patient_name'=> $patient->name,
                'dr_name'=> $visit->doctor_name??"",
                'hospital_name'=>$hospital->name??'',
                'hospital_contact'=>$hospital->contact_no??'',
                'date'=>date('D, d M Y', strtotime($otlog->surgery_date)),
                'slot'=>date('g:i A', strtotime($otlog->surgery_time)) . ' - ' . date('g:i A', strtotime($otlog->surgery_time)),
                'link' => $hospital->external_app_link?:url('book-appointment/select-doctor/'.encryptID(auth()->user()->org_id)),
                ]
        ]);
        Notifier::appointment_confirmation_to_doctor([
            'patient_id' => 0,
            'phone_number' => $visit->doc_contact_no,
            'appointment_id' => $otlog->id,
            'params' => [
                'dr_name'=> $visit->doctor_name??"",
                'patient_name'=> $patient->name,
                'hospital_name'=>$hospital->name??'',
                'hospital_contact'=>$hospital->contact_no??'',
                'date'=>date('D, d M Y', strtotime($otlog->surgery_date)),
                'slot'=>date('g:i A', strtotime($otlog->surgery_time)) . ' - ' . date('g:i A', strtotime($otlog->surgery_time)),
                'link' => url('doctor-panel/dashboard'),
            ]
        ]);



        return response()->json(['status' => 'success', 'message'=>'Notification Sended Successfully']);

        // if($isEnabled){
        //     return response()->json(['status' => 'success', 'message'=>'Notification Sended Successfully']);
        // }else{
        //     return response()->json(['status' => 'error', 'message'=>'Setting Not Enabled']);
        // }
    }

    public function get_document_type(Request $request){
        $types = [
            'Blood investigation',
            'BMD',
            'Dexa Scan',
            'X-ray-Pre-Op',
            'Post-X-ray',
            'MRI',
            'CT SCAN',
            'Scanogram',
