    public function saveSurgery(Request $request)
    {
        $hospitalId = Auth::user()->org_id;

        $validator = Validator::make($request->all(), [
            'surgery_name' => 'required|string|unique:hospital_services,service',
            /*'surgery_type' => 'required|string',
             'cgst'         => 'nullable|numeric',
            'sgst'         => 'nullable|numeric', */
        ]);

        if ($validator->fails()) {
            return response()->json([
                'status'  => 'error',
                'message' => $validator->errors()->first()
            ]);
        }
        DB::beginTransaction();
        try {

            $service = new Service();
            $service->service = $request->surgery_name;
            $service->flag    = "package";
            $service->active = 1;
            $service->save();

            $hospitalService = new HospitalService();
            $hospitalService->service  = $service->id;
            $hospitalService->hospital_id = $hospitalId;
            $hospitalService->service_cgst = 0;
            $hospitalService->service_sgst = 0;
            $hospitalService->active = 1;
            $hospitalService->save();
            DB::commit();

            return response()->json([
                'status'  => 'success',
                'message' => 'Surgery saved successfully'
            ]);
        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json([
                'status'  => 'error',
                'message' => 'Something went wrong while saving surgery'
            ]);
        }
    }

        public function getServiceDetails(Request $request)
            {
                $name = $request->name;
                $hospitalId = Auth::user()->org_id;

                $query = Service::leftJoin(
                    'hospital_services_index as hsi',
                    function ($join) use ($hospitalId) {
                        $join->on('hsi.service', '=', 'hospital_services.id')
                            ->where('hsi.hospital_id', '=', $hospitalId);
                    }
                )
                ->where('hospital_services.flag', 'package');

                if (!empty($name)) {
                    $query->where('hospital_services.service', 'LIKE', "%{$name}%");
                }

                $services = $query->select(
                    'hospital_services.id',
                    'hospital_services.service',
                    'hospital_services.flag',
                    DB::raw('COALESCE(hsi.service_cgst, 0) as service_cgst'),
                    DB::raw('COALESCE(hsi.service_sgst, 0) as service_sgst'),
                    DB::raw('hsi.active as active')
                )
                ->orderBy('hospital_services.service')
                ->get();

                return response()->json([
                    'status' => 'success',
                    'data' => $services
                ]);
            }



    public function toggleActive(Request $request)
    {
        $id = $request->id;
        $active = $request->active; // 1 = active, 0 = inactive
        $surgery = HospitalService::where('service',$id)->first();
        if(!$surgery){
            return response()->json(['status' => 'error', 'message' => 'Surgery not found']);
        }
        $surgery->active = $active; // assuming you have 'active' column in DB
        $surgery->save();
        return response()->json([
            'status' => 'success',
            'message' => 'Surgery status updated successfully',
            'active' => $active
        ]);
    }

    public function mEditService($id)
    {
       $surgery = DB::table('hospital_services')
        ->leftJoin(
            'hospital_services_index',
            'hospital_services.id',
            '=',
            'hospital_services_index.service'
        )
        ->where('hospital_services.id', $id)
        ->select(
            'hospital_services.id',
            'hospital_services.service',
            'hospital_services.flag',
            'hospital_services_index.service_cgst',
            'hospital_services_index.service_sgst'
        )
        ->first();

        if (!$surgery) {
            return response()->json([
                'status' => 'error',
                'message' => 'Surgery not found'
            ]);
        }

        return response()->json([
            'status' => 'success',
            'data' => $surgery
        ]);
    }

    public function mUpdateService(Request $request)
    {
         $request->validate([
        'id' => 'required|exists:hospital_services,id',
        'surgery_name' => 'required|string',
       /*  'surgery_type' => 'required|string',
        'cgst' => 'nullable|numeric',
        'sgst' => 'nullable|numeric', */
        ]);

        DB::beginTransaction();

        try {
            // Update service table
            DB::table('hospital_services')
                ->where('id', $request->id)
                ->update([
                    'service' => $request->surgery_name,
                    /* 'flag' => $request->surgery_type, */
                    'flag' => "package",
                ]);

            // Update or Insert CGST / SGST
            DB::table('hospital_services_index')->updateOrInsert(
                ['service' => $request->id],
                [
                   /*  'service_cgst' => $request->cgst,
                    'service_sgst' => $request->sgst, */
                    'service_cgst' => 0,
                    'service_sgst' => 0,
                ]
            );

            DB::commit();

            return response()->json([
                'status' => 'success',
                'message' => 'Surgery updated successfully'
            ]);

        } catch (\Exception $e) {
            DB::rollBack();

            return response()->json([
                'status' => 'error',
                'message' => 'Update failed'
            ], 500);
        }
    }



