    public function save_patient_consent(Request $request){

       $checklistFiles = $request->file('checklist', []);

        foreach ($checklistFiles as $key => $item) {

            if (!isset($item['file']) || !$item['file']->isValid()) {
                continue;
            }

            $file = $item['file'];

            $uploadDir = public_path('assets/files/clinical');
            if (!file_exists($uploadDir)) {
                mkdir($uploadDir, 0777, true);
            }

            $fileName = uniqid() . '_' . time() . '.' . $file->getClientOriginalExtension();
            $file->move($uploadDir, $fileName);

            OTConsentUpload::updateOrCreate(
                ['ot_case_id' => $request->id, 'type' => 'consent'],
                ['path' => 'assets/files/clinical/' . $fileName, 'is_active'=>1],
            );
        }

        return response()->json(['status'=>'success','message'=>'uploaded success']);

    }

