    public function delete_regi_lead(Request $request)
        {
            $lead = RegisterLead::find($request->id);

            if (!$lead) {
                return response()->json([
                    'status' => false,
                    'message' => 'Lead not found'
                ]);
            }

            $lead->delete();

            return response()->json([
                'status' => true,
                'message' => 'Lead deleted successfully'
            ]);
        }


        public function start_opd_billing_v5(Request $request){
        $user = Auth::user();
        $org_id = $user->org_id;

        Validator::make($request->all(),[
            'uhid' => 'required',
            'doctor' => 'required',
        ]);

        $patient_id = $request->uhid;
        $visit_id = $request->v_id;

        $others = json_decode($user->others??'{}',true);

        $restrict_service_flag = $others['restrict_service_flag']??[];

        $patient = Patient::where('id',$patient_id)->first();

        $services=HospitalService::leftJoin('hospital_services','hospital_services.id','=','hospital_services_index.service')
                                    ->leftJoin('hospital_service_charges','hospital_service_charges.service','=','hospital_services_index.service')
                                    ->where('hospital_services_index.hospital_id',$org_id)
                                    ->where('hospital_services_index.active',1)
                                    ->where('hospital_service_charges.insurance',$patient->i_cover)
                                    ->where('hospital_service_charges.hospital_id',$org_id)
                                    ->select('hospital_services.service',
                                                'hospital_services.spec_id',
                                                'hospital_services.id',
                                                'hospital_services.short_code',
                                                'hospital_services.flag',
                                                'hospital_services_index.is_outsource'
                                                )
                                    ->when($restrict_service_flag, function ($q) use ($restrict_service_flag) {
                                        return $q->whereIn('hospital_services.flag', $restrict_service_flag);
                                    })
                                    ->groupBy('hospital_service_charges.service')
                                    ->get();
        $discAuthUsers = User::where('active',1)->get()->toArray();

        $discounts = BillDiscount::where('active',1)->get();


        // chekc is_registered patient or new patient
        $is_registered = $patient->is_registered;
        $data = [];

        $data['is_registered'] = $is_registered;
        $data['add_consultation'] = $request->add_consultation;


        if($is_registered == 0){
            $regch = HospitalRegistrationFee::where('hospital_id',$org_id)->first();
            $regch = $regch->registration_fee??0;

            $ser = HospitalSer::where('flag','registration_charge')->first();
            $data['reg_service'] = $ser;
            $data['reg_charges'] = $regch;
        }

        // add consultant fee to bill
        if($request->add_consultation){
        $ser = HospitalSer::where('flag','consultation_charge')->first();
        $data['service'] = $ser;
        $data['opd_charges'] = $request->charges;
        }

        $data['insurance'] = $patient->i_cover;
        $data['patient_id'] = $patient->id;

        $type = "opd_billing";



        $bill_layout = view('admin.patient.billing.opd_billing_layout_v5',compact('services','discAuthUsers','discounts','data','type'))->render();

        return response()->json(['status'=>'success','bill_layout'=>$bill_layout, 'data'=>$data]);

    }



     public function gen_opd_bill_v5(Request $request)
    {

        $user = Auth::user();
        $org_id = $user->org_id;

         $request->validate([
            'patient_id' => 'required',
            'doctor_id' =>'required',
            'add_visit' => 'required',
           ]);

        try{
            $patientId = $request->patient_id;
            $rawId = preg_replace('/[^0-9]/', '', (string) $patientId);
            $pi = Patient::where('hospital_id', $org_id)
                ->where(function ($q) use ($patientId, $rawId) {
                    $q->where('id', $patientId)
                      ->orWhere('uhid', $patientId);
                    if (!empty($rawId)) {
                        $q->orWhere('id', $rawId)
                          ->orWhere('uhid', $rawId);
                    }
                })->first();
            if(!$pi){
                    return response()->json(['status'=>'error','message'=>'Patient not found in this hospital. Please register patient first.']);
            }

            $patient_id = $pi->id;
            $doctor_id = $request->doctor_id;
            $charges = $request->doctor_charges??0;
            $add_visit = $request->add_visit;

            $visit_id = $this->create_visit($patient_id, $doctor_id, $charges, $org_id, $add_visit, null, $request->ref_by ?? null);

            if ($visit_id instanceof \Illuminate\Http\JsonResponse) {
                return $visit_id;
            }

            $request->visit_id = $visit_id;

            if ($request->has('ref_by')) {
                $refVal = (!empty($request->ref_by) && $request->ref_by !== '__new__') ? $request->ref_by : null;
                Visitlog::where('id', $visit_id)->update(['ref_by' => $refVal]);
            }

            if($request->action == 'save_as_draft'){
                $status = 0;
                $bill_no = $request->bill_no ?? null;

                if(isset($bill_no) && !empty($bill_no)){

                    $res = $this->save_edited_bill($request, $status);

                    $pdf_url = $this->generate_opd_bill($request, $bill_no);
                    return response()->json(['message' =>"Draft Bill Updated Successfully", 'pdf_url' => $pdf_url, 'bill_id' => $bill_no, 'success' => true], 200);
                }

            }else
            if(($request->action == 'edit_bill') || ($request->action2 == 'gen_bill_from_draft')){
                $status = 1;

                $res = $this->save_edited_bill($request, $status);
                if ($res instanceof \Illuminate\Http\JsonResponse) {
                    return $res;
                }

                $pdf_url = $this->generate_opd_bill($request,$request->bill_no);

                return response()->json(['message' =>"Bill Updated Successfully", 'pdf_url' => $pdf_url,'bill_id' =>$request->bill_no, 'success' => true], 200);
            }else
            {
                $status = 1;
            }

                //  dd('create bill');
                // create new visit and generate bill
                DB::beginTransaction();


                $visitPi = null;
                if (!empty($visit_id) && is_numeric($visit_id)) {
                    $visitPi = Visitlog::join('pi', 'pi.id', '=', 'visitlog.patient_id')
                                    ->select('i_cover')
                                    ->where('visitlog.id', '=', $visit_id)
                                    ->first();
                }
                $i_cover = $visitPi ? $visitPi->i_cover : ($pi->i_cover ?? 0);

                Patient::where('id', $patient_id)->update(['is_registered' => 1]);

                $lastBill = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                                        ->select('visitlog.visit_status','patient_billing.*')
                                        ->where('visitlog.visit_status',0)
                                        ->orderBy('patient_billing.id','DESC')
                                        ->first();
                $receipt_no = ($lastBill && $lastBill->receipt_no) ? $lastBill->receipt_no + 1 : 1;

                if(isset($request->bill_no)){
                    $bill = PatientBilling::find($request->bill_no);
                }else{
                    $bill = new PatientBilling;
                    $bill->receipt_no = $receipt_no;
                    $bill->bill_number = \App\Helpers\HospitalHelper::generateBillNumber($visit_id);
                }

                $bill->i_cover = $i_cover;
                $bill->visit_id = $visit_id;
                $bill->discount = $request->input('discount');
                $bill->status = $status;
                $bill->claim_id = $request->input('claim_id');

                $bill->discount = $request->discount??0;
                if($request->discount != null){
                    $bill->discount_type = ($request->discount_type) ? 'percentage' : 'cash';

                    if($request->discount_type){
                        $discount_name = BillDiscount::find($request->discount_select)->name ??'';
                        $bill->discount_name = $discount_name;
                    }

                    $bill->discount_auth_by = $request->discount_auth_by;
                }
                $bill->created_by = auth()->user()->id;

                if ($request->hasFile('discount_attachment')) {
                        $file = $request->file('discount_attachment');
                        \App\Services\SecureFileService::validate($file, ['pdf', 'jpg', 'jpeg', 'png', 'webp', 'doc', 'docx'], 5120);

                        $cleanOriginalName = preg_replace('/[^a-zA-Z0-9_\.-]/', '_', $file->getClientOriginalName());
                        $filename = time() . '_' . $cleanOriginalName;

                        $destination = public_path('assets/files/attachments');
                        if (!file_exists($destination)) {
                            @mkdir($destination, 0755, true);
                        }
                        $file->move($destination, $filename);

                        $bill->attachment = $filename;
                        $bill->save();
                    }

                $bill->remarks = $request->remarks ?? '';
                $bill->save();

                $b_id = $bill->id;
                // dd($bill->toArray());

                foreach($request->payment as $key=>$amount){
                    if($amount > 0){
                        $payment = new BillingPaymentType;
                        $payment->bill_id = $b_id;
                        $payment->payment_mode = $key;
                        $payment->amount = $amount;
                        $payment->transaction_id = $request->trx[$key] ?? null;
                        $payment->created_by = auth()->user()->id;
                        $payment->save();
                    }
                }


                foreach($request->service_id as $i=>$ser_id){

                    if (empty($ser_id)) {
                            continue; // skip empty row
                        }


                    $service = HospitalSer::find($ser_id);

                        if($service && ($service->flag=="lab_package"))
                        {
                            $packageService = $service->service;
                            $packageServiceCharge = HospitalServiceCharges::where('hospital_id',$org_id)
                                                                            ->where('insurance',$i_cover)
                                                                            ->where('service',$service->id)
                                                                            ->first()->charges??0;

                            $testIncludes = InvestigationGroupTest::where('group_id', $ser_id)->orderBy('sequence_no', 'asc')->get();
                            $subTotal = 0;
                            foreach($testIncludes as $test)
                            {
                                $sCharge = HospitalServiceCharges::where('hospital_id',$org_id)->where('insurance',$i_cover)->where('service',$test->test_id)->first();
                                $subTotal += $sCharge->charges??0;

                                $gen= new PatientGenBill;
                                $gen->bill_id = $b_id;
                                $gen->service_id = $test->test_id;
                                $gen->charges = $sCharge->charges??0;
                                $gen->qty = 1;
                                $gen->doctor_id = $doctor_id;
                                $gen->i_cover = $i_cover;
                                $gen->created_by = auth()->user()->id;
                                $gen->save();
                            }

                            $bill = PatientBilling::find($b_id);
                            $bill->discount = $bill->discount + ($subTotal - $packageServiceCharge);
                            $bill->save();


                        }else{
                            $gen= new PatientGenBill;
                            $gen->bill_id = $b_id;
                            $gen->service_id = $ser_id;
                            $gen->charges = $request->charges[$i] ?? 0;
                            $gen->qty = $request->qty[$i] ?? 1;
                            $gen->discount = $request->discountArr[$i] ?? 0;
                            $gen->doctor_id = $doctor_id;
                            $gen->i_cover = $i_cover;
                            $gen->created_by = auth()->user()->id;
                            $gen->save();


                        }
                }


                $pdfPath = $this->generate_opd_bill($request,$b_id);

                $data = PatientBilling::join('visitlog','visitlog.id','patient_billing.visit_id')
                                            ->join('pi','pi.id','visitlog.patient_id')
                                            ->join('doctor_db', 'doctor_db.id', '=', 'visitlog.doctor_id')
                                            ->join('health_insurance_agen', 'health_insurance_agen.id', '=', 'pi.i_cover')
                                            ->join('users','users.id','=','patient_billing.created_by')
                                            ->select(
                                                'pi.id as patient_id',
                                                'pi.prefix as prefix',
                                                'pi.Fname as Fname',
                                                'pi.Lname as Lname',
                                                'pi.sex as gender',
                                                'pi.age as age',
                                                'pi.dob as dob',
                                                'pi.mobile_no as mobile_no',
                                                'doctor_db.name as doctor_name',
                                                'pi.i_cover as i_cover',
                                                'health_insurance_agen.insurance_agen as insurance',
                                                'patient_billing.created_at as created_at',
                                                'patient_billing.status as status',
                                                'patient_billing.id as bill_no',
                                                'patient_billing.discount as discount',
                                                'users.first_name',
                                                'users.last_name',
                                                'patient_billing.discount_auth_by as discount_auth_by',
                                                'patient_billing.discount_name as discount_name',
                                            )
                                            ->where('patient_billing.id',$b_id)
                                            ->first();


                $hospital = Healtcare_org::where('id', $org_id)->first();

                Notifier::bill_complete([
                    'patient_id' => $data->patient_id,
                    'phone_number' => $data->mobile_no,
                    'params' => [
                        'patient_name'=> $data->prefix.' '.$data->Fname.' '.$data->Lname,
                        'bill_amount'=> $request->total,
                        'hospital_name'=>$hospital->name??'',
                        'hospital_contact'=>$hospital->contact_no??'',
                        'link' => $hospital->external_app_link?:url('book-appointment/select-doctor/'.encryptID($hospital->id)),
                        'pdf'=>($pdfPath),
                        ]
                    ]);



                DB::commit();

                return response()->json([
                    'success' => true,
                    'message' =>"Service Charges Saved Successfully",
                    'bill_id' =>$b_id,
                'visit_id' => $request->visit_id,
                    'pdf_url' => url($pdfPath),
                ], 200);


            }catch(\Exception $e){
                DB::rollBack();
                return response()->json(['status'=>'error','message' => $e->getMessage()], 500);
            }

        }

    public function drug_coposition_form(Request $request)
    {
        $visit_id = $request->visit_id??'';
        $brand_id = $request->brand_id??'';
        $manual = $request->manual??0;
        $brand_name = $request->brand_name??'';
        $formulation = $request->formulation??'';

        $data = null;
        if ($brand_id && !$manual && is_numeric($brand_id)) {
            $data = \DB::table('drug_brand_index')
                ->leftJoin('drug_compositions', 'drug_compositions.id', '=', 'drug_brand_index.composition_id')
                ->where('drug_brand_index.id', $brand_id)
                ->select(
                    'drug_brand_index.id as brand_id',
                    'drug_brand_index.brand_name',
                    'drug_compositions.id as composition_id',
                    'drug_compositions.composition as composition_name'
                )
                ->first();
        }

        if (!$data && ($brand_name || $formulation)) {
            $data = (object)[
                'brand_id' => $brand_id,
                'brand_name' => $brand_name,
                'composition_id' => $brand_id,
                'composition_name' => $formulation
            ];
        }

        return view('admin.patient.clinical.forms.drug_composition_form', compact('visit_id', 'data', 'manual'));
    }
    public function drug_coposition_search(Request $request)
    {
        $search = $request->input('q', '');

        return \DB::table('drug_compositions')
                ->where('composition','like','%'.$search.'%')
                ->select('id', 'composition')
                ->limit(20)
                ->get()
                ->toJson();
    }
    public function save_drug_combo_single(Request $request)
    {
        $request->validate(['brand_name'=>'required']);

        $brand_id = $request->brand_id;
        $brand_name = $request->brand_name;
        $composition = $request->composition;
        $frequency = $request->frequency??'';
        $doctorID = $request->doctor_id??'';
        $special_instruction = $request->special_instruction??'';

        $comp = \DB::table('drug_compositions')
                ->where('id',$composition)
                ->first();
        $compID = $comp->id??false;
        if(!$compID && $composition){
            $compID = \DB::table('drug_compositions')
                ->insertGetId(['composition'=>$composition]);
        }

        $is_edit = false;
        if ($brand_id && is_numeric($brand_id)) {
            $brandExists = \DB::table('drug_brand_index')
                ->where('id', $brand_id)
                ->exists();
            if ($brandExists) {
                \DB::table('drug_brand_index')
                    ->where('id', $brand_id)
                    ->update([
                        'brand_name'=>$brand_name,
                        'composition_id'=>$compID ?: null,
                    ]);
                $is_edit = true;
            }
        }

        if (!$is_edit) {
            $existingBrand = \DB::table('drug_brand_index')
                ->where('brand_name', $brand_name)
                ->where('composition_id', $compID)
                ->first();
            if ($existingBrand) {
                $brand_id = $existingBrand->id;
            } else {
                $brand_id = \DB::table('drug_brand_index')
                    ->insertGetId([
                        'brand_name'=>$brand_name,
                        'composition_id'=>$compID ?: null,
                    ]);
            }
        }

        // Keep Redis medicine search cache in sync
        \App\Cache\MedicineCache::clear();

        if($frequency || $special_instruction){
            if ($request->visit_id) {
                $visit = Visitlog::find($request->visit_id);
                if ($visit && $compID) {
                    \DB::table('doctor_fav_brand_composition')
                        ->updateOrInsert([
                                'doctor_id' => $visit->doctor_id,
                                'composition_id' => $compID
                            ],
                            [
                                'frequency' => $frequency,
                                'spl_inst'  => $special_instruction,
                            ]);
                }
            }
        }

        $compositionName = '';
        if ($compID) {
            $compRow = \DB::table('drug_compositions')->where('id', $compID)->first();
            $compositionName = $compRow->composition ?? '';
        }

        return response()->json([
            'success' => true,
            'message' => $is_edit ? 'Brand Updated Successfully' : 'Brand Added Successfully',
            'brand_id' => $brand_id,
            'brand_name' => $brand_name,
            'composition' => $compositionName
        ]);
    }

