    function save_discount_and_refund(Request $request)
    {
        $request->validate([
            'refund_remark' => 'required|string|max:500'
        ],[
            'refund_remark.required' => 'Remark is required.'
        ]);

        if($request->discount > 0){
            $request->validate([
                'discount_auth_by' => 'required'
            ],[
                'discount_auth_by.required' => 'Please select Discount Authorized By.'
            ]);
        }

        try{
            DB::beginTransaction();


            $patientBillingID = $request->bill_id;
            $bill = PatientBilling::findOrFail($patientBillingID);
            $bill->discount = $request->discount;
            $bill->discount_auth_by = $request->discount_auth_by;
            $bill->remarks = $request->refund_remark;
            $bill->updated_by = auth()->user()->id;
            $bill->save();

            foreach($request->service_discount as $id => $discountAmt)
            {
                PatientGenBill::where('id', $id)
                    ->where('bill_id',$bill->id)
                    ->update([
                        'discount' => $discountAmt,
                    ]);
            }

            $lastBill = Visitlog::join('patient_billing','patient_billing.visit_id','=','visitlog.id')
                                ->select('visitlog.visit_status','patient_billing.*')
                                ->where('visitlog.visit_status',0)
                                ->orderBy('patient_billing.id','DESC')
                                ->first();

            $receipt_no = ($lastBill && $lastBill->receipt_no) ? $lastBill->receipt_no + 1 : 1;
            $refund_approval_system = \App\Helpers\HospitalHelper::isSettingEnabled(auth()->user()->org_id,'refund_approval_system');


            $pbill = new PatientBilling;
            $pbill->visit_id = $bill->visit_id;
            $pbill->i_cover = $bill->i_cover;
            $pbill->receipt_no = $receipt_no;
            $pbill->discount = 0;
            $pbill->status = 1;
            $pbill->created_by = auth()->user()->id;
            $pbill->save();


            // INSERT TRANSACTION TO PATIENT GEN BILL
            $paytype = new BillingPaymentType;
            $paytype->transaction_type = 1;
            $paytype->bill_id = $pbill->id;
            $paytype->amount =  $request->refund_amount;
            $paytype->payment_mode = $request->input_element;
            $paytype->created_by = auth()->user()->id;
            $paytype->save();

            $ref = new RefundRemark;
            $ref->bill_id = $pbill->id;
            $ref->bill_ref_id = json_encode([$bill->id]);
            $ref->status = 'issued';
            $ref->issued_at = now();
            $ref->issued_by = auth()->user()->id;
            $ref->initiated_by = auth()->user()->id;
            $ref->initiated_at = now();
            $ref->save();

            DB::commit();

            return response()->json([
                'status' => true,
                'message' => 'Discount & Refund saved successfully',
                'data' => $request->all()
            ]);

        }catch(\Exception $e){

            DB::rollBack();

            return response()->json(['status' => 'error', 'message' => $e->getMessage()]);
        }

    }


