    public function save_investigation_v3(Request $request){
        $rawData = json_decode($request->investigation_data, true);

        $finalData = [];

        foreach ($rawData as $row) {

            $finalData[] = [
                'hemoglobin' => $row['hemoglobin'] ?? null,
                'tlc' => strip_tags($row['tlc'] ?? null),
                'dlc' => $row['dlc'] ?? null,
                'platelet' => $row['platelet'] ?? null,
                'gct' => $row['gct'] ?? null,
                'abo_rh' => $row['abo_rh'] ?? null,
                'hba' => $row['hba'] ?? null,
                'tsh' => $row['tsh'] ?? null,
                'hiv_hbsag_hcv' => $row['hiv_hbsag_hcv'] ?? null,
                'vdrl' => $row['vdrl'] ?? null,

                // missing fields (force structure)
                'urine' => null,
                'lft' => null,
                'rft' => null,
                'imaging' => null,
                'other_investigation' => null,

                'crp' => $row['crp'] ?? null,
                'rbs' => $row['rbs'] ?? null,
                'esr' => null,
                'sgot_sgpt' => $row['sgot_sgpt'] ?? null,
                'typhoid' => $row['typhoid'] ?? null,
                'dengue' => null,


                // mapping
                'inv_date' => $row['date'] ?? null,

                // meta
                'created_by' => auth()->id(),
                'created_at' => now(),
            ];
        }

        $visit_id = $request->visit_id;

        //dd($finalData);

        $vital = vitals::where('visit_id',$visit_id)->first();
        $vital->investigation = json_encode($finalData);
        $vital->save();

        return response()->json(['status'=>'success','message'=>'Saved Successfully.']);

    }

    public function unlink_abha(Request $request)
    {
        $request->validate([
            'patient_id' => 'required|exists:pi,id'
        ]);

        $user = Auth::user();
        $patient = Patient::where('id', $request->patient_id)
            ->where('hospital_id', $user->org_id)
            ->first();

        if (!$patient) {
            return response()->json([
                'success' => false,
                'message' => 'Patient record not found.'
            ]);
        }

        $patient->abha_number = null;
        $patient->abha_address = null;
        $patient->abha_verified = 0;
        $patient->abha_add = null;
        $patient->save();

        return response()->json([
            'success' => true,
            'message' => 'ABHA details unlinked successfully.'
        ]);
    }

    public function update_abha(Request $request)
    {
        $request->validate([
            'patient_id'   => 'required',
            'abha_number'  => 'nullable|string',
            'abha_address' => 'nullable|string',
        ]);

        $user = Auth::user();
        $orgId = $user ? ($user->org_id ?? $user->hospital_id) : null;
        $patientId = $request->patient_id;

        $query = Patient::query();
        if ($orgId) {
            $query->where('hospital_id', $orgId);
        }
        $patient = $query->where(function ($q) use ($patientId) {
            $q->where('id', $patientId)
              ->orWhere('uhid', $patientId);
        })->first();

        if (!$patient) {
            // Strictly scoped to active branch: cross-tenant access prohibited
        }

        if (!$patient) {
            return response()->json([
                'success' => false,
                'message' => 'Patient record not found.'
            ], 404);
        }

        // If demographic sync is requested during update_abha
        if ($request->boolean('sync_demographics') || $request->has('Fname') || $request->has('name') || $request->has('dob') || $request->has('gender')) {
            $prevData = [
                'prefix'        => $patient->prefix,
                'Fname'         => $patient->Fname,
                'Lname'         => $patient->Lname,
                'sex'           => $patient->sex,
                'dob'           => $patient->dob,
                'age'           => $patient->age,
                'mobile_no'     => $patient->mobile_no,
                'whats_app_no'  => $patient->whats_app_no,
                'Address'       => $patient->Address,
                'district'      => $patient->district,
                'state'         => $patient->state,
                'pin'           => $patient->pin,
                'abha_number'   => $patient->abha_number,
                'abha_address'  => $patient->abha_address,
                'abha_verified' => $patient->abha_verified,
            ];

            $others = is_array($patient->others) ? $patient->others : (json_decode($patient->others ?: '{}', true) ?: []);
            if (!isset($others['abdm_demographic_history']) || !is_array($others['abdm_demographic_history'])) {
                $others['abdm_demographic_history'] = [];
            }

            // Universal full name decomposition
            $newFname = $request->input('Fname');
            $newLname = $request->input('Lname');
            $fullName = $request->input('name') ?: $request->input('patient_name');

            if (empty($newFname) && !empty($fullName)) {
                $parts = explode(' ', trim($fullName));
                $newFname = $parts[0];
                $newLname = count($parts) > 1 ? implode(' ', array_slice($parts, 1)) : '';
            } elseif (!empty($newFname) && (empty($newLname) && $newLname !== '') && count(explode(' ', trim($newFname))) > 1) {
                $parts = explode(' ', trim($newFname));
                $newFname = $parts[0];
                $newLname = implode(' ', array_slice($parts, 1));
            }

            $others['abdm_demographic_history'][] = [
                'timestamp'             => now()->toDateTimeString(),
                'updated_by_user_id'    => $user ? $user->id : null,
                'reason'                => $request->input('reason', 'Synced with Aadhaar verified profile during ABHA update'),
                'previous_demographics' => $prevData,
                'synced_demographics'   => [
                    'prefix'       => $request->input('prefix', $patient->prefix),
                    'Fname'        => !empty($newFname) ? trim($newFname) : $patient->Fname,
                    'Lname'        => $newLname !== null ? trim($newLname) : $patient->Lname,
                    'sex'          => $request->input('gender', $request->input('sex', $patient->sex)),
                    'dob'          => $request->input('dob', $patient->dob),
                    'age'          => $request->input('age', $patient->age),
                    'abha_number'  => $request->input('abha_number', $patient->abha_number),
                    'abha_address' => $request->input('abha_address', $patient->abha_address),
                ]
            ];
            $patient->others = $others;

            if (!empty($newFname))            $patient->Fname   = trim($newFname);
            if ($newLname !== null)           $patient->Lname   = trim($newLname);
            if ($request->filled('prefix'))   $patient->prefix  = trim($request->input('prefix'));
            if ($request->filled('gender'))   $patient->sex     = trim($request->input('gender'));
            elseif ($request->filled('sex'))  $patient->sex     = trim($request->input('sex'));

            if ($request->filled('dob')) {
                $rawDob = trim($request->input('dob'));
                try {
                    $patient->dob = date('Y-m-d', strtotime($rawDob));
                } catch (\Throwable $e) {
                    $patient->dob = $rawDob;
                }
            }
            if ($request->filled('age')) $patient->age = (int)$request->input('age');
        }

        if ($request->has('abha_number')) {
            $patient->abha_number = trim($request->abha_number);
        }
        $patient->abha_verified = 1;
        $patient->save();

        if ($request->filled('abha_address')) {
            ABDMCloudRelay::recordPatientAbhaAddress($patient, $request->abha_address, true, 'verify_abha');
        }

        if (!empty($patient->abha_address) || !empty($patient->abha_number) || !empty($patient->abha_add)) {
            \App\Jobs\ABDM\GenerateAbdmLinkTokenJob::dispatch((int)$patient->id, (int)($patient->hospital_id ?? 1))
                ->onQueue('abdm-notifications')
                ->delay(now()->addSecond());

            // Auto-trigger M2 HIP-initiated care context linking for patient's latest active encounter
            try {
                $ccm = app(\App\Services\ABDM\ClinicalContexts\ClinicalContextManager::class);
                $contexts = $ccm->discoverPatientCareContexts($patient);
                if (!empty($contexts)) {
                    $latestContext = $contexts[0];
                    $visitId = $latestContext['visit_id'] ?? null;
                    if ($visitId) {
                        $provider = $ccm->getProviderByReference($latestContext['referenceNumber']);
                        if ($provider) {
                            $provider->pushCareContextLink($patient, $visitId, [
                                'care_context_ref' => $latestContext['referenceNumber'],
                                'doctor_name'      => $latestContext['doctor_name'] ?? null,
                            ]);
                        }
                    }
                }
            } catch (\Throwable $e) {
                \Illuminate\Support\Facades\Log::warning('Auto HIP linking on ABHA link failed: ' . $e->getMessage());
            }
        }

        return response()->json([
            'success' => true,
            'message' => 'ABHA details updated in database record successfully.',
            'data'    => [
                'patient_id'   => $patient->id,
                'uhid'         => $patient->id,
                'abha_number'  => $patient->abha_number,
                'abha_address' => $patient->abha_address,
            ]
        ]);
    }

    public function checkAbhaDemographicAlignment(Request $request)
    {
        $request->validate([
            'patient_id' => 'required',
        ]);

        $user = Auth::user();
        $orgId = $user ? ($user->org_id ?? $user->hospital_id) : null;
        $patientId = $request->patient_id;

        $query = Patient::query();
        if ($orgId) {
            $query->where('hospital_id', $orgId);
        }
        $patient = $query->where(function ($q) use ($patientId) {
            $q->where('id', $patientId)
              ->orWhere('uhid', $patientId);
        })->first();

        if (!$patient) {
            return response()->json([
                'success' => false,
                'aligned' => false,
                'status'  => 'NOT_FOUND',
                'message' => 'Patient record not found.'
            ], 404);
        }

        $abhaAddress = $patient->abha_address ?? $patient->abha_add ?? null;
        $abhaNumber  = $patient->abha_number ?? null;

        if (empty($abhaAddress) && empty($abhaNumber)) {
            return response()->json([
                'success' => true,
                'aligned' => false,
                'status'  => 'UNLINKED',
                'message' => 'No ABHA linked to this patient.',
                'patient' => [
                    'id'   => $patient->id,
                    'uhid' => $patient->id,
                ]
            ]);
        }

        // Check if verified KYC is present in pi.others
        $others = is_array($patient->others) ? $patient->others : (json_decode($patient->others ?: '{}', true) ?: []);
        $storedKyc = $others['abdm_kyc'] ?? null;
        $hasVerifiedKyc = !empty($storedKyc) && !empty($storedKyc['name']);

        // Local HIMS Link Token Verification
        $hId = (int) ($patient->hospital_id ?? ($orgId ?? 1));
        /** @var \App\Services\ABDM\AbdmLinkTokenService $linkTokenService */
        $linkTokenService = app(\App\Services\ABDM\AbdmLinkTokenService::class);
        $validToken = $linkTokenService->getValidLinkToken((string)$abhaAddress, $hId, (int)$patient->id);
        $hasLinkToken = !empty($validToken);

        // Determine Demographic Alignment from verified sources of truth (Deterministic, 0ms latency)
        $isAligned = true;
        $alignmentStatus = 'ALIGNED';
        $alignmentMessage = 'Demographics aligned with verified Aadhaar profile.';

        $himsName = trim(preg_replace('/\s+/', ' ', ($patient->Fname ?? '') . ' ' . ($patient->Lname ?? '')));

        if ($hasVerifiedKyc) {
            $kycName = trim(preg_replace('/\s+/', ' ', (string)($storedKyc['name'] ?? '')));
            if (!empty($kycName) && !empty($himsName) && strcasecmp($himsName, $kycName) !== 0) {
                $alignmentStatus = 'MISMATCH';
                $isAligned = false;
                $alignmentMessage = "Hospital patient name ('{$himsName}') differs from verified Aadhaar KYC name ('{$kycName}').";
            } else {
                $alignmentStatus = 'ALIGNED';
                $isAligned = true;
            }
        } elseif (!empty($patient->abha_verified) && (int)$patient->abha_verified === 1) {
            $alignmentStatus = 'ALIGNED';
            $isAligned = true;
        } else {
            // Check if verified demographics can be resolved from linked care context / audit cache
            /** @var \App\Services\ABDM\CareContextManagerService $ccManager */
            $ccManager = app(\App\Services\ABDM\CareContextManagerService::class);
            $resolvedDemo = $ccManager->resolveVerifiedDemographics((int)$patient->id, $patient, (string)$abhaAddress);
            if (!empty($resolvedDemo['name'])) {
                $resName = trim(preg_replace('/\s+/', ' ', (string)$resolvedDemo['name']));
                if (!empty($resName) && !empty($himsName) && strcasecmp($himsName, $resName) !== 0) {
                    $alignmentStatus = 'MISMATCH';
                    $isAligned = false;
                    $alignmentMessage = "Hospital patient name ('{$himsName}') differs from verified ABHA profile name ('{$resName}').";
                } else {
                    $alignmentStatus = 'ALIGNED';
                    $isAligned = true;
                }
            } else {
                $alignmentStatus = 'UNVERIFIED';
                $isAligned = false;
                $alignmentMessage = 'ABHA linked without verified KYC on record. Click to verify.';
            }
        }

        return response()->json([
            'success'           => true,
            'status'            => $alignmentStatus,
            'aligned'           => $isAligned,
            'code'              => null,
            'message'           => $alignmentMessage,
            'raw_error'         => null,
            'has_link_token'    => $hasLinkToken,
            'link_token_status' => $hasLinkToken ? 'VALID' : 'MISSING_OR_EXPIRED',
            'has_verified_kyc'  => $hasVerifiedKyc,
            'kyc_name'          => $storedKyc['name'] ?? null,
            'patient_id'        => $patient->id,
            'uhid'              => $patient->id,
            'abha_address'      => $abhaAddress,
            'abha_number'       => $abhaNumber,
            'hims_demographics' => [
                'name'   => $himsName,
                'gender' => $patient->sex,
                'dob'    => $patient->dob,
                'age'    => $patient->age,
            ]
        ]);
    }

    /**
     * Retrieve comparative demographic details between local HIMS record and verified Aadhaar/ABHA profile.
     * Used by the Demographic Match & Sync modal (without OTP).
     */
    public function getAbhaProfileDemographics(Request $request)
    {
        $request->validate([
            'patient_id' => 'required',
        ]);

        $user = Auth::user();
        $orgId = $user ? ($user->org_id ?? $user->hospital_id) : null;
        $patientId = $request->patient_id;

        $query = Patient::query();
        if ($orgId) {
            $query->where('hospital_id', $orgId);
        }
        $patient = $query->where(function ($q) use ($patientId) {
            $q->where('id', $patientId)
              ->orWhere('uhid', $patientId);
        })->first();

        if (!$patient) {
            return response()->json([
                'success' => false,
                'message' => 'Patient record not found.'
            ], 404);
        }

        $abhaAddress = $patient->abha_address ?? $patient->abha_add ?? null;
        $abhaNumber  = $patient->abha_number ?? null;

        $others = is_array($patient->others) ? $patient->others : (json_decode($patient->others ?: '{}', true) ?: []);
        $storedKyc = $others['abdm_kyc'] ?? null;

        // Fallback to resolveVerifiedDemographics if not directly in storedKyc
        if (empty($storedKyc) || empty($storedKyc['name'])) {
            /** @var \App\Services\ABDM\CareContextManagerService $ccManager */
            $ccManager = app(\App\Services\ABDM\CareContextManagerService::class);
            $resolved = $ccManager->resolveVerifiedDemographics((int)$patient->id, $patient, (string)$abhaAddress);
            if (!empty($resolved['name'])) {
                $storedKyc = [
                    'name'        => $resolved['name'],
                    'gender'      => $resolved['gender'] ?? $patient->sex,
                    'yearOfBirth' => $resolved['yearOfBirth'] ?? null,
                    'dob'         => $patient->dob,
                    'abhaNumber'  => $resolved['abhaNumber'] ?? $abhaNumber,
                    'abhaAddress' => $abhaAddress,
                    'mobile'      => $patient->mobile_no,
                    'address'     => $patient->Address,
                    'district'    => $patient->district,
                    'state'       => $patient->state,
                    'pincode'     => $patient->pin,
                ];
            }
        }

        // Decompose KYC full name into First/Last
        $kycFullName = trim((string)($storedKyc['name'] ?? ''));
        $kycFname = '';
        $kycLname = '';
        if (!empty($kycFullName)) {
            $parts = explode(' ', $kycFullName);
            $kycFname = $parts[0];
            $kycLname = count($parts) > 1 ? implode(' ', array_slice($parts, 1)) : '';
        }

        $himsFullName = trim(($patient->Fname ?? '') . ' ' . ($patient->Lname ?? ''));

        // Normalize genders
        $himsGender = ucfirst(strtolower(trim((string)$patient->sex)));
        $kycGenderRaw = strtoupper(trim((string)($storedKyc['gender'] ?? 'M')));
        $kycGender = ($kycGenderRaw === 'M' || $kycGenderRaw === 'MALE') ? 'Male' : (($kycGenderRaw === 'F' || $kycGenderRaw === 'FEMALE') ? 'Female' : 'Other');

        $isNameDiff = !empty($kycFullName) && strcasecmp(preg_replace('/\s+/', ' ', $himsFullName), preg_replace('/\s+/', ' ', $kycFullName)) !== 0;
        $isGenderDiff = !empty($kycGender) && !empty($himsGender) && strcasecmp($himsGender, $kycGender) !== 0;
        $isDobDiff = false;
        if (!empty($storedKyc['dob']) && !empty($patient->dob)) {
            $isDobDiff = date('Y-m-d', strtotime($storedKyc['dob'])) !== date('Y-m-d', strtotime($patient->dob));
        }

        return response()->json([
            'success'    => true,
            'patient_id' => $patient->id,
            'hims' => [
                'prefix'     => $patient->prefix,
                'first_name' => $patient->Fname,
                'last_name'  => $patient->Lname,
                'full_name'  => $himsFullName,
                'gender'     => $himsGender,
                'dob'        => $patient->dob,
                'age'        => $patient->age,
                'mobile'     => $patient->mobile_no,
                'address'    => $patient->Address,
                'district'   => $patient->district,
                'state'      => $patient->state,
                'pin'        => $patient->pin,
            ],
            'abha' => [
                'abha_address' => $abhaAddress,
                'abha_number'  => $abhaNumber ?: ($storedKyc['abhaNumber'] ?? null),
                'first_name'   => $kycFname,
                'last_name'    => $kycLname,
                'full_name'    => $kycFullName,
                'gender'       => $kycGender,
                'dob'          => $storedKyc['dob'] ?? $patient->dob,
                'age'          => $patient->age,
                'yearOfBirth'  => $storedKyc['yearOfBirth'] ?? null,
                'mobile'       => $storedKyc['mobile'] ?? $patient->mobile_no,
                'address'      => $storedKyc['address'] ?? $patient->Address,
                'district'     => $storedKyc['district'] ?? $patient->district,
                'state'        => $storedKyc['state'] ?? $patient->state,
                'pin'          => $storedKyc['pincode'] ?? ($storedKyc['pin'] ?? $patient->pin),
            ],
            'diff' => [
                'name'    => $isNameDiff,
                'gender'  => $isGenderDiff,
                'dob'     => $isDobDiff,
            ]
        ]);
    }

    /**
     * Generate or re-establish an ABDM Link Token for a patient during registration/UHID search.
     * Prioritizes verified KYC demographics to ensure 100% character-for-character match with Aadhaar.
     */
    public function generateAbhaLinkToken(Request $request)
    {
        $request->validate([
            'patient_id' => 'required',
        ]);

        $user = Auth::user();
        $orgId = $user ? ($user->org_id ?? $user->hospital_id) : null;
        $patientId = $request->patient_id;

        $query = Patient::query();
        if ($orgId) {
            $query->where('hospital_id', $orgId);
        }
        $patient = $query->where(function ($q) use ($patientId) {
            $q->where('id', $patientId)
              ->orWhere('uhid', $patientId);
        })->first();

        if (!$patient) {
            return response()->json([
                'success' => false,
                'message' => 'Patient record not found.'
            ], 404);
        }

        $abhaAddress = $patient->abha_address ?? $patient->abha_add ?? null;
        if (empty($abhaAddress)) {
            return response()->json([
                'success' => false,
                'message' => 'No ABHA address associated with this patient record.'
            ], 422);
        }

        /** @var \App\Services\ABDM\AbdmLinkTokenService $linkTokenService */
        $linkTokenService = app(\App\Services\ABDM\AbdmLinkTokenService::class);
        $hId = (int) ($patient->hospital_id ?? ($orgId ?? 1));

        // 1. Check if token already exists in local storage
        $existingToken = $linkTokenService->getValidLinkToken((string)$abhaAddress, $hId, (int)$patient->id);
        if (!empty($existingToken)) {
            return response()->json([
                'success'        => true,
                'has_link_token' => true,
                'message'        => 'Active link token already established in local HIMS storage.',
            ]);
        }

        // 2. Resolve verified KYC demographics
        $ccManager = app(\App\Services\ABDM\CareContextManagerService::class);
        $demographics = $ccManager->resolveVerifiedDemographics((int)$patient->id, $patient, (string)$abhaAddress);

        $patientData = [
            'id'           => $patient->id,
            'abhaAddress'  => $abhaAddress,
            'abhaNumber'   => $demographics['abhaNumber'] ?: ($patient->abha_number ?? null),
            'name'         => $demographics['name'],
            'gender'       => $demographics['gender'],
            'dob'          => $patient->dob,
            'age'          => $patient->age,
            'yearOfBirth'  => $demographics['yearOfBirth'],
            'hospital_id'  => $hId,
        ];

        try {
            $probeResult = $linkTokenService->requestLinkToken($patientData, $hId);
            $status = $probeResult['status'] ?? 'UNKNOWN';

            if (in_array($status, ['ACCEPTED', 'DISPATCHED', 'IN_PROGRESS', 'SUCCESS'])) {
                $token = $probeResult['linkToken'] ?? $linkTokenService->getValidLinkToken((string)$abhaAddress, $hId, (int)$patient->id);
                return response()->json([
                    'success'        => true,
                    'has_link_token' => !empty($token),
                    'status'         => $status,
                    'message'        => !empty($token) ? 'Link token established and verified successfully!' : 'Link token requested; pending asynchronous callback.',
                ]);
            }

            return response()->json([
                'success'      => false,
                'requires_otp' => true,
                'status'       => $status,
                'message'      => $probeResult['message'] ?? 'Gateway requires OTP authentication to generate a fresh link token.',
            ]);
        } catch (\Throwable $e) {
            $errMsg = $e->getMessage();
            $isDuplicateOrOtp = stripos($errMsg, 'ABDM-1092') !== false 
                || stripos($errMsg, 'duplicate') !== false
                || stripos($errMsg, 'otp') !== false;

            return response()->json([
                'success'      => false,
                'requires_otp' => $isDuplicateOrOtp,
                'message'      => $isDuplicateOrOtp ? 'A link token already exists on Gateway. Please verify via Patient OTP to renew the link token.' : 'Error requesting link token: ' . substr($errMsg, 0, 150),
            ], 200);
        }
    }

    public function syncAbhaDemographics(Request $request)
    {
        $request->validate([
            'patient_id' => 'required',
        ]);

        $user = Auth::user();
        $orgId = $user ? ($user->org_id ?? $user->hospital_id) : null;
        $patientId = $request->patient_id;

        $query = Patient::query();
        if ($orgId) {
            $query->where('hospital_id', $orgId);
        }
        $patient = $query->where(function ($q) use ($patientId) {
            $q->where('id', $patientId)
              ->orWhere('uhid', $patientId);
        })->first();

        if (!$patient) {
            // Strictly scoped to active branch: cross-tenant access prohibited
        }

        if (!$patient) {
            return response()->json([
                'success' => false,
                'message' => 'Patient record not found.'
            ], 404);
        }

        // 1. Snapshot previous demographics for pi.others archival
        $prevData = [
            'prefix'        => $patient->prefix,
            'Fname'         => $patient->Fname,
            'Lname'         => $patient->Lname,
            'sex'           => $patient->sex,
            'dob'           => $patient->dob,
            'age'           => $patient->age,
            'mobile_no'     => $patient->mobile_no,
            'whats_app_no'  => $patient->whats_app_no,
            'Address'       => $patient->Address,
            'district'      => $patient->district,
            'state'         => $patient->state,
            'pin'           => $patient->pin,
            'abha_number'   => $patient->abha_number,
            'abha_address'  => $patient->abha_address,
            'abha_verified' => $patient->abha_verified,
        ];

        // 2. Read existing others JSON / array
        $others = is_array($patient->others) ? $patient->others : (json_decode($patient->others ?: '{}', true) ?: []);
        if (!isset($others['abdm_demographic_history']) || !is_array($others['abdm_demographic_history'])) {
            $others['abdm_demographic_history'] = [];
        }

        // Universal full name decomposition (handles "Bhupinder Singh Sahi" -> Fname: Bhupinder, Lname: Singh Sahi)
        $newFname = $request->input('Fname');
        $newLname = $request->input('Lname');
        $fullName = $request->input('name') ?: $request->input('patient_name');

        if (empty($newFname) && !empty($fullName)) {
            $parts = explode(' ', trim($fullName));
            $newFname = $parts[0];
            $newLname = count($parts) > 1 ? implode(' ', array_slice($parts, 1)) : '';
        } elseif (!empty($newFname) && (empty($newLname) && $newLname !== '') && count(explode(' ', trim($newFname))) > 1) {
            $parts = explode(' ', trim($newFname));
            $newFname = $parts[0];
            $newLname = implode(' ', array_slice($parts, 1));
        }

        $revision = [
            'timestamp'             => now()->toDateTimeString(),
            'updated_by_user_id'    => $user ? $user->id : null,
            'reason'                => $request->input('reason', 'Synced with Aadhaar verified profile to enable ABDM auto-linking'),
            'previous_demographics' => $prevData,
            'synced_demographics'   => [
                'prefix'       => $request->input('prefix', $patient->prefix),
                'Fname'        => !empty($newFname) ? trim($newFname) : $patient->Fname,
                'Lname'        => $newLname !== null ? trim($newLname) : $patient->Lname,
                'sex'          => $request->input('gender', $request->input('sex', $patient->sex)),
                'dob'          => $request->input('dob', $patient->dob),
                'age'          => $request->input('age', $patient->age),
                'abha_number'  => $request->input('abha_number', $patient->abha_number),
                'abha_address' => $request->input('abha_address', $patient->abha_address),
            ]
        ];

        $others['abdm_demographic_history'][] = $revision;
        $patient->others = $others;

        // 3. Update primary patient record with verified Aadhaar values
        if (!empty($newFname)) {
            $patient->Fname = trim($newFname);
        }
        if ($newLname !== null) {
            $patient->Lname = trim($newLname);
        }
        if ($request->filled('prefix')) {
            $patient->prefix = trim($request->input('prefix'));
        }
        if ($request->filled('gender')) {
            $patient->sex = trim($request->input('gender'));
        } elseif ($request->filled('sex')) {
            $patient->sex = trim($request->input('sex'));
        }

        if ($request->filled('dob')) {
            $rawDob = trim($request->input('dob'));
            try {
                $patient->dob = date('Y-m-d', strtotime($rawDob));
            } catch (\Throwable $e) {
                $patient->dob = $rawDob;
            }
        }
        if ($request->filled('age')) {
            $patient->age = (int)$request->input('age');
        }

        if ($request->filled('abha_number')) {
            $patient->abha_number = trim($request->input('abha_number'));
        }

        // Keep verified KYC up to date in others for instant deterministic checking
        if (!isset($others['abdm_kyc']) || !is_array($others['abdm_kyc'])) {
            $others['abdm_kyc'] = [];
        }
        $others['abdm_kyc']['name'] = trim(($patient->Fname ?? '') . ' ' . ($patient->Lname ?? ''));
        $others['abdm_kyc']['first_name'] = $patient->Fname;
        $others['abdm_kyc']['last_name'] = $patient->Lname;
        $others['abdm_kyc']['gender'] = $patient->sex;
        $others['abdm_kyc']['dob'] = $patient->dob;
        $others['abdm_kyc']['age'] = $patient->age;
        if (!empty($patient->abha_number)) {
            $others['abdm_kyc']['abhaNumber'] = $patient->abha_number;
        }
        if (!empty($patient->abha_address)) {
            $others['abdm_kyc']['abhaAddress'] = $patient->abha_address;
        }
        $patient->others = $others;

        $patient->abha_verified = 1;
        $patient->save();

        if ($request->filled('address')) {
            $patient->Address = trim($request->input('address'));
        } elseif ($request->filled('Address')) {
            $patient->Address = trim($request->input('Address'));
        }
        if ($request->filled('district')) {
            $patient->district = trim($request->input('district'));
        }
        if ($request->filled('state')) {
            $patient->state = trim($request->input('state'));
        }
        if ($request->filled('pincode') || $request->filled('pin')) {
            $patient->pin = trim($request->input('pincode') ?: $request->input('pin'));
        }

        if ($request->filled('abha_address')) {
            ABDMCloudRelay::recordPatientAbhaAddress($patient, $request->input('abha_address'), true, 'verify_abha_demographic_sync');
        }

        $patient->abha_verified = 1;
        $patient->save();

        // 4. Trigger ABDM Care Context link jobs & discovery
        if (!empty($patient->abha_address) || !empty($patient->abha_number)) {
            try {
                \App\Jobs\ABDM\GenerateAbdmLinkTokenJob::dispatch((int)$patient->id, (int)($orgId ?? 1))
                    ->onQueue('abdm-notifications')
                    ->delay(now()->addSecond());
            } catch (\Throwable $e) {}

            try {
                $ccm = app(\App\Services\ABDM\ClinicalContexts\ClinicalContextManager::class);
                $contexts = $ccm->discoverPatientCareContexts($patient);
                if (!empty($contexts)) {
                    $latestContext = $contexts[0];
                    $visitId = $latestContext['visit_id'] ?? null;
                    if ($visitId) {
                        $provider = $ccm->getProviderByReference($latestContext['referenceNumber']);
                        if ($provider) {
                            $provider->pushCareContextLink($patient, $visitId, [
                                'care_context_ref' => $latestContext['referenceNumber'],
                                'doctor_name'      => $latestContext['doctor_name'] ?? null,
                            ]);
                        }
                    }
                }
            } catch (\Throwable $e) {
                \Illuminate\Support\Facades\Log::warning('Auto HIP linking on sync demographic failed: ' . $e->getMessage());
            }
        }

        return response()->json([
            'success' => true,
            'message' => 'Demographics synchronized with Aadhaar. Previous details archived securely.',
            'patient' => [
                'id'            => $patient->id,
                'uhid'          => $patient->id,
                'prefix'        => $patient->prefix,
                'Fname'         => $patient->Fname,
                'Lname'         => $patient->Lname,
                'patient_name'  => trim(($patient->Fname ?? '') . ' ' . ($patient->Lname ?? '')),
                'gender'        => $patient->sex,
                'dob'           => $patient->dob,
                'age'           => $patient->age,
                'mobile_no'     => $patient->mobile_no,
                'abha_number'   => $patient->abha_number,
                'abha_address'  => $patient->abha_address,
                'abha_verified' => $patient->abha_verified,
                'history_count' => count($others['abdm_demographic_history']),
            ]
        ]);
    }

    public function getAbhaDemographicHistory(Request $request)
    {
        $request->validate(['patient_id' => 'required']);
        $user = Auth::user();
        $orgId = $user ? $user->org_id : null;
        $patient = Patient::when($orgId, fn($q) => $q->where('hospital_id', $orgId))
            ->where('id', $request->patient_id)
            ->first();

        if (!$patient) {
            return response()->json(['success' => false, 'message' => 'Patient not found.'], 404);
        }

        $others = is_array($patient->others) ? $patient->others : (json_decode($patient->others ?: '{}', true) ?: []);
        $history = $others['abdm_demographic_history'] ?? [];

        return response()->json([
            'success'    => true,
            'patient_id' => $patient->id,
            'history'    => $history
        ]);
    }

    public function check_local_by_mobile(Request $request)
    {
        $request->validate([
            'mobile_no' => 'required|string',
        ]);

        $user  = Auth::user();
        $orgId = $user ? $user->org_id : null;

        $mobile = preg_replace('/\D/', '', $request->input('mobile_no'));
        if (empty($mobile)) {
            return response()->json([
                'success'  => false,
                'count'    => 0,
                'patients' => []
            ]);
        }

        $query = Patient::query();
        if ($orgId) {
            $query->where('hospital_id', $orgId);
        }

        $query->where(function ($q) use ($mobile) {
            $q->where('mobile_no', $mobile)
              ->orWhere('phone', $mobile)
              ->orWhere('whats_app_no', $mobile);
        });

        $records = $query->orderBy('id', 'desc')->get();

        $patients = [];
        foreach ($records as $p) {
            $abhaNo   = $p->abha_number ?? '';
            $abhaAddr = $p->abha_address ?? $p->abha_add ?? '';
            $name     = trim(($p->Fname ?? '') . ' ' . ($p->Lname ?? ''));
            if (empty($name)) {
                $name = $p->first_name ?? $p->name ?? 'Patient Record';
            }

            $others = is_array($p->others) ? $p->others : (json_decode($p->others ?: '{}', true) ?: []);
            $history = $others['abdm_demographic_history'] ?? [];

            $patients[] = [
                'id'                      => $p->id,
                'uhid'                    => $p->id,
                'name'                    => $name,
                'prefix'                  => $p->prefix ?? '',
                'first_name'              => $p->Fname ?? '',
                'last_name'               => $p->Lname ?? '',
                'gender'                  => $p->sex ?? $p->gender ?? '',
                'sex'                     => $p->sex ?? $p->gender ?? '',
                'age'                     => $p->age ?? '',
                'dob'                     => $p->dob ?? '',
                'mobile_no'               => $p->mobile_no ?? $p->phone ?? '',
                'whats_app_no'            => $p->whats_app_no ?? '',
                'address'                 => $p->Address ?? '',
                'district'                => $p->district ?? '',
                'state'                   => $p->state ?? '',
                'pincode'                 => $p->pin ?? '',
                'abha_number'             => $abhaNo,
                'abha_address'            => $abhaAddr,
                'abha_verified'           => (int)($p->abha_verified ?? 0),
                'is_already_linked'       => (!empty($abhaNo) || !empty($abhaAddr)),
                'has_demographic_history' => !empty($history),
                'history_count'           => count($history),
                'created_at'              => $p->created_at ? $p->created_at->format('d-m-Y') : '',
            ];
        }

        return response()->json([
            'success'  => true,
            'count'    => count($patients),
            'patients' => $patients
        ]);
    }

}














